INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Fist', 'OVA', 1, 'Completed', '1991-03-20', NULL, '4', 'The story follows Ling Fei-long, a Chinese transfer student living in Japan. Ling is the son of the leader of the White Dragon clan, one of four clans who live in the mountains of China and are descended from mythical beasts. After killing an ordinary human, Ling is banished to Japan so that he might learn about humanity and how to control his powers around them.', 51, 'https://cdn.myanimelist.net/images/anime/9/55907.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Roots Search: Shokushin Buttai X', 'OVA', 1, 'Completed', '1986-09-10', NULL, '4', 'When a research crew in deep space discovers the desolate ship "Green Planet" that warps into their area, they encounter Buzz, the commander and sole surivor of the ship. Being too incapacitated to make them aware of the situation of his ship, the research team will soon discover that they have found something far, far worse... 
