INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shen Bi', 'Movie', 1, 'Completed', '1955-01-01', NULL, '5', '', 792, 'https://cdn.myanimelist.net/images/anime/1200/118072.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wuya Weisheme shi Hei de', 'Movie', 1, 'Completed', '1955-01-01', NULL, '5', 'A long time ago, there was a very beautiful bird with beautiful feathers and a sweet singing voice. Other birds admired her. As autumn approached, the birds were busy building nests and storing food to prepare for the winter, but she was the only one who didn''t do anything and wandered in the forest. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shouta no Sushi: Kokoro ni Hibiku Shari no Aji', 'Special', 1, 'Completed', '1999-10-11', NULL, '5', 'Shouta no Sushi is about a young boy who dreams of being a sushi chef just like his father. The anime steps away from the competitive nature of the manga and focuses on self-sufficiency and policy issues of agriculture, forestry, and fisheries in Japan in order to educate the population (as it was funded by the Ministry of Agriculture, Forestry and Fisheries) using the popular franchise as a proxy.', 871, 'https://cdn.myanimelist.net/images/anime/11/67773.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yewai de Zaoyu', 'Movie', 1, 'Completed', '1955-01-01', NULL, '5', 'The little flower pig''s food was snatched by a crow, so he follows the crow far away. However, the little pig who was left behind began crying because he couldn''t find the little flower pig. The little yellow dog asks the little pig why he was crying and the little yellow dog then helps the little pig find the little flower pig.', 792, 'https://cdn.myanimelist.net/images/anime/1035/115796.jpg');
