INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wo Zhidao', 'Movie', 1, 'Completed', '1956-01-01', NULL, '5', 'The little rabbit was playing hiding and seek with its mother, but the mother worried that the little rabbit would meet a wolf. The mother sang a song that described what a wolf looks like, and mimicked a wolf. The little replied, "I know, I know," despite having never seen a wolf before. The story follows the little rabbit encountering other animals and judging them to be a wolf or not by comparing them to the description from the song.', 792, 'https://cdn.myanimelist.net/images/anime/1784/115800.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jizhi de Shanyang', 'Movie', 1, 'Completed', '1956-01-01', NULL, '5', 'A puppet stop motion animation adapted from a Chinese folk tale about a witty goat who hides in a cave from a tiger. The goat lies to the tiger that it is the king of the mountain and eats tigers, scaring the tiger off. The tiger meets a fox at the bottom of the mountain and tells the fox what happened. The fox laughs and says that the tiger had been tricked by a goat.', 792, 'https://cdn.myanimelist.net/images/anime/1743/115832.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Genkichi Jiisan to Kogitsune', 'OVA', 1, 'Completed', '2001-01-01', NULL, '5', '', 1030, 'https://cdn.myanimelist.net/images/anime/10/67681.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Da Honghua', 'Movie', 1, 'Completed', '1956-01-01', NULL, '5', '', 792, 'https://cdn.myanimelist.net/images/anime/1297/118076.jpg');
