INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toaru Kagaku no Railgun T: Motto Marutto Railgun', 'Special', 2, 'Completed', '2020-04-30', '2020-10-09', '7', 'Toaru Kagaku no Railgun T specials that were released on Blu-ray and DVD volumes.', 436, 'https://cdn.myanimelist.net/images/anime/1220/109813.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rayearth', 'OVA', 3, 'Completed', '1997-07-25', '1997-11-24', '7', 'The Earth lies darkened and deserted. Despite the best efforts of the film''s heroine, Hikaru, the evil-filled castle of Cephiro has taken over the world and stands in the center of a lifeless Tokyo. Before the ice-witch Alcyone can take her revenge on Hikaru, she is rescued by Lantis, a young man who seals her into a magical maze where she is challenged to prove her powers while her friends are hunted down by Cephiro''s warlocks. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mewkledreamy Mix!', 'TV', 37, 'Completed', '2021-04-11', '2022-03-27', '7', 'Second season of Mewkledreamy.', 436, 'https://cdn.myanimelist.net/images/anime/1313/112427.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('IS: Infinite Stratos 2 - World Purge-hen', 'OVA', 1, 'Completed', '2014-11-26', NULL, '7', 'While Ichika Orimura departs to visit Kuramochi Engineering''s laboratories, an unidentified enemy hacks into IS Academy''s core and cripples its systems. To fend off the attack and repair the damage, his older sister Chifuyu enlists Ichika''s harem: Houki Shinonono, Cecilia Alcott, Huang Lingyin, Laura Bodewig, and Charlotte Dunois. Together, they utilize virtual reality to confront their opponents in IS Academy''s network.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Macross Flash Back 2012', 'OVA', 1, 'Completed', '1987-06-21', NULL, '7', 'Flash Back 2012 is Minmei''s farewell concert. Featuring some of her best songs, the music is performed over various scenes and events taken from Macross TV as well as Macross "Do You Remember Love". Also included is a newly animated closing sequence showing the launch of Misa''s colony vessel, the Megaroad-01, into space.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kodomo no Jikan Recap', 'OVA', 1, 'Completed', '2008-07-11', NULL, '7', 'A 86-minute DVD episode that includes an uncensored summary of the original TV series.', 857, 'https://cdn.myanimelist.net/images/anime/5/9186.jpg');
