INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyou no 5 no 2 Kagai Jugyou: Mizukake', 'Special', 1, 'Completed', '2008-01-30', NULL, '7', 'A short 5-minute special included in the "「Kyou no Go no Ni」 Collectable BOX" Limited Edition DVD released on January 30, 2008.', 523, 'https://cdn.myanimelist.net/images/anime/10/42577.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Binbou Shimai Monogatari', 'TV', 10, 'Completed', '2006-06-30', '2006-09-15', '7', 'Without the presence of both their deceased mother and their debt-ridden father, sisters Kyou and Asu Yamada are forced to fend for themselves. Thankfully, they at least have a roof over their heads: a small room in an old apartment spacious enough to fit both of them. However, to make ends meet, the older sister Kyou strives to juggle various part-time jobs—all while making sure that she and her younger sister can continue studying.
