INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Queen''s Blade OVA', 'OVA', 2, 'Completed', '2011-10-29', '2012-01-28', '6', 'OVAs bundled with the Queen''s Blade Premium Visual Book and the Queen''s Blade Rebellion Premium Visual Book. Both of the episodes will be based on Queen''s Blade Rebellion, a sequel to Queen''s Blade: Utsukushiki Toushitachi.', 85, 'https://cdn.myanimelist.net/images/anime/3/30145.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Divergence Eve 2: Misaki Chronicles', 'TV', 13, 'Completed', '2004-01-03', '2004-03-27', '6', 'Through the long distance warp called the "Exodus Project", Worns, Ryer and the
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Get Ride! AMDriver', 'TV', 51, 'Completed', '2004-04-05', '2005-03-28', '6', 'In the future, human beings are attacked by beings called the Bug-chine, which appeared a few years back. No normal human weapon can defeat the Bug-chine, but there is hope. It is the AMDrivers that will save the earth. They are solders using the latest "AM Technology". With overwhelming power, they will beat the Bug-chine one after another and become heroes, as well as capture the hearts of their fans.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyou, Watashi no Monogatari ga Hashirimasu.: Another Side-hen', 'Special', 1, 'Completed', '2023-05-13', NULL, '6', 'A commercial for the Japan Racing Association (JRA), as a followup to the original. Features the Aimer song Crossovers.', 870, 'https://cdn.myanimelist.net/images/anime/1522/135917.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Niehime to Kemono no Ou Mini Anime', 'ONA', 44, 'Completed', '2022-11-21', '2023-09-28', '6', 'Niehime to Kemono no Ou shorts posted online prior to the anime''s broadcast.', 436, 'https://cdn.myanimelist.net/images/anime/1110/132681.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jantama Pong☆ Special', 'Special', 1, 'Completed', '2022-10-26', NULL, '6', 'A special episode included with the physical release of Jantama Pong☆.', 782, 'https://cdn.myanimelist.net/images/anime/1200/131642.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Selector Infected WIXOSS: Midoriko-san to Piruruku-tan', 'Special', 3, 'Completed', '2014-08-27', '2014-12-19', '6', 'Hosting their own television show, LRIGs Midoriko and Piruluk set aside the thrill of WIXOSS battles to learn more about the world they live in. In striving to answer submitted questions, the two are connected with various individuals—people''s responses shed light on the spirited quirks and earnest feelings that persist even amid an unseen struggle linked to a sinister truth.
