INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuuyake Dandan', 'Movie', 23, 'Completed', '2015-03-31', '2015-09-10', '6', 'Short films screened at 109 Cinemas during previews.', 249, 'https://cdn.myanimelist.net/images/anime/9/72570.jpg');
