INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Komatsu Sakyou Anime Gekijou Specials', 'Special', 3, 'Completed', '1990-03-23', '1990-06-22', '5', 'Unaired episodes of Komatsu Sakyo Anime Gekijou that were included on the VHS release. The first 2 eps were on VHS volume 1 and the 3rd ep was on VHS volume 2.', 321, 'https://cdn.myanimelist.net/images/anime/1419/98322.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('B Rappers Street', 'TV', 50, 'Completed', '2019-04-11', '2020-03-26', '5', 'A multimedia project collaboration between Shogakukan, Sony Interactive Entertainment, Sony Music Entertainment, and Sony Music Communications, and features a theme of rap and hip-hop.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kokoro no Tokyo Kakumei', 'ONA', 3, 'Completed', '2015-07-02', NULL, '5', 'A studio DLE collaboration with the Tokyo Metropolitan government, aims to improve Tokyoites'' public manners and regard for others. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The Planet of Stray Cats', 'OVA', 13, 'Completed', '2015-11-11', NULL, '5', 'The Planet of Stray Cats, the "grown-up" CG gag comedy anime from studio Plus Heads collaboration with the "Mad Max: Fury Road" film. The film''s director George Miller himself approved this collaborative short.  The anime features the nonsensical, surreal conversations of stray cats on a planet. The only voice cast member, named Monica, ad-libs the dialogue of all the characters.', 873, 'https://cdn.myanimelist.net/images/anime/1381/98334.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Inuwari-san', 'Special', 1, 'Completed', '2009-03-18', NULL, '5', 'The pilot of Inuwari-san, it was originally meant to be a TV series before being canceled. The pilot was screened at the 2009 Tokyo International Anime Fair and developed as part of Miyagi Prefecture''s Miyagi e-Brand Establishment Support Project.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kedama no Gonjirou', 'TV', 51, 'Completed', '2019-04-06', '2020-03-28', '5', 'One day, a timid fifth elementary student named Makoto Maegami discovers a mysterious jumping hairball stuck to its head! It then eats one of Makoto''s buttons and suddenly transforms into an alien-like form named Gonjiro.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('10-piki no Kaeru', 'OVA', 4, 'Completed', '1998-03-13', '1998-03-21', '5', 'Ten frogs set out in search of adventure in their swamp, sailing in a boat made from a running shoe. Based on the children''s book by Hisako Madokoro and Michiko Nakagawa, the story of the frogs returned in a second episode, in which they went to a summer festival. Each episode has 2 stories in it.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nemurenu Yoru no Chiisana Ohanashi', 'OVA', 3, 'Completed', '1992-04-24', '1992-10-23', '5', 'Three videos about cats--Cat''s Best Friend, Cat''s Adventure, and Cat''s Christmas-each containing three smaller stories of feline fun. Based on a 1989 column in Monthly Kadokawa magazine by Yuko Hara, better known as the keyboard player/vocalist with the Southern All-Stars.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lao Po Po De Zao Shu', 'Movie', 1, 'Completed', '1958-01-01', NULL, '5', '', 792, 'https://cdn.myanimelist.net/images/anime/1555/118026.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Karasu no Panya-san/Dorobou Gakkou', 'OVA', 2, 'Completed', '1998-09-11', NULL, '5', 'A double feature based on a best-selling children''s books by Satoshi Hako.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Qiang Shang De Hua', 'Movie', 1, 'Completed', '1958-01-01', NULL, '5', '', 792, 'https://cdn.myanimelist.net/images/anime/1799/118080.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiao Hou Yu Bai Pang', 'Movie', 1, 'Completed', '1958-01-01', NULL, '5', '', 792, 'https://cdn.myanimelist.net/images/anime/1831/118040.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kasumin 2nd Season', 'TV', 26, 'Completed', '2002-10-05', '2003-04-05', '5', 'Second season of Kasumin', 621, 'https://cdn.myanimelist.net/images/anime/13/67257.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('San Mao Liu Lang Ji', 'Movie', 1, 'Completed', '1958-01-01', NULL, '5', '', 792, 'https://cdn.myanimelist.net/images/anime/1632/118081.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('San Mao Liu Lang Ji (TV)', 'TV', 4, 'Completed', '1984-01-01', NULL, '5', 'With a big head and three hairs on top, Sanmao, a child from an ordinary family, originally had a happy childhood, but the war made him a helpless orphan. A child without parents can even bully yellow dogs and crows. In times of crisis, he was rescued by a kind-hearted old fisherman and experienced a long-lost but short-lived happiness. The good times didn''t last long, the bullies stole the fruits of their labor, and the bandit soldiers brutally shot the old man to death.  What will be waiting for him... The film is adapted from the comic book of the same name by the famous cartoonist Zhang Leping.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sore Ike! Anpanman: Rhythm de Teasobi - Anpanman to Fushigi na Parasol', 'Movie', 1, 'Completed', '2012-07-07', NULL, '5', '', 990, 'https://cdn.myanimelist.net/images/anime/6/67007.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Major: World Series', 'OVA', 2, 'Completed', '2011-12-16', '2012-01-18', '8', 'Gorou Shigeno''s journey with the Indiana Hornets continues as they seek to win the prestigious World Series. However, after an unexpected accident during the match with his fated rival, his quest in becoming the world''s best becomes more challenging. Undaunted, Gorou continues to put the weight of his dreams into every pitch he makes, and forges a path towards his desired future through high-speed pitching.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga Eiyuu Densetsu: Die Neue These - Seiran 3', 'Movie', 4, 'Completed', '2019-11-29', NULL, '8', 'At the behest of Admiral Yang Wen-li, defected intelligence officer Commander Baghdash makes an emergency broadcast announcing that the National Salvation Military Council staged a coup under the direction of the Galactic Empire. Despite the lack of physical evidence, this debilitating declaration inspires former Rear Admiral Andrew Lynch to reveal his own role in sowing discord within the Free Planets Alliance. A fatal shootout between Lynch and Admiral Dwight Greenhill acts as the final death knell to the short-lived period of martial rule.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uma Musume: Pretty Derby Season 2', 'TV', 13, 'Completed', '2021-01-05', '2021-03-30', '8', 'Within the horse-racing world, the horse girls of Team Spica have been gaining popularity as they continue to rack up victories. The one receiving the most attention in the group is Toukai Teiou, known for her cheerful personality and exceptional running skills. Teiou aims to become an undefeated Triple Crown horse girl by winning all three G1 races consecutively, a feat that has not been accomplished since the legendary Symboli Rudolf managed to do so many years ago.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tokyo Godfathers', 'Movie', 1, 'Completed', '2003-11-08', NULL, '8', 'One Christmas Eve, Hana, Gin, and Miyuki are rummaging for presents through heaps of garbage when they chance upon an abandoned baby in the cold winter night. Appalled at the pitiful sight, Hana''s maternal instincts kick in and she insists on finding the baby''s biological mother to demand an explanation. Naming the baby Kiyoko—meaning pure child—they begin their search using the possible clues left alongside her: a mysterious key and a single note. However, their plans are soon thrown into disarray as they get caught up in a series of unprecedented events.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kino no Tabi: The Beautiful World', 'TV', 13, 'Completed', '2003-04-08', '2003-07-08', '8', 'Kino, a 15-year-old traveler, forms a bond with Hermes, a talking motorcycle. Together, they wander the lands and venture through various countries and places, despite having no clear idea of what to expect. After all, life is a journey filled with the unknown. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tanoshii Muumin Ikka', 'TV', 78, 'Completed', '1990-04-12', '1991-10-03', '8', 'Spring has finally arrived in Moomin Valley, giving way to another great adventure for Moomintroll and the rest of its inhabitants. With Snufkin coming home from his winter migration, the locals of the valley finally begin to rise from their hibernation. Finding a mysterious hat, the Moomins cannot bring themselves to throw it away due to its fine quality, instead hoping to eventually find its owner. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rurouni Kenshin: Meiji Kenkaku Romantan', 'TV', 94, 'Completed', '1996-01-10', '1998-09-08', '8', 'In the final years of the Bakumatsu era lived a legendary assassin known as Hitokiri Battousai. Feared as a merciless killer, he was unmatched throughout the country, but mysteriously disappeared at the peak of the Japanese Revolution. It has been ten peaceful years since then, but the very mention of Battousai still strikes terror into the hearts of war veterans.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Naruto: Shippuuden', 'TV', 500, 'Completed', '2007-02-15', '2017-03-23', '8', 'It has been two and a half years since Naruto Uzumaki left Konohagakure, the Hidden Leaf Village, for intense training following events which fueled his desire to be stronger. Now Akatsuki, the mysterious organization of elite rogue ninja, is closing in on their grand plan which may threaten the safety of the entire shinobi world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kage no Jitsuryokusha ni Naritakute! 2nd Season', 'TV', 12, 'Completed', '2023-10-04', '2023-12-20', '8', 'Enticed by its rumored wealth, Cid Kagenou happily tags along with his sister, Claire, on a trip to the infamous Lawless City. The region is ruled by three monarchs: Yukime, the Spirit Fox; Juggernaut, the Tyrant; and Elisabeth, a dormant progenitor vampire known as the Blood Queen. Hunting Elisabeth down serves as the perfect opportunity for Claire to prove her true mettle. On the other hand, Cid has different objectives—sneaking away from Claire''s sight, collecting as much loot as possible, and making Shadow''s glorious entrance at the perfect moment.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Diamond no Ace: Act II', 'TV', 52, 'Completed', '2019-04-02', '2020-03-31', '8', 'The hallowed ground of Koshien Stadium is the "field of dreams," where the ambitions of high school baseball players come true. After emerging victorious in the autumn tournament last year, Seidou High School baseball''s team  has finally earned the right to compete there for the first time in seven years.  Beyond the spring tournament looms the battle to decide who is the best team in the nation  — the Summer Koshien.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gin no Saji 2nd Season', 'TV', 11, 'Completed', '2014-01-10', '2014-03-28', '8', 'Now accustomed to his life at Ooezo Agricultural High School, Yuugo Hachiken explores the deeper aspects of what school life really means. As Hachiken learns more about himself and earns the skills necessary for his everyday tasks, he is even offered the position of the Equestrian Club''s vice-president. The new semester brings a variety of agricultural dilemmas and personal conflicts, but, nevertheless, Hachiken perseveres in order to discover his dream and continue working together with his friends.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doukyuusei', 'Movie', 1, 'Completed', '2016-02-20', NULL, '8', 'Hikaru Kusakabe is a normal, carefree boy in a rock band who is always focused on the present. During the summer, his entire class is forced to participate in an upcoming chorus festival. By coincidence, he discovers his classmate Rihito Sajou—known for being an honor student with excellent grades—practicing his singing alone. Sajou just cannot seem to get their class'' song right, and Kusakabe, delighted at seeing a new side of his straight-laced classmate, offers to help him prepare for the event.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fate/Zero', 'TV', 13, 'Completed', '2011-10-02', '2011-12-25', '8', 'With the promise of granting any wish, the omnipotent Holy Grail triggered three wars in the past, each too cruel and fierce to leave a victor. In spite of that, the wealthy Einzbern family is confident that the Fourth Holy Grail War will be different; namely, with a vessel of the Holy Grail now in their grasp. Solely for this reason, the much hated "Magus Killer" Kiritsugu Emiya is hired by the Einzberns, with marriage to their only daughter Irisviel as binding contract.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gintama: Shinyaku Benizakura-hen', 'Special', 1, 'Completed', '2010-12-15', NULL, '8', 'It''s the running gag of Ben Johnson episode where animation staff reuse the New Years footage; Yorozuya would sit around the kotatsu eating a bowl of tangerines. They discuss elaborate subjects, Shinpachi complains about reusing animation footage, and then Gin-chan always ending the gag with a pointless announcement.', 974, 'https://cdn.myanimelist.net/images/anime/12/26966.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koukaku Kidoutai', 'Movie', 1, 'Completed', '1995-11-18', NULL, '8', 'In the year 2029, Niihama City has become a technologically advanced metropolis. Due to great improvements in cybernetics, its citizens are able to replace their limbs with robotic parts. The world is now more interconnected than ever before, and the city''s Public Security Section 9 is responsible for combating corruption, terrorism, and other dangerous threats following this shift toward globalization.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tenki no Ko', 'Movie', 1, 'Completed', '2019-07-19', NULL, '8', 'Tokyo is currently experiencing rain showers that seem to disrupt the usual pace of everyone living there to no end. Amidst this seemingly eternal downpour arrives the runaway high school student Hodaka Morishima, who struggles to financially support himself—ending up with a job at a small-time publisher. At the same time, the orphaned Hina Amano also strives to find work to sustain herself and her younger brother.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shangri-La Frontier: Kusoge Hunter, Kamige ni Idoman to su 2nd Season', 'TV', 25, 'Completed', '2024-10-13', '2025-03-30', '8', 'Ever since Rakurou "Sunraku" Hizutome started to play the extremely popular virtual reality game Shangri-La Frontier, he has truly fallen in love with it. Sunraku has quickly made a big name for himself by fighting two of the seven unique, nearly unbeatable monsters, which is unthinkable for most players. To progress the game''s story, he sets out on an adventure with his leporine guide, Emul, to acquire a magic operation unit from an ancient workshop.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Haikyuu!! Movie 4: Concept no Tatakai', 'Movie', 1, 'Completed', '2017-09-29', NULL, '8', 'The long-awaited finals of the Spring Tournament have arrived for Karasuno High School''s volleyball team. The winner of the match will go on to represent all of Miyagi Prefecture at the National Tournament. However, the last challenge Karasuno must overcome is to win against Shiratorizawa Academy, the school that houses Wakatoshi Ushijima, one of Japan''s top three aces. Shiratorizawa is the reigning Miyagi champion for the past three years, and Karasuno seems to have little chance at dethroning them. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Steins;Gate: Kyoukaimenjou no Missing Link - Divide By Zero', 'Special', 1, 'Completed', '2015-12-03', NULL, '8', 'Having reached his emotional breaking point, Rintarou Okabe refuses to continue aiding time traveler Suzuha Amane in her mission to prevent World War III, believing any further efforts to save Makise Kurisu will be in vain. Shortly after, Okabe abandons his mad scientist persona and becomes a seemingly regular university student. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Space☆Dandy 2nd Season', 'TV', 13, 'Completed', '2014-07-06', '2014-09-25', '8', 'Second season of Space Dandy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dororo', 'TV', 24, 'Completed', '2019-01-07', '2019-06-24', '8', 'The greedy samurai lord Daigo Kagemitsu''s land is dying, and he would do anything for power, even renounce Buddha and make a pact with demons. His prayers are answered by 12 demons who grant him the power he desires by aiding his prefecture''s growth, but at a price. When Kagemitsu''s first son is born, the boy has no limbs, no nose, no eyes, no ears, nor even skin—yet still, he lives.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuru Camp△', 'TV', 12, 'Completed', '2018-01-04', '2018-03-22', '8', 'While the perfect getaway for most girls her age might be a fancy vacation with their loved ones, Rin Shima''s ideal way of spending her days off is camping alone at the base of Mount Fuji. From pitching her tent to gathering firewood, she has always done everything by herself, and has no plans of leaving her little solitary world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shirobako', 'TV', 24, 'Completed', '2014-10-09', '2015-03-26', '8', 'It all started in Kaminoyama High School, when five best friends—Aoi Miyamori, Ema Yasuhara, Midori Imai, Shizuka Sakaki, and Misa Toudou—discovered their collective love for all things anime and formed the animation club. After making their first amateur anime together and showcasing it at the culture festival, the group vows to pursue careers in the industry, aiming to one day work together and create their own mainstream show.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doupo Cangqiong 4th Season', 'ONA', 24, 'Completed', '2021-03-28', '2021-08-29', '8', 'To awaken his teacher Yao Cheng, Xiao Yan travels to the capital for a meeting of the pill masters. His power was immediately noticed, people who wanted to use it, but at the decisive moment Xiao Yan still becomes a champion and defends the honor of the empire. But Xiao Yan is waiting for a meeting, for which he has been preparing for three whole years...', 585, 'https://cdn.myanimelist.net/images/anime/1887/112452.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gyakkyou Burai Kaiji: Ultimate Survivor', 'TV', 26, 'Completed', '2007-10-03', '2008-04-02', '8', 'After one of his coworkers fails to repay a debt, apathetic bum Kaiji Itou is pressured by loan sharks to settle the large sum of cash. Since Kaiji has little money and no future prospects of his own, he is unable to return what his colleague borrowed. Faced with massive financial burdens, Kaiji is given an offer to board the illustrious Espoir—it is said that "one night aboard the ship, and all of your debts will be paid."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nanatsu no Taizai', 'TV', 24, 'Completed', '2014-10-05', '2015-03-29', '8', 'In a world similar to the European Middle Ages, the feared yet revered Holy Knights of Britannia use immensely powerful magic to protect the region of Britannia and its kingdoms. However, a small subset of the Knights supposedly betrayed their homeland and turned their blades against their comrades in an attempt to overthrow the ruler of Liones. They were defeated by the Holy Knights, but rumors continued to persist that these legendary knights, called the "Seven Deadly Sins," were still alive. Ten years later, the Holy Knights themselves staged a coup d’état, and thus became the new, tyrannical rulers of the Kingdom of Liones.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Digimon Adventure tri. 3: Kokuhaku', 'Movie', 1, 'Completed', '2016-09-24', NULL, '8', 'The Chosen Children are in shock after the betrayal of Meicoomon, the digital monster who had recently joined their group alongside her human partner, Meiko Mochizuki. Koushirou Izumi is determined to diagnose the infection that took control of Meicoomon. Meanwhile, Takeru Takaishi realizes that his own partner, Patamon, is starting to exhibit alarming symptoms similar to those of other infected Digimon, like Meicoomon.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hanhua Riji 2nd Season', 'ONA', 12, 'Completed', '2020-11-15', '2021-01-24', '8', 'In the 21st century, due to the rapid development of human society, the originally stable three realms of humans, gods, and demons lost their balance. The gods and Demons urgently launched the salvation plan and decided to send a group of gods and monsters to the human world to find the key to saving the world. Su Moting is a young woman with the status of "the son of the god and demon". After being invited out of the house by her parents for the reason of "independence and self-improvement", Su Moting met the handsome little cute gods, Tianjixing and Dikui, a mysterious calm cool cat demon. Under the guidance of the land god, the three formed a salvation group and began to perform the funny and heartbreaking nonsense of daily life.', 524, 'https://cdn.myanimelist.net/images/anime/1381/111049.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimagure Orange☆Road: Ano Hi ni Kaeritai', 'Movie', 1, 'Completed', '1988-10-01', NULL, '8', 'Years have passed since Kyousuke Kasuga became entangled in a love triangle with the childish Hikaru Hiyama and the elegant Madoka Ayukawa. Now in their final year of high school, Madoka and Kyousuke are thoroughly occupied preparing for their college entrance exams. Hikaru, not yet close to graduation, struggles with the realization that her two closest friends are leaving her. With the threat of separation looming over the horizon, Kyousuke is finally forced to decide who he loves—no matter how painful it may be.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan Movie 09: Suihei Senjou no Strategy Recap', 'Special', 1, 'Completed', '2005-04-02', NULL, '8', 'A promotional preview summary of the events in Detective Conan Movie 09: Strategy Above the Depths. Aired before the movie.', 990, 'https://cdn.myanimelist.net/images/anime/1356/150509.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rozen Maiden: Träumend', 'TV', 12, 'Completed', '2005-10-21', '2006-01-27', '8', 'As the story of Rozen Maiden closes, a new chapter begins in Rozen Maiden: Träumend. Shinku and the other sentient dolls of the Rozen Maiden collection are living life as usual at Jun Sakurada''s house. Having settled into his role as Shinku''s partner in the deadly Alice Game, Jun overcomes his former fears and prepares to return to school. And although Shinku and the other dolls idly pass the days by in the comfort of Jun''s home, dark times lie ahead as a new foe presents herself: Barasuishou, the seventh Rozen Maiden.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Heion Sedai no Idaten-tachi', 'TV', 11, 'Completed', '2021-07-23', '2021-09-28', '8', 'Eight hundred years ago, terrifying demons threatened mankind''s existence. On the brink of extinction, humans prayed to their gods, calling out for someone to save them. Emerging from these desperate pleas for salvation, battle deities known as the "Idaten" were born. Possessing unnatural strength and endurance, the Idaten managed to defeat the demons and an era of unprecedented peace was finally ushered in.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Break Blade Movie 1: Kakusei no Toki', 'Movie', 1, 'Completed', '2010-05-29', NULL, '8', 'Rygart Arrow is different compared to the other people in the continent of Cruzon: he is unable to control quartz, branded an "un-sorcerer." Despite this, he still befriends the future king and queen of Krisna—Hodr and Sigyn—as well as Zess, the younger brother of the Athens Commonwealth''s Secretary of War.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou Shoujo Lyrical Nanoha StrikerS', 'TV', 26, 'Completed', '2007-04-02', '2007-09-24', '8', 'Distinguished mages Nanoha Takamachi, Fate Testarossa, and Hayate Yagami now work as military personnel for the Time-Space Administration Bureau on the planet Midchilda, having completed their studies on Earth in the last ten years since the "Book of Darkness" incident.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Genshiken OVA', 'OVA', 3, 'Completed', '2006-12-22', '2007-04-25', '8', 'It''s the start of a new year for the Genshiken crew, and that means recruiting new members. Always a dreaded task, The Society for the Study of Modern Visual Culture manages to get Chika Ogiue pushed onto them from the Manga Club. With her introduction of "I''m Ogiue and I hate otaku," this year certainly will be anything but boring.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fune wo Amu', 'TV', 11, 'Completed', '2016-10-14', '2016-12-23', '8', 'Kouhei Araki, a veteran editor of the dictionary editorial division at Genbu Publishing, plans to retire in order to better care for his ailing wife. However, before retiring, he must find a replacement to complete his latest project: a new dictionary called The Great Passage. But no matter where he looks, he cannot find anyone suitable, as making a dictionary requires a wealth of patience, time, and dedication.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Owari no Seraph: Nagoya Kessen-hen', 'TV', 12, 'Completed', '2015-10-10', '2015-12-26', '8', 'Yuuichirou Hyakuya is finally reunited with his childhood friend Mikaela Hyakuya, whom he had long presumed to be dead. Upon their reunion, however, he discovers that Mikaela has been turned into a vampire. Determined to help his friend, Yuuichirou vows to get stronger so that he can protect Mikaela as well as the comrades in the Moon Demon Company.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Servant x Service', 'TV', 13, 'Completed', '2013-07-06', '2013-09-28', '8', 'Frustrating, insufficient, and irritating is how most citizens would describe civil servants. However, three new employees are about to discover what really happens behind the scenes. Lucy Yamagami, bent on revenge against the civil servant who allowed her comically long name to be put on her birth certificate; Yutaka Hasebe, an easygoing guy always on the lookout for a place to slack off; and Saya Miyoshi, a nervous first-time worker, are about to experience the underwhelming satisfaction of being government employees. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tong Ling Fei', 'ONA', 16, 'Completed', '2018-11-30', '2019-04-19', '8', 'When Qian Yunshang''s marriage to Ye Youming is arranged by the emperor, she is terrified that the bad blood between their families will lead to her being treated miserably in the Ye household. Torn between duty and concern for his daughter, Qian Aotian devises a reckless plan. He summons his firstborn daughter—her existence unknown to all but his own family—to be the stand-in for her younger sister.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The iDOLM@STER Movie: Kagayaki no Mukougawa e!', 'Movie', 1, 'Completed', '2014-01-25', NULL, '8', 'The idols of 765 Production continue on their neverending journey—towards a new stage, towards a bright and shiny future!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dakaretai Otoko 1-i ni Odosarete Imasu. Movie: Spain-hen', 'Movie', 1, 'Completed', '2021-10-09', NULL, '8', 'Takato Saijou and Junta Azumaya—Japan''s sexiest men—perform wonders together as co-stars. Their next joint assignment is to act in a play featuring a flamenco showdown, but Junta once again holds an advantage due to his ancestry and because Takato has never danced before. Fueled by his ceaseless desire to outshine Junta, Takato decides to travel to southern Spain and learn firsthand the passion needed to perform the demanding dance.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Utawarerumono', 'TV', 26, 'Completed', '2006-04-04', '2006-09-26', '8', 'An injured man is found in the woods by a girl named Eruruu, and everything about him is mysterious. Without knowledge of his past nor even his own name, he is welcomed to Eruruu''s home and is given the name Hakuoro by her grandmother, and younger sister, Aruruu. While the inhabitants of the village have large ears and tails, Hakuoro''s defining physical trait is quite different as he has neither ears nor tail, but only a mask that he cannot remove.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Digimon Adventure Movie', 'Movie', 1, 'Completed', '1999-03-06', NULL, '8', 'A brother and sister discover the digital world is more than 1s and 0s when a living creature arrives out of the family computer. The adventures of a group of children start with the appearance of a Digital Monster in the real world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Juubee Ninpuuchou', 'Movie', 1, 'Completed', '1993-06-05', NULL, '8', 'Jubei Kibagami wanders feudal Japan as an itinerant swordsman-for-hire. After a past betrayal left him masterless, he has no more patience for warring political factions and their schemes. Unfortunately, both past and political intrigue collide when he meets and saves a female ninja named Kagero from a man with the ability to make his body as hard as stone.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Piano no Mori', 'Movie', 1, 'Completed', '2007-07-21', NULL, '8', 'Piano no Mori tells the story of Shuuhei Amamiya, a transfer student, and Kai Ichinose, a problem child from the rough areas of town. Upon transferring to Moriwaki Elementary and telling the other kids about his talent for piano, Shuuhei quickly finds himself as the victim of bully Daigaku Kanehira. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maria-sama ga Miteru: Haru', 'TV', 13, 'Completed', '2004-07-04', '2004-09-26', '8', 'The spring term is beginning for the students at Lillian Girls'' Academy. Friends are reunited, but for the Yamayuri Council, it''s a bittersweet time. Yoko, Eriko, and Sei are busy preparing to depart Lillian while Sachiko, Rei, and Shimako are doing their best to ensure that their dear sisters receive a memorable commencement.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seikai no Senki III', 'OVA', 2, 'Completed', '2005-08-06', NULL, '8', 'Jinto and Lafiel were riding on a light-armed transport ship "Bokbrusue" and navigating at the planar space of the Hyde System. This was for Jinto to govern the Hyde System, which returned to Empirial rule after the Union retreated, officially as an Earl. However, the government of Martin, Jinto`s motherland, resisted obstinately against the Empirial rule. On the other side, "Daiichi Jyuurin Sentai" (the First Devastation Fleet), formed with the new ship type "Attack Vessel", travelled to the Hyde System for drilling practices, but... 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eikoku Koi Monogatari Emma', 'TV', 12, 'Completed', '2005-04-03', '2005-06-19', '8', 'Emma has been a maid for most of her life. Working for a retired governess—the strict but compassionate Kelly Stownar—Emma has grown to love her work and has long since accepted her place in society. Beautiful, hardworking, and exceptionally kind, Emma has captured the hearts of many of London''s working men—but their feelings always remain unrequited. Emma is waiting for love, and she finds it in the most unlikely of places.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gabriel DropOut Specials', 'Special', 2, 'Completed', '2017-03-24', '2017-05-24', '8', 'Specials included with the Blu-ray/DVD release of Gabriel DropOut.', 241, 'https://cdn.myanimelist.net/images/anime/8/89690.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seikai no Monshou', 'TV', 13, 'Completed', '1999-01-03', '1999-03-28', '8', 'In the distant future, humanity is under attack by the Abh Empire, a race of advanced humanoid beings possessing vastly superior technology. As countless worlds fall to the Abh, mankind establishes the Four Nations Alliance—a resistance faction made up of the United Mankind, the Republic of Greater Alcont, the Federation of Hania, and the People''s Sovereign of Union Planets.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Alma-chan wa Kazoku ni Naritai', 'TV', 11, 'Airing', '2025-10-05', '2025-12-14', '7', 'Alma, an autonomous self-learning robot with advanced combat capabilities, was created by two genius scientists, Enji Kamisato and Suzume Yobane, who developed Alma''s artificial intelligence and robotics, respectively. After being mocked by their former acquaintances, the duo have worked together in order to show the world their true talents. But even though they cooperate in their work, the two scientists cannot seem to get along in their personal lives.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shen Mu 2nd Season', 'ONA', 27, 'Completed', '2024-08-10', '2025-02-01', '7', 'Second season of Shen Mu.', 1108, 'https://cdn.myanimelist.net/images/anime/1527/144555.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sentai Daishikkaku 2nd Season', 'TV', 12, 'Completed', '2025-04-13', '2025-06-29', '7', 'After Sentouin D successfully infiltrated the Ranger Force in the disguise of Hibiki Sakurama, he is closer than ever to defeating the heroic Dragon Keepers. While strategizing his ideal placement in the Force, he discovers that he is assigned to the Green Squadron, whose main duty is to search and eradicate long-lost boss monsters.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cardfight!! Vanguard: Divinez', 'TV', 13, 'Completed', '2024-01-13', '2024-04-20', '7', 'One day, six cards known as the "Six Desires" were born with the power to change fate.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan: Honchou no Keiji Koi Monogatari - Kekkon Zenya', 'Special', 1, 'Completed', '2022-04-15', NULL, '7', 'The special contains the footage from episodes featuring Takagi and Sato, with a new narration from Conan and re-recorded line of Takagi and Sato.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Happiness Charge Precure! Movie: Ningyou no Kuni no Ballerina', 'Movie', 1, 'Completed', '2014-10-11', NULL, '7', 'The film''s story is set in the Doll Kingdom where dolls reside. Happiness Charge PreCure are asked to help by a women named Tsumugi when the sudden appearance of Saiarks begin wrecking havoc upon the Kingdom. However all is not what it seems with the mysterious man Black Fang dwelling in the shadows.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam: Dai 08 MS Shoutai - Sanjigen to no Tatakai', 'Special', 1, 'Completed', '2013-02-22', NULL, '7', 'Mobile Suit Gundam: The 08th MS Team - Battle in Three Dimensions is a short film bundled with Mobile Suit Gundam: The 08th MS Team Blu-ray Memorial Box-set.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lostorage Conflated WIXOSS', 'TV', 12, 'Completed', '2018-04-07', '2018-06-23', '7', 'Tensions from the Selector battles have seemingly vanished, and the remaining participants have quickly put the entire ordeal behind them. However, Kiyoi Mizushima feels that the conflict has yet to end. Despite Kou Satomi''s defeat, his supporters are already attempting to revive his plans in the background.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Keroro Gunsou Movie 5: Tanjou! Kyuukyoku Keroro, Kiseki no Jikuu-jima, de Arimasu!!', 'Movie', 1, 'Completed', '2010-02-27', NULL, '7', 'One day, a stone carving bearing an uncanny likeness to Keroro  arrives at Fuyumi''s place. To solve this mystery, the Keroro Squad travels to the isolated and mysterious Easter Island. There, they meet harmless spirits known as Mana, and the odd twins Io and Rana. Lastly, there is Akuaku, a legendary evil spirit recently awoken from its long sleep. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Precure All Stars Movie: Minna de Utau♪ - Kiseki no Mahou', 'Movie', 1, 'Completed', '2016-03-19', NULL, '7', 'Mirai and Rico come to the human world to play, but are separated when the witch Sorciere and her servant Torauuma suddenly appear. Their aim is to acquire the tears of the 44 Precure girls, using them for her "Most Evil Magic." Only the friendship of all 44 Precure girls will allow them to protect the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Accel World EX', 'OVA', 2, 'Completed', '2012-09-13', '2013-01-31', '7', 'Reverberation
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saint Seiya: Soul of Gold', 'ONA', 13, 'Completed', '2015-04-11', '2015-09-26', '7', 'In the Underworld, during the fight against Hades, the 12 Gold Saints gave up their lives to destroy the Wailing Wall and allow Seiya and his friends to keep moving forward. Aioria and the Gold Saints, who should have disappeared, come back to life in this beautiful Earth full of light. How have they resurrected if they were supposed to be dead? While the big mystery remains, Aioria gets involved in a new battle and when his Cosmo exceeds its limits... a change happens to the Leo Cloth!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Prima Doll', 'TV', 12, 'Completed', '2022-07-09', '2022-09-24', '7', 'Black Cat Cafe is located in the fifth ward of the Imperial Capital. Having lost their purpose after the war ended a few years prior, advanced mechanical dolls known as Automata have been restored and now work at the cafe wearing elegant kimonos. While they adjust to the peaceful world, events of the past continue to haunt the Automata, preventing them from letting go of the responsibility they once held.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('BanG Dream! Asonjatta!', 'Special', 1, 'Completed', '2017-11-22', NULL, '7', 'Unaired episode included with the 7th Blu-ray volume of BanG Dream!.', 1117, 'https://cdn.myanimelist.net/images/anime/13/89692.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('No Guns Life 2nd Season', 'TV', 12, 'Completed', '2020-07-10', '2020-09-25', '7', 'Picking up where season one left off, Juzo Inui (Gun Slave Unit Device 13) has Rosa''s data. Although it seems like everyone wants it, either to expose it or to destroy it, really no one is interested in it. Wachowski, the leader of the anti-Extended terrorist organization Spitzbergen, attempts to coerce Tetsurō to use Harmony to command Juzo to destroy Gun Slave Unit Device 7, who works for Berühren. Juzo does eventually fight Seven, but -- between corruption and double-crosses -- Berühren still pulls all the strings.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nanatsu no Taizai Movie 1: Tenkuu no Torawarebito', 'Movie', 1, 'Completed', '2018-08-18', NULL, '7', 'In search of a mystical ingredient known as Sky Fish, Meliodas and Hawk stumble upon a spring that suddenly transports them to the Sky Temple: a breathtaking land above the clouds, inhabited by beings called Celestials. Meliodas, however, looks strikingly similar to a local criminal called Solaad, and is imprisoned and shunned as a result. Meanwhile, the kingdom of the Sky Temple prepares to defend the Great Oshiro''s seal—said to harbour a three thousand-year-old evil—from the malevolent Six Knights of Black, a group of demons who seek to destroy the seal. However, the Demon Clan is successfully unleashed and terrorizes the land, prompting the remaining Seven Deadly Sins and the Celestials to fight against their wicked foes. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jie Yao', 'ONA', 13, 'Completed', '2020-01-09', '2020-03-26', '7', 'Cheng Ke has lost everything. Coming from a privileged background, he now has to search through trash to find his missing possessions. When one of his frustrated outbursts results in him being punched in the face, Cheng Ke finds himself unfortunately acquainted with terrifying gang leader Jiang Yuduo.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('RD Sennou Chousashitsu', 'TV', 26, 'Completed', '2008-04-09', '2008-10-01', '7', '2061 AD. Fifty years have passed since mankind developed the Network society. It was anticipated that this new infrastructure would realize a utopia where people connected with each other at the level of consciousness. However, new social problems such as personal data leaks and proliferation of manipulated information began to surface. Nevertheless, people still relied on the Network to exchange information, and proved unable to opt to abandon it.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Muteki Koujin Daitarn 3', 'TV', 40, 'Completed', '1978-06-03', '1979-03-31', '7', 'Souzou Haran was a brilliant scientist that was conducting research on Mars. He created a form of cyborg life with the ability to think for itself. These cyborgs, dubbed the Meganoids, soon ran out of control and killed Dr. Haran along with his whole family, save his youngest son, the 16-year-old Banjou Haran. Banjou escapes from Mars on a rocket with a solar-powered super robot called Daitarn 3, which was built with the special metals of Mars. Now eighteen years old and living on Earth in a luxurious mansion, Banjou fights against the Meganoids with the aid of his faithful butler Garrison and his two gorgeous companions Reika and Beauty. Together they must stop the evil Meganoids which aspire to turn all humans into cyborgs and thus "improve" the human race.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saraba Uchuu Senkan Yamato: Ai no Senshi-tachi', 'Movie', 1, 'Completed', '1978-08-05', NULL, '7', 'In the year 2201, one year after the Yamato saved Earth from radioactive contamination, a new threat emerges. The Yamato makes its final journey to save the Earth from this new threat.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saenai Heroine no Sodatekata: Ai to Seishun no Service-kai', 'Special', 1, 'Completed', '2015-01-09', NULL, '7', 'The latest game by Blessing Software needs one final push to make it over the finish line. To help with this, the team ventures out to the Japanese countryside for location scouting. Illustrator Eriri Spencer Sawamura and model Megumi Kato busy themselves with work. However, scriptwriter Utaha Kasumigaoka and music producer Michiru Hyoudou have other plans with their teammate Tomoya Aki. With the four girls all fighting for his attention, Tomoya finds himself in increasingly risqué situations.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Adachi to Shimamura', 'TV', 12, 'Completed', '2020-10-09', '2020-12-25', '7', 'Somewhere in the school at noon, one might hear the sound of two girls playing table tennis together as they wait for time to pass by.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('A3! Season Spring & Summer', 'TV', 12, 'Completed', '2020-01-14', '2020-06-23', '7', 'Home to countless street acts and performances, Veludo Way attracts those interested in watching professional actors. After receiving a mysterious letter, Izumi Tachibana arrives at the venue where her father directed a once-popular theater group, Mankai Company, but learns that the building is about to be repurposed due to excessive debt. At the last minute, she convinces the debt collector to give the ensemble one more chance. He is willing to accept but on three conditions: their debut show must be successfully produced by the following month, the four all-male sub-troupes must be reinstated, and the debt must be paid off within a year. To top it off, Izumi herself must become the director.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Masuda Kousuke Gekijou: Gag Manga Biyori 2', 'TV', 12, 'Completed', '2006-08-05', '2006-10-21', '7', 'Gyagu Manga Biyori is hyperactive, random, and nonsensical, revolving around various plots and characters throughout the series. It makes absolutely no sense. The 1st episode is about stickers included in snacks
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuang Wang', 'ONA', 9, 'Completed', '2024-02-28', '2024-03-13', '7', 'Youyu, a frail Asura youth, witnesses his tribe''s slaughter, unlocking his hidden potential. Abducted by his ancestor Liaoji, he endures torturous training, mastering the Martial God''s Five Senses. Reuniting with his friend Shiyu, Youyu sees him persecuted to death by Asura''s ruthless laws. Determined to rewrite these rules, Youyu sets forth to become the strongest.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Synduality: Noir', 'TV', 12, 'Completed', '2023-07-11', '2023-09-26', '7', 'In 2242, the remnants of humanity are forced to live in scattered bubble-like cities across devastated lands. Hiding from toxic rain and hostile lifeforms known as Enders, they survive thanks to a new source of energy from AO crystals. Those tasked with risking their lives to collect AO crystals are called drifters, piloting versatile bipedal tanks with the support of combat androids named magus.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wangu Shenhua', 'ONA', 280, 'Completed', '2022-08-15', '2025-04-10', '7', 'A small town boy whose spiritual seed was abolished unexpectedly received the favor of an ancient treasure. In a prosperous world of martial arts, in a perilous situation, what should Wang Hao, who is in the center of the whirlpool, do?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uta no☆Prince-sama♪ Maji Love ST☆RISH Tours: Tabi no Hajimari', 'Special', 1, 'Completed', '2022-07-31', NULL, '7', 'A prologue to Uta no☆Prince-sama♪ Movie: Maji Love ST☆RISH Tours.', 14, 'https://cdn.myanimelist.net/images/anime/1479/126366.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boku to Roboko', 'TV', 28, 'Completed', '2022-12-05', '2023-06-19', '7', 'Robotic OrderMaids are popping up in every household, and 10-year-old Bondo Taira has found out that his two closest friends—Motsuo and Gachi Gorilla—have OrderMaids too. Motsuo, in particular, owns Meico, a beautiful robot that gives excellent massages and serves drinks with a smile. Jealous of his friend, Bondo convinces his mother to get him an OrderMaid, hoping for a similar experience.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xing Wushen Jue 2nd Season', 'ONA', 40, 'Completed', '2022-06-24', '2022-10-28', '7', 'The second season of Xing Wushen Jue.', 752, 'https://cdn.myanimelist.net/images/anime/1309/125179.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiao Mo Tou Baolu La! 2', 'ONA', 13, 'Completed', '2022-04-09', '2022-07-02', '7', 'Second season of Xiao Mo Tou Baolu La!.', 1098, 'https://cdn.myanimelist.net/images/anime/1498/122870.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wangu Xian Qiong', 'ONA', 12, 'Completed', '2017-05-18', '2017-07-27', '7', 'Heavenly Dao is eternal, however life is limited, making heaven and earth pieces of a chessboard.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shirobako Specials', 'Special', 2, 'Completed', '2015-02-25', '2015-07-29', '7', 'Shirobako Specials is an OVA adaptation of the first episodes of the two fictional television anime produced by Musashino Animation in the Shirobako television anime.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sword Art Online Movie: Ordinal Scale - Sword Art Offline', 'Special', 1, 'Completed', '2017-09-27', NULL, '7', '', 397, 'https://cdn.myanimelist.net/images/anime/12/87940.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Magia Record: Mahou Shoujo Madoka☆Magica Gaiden', 'TV', 13, 'Completed', '2020-01-05', '2020-03-29', '7', 'Rumor has it that if a young girl strikes a bargain with a white fairy, it will grant any wish her heart desires. However, in exchange, she will become a magical girl and must put her life on the line to slay fearsome and ferocious witches.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Devils Line', 'TV', 12, 'Completed', '2018-04-07', '2018-06-23', '7', 'Vampires walk among society, existing as part of its underbelly. They do not require blood to survive, but extreme emotions can immensely increase their bloodlust, turning them into uncontrollable monsters. Tsukasa Taira, a 22-year-old university student, learns of the existence of vampires when her longtime friend reveals himself to be one of them after a tense confrontation with Yuuki Anzai—a human and vampire hybrid.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mayonaka no Occult Koumuin: Fukurokouji to Ano Ko to Ore to', 'OVA', 1, 'Completed', '2019-11-22', NULL, '7', 'Episode 13 was bundled with the limited edition 12th volume of the manga.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dream Festival! R', 'ONA', 12, 'Completed', '2017-08-23', '2017-11-08', '7', '', 116, 'https://cdn.myanimelist.net/images/anime/1633/133979.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zetman', 'TV', 13, 'Completed', '2012-04-03', '2012-06-26', '7', 'The story starts off with a face-off between two rival heroes, ZET and ALPHAS, and then traces their origins - Jin Kanzaki, a young man with the ability to transform into a superhuman being known as ZET, and Kouga Amagi, a young man with a strong sense of justice who uses technology to fight as ALPHAS.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Genji Monogatari Sennenki', 'TV', 11, 'Completed', '2009-01-16', '2009-03-27', '7', 'Born from a much loved, but lowly ranked concubine, Genji Hikaru is called the Shining Prince and is the beloved second son of the Emperor. Although he cannot be an heir to the throne of his father, Genji spends his life surrounded by every pleasure and love. And yet, his one longing in love is something that even the power of an Emperor can never give him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toaru Majutsu no Index III', 'TV', 26, 'Completed', '2018-10-05', '2019-04-05', '7', 'Touma Kamijou can''t catch a break. After the invasion of Academy City, political tensions continue to rise as both the science and magic factions collide head on. It appears that Academy City intends to declare war against the Roman Catholic Church, consequently plunging the whole world into global warfare. Touma soon finds himself on the front lines once again, striving to protect his friends and allies.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kekkai Sensen: Soresaemo Saitei de Saikou na Hibi', 'Special', 1, 'Completed', '2015-06-14', NULL, '7', 'A recap episode of episodes 1 through 10 of Kekkai Sensen. Leonardo Watch reflects on his experiences at Libra.', 138, 'https://cdn.myanimelist.net/images/anime/3/74387.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Miyanishi Tatsuya Gekijou: Omae Umasou da na', 'TV', 20, 'Completed', '2010-10-04', '2010-10-29', '6', 'A Tyrannosaurus called Heart was raised by a herbivorous dinosaur. As he grew up, he was scared by other dinosaurs. One day, Heart meets a baby Ankylosaurus and he names the baby "Umasou (looks delicious)". Umasou started to be attached to Heart and a strange family love develops between the two.', 53, 'https://cdn.myanimelist.net/images/anime/13/26785.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Delico''s Nursery: Ikuji Nisshi', 'Special', 1, 'Completed', '2024-10-10', NULL, '6', 'From the pages of Dali''s child-rearing journal, as reported on by Henrique, it''s a summary of the first six episodes of Delico''s Nursery.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Urusei Yatsura x Onitsuka Tiger Collaboration CM', 'Special', 1, 'Completed', '2022-10-20', NULL, '6', 'A collaboration commercial between the shoe brand Onitsuka Tiger and Urusei Yatsura. It features Ataru and Lum shopping at the real life Onitsuka Tiger store, where Lum attacks Ataru after he hits on the shop attendant.', 227, 'https://cdn.myanimelist.net/images/anime/1191/129537.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jian Xian Zai Ci', 'ONA', 36, 'Completed', '2022-05-21', '2022-09-21', '6', 'Lin Beichen, an otaku, got a mobile phone by coincidence, and the mobile phone took him into a world called Dongdong Zhenzhou. Here, he became the first son of Lin Jinnan, one of the top ten famous men in the North Sea Empire [Zhantianhou]. He was also a notorious black sheep, and was born with brain disease. When Hou Lin was defeated in the south during the war, his family was in decline, and Lin Beichen, who lost his backer, was stuck in school by various'' enemies'' and couldn''t go out. In a critical moment, he was surprised to find that the mobile phone he brought with him turned out to be a plug-in artifact that could help him practise. Relying on this artifact, Lin Beichen opened his own way of hilarious counterattack.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('100-man no Inochi no Ue ni Ore wa Tatteiru Recap', 'Special', 1, 'Completed', '2021-07-02', NULL, '6', 'Recap of the first season of 100-man no Inochi no Ue ni Ore wa Tatteiru airing before second season.', 542, 'https://cdn.myanimelist.net/images/anime/1453/122534.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Haiyoru! Nyaruani', 'OVA', 9, 'Completed', '2010-03-17', NULL, '6', 'Animated Flash shorts based on the light novel series "Haiyore! Nyaruko-san." In these shorts, Nyarlko, an anthropomorphized female version of Nyarlathotep from the Cthulhu Mythos, is constantly being told off by Mahiro, a normal human boy, for all the crazy or stupid things she does.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gokujou!! Mecha Mote Iinchou Second Collection', 'TV', 51, 'Completed', '2010-04-03', '2011-04-10', '6', 'The continuation of Gokujou!! Mecha Mote Iinchou with a new title.  Episode numbers continue from 51.', 806, 'https://cdn.myanimelist.net/images/anime/5/23149.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Heibai Wushuang 2nd Season', 'ONA', 12, 'Completed', '2017-08-05', '2017-10-14', '6', 'The opposite bank of Lethe River is Boundary Realm with all night along, keeping the balance of the world’s deaths by ghost messengers. Black and White Warriors are ghost messengers collecting spirits from the Human Realm. Xiaohei and Xiaobai, a pair of Black and White Warriors at the bottom, whose relationship became delicate after experiencing the incident happened inside One Hundred Ghost Great Seal. At the same time, Xiaobai’s true identity began to surface…', 1098, 'https://cdn.myanimelist.net/images/anime/12/88317.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hajimete no Gal', 'TV', 10, 'Completed', '2017-07-12', '2017-09-13', '6', 'Following a prank pulled by his perverse friends, Junichi Hashiba asks a gal out in an attempt to change the fact that he''s a hopeless virgin. Yukana Yame, the girl in question, is disgusted by Junichi''s groveling. However, through a series of teasing remarks, she soon finds herself bonding with him and ultimately accepting Junichi''s confession, much to his surprise.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ingress the Animation', 'TV', 11, 'Completed', '2018-10-18', '2018-12-27', '6', 'A project was launched where scientists discovered a mysterious substance that can interface directly with the human brain. This substance, called "Exotic Matter (XM)," has existed since ancient times, influencing human minds and the progress of humanity. In the wake of this discovery, a battle of powerful nations and corporate giants has been unleashed. Organizations across the globe have embarked on a secret race to exploit XM. It represents both an opportunity and a threat to humanity. Two Factions seeks to control the XM. The Enlightened view XM''s power as a gift that enhances human experience and discovery. The Resistance sees XM as a hostile takeover of the human mind, choosing technology as humanity''s best path forward. XM, and the mystery behind it lie at the center of this battle for the fate of humanity.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Monster Strike the Movie: Sora no Kanata', 'Movie', 1, 'Completed', '2018-10-05', NULL, '6', '13 years ago, suddenly one part of Tokyo broke off and began to float in the sky. Tokyo was separated into "Old Tokyo" as the part that was floating in the air, and "New Tokyo," the part that stayed on the ground. Communication and interaction between the two Tokyos was impossible, and years passed. One day, a young girl perceives that Old Tokyo will fall back down to the ground, and she sets out on the perilous path from from Old Tokyo to New Tokyo to save the citizens from the impending crisis.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seizei Ganbare! Mahou Shoujo Kurumi 2nd Season', 'ONA', 25, 'Completed', '2018-10-28', '2019-10-13', '6', 'Second season of Seizei Ganbare! Mahou Shoujo Kurumi.', 681, 'https://cdn.myanimelist.net/images/anime/1880/103502.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Megumi', 'ONA', 1, 'Completed', '2008-03-28', NULL, '6', 'An anime biography on Megumi Yokota, who was abducted by North Korea in 1977 when she was 13 years old. North Korea acknowledges abducting her and at least 12 other Japanese residents during the 1970s and the 1980s, but the country has not provided any conclusive evidence on her fate and most of the others.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Comet Lucifer: Garden Indigo no Shasou kara', 'ONA', 12, 'Completed', '2016-01-29', '2016-06-24', '6', 'Super deformed flash anime shorts. Half were streamed on Bandai’s official youtube page and half were bundled with the DVD/Blu-ray release of the main show.', 397, 'https://cdn.myanimelist.net/images/anime/12/76688.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kamisama Dolls Specials', 'Special', 6, 'Completed', '2011-09-21', '2012-02-22', '6', 'Short episodes included in the Kamisama Dolls Blu-ray and DVD volumes.', 143, 'https://cdn.myanimelist.net/images/anime/8/32717.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsuritama: Harikitte Contest', 'Special', 1, 'Completed', '2012-11-21', NULL, '6', 'Haru, Yuki, and the boys participate in a competition to decide who will be the next "Prince of the Sea from Endoshima." They just need to show their talents and impress the jury, but everything went in a wrong direction.', 14, 'https://cdn.myanimelist.net/images/anime/8/76239.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chikyuu wo Mitsumete', 'Movie', 1, 'Completed', '2011-01-01', NULL, '6', 'A movie by National Museum of Emerging Science and Innovation (Miraikan) screened at planetariums.', 607, 'https://cdn.myanimelist.net/images/anime/12/73734.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nippon-ichi no Otoko no Tamashii 2', 'TV', 16, 'Completed', '1999-05-04', '1999-05-28', '6', 'Sequel of Nippon-ichi no Otoko no Tamashii.', 879, 'https://cdn.myanimelist.net/images/anime/10/24639.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dr. Slump: Arale-chan Specials', 'Special', 2, 'Completed', '1981-10-07', NULL, '6', 'A special two-part episode that aired between episodes 24 and 25 of Dr. Slump: Arale-chan.', 1030, 'https://cdn.myanimelist.net/images/anime/13/68505.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('White Album 2 Picture Drama', 'Special', 2, 'Completed', '2014-05-28', NULL, '6', 'Two picture drama episodes included in the last Blu-ray volume of the TV series.', 780, 'https://cdn.myanimelist.net/images/anime/5/71047.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zakuro Yashiki', 'OVA', 1, 'Completed', '2006-08-01', NULL, '6', 'The Japanese painter FUKAZAWA Takeshi expresses in pictures the novel written by Honoré de BALZAC “La grenadière”. Over 70 tempera paintings are beautifully brought to life and put together by FUKADA Koji for this Ga-nime that tells us the story of a mother and child in the 19th century, coated in a music that punctuates the whole experience. FUKAZAWA and FUKADA thus succeed in reproducing the ambiance of this mansion so dear to BALZAC, as the artistic pictures call to the imagination and the emotions of the viewer that only be so aroused by a Ga-nime.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Futari no Oujisama', 'Movie', 1, 'Completed', '1996-07-12', NULL, '6', 'On the island of Jambe, Subarna, an introverted boy, is given a magic crown and, with the help of the crown, soon becomes the people''s hero known kind heartedness. This enrages Rupia, the island''s young prince, who has Subarna arrested.', 1030, 'https://cdn.myanimelist.net/images/anime/10/60321.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaibutsu-kun: Kaibutsu Land e no Shoutai', 'Movie', 1, 'Completed', '1981-03-14', NULL, '6', 'Based on the shounen manga by Fujiko Fujio.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chinzei Hachirou Tametomo', 'ONA', 1, 'Completed', '2020-12-10', NULL, '6', 'Kamimine Town, located in the eastern part of Saga Prefecture, is a place associated with the legendary military commander Minamoto no Tametomo, who is said to be "Yoshitsune in the east, Tametomo in the west."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Time Bokan 2000: Kaitou Kiramekiman', 'TV', 26, 'Completed', '2000-04-05', '2000-10-04', '6', 'More Time Bokan adventures.', 1009, 'https://cdn.myanimelist.net/images/anime/1773/132668.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Parol no Miraijima', 'Movie', 1, 'Completed', '2014-03-01', NULL, '6', 'Rikotto, Zuzu, and Paroru are intelligent furry creatures who believe more than anything that the world outside their island is too dangerous to explore. Despite this, Rikotto and Zuzu long to see the world that produces the mysterious objects that wash up on their shores. After a particularly exciting find, Rikotto convinces Zuzu to build a boat, and they set sail across the sea with their reluctant friend Paroru in tow.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Futari Daka', 'TV', 36, 'Completed', '1984-09-20', '1985-07-12', '6', 'Two motor-bike crazy young men meet on a track one day. One almost kills the other and after a while, they discover that they have the same first name. Since they are both excellent at racing, they very quickly become rivals ... but their passion and firstname is not the only thing they have in common.', 488, 'https://cdn.myanimelist.net/images/anime/2/59891.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The Supergal', 'OVA', 1, 'Completed', '1986-06-05', NULL, '6', 'Despite being a refugee from an extinct planet, having an alcoholic as a father and an airhead for a mother, Maris'' biggest problem is that she''s a Thanatosian. Considering that Thanatosians are six times stronger than the average Earthling it shouldn''t be such a curse, especially in a galaxy where violence is rife. But the accidental destruction she wreaks on everything she touches —even with the exotic alloy restraints she wears— means she''s constantly in debt. Every mission she''s assigned to by the Inter-Galactic Space Patrol becomes a cash-drain when all the damages are docked from her wage. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Taiko no Tatsujin', 'TV', 26, 'Completed', '2005-04-04', '2006-05-15', '6', 'A series of four minute claymation shows. Each episode shows the different antics of the various Taiko no Tatsujin characters.', 859, 'https://cdn.myanimelist.net/images/anime/12/6534.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fairy Ranmaru: Anata no Kokoro Otasuke Shimasu', 'TV', 12, 'Completed', '2021-04-08', '2021-06-24', '6', 'In a world where negative emotions fester, five fairies from the strongest clans are sent to Earth to collect "attachment" in order to sustain their world. The fairies establish Bar F and live their lives as normal high school boys and a barkeep in order to protect their true identities and fulfill their mission. The boys encounter various female clientele at Bar F, each hiding dark feelings within their hearts, and the boys offer to help them overcome their troubles. The only thing they ask for in return is the client''s permission to steal their heart.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Himitsukessha Taka no Tsume The Movie 3: http://takanotsume.jp wa Eien ni', 'Movie', 1, 'Completed', '2010-01-16', NULL, '5', 'The third Eagle Talon movie.', 214, 'https://cdn.myanimelist.net/images/anime/10/22016.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gegege no Kitarou: Youkai Japan Rally 3D', 'Movie', 1, 'Completed', '2008-07-12', NULL, '5', '', 1030, 'https://cdn.myanimelist.net/images/anime/13/68017.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sennin Buraku', 'TV', 23, 'Completed', '1963-09-04', '1964-02-23', '5', 'The ancient Chinese town of Taoyuan is populated exclusively by Taoist ascetics. The elder, Lao Shi, conducts research on magic and alchemy, while his pupil Zhi Huang is more interested in the pleasures of the flesh. He fell in love with three beautiful sisters who live close by.', 986, 'https://cdn.myanimelist.net/images/anime/2/78110.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Marie & Gali Special', 'Special', 1, 'Completed', '2009-06-02', NULL, '5', 'Special episode 9.5.', 1030, 'https://cdn.myanimelist.net/images/anime/12/15369.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oniku Daisuki! Zeushi-kun', 'TV', 12, 'Completed', '2014-01-06', '2014-03-24', '5', 'High above the clouds, meat-loving Zeushi-kun is the prince of ''Nikuniku Land''! He and his pal Minota think about meat every day! (Oh, they like veggies too.) Right now, they''re freeloading down on the surface with the Miito family so they can discover all sorts of tasty domestic meat products.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('OL Kaizou Kouza', 'OVA', 1, 'Completed', '1990-09-01', NULL, '5', 'Inspired by Drop Dead! Stupid Office Ladies, a column in Monthly Gendai magazine.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Baka Misérables', 'ONA', 3, 'Completed', '2013-05-21', '2013-06-28', '5', 'Baka Miserables follows the every day life of a family that goes into Les Misérables-style ballads for minor inconveniences or irks.', 214, 'https://cdn.myanimelist.net/images/anime/11/54813.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Field ni Soyogu Kaze', 'OVA', 1, 'Completed', '1997-07-25', NULL, '5', 'Trying to prove he is the better soccer player, Kenji tackles and injures Yuta''s leg during a trial for the school team. Impressed by the fact that Yuta still does what he can to contribute to the team; Kenji begins to realize the true meaning of sportsmanship.', 1030, 'https://cdn.myanimelist.net/images/anime/1628/112475.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lupin Shanshei', 'OVA', 10, 'Completed', '2012-12-19', NULL, '5', 'Series of 10 shorts parodying the popular classic anime Lupin III.', 990, 'https://cdn.myanimelist.net/images/anime/10/44261.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jikuu Tenshou Nazca', 'TV', 12, 'Completed', '1998-04-06', '1998-06-29', '5', 'Miura Kyoji, a dedicated kendo student, discovers that his shisho (master) Tate Masanari is a reincarnated Incan warrior named Yawaru who wishes to destroy the world to purify it. Kyoji himself is the warrior Bilka, who foiled Yawaru''s plans in their previous lives. Yawaru gathers other awakened spirits to release the powers of nature. Now Kyoji must wrestle with his own fate and decide if he is merely a vessel for the reincarnated soul or if he is truly Miura Kyoji and which will be better able to save the world and the future as he knows it. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mayoiga', 'TV', 12, 'Completed', '2016-04-01', '2016-06-17', '5', 'A bus full of eccentric individuals is headed toward the urban legend known as Nanaki Village, a place where one can supposedly start over and live a perfect life. While many have different ideas of why the village cannot be found on any map, or why even the police cannot pinpoint its location, they each look forward to their new lives and just what awaits them once they reach their destination.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mother: Saigo no Shoujo Eve', 'Movie', 1, 'Completed', '1993-12-26', NULL, '5', 'The future is bleak and urbanized. A government super-power holds the keys to all the doors. Hope lies in a secret organization who kidnaps "gifted" children and teaches them to wield their ability to view the life energy of all living things. A young girl befriends a sempai, a street rat comes to rescue her, and two parents wait helplessly to see their daughter one last time...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('UHA Mikakutou x One Piece', 'Special', 7, 'Completed', '2012-01-01', '2013-01-01', '5', 'Collaboration commercials between UHA Mikakutou and One Piece to promote their candy products.', 1030, 'https://cdn.myanimelist.net/images/anime/1095/145431.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xfit x One Piece', 'Special', 2, 'Completed', '2016-02-21', '2016-06-20', '5', 'Collaboration commercials between Xfit razors and One Piece to promote their specially branded packaging which included figurines of characters from the series.', 1030, 'https://cdn.myanimelist.net/images/anime/1234/145392.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Suisei no Freyline: Prologue', 'Special', 1, 'Completed', '2022-03-31', NULL, '5', 'The anime centers on Morita, a boy who is transported to another world and takes on the task of saving it by becoming an idol producer to fairies and demi-humans.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Shinka no Mi: Shiranai Uchi ni Kachigumi Jinsei', 'TV', 12, 'Completed', '2023-01-14', '2023-04-01', '5', 'Thanks to the Fruit of Evolution, Seiichi Hiiragi''s amazing new life in another world allows him to meet dependable allies and create formidable spells. His abilities catch the attention of Barnabus Ablitt, the principal of the Barbador Academy of Magic, who invites Seiichi to become a teacher at the institution. Coincidentally, Seiichi''s classmates from Earth are enrolled there, which will lead to an awkward reunion if he is to meet them.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zuihou de Fangxian', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'Ye Ran witnessed his mother''s tragic death and awakened a mysterious power, yet he was seen as an outcast. He grew up amidst the flames of war, gradually mastering the power of the Qilin bloodline, transforming into the colossal mech, becoming humanity''s last line of defense. However, the shadowy figures of his supposedly deceased loved ones reappear, and all the mysteries point to a deeper darkness beyond the walls.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('134 Yi Wang Ju', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'At the start of the new year, college student Chu Lan''s ordinary life ended abruptly. With his loved ones dead and a demon possessing him, he was drawn into a thousand-year struggle of fate. He became both the "only key" to end the disaster and the "vessel of evil" that could destroy humanity. Forced by destiny, he joined a secret agency to break the endless cycle of the Spirit Calamity. Ultimately, he faced a choice at the end of the battle between good and evil.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xibu de Tu Ke', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'Tuke is a spirit guardian exiled to the mortal realm. For centuries, he''s protected humanity with eight other spirit guardians. But the River God''s Son, who was sealed away by them, breaks free and takes control of seven spirit guardians'' souls, plotting to transform the world into a purgatory. To save his friends and defeat the River God''s Son, Tuke ventures all the way to the Son''s stronghold, where an epic battle ensues...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hai Ru Shenming', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'A tech giant corporation discovered an ancient time rift connecting higher-dimensional space. To monopolize energy, the tech giant concealed this discovery from the world. Its relentless exploitation eventually caused the temporal rift to go out of control, allowing non-Earthly spiritual energy to spread across the globe. Capitalizing on this upheaval, the giant accelerated its monopoly over the world. Gradually, more and more heroes capable of forging contracts with deities through spiritual energy united to oppose the evil forces intent on destroying humanity.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yi Ci Gui Ling', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'Xu Yichuan accidentally travels into a nightmarish realm and awakens the ability to regenerate. To escape this twisted dimension and return to his family, he gathers a group of partners to brave deadly games and unlock abilities. But it turns out that all this is a death trap conspired by the realm''s supreme overseer. In the end, Xu Yichuan and his companions manage to break through the overseer’s grip and keep looking for ways to escape.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chaoxinxing', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'The hero of the Star Federation, "Beidou", was framed as a traitor and imprisoned. A decade later, Yang Bei returned to clear his name, embarking on an adventure with the Federation President''s daughter to find allies. Ultimately, Yang Bei exposed the conspiracy and reclaimed his status as a star hero.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tianmu', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'The young Han Jin bore a future Dao embryo, wielded mystical powers, defeated nine dark realms, and overcame inner demons, forging a path to save humanity and defy fate.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Suo Yao Lu', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'College student Liu Ye accidentally entered a mysterious pawnshop, awakened his bloodline powers, and inherited the Mountain-Seeking Map. In rescuing a friend, he unlocked the map''s mysterious spells, gradually sensing ties from his past life with Bai Ze. The unusual abilities of Liu Ye drew the attention of the Supernatural Bureau, which sent the elite Lu Li to intervene under the pretext of "supervision." At the same time, the pawnshop heiress Lin Nianyu began pursuing him to seize the map, and the three formed separate demon-sealing teams with their own agendas.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shi Ren Huixiang', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'Lu Xiaobai, an ordinary high schooler, is suddenly attacked by "Xiao", a higher-dimensional envoy. On the brink of death, he awakens time-based powers and is rescued by his future self, "Cang". Taking up his late father''s mission, Lu Xiaobai takes over the leadership of the Bureau of Demon Defense, an organization dedicated to defending humanity. Together with Cang and new allies, he confronts a series of crises sparked by villains, ultimately drawing out and defeating them, reshaping the timeline, and saving humanity from a doomed future.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tai Qing', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', '', 827, 'https://cdn.myanimelist.net/images/anime/1037/152651.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yumemiru Alumi CMs', 'Special', 4, 'Completed', '2023-10-02', '2025-06-16', '5', 'Animated commercials for UACJ company produced by Studio 4°C.', 849, 'https://cdn.myanimelist.net/images/anime/1712/141732.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nintama Rantarou: 100% Yuuki! Dokutake Dejiro wo Yattsukero no Dan', 'Special', 1, 'Completed', '2022-05-04', NULL, '5', 'Rantarou, Kirimaru, Shinbei and the others were taking a walk when they found a beautiful field. Due to a sudden idea from the school principal, everyone at the Ninjutsu Academy decides to go on a field trip, not knowing it''s all part of the terrifying plan of the Dokutake ninjas.', 53, 'https://cdn.myanimelist.net/images/anime/1349/141775.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nintama Rantarou: Ninjutsu Gakuen Nyuugaku Annai no Dan', 'Special', 1, 'Completed', '2017-11-03', NULL, '5', 'People who wants to entroll into Ninjutsu Academy, gather now! Rantarou, Kirimaru, Shinbei and their friends present the glamor of Ninjutsu Academy as a commemoration of the 25th anniversary of the  Nintama Rantarou TV anime.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wo Kao Chongzhi Dang Wudi 2nd Season', 'ONA', 30, 'Completed', '2024-02-24', '2024-05-25', '5', 'Second season of Wo Kao Chongzhi Dang Wudi.', 978, 'https://cdn.myanimelist.net/images/anime/1124/141318.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eto Eto Setora', 'Special', 2, 'Completed', '2021-01-01', '2022-01-01', '5', 'The unique superstars of the zodiac have arrived aboard the "Eto Eto Setora."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oishiku Tsukurou! Puchipuchi Dance', 'Special', 1, 'Completed', '2015-12-31', NULL, '5', 'A story about a meerkat cook who comes to Eddie''s town.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seijuu Kirin Creative Relay', 'Special', 4, 'Completed', '2019-11-26', '2019-12-06', '5', 'Four short advertisements made for the Kirin Company.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jijia Yingxiong: Ji Dou Yongzhe', 'ONA', 4, 'Completed', '2019-08-16', '2019-09-27', '5', '', 341, 'https://cdn.myanimelist.net/images/anime/1196/129324.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wudang Hong Shaonian 2', 'TV', 26, 'Completed', '2016-01-01', NULL, '5', '', 4, 'https://cdn.myanimelist.net/images/anime/1085/129322.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wudang Hong Shaonian', 'TV', 26, 'Completed', '2014-12-23', NULL, '5', '', 4, 'https://cdn.myanimelist.net/images/anime/1952/129320.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsubasa: Tokyo Revelations', 'OVA', 3, 'Completed', '2007-11-16', '2008-03-17', '8', 'Continuing their journey from Record Country (the place that held the book of memories), Syaoran and company land into Tokyo Country, a blood-filled country under war from opposing factions for natural resources and survival. While reluctantly involved in the race to live, the group faces their own problems as certain revelations are made, changing their journey forever.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tenkuu no Shiro Laputa', 'Movie', 1, 'Completed', '1986-08-02', NULL, '8', 'In a world filled with planes and airships, Sheeta is a young girl who has been kidnapped by government agents who seek her mysterious crystal amulet. While trapped aboard an airship, she finds herself without hope—that is, until the ship is raided by pirates. Taking advantage of the ensuing confusion, Sheeta manages to flee from her captors. Upon her escape, she meets Pazu, a boy who dreams of reaching the fabled flying castle, Laputa. The two decide to embark on a journey together to discover this castle in the sky. However, they soon find the government agents back on their trail, as they too are trying to reach Laputa for their own greedy purposes.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dr. Stone', 'TV', 24, 'Completed', '2019-07-05', '2019-12-13', '8', 'After five years of harboring unspoken feelings, high-schooler Taiju Ooki is finally ready to confess his love to Yuzuriha Ogawa. Just when Taiju begins his confession however, a blinding green light strikes the Earth and petrifies mankind around the world—turning every single human into stone.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hotarubi no Mori e', 'Movie', 1, 'Completed', '2011-09-17', NULL, '8', 'During a summer vacation at her grandfather’s house, six-year-old Hotaru Takegawa gets lost in a forest rumored to be inhabited by spirits. While crying out in desperation, Hotaru is approached by Gin—a mysterious boy wearing a mask—who offers to help her.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dr. Stone: Science Future', 'TV', 12, 'Completed', '2025-01-09', '2025-03-27', '8', 'Having resolved the crisis in the Petrification Kingdom, Senkuu and his companions gear up to deal directly with the mastermind behind the petrification phenomenon—who supposedly resides on the moon. The ambitious spaceship project, however, requires immense manpower and critical resources scattered across the world. Thus, the Kingdom of Science exploration team kick-starts its transcontinental journey on the ship Perseus to gather them all.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka IV: Shin Shou - Yakusai-hen', 'TV', 11, 'Completed', '2023-01-07', '2023-03-18', '8', 'Second part of Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka IV.', 436, 'https://cdn.myanimelist.net/images/anime/1476/128693.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaijuu 8-gou', 'TV', 12, 'Completed', '2024-04-13', '2024-06-29', '8', 'After the destruction of their hometown, childhood friends Kafka Hibino and Mina Ashiro make a pact to become officers in the Defense Force—a militarized organization tasked with protecting Japan from colossal monsters known as "kaijuu." Decades later, the 32-year-old Kafka has all but given up on his dreams of heroism. Instead, he cleans up the remains of the slaughtered kaijuu after they are defeated by valiant soldiers—including Mina, who has successfully achieved their shared goal.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nodame Cantabile', 'TV', 23, 'Completed', '2007-01-12', '2007-06-15', '8', 'Shinichi Chiaki is a first class musician whose dream is to play among the elites in Europe. Coming from a distinguished family, he is an infamous perfectionist—not only is he highly critical of himself, but of others as well. The only thing stopping Shinichi from leaving for Europe is his fear of flying. As a result, he''s grounded in Japan.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tonari no Totoro', 'Movie', 1, 'Completed', '1988-04-16', NULL, '8', 'In 1950s Japan, Tatsuo Kusakabe relocates himself and his two daughters, Satsuki and Mei, to the countryside to be closer to their mother, who is hospitalized due to long-term illness. As the girls grow acquainted with rural life, Mei encounters a small, bunny-like creature in the yard one day. Chasing it into the forest, she finds "Totoro"—a giant, mystical forest spirit whom she soon befriends. Before long, Satsuki too meets Totoro, and the two girls suddenly find their lives filled with magical adventures in nature and fantastical creatures of the woods.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuroshitsuji Movie: Book of the Atlantic', 'Movie', 1, 'Completed', '2017-01-21', NULL, '8', 'The young Earl Ciel Phantomhive—the Queen''s Guard Dog—is once again called to investigate seemingly supernatural phenomena when news of miraculous resurrections begins to surface in Victorian London. Along with Sebastian Michaelis, his demon butler, they board the luxury cruise liner Campania to investigate rumors of the Aurora Society—a medical organization suspected of experimenting on the dead.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hajime no Ippo: Mashiba vs. Kimura', 'OVA', 1, 'Completed', '2003-09-05', NULL, '8', 'Tatsuya Kimura is beginning to feel left behind. With his friends Ippo Makunouchi and Mamoru Takamura holding the championship belt in their respective weight classes, Kimura''s inability to become Japan''s Junior Lightweight boxing champion eats away at him. Scheduled to fight with the current champion Ryo Mashiba, Kimura begins to train with Ippo''s rival Ichirou Miyata, who previously suffered a crushing defeat from Mashiba''s signature "Hitman" style of boxing.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hajime no Ippo: Champion Road', 'Special', 1, 'Completed', '2003-04-18', NULL, '8', 'The challenger has become the champion as Ippo Makunouchi now wears the featherweight championship belt of Japan. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Suzume no Tojimari', 'Movie', 1, 'Completed', '2022-11-11', NULL, '8', 'On her way to school one day, Suzume Iwato stumbles upon Souta Munakata, a young man searching for abandoned areas. The high school girl directs Souta to a nearby ruin, but out of pure curiosity, she herself decides to head to the same destination.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hunter x Hunter: Greed Island Final', 'OVA', 14, 'Completed', '2004-03-03', '2004-08-18', '8', 'Continuing with their adventure at Greed Island, Gon and Killua train furiously under the guidance of Biscuit for better preparation at attempting the game. With their abilities vastly improving and the threat of player killers menacing Greed Island, Gon and company continue the game despite the dangers that they will face with the game activities and encounters with other players. Based on the manga by Togashi Yoshihiro.', 607, 'https://cdn.myanimelist.net/images/anime/1/139.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wu Liuqi: Jiyi Suipian', 'ONA', 10, 'Completed', '2024-10-02', '2024-11-20', '8', 'In order to find his cherished partner, Wu Liuqi returns to Xuanwu Country and faces those forgotten fragments of memory. The dusty truth brings pain and anger, but now he is no longer alone. What is the purpose of having power? This time, Wu Liuqi has to make a new choice for his life...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mononoke Movie 2: Hinezumi', 'Movie', 1, 'Completed', '2025-03-14', NULL, '8', 'One month after the Karakasa incident, the situation at the Inner Chambers is slowly returning to normal. To the noble families that run the country, normalcy means carrying on with their usual schemes to prevent any undesirable power shifts in the government. Their current target is the high-ranking concubine Fuki Tokita, who seems to be receiving Lord Tenshi''s attention despite being the daughter of a merchant and, therefore, socially unfit to give him an heir.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wu Liuqi: Anying Suming', 'ONA', 10, 'Completed', '2023-01-18', '2023-03-15', '8', 'The protagonist Wu Liuqi originally lived a carefree life on Xiaoji Island, but his identity became a mystery due to amnesia. As outsiders landed on the island and recognized Wu Liuqi, various conspiracies began to cover Xiaoji Island. So Wu Liuqi decided to return to Xuanwu Kingdom to meet his destiny in order to protect his partners and their homeland. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shen Yin Wangzuo 2nd Season', 'ONA', NULL, 'Airing', '2022-11-10', NULL, '8', 'Revealing himself to be a Dual Knight, Long Hao Chen triumphs in his match within his temple and advances to the finals. But before the grand finals can begin, ranking matches are conducted in each temple to determine the strongest within. During the rankings, Hao Chen is injured, enraging Sheng Cai''er and driving her to seek vengeance for what happened to him. Her actions cause a fight between the Knight Temple and Assassin Temple, only to be subdued after a shocking revelation—that Sheng Cai''er is a Reincarnated Saint.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Golden Kamuy 2nd Season', 'TV', 12, 'Completed', '2018-10-08', '2018-12-24', '8', 'In Hokkaido, it is rumored that there is a stash of hidden gold. This gold was supposedly stolen by a man who killed the original Ainu owners; and before being captured and imprisoned by the police, he hid it in a secret location. In order to relay the gold''s location to his comrades on the outside, he tattooed the map on the bodies of his cellmates and promised them a share of the gold—provided they managed to escape and find it.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gyakkyou Burai Kaiji: Hakairoku-hen', 'TV', 26, 'Completed', '2011-04-06', '2011-09-28', '8', 'Owing to an increasing debt, Kaiji Itou ends up resuming his old lifestyle. One day, while walking on the street, he stumbles upon Yuuji Endou, who is hunting Kaiji due to the money he owes to the Teiai Group. Unaware of this, Kaiji eagerly follows Endou, hoping for a chance to participate in another gamble, but soon finds out the loan shark''s real intentions when he is kidnapped.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kamisama Hajimemashita◎', 'TV', 12, 'Completed', '2015-01-06', '2015-03-31', '8', 'Nanami Momozono and her familiars Tomoe and Mizuki have survived quite a few challenges since Nanami took up the mantle of Mikage Shrine''s patron god. Naturally, the wind god Otohiko comes to invite Nanami to the Divine Assembly in Izumo, the home of the gods, and Nanami chooses to take Mizuki with her, leaving Tomoe to pose as her at school. However, she has an ulterior motive for attending the Divine Assembly: to discover the whereabouts of the missing Lord Mikage, the former god of the shrine. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shinsekai yori', 'TV', 25, 'Completed', '2012-09-29', '2013-03-23', '8', 'In the year 2011, a small percentage of humans began manifesting psychokinetic abilities known as "Cantus." Over a millennium later, in the small town of Kamisu 66, Saki Watanabe is the last of her friends to awaken her powers and join the Sage Academy, a school for psychics like her. Although everyone at the institution has Cantus, they are not all equal; shortly after Saki enrolls, one of her classmates who is regarded as being weaker than the others suddenly disappears.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Stranger: Mukou Hadan', 'Movie', 1, 'Completed', '2007-09-29', NULL, '8', 'In the Sengoku period of Japan, a young orphan named Kotarou and his dog Tobimaru steal from unsuspecting villagers in order to make ends meet. However, Kotarou is forced to remain on the run when he finds himself being hunted down by assassins sent by China''s Ming Dynasty for mysterious reasons not involving his petty crimes. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('World Trigger 3rd Season', 'TV', 14, 'Completed', '2021-10-10', '2022-01-23', '8', 'At the Border Defense Agency''s headquarters, the B-Rank Wars are underway as each team fights intensely to secure a spot in the upcoming Away Mission. Though Osamu Mikumo and the rest of Tamakoma-2 have pulled through thus far, the final rounds will require them to push far beyond the limits of their current abilities. Taking in a talented new member, the squad begins to train and develop new strategies, but, amid these efforts, the team is shaken by a heated dispute—one that could jeopardize their ticket to the Neighbor''s dimension.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kono Subarashii Sekai ni Shukufuku wo! 2', 'TV', 10, 'Completed', '2017-01-12', '2017-03-16', '8', 'When Kazuma Satou died, he was given two choices: pass on to heaven or be revived in a fantasy world. After choosing the new world, the goddess Aqua tasked him with defeating the Demon King, and let him choose any weapon to aid him. Unfortunately, Kazuma chose to bring Aqua herself and has regretted the decision ever since then.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyou kara Maou!', 'TV', 78, 'Completed', '2004-04-03', '2006-02-25', '8', 'Kyou kara Maou! revolves around Yuri Shibuya, your average Japanese teenager. One day, Yuri sees a classmate being harassed by bullies. Thanks to this intervention, his friend is able to escape, but unfortunately Yuri becomes the new target of the bullies in the process and gets his head shoved into a toilet. But instead of water, the toilet contains a swirling portal that sucks him into another world, largely resembling medieval Europe. There, he is told that he will become the next Demon King due to his black hair and black eyes, traits only possessed by the demon''s royal lineage.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('R.O.D: Read or Die', 'OVA', 3, 'Completed', '2001-05-23', '2002-02-06', '8', 'Yomiko Readman is a lovable, near-sighted bibliomaniac working as a substitute teacher at a Japanese high school. Her real identity, however, is that of a secret agent for the British Library Special Operations Division. Her codename: "The Paper." The moniker denotes her supernatural ability to freely manipulate paper into any object she can imagine, including tools and weapons in her fight against the powerful and self-serving IJIN (Great Historical Figure) Army! Along with her partner, the enigmatic "Ms. Deep," Yomiko travels across the world in attempt to solve the mystery behind the reincarnation of historical figures and their attempt to control the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Master Keaton', 'TV', 24, 'Completed', '1998-10-06', '1999-03-30', '8', 'The amazing Taichi Keaton works on cases around the globe that always lead to adventure! He combines his arsenal of multidisciplinary expertise in investigation, archeology, and survival with his experience as a professor, a Falklands Conflict veteran and a SAS agent to unravel the often dangerous challenges in each riveting episode.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fate/Grand Order: Shinsei Entaku Ryouiki Camelot 2 - Paladin; Agateram', 'Movie', 1, 'Completed', '2021-05-15', NULL, '8', '"This time for sure, I will kill my king with my own hands..."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Free! Eternal Summer', 'TV', 13, 'Completed', '2014-07-03', '2014-09-25', '8', 'Even though it has been a year since the Iwatobi High School Swim Club has been created, new members have yet to join the club. Now that Haruka Nanase and Makoto Tachibana are senior students, along with their younger friends Nagisa Hazuki and Rei Ryuugazaki, they have to find a way to attract new members. If not, the club will be forced to close the following year due to a lack of membership.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sekaiichi Hatsukoi', 'TV', 12, 'Completed', '2011-04-09', '2011-06-25', '8', 'After having to deal with jealousy from his co-workers for working under his father''s name, prideful literary editor Ritsu Onodera is determined to establish himself in the industry. To accomplish this, he quits his job at his father''s publishing company and transfers to Marukawa Publishing. But instead of being placed in their literary division, Ritsu finds himself working as the rookie manga editor for the Emerald editing department, a team that operates under extremely tight schedules in order to meet deadlines. There, Ritsu is introduced to the infamous editor-in-chief Masamune Takano, a persistent man who strives for results.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koyomimonogatari', 'ONA', 12, 'Completed', '2016-01-10', '2016-03-27', '8', 'Whether it is investigating stone shrines, tracking rumors, or simply playing hide and seek, Koyomi Araragi is always there to fulfill the requests of his friends from both the human and supernatural worlds. In this series of short stories, Koyomi helps each of the girls in his cohort solve a mystery or kill some time, all while slowly unraveling the truth about his town and its many supernatural occurrences.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Vigilante: Boku no Hero Academia Illegals', 'TV', 13, 'Completed', '2025-04-07', '2025-06-30', '8', 'In a world filled with superpowered Quirk users, college student Kouichi Haimawari''s dream is to become a hero just like the ones he so admires. Unfortunately for him, he finds out that there is only so much he can do with a sliding ability that gives him about as much speed as a bicycle. Thus, he is drawn to extra-legal, simpler work and takes on various local tasks beyond the grasp of the police and licensed heroes.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Karaoke Iko!', 'TV', 5, 'Completed', '2025-07-24', '2025-09-25', '8', 'Middle school student Satomi Oka ought to be proud that his choir group placed second at a national competition. However, he views this achievement as a failure caused by his inadequacies. Furthermore, since graduation is fast approaching, his time as leader of the choir is coming to an end. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doraemon Movie 44: Nobita no E Sekai Monogatari', 'Movie', 1, 'Completed', '2025-03-07', NULL, '8', '', 802, 'https://cdn.myanimelist.net/images/anime/1143/146877.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Feng Ling Yu Xiu 2nd Season', 'ONA', 12, 'Completed', '2023-07-02', '2023-09-10', '8', '', 972, 'https://cdn.myanimelist.net/images/anime/1634/136523.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimi no Iro', 'Movie', 1, 'Completed', '2024-08-30', NULL, '8', 'Totsuko is a high school student with the ability to see the "colors" of others. Colors of bliss, excitement, and serenity, plus a color she treasures as her favorite. Kimi, a classmate at her school, gives off the most beautiful color of all. Although she does not play an instrument, Totsuko forms a band with Kimi and Rui, a quiet music enthusiast they meet at a used bookstore in a far corner of town. As they practice at an old church on a remote island, music brings them together, forming friendships and stirring affections. Will they discover their true "colors"?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hirano to Kagiura', 'Movie', 1, 'Completed', '2023-02-17', NULL, '8', 'The diligent high school freshman Akira Kagiura and his senior Taiga Hirano have been roommates for half a year. Kagiura used to be anxious about his future dormitory life, but thanks to his energetic senior looking out for him, he has come to feel content and at ease. As he continues to rely on Hirano more and more each day, he develops strong feelings for his selfless friend. In the six months they have left as roommates, Kagiura is determined to put a name to the relationship he cherishes so dearly before it comes to an end. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Persona 3 the Movie 3: Falling Down', 'Movie', 1, 'Completed', '2015-04-04', NULL, '8', 'As the fall season nears its end, Chidori Yoshino, a member of Strega, abducts Junpei Iori. Meanwhile, Makoto Yuuki and the Specialized Extracurricular Execution Squad (SEES) annihilate the Arcana Hanged Man. Soon after, a mysterious playboy named Ryouji Mochizuki transfers into Gekkoukan High School''s Class 2-F.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('K: Seven Stories Movie 5 - Memory of Red - Burn', 'Movie', 1, 'Completed', '2018-11-03', NULL, '8', 'It is the beginning of December. Anna Kushina''s birthday is coming up, so the boys of HOMRA decide to celebrate by preparing a surprise party for their little princess.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nurarihyon no Mago', 'TV', 24, 'Completed', '2010-07-06', '2010-12-21', '8', 'Rikuo Nura, a part-youkai and part-human boy, grew up as the young master of the Nura Clan. While he treated the clan, which consists of youkai of all shapes and sizes, like family, he soon learned that he was the only one among his classmates who saw youkai in this light. To most, they were terrifying creatures of folklore who ate children and relished in bloodshed. Taking this to heart, he swore to live his life as a normal human.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doraemon Movie 40: Nobita no Shin Kyouryuu', 'Movie', 1, 'Completed', '2020-08-07', NULL, '8', 'Nobita and the gang travel 66 million years into the past to bring a pair of adorable dinosaur twins back to where they belong.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Huyao Xiao Hongniang 3: Yue Hong Pian', 'ONA', 13, 'Completed', '2016-06-24', '2016-09-16', '8', 'Third season of Huyao Xiao Hongniang.', 369, 'https://cdn.myanimelist.net/images/anime/1404/153689.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jigoku Shoujo Mitsuganae', 'TV', 26, 'Completed', '2008-10-04', '2009-04-04', '8', 'Following the events of Jigoku Shoujo Futakomori, Ai Enma, the Hell Girl, has disappeared. Her former companions decide to lead normal lives, until their absent mistress returns to them with a new companion, and in a way that none of them anticipated.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Soukyuu no Fafner: Dead Aggressor - Exodus Part 2', 'TV', 13, 'Completed', '2015-10-03', '2015-12-26', '8', 'Continuation of Soukyuu no Fafner: Dead Aggressor - Exodus.', 400, 'https://cdn.myanimelist.net/images/anime/7/76538.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Candy Candy', 'TV', 115, 'Completed', '1976-10-01', '1979-02-02', '8', 'This story is about a girl, Candy, who is an orphan. She is a nice and optimistic girl and she has a warm heart. When she was a child, she lived in an orphanage called Pony''s Home. She had a good friend called Annie. And she met the "Prince of the Hill" who is a important person in her life, on the hill behind the orphanage.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fanren Xiu Xian Chuan: Yan Jia Bao Dazhan', 'ONA', 4, 'Completed', '2021-01-31', '2021-02-14', '8', 'The special episode picks up right after the first season, telling the story of Han Li''s series of adventures in Yan Family Fortress after he discovers the full-scale invasion of the demonic path. Mysterious demonic spies, Dong Xuan''er, a "blind date" arranged by his sect, and Mo Caihuan, the long-lost daughter of the Mo Master, Han Li cautiously steps into an extremely dangerous and perilous situation, navigating seemingly comical and chaotic battlefields.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hakkenden: Touhou Hakken Ibun 2nd Season', 'TV', 13, 'Completed', '2013-07-07', '2013-09-29', '8', 'The journey to find all eight sacred gems continues, as Sousuke and Shino travel in search of the remaining gem holders. From the shadows the Imperial Church continues to scheme, and a mysterious woman seeks to fulfill a sinister plot with the gem holders at its heart. As the origin of the gems comes to light, so does the truth behind Sousuke''s doppelganger, Ao, as he resurfaces with his own goal—one involving Sousuke and his gem!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimitachi wa Dou Ikiru ka', 'Movie', 1, 'Completed', '2023-07-14', NULL, '8', 'Three years into the war, Mahito Maki loses his mother in a tragic fire at the hospital. Shortly thereafter, his father marries Natsuko, the younger sister of Mahito''s mother. They take Mahito out of Tokyo to seek refuge in his late mother''s rural family home. There, Mahito is constantly taunted by a strange gray heron, who seems to have taken an interest in him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mutafukaz', 'Movie', 1, 'Completed', '2018-10-12', NULL, '7', 'After a scooter accident provoked by a mysterious woman''s vision, Angelino, a deadbeat like thousands of others in Dark Meat City, starts getting violent migraines that are accompanied by strange hallucinations. Along with his good buddy Vinz, he tries to figure out what''s happening to him while threatening men in black seem determined to catch him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece: Yume no Soccer Ou!', 'Movie', 1, 'Completed', '2002-03-02', NULL, '7', 'Luffy and his crew take on the Villain All-Stars in a game of soccer in order to become the Dream Soccer King. The game comes down to a pk tie-breaker shoot-out with Coby as goalie and Helmeppo refereeing.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ranma ½: Nettou Uta Gassen', 'OVA', 2, 'Completed', '1990-11-07', '1990-11-21', '7', 'A two-part music OVA series never released outside of Japan featuring the main Ranma 1/2 characters. They appear to be having a music contest at a local TV station. As everybody knows, these characters can''t get along for more than three minutes and hilarity and hijinks ensue. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aoi Hana', 'TV', 11, 'Completed', '2009-07-02', '2009-09-10', '7', 'Shy and soft-spoken Fumi Manjoume and upfront and caring Akira Okudaira were best friends in elementary school, but this changed when Fumi and her family moved away. Years later, Fumi moves back to her hometown after being accepted at Matsuoka Girls’ High School. She finally reunites with Akira, who is going to attend Fujigatani Girls’ Academy. Despite their reunion, their relationship isn''t the same as it was years ago.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyoushoku Soukou Guyver (1989)', 'OVA', 6, 'Completed', '1989-09-25', '1990-02-25', '7', 'Shou and his friend, Tetsurou, stumble upon a strange orb-like mechanism, the Guyver Unit, in the woods. It physically bonds with Shou and turns him into the alien soldier, Guyver. His mission is to protect the Guyver Unit from the Japanese corporation known as Chronos. They are after it and two other units just like it. To retrieve the object, they send out vicious monsters known as Zoanoids. So no one is safe in Shou''s life; not even himself.', 1087, 'https://cdn.myanimelist.net/images/anime/7/13102.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon: Mewtwo! Ware wa Koko ni Ari', 'Special', 1, 'Completed', '2000-12-30', NULL, '7', 'The Team Rocket leader, Giovanni, has found Mewtwo in a remote area of the Johto region. As Giovanni tries to re-capture Mewtwo, Ash and his friends are kidnapped by Domino, a new Team Rocket member, while trying to rescue Pikachu from Jessie and James. The Clone Pokemon are also captured and are then used as bait for Mewtwo. The situation then becomes a battle between the wills of Mewtwo and Giovanni; and Mewtwo also tries to discover if it and the clones have a purpose in life, even though they are products of science.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Offside (TV)', 'TV', 39, 'Completed', '2001-05-10', '2002-01-31', '7', 'Goro Kumagaya is an established, tall middle-school goalkeeper who wanted to enter Yokonan high-school that is considered to be among the elites in terms of its football club, only to fail and end up in the lowly-ranked school opposite to Yokonan because of an accident. However, he met Shingo, Hideki and Kazuhito Oda who are all skillful footballers there and together in the Kawasaki High School football club, they challenge Yokonan and any other schools that they have to face in order to improve and become the champions. Any setbacks that they face would instead be an opportunity for a better improvement; one of which was the discovery of Goro''s natural talent as an ace striker. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yoake Mae yori Ruriiro na: Crescent Love', 'TV', 12, 'Completed', '2006-10-05', '2006-12-21', '7', 'The moon and the earth are linked by a single contact point, "Mitsuru ga Sakichau Ouren Rakuniushi" where Tatsuya lives under the supervision of the Sphere Kingdom (Moon Kingdom)''s Princess Feena Fam Earthlight who is coming to stay at his home.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hakuouki: Reimeiroku OVA', 'OVA', 2, 'Completed', '2013-05-22', NULL, '7', '2 eps. Tokuten that were released in a Tokuten Disc for those who purchased all 6 volumes of Hakuouki Reimeiroku OVAs.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mangaka-san to Assistant-san to The Animation', 'TV', 12, 'Completed', '2014-04-08', '2014-06-24', '7', 'Yuuki Aito is a perverted manga artist who appreciates panties, wishing to draw as many as he can. Being surrounded by numerous female assistants, he is constantly asking to use them as references for the manga he draws.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hatenkou Yuugi', 'TV', 10, 'Completed', '2008-01-05', '2008-03-08', '7', '"See the world"
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chibi Maruko-chan Movie', 'Movie', 1, 'Completed', '1990-12-15', NULL, '7', 'Chibi Maruko chan is the nickname of a sweetly obnoxious 9-year-old girl. She tricks her grandfather, ponders for hours over how to spend her allowance, and hates sitting next to ugly boys. She talks, feels and lives just as real kids do.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuzu no Honkai', 'TV', 12, 'Completed', '2017-01-13', '2017-03-31', '7', 'To the outside world, Hanabi Yasuraoka and Mugi Awaya are the perfect couple. But in reality, they just share the same secret pain: they are both in love with other people they cannot be with. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsurikichi Sanpei', 'TV', 109, 'Completed', '1980-04-07', '1982-06-28', '7', 'Mihira Sanpei talks with a Tohou accent and is a down-to-earth boy with a cheerful and optimistic personality. However, when it comes to fishing, he becomes very serious and is a youth who enjoys fishing more than anything else. The village where he lives in is a natural environment which provides different kinds of fishing challenges. Despite his lack of experience, Sanpei has a first-rate sense with regards to fishing and decides to maxmise his potential by entering into different fishing contests. As he faces various challenges, he learns to solve difficult problems and learn from his mistakes to the extent that he is able to fish anything out of the waters. Along the way, he encounters all kinds of rivals and companions who increase his experience points and help him in his growth.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Ball Z Movie 05: Tobikkiri no Saikyou tai Saikyou', 'Movie', 1, 'Completed', '1991-07-20', NULL, '7', 'Gokuu Son and his friends are out camping when three mysterious enemies ambush them. After a quick fight, a fourth enemy named Cooler joins the fray. Seeking retribution for his younger brother Frieza after he was defeated, Cooler attacks Gokuu; however, the latter manages to escape with Gohan Son and goes into hiding. Unsatisfied and infuriated with the outcome, Cooler and his men begin the hunt to uncover Gokuu''s location and kill him to carry out their plans of exacting revenge.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hokuto no Ken: Yuria-den', 'OVA', 1, 'Completed', '2007-02-23', NULL, '7', 'The second part of the new Hokuto no Ken pentalogy. The story of this OVA centers around Yuria.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Penguin''s Memory: Shiawase Monogatari', 'Movie', 1, 'Completed', '1985-06-22', NULL, '7', 'Mike is a penguin soldier who returns home after being injured during combat. Estranged from his family and friends, he leaves his hometown and starts to roam adrift through the country.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kochira Katsushikaku Kameari Kouenmae Hashutsujo The Movie', 'Movie', 1, 'Completed', '1999-12-23', NULL, '7', 'The wicked multi-billionaire, Shinatora, builds wretched, ugly buildings. The explosives genius calling himself Benten has targeted Shinatora''s empire and begins to destroy the monstrosities that are wiping out whole sections of downtown Tokyo. In cooperation with the local police force, the FBI has sent Lisa Hoshino, a bomb disposal expert, and her robot assistant, Dandy, on a lecture tour of Japan. Ryotsu is reluctantly paired with Lisa to protect the people of the Kameari district. Why does Benten only target Shinatora''s buildings? What is his next target?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mou Ippon!', 'TV', 13, 'Completed', '2023-01-09', '2023-04-03', '7', 'The happy-go-lucky Michi Sonoda announces to her teammate, Sanae Takigawa, that she will quit judo for good after her final middle school tournament. This leaves Sanae in disbelief; after all, it was Michi''s passion toward the sport that reeled Sanae into judo in the first place. Michi claims that a well-spent youth should be associated with things such as getting a boyfriend rather than sweaty tatami mats.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bubblegum Crisis Tokyo 2040', 'TV', 26, 'Completed', '1998-10-08', '1999-04-01', '7', 'In the wake of an earthquake that devastated most of the city, Tokyo has been rebuilt in record time due to the development of humanoid robots known as boomers. After the disaster, these machines now service the city as cheap labor. Genom Corporation is the mastermind behind the boomers, having become so rich and powerful that they have extended its influence into space.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Space Adventure Cobra', 'Movie', 1, 'Completed', '1982-07-03', NULL, '7', 'While enjoying a drink at a bar, a beautiful yet intimidating woman catches the eye of Cobra, an infamous outlaw with a powerful gun fused to his left arm. This woman, Jane Royal, has also caught the eye of the Pirate Guild, a dangerous organization led by the enigmatic Crystal Bowie. As Cobra helps Jane escape the Pirate Guild and find her missing sisters, he discovers that she might just hold the fate of the galaxy in her hands.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Unico: Mahou no Shima e', 'Movie', 1, 'Completed', '1983-07-16', NULL, '7', 'Based on "Unico and the Kingdom of the Sun," which was newly written as a theater version, this animated film features a battle between the wizard Kukuruku and Unico. Kukuruku builds a castle using dolls transformed from men as building parts. The story revolves around the sorrow and terror of men who have been transfigured into dolls, and a girl named Cherry who wishes to recover the kindness in her brother, who is a student of Kukuruku. This work reminds us of the fact that "transformation" or "transfiguration" - favorite themes of Tezuka Osamu - involves not only material aspects, but also man''s immaterial heart.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka Gaiden: Sword Oratoria', 'TV', 12, 'Completed', '2017-04-15', '2017-07-01', '7', 'After having descended upon this world, the gods have created guilds where adventurers can test their mettle. These guilds, known as "familia," grant adventurers the chance to explore, gather, hunt, or simply enjoy themselves.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchi no Ko no Tame naraba, Ore wa Moshikashitara Maou mo Taoseru kamo Shirenai.', 'TV', 12, 'Completed', '2019-07-04', '2019-09-19', '7', 'Eighteen-year-old Dale Reki is a skilled, kind, and respected traveler, acknowledged as one of the leading adventurers in the city of Kreuz. One day while on the hunt for magical beasts, he comes across a sweet devil girl named Latina. She is alone, dressed in rags, and bears the devils'' symbol of a criminal: a broken horn. Concerned for her wellbeing, Dale decides to ensure Latina''s safety by bringing her to his home, eventually leading to him adopting her.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Digimon Frontier: Ornismon Fukkatsu!!', 'Movie', 1, 'Completed', '2002-07-20', NULL, '7', 'The five digi-destined children stumble upon an ancient island inhabited by two different types of digimon; The Beast types, and the Human types. When they see two young digimon-a beast and humanoid-have become friends, they decide something must be done about the feud.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jigoku Sensei Nube: Gozen 0 Ji Nube Shisu!', 'Movie', 1, 'Completed', '1997-03-08', NULL, '7', 'New student comes to Nube class. His name is Jun and he''s a lonely boy who loves clowns very much. His only friend is a Pierre - clown in the mirror. And one night Pierre gives Jun a mask with strange abilities. At that point Jun starts to act strange and lot of accidents occur in the school.', 1030, 'https://cdn.myanimelist.net/images/anime/1140/148921.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('B-gata H-kei', 'TV', 12, 'Completed', '2010-04-02', '2010-06-18', '7', 'Most people, including the girl herself, would say that first year high school student Yamada is beautiful and perfect. Despite this, she is working towards a peculiar goal: to have sex with one hundred men by the end of high school.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokonyan!', 'TV', 170, 'Completed', '1993-04-05', '1996-03-29', '7', 'Rocky Rackat (Pokonyan) is a funny little creature that''s a bit of a cross between a cat and a raccoon. There are rumors that he may be a lunar cat, however this is not a documented fact, he may be a bit looney at times, yet his origin remains a mystery.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jue Shi Wu Hun', 'ONA', 440, 'Completed', '2020-10-25', '2024-12-11', '7', 'In the continent of Longmai, thousands of clans stand tall, countless sects exist, and cultivation is the way of life. The strong can do anything they want while the weaklings live like ants. Youngster Chen Feng has an incomplete dan region, causing him to be unable to cultivate, he withstood countless sneers directed at him. Until he obtained a mysterious dragon bloodline, breaking out of his cocoon and opening a new chapter to his life! Coquettish demonic fox spirits, cold female emperors, demon girls or princesses from a prestigious clan, all of them jump into my embrace. With the unparalleled inheritance, I will manifest the strongest martial spirit, obtain all the beauties and look down from the heavens.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Majimoji Rurumo', 'TV', 12, 'Completed', '2014-07-09', '2014-09-24', '7', 'After an unfortunate accident, completely normal heterosexual high school student Kouta Shibaki is branded as the school pervert. With girls avoiding Kouta like the plague, truly the young man''s worst nightmare has come to fruition! One day in the school library, he stumbles upon a peculiar book said to possess the power to summon witches. Partly out of desperation, partly out of boredom, Kouta decides to play along with the joke of a book, until an apprentice witch going by the name of Rurumo Maji Mojiruka appears before him. In an unusual turn of events, Kouta ends up helping Rurumo with some general witchery tasks in exchange for his soul being spared.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Clamp Gakuen Tanteidan', 'TV', 26, 'Completed', '1997-05-03', '1997-10-25', '7', 'The CLAMP school, with its integrated curriculum from kindergarten to post-graduate studies, was founded by the largest of Japanese business empires, the House of Imonoyama. Funded entirely out of its own deep pockets, it was hoped that the school would be a haven for young men and women on whose shoulders our future would rest.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon: Pikachu no Natsuyasumi', 'Movie', 1, 'Completed', '1998-07-18', NULL, '7', 'Satoshi, Kasumi, and Takeshi surprise their Pokémon with a summertime retreat at a resort called Pokémon Plaza, where Pokémon of all types can relax and have fun outside their Poké Balls.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Goal FH: Field Hunter', 'TV', 39, 'Completed', '1994-04-04', '1994-12-26', '7', 'The story is about Hikaru Tatsumura who came from Brazil to fulfill his dream to be a great soccer player because he met a great player once who was admired by all people. However Tatsumura is a very cheerful person  and easy going except when it is about soccer. He becomes serious and strong. He also gives a unique performance such as doing a funny dance with his buddy after he makes a goal. Tatsumura will face a lot of challenges with his team while aiming for success.', 414, 'https://cdn.myanimelist.net/images/anime/8/61767.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ikkyuu-san', 'TV', 296, 'Completed', '1975-10-15', '1982-06-28', '7', 'Ikkyu is a little boy training to be a monk at Ankokuji Temple. Known for being mischievous and a bit of a troublemaker, but also extremely smart, Ikkyu constantly thinks of new ways to outwit his frustrated teachers, helping others at the same time.', 1030, 'https://cdn.myanimelist.net/images/anime/6/60917.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Daitoshokan no Hitsujikai', 'TV', 12, 'Completed', '2014-10-09', '2014-12-25', '7', '"The Shepherd," an urban legend of Shiomi Academy, is said to appear before hardworking students to grant them a wish. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jewelpet Happiness', 'TV', 52, 'Completed', '2013-04-06', '2014-03-29', '7', 'The series focuses on the main heroine Chiari Tsukikage and her friends on managing the Jewelpet Cafe. One day at the magical world of Jewel Land, Lady Jewelina entrusted Ruby the Magical Jewel Box with a mission to make friends and collect Magic Jewels. At the same time she needs to attend the Jewel Academy to do so and open a shop called the Jewelpet Cafe. However with her friends, things didn''t go well as planned with several failed mishaps happened to her and the students being scared, in the point of Ruby giving up. But when she met a young girl named Chiari Tsukikage and decides to help, Ruby''s life is about to change forever. Now, she and her friends now must work together for the cafe to prosper, stick together through good and bad luck as well as protecting the Jewel Box from being stolen.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Ball Z Movie 07: Kyokugen Battle!! Sandai Super Saiyajin', 'Movie', 1, 'Completed', '1992-07-11', NULL, '7', 'Dr. Gero''s Androids #13, #14, and #15 are awakened by the laboratory computers and immediately head to the mall where Goku is shopping. It is up to Goku and his friends to defeat them.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Devil Survivor 2 The Animation', 'TV', 13, 'Completed', '2013-04-05', '2013-06-28', '7', 'The countdown to extinction begins on Sunday with the arrival of the Septentriones, otherworldly invaders set on the eradication of mankind. Caught in the crossfire, Hibiki Kuze and his friends join in the war for humanity''s survival by signing contracts with demons to become "Devil Summoners." Soon, their abilities attract the attention of JP''s, an underground agency led by Yamato Houtsuin. Once recruited into JP''s, Hibiki and his friends fight and bond alongside other ordinary citizens who are Devil Summoners. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Iblard Jikan', 'OVA', 1, 'Completed', '2007-07-04', NULL, '7', 'Much like looking through a window, Iblard Jikan explores the fantastic and beautiful world of Iblard by panning through art created by Naohisa Inoue. Iblard shows itself to be nothing short of amazing and will wash serenity over your mind.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yaku nara Mug Cup mo: Niban Gama', 'TV', 12, 'Completed', '2021-10-02', '2021-12-18', '7', 'The conclusion of the Mino ware contest has spurred Himeno Toyokawa to create a piece even more remarkable than the last. Anxious to embrace the future yet emboldened by her mother''s legacy, Himeno strives to find the right inspiration—a task that proves to be just as ambitious as her goal. When Himeno''s father suggests that her next creation should be the centerpiece at the cafe, expectations for the final product only grow with each passing day.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Anime 80-nichikan Sekai Isshuu', 'TV', 26, 'Completed', '1984-01-08', '1984-07-15', '7', 'Willy Fog accepts a bet from members of the Reform Club that he can make it around the world in 80 days. His plan, however, does not include being stopped by unknown enemies.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Crayon Shin-chan Movie 15: Arashi wo Yobu Utau Ketsu dake Bakudan!', 'Movie', 1, 'Completed', '2007-04-21', NULL, '7', 'A slapstick comedy on a bomb uproar, and a touching story about the ties between the Nohara Family and their dog Shiro. A film in the musical style including the scenes with inserted songs. When the Nohara Family enjoy a trip to Okinawa, a strange object like a flying saucer becomes stuck with Shiro''s bottom. That is a special bomb dropped by "The Only Buttocks Aliens," and it has the power to destroy the whole earth. The space monitoring center "UNTI" (Unidentified Nature Team Inspection) begins to pick up the bomb, but a female terrorist group "Hinageshi Opera Company" tries to get the bomb and disturbs UNTI''s work.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Captain Tsubasa: Sekai Daikessen!! Jr. World Cup', 'Movie', 1, 'Completed', '1986-07-12', NULL, '7', 'In the fourth movie, the classical Japan-Europe match becomes intercontinental. This time they arrange a world cup with 4 teams: Japan, USA, "All Europe", and "All South America". In the first match, Japan easily defeats the USA 3:0 and in the second match Europe loses 2:3 against South America. In the final round S.A. shows their "soccer cyborg" Carlos Santana, a more than supreme player who seems to be undefeatable. All their classical tricks like Hyugas "Tiger Shot" or Tsubasas "Top Spin" seem to be totally worthless, but in a hard and spectacular match the Japanese learn more and more to play in unison and finally they get the win.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yomigaeru Sora: Rescue Wings - Saigo no Shigoto', 'Special', 1, 'Completed', '2006-06-17', NULL, '7', 'Episode 13 of Yomigaeru Sora: Rescue Wings, released as a DVD special. Takes place before the events in the series.', 436, 'https://cdn.myanimelist.net/images/anime/1/1843.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ranma ½: Tendou-ke no Oyobidenai Yatsura!', 'Special', 1, 'Completed', '1992-08-30', NULL, '7', 'This features a Nabiki narrated review of the series where she discusses various characters that the Tendo family has had to tolerate spliced with new animation of Nabiki hanging around the house, taking a bath, and wondering about the true identity of P-chan. It was available through the Kitty Animation Circle. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chou Robot Seimeitai Transformers Micron Densetsu', 'TV', 52, 'Completed', '2003-01-10', '2003-12-26', '7', 'On the mechanical planet of Cybertron live super robotic organisms known as Transformers. There, mainly consisting of convoys, the Cybertron army, and their old enemy Destron fell into conflict to gain hold of a new power to join their side. A new breed of Transformers known as the Microns. But, grieving over the battle the Microns set off to the other end of the universe. 4 million years later, on Earth, 3 young children activated a mysterious panel inside a cave. And somehow, that was the dormant Micron...', 48, 'https://cdn.myanimelist.net/images/anime/1231/104729.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ryouma! The Prince of Tennis Shinsei Movie: Tennis no Oujisama', 'Movie', 1, 'Completed', '2021-09-03', NULL, '6', 'Following the conclusion of the National Middle School Tennis Tournament, 12-year-old tennis prodigy Ryouma Echizen sets out to the United States in order to further improve his tennis skills. While finding his own way to shine in the sport, Ryouma investigates a perplexing development: the circumstances behind his father''s retirement from professional tennis. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Beyblade Burst Gachi', 'TV', 52, 'Completed', '2019-04-05', '2020-03-27', '6', 'Legendary Blader Valt Aoi has been training the next generation of elite Bladers at Spain’s BC Sol. One day, rookie Blader Koryu Drum witnesses Valt unleashing his newly evolved Gachi Bey, Slash Valkyrie. To Drum''s surprise, Valkyrie radiates a golden light as it rockets around the stadium. Inspired by the limitless possibilities of this “Gold Turbo” state, Drum seeks to achieve the same bond with his Bey, Dragon. Here begins the story of Dante and Dragon’s rise to the peak of the Blading world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Monster Strike: Zoku Saishuu-banashi - Pandora no Hako', 'ONA', 1, 'Completed', '2016-12-31', NULL, '6', 'After defeating the War Gods, Ren and his friends are living the dream. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kouya no Kotobuki Hikoutai Gaiden: Oozora no Harukaze Hikoutai', 'ONA', 12, 'Completed', '2019-04-10', '2020-02-29', '6', 'A short spin-off anime released on "Kouya no Kotobuki Hikoutai: Oozora no Takeoff Girls!" game app and YouTube. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shoujo☆Conto All Starlight', 'ONA', 26, 'Completed', '2019-07-05', '2019-12-27', '6', 'Chibi shorts based on Shoujo☆Kageki Revue Starlight.', 480, 'https://cdn.myanimelist.net/images/anime/1776/102092.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Megaton-kyuu Musashi', 'TV', 13, 'Completed', '2021-10-01', '2021-12-24', '6', 'In an ordinary town, there are people who live a peaceful and fulfilling life. But they don''t know that it is a false peace. The untold truth... The earth has already been destroyed...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsubasa to Hotaru (2016)', 'Special', 3, 'Completed', '2016-05-10', '2016-05-24', '6', 'The story revolves around Tsubasa Sonokawa, a 15-year old high school girl who fell in love with her upperclassman when he saved her after she fainted at the train station from anemia. She thought it was a meeting of fate, and visited him at his class every day. However, he told her that her feelings were "heavy," and he dumped her. She once again meets a boy after taking over her friend Yuri''s job as boy''s basketball team manager. She learns that she might have more of a connection with this boy named Aki than she first thought...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ninpuu Kamui Gaiden: Tsukihigai no Maki', 'Movie', 1, 'Completed', '1971-03-20', NULL, '6', 'A theatrical edited release of episode 21-26.', 986, 'https://cdn.myanimelist.net/images/anime/1407/141808.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kacchikenee!', 'Movie', 1, 'Completed', '2016-03-19', NULL, '6', 'Aiko lives in a shrine with a sliding door that mysteriously is only half painted and thought during her childhood that she wanted to paint it. But the 17-year old Aiko now has no dreams about the future. Suddenly, a strange man appears before her. Aiko''s grandfather and the shrine''s chief priest offers the man to stay in the shrine, but Aiko isn''t having any of it. But he realizes the kindness of the brusque young man and slowly comes to like him. What is his true identity?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Balgwanghaneun Hyeondaesa', 'ONA', 3, 'Completed', '2014-07-10', NULL, '6', '"I can''t finish you..."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seizei Ganbare! Mahou Shoujo Kurumi 3rd Season', 'TV', 25, 'Completed', '2020-10-07', '2021-09-29', '6', 'Third season of Seizei Ganbare! Mahou Shoujo Kurumi.', 681, 'https://cdn.myanimelist.net/images/anime/1097/108552.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sore Ike! Anpanman: Black Nose to Mahou no Uta', 'Movie', 1, 'Completed', '2010-07-10', NULL, '6', '22nd Anpanman short movie.', 990, 'https://cdn.myanimelist.net/images/anime/10/24923.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Daitoshokan no Hitsujikai Picture Drama', 'Special', 6, 'Completed', '2014-12-25', '2015-05-28', '6', 'Picture Drama episodes bundled with the Blu-ray/DVD Volumes. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon: Pikachu to Pokemon Ongakutai', 'Movie', 1, 'Completed', '2015-07-18', NULL, '6', 'Pikachu and the rest of the group practice singing and dancing, as well as rehearsing their segments, until they realize Luchabull (Hawlucha) can''t sing! Now it''s up to Pikachu and everybody else to encourage Luchabull into getting back on cue before they have to do the show for real! Will they succeed?', 621, 'https://cdn.myanimelist.net/images/anime/6/71600.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Heart Cocktail', 'TV', 78, 'Completed', '1986-10-04', '1988-03-27', '6', 'Sometimes, it is the simplest gestures that convey the most intimate feelings. From awkward first encounters in an elevator to receiving a hand-knit sweater, love can blossom even in the most mundane of situations. Each new experience of sweet—and at times bitter—romance develops in less time than it takes to smoke a cigarette.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dr. Slump Movie 01: Arale-chan Hello! Fushigi Shima', 'Movie', 1, 'Completed', '1981-07-18', NULL, '6', 'Professor Senbei finds a videotape of his deceased father providing instructions on how to create a love potion. The main ingredient is a tear of the evil Gyaasuka Daimao who lives at the Wonder Island. To retrieve it, Senbei takes Arale and Gatchan on a wacky adventure.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Madou King Granzort: Bouken-hen', 'OVA', 3, 'Completed', '1992-03-27', '1992-06-26', '6', '', 974, 'https://cdn.myanimelist.net/images/anime/10/16692.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Avengers Confidential: Black Widow to Punisher', 'Movie', 1, 'Completed', '2014-03-11', NULL, '6', 'After interfering with a top secret mission, the Punisher is taken into custody by S.H.I.E.L.D. Agent and Avenger, Black Widow. At the orders of Director Nick Fury, Punisher and Black Widow are sent on a mission to stop Leviathan, a global terrorist organization that plans to sell stolen S.H.I.E.L.D. technology to the highest bidder. Now, the vigilante and spy must work together to prevent this technology from falling into the wrong hands. The fate of the world, and of the Avengers, hangs in the balance. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sora wo Kakeru Shoujo Picture Drama', 'Special', 9, 'Completed', '2009-04-24', '2009-11-24', '6', 'Short specials added to DVDs and Blu-rays.', 974, 'https://cdn.myanimelist.net/images/anime/9/22636.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ichirin-sha', 'ONA', 1, 'Completed', '2010-09-24', NULL, '6', 'On a planet very similar to the earth... Here, the missile mechanoids started to have its own will and control, and were driving the human beings into serious danger. Shaleen was the last ICHIRIN-SHA (unicyclist) in the world, traveling the world on his beat up motor unicycle. One day, when Shaleen was running from the attacks of the missile mechanoids, he stops by a ghost town and meets a mysterious girl who was constantly targeted by the mechanoids.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blame!', 'ONA', 6, 'Completed', '2003-10-24', NULL, '6', 'The story takes place in a city where it''s said that has thousands of levels.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ookami Shounen Ken', 'TV', 86, 'Completed', '1963-11-25', '1965-08-16', '6', 'Ken The Wolf Boy is about the adventures of Ken, who was brought up by wolves in the jungle and can be compared to Jungle Book. His main companions were two young wolves named Chi Chi and Po Po.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Street Fighter II: Yomigaeru Fujiwara-Kyou - Toki wo Kaketa Fighter-tachi', 'OVA', 1, 'Completed', '1995-03-29', NULL, '6', 'An educational anime featuring Ryu, Ken, Chun-Li, and E. Honda. The four travel back in time and talk about historic things.', 939, 'https://cdn.myanimelist.net/images/anime/1836/113597.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Akai Koudan Zillion Recaps', 'Special', 3, 'Completed', '1987-07-21', '1988-08-21', '6', '1. Akai Koudan Zillion: Emi Penguin''s Diary (EMI♡PENGUIN''S DIARY)
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('True Love Story', 'OVA', 3, 'Completed', '2003-09-26', '2004-04-23', '6', 'When Morisaki Yuuta ran into a girl in the school hallway that day, he had no idea his life would change forever. As a member of the photography club and a fledgling to the world of women, Yuuta''s life has been turned upside down by the entrance of not one, but several women into his life! From old friends to new acquaintances, it will be tough figuring out who to choose!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Magical Suite Prism Nana', 'OVA', 7, 'Airing', '2015-11-29', NULL, '6', 'In a future not too distant from ours, Nanagoo City is a beautiful city in Japan surrounded by mountains and ocean-sides. The sensitive, adolescent girls who live there are each opening up doors to their own, unique possibilities. No one wants to forget the path they take to adulthood.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Natsu e no Tobira', 'Movie', 1, 'Completed', '1981-03-20', NULL, '6', 'Marion is a young schoolboy who prides himself on his adherence to a philosophy he calls "rationalism". Because of his disdain for emotional display, he ignores anything remotely akin to affection. But when he''s entangled in a romantic affair with an older courtesan, his rationalism is revealed to be little more than a cover for his own emotional immaturity. Learning to love, Marion blossoms under his older lover''s care but unfortunately, Marion has yet to learn the true price of the affair.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Skyers 5', 'TV', 12, 'Completed', '1967-10-04', '1967-12-20', '6', 'A science fiction action series about the future battles between a planetary police force and an international crime syndicate. The series plays out as a mix between science fiction and an old western.', 986, 'https://cdn.myanimelist.net/images/anime/1010/130421.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Love♥Love? Specials', 'Special', 4, 'Completed', '2004-07-14', '2004-09-01', '6', 'DVD Special containing:
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Soliton no Akuma', 'Movie', 1, 'Completed', '1997-01-01', NULL, '6', 'In the future, tensions are rising between Japan and China. The jewel of humankind is the new Ocean Techno Polis, a man-made city which floats above the sea. One day, a mysterious catastrophe destroys a Taiwanese submarine followed by the entire city of Ocean Techno Polis. One of the engineers of Ocean Techno Polis, Kurase, must race to rescue his family. Along the way, he must deal with a Japanese navy trying to keep their own secrets under wraps, and discover why Ocean Techno Polis sank to the bottom of the sea.', 1053, 'https://cdn.myanimelist.net/images/anime/1841/116383.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Legend of Crystania', 'OVA', 3, 'Completed', '1996-11-21', '1997-04-23', '6', 'Dreams begin to haunt Lady Sheru -- dreams of her past life as Pirotesse. Her love, Ashram, is being tormented at the hands of the soul of Barbas posing as their former king, Beld of Marmo. Interpreting this as a plea for help, Sheru searches for a way to save him by entering the chaos realm using the Chaos Ring. Meanwhile, Redon and his friends are called to arms again as ancient creatures begin to appear after being sealed away for centuries. Both their paths will cross once again, and on their shoulders will the fate of Crystania lie. 
(Source: ANN)', 1053, 'https://cdn.myanimelist.net/images/anime/9/2764.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Teito Monogatari', 'OVA', 4, 'Completed', '1991-09-27', '1992-09-25', '6', 'At the end of the Meiji era, Japan works toward a bright future, with technological advancements changing people''s lives daily. However, the enigmatic Yasunori Katou looks upon the modern metropolis of Tokyo with disdain and wants nothing more than to see its ruin. As Katou tries to wreak havoc on the city, the Tatsumiya family finds itself at the center of his strange and nefarious schemes.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rhythmens Episode 0', 'ONA', 1, 'Completed', '2021-05-14', NULL, '6', '', 1080, 'https://cdn.myanimelist.net/images/anime/1035/121169.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Suntory Minami Alps no Tennensui', 'Special', 3, 'Completed', '2016-08-09', '2016-08-20', '6', 'Collaboration commercials with Suntory and Kimi no Na wa..
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Guilty Gear Strive: Dual Rulers', 'TV', 8, 'Completed', '2025-04-05', '2025-05-24', '6', 'After the decline of the once robust fields of science and technology, a new energy source known as magic fuels the modern era. Humanity creates forbidden biological weapons: Gears. Those Gears eventually stand against humanity in a rebellion. Although they manage to overcome in the struggle for survival known as the Crusades, humanity''s losses are so great that even after several decades pass, their emotional wounds remain unable to fully heal.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hikari no Ou 2nd Season', 'TV', 10, 'Completed', '2024-01-14', '2024-03-17', '6', 'After escaping a violent encounter, Touko finds herself lost in the chaos of a city under invasion by Spiders, a tribe of people with dangerous supernatural abilities. Touko has traveled to the city intending to return the possessions of Haijuu, a fire hunter who died protecting her. She is aided by Haijuu''s dog, Kanata, and Akira, a fire hunter who has protected her on her journey so far. When Akira is drawn away by an important task, Touko is swept into the battle''s confusion to begin a new journey of her own.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lance N'' Masques', 'TV', 12, 'Completed', '2015-10-02', '2015-12-18', '5', 'Eight words describe the feelings of Youtarou Hanabusa: "I just want to live a normal life." Unfortunately for him, as a member of the Knights of the World, his training in this ancient and international order has left him with a condition he calls "White Knight Syndrome." This condition causes Youtarou to instinctively act heroically and chivalrously whenever he encounters someone in danger.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dies Irae: Irasshai Zonnenji', 'ONA', 18, 'Completed', '2017-06-28', '2017-10-18', '5', 'A picture drama parody of Dies Irae, but advertised as a radio-style drama. It predominantly follows a chibi-Kasumi and chibi-Rea at the temple.', 17, 'https://cdn.myanimelist.net/images/anime/13/88198.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ookami Kodomo no Ame to Yuki x House Shokuhin Stew CM', 'Special', 1, 'Completed', '2012-08-27', NULL, '5', 'A collaboration campaign between Ookami Kodomo no Ame to Yuki and House Foods Corporation. The commercial features Hana making cream stew using the roux box along with Ame and Yuki helping with dinner preparations. The House Cream Stew was also sold in a Ookami Kodomo no Ame to Yuki-themed design for a limited time.', 865, 'https://cdn.myanimelist.net/images/anime/1890/90862.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Higanjima X', 'ONA', 12, 'Completed', '2016-10-15', '2017-03-25', '5', 'Akira is in the midst of the final battle between the human race and vampires. He only has 47 days until Japan is turned into an island of vampires.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bamboo Blade: Fanfu-Fufe-Fo', 'Special', 2, 'Completed', '2008-04-23', '2008-06-25', '5', 'Bamboo Blade specials released on DVD volumes 4 and 6. Done in a chibi flash animation style and set to bizzare scenarios.', 26, 'https://cdn.myanimelist.net/images/anime/8/69535.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Otona no Bouguya-san II', 'ONA', 12, 'Completed', '2021-01-02', '2021-03-20', '5', 'Second season of Otona no Bouguya-san.', 405, 'https://cdn.myanimelist.net/images/anime/1738/111426.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hybe: Above and Beyond', 'Special', 1, 'Completed', '2021-03-19', NULL, '5', 'HYBE Labels brand identity film.', 671, 'https://cdn.myanimelist.net/images/anime/1762/141569.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Harutsugeuo to Fuuraibou', 'Special', 1, 'Completed', '2024-02-16', NULL, '5', 'A little covetous breeze makes a pretty melody blowing in the wind. The story of a mysterious journey of tiny creatures intertwine through the hommono wilderness.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Natsumatsuri', 'Movie', 1, 'Upcoming', NULL, NULL, '5', 'A girl moves to a certain town and goes to a summer festival in the neighborhood with her grandmother. As she was excited by the lively people and the unfamiliar food stalls, she suddenly lost sight of her grandmother.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Atarashii wo Uchi ni Chu', 'Movie', 1, 'Upcoming', NULL, NULL, '5', 'Why do people live with cats at home? A short animation that explores and reconsiders the expectations and anxieties of living at home with a cat from the perspectives of a child and an adult.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lanqiu Xuanfeng', 'TV', 52, 'Completed', '2019-09-02', '2019-09-28', '5', '', 156, 'https://cdn.myanimelist.net/images/anime/1044/150164.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pipilu Anquan Tegong Dui', 'TV', 13, 'Completed', '2019-01-02', '2019-03-27', '5', 'Protecting children''s safety: Pipilu''s 100 Safety Rules! Pipilu Rangers make a promise to create the "Safetipedia" by making 100 safety rules one rule at a time, every time they stop an accident. However, the troublemakers RedNose and BlueNose keep causing accidents!! The match between space villains and Pipilu Rangers builds tension… Pipilu and Luxixi get better and better each episode. The Pipilu Rangers'' teamwork also gets stronger and stronger. They rescue children from safety accidents and keep on creating safety rules. Pipilu Rangers will always be on duty until the Safetipedia is complete!!!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sennen Joyuu', 'Movie', 1, 'Completed', '2002-09-14', NULL, '8', 'At the turn of the millennium, Ginei Studio''s dilapidated buildings are set to be demolished. Ex-employee and filmmaker Genya Tachibana decides to honor this occasion with a commemorative documentary about the company''s star actress: Chiyoko Fujiwara, the reclusive sweetheart of Shouwa Era cinema. Having finally obtained permission to interview the retired starlet, an enamored Genya drags along cynical cameraman Kyouji Ida to meet her, ready to put his lifelong idol back in the spotlight once more.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Planetes', 'TV', 26, 'Completed', '2003-10-04', '2004-04-17', '8', 'In 2075, space travel is no longer just a dream, but an everyday reality for mankind. Advancements in science and technology have led to the colonization of the moon, the commercialization of outer space, and the formation of large space corporations. Ai Tanabe, an upbeat woman whose interests lie in the cosmos, joins Technora Corporation as a member of their Debris Section, a department dedicated to the removal of dangerous space junk between the orbits of the Earth and Moon.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan: Episode One - Chiisaku Natta Meitantei', 'Special', 1, 'Completed', '2016-12-09', NULL, '8', 'The "real" episode 1 of Meitantei Conan written by the Mangaka Gosho Aoyama.', 990, 'https://cdn.myanimelist.net/images/anime/5/81968.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Re:Zero kara Hajimeru Isekai Seikatsu', 'TV', 25, 'Completed', '2016-04-04', '2016-09-19', '8', 'When Subaru Natsuki leaves the convenience store, the last thing he expects is to be wrenched from his everyday life and dropped into a fantasy world. Things are not looking good for the bewildered teenager; however, not long after his arrival, he is attacked by some thugs. Armed with only a bag of groceries and a now useless cell phone, he is quickly beaten to a pulp. Fortunately, a mysterious beauty named Satella, in hot pursuit after the one who stole her insignia, happens upon Subaru and saves him. In order to thank the honest and kindhearted girl, Subaru offers to help in her search, and later that night, he even finds the whereabouts of that which she seeks. But unbeknownst to them, a much darker force stalks the pair from the shadows, and just minutes after locating the insignia, Subaru and Satella are brutally murdered.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Spy x Family Season 3', 'TV', 13, 'Airing', '2025-10-04', '2025-12-27', '8', 'Despite occasional setbacks, Operation Strix has remained on track to extract sensitive information from the enigmatic politician Donovan Desmond. To this end, spy Loid Forger has managed to maintain his pretend family consisting of his telepathic daughter, Anya; assassin wife, Yor; and their clairvoyant dog, Bond. Still the only one aware of everyone''s true identities, Anya tries to sustain the family''s cohesion while working to befriend Donovan''s son Damian, her Eden Academy classmate.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('BanG Dream! It''s MyGO!!!!!', 'TV', 13, 'Completed', '2023-06-29', '2023-09-14', '8', 'In their last year of middle school, the five band members of CRYCHIC went their separate ways after an unpleasant disbandment. Each wrestling with their own regrets, the girls enrolled in different high schools, hoping never to hear from one another again.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Youjo Senki Movie', 'Movie', 1, 'Completed', '2019-02-08', NULL, '8', 'With its armies sweeping across the continent, the Empire seems unstoppable. After securing victory over the remnants of the Republic''s army, the Empire''s ultimate victory is finally within reach. However, dark clouds are gathering in the East. The communist-led Russy Federation is mustering troops on its western border, preparing to enter the war. Supported by a detachment of Allied volunteer magicians—among whom is Mary Sioux, the daughter of a soldier killed by Tanya Degurechaff—the Federation is determined to spread the communist creed and bring the Empire to its knees.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Non Non Biyori Movie: Vacation', 'Movie', 1, 'Completed', '2018-08-25', NULL, '8', 'With summer vacation coming to an end, the girls are having as much fun as they can with their remaining time. However, their daily shenanigans are cut short when Suguru Koshigaya wins the grand prize of a lottery—tickets to Okinawa! After hasty preparations, the Asahigaoka group embarks on a three-day trip for their final summer getaway.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kono Sekai no Katasumi ni', 'Movie', 1, 'Completed', '2016-11-12', NULL, '8', 'Suzu Urano is a pure and kindhearted girl who loves to draw and keep her head in the clouds. Growing up in the outskirts of Hiroshima with her family, she is more than happy to help with her grandmother''s nori business.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam: Tekketsu no Orphans 2nd Season', 'TV', 25, 'Completed', '2016-10-02', '2017-04-02', '8', 'Tekkadan has now become a direct affiliate of Teiwaz after procuring a new trade agreement with Arbrau. With its newfound funds and prestige, Tekkadan finds both its list of allies and enemies growing. Meanwhile, the flames of the Gjallarhorn power struggle continue to rage in full force. As a part of her efforts to make Mars financially independent from Earth, Kudelia Aina Bernstein founds the Admoss Company and enlists Tekkadan as her business partner. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Danshi Koukousei no Nichijou', 'TV', 12, 'Completed', '2012-01-10', '2012-03-27', '8', 'Roaming the halls of the all-boys Sanada North High School are three close comrades: the eccentric ringleader with a hyperactive imagination Hidenori, the passionate Yoshitake, and the rational and prudent Tadakuni. Their lives are filled with giant robots, true love, and intense drama... in their colorful imaginations, at least. In reality, they are just an everyday trio of ordinary guys trying to pass the time, but who said everyday life couldn''t be interesting? Whether it''s an intricate RPG reenactment or an unexpected romantic encounter on the riverbank at sunset, Danshi Koukousei no Nichijou is rife with bizarre yet hilariously relatable situations that are anything but mundane.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seishun Buta Yarou wa Bunny Girl Senpai no Yume wo Minai', 'TV', 13, 'Completed', '2018-10-04', '2018-12-27', '8', 'The rare and inexplicable Puberty Syndrome is thought of as a myth. It is a rare disease which only affects teenagers, and its symptoms are so supernatural that hardly anyone recognizes it as a legitimate occurrence. However, high school student Sakuta Azusagawa knows from personal experience that it is very much real, and happens to be quite prevalent in his school.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kage no Jitsuryokusha ni Naritakute!', 'TV', 20, 'Completed', '2022-10-05', '2023-02-15', '8', 'For as long as he can remember, Minoru Kagenou has been fixated on becoming as strong as possible, which has led him to undertake all kinds of rigorous training. This wish, however, does not stem from a desire to be recognized by others; rather, Minoru does everything he can to blend in with the crowd. So, while pretending to be a completely average student during the day, he arms himself with a crowbar and ruthlessly thrashes local biker gangs at night. Yet when Minoru finds himself in a truck accident, his ambitions seemingly come to a sudden end. In his final moments, he laments his powerlessness—no matter how much he trained, there was nothing he could do to overcome his human limitations.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Majo no Takkyuubin', 'Movie', 1, 'Completed', '1989-07-29', NULL, '8', 'Kiki, a 13-year-old witch-in-training, must spend a year living on her own in a distant town in order to become a full-fledged witch. Leaving her family and friends, Kiki undertakes this tradition when she flies out into the open world atop her broomstick with her black cat Jiji.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shoujo Kakumei Utena', 'TV', 39, 'Completed', '1997-04-02', '1997-12-24', '8', 'Years ago, a tragic incident befell a young princess when both her parents died. Devastated, it seemed nothing would calm this poor soul. However, a prince traveling through the area came to see the princess, hoping to cheer her up. After wiping her sorrowful tears, the prince gave her a ring carrying a rose emblem and told her as long as she holds onto the ring, they are destined to meet again. The event leaves a deep impression on the girl, Utena Tenjou, leading her to become a prince herself. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('IDOLiSH7 Third Beat!', 'TV', 13, 'Completed', '2021-07-04', '2021-09-26', '8', 'Nearing their first debut anniversary and with their popularity still on the rise, IDOLiSH7 set a date for a live tour to express their gratitude toward their fans. Meanwhile, the Black or White event draws closer—and as the previous year''s winners—the group must prepare to take on the challengers. Looking to solidify their reputation in the world of idols, IDOLiSH7 are determined to come out victorious and settle the score once and for all with their rival, TRIGGER.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shoujo Shuumatsu Ryokou', 'TV', 12, 'Completed', '2017-10-06', '2017-12-22', '8', 'Amid the desolate remains of a once-thriving city, only the rumbling of a motorbike breaks the cold winter silence. Its riders, Chito and Yuuri, are the last survivors in the war-torn city. Scavenging old military sites for food and parts, the two girls explore the wastelands and speculate about the old world to pass the time. Chito and Yuuri each occasionally struggle with the looming solitude, but when they have each other, sharing the weight of being two of the last humans becomes a bit more bearable. Between Yuuri''s clumsy excitement and Chito''s calm composure, their dark days get a little brighter with shooting practice, new books, and snowball fights on the frozen battlefield. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yi Nian Yong Heng 3rd Season', 'ONA', 59, 'Completed', '2024-07-03', '2025-07-22', '8', 'After Bai Xiaochun merged the four downstream sects to form the Reverse River Sect, he successfully challenged the three midstream sects and established a firm foothold. He was then chosen by the Celestial Being of the Starry Sky Dao Sect in the upstream to be a hostage, thus beginning the third season, the Hostage arc.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boku no Kokoro no Yabai Yatsu', 'TV', 12, 'Completed', '2023-04-02', '2023-06-18', '8', 'Kyoutarou Ichikawa may look like a shy and reserved middle school student, but deep within his heart is a bloodthirsty killer. His ultimate desire is to see his classmate Anna Yamada''s beautiful face writhing in pain before he ends her life. But this fantasy may never come to fruition, as Ichikawa starts to see an entirely different side to Yamada.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Liz to Aoi Tori', 'Movie', 1, 'Completed', '2018-04-21', NULL, '8', 'Liz''s days of solitude come to an end when she meets a blue bird in the form of a young girl. Although their relationship blossoms, Liz must make a heart-wrenching decision in order to truly realize her love for Blue Bird.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bakemono no Ko', 'Movie', 1, 'Completed', '2015-07-11', NULL, '8', 'Two souls, living very different lives, wander alone and isolated in their respective worlds. For nine-year-old Ren, the last person who treated him with any form of kindness has been killed, and he is shunned by what is left of his family. With no parents, no real family, and no place to go, Ren escapes into the confusing streets and alleyways of Shibuya. Through the twists and turns of the alleys, Ren stumbles into the intimidating Kumatetsu, who leads him to the beast realm of Shibuten.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nodame Cantabile Finale', 'TV', 11, 'Completed', '2010-01-15', '2010-03-26', '8', 'Shinichi Chiaki is quickly making a name for himself as the principal conductor of the revitalized Roux-Marlet Orchestra, and Megumi "Nodame" Noda has made leaps and bounds as a pianist at the Conservatoire de Paris. However, tensions mount between the two as Nodame feels left behind by Chiaki''s growing success and his close friendship with legendary piano prodigy Rui Son. Disregarding her teacher Professor Charles Auclair''s advice, Nodame enters another piano competition in an attempt to jumpstart her own performance career. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wu Liuqi: Zui Qiang Fa Xing Shi', 'ONA', 10, 'Completed', '2019-10-23', '2020-01-01', '8', 'Seeking to recover his memories, a scissor-wielding hairdresser, bungling quasi-assassin stumbles into a struggle for power among two feuding factions.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou Shoujo Madoka★Magica Movie 1: Hajimari no Monogatari', 'Movie', 1, 'Completed', '2012-10-06', NULL, '8', 'Madoka Kaname and her best friend Sayaka Miki are ordinary middle school students in the city of Mitakihara. But one day, they encounter a strange cat-like creature named Kyuubey, who claims he can grant them one wish. In exchange, they would become magical girls and fight against evil perpetrated by witches. A veteran magical girl in the area, Mami Tomoe, decides to show them how to hunt witches, while the mysterious transfer student Homura Akemi warns them to not take Kyuubey''s deal, though she refuses to say why.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sexy Commando Gaiden: Sugoi yo!! Masaru-san', 'TV', 48, 'Completed', '1998-01-06', '1998-04-01', '8', 'Okometsubu Fujiyama has recently transferred over to a new school, Wakame High School. His goal is to make 100 friends--until he meets the extremely weird Masaru Hananakajima. Masaru is a martial artist whose specialty is the "Sexy Commando" form of martial art. Masaru forms a club based on this art, including Fujiyama, who he nicknames Fuumin, in the club. The club becomes full of strange, yet wacky people. Aliens, mustaches, and cute fuzzy animals are encountered as the club moves along and gets steadily more popular.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tenchi Muyou! Ryououki 2nd Season', 'OVA', 6, 'Completed', '1994-09-25', '1995-09-25', '8', 'While the galaxy remains at peace, Tenchi Masaki continues to live on Earth with Ryouko and Washuu Hakubi, Aeka and Sasami Jurai Masaki, Mihoshi Kuramitsu, and the cat-like creature Ryo-Ohki. Though it sounds great to be surrounded by so many women, they always end up making things difficult for Tenchi by constantly fighting for his attention, and their attempts at household chores always end in disaster.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tenchi Muyou! Ryououki', 'OVA', 6, 'Completed', '1992-09-25', '1993-03-25', '8', 'Seventeen-year-old Tenchi Masaki grew up hearing stories about how his ancestor used a sword to seal a demon inside a cave seven hundred years ago. When curiosity gets the better of him, Tenchi goes to the cave and stumbles across the sword from the legend. Thinking that the story is nothing more than a fairy tale, he removes the blade and inadvertently releases the demon, who turns out to be a space pirate named Ryouko Hakubi. Furious about being trapped for so long, she attacks Tenchi, but he is able to repel her with the sword, awakening his inner power. After seeing this, Ryouko takes an interest in her unlikely savior and decides to crash at his place.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fairy Tail: 100-nen Quest', 'TV', 25, 'Completed', '2024-07-07', '2025-01-05', '8', 'For over one hundred years, a special quest has been waiting for a wizard skilled enough to complete it. On the northern continent of Guiltina, there are five immensely powerful Dragon Gods who possess great destructive force that can only be quelled by sealing them away. Natsu Dragneel and his friends from the Fairy Tail guild—Lucy Heartfilia, Gray Fullbuster, Erza Scarlet, Wendy Marvell, and the exceeds Happy and Charlés—consider this the perfect challenge to take on.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Free! Dive to the Future', 'TV', 12, 'Completed', '2018-07-12', '2018-09-27', '8', 'With the seniors having graduated from high school, the determined swimmers eagerly take on their futures with a dream to fulfill. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jungle wa Itsumo Hare nochi Guu Final', 'OVA', 7, 'Completed', '2003-12-21', '2004-06-25', '8', 'Haré''s family receives a video letter from Weda''s home in the city. Witnessing how sad and lonely Weda''s mother and Bel are without her, Weda decides to take Haré and Guu back to the city for a while. After Haré complains about being bored and lonely without his friends in the jungle (as part of his plot to persuade his mother to take him back), Weda decides to send him to a private school in the city, where he instanly falls in love with a pretty girl named Rita. But, of course, Guu wants part of the action too.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The iDOLM@STER', 'TV', 25, 'Completed', '2011-07-08', '2011-12-23', '8', '765 Production Studio manages the unique talents of 13 professional idols as they slowly make their way to the top and become country-wide celebrities. But the girls'' journey is far from just fun and games: hard work, sweat, and tears are some of the prerequisites needed to flourish in this industry—and for 765 Pro in particular, a watchful eye out for their rival, the infamous 961 Production.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kareshi Kanojo no Jijou', 'TV', 26, 'Completed', '1998-10-02', '1999-03-26', '8', 'Yukino Miyazawa is the female representative for her class and the most popular girl among the freshmen at her high school. Good at both academics and sports on top of being elegant and sociable, she has been an object of admiration all her life. However, in reality, she is an incredibly vain person who toils relentlessly to maintain her good grades, athleticism, and graceful appearance. She wants nothing more than to be the center of attention and praise—which is why she cannot stand Souichirou Arima, the male representative for her class and the only person more perfect than her. Since the first day of high school, she has struggled to steal the spotlight from her new rival but to no avail.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fushigi Yuugi', 'TV', 52, 'Completed', '1995-04-06', '1996-03-28', '8', 'During a visit to the National Library, Miaka Yuuki and Yui Hongo stumble upon a strange old book that casts a red light, sucking them inside its unfamiliar world. Upon arrival, the two encounter hostile slave traders and barely escape with the help of Tamahome—a powerful young man bearing a Chinese symbol on his forehead. But, a moment later, the red light returns and takes Yui away. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blood+', 'TV', 50, 'Completed', '2005-10-08', '2006-09-23', '8', 'Saya Otonashi is a seemingly ordinary girl living a mundane life with her adoptive family in Okinawa City. In fact, her only peculiarities are suffering from anemia and being unable to remember any of her life beyond the previous year.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jigoku Shoujo', 'TV', 26, 'Completed', '2005-10-05', '2006-04-05', '8', 'It is said that if someone seeks revenge, they should dig two graves—and this is especially true of those who use the Hell Correspondence website. At the stroke of midnight, this ominous web domain becomes accessible, and whoever inputs the name of their grudge will get a visit from Ai Enma, the Hell Girl. Ai explains that she will send the target''s soul to hell, but the requester will also end up in hell when they die.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sakamoto Days', 'TV', 11, 'Completed', '2025-01-11', '2025-03-22', '8', 'The name Tarou Sakamoto once instilled fear in every villain. No other professional hitman matched his prowess, and fellow assassins revered him. However, Sakamoto fell in love. In five short years, he married, became a father, put on some weight, and traded his weapons for an apron as he became the owner of a humble convenience store.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ninja to Koroshiya no Futarigurashi', 'TV', 12, 'Completed', '2025-04-10', '2025-06-26', '8', 'At first glance, Konoha Koga is an average high school girl who lives alone. However, she has a secret—she works as an assassin on the side! One day, fate puts her in an encounter with Satoko Kusagukare, a runaway ninja hunted by her comrades for accidentally leaving her village.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saikyou no Shienshoku "Wajutsushi" de Aru Ore wa Sekai Saikyou Clan wo Shitagaeru', 'TV', 12, 'Completed', '2024-10-07', '2024-12-23', '8', 'Noel longs to be a Seeker like his heroic grandfather, slaying the beasts that emerge from Abysses and exploring far-off lands. Unfortunately, it turns out he''s nothing but a measly Talker–a job with no combat skills whatsoever. Undaunted, Noel sets out to establish the strongest clan in all the land, using his silver-tongued Talker skills to unite assassins and heroes under his leadership.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wanneng Lian Ai Zahuo Dian', 'ONA', 16, 'Completed', '2023-11-09', '2024-02-08', '8', 'Shi Ye is a police inspector who has no such interests in things like love and romance. One day, Ye finds himself up against a crafty witch who offers peculiar solutions to love problems. Follow Shi Ye as he tries to solve the mystery of the Ultimate Love Bazaar and its peculiar owner.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Ball Daima', 'TV', 20, 'Completed', '2024-10-11', '2025-02-28', '8', 'After saving the world from the destructive might of Majin Buu, Gokuu Son and his allies look forward to a well-earned rest. However, unbeknownst to them, their battle was recorded and observed by Gomah, an evil being who assumes the title of King in the Demon Realm, filling the void left behind with the death of former ruler Dabura.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gensou Mangekyou: The Memories of Phantasm', 'OVA', NULL, 'Airing', '2011-08-12', NULL, '8', 'Marisa, an ordinary magician, suspects a youkai is behind the winterly weather in the middle of spring. She goes off to investigate and soon arrives in the netherworld, facing the youkai behind the strange incident. Will her friend, the shrine maiden Reimu, arrive in time to save the day or will all be lost?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Arknights: Perish in Frost', 'TV', 8, 'Completed', '2023-10-07', '2023-11-25', '8', 'Rebel organization Reunion has reduced the city of Chernobog to ashes and despair. That is only the beginning of its uprising against the nations prejudiced toward those infected with the highly contagious and deadly disease Oripathy. Now, the rebels have set their sights on Lungmen—a prosperous city infamous for its inhumane treatment of the sick. After witnessing Reunion destroy her homeland, Chief Ch''en of the Lungmen Guard Department''s Special Inspection Unit leads her squad to defend her city.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon: Mezase Pokemon Master', 'TV', 11, 'Completed', '2023-01-13', '2023-03-24', '8', 'By embracing challenges, learning from failures, overcoming obstacles, and beating the best in the world, Satoshi finally achieves his long-held dream. His adventurous spirit, however, still runs high as he continues to explore new regions, witness unfamiliar Pokémon, and forge unexpected friendships and rivalries.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ensemble Stars!! Tsuioku Selection Element', 'ONA', 6, 'Completed', '2023-04-06', '2023-04-11', '8', 'New Ensemble Stars!! web animated series based on the game story "Element".', 223, 'https://cdn.myanimelist.net/images/anime/1328/133039.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hirogaru Sky! Precure', 'TV', 50, 'Completed', '2023-02-05', '2024-01-28', '8', 'A major incident in peaceful Skyland?! The infant princess Ellee-chan has been kidnapped by a monster from the Undergu Empire! A brave girl named Sora follows the princess into a strange hole. It leads her to another world called Sorashido City. Televisions? Bicycles? Are these magical devices?!?! There''s no time to be surprised! Sora has to take the princess back to the castle as soon as possible! Flying between two worlds! This is the beginning of a Precure adventure! It''s hero time!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Asobi Asobase Specials', 'Special', 2, 'Completed', '2018-11-28', '2018-12-21', '8', 'Ototo
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chuuka Ichiban!', 'TV', 52, 'Completed', '1997-04-27', '1998-09-13', '8', 'The story takes place in 19th century China during the Qing Dynasty, where the Emperor was weakened and the country was close to chaos. It is also during a fictitious era called "The Era of the Cooking Wars". It was an era in which top chefs with different cooking styles tried their best to improve their skills and to become the best chef in China. It is a country where insulting a high-grade chef or fooling around with cooking could land a person in a jail, and impersonating a top-chef is as good as usurpation of authority. Chefs compete with each other in order to gain respect and even power, but also with the risks of losing everything.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Full Metal Panic!', 'TV', 24, 'Completed', '2002-01-08', '2002-06-18', '8', 'Mithril, a covert military institution using state-of-the-art technology to combat terrorist operations, assigns a specialized team to a sensitive mission. Under the command of superior officer Melissa Mao, sergeants Sousuke Sagara and Kurz Weber must secretly protect Kaname Chidori—a teenage girl who unconsciously holds breakthrough scientific knowledge and is considered a "Whispered"—from intelligence agencies and other organizations pursuing her abilities.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gosick: Utsukushiki Kaibutsu wa Konton no Sen wo Shimiru', 'Special', 1, 'Completed', '2011-03-26', NULL, '7', 'Recap episode. The first part of the episode consists of the recap, the second part consists of some interviews with the cast.', 138, 'https://cdn.myanimelist.net/images/anime/11/28897.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Metal Fight Beyblade 4D', 'TV', 52, 'Completed', '2011-04-03', '2012-04-01', '7', 'In the Cosmos, an unusual event has occurred.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bakumatsu Kikansetsu Irohanihoheto', 'ONA', 26, 'Completed', '2006-10-06', '2007-04-06', '7', 'In the final years of the Bakumatsu, wandering mercenary Yojiro Akizuki travels the length and breadth of Japan. And while he employs his sword in the usual fashion, he also uses it to help him locate supernatural items which he pursues with single-minded determination, often with bloody results. In the course of his quest, he crosses paths with a traveling theater group whose members have their own dark agenda. Is it a chance meeting or the result of some, as yet, undiscovered conspiracy? 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Black Blood Brothers', 'TV', 12, 'Completed', '2006-09-08', '2006-11-24', '7', 'Black Bloods and Red Bloods, vampires and humans. Despite their differences, these two races once fought together in a crusade against a formidable foe. A decade later, the vampire war hero Jirou Mochizuki, known as the "Silver Blade," travels with his younger brother Kotarou to the Special Zone—a safe haven where vampires and humans live in harmony.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuragi-sou no Yuuna-san OVA', 'OVA', 4, 'Completed', '2018-07-04', '2020-12-04', '7', 'Bundled with the 11th, 12th, 13th and 24th volumes of the Yuragi-sou no Yuuna-san manga. The first episode will adapt the manga''s 12th chapter. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sousei no Aquarion', 'TV', 26, 'Completed', '2005-04-05', '2005-09-27', '7', 'Once upon a time, a race known as the Shadow Angels attacked Earth to harvest the life force of all those who inhabited the planet. Thanks to some outrageous miracle, the Shadow Angels went dormant, and humanity was able to live another 12,000 years without fearing their presence. But 11 years after a catastrophe dubbed the Holy Genesis brought ruin to the Earth, the Shadow Angels were stirred from their slumber and resumed the attacks once more.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Muv-Luv Alternative: Total Eclipse', 'TV', 24, 'Completed', '2012-07-02', '2012-12-24', '7', 'In 1973, following the ruthless six-year-long Lunar War, the hostile alien species known as the BETA—Beings of Extra Terrestrial origin which are Adversary of the human race—invaded Earth, killing billions and decimating Eurasia. While BETA can be destroyed with conventional weapons, their laser-class is able to wipe out entire aircraft fleets, forcing mankind to develop giant combat suits called Tactical Surface Fighters (TSF) to combat them.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hoshi no Koe', 'OVA', 1, 'Completed', '2002-02-02', NULL, '7', 'It is the year 2046, Noboru Terao and Mikako Nagamine are close friends who will soon be graduating junior high school. But after an alien attack on humanity, Mikako is selected for the UN military space expedition set to retaliate against the aliens. Separated, Noboru and Mikako attempt to keep in touch by sending emails to each other with their cell phones. Yet as the expedition journeys farther from Earth, the time it takes for them to transmit and receive each other''s messages increases substantially.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shaonian Ge Xing', 'ONA', 26, 'Completed', '2018-12-26', '2019-06-05', '7', 'Wangyou, Master of Hanshui Temple died mysteriously and when the news about a golden coffin spreads throughout the world, it triggered disputes between the World of Martial arts. Join a group of youths, Lei Wujie, Xiao Se, Tang Lian, Sikong Qianluo, Heavenly Maiden Rui in their adventure as the mystery of the golden coffin unravels.', 159, 'https://cdn.myanimelist.net/images/anime/1712/153839.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece Movie 02: Nejimaki-jima no Daibouken', 'Movie', 1, 'Completed', '2001-03-03', NULL, '7', 'Informed by the Thief Brothers his ship has been stolen by the Trump Kyoudai (Trump Siblings) who have set up base on Clockwork Island. Monkey D. Luffy, Captain of the Going Merry and aspiring Pirate King works with his crew - Usopp, Zoro, Sanji and Nami to battle their way up Clockwork Island to reclaim their ship.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mizu Zokusei no Mahoutsukai', 'TV', 12, 'Completed', '2025-07-04', '2025-09-26', '7', 'After getting caught up in an accident, Ryou Mihara is reincarnated in the world of Phi as a water magician. Waking up in a remote forest, he sets out to achieve his ideal slow life by living off monsters and refining his magic. Unbeknownst to Ryou, in his second life he has gained the hidden trait "Eternal Youth."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Terminator 0', 'ONA', 8, 'Completed', '2024-08-29', NULL, '7', 'Decades after the sentient artificial intelligence Skynet took control of the planet in 2022, the resistance is still fighting against the machines. Following a fierce battle, Eiko, a guerilla soldier in Japan, manages to corner a Terminator—Skynet''s elite killing cyborg. Eiko extracts crucial details of its plan, allowing the resistance to send her back in time and secure a different future.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bad Girl', 'TV', 12, 'Completed', '2025-07-06', '2025-09-21', '7', 'High school first year Yuu Yuutani has always been a good girl, following the rules, helping out around her house, and generally going through life unnoticed. From afar, she reveres her upperclassman and the school''s Public Decency Officer, Atori Mizutori, and desperately wants her attention. When she realizes that the best way to get Atori to notice her is to be a delinquent, she begins to dress differently: she dyes parts of her hair a bright red, wears clips on her ears to resemble piercings, and attaches jumbo erasers to her shoes to give them thicker soles.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shiunji-ke no Kodomotachi', 'TV', 12, 'Completed', '2025-04-08', '2025-06-24', '7', 'The wealthy and esteemed Shiunji family consists of seven siblings: Banri, Seiha, Ouka, Arata, Shion, Minami, and Kotono. Arata, the family heir, is constantly teased by his sisters for his inability to find love. However, during Kotono''s 15th birthday, the siblings learn a shocking, long-hidden secret—all of them are adopted!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wangzhe Da Shixiong', 'ONA', 16, 'Completed', '2023-09-30', '2023-12-30', '7', 'After Jiang Beiran came to Xuanlong Continent, he experienced the ups and downs of human relationships, and gradually figured out the rules of survival in this world, and was later accepted as a disciple of Guixin Sect. In the sect, he appears to be a low-key disciple who loves Go, but in fact he is proficient in chess, calligraphy, and painting, and is capable of literary and martial arts. He secretly helped the sect discover and train a group of outstanding disciples, and started the path of cultivating immortality in a low-key way...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gintama on Theater 2D: Baragaki-hen', 'Movie', 1, 'Completed', '2023-11-10', NULL, '7', 'A compilation film of the Thorny Arc, episodes 43–46 in the second season, featuring additional footage. The movie is a part of the "Gintama 20th Anniversary Project."', 116, 'https://cdn.myanimelist.net/images/anime/1579/150207.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dubu Wangu', 'ONA', 40, 'Completed', '2023-09-29', '2024-02-06', '7', 'The protagonist genius, Ye Feng, was betrayed and attacked by his senior, and other evildoers, after he refines the Divine Realm pill that would lead him towards Supreme Realm. He managed to fend off and consume the pill, yet finds himself inhabiting the body of his descendant, who bears his name after 500 years later. He pledge to save his current lineage and seeks vengeance, Yefeng embarked on the path of cultivation again, practicing hard and improving while exploring the mystery of the way of heaven.', 978, 'https://cdn.myanimelist.net/images/anime/1720/138642.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Crayon Shin-chan Movie 31: Chounouryoku Daikessen - Tobe Tobe Temakizushi', 'Movie', 1, 'Completed', '2023-08-04', NULL, '7', '', 804, 'https://cdn.myanimelist.net/images/anime/1431/136322.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Knight''s & Magic', 'TV', 13, 'Completed', '2017-07-02', '2017-09-24', '7', 'Having died in a car accident, Tsubasa Kurata—an otaku from modern Japan—is reborn in the Fremmevilla Kingdom, a medieval world where powerful mechs called Silhouette Knights are used to fight horrific demonic beasts.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Black Bullet', 'TV', 13, 'Completed', '2014-04-08', '2014-07-01', '7', 'In the year 2021, a parasitic virus known as "Gastrea" infects humans and turns them into monsters. What is left of mankind now lives within the Monolith walls, walls that are made of Varanium, the only material that can hurt Gastrea.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gundam Build Divers Re:Rise', 'ONA', 13, 'Completed', '2019-10-10', '2019-12-26', '7', 'Two years have passed since the EL-Divers incident, and the popularity of the game Gunpla Battle Nexus Online (GBN) has continued to skyrocket. With the addition of exciting new features such as missions and story events, the GBN experience is more immersive than ever before. Amidst the player base, a user known as Hiroto Kuga has been gaining notoriety for his top-notch skills.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hokuto no Ken: Raoh Gaiden Ten no Haoh', 'TV', 13, 'Completed', '2008-10-03', '2008-12-26', '7', 'In the wastelands following the great nuclear war, a legend grew of a man.  “Hokuto No Ken.”  The Fist of the North Star.  Master of a legendary fighting technique.  A man of impossible strength and endurance.  Yet before Ken claimed the title of the Fist, there was another master, trained in the art of Hokuto Shinken, the King of the Fist, the Divine Fist of Heaven.  Raoh: the ultimate assassin, the ultimate warrior.  This is the story of the world before Fist of the North Star, and how one man took the future of a savage world into his deadly hands and reshaped its destiny.  Not as a hero but as a conqueror.  For in the mind of the man called Raoh, the only way to save Mankind is to grind it under his giant heel!  The greatest battle is about to begin in Legends of the Dark King ~ Fist of the North Star! 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon Crystal: Raikou Ikazuchi no Densetsu', 'Special', 1, 'Completed', '2001-12-30', NULL, '7', 'Kenta, a Pokemon master in the making, meets up with his childhood friend, Marina, at a Pokemon Center, to see how their skills have developed. Their battle is interrupted by a thunderstorm and the arrival of Bashou and Buson, two Roketto-Dan members using the Crystal System (which attracts Electric-type Pokemon). Their ultimate goal is to, under the guidance of Shiranui-hakase, bring Pokemon back to Sakaki. Kenta and Marina stumble upon this plan, and they try to stop it, but things get more difficult when the legendary Pokemon Raikou is captured.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dog Days', 'TV', 13, 'Completed', '2011-04-02', '2011-06-25', '7', 'Dog Days takes place in the world of Flonyard, an alternate Earth inhabited by beings who resemble humans, but also have the ears and tails of specific animals. The Republic of Biscotti, a union of dog-like citizens, has come under attack by the feline forces of the Galette Leo Knights. In an effort to save Biscotti, Princess Millhiore summons a champion from another world in order to defend her people. That champion is Cinque Izumi, a normal junior high student from Earth.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hyakujuu-Ou GoLion', 'TV', 52, 'Completed', '1981-03-04', '1982-02-24', '7', 'Golion, a powerful sentient robot, abuses his great powers by attacking and killing creatures known as Deathblack Beastmen, boasting that no one could defeat him. A divine space being punishes Golion for his arrogance and abuse by seperating him into 5 different lion robots. In the year 1999, a group of 5 young men return to Earth after a space voyage, only to find it ravaged by nuclear war. After encountering the alien race known as the Galra, the 5 youths end up on the planet Altea, and learn that the 5 lion robots that Golion was split into are in hibernation in various parts of Altea. Somehow, they must reunite the lions and form Golion, the only hope for the human race.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Futakoi Alternative', 'TV', 13, 'Completed', '2005-04-07', '2005-06-30', '7', 'The Futaba Detective Agency, being run by Rentarou, who has taken over the family business, after his father''s death 3 weeks ago. Along with Sara &amp; Souju, his live-in identical twin assistants. He ends up running afoul of the local Yakuza.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koukaku Kidoutai: SAC_2045 Season 2', 'ONA', 12, 'Completed', '2022-05-23', NULL, '7', 'The year is 2045. As a result of the Global Simultaneous Default, an economic disaster that shook every country on Earth to its foundations, as well as the explosive evolution of artificial intelligence, the world has plunged into the Sustainable War, a planned war that can be continued indefinitely. In this near future, the decline has not yet become bad enough that people can sense in their daily lives the risk to human survival posed by A.I.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Switch', 'OVA', 2, 'Completed', '2008-10-24', '2009-02-25', '7', 'Two new members of Japan''s Narcotics Control Department are tasked with dismantling the criminal network that supplies the deadly drug called Funny Angel (FA). While Haru Kurabayashi infiltrates the mafia branch that commercializes this drug, his partner Kai Etou starts working in a suspicious greenhouse that may harbor the FA production. As both agents grow closer to their objective, they are confronted with difficult choices that threaten to jeopardize the cover of each other.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lv2 kara Cheat datta Motoyuusha Kouho no Mattari Isekai Life', 'TV', 12, 'Completed', '2024-04-08', '2024-06-24', '7', 'When a humble merchant named Banaza is summoned to the magical kingdom of Klyrode in another world, the citizens hope he will become the hero who can take down the threatening Dark Army. Unfortunately, Banaza does not gain any exceptional powers at level one as hero candidates usually do, and he has no way of returning to his old world. As compensation, he is sent to live in a faraway forest. Upon arriving, Banaza levels up once and suddenly gains limitless powers that he now has no idea what to do with.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tentai Kansoku', 'ONA', 1, 'Completed', '2023-03-20', NULL, '7', 'The music film is a part of TOHO animation''s 10th anniversary project.', 290, 'https://cdn.myanimelist.net/images/anime/1722/132107.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Slam Dunk: Ketsui no Shouhoku Basket-bu', 'Special', 1, 'Completed', '1994-04-09', NULL, '7', 'This game was a practice match with Ryonan, and the debut match of amazing amateur Hanamichi Sakuragi. But adversity ignited the fighting spirit of the two men. Captain Akagi and rookie Rukawa, who have strong feelings for this year. The match turns into a dead end seesaw game due to the success of the two. And just before the end, the ball passed to Ryonan''s genius, Sendo. Follow the trajectory of rapid growth of Hanamichi. Haruko meets Hikoichi by chance and talks about each other''s teams.', 1030, 'https://cdn.myanimelist.net/images/anime/1208/124649.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Micchiri Neko', 'TV', 39, 'Completed', '2018-01-04', '2018-03-26', '7', 'The cute and mysterious cat-like creatures called Mitchiri Neko that seem to gather around each other if you leave them alone now get their own anime with a glorious voice cast! The free and happy-go-lucky Mitchiri Neko''s daily life is filled fluff and surreal laughs! Say it with me, "Mitchiri! Mitchiri!"
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kirakira☆Precure A La Mode Movie: Paritto! Omoide no Mille-Feuille!', 'Movie', 1, 'Completed', '2017-10-28', NULL, '7', 'I''m Usami Ichika! Myself and the others all decided to take part in a famous sweets contest that''s to be held in France♪ But Ciel doesn''t seem like herself...so making sweets and transforming into a Cure don''t go so well for her!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sakamoto desu ga? Sakamoto deshita?', 'Special', 1, 'Completed', '2016-09-26', NULL, '7', 'Sakamoto has it all: he is handsome, he excels at his studies, and there is no situation he cannot handle with style. Not having lost their admiration for him, Sakamoto''s former classmates recall the days when he graced the halls of their school before moving to America. As they imagine his life abroad, they figure that there is only one place suitable for their perfect friend—NASA. It seems that even in his absence, Sakamoto continues to enchant all who were lucky enough to meet him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kobato.: Hajimete no Kobato.', 'Special', 8, 'Completed', '2010-01-29', '2012-03-30', '7', 'Mini Flash anime from the limited-edition DVDs volumes (episodes 1-6) and Blu-ray Box (episodes 1-8, of which 7 and 8 were new additions to the Blu-ray box).', 538, 'https://cdn.myanimelist.net/images/anime/6/36685.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Overlord: Ple Ple Pleiades 2', 'ONA', 13, 'Completed', '2018-01-09', '2018-04-03', '7', 'Super deformed parody shorts of Overlord II streamed on Kadokawa''s official YouTube channel.', 945, 'https://cdn.myanimelist.net/images/anime/10/90101.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('IS: Infinite Stratos Encore - Koi ni Kogareru Rokujuusou', 'OVA', 1, 'Completed', '2011-12-07', NULL, '7', 'On a hot day of summer vacation, Charlotte''s plan to spend time alone with Ichika at his house is somewhat ruined when Cecilia gets the same idea, later followed by Houki, Lingyin and Laura. The next day, Houki helps out at a summer festival being held at her family''s shrine and is surprised when Ichika shows up.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hataraku Saibou CM', 'Special', 1, 'Completed', '2017-07-02', NULL, '7', 'A special animated commercial to celebrate the release of the manga''s fifth volume. The full length version of the commercial was released on Kodansha''s official YouTube channel the day after the short version was released on TV.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dagashi Kashi 2', 'TV', 12, 'Completed', '2018-01-12', '2018-03-30', '7', 'Second season of Dagashi Kashi.', 1021, 'https://cdn.myanimelist.net/images/anime/1649/90141.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yi Ren Zhi Xia', 'TV', 12, 'Completed', '2016-07-08', '2016-09-24', '7', 'When university student Zhang Chulan returns to his home village, he is devastated to learn that his grandfather Zhang Xilin''s grave has been desecrated. As he investigates the cemetery in search for clues, he is attacked by a tomb raider using the false identity of Zhang Xilin''s granddaughter. Left to die in a swarm of zombies summoned by the person who spirited his grandfather''s body away, Zhang Chulan manages to escape thanks to qi, the power that his grandfather taught him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koi to Senkyo to Chocolate: Koi Imouto!', 'Special', 1, 'Completed', '2013-03-27', NULL, '7', 'Unaired 13th episode released on the 7th DVD/BD.', 27, 'https://cdn.myanimelist.net/images/anime/3/83000.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yoku Wakaru Mahouka!', 'ONA', 6, 'Completed', '2014-02-22', '2014-09-13', '6', 'Special introduction videos posted on the official website.', 538, 'https://cdn.myanimelist.net/images/anime/3/60355.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cookin'' Idol Ai! Mai! Main!', 'TV', 305, 'Completed', '2009-03-30', '2013-03-22', '6', 'Cooking Idol teaches children how to cook through instruction of the main character, MAIN. The show itself is divided into an animated segment featuring MAIN, and a live-action segment featuring the voice actor of MAIN, Fukuhara Haruka, as she practices the cooking herself. The live-action segment is not included in the avg episode duration.', 879, 'https://cdn.myanimelist.net/images/anime/13/73550.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Getter Robo Go', 'TV', 50, 'Completed', '1991-02-11', '1992-01-27', '6', 'A new Getter robot is piloted by three youth as they combat the evil terrors that plague the world.', 1030, 'https://cdn.myanimelist.net/images/anime/1171/134638.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tanoshii Willow Town', 'TV', 26, 'Completed', '1993-10-07', '1994-03-31', '6', 'Kenneth Grahame''s enchanting novel The Wind in the Willows (1908) is the basis for a series about the happy little world of the animals who live along the riverbank. Toad''s boastful nature and the evil ferrets and weasels who live in the Wild Wood threaten everyone''s quiet lives until the brave Ratty, Mole, Badger, and Toad band together to ensure that they can all live happily ever after.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tatakae!! Ramenman', 'TV', 35, 'Completed', '1988-01-10', '1988-09-11', '6', 'Set in a land where several martial arts styles collide, including (but not limited to) Chinese Kung Fu, Japanese Karate, and South Korean Taekwondo. Yet amongst these Shaolin-trained fighters and men powerful enough to cut the face of a mountain, Victory Ramenman is said to be the strongest of them all. At a young age, he witnessed his father Somenman being murdered by members of the Cobra Gang (who are still running rampant to this day). Found and taken in by the wise old Chen Sou-Mei, Ramenman trains for 12 years under his master and learns the great Essential Battle Dragon (闘龍極意書, To Ryuu Gokui Sho) style of Choujin Martial arts. Now, with his young sidekick Shao-Mai, Ramenman travels the land seeking vengeance for his father, fighting several villains along the way.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mamono-tachi no Kunou', 'ONA', 12, 'Completed', '2020-10-10', '2020-12-24', '6', 'Chibi shorts to Maou-jou de Oyasumi released on the anime''s Twitter page.', 241, 'https://cdn.myanimelist.net/images/anime/1674/112039.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mafukiden: Pandarian', 'TV', 26, 'Completed', '2005-01-08', '2005-07-09', '6', 'It follows the story of a fairy named Mi who is sent to Planet Pandasia to warn the residents about a great evil that threatens to destroy Pandasia. She chooses a heroic panda named Toby to defeat Gold and Silver, two villains who want to collect the seven Beans of Power and rid Pandasia of its colorful, beautiful environment and replace it with a dark wasteland.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Puchitto Gargantia', 'ONA', 13, 'Completed', '2013-04-10', '2013-07-03', '6', 'Short episodes streamed on the anime''s official site after every episode, giving background information about the show.', 945, 'https://cdn.myanimelist.net/images/anime/7/49979.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zettai Bouei Leviathan', 'TV', 13, 'Completed', '2013-04-06', '2013-07-06', '6', 'The story is set in Aquafall, a fantasy world abound with water and greenery, and populated by dragons and fairies. Meteorites suddenly bring forth evil creatures that threaten all living things on the planet. The fairy Syrup assembles the Aquafall Defense Force, with three girls of the dragon clans as recruits. The story follows Syrup and the dragon girls Leviathan, Bahamut, and Jörmungandr as they work together to battle enemies and grow up.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kunimatsu-sama no Otoridai', 'TV', 46, 'Completed', '1971-10-06', '1972-09-25', '6', 'A comedy about a group of kids forming a school baseball team, with the leader being very stubborn and argumentative.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chouon Senshi Borgman', 'TV', 35, 'Completed', '1988-04-13', '1988-12-21', '6', 'Sonic Soldier Borgman is a science fiction that comebines super sentai with non-gattai. It features a sentai-like three members team that fight an organization known as Youma. Features three characters with three basic ranger colors: Pink, Blue and Green. Featuring three main characters: Chuck, Ryo and Anise, Ryo is the leader, Chuck and Anise are teachers at a public school. Sometimes, the students help or make troubles to the Borgman somehow, some even know the Borgman secret identities. Ryo has a talking "modern" blue motorcycle that can upgrade itself. The transformation code is "Borg. Get On". Each member has a personal cannon that matches his/her armor color that appears only to finish the monster they fight.', 92, 'https://cdn.myanimelist.net/images/anime/11/23045.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('King of Fighters: Another Day', 'ONA', 4, 'Completed', '2005-12-02', '2006-03-03', '6', 'The four episodes are set in Southtown, the imaginary city well known to all fans as the stage of numerous death matches throughout the KOF series. Many past heroes of the saga make their appearance here, and the four plots intertwine to create a large-scale drama, that is also linked to the story of KOF Maximum Impact 2.', 704, 'https://cdn.myanimelist.net/images/anime/3/12676.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Happy☆Lucky Bikkuriman', 'TV', 46, 'Completed', '2006-10-15', '2007-09-30', '6', 'Continuation of the Bikkuriman Series.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Barbapapa', 'TV', 45, 'Completed', '1974-10-13', '1975-09-28', '6', 'Barbapapa and his family can turn into anything they want. Each member of the family has his or her own personality. Very good show for the youngest children as each episode deals with another problem they will recognize in a way that is ''morally correct''.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Heibai Wushuang 3rd Season', 'ONA', 12, 'Completed', '2021-07-19', '2021-09-27', '6', 'Third season of Heibai Wushuang.', 1098, 'https://cdn.myanimelist.net/images/anime/1604/115814.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Angelique', 'OVA', 3, 'Completed', '2004-03-17', '2005-03-23', '6', 'One woman, simply known as The Queen, rules over the universe. By harnessing the elemental powers of her nine Guardians, she nurtures life on many planets. When it is time for The Queen to appoint a successor, she sees promise within two young maidens, Angelique Limoges and Rosalia de Catargena, and she gives them a test: utilize the power of the Guardians to cultivate life and prosperity on an uninhabited planet. However, Angelique is much less prepared than her rival; she must carefully foster relationships with the Guardians if she stands any chance at success.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Touma Kishinden Oni', 'TV', 25, 'Completed', '1995-10-05', '1996-03-21', '6', 'Shuramaru is hated and feared by the villagers for his unusual powers. He thinks he is human, but... is he?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Guskou Budori no Denki (2012)', 'Movie', 1, 'Completed', '2012-07-07', NULL, '6', 'The fairy tale follows a young man named Budori Gusuko in the Tohoku forests of northeastern Japan in the 1920s. After an onslaught of droughts and natural disasters, Budori is forced to leave his home and search for a better life elsewhere. Budori joins a group of scientists at the Ihatov Volcano Department, which deals with the same natural disasters that drove Budori from his home.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shiranpuri (Special)', 'Special', 1, 'Completed', '2012-03-20', NULL, '6', 'When a young boy witnesses Yaragase and his gang bully his classmate Don, he becomes incredibly uncomfortable. Unable to intervene out of fear of becoming their next target, the young boy decides to mind his own business. As Yaragase''s tormenting becomes increasingly worse, the boy''s sense of guilt continues to grow. After he talks to an oden stand owner who believes that people who watch and do nothing are just as bad as those bullying, will the young boy be able to end his classmate''s misery?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Genmu Senki Leda', 'OVA', 1, 'Completed', '1985-03-01', NULL, '6', 'For a year and a half, Youko Asagiri has fostered an unrequited love for one of her classmates. To express her affection, she composes a piano solo that she plans to show him when she confesses. When the moment of truth comes, however, Youko is not brave enough to speak to her classmate, and the ground suddenly swallows her up!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yurumates 3D', 'TV', 13, 'Completed', '2012-04-03', '2012-06-26', '6', 'Yurume, an 18-year-old "ronin" and recent high school graduate, has high hopes of being accepted and attending Tokyo University. She moves into an apartment complex, the Maison du Wish, located on the outskirts of Tokyo where other ronins living there are studying for upcoming college acceptance exams.', 152, 'https://cdn.myanimelist.net/images/anime/3/36705.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchuu no Kishi Tekkaman Blade II', 'OVA', 6, 'Completed', '1994-07-21', '1995-04-21', '6', '10 years have passed since the end of the last war against the radam. A new team of Space Knights has been assembled under the lead of Aki and D-boy. The first mission of the new tekkaman is to defeat the radam but then, they have to fight against a remnent from the past.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Geobreeders: File-X Chibi Neko Dakkan', 'OVA', 3, 'Completed', '1998-05-21', '1998-10-21', '6', 'Taba and the Girls of Kagura Total Security Inc. specialize in jobs where their enemy are "Phantom Cats". They have a few run ins with the various Government agencies, as well as a gang of Phantom Cats; blowing up a lot of stuff along the way. When one of their own is kidnapped, they have to get her back.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchuu Senkan Yamato 2199: Hoshimeguru Hakobune Picture Drama', 'Special', 3, 'Completed', '2015-05-27', NULL, '6', 'Picture dramas from the DVD/BDs.', 1117, 'https://cdn.myanimelist.net/images/anime/1441/116136.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('MonHun Nikki Girigiri Airou Mura: Airou Kiki Ippatsu', 'TV', 10, 'Completed', '2010-08-05', '2010-10-07', '6', 'A flash anime featuring Airuu, the helper cats in the original Monster Hunter game.', 214, 'https://cdn.myanimelist.net/images/anime/9/25713.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('"Eiyuu" Kaitai', 'OVA', 1, 'Completed', '2016-11-23', NULL, '6', 'Uro Yamada works as part of the "Hero Retirement and Return to Everyday Life Assistance Agency," which takes heroes from another world back to Earth and helps them reintegrate into everyday life.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Itazura Majo to Nemuranai Machi', 'ONA', 1, 'Completed', '2017-12-01', NULL, '6', 'The story is set in New York which is lit up with Christmas lights. Tokyo Metropolitan Police officer Akari Kido is directing traffic while on her international exchange training program, when a witch-like character pulls a "Christmas Party" prank. Just before a runaway trailer truck smashes into Akari, a mysterious girl suddenly appears and shouts, "I''m going to protect New York and Akari!"  
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chuldong! Super Wings', 'TV', 52, 'Completed', '2013-09-01', '2016-02-25', '6', 'Super Wings follows the adventures of an adorable jet plane named Jett who travels around the world delivering packages to children. On every delivery, Jett encounters new problems that he must solve with the help of his friends the "Super Wings": Dizzy, Jerome and Donnie. Together, the team explores different countries and learns the diversity of new cultures.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Honoo no Alpenrose: Ai no Symphony Ongaku-hen', 'OVA', 1, 'Completed', NULL, NULL, '6', 'A music-video style recap OVA. This release covers episode 12-20 and is with classical music entirely except for one song right before the credits. The beginning also has a unique frosted boarder frame around the video that changes designs which was not present in the the first music recap nor in the original anime.', 1009, 'https://cdn.myanimelist.net/images/anime/11/85888.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Green Co-Op CMs', 'Special', 5, 'Completed', '2017-12-15', '2019-04-01', '6', 'Green Co-Op''s commercials created by Yoshiharu Satou.', 1050, 'https://cdn.myanimelist.net/images/anime/1145/97985.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dongguo Xiaojie', 'ONA', 15, 'Completed', '2016-12-26', '2017-04-10', '6', 'Dongguo Xiaojie, a young girl, has lived together with her mother ever since she was little. On the year she turned sixteen, her mother suddenly contracted a "Grave Illness". To save her mother, Dongguo Xiaojie set foot into the unknown on a dangerous journey. Accompanying her on this journey is her sworn elder brother Mo Zixuan and the mysterious youth, Life''s Hardship. However, danger arises again and again as they are continuously attacked by people they meet on their journey. Just what conspiracy is hidden behind this journey?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ganbare! Kakure Ase Project', 'ONA', 1, 'Completed', '2019-05-17', NULL, '6', 'An animated commercial for Kao Biore Sarasara Powder Sheets focuses less on a personal hygiene routine, instead opting to tug at viewers'' heartstrings. The ad stars three high school friends, one a flutist named Mina and the other a burgeoning photographer named Akane. Mina finds herself getting wistful as the school year is drawing to a close but through the encouragement of her friends (and some well-timed product placement) she''s reinvigorated to make the year the best it can be. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tenki no Ko CMs', 'Special', 8, 'Completed', '2019-06-30', '2019-01-01', '6', 'Tenki no Ko received an assortment of collaboration commercials with original footage. So far: Suntory the beverage company, SoftBank the technology conglomerate, Baitoru the job search company, and Misawa Homes the real estate company have participated.', 270, 'https://cdn.myanimelist.net/images/anime/1959/101750.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyokou Suiri Mini Anime', 'ONA', 38, 'Completed', '2019-11-15', '2020-02-10', '6', 'Short episodes with super-deformed characters posted on the official Twitter account. Includes the extra episode commemorating the BD/DVD releases.', 39, 'https://cdn.myanimelist.net/images/anime/1597/108435.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nippon-ichi no Otoko no Tamashii', 'TV', 16, 'Completed', '1999-01-05', '1999-01-29', '6', 'Tales of sex and sadomasochism, based on the manga in Young Sunday by Masahiko Kikuni, creator of Kizu darake no Tenshi-tachi (Heartbroken Angels). With a TV share of 9.1% in the graveyard slot, it was broadcast daily as part of the Wonderful anthology program.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ji Jia Shou Shen: Baolie Feiche', 'TV', 40, 'Completed', '2016-03-14', '2016-04-21', '6', 'Bang! One day, the Universe exploded! The explosion produced a number of light crystals which scattered in the Earth and became energy coins. Some energy life entities also came to the Earth and existed as mini cars to chase light crystals. Once those mini cars grasped light crystals, they would return to their original forms. A group of evil attempted to plot against the Earth with the super power of light crystals. To protect the Earth, the righteous kids Hawley, Kinson and Yolan help the mini cars of the justice side to collect energy coins. Armed with Eagle Car and Dragon Car, the two brothers are ready to fight against the Commander-K leaded evil force. The war is on…
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bonobono', 'Movie', 1, 'Completed', '1993-11-13', NULL, '6', 'The first theatrical Bonobono movie.', 351, 'https://cdn.myanimelist.net/images/anime/7/22162.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Backkom Specials', 'ONA', 8, 'Completed', '2007-01-01', '2013-01-01', '6', 'ONAs posted on the official site of RG Studios'' page and the director''s youtube page that feature Backkom shorts that never made it to the main series nor the the DVD release of the main series.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hana to Shounen', 'OVA', 1, 'Completed', '2004-01-01', NULL, '5', 'Yuji and Koichi set off on a journey to find a rare bamboo flower for a school project. In the forest they encounter a legendary phoenix who asks for their help to save the forest.', 1030, 'https://cdn.myanimelist.net/images/anime/4/61379.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koroshiya-san: The Hired Gun', 'TV', 10, 'Completed', '2013-10-11', '2013-12-13', '5', 'The comedy story follows the title character, who is regarded by himself and others as the best hit man in Japan. He goes by the motto, "If I have an assignment, I will kill anything." However, his "killing" assignments have expanded to include everything from summer vacation homework to housekeeping. "The hit man never fails to kill the target. Though he does not aim to, he also never misses the laughter."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gundam: Mission to the Rise', 'Special', 1, 'Completed', '1998-08-01', NULL, '5', 'In the late Universal Century, the Earth Federation enacts an attempt to propel a craft at faster-than-light speeds. Zeon forces attack the launch facility in space and destroy it, but not before the craft can be successfully deployed.', 974, 'https://cdn.myanimelist.net/images/anime/6/8685.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ali Baba to 40-hiki no Touzoku', 'Movie', 1, 'Completed', '1971-07-18', NULL, '5', 'A film produced for Toei''s 20th anniversary. A boy who is the descendant of the leader of the theives who met a grisly fate in the 1001 Nights bands together with 38 cats and a mouse to get back his rightful treasure from Ali Baba XXXIII, the descendent of Ali Baba who now rules the kingdom with an iron fist. This is a reversal of the good guy/bad guy roles in the original story! (perhaps not surprising for being a film in which Hayao Miyazaki was involved) This film is one of the most rollicking and action-packed films made by Toei, and is in an outrageously cartoonish style breaking with the Toei mold. It has a spectacular lineup of animators including Yasuji Mori, Akira Daikubara, Hayao Miyazaki, Yoichi Kotabe and Reiko Okuyama. The original story about Ali Baba and the 40 Thieves itself is recounted at one point in the film in an unexpected and interesting way using shadow-puppets. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nayuta', 'OVA', 1, 'Completed', '1986-07-31', NULL, '5', 'Scifi tale of a young girl who acquires ESP powers. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hana no Asukagumi! 2: Lonely Cats Battle Royale', 'OVA', 1, 'Completed', '1990-03-23', NULL, '5', 'Second OVA of "Hana no Asukagumi!".', 1030, 'https://cdn.myanimelist.net/images/anime/2/45979.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Virus: Virus Buster Serge', 'TV', 12, 'Completed', '1997-10-03', '1997-12-19', '5', 'Neo Hong Kong, 2097: The world has changed. Advances in genetic engineering and cybernetics have created an environment full of artificially enhanced humans and intelligent super-computers that operate using biological software. But the same technology that has allowed man and machine to merge has made both susceptible to a new kind of threat—digital viruses capable of controlling their hosts.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yajikita Gakuen Douchuuki', 'OVA', 2, 'Completed', '1989-09-15', '1991-07-25', '5', 'Shinokita Reiko and Yajima Junko are second-year high school students who travel from school to school fighting bad guys, ninjas, yakuza and corruption. At this high school they encounter a secret ninja order and a corrupt administrator, as well as a tragic death in the distant past. With the help of Kotetsu, a skilled ninja, they set the school to rights, but not before leaving several broken hearts behind.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Choushin Hime Dangaizer 3', 'OVA', 4, 'Completed', '1999-10-08', '2001-03-23', '5', '10,000 years ago, acting as judge, jury and executioner, Dangaizer sealed the fate of mankind by reducing it to ashes. Slowly, mankind rebuilt their civilization and once again stands at its peak. Hiding amongst the survivors of mankind, the evil organization of Goma lies in wait for the return of Dangaizer. This time, it’s a race to stop the awakening of the 3 that can pilot Dangaizer and subjugate the world to their rule. Will the 3rd pilot learn her true destiny and awaken in time, or will the world find a new destiny in the hands of Goma?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cyborg 009: The Reopening', 'Special', 1, 'Completed', '2010-10-05', NULL, '5', 'A short 3D CGI anime of Cyborg 009 produced by director Oshii Mamoru.', 704, 'https://cdn.myanimelist.net/images/anime/5/26666.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Isekai Cheat Magician', 'TV', 12, 'Completed', '2019-07-10', '2019-09-25', '5', 'Regular high schooler Taichi Nishimura and his childhood friend, Rin Azuma, are on their way to school one ordinary morning. Suddenly, a glowing light envelops them, transporting them to a fantasy world full of magical creatures.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('SpoGomi: World Cup Exhibition Match-hen', 'ONA', 1, 'Completed', '2022-03-17', NULL, '5', 'In the near future, litter-picking has become a competitive sport as popular as soccer.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Matter', 'Special', 1, 'Completed', '2017-01-01', NULL, '5', 'Animation for Design Art Fair (Seoul Art Center, 2017)
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kakyuusei (TV): Hajimemashite Tina!', 'Special', 1, 'Completed', '2000-03-24', NULL, '5', 'An unreleased episode of Kakyuusei (1999) that was available on the 7th VHS/DVD. It is set in an alternate universe where Ai and Miko aren''t the main heroines. It focuses on Tina''s (an alien who can fly) love conquest of Tsuyoshi. Tina, along with several other characters featured, were absent from the main series.', 659, 'https://cdn.myanimelist.net/images/anime/1453/153871.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jintian Kaishi Zuo Mingxing: Tianshi Qingge', 'ONA', 1, 'Completed', '2021-08-03', NULL, '5', 'Recap of Jintian Kaishi Zuo Mingxing.', 42, 'https://cdn.myanimelist.net/images/anime/1158/141557.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eri', 'Movie', 1, 'Upcoming', NULL, NULL, '5', 'Eri, a Holstein cow, lives in a mountain ranch enclosed by a fence. One day, Jersey cows arrive from the outside. Among them is Sou, with whom Eri falls madly in love at first sight.  In order to refine her feeling of love for Sou, Eri submits herself to various trials.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bikkuriman: Daiichiji Seima Taisen', 'Movie', 1, 'Completed', '1988-03-12', NULL, '5', 'First Bikkuriman film.', 1030, 'https://cdn.myanimelist.net/images/anime/1436/97580.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bikkuriman: Muen Zone no Hihou', 'Movie', 1, 'Completed', '1988-07-09', NULL, '5', 'The second movie version of the popular "Bikkuriman" first TV anime series. The vast dark world outside the heavenly world, the unrelated zone. Head Rokoko and the six god-emperors were traveling there with St. Big Bird. Before long, they rescued a girl who was a talisman (those who cooperated with angels), Suisai, who was being attacked by Kuuma. However, Yamato lost consciousness in the middle of the battle, and eventually came to his senses However, a secret crisis was approaching the heaven and earth. Contents depicting an incident that is not told on TV in the latter half of the TV series. In the world of "Bikkuriman", the theme was the world of "omamori", the third race following angels and demons.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Insect Land', 'TV', 22, 'Completed', '2022-04-04', '2022-08-29', '5', 'Anime based on "nature learning picture books" which explore the lives of insects, while also celebrating the themes of ecology and diversity.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahoutsukai no Yoru', 'Movie', 1, 'Upcoming', NULL, NULL, '5', 'Set near the end of the Showa period in the late 1980s, an old mansion in Misaki Town is rumored to be the home of a witch.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Baby-Hamitang', 'TV', 6, 'Completed', '2022-01-12', '2022-02-16', '5', 'The episodes will present topics from the list of 17 Sustainable Development Goals (SDG) such as global warming, food waste, and gender equality, in an easy-to-understand manner. Baby Hamitang will then solve the issues.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wo Wei Ge Kuang', 'TV', 52, 'Completed', '2001-08-06', '2002-01-01', '5', 'Four young teenage boys share a common vision and passion for music. They come together overlapping their own personalities and ideas. In the process, they encounter a lot of difficulties as any youth might have. The story is unfolded as the band grows up. Academic, personal conflicts, family, friendship and emotional problems are all intertwined. With the help of teachers, students, and friends they try to achieve their dreams.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tonari no Tokoro', 'OVA', 1, 'Completed', '1990-05-25', NULL, '5', 'Based on the original story by famous Japanese comedian George Tokoro.', 674, 'https://cdn.myanimelist.net/images/anime/4/27209.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bit the Cupid', 'TV', 48, 'Completed', '1995-04-26', '1996-03-29', '5', 'Comedy about a character who shoots arrows that cause pairs of people to fall madly in love and float about in an ecstasy of emotion.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hanasaka Tenshi Tenten-kun', 'TV', 43, 'Completed', '1998-10-10', '1999-09-25', '5', 'A foolish clumsy angel came to the human world to help a very unlucky boy. But more accidents are then created...', 607, 'https://cdn.myanimelist.net/images/anime/4/27207.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Harimogu Harry', 'TV', 140, 'Completed', '1996-08-05', '1997-06-27', '5', 'Story of Harry and his animal friends going to a school.', 414, 'https://cdn.myanimelist.net/images/anime/13/29632.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('MonHun Nikki Girigiri Airou Mura: Airou Kiki Ippatsu Specials', 'Special', 2, 'Completed', '2010-11-24', NULL, '5', 'Two unaired episodes included with the Blu-ray and the DVD.', 214, 'https://cdn.myanimelist.net/images/anime/9/27156.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tegamibachi', 'TV', 25, 'Completed', '2009-10-03', '2010-03-27', '8', 'Gauche Suede is highly respected among the Letter Bees—a government organization that delivers written messages to even the most remote locations. However, the Amberground, the land Gauche must traverse, is blanketed in a constant twilight and home to monsters known as Gaichuu. On one precarious journey, Gauche meets Lag Seeing, a troubled young boy who has himself been sent as a letter.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('D4DJ First Mix', 'TV', 13, 'Completed', '2020-10-30', '2021-01-29', '8', 'Having lived abroad in Africa for most of her life, Rinku Aimoto is now returning to Japan to attend Yoba Academy, a school where DJ units—groups made up of DJs, vocalists, and dancers—are extremely popular. There, she meets Maho Akashi, an aspiring DJ who teaches Rinku the basics of DJing. The girls attend a performance by Yoba''s famous DJ unit Peaky P-key, and struck by inspiration, they decide to form a unit of their own.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tianbao Fuyao Lu', 'ONA', 13, 'Completed', '2020-07-05', '2020-09-20', '8', 'Having lived his entire life on Mount Taiheng, half-yao Kong Hongjun is at last presented with the chance to explore the human world. He is assigned three tasks: uncover his father''s murderer, eliminate the Black Jiao and its yao tribes that have infiltrated Chang''an, and return the Heart Lamp to a descendent of the Chen family. However, on his first night in the city, the Heart Lamp is mistakenly absorbed by military general Li Jinglong.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chrno Crusade', 'TV', 24, 'Completed', '2003-11-25', '2004-06-10', '8', 'The 1920s was a decade of great change and upheaval, with monstrous demons appearing across America. To combat this menace, the holy organization known as the Order of Magdalene was established. The organization''s New York branch is home to the young and reckless Sister Rosette Christopher, as well as her partner Chrno. Tasked with the extermination of demonic threats, the renowned team is excellent at their job, despite causing extensive collateral damage on their missions.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tensura Nikki: Tensei shitara Slime Datta Ken', 'TV', 12, 'Completed', '2021-04-06', '2021-06-22', '8', 'In between slaying monsters and negotiating with neighboring countries, Rimuru Tempest has his hands full attending to his kingdom alongside day-to-day matters. But whether it''s expanding the farms in the summer heat or shoveling snow in the chilly winter, no task is too big for Rimuru and his friends!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ani ni Tsukeru Kusuri wa Nai! 4', 'TV', 12, 'Completed', '2020-10-02', '2020-12-18', '8', 'Shi Miao has a lot of experience dealing with her older brother''s peculiar habits. After all her scolding, it is natural to expect that Shi Fen''s antics would come to an end. But having spent their whole life together, it is obvious to Miao that some things never change—and maybe that is for the best.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toaru Hikuushi e no Tsuioku', 'Movie', 1, 'Completed', '2011-10-01', NULL, '8', 'The war between the Levamme Empire and the Amatsukami Imperium has been raging for years. In the midst of this struggle, the prince of the Levamme Empire declares his love for Juana del Moral and vows to end the war in one year, as part of his marriage proposal. When the Amatsukami catch wind of this, they assault the del Moral residence, targeting Juana''s life. As a last ditch effort to bring the prince his bride, the San Maltilia Airforce hires a mercenary of mixed blood—a bestado—to fly Juana to the Levamme capital in secret. The pilot, Charles, accepts the mission...but traversing an ocean alone, into enemy territory, proves a much more dangerous ordeal than anyone could have anticipated.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hellsing: Digest for Freaks', 'OVA', 1, 'Completed', '2006-01-22', NULL, '8', 'This OVA is a summary of the first three episodes of Hellsing, with the animation style of Hellsing Ultimate and following the events of the Hellsing manga.', 780, 'https://cdn.myanimelist.net/images/anime/7/26935.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ashita no Nadja', 'TV', 50, 'Completed', '2003-02-02', '2004-01-25', '8', 'This story takes place about one hundred years ago. Nadja is a bright, cheerful girl who was raised in an orphanage near London, England. Nadja was entrusted to the orphanage when she was a baby. So she thought her father and mother were dead. But before her thirteenth birthday, she found out that her mother might be alive..
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kekkaishi', 'TV', 52, 'Completed', '2006-10-16', '2008-02-05', '8', 'Yoshimura Sumimura comes from a long line of "Kekkaishi," individuals who have supernatural abilities and are able to destroy evil creatures called Ayakashi that venture into the human realm from time to time. The Ayakashi are demons that look to feast on the power emanating from the land of Karasumori, which also happens to be where Yoshimura''s high school is located. Now, Yoshimura must fight to protect his beloved school and hometown. Although, if it were up to him, he would rather be baking cakes than fighting off the ugly characters that show up at night.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yahari Ore no Seishun Love Comedy wa Machigatteiru. OVA', 'OVA', 1, 'Completed', '2013-09-19', NULL, '8', 'One morning, Hachiman Hikigaya contemplates the superfluous nature of marriage and its misleading image of happiness. However, he is forced into confronting his skepticism when the Volunteer Service Club is tasked with assisting a local municipal magazine advertise the allure of marriage to younger people. Unfortunately, neither the club''s advisor, Shizuka Hiratsuka, nor the other club members have any firsthand experience with the subject. With only one week until the deadline, the group must quickly learn about the intricacies behind the special ceremony, even if they have to resort to more creative means!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Prison School', 'TV', 12, 'Completed', '2015-07-11', '2015-09-26', '8', 'Located on the outskirts of Tokyo, Hachimitsu Private Academy is a prestigious all-girls boarding school, famous for its high-quality education and disciplined students. However, this is all about to change due to the revision of the school''s most iconic policy, as boys are now able to enroll as well.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('White Album 2', 'TV', 13, 'Completed', '2013-10-06', '2013-12-29', '8', 'Haruki Kitahara''s light music club is on the verge of disbanding. At this rate, the third year''s dream of performing at the school festival would never be realized. However, as his exhausted fingers drift through the chords of "White Album," the first song he would ever play, an angelic voice and mysterious piano begin harmonizing with his lonely guitar. It is a momentous performance that marks the beginning of everything for Haruki.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Top wo Nerae 2! Diebuster', 'OVA', 6, 'Completed', '2004-10-03', '2006-08-25', '8', 'Generations have passed since the war with the Space Monsters started, and none remain who know how it began, with even records of those times being scarce. It is a lost cause, but humanity still fights against them, relying on the "Topless": a group of elite space pilots with special powers that allow them to use the Buster Machines—the last hope against the Space Monsters.  
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Initial D Battle Stage', 'OVA', 1, 'Completed', '2002-05-15', NULL, '8', 'There are many street races in the Initial D Series. This OVA has no plot other than to collect all the street races into one stage. The dialog during the original races is left in.', 674, 'https://cdn.myanimelist.net/images/anime/2/13168.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hoshiai no Sora', 'TV', 12, 'Completed', '2019-10-11', '2019-12-27', '8', 'Constantly outperformed by the girls'' club, the boys'' soft tennis club faces disbandment due to their poor skills and lack of positive results in matches. In desperate need of members, Touma Shinjou is looking to recruit capable players, but he fails to scout anyone. Enter Maki Katsuragi, a new transfer student who demonstrates great reflexes when he catches a stray cat in his classroom, instantly capturing Touma''s attention. With his interest piqued, Touma ambitiously asks Maki to join the boys'' team but is quickly rejected, as Maki doesn''t wish to join any clubs. Touma refuses to back down and ends up persuading Maki—only under the condition that Touma will pay him for his participation and cover other club expenses. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kekkai Sensen', 'TV', 12, 'Completed', '2015-04-05', '2015-10-04', '8', 'Supersonic monkeys, vampires, talking fishmen, and all sorts of different supernatural monsters living alongside humans—this has been part of daily life in Hellsalem''s Lot, formerly known as New York City, for some time now. When a gateway between Earth and the Beyond opened three years ago, New Yorkers and creatures from the other dimension alike were trapped in an impenetrable bubble and were forced to live together. Libra is a secret organization composed of eccentrics and superhumans, tasked with keeping order in the city and making sure that chaos doesn''t spread to the rest of the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Initial D: Project D to the Next Stage - Project D e Mukete', 'Special', 1, 'Completed', '2003-03-22', NULL, '8', 'A special that comes with the Fourth Stage DVD-BOX. It is comprised of a recap from First Stage to Third Stage, along with staff commentary and sneak preview of the making of the Fourth Stage.', 17, 'https://cdn.myanimelist.net/images/anime/12/35739.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bokura no', 'TV', 24, 'Completed', '2007-04-09', '2007-09-25', '8', 'As fifteen children at a summer camp enjoy their carefree vacation together, they stumble upon a small cave near the beach. The group finds a mysterious room deep within its caverns, where they meet a strange man who calls himself Kokopelli. The man invites the children to play a game that involves taking turns controlling a robot to protect the Earth against aliens. Thinking it might be an interesting computer game, all but one of the children sign a contract agreeing to play.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fuufu Ijou, Koibito Miman.', 'TV', 12, 'Completed', '2022-10-09', '2022-12-25', '8', 'Third-year high school student Jirou Yakuin is in love with his childhood friend and classmate, Shiori Sakurazaka. Thus, he hopes to be paired with her for the marriage practical: their school''s practice of randomly selecting boy-girl pairs to live as pretend married couples while monitoring and rating them on how close they have gotten. Meanwhile, the lively Akari Watanabe wants to be assigned to her crush, the popular and good-looking Minami Tenjin.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Free! Movie 1: Timeless Medley - Kizuna', 'Movie', 1, 'Completed', '2017-04-22', NULL, '8', 'Haruka Nanase has reconciled with his rival Rin Matsuoka, and they have re-established their friendship, determined to race each other again. Now Haruka, along with Makoto Tachibana, Rei Ryuugazaki, and Nagisa Hazuki, prepare for their upcoming tournaments, determined to compete wholeheartedly and achieve victory as a team. At Samezuka Academy, Rin resolves to do the same.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xian Ni Movie: Shenlin Zhi Zhan', 'ONA', 1, 'Completed', '2025-05-30', NULL, '8', 'After Wang Lin''s arrival in the Ancient God Land, the Eternal Night Demon City in the Demon Cultivation Sea rose overnight, continuously attacking the surrounding sects. During the battle to defend the gate, Li Muwan was poisoned, her life hanging in the balance. Upon learning of this, Wang Lin took her back to the Demon Cultivation Sea, revealing a thousand-year conspiracy...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zenshuu.', 'TV', 12, 'Completed', '2025-01-05', '2025-03-23', '8', 'After graduating from high school, Natsuko Hirose starts her career as an animator. Her talent quickly flourishes, and she makes her debut as a director in no time. Her first anime becomes a massive hit, sparking a social phenomenon and earning her recognition as an up-and-coming genius director. Her next project is set to be a romantic comedy movie themed around first love! However, having never been in love herself, Natsuko struggles to understand the concept of first love, and as a result, she''s unable to create the storyboard, causing the movie production to come to a standstill. One day, she passes out while working on her storyboard and wakes up in the world of her favorite childhood anime movie "A Tale of Perishing."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sengoku Youko: Senma Konton-hen', 'TV', 22, 'Completed', '2024-07-18', '2024-12-26', '8', 'The chaotic aftermath of a confrontation between Jinka Yamato and Yazen results in the power dynamics between the magically gifted katawara and humans being turned upside down. As the news of the downfall of dangaishu—the katawara-hunting monks led by Yazen—spreads across the country, rogue groups of katawara start to form, worsening the already-fragile relationship between them and humanity.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mimi wo Sumaseba', 'Movie', 1, 'Completed', '1995-07-15', NULL, '8', 'Shizuku Tsukishima is an energetic 14-year-old girl who enjoys reading and writing poetry in her free time. Glancing at the checkout cards of her books one evening, she notices that her library books are frequently checked out by a boy named Seiji Amasawa. Curiosity strikes Shizuku, and she decides to search for the boy who shares her love for literature.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boku no Hero Academia 6th Season', 'TV', 25, 'Completed', '2022-10-01', '2023-03-25', '8', 'With Tomura Shigaraki at its helm, the former Liberation Army is now known as the Paranormal Liberation Front. This organized criminal group poses an immense threat to the Hero Association, not only because of its sheer size and strength, but also the overpowering quirks of Jin "Twice" Bubaigawara and Gigantomachia.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Trigun', 'TV', 26, 'Completed', '1998-04-01', '1998-09-30', '8', 'Vash the Stampede is the man with a $$60,000,000,000 bounty on his head. The reason: he''s a merciless villain who lays waste to all those that oppose him and flattens entire cities for fun, garnering him the title "The Humanoid Typhoon." He leaves a trail of death and destruction wherever he goes, and anyone can count themselves dead if they so much as make eye contact—or so the rumors say. In actuality, Vash is a huge softie who claims to have never taken a life and avoids violence at all costs.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tengoku Daimakyou', 'TV', 13, 'Completed', '2023-04-01', '2023-06-24', '8', 'Fifteen years ago, disaster struck human civilization, and now dangerous man-eating monsters roam the ravaged lands, posing an existential threat to the remaining survivors. Amid this turmoil, an isolated facility shelters children and nurtures them in peace. However, as a few among them find out about the world beyond the narrow periphery of their nursery''s walls, their curiosity about it slowly grows.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sono Bisque Doll wa Koi wo Suru Season 2', 'TV', 12, 'Completed', '2025-07-06', '2025-09-21', '8', 'After Marin Kitagawa introduced Wakana Gojou to the world of cosplay, he has been creating her outfits with ease. Even so, he still has a lot to learn, and every new lesson seems to strengthen his love for sewing and for the hina dolls his grandfather taught him to make.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ore dake Level Up na Ken', 'TV', 12, 'Completed', '2024-01-07', '2024-03-31', '8', 'Humanity was caught at a precipice a decade ago when the first gates—portals linked with other dimensions that harbor monsters immune to conventional weaponry—emerged around the world. Alongside the appearance of the gates, various humans were transformed into hunters and bestowed superhuman abilities. Responsible for entering the gates and clearing the dungeons within, many hunters chose to form guilds to secure their livelihoods.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mushoku Tensei II: Isekai Ittara Honki Dasu', 'TV', 12, 'Completed', '2023-07-10', '2023-09-25', '8', 'After his relationship with Eris Boreas Greyrat reaches new heights, Rudeus Greyrat is ecstatic. Unfortunately, his joy is short-lived, as Eris suddenly abandons him to embark on her own journey. Believing that Eris has lost all interest in him, a heartbroken and depressed Rudeus sets forth to the Northern Territories. With his sole goal being to locate his mother on the vast continent, Rudeus wonders if persisting through daily life is worth the pain, falling into a robotic routine as he endlessly ruminates on his lost love.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Berserk: Ougon Jidai-hen III - Kourin', 'Movie', 1, 'Completed', '2013-02-01', NULL, '8', 'The Band of the Hawk has dwindled in the year since Guts left them on his journey to forge his own destiny. Unaware of their fate, Guts returns to the Hawks—now being led by his former ally Casca—after a rumor about them passes his way. Once the saviors of the kingdom of Midland, the Band of the Hawk are now hunted as they desperately fight for their lives while plotting to free their leader, Griffith, after he was imprisoned for committing treason. But the man they save is far from the Griffith they remember.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saiki Kusuo no Ψ-nan: Kanketsu-hen', 'Special', 1, 'Completed', '2018-12-28', NULL, '8', 'The ground shakes, a rumble follows, and before anyone in Japan can prepare themselves, a cataclysmic volcanic eruption engulfs the country in molten lava and suffocating ashes. Of course, high school student Kusou Saiki repeatedly uses his psychic powers to prevent this harrowing catastrophe.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ookami to Koushinryou', 'TV', 13, 'Completed', '2008-01-09', '2008-03-26', '8', 'Holo is a powerful wolf deity who is revered in the small town of Pasloe for blessing the annual harvest. Yet as years go by and the villagers become more self-sufficient, Holo has been reduced to a mere folktale. When a traveling merchant named Kraft Lawrence stops at the settlement, Holo offers to become his business partner if he takes her to her northern home of Yoitsu. The savvy trader recognizes Holo''s unusual ability to evaluate a person''s character and accepts her proposition. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('ReLIFE: Kanketsu-hen', 'Special', 4, 'Completed', '2018-03-21', NULL, '8', 'After reliving the life of a high school student through the ReLIFE experiment, 27-year-old Arata Kaizaki cannot believe how quickly it has changed him. He has begun to see the world through a different perspective that he had completely forgotten as an adult. He has made friends and formed deep relationships with each one of them. However his support, Ryou Yoake, reminds him that the experiment is all an illusion; after his experiment ends, he will be forgotten by all of them.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fruits Basket 1st Season', 'TV', 25, 'Completed', '2019-04-06', '2019-09-21', '8', 'Tooru Honda has always been fascinated by the story of the Chinese zodiac that her beloved mother told her as a child. However, a sudden family tragedy changes her life, and subsequent circumstances leave her all alone. Tooru is now forced to live in a tent, but little does she know that her temporary home resides on the private property of the esteemed Souma family. Stumbling upon their home one day, she encounters Shigure, an older Souma cousin, and Yuki, the "prince" of her school. Tooru explains that she lives nearby, but the Soumas eventually discover her well-kept secret of being homeless when they see her walking back to her tent one night.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Major S3', 'TV', 26, 'Completed', '2007-01-06', '2007-06-30', '8', 'Having bid farewell to his former teammates at Kaido High School''s baseball club, Gorou Honda returns to his hometown eager to continue playing. Attending a new high school proves to be more difficult than he initially expected, as Tetsufumi Egashira''s merciless slandering of his name prevents Gorou from being accepted into any school with an existing baseball team. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Spy x Family Part 2', 'TV', 13, 'Completed', '2022-10-01', '2022-12-24', '8', 'With Anya Forger successfully enrolled at the renowned Eden Academy, Operation Strix advances to its second phase. To investigate Ostanian politician Donovan Desmond, Anya must either befriend his son Damian or collect eight Stella Stars to become an Imperial Scholar. Fortunately, Anya has already acquired her first star. In celebration, her adoptive father, Loid, decides to fulfill her wish to adopt a dog.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kobayashi-san Chi no Maid Dragon S', 'TV', 12, 'Completed', '2021-07-08', '2021-09-23', '8', 'As Tooru continues on her quest to become the greatest maid and Kanna Kamui fully immerses in her life as an elementary school student, there is not a dull day in the Kobayashi household with mischief being a daily staple. On one such day, however, a massive landslide is spotted on the hill where Kobayashi and Tooru first met—a clear display of a dragon''s might. When none of the dragons they know claim responsibility, the perpetrator herself descends from the skies: Ilulu, the radical Chaos Dragon with monstrous power rivaling that of Tooru.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaguya-hime no Monogatari', 'Movie', 1, 'Completed', '2013-11-23', NULL, '8', 'Deep in the countryside, a man named Okina works as a bamboo cutter in a forest, chopping away at the hollow plants day after day. One day, he discovers a small baby inside a glowing shoot. He immediately takes her home, convinced that she is a princess sent to Earth as a divine blessing from heaven. Okina and his wife Ouna take it upon themselves to raise the infant as their own, watching over her as she quickly grows into an energetic young girl. Given the name Kaguya, she fits right in with the village she has come to call home, going on adventures with the other children and enjoying what youth has to offer.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cardcaptor Sakura Movie 2: Fuuin Sareta Card', 'Movie', 1, 'Completed', '2000-07-15', NULL, '8', 'For this year''s Nadeshiko Festival, Sakura Kinomoto''s elementary school class is presenting a play. She will portray a princess who struggles to respond to the love confession of the neighboring country''s prince. Sakura empathizes with her character all too well, since she herself still owes an answer to the boy who confessed his love for her four months ago.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mushen Ji', 'ONA', NULL, 'Airing', '2024-10-27', NULL, '8', 'In the Disabled Elderly Village, there live nine elderly people with unpredictable origins and the young man Qin Mu they raised. One day, the cows that Qin Mu was responsible for grazing began to speak human words. From then on, Qin Mu became more aware of the dangers and beauty of Daxu, a land abandoned by gods: demons descended with darkness, divine bones danced in the ruins, and dragon bones protected their young, a giant ship that drags the sun... No matter what kind of danger he faces, Qin Mu is fearless. He has integrated the skills passed down by the Nine Elders and vowed to carve out a world with his unparalleled hegemony. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yubisaki to Renren', 'TV', 12, 'Completed', '2024-01-06', '2024-03-23', '8', 'For hearing-impaired university student Yuki Itose, silence has been a natural part of life since birth. Her world is small and isolated; she commutes to campus, interacts with her best friend Rin Fujishiro, and communicates through writing and text messages—a lifestyle that offers little to no change. One day, during her commute, Yuki meets fellow student Itsuomi Nagi, a multilingual travel enthusiast and friend of Rin. When Itsuomi learns of Yuki''s condition, he takes it in stride, moving Yuki''s heart. From this one simple gesture, Yuki and Itsuomi''s lives start changing day by day as they let each other into their own worlds.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Haikyuu!! Movie 3: Sainou to Sense', 'Movie', 1, 'Completed', '2017-09-15', NULL, '8', 'Following the events of the Inter-High, the Karasuno High School volleyball team decides to regroup by attending an intensive boot camp organized by Nekoma High School in Tokyo. At the camp, the team continues to suffer loss upon loss to the other schools in attendance. Reaching an impasse, the players each struggle to break out of their routine to hone their skills. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bungou Stray Dogs 3rd Season', 'TV', 12, 'Completed', '2019-04-12', '2019-06-28', '8', 'Following the conclusion of the three-way organizational war, government bureaucrat Ango Sakaguchi recalls an event that transpired years ago, after the death of the former Port Mafia boss. Osamu Dazai, still a new recruit at the time, was tasked with investigating rumors related to a mysterious explosion that decimated part of the city years ago—and its connection to the alleged reappearance of the former boss.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan Movie 13: Shikkoku no Chaser', 'Movie', 1, 'Completed', '2009-04-18', NULL, '8', 'Kudou Shinichi is living his life as Edogawa Conan, but those days seem like they might end pretty soon. The Black Syndicate is coming dangerously close to learning the truth about Shinichi having survived. Conan and everybody around him may end up dead if he doesn''t manage to find Irish—a member of the Black Organization who has infiltrated the police forces, currently investigating a big serial murder case.', 1036, 'https://cdn.myanimelist.net/images/anime/2/22558.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yahari Ore no Seishun Love Comedy wa Machigatteiru. Zoku', 'TV', 13, 'Completed', '2015-04-03', '2015-06-26', '8', 'With the Volunteer Service Club now firmly established, it is receiving more requests from students in search of solutions to their various issues. However, the club members often struggle to see eye to eye when it comes to their problem-solving ideals. The suggestions that Hachiman Hikigaya recommends frequently clash with those of Yukino Yukinoshita, fracturing the relationships within the club. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('InuYasha: Kanketsu-hen', 'TV', 26, 'Completed', '2009-10-04', '2010-03-30', '8', 'Thwarted again by Naraku, Inuyasha, Kagome Higurashi, and their friends must continue their hunt for the few remaining Shikon Jewel shards, lest they fully form into a corrupted jewel at the hands of Naraku. But Naraku has plans of his own to acquire them, and will destroy anyone and anything standing in his way—even his own underlings.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maison Ikkoku', 'TV', 96, 'Completed', '1986-03-26', '1988-03-02', '8', 'In the town of Clock Hill, there is an old boarding house called Maison Ikkoku. While the residence itself is fairly normal, most of its occupants are not. Yuusaku Godai, its most quiet tenant, has finally reached his limit with his neighbors'' constant disruptions and boisterous partying. Wanting a calmer place to call home so that he can study in peace, he prepares to move away.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The God of High School', 'TV', 13, 'Completed', '2020-07-06', '2020-09-28', '7', 'The "God of High School" tournament has begun, seeking out the greatest fighter among Korean high school students! All martial arts styles, weapons, means, and methods of attaining victory are permitted. The prize? One wish for anything desired by the winner.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Log Horizon: Entaku Houkai', 'TV', 12, 'Completed', '2021-01-13', '2021-03-31', '7', 'Third season of Log Horizon.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sayonara Watashi no Cramer Movie: First Touch', 'Movie', 1, 'Completed', '2021-06-11', NULL, '7', '14-year-old Nozomi Onda has only one thing on her mind: playing beautiful soccer. There''s just one problem: no matter how much she longs to participate in official matches, she''d have physically superior boys as opponents. But when a boy from her past confronts her on the street, she decides she can''t wait any longer.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fushigi Mahou Fun Fun Pharmacy', 'TV', 48, 'Completed', '1998-02-15', '1999-02-06', '7', 'In a small town, there is a small pharmacy called Fun Fun Pharmacy. Popuri, a girl who recently moved in downtown, discovers this pharmacy and meets Miss Fukiko, who is actually a witch. Miss Fukiko gives Popuri a mysterious bottle that can create magic spirits.', 1030, 'https://cdn.myanimelist.net/images/anime/3/49799.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Metal Fight Beyblade: Baku', 'TV', 51, 'Completed', '2010-04-04', '2011-03-27', '7', 'Ginga Hagane and his crew of Bladers are back and ready to take on new challenges. The World Championship beckons, and Ginga is more than prepared, now equipped with a new Beyblade, the Galaxy Pegasus W105R2F. And he will be battling with a tag-partner from the USA, Masamune Kadoya. However, Masamune has also set his eyes on the championship, and plans to defeat Gingka.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tennis no Oujisama: Another Story - Kako to Mirai no Message Specials', 'Special', 2, 'Completed', '2009-05-26', '2009-09-25', '7', 'Aru Hi no Oshitari
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Youkai Watch Movie 1: Tanjou no Himitsu da Nyan!', 'Movie', 1, 'Completed', '2014-12-20', NULL, '7', 'The movie will feature special guests such as popular familiar characters from the TV anime series and the latest Youkai from the upcoming Youkai Watch 2 sequel games.', 621, 'https://cdn.myanimelist.net/images/anime/1715/94495.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Final Fantasy VII: On the Way to a Smile - Episode: Denzel', 'OVA', 1, 'Completed', '2009-04-16', NULL, '7', 'After the three-pronged conflict between tyrannical electric company Shinra, rebel group Avalanche, and the maniacal Sephiroth, the damaged planet slowly heals its wounds. A rural town dubbed Edge sprouts up on the outskirts of Midgar''s ruins. Reeve Tuesti, former Head of Urban Development at Shinra, interviews a young boy named Denzel for potential membership in Reeve''s World Regenesis Organization, a group devoted to the restoration and protection of the planet.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Negima!? Natsu Special!?', 'OVA', 1, 'Completed', '2006-11-22', NULL, '7', 'Yue and Nodoka are practicing magic, and one spell catches their eye: The Red String of Fate. Supposedly, this spell connects you with your fated partner. Nodoka decides to try it out, and ends up tied to Negi. However, this spell isn''t the Red String of Fate at all, but is in fact just a red string that connects two people. A magical red string that happens to be impossible to sever. Delightful. Meanwhile, Ayaka invites the class to a free trip to her family''s recently constructed spa resort. Tied together for at least a day, will Negi and Nodoka be able to make the most out of this free trip without going too far...?', 791, 'https://cdn.myanimelist.net/images/anime/8/23631.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cobra The Animation', 'TV', 13, 'Completed', '2010-01-02', '2010-03-27', '7', 'This Cobra adaptation features short arcs of Cobra saving the world, his friends or himself.', 540, 'https://cdn.myanimelist.net/images/anime/13/18900.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Majutsushi Orphen', 'TV', 24, 'Completed', '1998-10-03', '1999-03-27', '7', 'Six years ago at the magic school known as the Tower of Fang, a grave accident happened involving the magical sword Baltanders and the magic user Azalie. Unable to control the sword''s power, Azalie was transformed into the shape of a great dragon who since that day became known as Bloody August. Krilancelo, a young magician at the Tower who cared greatly for Azalie found much to his disgust that the elders of the Tower of Fang were less than willing to save Azalie and wanted rather to pretend the accident never happened. Angered by their stand, Krilanceloa swore that he would find a way to return Azalie to her former self. Thus he forsook the name Krilancelo and declared himself Orphen, leaving the Tower and his magical studies behind to wander the world...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doubutsu no Mori', 'Movie', 1, 'Completed', '2006-12-16', NULL, '7', 'On a fateful day, a young girl named Ai takes a taxi to her new home in Animal Village. After being swindled by her landlord, Tanukichi, into working for his delivery service, it is not long before Ai meets other village residents: Kotobuki, the mayor perpetually worried about his reelection; Yuu, the only other human around, with a passion for random antics and costumes; Bouquet, an overly energetic but rather friendly cat; and Sally, an elephant who dreams of being a fashion designer. New friends seem to lurk in every nook and cranny, but despite that, Ai still struggles to find her niche in this town—until some mysterious notes left on the beach give her a glimpse of a greater purpose.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chicchana Yukitsukai Sugar', 'TV', 24, 'Completed', '2001-10-03', '2002-03-27', '7', 'Season Fairies create and control the weather using special musical instruments. They make the wind blow, the snow fall, the sun shine; if it''s something weather related, they are the ones who make it happen. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaizoku Oujo', 'TV', 12, 'Completed', '2021-10-03', '2021-12-19', '7', 'A decade ago, a tragic shipwreck separated Fena Houtman from her childhood friend Yukimaru and took her father''s life. Now, at age 23, she is trapped on an island and is doomed to spend the rest of her life selling herself to men. On the night she is to be forcibly wed to a client, Fena hatches a plan to escape from her employers, but two old acquaintances unexpectedly intervene and help her run away. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ashita no Joe (Movie)', 'Movie', 1, 'Completed', '1980-03-08', NULL, '7', 'An abridged remake of the first Ashita no Joe TV series, released in 1980 to provide back-story for the second TV series to new fans who were not familiar with the first TV series or the manga.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tetsuwan Atom', 'TV', 193, 'Completed', '1963-01-01', '1966-12-31', '7', 'Devastated over losing his only child in a car accident, Dr. Umatarou Tenma, the director of the Ministry of Science, mobilizes the institution''s entire staff to create Atom: an ultimate technology robot made in his late son Tobio''s exact image. Aside from unmatched power and intelligence, the robot also possesses the innocence and playfulness of a young boy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toku: Touken Ranbu - Hanamaru - Setsugetsuka', 'Movie', 3, 'Completed', '2022-05-20', '2022-09-01', '7', 'Touken Ranbu: Hanamaru anime movie trilogy.', 241, 'https://cdn.myanimelist.net/images/anime/1233/121779.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Black Cat: Toozakaru Neko', 'Special', 1, 'Completed', '2006-07-26', NULL, '7', 'Black Cat DVD only episode.', 341, 'https://cdn.myanimelist.net/images/anime/5/22527.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boku no Chikyuu wo Mamotte', 'OVA', 6, 'Completed', '1993-12-17', '1994-09-23', '7', 'Alice Sakaguchi once dreamt that she is another person living on the moon. The dream is so strange and so real that Alice can''t stop thinking about it. She finds out that some of her classmates are having the same kind of dream. They soon discover that they had been seeing flashes of their past lives as a team of scientists on the moon. Alice and her friends then decide to find the other members and piece together what took place back then. Complications arise when they realize that everything that happened in their previous existence continue to haunt and affect their present lives. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hello! Sandybell', 'TV', 47, 'Completed', '1981-03-06', '1982-02-26', '7', 'Sandybell is a playful girl from Scotland. She is happy even if her mum died when she was little. Past secrets begin to reveal after Sandybell gets a white lily from a rich lady. After a tragic act Sandybell moves to London where she is trying to find clues to her past.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Karneval (TV)', 'TV', 13, 'Completed', '2013-04-04', '2013-06-27', '7', 'While in search of his precious friend, a young boy named Nai falls captive to a beautiful woman, whose looks are matched only by her taste for human flesh. Meanwhile Gareki, a clever thief, is in the midst of robbing her luxurious home. After causing a distraction, Gareki agrees to help Nai escape, but they are discovered upon the woman''s return. As she transforms into a ghoulish monster, the boys flee.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dubu Xiaoyao', 'ONA', 480, 'Completed', '2020-06-18', '2024-12-06', '7', 'The universe is vast, producing countless types of life forms. These life forms form all kinds of souls. All races and spirits have different races and different beliefs, but the same is the extravagant hope for Taoism. Any living beings are dusted with Dao heart, they are not willing to do this, they become powerful and even live forever by enlightening Dao through practice. The Avenue of Heaven and Earth is like luck, where the able live. The road to the great road is the road to struggle for the road, which has caused the struggle of all races and souls. An era can only support a few people to gain the Tao. Those who have attained the Tao think that standing on the top of the world, they can be free in the future. But I found that even Dao. It’s also hard to escape bad luck. There is a ruler above them, harvesting one era after another, and the cultivators of the world want to maintain their ambitions. Ten thousand races and all spirits are just nourished by these rulers. These masters harvest the Taoists, harvest the spirituality of each world, and destroy one by one. The Taoists in the past were unwilling to be reaped and resisted constantly, but failed every time. Until… the protagonist Ye Yu appeared, he peeled away one time and one secret. As he unfolded an epic picture scroll, in this magnificent world, he continued to grow, experience love and friendship, cleanse the dusted Taoist heart, and finally confront the master who harvests all races.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dirty Pair: The Movie', 'Movie', 1, 'Completed', '1987-03-14', NULL, '7', 'Agerna is a planet rich in Vizorium, the one mineral necessary to space travel. So when a series of mysterious attacks on mining operations has the governments of the world pointing fingers and blaming each other, the World Welfare &amp; Works Association naturally sends in their top agents to investigate. But are the lovely angels up to the task of stopping a mad scientist bent on taking a long dormant alien race to its final evolutionary form? Throw in a thief who''s hunting a bottle of World War II-vintage wine and it''s a safe bet that nobody on the planet is safe. It''s more chaos, more mayhem and even more destruction than ever before as the Dirty Pair take on their wildest case yet!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Arknights: Prelude to Dawn', 'TV', 8, 'Completed', '2022-10-29', '2022-12-17', '7', 'The discovery of a black crystalline mineral known as Originium has accelerated technological advancement in the world of Terra, with its high energy yield allowing people to demonstrate abilities akin to magic called Arts. Large veins of Originium can naturally be found at the sites of Catastrophes, various forms of natural disasters caused by the mineral itself.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ze Tian Ji', 'ONA', 13, 'Completed', '2015-07-15', '2015-12-23', '7', 'At the beginning of time, a mystical meteor came crashing down from outer space and scattered all over the world. A piece of it landed in the Eastern Continent. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jitsu wa Watashi wa', 'TV', 13, 'Completed', '2015-07-07', '2015-09-29', '7', 'One day after school, Asahi Kuromine stumbles upon the truth that Youko Shiragami, the girl he has a crush on, is actually a vampire. According to her father''s rules, Youko must now quit school in order to keep her family safe. However, Asahi does not want her to go and promises that he will keep her true nature secret. Unfortunately, this turns out to be easier said than done, as Asahi is a man who is easy to read and is unable to keep any secrets to himself.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Code Geass: Hangyaku no Lelouch - Kiseki no Birthday', 'Special', 1, 'Completed', '2010-04-23', NULL, '7', 'On a lively December day at Ashford Academy, the students are joyously preparing for tomorrow’s school festival. However, the celebrations come to an abrupt halt when terrorists strike the academy. The students are taken hostage and put under lockdown as militant remnants of the Neo-Chinese Federation seize control of the school.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hirune Hime: Shiranai Watashi no Monogatari', 'Movie', 1, 'Completed', '2017-03-18', NULL, '7', 'Kokone Morikawa has a strange napping disease that distracts her from reality, one that makes the world of her dreams and the real world near indistinguishable. In reality, she is an average high school student preparing for her university entrance exams; but in her dreams she is a magical princess of Heartland, a machine-driven future where the use of artificial intelligence is forbidden.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shaonu Qianxian: Renxing Xiao Juchang 2', 'ONA', 12, 'Completed', '2020-10-07', '2020-12-16', '7', 'Second season of Shaonu Qianxian: Renxing Xiao Juchang.', 130, 'https://cdn.myanimelist.net/images/anime/1331/109369.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Binan Koukou Chikyuu Bouei-bu LOVE!', 'TV', 12, 'Completed', '2015-01-07', '2015-03-25', '7', 'Why should girls get to have all the fun? These magical boys are here to save the world from the loveless... at least that''s what the pink wombat who gives them their magical powers wants them to do.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fate/stay night TV Reproduction', 'OVA', 2, 'Completed', '2010-01-17', NULL, '7', 'An edited and condensed version of the TV series.', 879, 'https://cdn.myanimelist.net/images/anime/7/33537.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saikyou Bushouden: Sangoku Engi', 'TV', 52, 'Completed', '2010-04-04', '2011-03-27', '7', 'Chinese-Japanese anime adaptation of the "Romance of the Three Kingdoms" classic novel.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon XY: Sora no Hahen', 'Movie', 1, 'Completed', '2014-07-12', NULL, '7', 'Pocket Monsters XY: Sora no Hahen, is an anime movie tied to Pokémon XY television anime, that screened in two Tokyo planetariums. Like previous Pokémon planetarium anime, this one was projected onto 360-degree panoramic domes.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jewelpet', 'TV', 52, 'Completed', '2009-04-05', '2010-03-28', '7', 'When what looks to be a cluster of shooting stars appear in the sky, Rinko Kougyoku and her friend Minami each make a wish.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shuumatsu no Walküre', 'ONA', 12, 'Completed', '2021-06-17', NULL, '7', 'The gods of the world—from Greek to Norse to Hindu mythology—gather every one thousand years to make one important decision: whether or not to wipe out mankind. Repulsed by humanity''s selfishness, the council unanimously votes to destroy all humans. But before the decree is enacted, Brunhilde, one of the 13 Valkyries of Valhalla, interrupts the meeting to give mankind a chance at survival. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Stratos 4 Advance Kanketsu-hen', 'OVA', 2, 'Completed', '2006-09-22', '2006-10-22', '7', 'With Mikaze Honjou shot, the newly-awakened Miharu Oozora on the run, and the rest of the Shimoji team scattered, things are not looking good. To make matters worse, new swarms of comets show up, threatening to strike even the Shimoji base itself. Now is the time for the girls to show what they are truly made of as they fight for what they believe in.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Ball: Ossu! Kaettekita Son Gokuu to Nakama-tachi!!', 'Special', 1, 'Completed', '2008-09-21', NULL, '7', 'Based on an original concept by the original author Akira Toriyama, the story, set shortly after the defeat of Majin Buu, pits Son Gokuu and his friends against a new, powerful enemy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kanamemo', 'TV', 13, 'Completed', '2009-07-06', '2009-09-28', '7', 'Middle schooler Kana Nakamachi''s life drastically changes when her grandmother passes away. Leaving behind an empty house, Kana learns that no one can provide her lodging due to her young age. Eventually, she stumbles upon the Fuhshin Gazette, a local newspaper delivery business who is able to provide her with a place to stay if she works for them in return.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cobra The Animation: Time Drive', 'OVA', 2, 'Completed', '2009-04-24', '2009-06-26', '7', 'Lady has disappeared so Cobra must dive into her past to save her. This is the story of who Lady used to be and how she got that metal body.', 540, 'https://cdn.myanimelist.net/images/anime/11/14093.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cobra The Animation: The Psycho-Gun', 'OVA', 4, 'Completed', '2008-08-29', '2009-02-27', '7', 'When Utopia More discovers an ancient record that holds the key to unlocking the secrets of the universe, she becomes the target of the ruthless Gypsy Doc of the Pirate Guild. Utopia finds herself saved by the easy-going yet legendary space pirate, Cobra, whose custom made Psychogun makes him a force to be reckoned with. Together, the two of them attempt to stop Gypsy Doc (along with Cobra''s revived arch-nemesis, Crystal Boy) and his efforts to steal the record and use its secrets to rule the universe.', 540, 'https://cdn.myanimelist.net/images/anime/1592/96818.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hibike! Euphonium 2 Specials', 'Special', 7, 'Completed', '2016-12-21', '2017-06-21', '7', 'Short specials included in the Blu-ray/DVD releases.', 494, 'https://cdn.myanimelist.net/images/anime/13/83486.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kouchuu Ouja Mushiking: Mori no Tami no Densetsu', 'TV', 52, 'Completed', '2005-04-06', '2006-03-29', '7', 'The story begins with a spaceship struggling to return to its home world, which crash lands onto a dying planet, triggering an explosion of pure energy, generated by the powerful and mysterious life forms that are piloting the craft. This outburst of energy infuses the dying planet with a life-generating force.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Versailles no Bara: Seimei Aru Kagiri Aishite', 'Movie', 1, 'Completed', '1990-05-19', NULL, '7', 'A theatrical re-edit/summary of the TV series. Some of the voice actors were changed (eg. Oscar is played by Keiko Toda instead of re-using the original audio by Reiko Tajima).', 1036, 'https://cdn.myanimelist.net/images/anime/11/26204.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ryuuou no Oshigoto!', 'TV', 12, 'Completed', '2018-01-08', '2018-03-26', '7', 'Shogi, a Japanese game similar to chess, is one of the most popular board games in the country, played by everyone from children to the elderly. Some players are talented enough to take the game to a professional level. The title of Ryuuou, meaning "the dragon king," is only awarded to the person who reaches the pinnacle of competitive shogi.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hetalia World★Stars Specials', 'Special', 3, 'Completed', '2021-07-28', NULL, '7', 'Episodes 13-15 of Hetalia World★Stars included in the Blu-ray BOX.', 879, 'https://cdn.myanimelist.net/images/anime/1724/115681.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ichigo 100% OVA', 'OVA', 4, 'Completed', '2005-06-20', '2005-10-31', '7', 'Further continuation from the Ichigo 100% TV series. Four episodes in length, comprised mostly of side-story elements such as a Spring Festival featuring Cosplay, Junpei''s adventure to return a notebook to Yui''s friend who atteneds the All-Girl Oumi Academy, summer work at Sawayaka to help cover production costs and last, but not least.. the Strawberry ''Pantsu'' Invaders. This OVA features two new characters. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kinnikuman: Kinnikusei Oui Soudatsu-hen', 'TV', 46, 'Completed', '1991-10-06', '1992-09-27', '7', 'Kinnikuman has proven himself worthy to be crowned the next king of Planet Kinniku. But at the ceremony, five other Kinnikuman''s arrive, all claiming to be the true prince of Planet Kinniku. Now, a Royal Survivor Tournament is being held to decide the true successor to the throne, and with the help and support of his friends and with his recently acquired knowledge of the Ultimate Technique (The Muscle Spark), Kinnikuman fights for what is rightfully his.', 1030, 'https://cdn.myanimelist.net/images/anime/1877/105621.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Magia Record: Mahou Shoujo Madoka☆Magica Gaiden Final Season - Asaki Yume no Akatsuki', 'Special', 4, 'Completed', '2022-04-03', NULL, '7', 'The desperate battle in Kamihama City continues to intensify. With Walpurgis Night changing course for Mitakihara City, all eyes shift toward Embryo Eve—an artificial being, currently dormant, that can allegedly liberate magical girls from their destinies. As the Wings of Magius grow dangerously close to executing their plan, Iroha Tamaki''s last chance to stop the organization is quickly fading. Despite the dwindling odds, lingering hope for the dawn of a better future invigorates her final endeavor, while also uncovering memories of a story tampered with by the hands of fate.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Juubee-chan 2: Siberia Yagyuu no Gyakushuu', 'TV', 13, 'Completed', '2004-01-08', '2004-04-01', '7', 'Three hundred years ago, in the frigid land of Siberia, Jubei Yagyu engaged in a fierce battle with Kitaretsusai of the Northern Yagyu clan. The duel was costly, as his daughter Freesia was frozen in suspended animation. As a result of global warming in the present day, Freesia breaks free from her icy grave and moves to Japan as a middle school transfer student, where she befriends Jiyuu Nanohana. Little does Jiyuu know that Freesia is targeting her to acquire the coveted Lovely Eye Patch, which Freesia believes is rightfully hers.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Senran Kagura', 'TV', 12, 'Completed', '2013-01-06', '2013-03-24', '6', 'At the renowned Hanzo Academy, a select group of students trains in secret to become ninjas of an elite clan known as the Shinobi Masters. Following her grandfather''s footsteps, the hopeful Asuka undergoes this intensive training alongside her distinctive group of friends: Ikaruga, Katsuragi, Yagyuu, and Hibari. Relentlessly studying the secret ninja arts, they hone their skills in the hopes of one day becoming full-fledged female ninjas. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hachi-nan tte, Sore wa Nai deshou!', 'TV', 12, 'Completed', '2020-04-02', '2020-06-18', '6', 'Waking up in a new world, 25-year-old Shingo Ichinomiya realizes that he is in the body of a six-year-old. Retaining memories of his stressful life working at a firm company, Shingo learns that the person he is occupying is Wendelin Von Benno Baumeister, the eighth son of a poor noble family living in the countryside. Awoken to his bizarre situation, Wendelin strives to change his financial and social status for the better. His newly discovered great magical aptitude may prove to be just what he needs to achieve that goal.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ore dake Haireru Kakushi Dungeon', 'TV', 12, 'Completed', '2021-01-09', '2021-03-27', '6', 'Despite his noble title, Noir Stalgia is at the bottom of the social hierarchy. Because of this, his fellow nobles oppress him and treat him like garbage. However, he possesses a rare yet powerful ability to communicate with the Great Sage, an oracle who grants Noir the answer to absolutely anything.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('New Jersey and Enterprise''s Beach Vacation', 'ONA', 1, 'Completed', '2024-08-12', NULL, '6', 'Commanders, join the shipgirls for a seaside getaway!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Duel Masters LOST: Tsuioku no Suishou', 'ONA', 4, 'Completed', '2024-10-04', '2024-11-29', '6', 'One day, mysterious incidents occur frequently in Shinjuku City, Tokyo, where people''s have suddenly disappeared. Half a year ago, Win Kirifuda, who woke up in this town, had lost all his memories. In his high school and part-time job he started attending on a whim, he couldn''t fit in with those around him. He spent his days feeling frustrated, hanging out in the park at night with classmates such as Niika. Such daily life transforms with the appearance of Crysta, a mysterious transfer student who claims to "know everything about Win." She says that they are engaged, but a dubious presence lurks behind her. What is the truth behind the frequent mysterious incidents? What is Crystas''s sudden goal? And what about Win''s hidden past? A new story begins to recover the lost memories.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuramerukagari', 'Movie', 1, 'Completed', '2024-04-12', NULL, '6', 'This is a story that weaves together people and a town. A coal mining town crowded with small-scale excavators, commonly known as the "Hakoniwa." In this town that changes daily like a labyrinth, there''s a girl named Kagari who runs a mapmaking business and a boy named Yuya who dreams of breaking free from the "Hakoniwa." Eventually, the two, along with the unique residents of the town, find themselves confronting a conspiracy that shakes the entire town. The fate of the” Hakoniwa" depends on Kagari''s drawings on the map.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Debu to Love to Ayamachi to!', 'TV', 12, 'Airing', '2025-10-06', NULL, '6', '"This is the punishment for a fat, ugly girl like me falling in love with someone as beautiful as you..." Yumeko had a mountain of complexes about herself. Then, a terrible accident befalls her. Though somehow saved from the brink of death, Yumeko wakes up a completely different person. "This is...me...?! I''m SO cute!!" Those around her can''t hide their surprise and wonderment at this 180°change... But, Yumeko''s new hyper-positive attitude starts to change her surroundings, too. Worries and complexes can affect anyone, and Yumeko will chop right through those of her various supporting characters!! In love, work, friendship... And an attempted murder case?! This frenzied romantic comedy will leave you bubbling with energy!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eiyuu Kyoushitsu Specials', 'Special', 3, 'Completed', '2024-01-26', '2024-03-27', '6', 'Specials included in the BD/DVD release of Eiyuu Kyoushitsu.', 48, 'https://cdn.myanimelist.net/images/anime/1352/138739.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koneko no Haitatsuin Uunyan', 'ONA', 1, 'Completed', '2022-08-13', NULL, '6', 'Uunyan, a kitten from Cat Island, is excited about his first delivery job! However, while he is distracted by the flying soap bubbles and chewing on candy, the delivery bag disappears. By the time Uunyan realizes it, he must find the bag and chase after it!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bing Zhu Qi Hun Part 2', 'ONA', 12, 'Completed', '2023-01-24', '2023-04-04', '6', '', 392, 'https://cdn.myanimelist.net/images/anime/1685/132802.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Larva Island Movie', 'ONA', 1, 'Completed', '2020-07-23', NULL, '6', 'In this movie sequel to the hit series, Chuck returns home and talks to a reporter about life on the island with zany larva pals Red and Yellow.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Genei wo Kakeru Taiyou: Fumikomenai Kokoro', 'Special', 1, 'Completed', '2013-11-16', NULL, '6', 'Unaired 14th episode of Genei wo Kakeru Taiyou, broadcast on Nico Nico and included in the 4th Blu-ray and DVD volumes. It shows Akari and Fuyuna''s lives prior to the main series as well as how Luna got started as a magical girl.', 25, 'https://cdn.myanimelist.net/images/anime/5/53747.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kotoura-san: Haruka no Heya', 'ONA', 6, 'Completed', '2012-12-07', '2013-01-11', '6', 'Mini episodes of Kotoura-san introducing each of the series'' characters.', 28, 'https://cdn.myanimelist.net/images/anime/10/45090.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hua Jianghu: Bei Mo Ting', 'ONA', 40, 'Completed', '2016-12-07', '2017-09-06', '6', 'Years ago, Zong Shuai from the Middle State, Wanyan Zang from the Northern Land, and Wen Taiji from the Southern Territory suffered great loss during their fight for the hegemony of the world. As a result, a 20-year truce was established. Now, with the deal coming to an end, conflicts are brewing in the ostensible peace. In hatred and suspicion, the three families set up their respective Blood Orders, listing the names of the most important people of the hostile families and swearing to hunt them down. A breathtaking war is about to commence.', 747, 'https://cdn.myanimelist.net/images/anime/10/85984.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('SD Gundam Sangokuden Brave Battle Warriors', 'TV', 51, 'Completed', '2010-04-03', '2011-03-19', '6', 'A Romance of the Three Kingdoms retelling using SD Gundams.', 974, 'https://cdn.myanimelist.net/images/anime/6/21471.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Suki na Mono wa Suki Dakara Shou ga Nai!!: Onsen ni Ikou!', 'Special', 1, 'Completed', '2005-09-23', NULL, '6', 'A bonus DVD only episode where the boys go to a hot spring.', 1145, 'https://cdn.myanimelist.net/images/anime/8/78436.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zephyr', 'Special', 1, 'Completed', '2014-10-11', NULL, '6', 'The story revolves around the boy band named Zephyr, who lives in the slums of Tokyo in the near future. They stopped producing music after a war. One day Ned, the lead vocalist, receives a message on his phone from his girlfriend who he thought died in the war.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chiisana Koi no Monogatari: Chichi to Sally Hatsukoi no Shiki', 'Special', 1, 'Completed', '1984-03-20', NULL, '6', 'Tiny schoolgirl Chiiko develops a crush on older boy Sally and believes herself to be his girlfriend, although Sally is already involved in a love triangle with a girl called Tonko.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bakabon Osomatsu no Karee wo Tazunete Sansenri', 'Special', 1, 'Completed', '1991-10-19', NULL, '6', '', 939, 'https://cdn.myanimelist.net/images/anime/3/62947.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Val x Love', 'TV', 12, 'Completed', '2019-10-05', '2019-12-21', '6', 'Valkyries—legendary female warriors from the land of gods, Asgard—are sent by Odin to protect Earth against the growing threat of demons. To overcome these threats, nine valkyries under the guise of the Saotome sisters will have to level up by performing a variety of romantic acts with their official lover, Einherjar.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aruhi no Clamp Gakuen Tanteidan', 'Special', 13, 'Completed', '2005-04-22', NULL, '6', 'DVD short specials featuring characters from the original series as well as Gakuen Tokukei Duklyon and 20 Mensou ni Onegai!! all done in a chibi-comedy format.', 939, 'https://cdn.myanimelist.net/images/anime/12/18518.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hoshi Neko Fullhouse', 'OVA', 4, 'Completed', '1989-06-16', '1989-12-25', '6', 'This slapstick comedy is about three pretty girls struggling to earn a living as pilots of the Iron Goblin delivery vessel. The computer answers back, the space pirates are on their tail, and romantic entanglements with their clients cause friction in the trio. The final episode throws the alien Eterna race in to the mix.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Patalliro Saiyuuki! Special', 'Special', 1, 'Completed', '2006-01-25', NULL, '6', 'Unaired episode 27 of Patalliro Saiyuuki! that was included in the 5th DVD volume.', 540, 'https://cdn.myanimelist.net/images/anime/1310/143607.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Iii Icecrin', 'TV', 12, 'Completed', '2021-04-06', '2021-06-29', '6', 'Icecrins are the sweetly peculiar inhabitants of Ice Cream Town. Every day is a fresh start, with each Icecrin bringing their own unique flavor wherever they go. They may lose their cool at times, but in the end, they always do their best to help their friends have a very ''ice day!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shounen Sarutobi Sasuke', 'Movie', 1, 'Completed', '1959-12-25', NULL, '6', '"Magic Boy" was the first ever Japanese animation to be released theatrically in North America. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaizoku Ouji', 'TV', 31, 'Completed', '1966-05-02', '1966-11-28', '6', 'Kid was brought up on a small island which floats on the Carribean Sea. He lives a pleasant life with many animals as his companions. However, this changes when he learns that his dying father is not his real father. Before he passes away, his foster father reveals to Kid that his real father is actually Captain Morgan, the pirate who rules the seven seas. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Samurai Girl Real Bout High School', 'TV', 13, 'Completed', '2001-07-30', '2001-10-22', '6', 'At Daimon High School, kids settle their disputes by dueling with each other in the school''s official K-Fight battle arena. Ryoko Mitsurugi, samurai girl and undefeated K-Fight champion, is called upon by a mysterious Priestess to protect the Earth from an invasion coming from the alternate universe of Solvania. She must face battles that will test her skills, her friendships, and her heart in order to find her true strength as a samurai warrior. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Surf Side High-School', 'TV', 20, 'Completed', '1999-06-01', '1999-07-02', '6', 'At a high school that sits in front of the ocean, three unpopular pubescent guys, Abe, Nagaho, and Mita, spend more of their time goofing off at the beach than studying. Of course, surfing always comes first, but their other adventures on the beach and search for girls are a source of non-stop laughter. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Colorful', 'TV', 16, 'Completed', '1999-09-07', '1999-10-01', '6', 'Two horny college slackers and a beautiful professor. A frustrated TV reporter. A sexy track star and her tempted coach. And a high school girlzilla that’s the size of the Empire State building. Colorful! contains over 50 vignettes of men, women, and the pursuit of… well, you’ll just have to see.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rokushin Gattai GodMars: Juunana-sai no Densetsu', 'OVA', 1, 'Completed', '1988-06-05', NULL, '6', 'Marg was deprived his little brother, Mars, by Zure, and lost his parents. Therefore, he was living alone on the planet, Gishin. He became a member of guerrilla to riot against the dictator Zure, and he fell in love with Ruru, the daughter of the leader, Ura. However, the organization was destroyed. He was trapped by Zure, and he was brainwashed to become a soldier. Then, his long cherished wish that he would meet his brother again was realized… as a duel with him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Birth', 'OVA', 1, 'Completed', '1984-07-21', NULL, '6', 'Aqualoid was a prosperous planet, but an attack from a mysterious life force, the Inorganics, transforms it into a post-apocalyptic shell of its former self. When Nam finds a mysterious sword, he is suddenly the object of a planet-wide chase. With the Inorganics closing in, will Nam and his friends discover the secret of the sword and save their world? Or will they destroy Aqualoid in favor of a new Birth?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wind: A Breath of Heart', 'OVA', 1, 'Completed', '2002-12-27', NULL, '6', 'Set four months after the resolution of the game the anime Wind is based on (via Hikari''s ending), the entire gang is planning a big Christmas party. However, with the reappearance of Hikari, weird things start to happen in the city of Kazune. How will things turn out?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Divergence Eve', 'TV', 13, 'Completed', '2003-07-02', '2003-09-24', '6', 'In the 24th Century, Intergalactic Space Travel has become a reality. One of the first outposts in the far reaches of space is WATCHER''S NEST - an inflation hole drive portal - which has recently come under attack by a mysterious force known simply as GHOUL... A group of young female cadets assigned to the portal are unexpectedly thrown into a hornet''s nest of trouble as they finalize their training to become an elite pilot in the Seraphim Squadron.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The Samurai', 'OVA', 1, 'Completed', '1987-11-01', NULL, '6', 'Though the time of the samurai has long since passed, Takeshi Chimatsuri does his best to keep the spirit of duty alive by wearing traditional clothing and carrying a sword with him every day. However, when Kageri and Akari Toki, who hail from a family of ninjas, transfer to Chimatsuri''s high school, their sudden meeting may just bring the entire place to its knees. The Toki sisters have sworn to take back an heirloom sword that Chimatsu''s father had won in a duel years before—and are more than willing to use underhanded tactics to accomplish their goal.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hand Maid Mai', 'OVA', 1, 'Completed', '2003-01-18', NULL, '6', 'Hideo Ozu is an editor in a shady adult video company. For years, he has dreamed of being a motion picture director while his childhood friend Mai Kurosawa has become an upcoming actress. Then one day, his dreams are shattered when Mai takes all of his amateur videos of her and tells him to get out of her life. On his way home after a few drinks, Hideo bumps into Cyberdoll Sara, who makes him mark an invoice. When he arrives at his pad, Hideo is greeted by three Cyberdolls - Mai, Ai and Mie. All three of them happen to look like different age variations of Mai Kurosawa. And when Kurosawa announces the release of a biography video of her using Hideo''s old footage, Hideo decides to start his directing dreams over again using his three Cyberdolls. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chikatetsu ni Noru', 'Special', 1, 'Completed', '2017-05-27', NULL, '5', 'A group of three high school girls explore Kyoto using the Kyoto City Subway system.', 356, 'https://cdn.myanimelist.net/images/anime/3/89263.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yoshida no Matsue Beauty Daisakusen', 'ONA', 3, 'Completed', '2017-03-16', NULL, '5', 'A Matsue City collaboration anime with Eagle Talon. Yoshida and Hifumi Arai go exploring the city for these beautifying locations. All 3 episodes (and the prologue) were uploaded on the same day but then a bit later episode 2 and 3 were removed. They were then reuploaded the week after and the week after that, as a minor semblance to a weekly released series instead.', 214, 'https://cdn.myanimelist.net/images/anime/3/84748.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jakusansei Million Arthur Specials', 'Special', 3, 'Completed', '2016-07-06', '2016-08-25', '5', 'Special episodes of Jakusansei Million Arthur released to commemorate the Playstation 4/Vita game release.', 329, 'https://cdn.myanimelist.net/images/anime/10/81339.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tang Lang Bu Chan', 'Movie', 1, 'Completed', '1988-01-01', NULL, '5', 'A cicada is resting high on a tree. It is chirping for all it’s worth and drinking in the dew, oblivious of a mantis behind. The mantis, bending over and arching up its front leg, is going to catch the cicada but does not know that there is an oriole beside it. The bird has stretched out its neck, ready to peck at the mantis. Again the oriole is unaware that a weasel is sneaking up to it. The three creatures all covet gains ahead without being aware of an imminent danger behind.', 792, 'https://cdn.myanimelist.net/images/anime/4/76910.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kanojo ga Kanji wo Suki na Riyuu.', 'ONA', 2, 'Completed', '2015-09-14', '2015-10-13', '5', 'Anime shorts created by Studio 4℃ as a collaboration with the Japan Kanji Aptitude Test.', 849, 'https://cdn.myanimelist.net/images/anime/4/76306.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Q Transformers: Saranaru Ninki Mono e no Michi', 'TV', 13, 'Completed', '2015-07-06', '2015-10-01', '5', 'Second season of Q Transformers.', 214, 'https://cdn.myanimelist.net/images/anime/2/74246.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Santa Claus Tsukamaeta!', 'OVA', 1, 'Completed', '1989-12-06', NULL, '5', 'A simple story about a young boy who stays up on Christmas in order to catch Santa and show the proof to his older friends.', 1002, 'https://cdn.myanimelist.net/images/anime/1870/112393.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Himitsukessha Taka no Tsume The Movie 1: Soutou wa Nido Shinu', 'Movie', 1, 'Completed', '2007-03-17', NULL, '5', 'The first Eagle Talon movie.', 214, 'https://cdn.myanimelist.net/images/anime/8/22014.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Genji', 'OVA', 2, 'Completed', '1992-05-21', '1992-10-10', '5', 'Katsumi and Sakura find themselves transported in the midst of a civil war between the Heike and Genji clans.', 436, 'https://cdn.myanimelist.net/images/anime/11/21295.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kagaku x Bouken Survival!', 'TV', 21, 'Completed', '2024-10-05', '2025-03-15', '5', '', 325, 'https://cdn.myanimelist.net/images/anime/1798/150102.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gasonshi!!: Esper Shoujo to Ninja no Abiko Monogatari', 'ONA', 1, 'Completed', '2023-12-02', NULL, '5', '', 980, 'https://cdn.myanimelist.net/images/anime/1450/141420.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sushe Bu Richang', 'ONA', 6, 'Completed', '2018-01-23', '2018-03-06', '5', 'Third season of Nusheng Sushe Richang.', 1138, 'https://cdn.myanimelist.net/images/anime/1954/138880.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuroko no Basket 2nd Season', 'TV', 25, 'Completed', '2013-10-06', '2014-03-30', '8', 'With the Interhigh Championship finally over, Seirin''s basketball team refocuses their efforts, training harder than ever to get the chance to participate in the Winter Cup. Both Tetsuya Kuroko and Taiga Kagami see old friends walk back into their lives, providing a challenge both on and off the court.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('xxxHOLiC◆Kei', 'TV', 13, 'Completed', '2008-04-04', '2008-06-27', '8', 'Kimihiro Watanuki''s life was never really normal. But in addition to his ability to see spirits, this sequel to xxxHOLiC finds him still slaving away for Yuuko, the bizarre owner of a strange shop, who promised to rid him of this ability. However, this otherworldly woman can only do so when he has worked enough to earn his wish. Such is the way for anyone who finds their way into the shop to have their request granted: a compensation equal to their wish must be paid. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Major S1', 'TV', 26, 'Completed', '2004-11-13', '2005-05-21', '8', 'Gorou Honda, a little boy obsessed with baseball, has always admired his father, Shigeharu. Wishing to follow in his father''s footsteps, Gorou dreams of becoming a professional baseball player. In turn, his son''s starry-eyed admiration encourages Shigeharu to keep persevering, despite his late wife''s death and his unsatisfying position on the second-string team Blue Ocean.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Ball Z', 'TV', 291, 'Completed', '1989-04-26', '1996-01-31', '8', 'Five years after winning the World Martial Arts tournament, Gokuu is now living a peaceful life with his wife and son. This changes, however, with the arrival of a mysterious enemy named Raditz who presents himself as Gokuu''s long-lost brother. He reveals that Gokuu is a descendant of the once powerful but now virtually extinct Saiyan race, whose homeworld was annihilated. When he was sent to Earth as a baby, Gokuu''s sole purpose was to conquer and destroy the planet; but after suffering amnesia from a head injury, his violent and savage nature changed, and instead was raised as a kind and well-mannered boy, now fighting to protect others.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('SKET Dance', 'TV', 77, 'Completed', '2011-04-07', '2012-09-27', '8', 'At Kaimei High School there is a special club dedicated to helping others known as the SKET Brigade. The brains of the group is Kazuyoshi "Switch" Usui, a tech-savvy otaku who speaks through speech synthesis software, while the brawn is provided by Hime "Himeko" Onizuka, the hockey stick-wielding girl once known as "Onihime."  And last but not least, their leader is Yuusuke "Bossun" Fujisaki, whose latent ability is evoked by his goggles, allowing him to summon the awesome power of extraordinary concentration.  
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Magi: The Kingdom of Magic', 'TV', 25, 'Completed', '2013-10-06', '2014-03-30', '8', 'After celebrating their victory against Al-Thamen, Aladdin and his friends depart the land of Sindria. With the end of the battle, however, comes the time for each of them to go their separate ways. Hakuryuu and Kougyoku are ordered to go back to their home country, the Kou Empire. Meanwhile Aladdin announces he needs to head for Magnostadt—a mysterious country ruled by magicians—to investigate the mysterious events occurring in this new kingdom and become more proficient in magic. For their part, encouraged by Aladdin''s words, Alibaba and Morgiana also set off in pursuit of their own goals: training and going to her homeland, respectively.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Ball Super: Broly', 'Movie', 1, 'Completed', '2018-12-14', NULL, '8', 'Forty-one years ago on Planet Vegeta, home of the infamous Saiyan warrior race, King Vegeta noticed a baby named Broly whose latent power exceeded that of his own son. Believing that Broly''s power would one day surpass that of his child, Vegeta, the king sends Broly to the desolate planet Vampa. Broly''s father Paragus follows after him, intent on rescuing his son. However, his ship gets damaged, causing the two to spend years trapped on the barren world, unaware of the salvation that would one day come from an unlikely ally.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Girls & Panzer Movie', 'Movie', 1, 'Completed', '2015-11-21', NULL, '8', 'Having won the 63rd National Sensha-dou tournament, the girls from Ooarai Girls Academy managed to prevent their school from closure by the Japanese Ministry of Education. However, new troubles loom on the horizon: a ministry official argues that the deal was not legally binding and that the Ooarai school carrier is to be decommissioned. Students and their families are frustrated with this injustice and overwhelmed with despair; it seems little can be done to save the school.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Asobi Asobase', 'TV', 12, 'Completed', '2018-07-08', '2018-09-23', '8', 'During recess, Olivia, a foreign transfer student who doesn''t know English, plays a game of "look-the-other-way" with Hanako Honda, a loud-mouthed airhead. Their rowdy behavior spurs the ire of Kasumi Nomura, a deadpan loner constantly teased by her older sister for her tendency to lose games. Not willing to compete, Kasumi declines Olivia''s offer to join the fun, but eventually gets involved anyway and dispenses her own brand of mischief. Soon, a strange friendship blossoms between the peculiar trio, and they decide to form the "Pastime Club," where they are free to resume their daily hijinks. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Quanzhi Gaoshou Specials', 'ONA', 3, 'Completed', '2018-04-27', '2018-05-11', '8', 'The All-Star Tournament is a three-day event that allows e-sports participants from various professional clubs to display their skills, while also giving casual Glory players the chance to interact with pros in the flesh.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mo Dao Zu Shi Q', 'ONA', 30, 'Completed', '2020-07-31', '2021-01-29', '8', 'The cultivation classes in the Cloud Recesses have started, and Wei Wuxian is as mischievous as ever. From getting in trouble for cheating to tempting the ever-so-cold and stoic Lan Wangji into breaking one of the three thousand strict rules of the Gusu Lan Clan—he''s done it all. Although almost everything Wei Wuxian does is against Lan Wangji''s principles, an unbreakable bond forms between the two. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Stand By Me Doraemon 2', 'Movie', 1, 'Completed', '2020-11-20', NULL, '8', 'After reminiscing about his late grandmother, Nobita Nobi wishes to see her again and asks Doraemon to return them to the past. Following the wholesome reunion of the two, Nobita''s grandmother confesses that she hopes to meet his future bride. Nobita accepts her request out of filial love and quickly scrambles into the time machine as he and Doraemon journey forward in time.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Senki Zesshou Symphogear XV', 'TV', 13, 'Completed', '2019-07-07', '2019-09-29', '8', 'Humanity is finally confronted with the threat of the Custodians—the ancient, sentient species held responsible for cursing humanity to speak different languages thousands of years ago. The Symphogear wielders—Hibiki Tachibana, Tsubasa Kazanari, Chris Yukine, Maria Cadenzavna Eve, Kirika Akatsuki, and Shirabe Tsukuyomi—are sent to the Antarctic in order to retrieve an ancient relic. After securing it and rescuing the scientific staff present there from a Coffin, the automated defense mechanism protecting it, the relic is given to American researchers due to international agreements.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yi Nian Yong Heng 2nd Season', 'ONA', 54, 'Completed', '2022-07-20', '2023-07-12', '8', 'To avoid a war between the two sects, Bai Xiaochun disguises himself as "Ye Zang" and infiltrates the rival sect, Blood Stream Sect. He climbs his way up and obtains the identity of Blood Child. However, how can he avoid the impending war between the two sects...?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Great Pretender', 'TV', 23, 'Completed', '2020-07-09', '2020-12-17', '8', 'A series of unfortunate events has led Makoto Edamura to adopt the life of crime—pickpocketing and scamming others for a living. However, after swindling a seemingly clueless tourist, Makoto discovers that he was the one tricked and, to make matters worse, that the police are now after him. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Initial D Second Stage', 'TV', 13, 'Completed', '1999-10-15', '2000-01-21', '8', 'Accumulating an impressive series of victories with his AE86, Takumi Fujiwara has imposed himself as street racing''s newest rising star. However, his newly found confidence of winning at his home turf of Mount Akina has been put in jeopardy by a new Emperor team exclusively using a car model favored by most professional racing pilots: the Mitsubishi four-wheel drive Lancer Evolutions—also known as Lan Evos. The Emperor team leader, Kyouichi Sudou, looks down on Takumi and regards him as an inferior pilot for driving an antique car that lacks the makings of a true modern race car. Kyouichi''s elitist philosophy is also the reason why his team is only made of Lan Evo drivers.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Horimiya', 'TV', 13, 'Completed', '2021-01-10', '2021-04-04', '8', 'On the surface, the thought of Kyouko Hori and Izumi Miyamura getting along would be the last thing in people''s minds. After all, Hori has a perfect combination of beauty and brains, while Miyamura appears meek and distant to his fellow classmates. However, a fateful meeting between the two lays both of their hidden selves bare. Even though she is popular at school, Hori has little time to socialize with her friends due to housework. On the other hand, Miyamura lives under the noses of his peers, his body bearing secret tattoos and piercings that make him look like a gentle delinquent.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Vanitas no Karte Part 2', 'TV', 12, 'Completed', '2022-01-15', '2022-04-02', '8', 'Vanitas and Noé Archiviste head out to the town of Gévaudan in search of the "Beast," an enormous wolf-like creature that has slaughtered hundreds of people. Suspecting that the Beast is a curse-bearing vampire, Vanitas primarily aims to heal it using the powers of his grimoire.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sasaki to Miyano', 'TV', 12, 'Completed', '2022-01-10', '2022-03-28', '8', 'Yoshikazu Miyano''s troubles first start one hot summer day when Shuumei Sasaki steps into his life. Sasaki saves Miyano''s classmate from a group of bullies, and after that, Miyano cannot seem to shake off his eccentric upperclassman. His silent admiration for Sasaki gradually sours into annoyance each time the so-called delinquent refuses to leave him alone. Constantly being called by cute nicknames and having his boundaries ignored, Miyano wonders why Sasaki wants to get close to him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fujimoto Tatsuki 17-26', 'ONA', 8, 'Completed', '2025-11-08', NULL, '8', '1. Niwa ni wa Niwa Niwatori ga Ita. (A Couple Clucking Chickens Were Still Kickin'' in the Schoolyard)
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seishun Buta Yarou wa Santa Claus no Yume wo Minai', 'TV', 13, 'Completed', '2025-07-05', '2025-09-27', '8', 'After surviving the entrance exams, Sakuta Azusagawa has finally enrolled in the same university as his girlfriend, Mai Sakurajima. He is gradually getting used to the unfamiliar environment as he attends student gatherings and makes new acquaintances. Everything seems to be going smoothly until Sakuta''s friend and Sweet Bullet idol group member Uzuki Hirokawa begins acting out.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ao no Hako', 'TV', 25, 'Completed', '2024-10-03', '2025-03-27', '8', 'Every morning, incoming first-year Taiki Inomata hurries to his high school gym in order to further refine his badminton skills. However, his true motivation stems from sharing the otherwise empty gym with second-year Chinatsu Kano, Taiki''s crush and the star player of the girls'' basketball team. Although Chinatsu seems unapproachable, Taiki gradually finds opportunities to get to know her little by little.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fate/strange Fake: Whispers of Dawn', 'Special', 1, 'Completed', '2023-07-02', NULL, '8', 'In the American city of Snowfield, a new Holy Grail War is about to erupt. Such ruthless confrontations pit against each other magic experts known as magi, who ascend to the status of Master by summoning Servants—heroic spirits of the past. The winner is thought to have any one of their wishes granted.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('K-On!!', 'TV', 26, 'Completed', '2010-04-07', '2010-09-29', '8', 'It is the new year, which means that the senior members of the Light Music Club are now third-years, with Azusa Nakano being the only second-year. The seniors soon realize that Azusa will be the only member left once they graduate and decide to recruit new members. Despite trying many methods of attracting underclassmen—handing out fliers, bringing people into the clubroom, and performing at the welcoming ceremony—there are no signs of anyone that plans to join.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fate/stay night: Unlimited Blade Works', 'TV', 12, 'Completed', '2014-10-12', '2014-12-28', '8', 'The Holy Grail War is a battle royale among seven magi who serve as Masters. Masters, through the use of the command seals they are given when they enter the war, command Heroic Spirits known as Servants to fight for them in battle. In the Fifth Holy Grail War, Rin Toosaka is among the magi entering the competition. With her Servant, Archer, she hopes to obtain the ultimate prize—the Holy Grail, a magical artifact capable of granting its wielder any wish.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tensei shitara Slime Datta Ken: Coleus no Yume', 'ONA', 3, 'Completed', '2023-11-02', NULL, '8', 'The story takes place between the first and second season, where Rimuru confronts the swirling conspiracies in the Coleus kingdom.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shen Lan Qi Yu Wushuang Zhu: Hong Bao Pian', 'ONA', 15, 'Completed', '2023-01-14', '2023-04-15', '8', 'The second season of Shen Lan Qi Yu Wushuang Zhu.', 159, 'https://cdn.myanimelist.net/images/anime/1349/132466.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Akiba Meido Sensou', 'TV', 12, 'Completed', '2022-10-07', '2022-12-23', '8', 'The innocent Nagomi Wahira has always admired the cute girls serving at maid cafes. Hoping to fulfill her dream of becoming one, she moves to Akihabara to work at the maid cafe Ton Tokoton.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Da Wang Rao Ming 2', 'ONA', 12, 'Completed', '2023-12-30', '2024-01-27', '8', 'After returning victorious from his first journey to magical ruins, Lü Shu resumes his peaceful life with his adoptive sister, Lü Xiaoyu, while trying to avoid revealing his true power to Tian Luo Di Wang, the organization that enlists cultivators and protects the country from foreign threats.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuroko no Basket: Mou Ikkai Yarimasen ka', 'Special', 1, 'Completed', '2014-06-20', NULL, '8', 'Bundled with the 6 Blu-ray/DVD. It will adapt the 124th chapter of the manga, which depicts when Kuroko and Aomine first met.', 704, 'https://cdn.myanimelist.net/images/anime/12/68055.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Naruto: Shippuuden - Sunny Side Battle', 'Special', 1, 'Completed', '2013-10-06', NULL, '8', 'Back at their childhood home, siblings Itachi and Sasuke Uchiha experience an unusual morning together when Itachi becomes obsessed with cooking the perfect fried egg for Sasuke. Despite being completely focused on the task, he continuously fails to achieve the desired result. As Sasuke marvels at his brother''s seemingly unnecessary behavior, he comes to realize that there is more than meets the eye to Itachi''s efforts.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Re:Zero kara Hajimeru Isekai Seikatsu - Memory Snow', 'Movie', 1, 'Completed', '2018-10-06', NULL, '8', 'Subaru Natsuki finally gets to take a breather, but he does not waste any time as he prepares for a date with his beloved Emilia. He scouts the nearby village for the right dating spot, and with the help of the village children, he finds a wonderful location. With that, he is well prepared for his date!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Love Live! Sunshine!! 2nd Season', 'TV', 13, 'Completed', '2017-10-07', '2017-12-30', '8', 'Having decided to walk down a path separate from their inspirations as idols, the girls of Aqours are more determined than ever to shine brilliantly as school idols. With their previous performance marginally increasing the number of prospective students for their endangered school, they look to carry the momentum of their small step forward into the school''s upcoming open house and the next Love Live competition. Hoping to use these events to bring more attention to their school, the nine girls look to give their best performances yet.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Re:Zero kara Hajimeru Isekai Seikatsu - Hyouketsu no Kizuna', 'Movie', 1, 'Completed', '2019-11-08', NULL, '8', 'Covered in ice and snow, Elior Forest is the home to dangerous magical beasts and 50 elves frozen in ice. One day, the great spirit Puck helps a young girl break out of her ice prison. Her name is Emilia, a half-elf born with silver hair, long ears, and amethyst eyes—features that resemble the evil Witch who destroyed half the world long ago. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jujutsu Kaisen Official PVs', 'Special', 3, 'Completed', '2018-12-03', '2018-12-08', '8', 'Just where do Curses, the fiendish spirits invisible to normal humans, come from? What is Sukuna Ryoumen, whose very existence grips the Jujutsu world in fear? And who exactly is Yuuji Itadori, the boy who recently became the center of attention in Jujutsu society?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Butouden G Gundam', 'TV', 49, 'Completed', '1994-04-01', '1995-03-31', '8', 'In the year Future Century 0060, the many countries that once comprised Earth''s surface exist as separate colonies floating in space. Their home planet now uninhabitable, the ruler of all of the colonies is decided by their unanimous participation in the intergalactic Gundam Fight Tournament—a series of battles between the champions of each colony to determine who is most fit to reign over them all.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Manga de Wakaru! Fate/Grand Order', 'Special', 1, 'Completed', '2018-12-31', NULL, '8', 'A short anime based on Manga de Wakaru! Fate/Grand Order by Riyo. Aired during Fate Project Year End 2018, and is also available on YouTube.', 14, 'https://cdn.myanimelist.net/images/anime/1830/98102.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sword Art Online: Alicization - War of Underworld', 'TV', 12, 'Completed', '2019-10-13', '2019-12-29', '8', 'Despite the defeat of Quinella—the pontifex of the Axiom Church—things have not seemed to calm down yet. Upon contacting the real world, Kazuto "Kirito" Kirigaya finds out that the Ocean Turtle—a mega-float controlled by Rath—was raided. Due to a sudden short-circuit caused by the raiders, Kirito''s fluctlight is damaged, leaving him comatose. Feeling insecure about the people at the Axiom Church, Alice brings the unconscious Kirito back to their hometown—Rulid Village, disregarding her banishment due to an unabsolved crime. Now, Alice is living an ordinary and peaceful life close by the village, wishing for Kirito to wake up.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bishoujo Senshi Sailor Moon Eternal Movie 1', 'Movie', 1, 'Completed', '2021-01-08', NULL, '8', 'The Dead Moon Circus has arrived in Juban with the hopes of liberating their queen, Nehellenia, by stealing the Legendary Silver Crystal for themselves. Using "Lemures," the Circus begins to convert people''s dreams into nightmares in order to collect enough energy to plunge the Earth into darkness and turn it into a planet of death. In order to stop the Circus in their tracks, Usagi Tsukino and her friends must reprise their roles as the Inner Sailor Guardians.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shoujo☆Kageki Revue Starlight: Rondo Rondo Rondo', 'Movie', 1, 'Completed', '2020-08-07', NULL, '8', 'At the performing arts division of Seishou Music Academy, the ever-evolving stage threads the lives of its students together as they tirelessly hone their craft. Yet, as the girls prepare for a new rendition of the previous year''s performance, the carefree Karen Aijou begins to settle for a smaller role. However, her waning passion is reignited by the return of her childhood friend Hikari Kagura, whose sudden transfer to the academy triggers a flurry of changes in the class dynamics.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saint Seiya: Meiou Hades Elysion-hen', 'OVA', 6, 'Completed', '2008-03-07', '2008-08-01', '8', 'After the 12 Gold Saints sacrifice their lives to destroy the Wailing Wall, The Bronze Saints enter the deepest realm of the Underworld, Elysion, where they face off against Hades''s two most powerful servants: The Twin Gods, Hypnos and Thanatos, before they can reach Hades for the final battle.', 1030, 'https://cdn.myanimelist.net/images/anime/9/55659.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Junjou Romantica 3', 'TV', 12, 'Completed', '2015-07-09', '2015-09-24', '8', 'After living together for three years, Misaki Takahashi and Akihiko "Usagi" Usami''s relationship has been progressing smoothly. However, all great relationships have problems, and theirs is just beginning. With a new rival on the horizon, Usagi worries about Misaki''s feelings towards him. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('World Trigger', 'TV', 73, 'Completed', '2014-10-05', '2016-04-03', '8', 'When a gate to another world suddenly opens on Earth, Mikado City is invaded by strange creatures known as "Neighbors," malicious beings impervious to traditional weaponry. In response to their arrival, an organization called the Border Defense Agency has been established to combat the Neighbor menace through special weapons called "Triggers." Even though several years have passed after the gate first opened, Neighbors are still a threat and members of Border remain on guard to ensure the safety of the planet.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Diamond no Ace OVA', 'OVA', 3, 'Completed', '2014-11-17', '2015-03-17', '8', 'One hundred boys, each of them in love with baseball, represent the Seidou High School baseball team. On any team, the Ace is the star of the game. Besides the main heroes, others are striving to attain this position, and each of them has their strengths, weaknesses, and emotional journeys that they have to undertake to become the best that they can be.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Date A Bullet: Dead or Bullet', 'Movie', 1, 'Completed', '2020-08-14', NULL, '8', 'Soon after falling into another world, Kurumi Tokisaki takes interest in a particular white cat. Much to Kurumi''s disappointment, the two part ways.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Tennis no Oujisama vs. Genius 10', 'OVA', 10, 'Completed', '2014-10-29', '2015-06-26', '8', 'After a month abroad, the Foreign Expedition Team has returned to the Japan U-17 training camp. The group consists of 20 players, each with strength and technique that far surpasses those who occupy the camp''s top court. In anticipation of the team''s arrival, the coaches announce that 20 of the best players would be selected for further training. Tension begins to rise when only high school students are chosen to participate, but the middle school students challenge the players who possess the 11th to 20th positions to steal their places.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yowamushi Pedal: Glory Line', 'TV', 25, 'Completed', '2018-01-09', '2018-06-26', '8', 'Fourth season of the Yowamushi Pedal series.', 990, 'https://cdn.myanimelist.net/images/anime/3/88489.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hakuouki Movie 1: Kyoto Ranbu', 'Movie', 1, 'Completed', '2013-08-24', NULL, '8', 'Disguised as a boy, young Chizuru Yukimura leaves her quiet home and heads to Kyoto in search of her missing father—a medical doctor by the name of Koudou. She soon learns that the volatile capital city is a dangerous place to be in as she is ambushed by a pair of ronin while in the streets. Much to her horror, the ronin are slain right in front of her eyes by white-haired, red-eyed samurai, only to be quickly disposed of by three men from the Shinsengumi—a special police force who serve the shogun.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pretty Rhythm: Rainbow Live', 'TV', 51, 'Completed', '2013-04-06', '2014-03-29', '8', 'Naru Ayase is an 8th grader who can see the colors of music when she listens to it. For Naru, who is extremely good at decorating, becoming the owner of a shop like Dear Crown was her dream. One day, she finds out that the manager of a newly-opened shop is recruiting middle school girls who can do Prism Dance, and immediately applies. Naru begins to Prism Dance at the audition, and an aura she''s never experienced spreads out in front of her. At that moment, a mysterious girl named Rinne asks her if she can see "rainbow music."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Ball Super: Super Hero', 'Movie', 1, 'Completed', '2022-06-11', NULL, '8', 'Years after his father is defeated by an adolescent Gokuu Son, Magenta seeks revenge against Gokuu''s family and allies. In his quest to resurrect the defunct Red Ribbon Army, Magenta drafts the services of Dr. Hedo, grandson of the evil legendary scientist Dr. Gero. Hedo embarks to invent a new line of superheroic androids to eliminate Gokuu after Magenta manipulates him into believing that Earth''s most powerful heroes are actually alien villains.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Muteki Kanban Musume', 'TV', 12, 'Completed', '2006-07-05', '2006-09-20', '7', 'Miki Onimaru is a poster girl that works at her mother''s Chinese ramen restaurant. She appears to be a normal girl, but she can become very violent if provoked. She picks a fight with her mother and accquaintances as a result on an almost daily basis, causing a series of troubling mishaps in their otherwise normal lives. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aquarion Evol', 'TV', 26, 'Completed', '2012-01-09', '2012-06-25', '7', '12,000 years after the events in Genesis Aquarion, humans live on the star Vega under constant threat of trans-dimensional beings called Abductors. These enemies originate from Vega’s sister star Altair and raid Vega for human life. As a countermeasure, an organization known as Neo-DEAVA formed to combat the Abductors. They pilot advanced mecha suits called Aquaria and are strictly separated by gender. Boys and girls are not allowed contact; they are even restrained from fighting on the same battlefield. However, events take a shocking turn when an advanced Abductor mecha suit joins the fray. Two teenagers, Mikono and Amata, are dragged into the conflict. Unknowingly, Amata performs a taboo when he summons an Aquaria and initializes what is called the Forbidden Union between male and female Aquaria. Neo-DEAVA is shocked, and the repercussions of Amata’s actions are much farther reaching than he realizes. How was he able to summon an Aquaria? Where did he learn to form a Forbidden Union? And why was Mikono also able to pilot the mecha suit?', 780, 'https://cdn.myanimelist.net/images/anime/6/72743.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga Tetsudou Monogatari', 'TV', 26, 'Completed', '2003-10-05', '2004-04-11', '7', 'In the distant future, trains are no longer bound by their physical tracks. Instead, they take to the skies and travel across the universe on the Galaxy Railways, transporting mankind from planet to planet. However, the Galaxy Railways are no safer than traditional trains: criminals, terrorists, and vile aliens always find a way to stir up trouble. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yoroiden Samurai Troopers', 'TV', 39, 'Completed', '1988-04-30', '1989-03-04', '7', 'Thousands of years ago, the evil emperor Talpa attempted to conquer the Earth. Defeated, he was banished to the Nether Realm and his armor was divided into 9 separate suits. Now, he has returned to conquer Earth, having reclaimed 4 of the suits. The other 5 are in the possesion of those who are the only hope of stopping him: The Ronin Warriors. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wangzhe Rongyao: Rongyao Zhi Zhang - Sui Yue Pian', 'ONA', 4, 'Completed', '2024-01-13', '2024-01-20', '7', 'The exciting 3D series revolves around the main character Li Bai and focuses on the main theme of "love and homecoming." The story invites the viewer to take an adventurous journey with Li Bai to the city of Chang''an on the mainland of Glory of Kings. The young man investigates, discovers the truth and solves the case of his hometown, the City of Broken Moon, demonstrating the pursuit of truth, goodness and beauty in a positive, courageous and forward-looking spirit. In pursuit of a higher purpose, young Li Bai leaves his family and embarks on a long journey. However, a letter from his family, which affects the wanderer''s thoughts of returning to his hometown, brings about a shocking crisis that affects Chang''an.', 180, 'https://cdn.myanimelist.net/images/anime/1137/140696.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimi wa Meido-sama.', 'TV', 12, 'Completed', '2024-10-06', '2024-12-22', '7', 'One day, Hitoyoshi Yokoya wakes up to a mysterious nameless girl dressed as a maid ringing his doorbell, asking to be his servant. With her former master referring her to the Yokoya household, she offers her expertise as an assassin. Intimidated by her background, Hitoyoshi tries to send her away; but when she leaves something behind, he rushes to return it to her and is nearly hit by a truck in the process. With her fast reflexes, the girl saves him just in time, and Hitoyoshi ends up taking her in. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('ChroNoiR Episode.0', 'ONA', 1, 'Completed', '2023-07-28', NULL, '7', 'The anime tells a story from 150 years ago in the town of Planie. A strange disease that turns humans into the undead has spread throughout the land, causing Planie to become known as the cursed city. The priest Kanae lives in a church on the outskirts of town. Ever since he arrived at the town, the number of cases of the disease have decreased. The fate of the town changes when a mysterious man accompanies Kanae.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bastard!! Ankoku no Hakaishin: Jigoku no Chinkonka-hen', 'ONA', 15, 'Completed', '2023-07-31', NULL, '7', 'Two years after the heroic sacrifice of Dark Schneider in the battle against Abigail, Kall-Su, the final surviving member of the Four Divine Kings, is close to seizing global power. As cities and kingdoms fall one after the other, humanity''s last beacon of hope is a group of samurai led by the high priestess Yoko Tia Noto. However, the brutal assaults of Kall-Su''s lieutenants against the samurai''s fortress quickly make the situation desperate. Once more, Yoko''s only way to fix the rapidly devolving crisis is to find Dark Schneider''s soul, which has seemingly deserted Lucien Renlen''s body since the demise of the kingdom of Metallicana.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yi Ren Zhi Xia 5th season', 'ONA', 12, 'Completed', '2022-12-09', '2023-02-24', '7', 'The fifth season of Yi Ren Zhi Xia.', 721, 'https://cdn.myanimelist.net/images/anime/1585/125562.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kagejitsu!', 'ONA', 17, 'Completed', '2022-10-26', '2023-02-15', '7', 'A spin-off chibi anime of Kage no Jitsuryokusha ni Naritakute!.', 945, 'https://cdn.myanimelist.net/images/anime/1014/129578.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jashin-chan Dropkick', 'TV', 11, 'Completed', '2018-07-10', '2018-09-17', '7', 'The demon Jashin-chan has been summoned to Earth by Yurine Hanazono, a girl with a knack for the occult. Unfortunately, Yurine does not actually know how to send Jashin-chan back to Hell. Now stuck on Earth, she must live at Yurine''s apartment as her familiar.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Show By Rock!! #', 'TV', 12, 'Completed', '2016-10-02', '2016-12-18', '7', 'Metropolis of music, MIDICITY. A kitty girl wearing gothic lolita clothing named Cyan is scouted by Maple Arisugawa, the president of a music agency. From there, she meets Chuchu (a pun off of the sound that rabbits make) the honor student rabbit girl, a net geek dog girl named Retoree (from "Retriever"), and an alien sheep (?) girl named Moa. Together, they form the band named "Plasmagica," and aim for the top of the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sanzoku no Musume Ronja', 'TV', 26, 'Completed', '2014-10-11', '2015-03-28', '7', 'The story is about a girl named Ronja who is the daughter of a chief from a tribe of bandits, she lives in a huge castle inside the forest with the bandits. The story follows Ronja as she encounters mystical creatures, making friends with another young child such as herself and experiencing what it is like to live in the forest.', 893, 'https://cdn.myanimelist.net/images/anime/11/68125.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boogiepop wa Warawanai (2019)', 'TV', 18, 'Completed', '2019-01-04', '2019-03-29', '7', 'Hushed exchanges among the female student populace of Shinyo Academy center around an enigmatic supernatural entity. This entity is Boogiepop, a Shinigami who is rumored to murder people at the height of their beauty before their allure wanes. Few know of his true nature: a guardian who, between periods of dormancy, manifests as the alter ego of a high school girl named Touka Miyashita to fend off "the enemies of the world." Now, a string of mysterious disappearances—presumed by the school to be merely runaways—has caused Boogiepop to awaken. But somewhere in the academy, a menacing creature hides, waiting for its opportune moment to strike.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Highschool of the Dead', 'TV', 12, 'Completed', '2010-07-05', '2010-09-20', '7', 'It happened suddenly: The dead began to rise and Japan was thrown into total chaos. As these monsters begin terrorizing a high school, Takashi Kimuro is forced to kill his best friend when he gets bitten and joins the ranks of the walking dead. Vowing to protect Rei Miyamoto, the girlfriend of the man he just executed, they narrowly escape their death trap of a school, only to be greeted with a society that has already fallen.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyoukai no Rinne 3rd Season', 'TV', 25, 'Completed', '2017-04-08', '2017-09-23', '7', 'The third season of Kyoukai no Rinne.', 143, 'https://cdn.myanimelist.net/images/anime/13/85289.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seihou Bukyou Outlaw Star Specials', 'Special', 2, 'Completed', '1998-12-18', '1999-04-25', '7', 'Unaired episodes of Seihou Bukyou Outlaw Star included in the eighth and twelfth volumes of the VHS, designated as episodes 16 and 23.', 974, 'https://cdn.myanimelist.net/images/anime/8/81082.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Vampire Knight Guilty', 'TV', 13, 'Completed', '2008-10-07', '2008-12-30', '7', 'When the missing Zero Kiryuu returns to Cross Academy, Yuuki Cross is relieved to see him safe, but finds that Zero has changed in more ways than one. As a result of choices he made, Zero is plagued by visions, and he seeks to uncover the reason behind them—unaware that the answers may be much closer than he thinks.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nanatsu no Taizai: Eiyuu-tachi wa Hashagu', 'OVA', 1, 'Completed', '2018-11-16', NULL, '7', 'OVA bundled with the 34th volume of the manga.', 14, 'https://cdn.myanimelist.net/images/anime/1369/96304.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('IGPX: Immortal Grand Prix (2005)', 'TV', 13, 'Completed', '2005-10-06', '2006-01-18', '7', 'In the year 2048, people are raving about a fighting race called "Immortal Grand Prix", or IGPX in short, which is faster and more exciting than any of the existing motor sports. The phenomenon is so big that an entire city was built for the racing industry where competitions take place on a huge track. In the "Immortal Grand Prix," two teams of three IG machines, high-tech humanoid mechs driven by humans, race at speeds greater than 400km/h. The teams make three laps of a 60 km course while intercepting the opponent as they vie for a first place finish. The best machine performance, the best pilots and the best teamwork are the only factors that can make them the winners.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('.hack//G.U. Trilogy', 'Movie', 1, 'Completed', '2007-12-22', NULL, '7', 'Based on the CyberConnect2 HIT GAME, now will be released in a CG Movie!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('You Yao', 'ONA', 12, 'Completed', '2020-07-10', '2020-09-18', '7', 'The current government is seeking outsiders and granting them positions according to their abilities in order to update their backwards country and create a new world! Zuo Yunqi is just an ordinary young master, but to save his father, he disguises himself as an outsider to join the government.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bishoujo Senshi Sailor Moon R: Make Up! Sailor Senshi', 'Special', 1, 'Completed', '1993-12-05', NULL, '7', 'Usagi and Chibiusa overhear two girls talking about the Sailor Senshi after they see a poster. Humorously, as the girls discuss which is the smartest, most elegant, strongest, and the leader of the Senshi, Usagi claims those titles for herself. Chibiusa shakes her head at Usagi''s delusion. Clips are shown from the debut of each Sailor Senshi, and that girl''s image song is played in the background. When even Tuxedo Mask is mentioned, and the girls go to leave without having mentioned Sailor Moon, Usagi butts in on their conversation and asks them directly about Sailor Moon. The girls give a series of glowing compliments about Sailor Moon, but unlike they did for the other Senshi, they also list her faults. After the girls leave, Usagi sarcastically apologises for being a clumsy cry-baby and then bursts into tears.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wo Shi Jiang Xiaobai', 'ONA', 12, 'Completed', '2017-11-09', '2018-01-24', '7', 'Ten years ago, Jiang Xiaobai lost all his memories due to a traumatic event he no longer remembers. Now working as a trainee in Editorial Office No.2 of Wen Zheng Magazine, a literary periodical based in Chongqing, he is excited to begin a new chapter of his life: in two days, he finishes his probationary period and officially starts his job as an editor. He gives no thought to his recurring dream of a girl whose face can never clearly see.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Last Exile: Ginyoku no Fam', 'TV', 21, 'Completed', '2011-10-15', '2012-03-24', '7', '"I''ve made up my mind! I''m going to steal that ship!"
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jiu Tian Xuan Di Jue', 'ONA', 40, 'Completed', '2021-08-16', '2021-12-24', '7', 'Of all the races in the world only 3 stand at the top. Each race possesses a master of the martial arts, a Golden Martial God. The balance of power appears to be shifting after Wang Fan''s brother is killed triggering a chain of events that will begin to turn the world upside down. Disguising himself as the Silver Tiger King, Wang Fan becomes a symbol of power and the hope of the human race.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece Movie 03: Chinjuu-jima no Chopper Oukoku', 'Movie', 1, 'Completed', '2002-03-02', NULL, '7', 'The crew comes upon Crown Island where the animals can talk and they makes Chopper their new king. But there are human hunters there also looking for the legendary horns that will give the person who consumes it immense power. Luffy and friends must stop them from destroying this animal kingdom.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou no Yousei Persia', 'TV', 48, 'Completed', '1984-07-06', '1985-05-31', '7', '11-year-old Persia has grown up alongside the animals on the Serengeti plains of Africa. Twins Riki and Gaku Muroi and their grandfather, Gouken, bring Persia to Japan with them, where she will live with a couple (who Persia calls Mama and Papa) that own a grocery store. During the flight to Japan, Persia finds herself in the "Lovely Dream" where she meets the Fairy Queen, who explains that the Lovely Dream is in danger and requests Persia''s help. Giving Persia a magical headband (which can also summon a magical baton) that allows her to transform into a teenage girl, connecting her to the Lovely Dream and allowing her to use magic. She is sent with three kappa back into the regular world with the mission of collecting love energy to thaw the frozen Lovely Dream. If Persia fails her task of collecting love energy or if someone catches her using magic, Riki and Gaku will be transformed into women.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Di Gi Charat', 'TV', 16, 'Completed', '1999-11-30', '1999-12-24', '7', 'Having infiltrated Earth with blind ambitions of stardom, Princess Di Gi Charat—also known as Dejiko—of the planet Di Gi Charat quickly realizes that money makes the world go around, of which she has none. On a never-ending, futile mission to change her socioeconomic status, Dejiko, her sidekick Petit Charat "Puchiko", her royal guardian Gema, and her competitive coworker Hikaru Usada try everything in their power to overturn the soul-crushing mundanity of working in retail—all in a series of surreal yet ironically relatable attempts at spicing up their daily lives.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('To Heart 2 OVA', 'OVA', 3, 'Completed', '2007-02-28', '2007-09-28', '7', 'A collection of stories involving the girls of To Heart 2, with each episode focusing on a different character.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sumomomo Momomo: Chijou Saikyou no Yome', 'TV', 22, 'Completed', '2006-10-06', '2007-03-16', '7', 'Koushi Inuzuka is a smart high school student who aims to become a public prosecutor. Unfortunately for our good guy, he was born into a martial arts family whose head (ie his father) only knows one language: violence. When Koushi was still a baby, his father made a pact with his biggest rival to marry Koushi to his opponent-turned-friend''s daughter. The union of the two blood lines is supposed to bring forth Earth''s strongest martial arts clan. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wata no Kuni Hoshi', 'Movie', 1, 'Completed', '1984-02-11', NULL, '7', 'After two-month-old kitten Chibi-neko is abandoned by her former owners, she is found by 18-year-old Tokio. Although his mother is allergic to cats and has a great fear of them, she agrees to let him keep the kitten because she fears he is becoming too withdrawn after failing his university entrance exams. Chibi-neko soon falls in love with Tokio.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mugen no Juunin', 'TV', 13, 'Completed', '2008-07-14', '2008-12-29', '7', 'Manji is an infamous swordsman in feudal Japan who is known as the "Hundred Man Killer," as he has killed one hundred innocent men. However, there is something far more frightening than his ominous reputation: the fact that he is immortal. This is the handiwork of eight-hundred-year-old nun Yaobikuni, who placed bloodworms capable of healing almost any wound in Manji''s body.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jibi Eopseo', 'ONA', 8, 'Completed', '2024-11-01', '2024-11-15', '7', 'Go Hae-jun, who ran away from home, and Baek Eun-young, a troublemaker who lives in a tent without a home. The two people who met through bad luck end up living together in an old, abandoned dormitory. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Magic Maker: Isekai Mahou no Tsukurikata', 'TV', 12, 'Completed', '2025-01-09', '2025-03-27', '7', 'A 30-year-old man who dreams of becoming a wizard suddenly loses his life. Reincarnated in another world as a young child named Shion, he grows up alongside Marie, his dependable older sister who adores him. Shion eagerly anticipates using magical powers, but he discovers that the new world seemingly does not have any magic. He spends the ensuing years as a gloomy and dejected child until a mystical phenomenon at a nearby lake catches the siblings'' attention and breathes life back into his magical dream.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ququ Bucai, Zaixia Yeguai 2nd Season', 'ONA', 16, 'Completed', '2023-07-02', '2023-10-15', '7', 'The second season of Ququ Bucai, Zaixia Yeguai.', 492, 'https://cdn.myanimelist.net/images/anime/1530/136847.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kawaisugi Crisis', 'TV', 12, 'Completed', '2023-04-07', '2023-06-23', '7', 'Upon first seeing Earth from the Azatos Empire''s survey ship, Chief Investigator Liza Luna plans to eradicate every lifeform on it immediately, leaving behind only useful resources. While surveying the planet, Liza discovers that human civilization has evolved at a pathetic rate compared to other lifeforms.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimi no Iru Machi', 'TV', 12, 'Completed', '2013-07-13', '2013-09-28', '7', 'Haruto Kirishima lived a calm life out in the countryside, away from the fast-paced life of the city. Then Yuzuki Eba appeared in his life out of nowhere, having come from Tokyo to briefly live with her family. Their time together left him enamored with the memories of that short period before she just as abruptly disappeared from his life, and left him full of questions.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Overlord: Ple Ple Pleiades 3', 'ONA', 13, 'Completed', '2018-07-10', '2018-10-02', '7', 'Super deformed parody shorts of Overlord III streamed on Kadokawa''s official YouTube channel.', 945, 'https://cdn.myanimelist.net/images/anime/1386/93157.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Isshuukan Friends. Specials', 'Special', 12, 'Completed', '2014-06-18', '2014-11-19', '7', 'Specials included in the Blu-ray/DVD releases.', 143, 'https://cdn.myanimelist.net/images/anime/8/69879.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lian Qi Lianle 3000 Nian', 'ONA', 16, 'Completed', '2022-10-07', '2023-01-13', '7', 'Bai Qiuran is one of Qingming''s disciples, and has a lot of potential to be his successor. Even though he''s still a Qi cultivator, he believes he will finally make his breakthrough this time. As such, Bai Qiuran decides to go down the mountain where exciting experiences await him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('ACCA: 13-ku Kansatsu-ka Specials', 'Special', 6, 'Completed', '2017-04-21', '2017-08-29', '7', 'The Kingdom of Dowa is free at last of political tensions and coup d''état rumors. Jean and Lotta Otus spend their days together with their best friend Niino, enjoying carefree conversations accompanied by alcohol and cigarettes. Although they look out for any potential threat to Dowa, even the administrative leaders of ACCA seem to relax in the long-awaited warmth of peace.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Akkun to Kanojo', 'TV', 25, 'Completed', '2018-04-06', '2018-09-21', '7', 'Despite his incredible bashfulness, Atsuhiro "Akkun" Kagari has landed the girl of his dreams: the sweet and loveable Non Katagiri. However, his embarrassment for affectionate acts—from giving compliments to exchanging a kiss—causes him to act harsh and downright mean to Katagiri in their day-to-day lives. But Akkun is still very much a boy in love; he shows his admiration for Katagiri in his own way. From tailing her in order to take her picture to eavesdropping in on her conversations, he ends up stalking his own girlfriend. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Binan Koukou Chikyuu Bouei-bu LOVE! LOVE! LOVE!', 'OVA', 1, 'Completed', '2017-08-26', NULL, '7', 'The older boys are graduating school and recount their memories together. The next day everyone defends the graduation ceremony against Zundar and Dadacha''s Second Button Monster but Yumoto struggles using his love power.', 871, 'https://cdn.myanimelist.net/images/anime/6/85527.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Baja no Studio: Baja no Mita Umi', 'OVA', 1, 'Completed', '2020-02-21', NULL, '7', 'Living in an animation studio fawned over by its staff, Baja and his best friend Ga-chan have all sorts of fun every day. While working on a particularly stressful project, the studio''s head director, Kanako, wishes that she could take a trip to the sea. This makes Baja wonder what sort of place the sea might be and if he and Ga-chan could use magic to experience it as well.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nezha Chuanqi', 'TV', 52, 'Completed', '2003-06-01', '2004-07-01', '7', 'The Legend of Nezha narrative The story of Natra, the heavenly boy who was born bare, very mischievous, but the temperament, the mentality of goodness, always towards the righteous. With powerful martial arts and magic, he tried to save the evil to bring peaceful life for people in the time of raging love.', 156, 'https://cdn.myanimelist.net/images/anime/1396/101385.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mass Effect: Paragon Lost', 'Movie', 1, 'Completed', '2012-11-29', NULL, '6', 'Mass Effect: Paragon Lost is the prequel to the highly-anticipated Mass Effect 3 and follows the early career of Alliance Marine, James Vega. Vega leads an elite Special Forces squad into battle against a mysterious alien threat known as The Collectors. Stationed at a colony in a remote star system, Vega and his soldiers must protect the civilians from a ruthless invasion determined to capture the population for unknown purposes. Learn more about the Mass Effect universe with an unprecedented glimpse into the haunted past of Mass Effect''s newest hero! 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hidamari Sketch x ☆☆☆ Recap', 'Special', 1, 'Completed', '2012-09-26', NULL, '6', 'Recap of Hidamari Sketch x ☆☆☆ series included on the limited edition Blu-Ray "Hidamari Sketch Fan Disc / Mousugu! Hidamari Sketch x Honeycomb".', 791, 'https://cdn.myanimelist.net/images/anime/11/70497.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kami wa Game ni Ueteiru.', 'TV', 13, 'Completed', '2024-04-01', '2024-06-24', '6', 'When Leoleshea, a dragon god, is accidentally awoken from her sleep within a glacier, she demands this era''s very best game player be brought before her. After a year of waiting, she meets Fay Theo Philus, an apostle—a human granted a supernatural ability called an Arise and thus given permission to challenge the gods in games. Fay and Leoleshea realize they share a passion for games, whether it be with cards or a battle of wits with a god. Declaring that she likes this human, Leoleshea allows Fay to call her "Leshea" and team up with her to play in the gods'' games.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Konbini Kareshi', 'TV', 12, 'Completed', '2017-07-07', '2017-09-29', '6', 'The lives of high school freshmen Haruki Mishima and Towa Honda revolve around studying, clubs, and girls. Amid their hectic routines, romance is certainly budding for the two best friends. Since childhood, Haruki has been pining over Miharu Mashiki, and a chance encounter at the convenience store reignites his feelings. As for Towa, the class representative Mami Mihashi has caught his eye; but unfortunately for him, his affections are not reciprocated.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fudanshi Koukou Seikatsu: Sports no Aki, Bonnou no Aki', 'Special', 1, 'Completed', '2016-10-14', NULL, '6', 'A bonus episode bundled with the DVD and Blu-ray releases taking place at a sports day.', 254, 'https://cdn.myanimelist.net/images/anime/9/89162.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Inazma Delivery: Dougyousha Attack-hen', 'TV', 10, 'Completed', '2017-12-08', '2018-03-02', '6', '', 463, 'https://cdn.myanimelist.net/images/anime/1452/112265.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toji no Miko Recap', 'Special', 1, 'Completed', '2018-03-30', NULL, '6', 'A summary of the first 12 episodes of Toji no Miko.', 896, 'https://cdn.myanimelist.net/images/anime/1614/91864.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ikemen Sengoku: Toki wo Kakeru ga Koi wa Hajimaranai', 'TV', 12, 'Completed', '2017-07-12', '2017-09-27', '6', '"Sasuke Sarutobi" is an average college student at Kyoto University studying time slips as a hobby until the day he falls into a time slip himself, transporting him to the Sengoku Period. Upon arrival, Sasuke encounters several warlords he could only ever dream of meeting: Toyotomi Hideyoshi, Tokugawa Ieyasu, and the famous "Demon King of the Sixth Heaven" Oda Nobunaga, who takes him in as a vassal. Introducing several modern concepts to the warlords varying from playing tennis to sending chain letters, Sasuke finds his place in an old but utterly new world. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shi Wan Ge Leng Xiaohua', 'ONA', 12, 'Completed', '2012-07-11', '2013-08-01', '6', 'One Hundred Thousand Bad Jokes is a parody series that references folktales, classic literature, and modern comics, films, and animation from a variety of countries and regions.', 524, 'https://cdn.myanimelist.net/images/anime/5/79764.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mirai no Watashi', 'Special', 2, 'Completed', '2016-03-15', '2017-04-27', '6', 'The shorts are part of McDonald''s new "Crew ni Narou. Campaign" (Join the Crew. Campaign) to attract part-time restaraunt staff members.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('KanColle: Itsuka Ano Umi de', 'TV', 8, 'Completed', '2022-11-04', '2023-03-25', '6', 'The dawn of a decisive battle nears in Leyte Gulf against the Abyssal Fleet, the mysterious enemies that occupy the sea. As the only ones capable of fighting them, Kanmusu—young girls possessing the souls of warships—reorganize in preparation. The Shiratsuyu-class destroyer Shigure is assigned to the First Striking Force, Third Section—also known as 1YB3H.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oishinbo: Kyuukyoku tai Shikou, Chouju Ryouri Taiketsu!!', 'Special', 1, 'Completed', '1992-12-11', NULL, '6', 'Ultimate Menu and Supreme Menu square off in a cooking battle about dishes that promote longevity. For Supreme''s Kaibara Yuzan and Ultimate''s Yamaoka Shirou (who are father and son), this confrontation is more than strictly business: it''s personal.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Inakappe Taishou', 'TV', 104, 'Completed', '1970-10-04', '1972-09-24', '6', 'A comedy about a country boy that travels to the city to study judo. He ends up meeting the daughter of a prominent dojo and her judo skilled cat. Each episode features 2 stories. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Time Bokan Series: Time Patroltai Otasukeman', 'TV', 53, 'Completed', '1980-02-02', '1981-01-31', '6', 'Burning with ambitions to become the most beautiful woman, the most renowned scientist, and the greatest hero the world has ever known, three villains, Atasha, Sekobitchi and Duwarusuki, unite. The trio are Time Patrollers, the keepers and protectors of the annals of history. But, this is only a cover for the trio, as the villains are league with a nefarious leader, who is trying to alter the course of history to suit his desires, and, under his instructions, the trio travel in time with the aim of tampering with recorded history. Only Hikaru and Nana, disguised as the Otasukemen, stand between the villains and their goals. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Biohazard: Infinite Darkness', 'ONA', 4, 'Completed', '2021-07-08', NULL, '6', 'Federal Agent Leon S. Kennedy teams up with TerraSave staff member Claire Redfield to investigate a zombie outbreak.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dr. Slump Movie 07: Arale-chan N-cha! Penguin Mura yori Ai wo Komete', 'Movie', 1, 'Completed', '1993-07-10', NULL, '6', 'Unable to entertain their princess Puruah, the kingdom of Yapaya requests professor Senbei to create a comedic robot capable of making her laugh for the first time in her life.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Moom', 'Movie', 1, 'Completed', '2016-03-05', NULL, '6', 'Every forgotten object has a memory with its previous owner still attached. This is a story of Moom, one of those memories stuck in this world. One day, Moom meets another memory just like him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon XY: Koukoku no Princess Diancie', 'Special', 1, 'Completed', '2014-07-17', NULL, '6', 'In order to save the Diamond Ore Kingdom from certain danger Princess Diancie and the Carbink who serve as her butlers set off together on a journey to find the legendary Pokémon Xerneas. But who is that waiting for them on the road ahead...!? 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece: Dr. Chopper no Bouken Karte - Uragirimono-tachi no Masquerade', 'Special', 1, 'Completed', '2025-10-12', NULL, '6', 'The ninth recap special of the Egghead arc.', 1030, 'https://cdn.myanimelist.net/images/anime/1402/152287.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuroi Rayquaza Kourin', 'Special', 1, 'Completed', '2024-11-18', NULL, '6', 'A promotional video to announce the arrival of Black Rayquaza in the Pokemon Scarlet Violet Terra Raid Battle. It''s part of a larger campaign with Black Rayquaza who will make appearances across various Pokemon media.', 413, 'https://cdn.myanimelist.net/images/anime/1525/146552.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Artiswitch Collection/2021', 'ONA', 1, 'Completed', '2021-11-05', NULL, '6', 'An original animation showcasing the various outfits Nina wore throughout Artiswitch, in the style of a runway fashion show.', 974, 'https://cdn.myanimelist.net/images/anime/1453/133129.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Haigakura', 'TV', 13, 'Completed', '2024-10-07', '2025-09-26', '6', 'The balance of the world is deeply shaken when malevolent gods known as the Four Perils break their seals and disappear together with eight million minor deities. In the absence of gods, lands become barren and famine looms in the country of the Eight Immortals. In order to restore the fragile harmony, kashi—gifted dancers and singers—must hunt the missing gods in other realms, use their performance skills to charm the deities, and seal them using the power of their rosaries.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fire Emblem Heroes - Book V Ending Movie', 'ONA', 1, 'Completed', '2021-11-28', NULL, '6', 'Eitri has a few words for all you summoners out there. Watch if you''re feeling bold, but be warned… It''s not for the faint of heart! 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oshougatsuda yo! Pokemon Special!', 'Special', 1, 'Completed', '1999-01-01', NULL, '6', 'A recap special of the first seventy-seven episodes of the Pokemon anime.', 621, 'https://cdn.myanimelist.net/images/anime/1045/106871.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Frame Arms Girl Movie: Kyakkya Ufufu na Wonderland', 'Movie', 1, 'Completed', '2019-06-29', NULL, '6', 'A compilation movie of the TV series containing a newly added footage.', 1145, 'https://cdn.myanimelist.net/images/anime/1781/124589.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yume Oukoku to Nemureru 100-nin no Oujisama', 'TV', 12, 'Completed', '2018-07-05', '2018-09-20', '6', 'The heroine is a normal girl, until one day she is invited to another world and becomes the princess of the dream world, where people use dreams as the energy to live. One day, the dream world is being attacked by something called "yumekui" ("dream eater"), and many princes are being attacked by it. The heroine must wake them up to save the dream world, as the princes are unable to wake up due to having their dreams stolen.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sex: Prologue', 'OVA', 1, 'Completed', '2018-05-07', NULL, '6', 'The anime depicts an original story before Kaho arrives, when Yuki and Natsu have just met in Okinawa.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Osomatsu-san: Hajimaru Hajimari', 'Special', 6, 'Completed', '2018-08-02', NULL, '6', 'A Daiichi (pachinko company) x Osomatsu-san fan event will be held on August 2nd. Character goods, attractions, mascots, and a mini-anime where the cast recreates classic Japanese tales. In particular: Tsuru no Ongaeshi, Urashima Tarou, Kaguya-hime, Saru Kani Gassen, Kintarou, and Momotarou.', 939, 'https://cdn.myanimelist.net/images/anime/1964/93279.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Garo: Guren no Tsuki', 'TV', 23, 'Completed', '2015-10-10', '2016-04-02', '6', 'Monsters known as "Horrors" have invaded the world, entering through gates from the Makai Realm of Darkness. These corrupt, demonic creatures have the ability to seize human bodies and feed on their souls. Citizens who are out past sunset will likely never see the sun rise again, but those who live in the capital city have no need to worry—they are protected by a spiritual force field created by the sorcerer group Onmyouji.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kao Haru CMs', 'Special', 4, 'Completed', '2018-12-28', '2020-08-16', '6', 'Kao Japan is a chemical and cosmetics company. For their spring campaign to bring in the freshness and happiness of their customers, they have commissioned Yoshiharu Satou to create animated commercials.', 1050, 'https://cdn.myanimelist.net/images/anime/1667/105772.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boku no Oldies wa All Color', 'OVA', 1, 'Completed', '1987-12-10', NULL, '6', 'A minimalist adaptation of Seizo Watase''s manga of the same name. It contains 5 stories of slow paced vignettes of romance whose only dialogue lies within the "oldies" being played as background music.', 1009, 'https://cdn.myanimelist.net/images/anime/11/85164.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gou-chan.: Moko to Chinjuu no Mori no Nakama-tachi', 'Movie', 1, 'Completed', '2017-01-29', NULL, '6', 'Gou-chan arrives on earth in search of the heart plasma that will restore peace to his home planet EX Panda. He meets a human girl named Moko, who lives on a farm with her grandfather, and several strange animals called Chinjuumin. They pass their days enjoyably, but trouble begins when humans invade the forest home of the Chinjuumin looking to capture them. Meanwhile, Moko''s family life gets complicated when her grandmother arrives from the city.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shinrabanshou: Tenchi Shinmei no Shou', 'ONA', 1, 'Completed', '2014-06-29', NULL, '5', 'The ONA produced to celebrate the 10th anniversary of Shinra Bansho Choco from Bandai.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Strange+ Special', 'Special', 1, 'Completed', '2014-04-18', NULL, '5', 'Unaired episode of Strange+ included on the Blu-ray/DVD release.', 785, 'https://cdn.myanimelist.net/images/anime/2/62059.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Choujin Locke: Mirror Ring', 'OVA', 1, 'Completed', '2000-12-22', NULL, '5', '"Locke the Superman, Mirror Ring" is the 30th Anniversary Episode following ''84, "Locke the Superman, Mirrenian the witch" (Theatrical Version), ''89, "Lordleon" (OVA) and ''91, "New World Command" (OVA). 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fujiko Fujio A no Mumako', 'Special', 1, 'Completed', '1990-07-03', NULL, '5', 'Based on the horror novel by Fujio (A) Fujiko.', 802, 'https://cdn.myanimelist.net/images/anime/9/52375.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('High School Agent', 'OVA', 2, 'Completed', '1987-07-01', '1987-10-02', '5', 'Based on a manga by Tanimura Hitoshi, serialized in Comic Burger.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oshare Majo Love and Berry: Shiawase no Mahou', 'Movie', 1, 'Completed', '2007-03-21', NULL, '5', 'A movie based on the popular fashion card and arcade dance game aimed at young girls. The movie features the magical Princesses Love and Berry, who posess Fashion Magic. While Love and Berry are best friends, they become rivals for attention when they''re on the dance floor.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('SF Saiyuuki Starzinger (Movie)', 'Movie', 1, 'Completed', '1979-03-17', NULL, '5', 'Princess Aurora, the only survivor of her planet destroyed by evil mutants, is resolved to put an end to the mutant menace in the galaxy along with three enhanced human cyborgs Jesse Dart, Porkos and Aramus, she travels space in the Cosmos Queen to the Dekkos System to fight the final battle.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyoufu no Bio Ningen Saishuu Kyoushi', 'OVA', 1, 'Completed', '1988-02-06', NULL, '5', 'At a run down school the "Ultimate Teacher" Ganpachi is sent to get things back on track and prepare the delinquent students for the real world. But the students don''t want Ganpachi ruining the gang they got going so their boss, Hinako, fights back Ganpachi aided by her secret power...her lucky kitty underwear. Things get more interesting when we findout Ganpachi is the result of genetic experiments.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seiken Densetsu: Legend of Mana - The Teardrop Crystal', 'TV', 12, 'Completed', '2022-10-08', '2022-12-24', '5', 'Not far from the town of Domina lives Shiloh, a boy who keeps hearing a voice in his dreams about a mission he must fulfill. But what mission could he be needed for remains unknown. That all changes when he meets two Jumi, a race that’s hunted for their unique gemstones, as a sudden outbreak of attacks against the Jumi occurs. His dream, his quest, becomes clear—help the Jumi and their gemstones!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seishun Fuufu Monogatari: Koiko no Mainichi', 'OVA', 2, 'Completed', '1989-09-22', '1990-03-23', '5', 'Based on the romance manga "Koiko no Mainichi " by George Akiyama, serialized in Weekly Manga Goraku.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bloodivores', 'TV', 12, 'Completed', '2016-10-01', '2016-12-17', '5', '60 years ago, a strange case of insomnia struck the population, forcing them to stay awake for more than a full week. The victims, completely sleep deprived, all went mad. To cure this illness, a new medicine was produced, but the side effects turned the patients into vampires. Humanity went to war against this new species and triumphed, but some of the vampires managed to survive. Born from a Human and a Vampire, the main character Mi Liu, "The Child of Hope," is to represent the new hope that will connect the two species. Ringleader of a bank robbery, Mi Liu is arrested and transferred to a special prison of the National Defense Agency that monitors Vampires. Trying to break free with Anji, Mi Liu is attacked by strange monsters and he finds out that the prison location corresponds to the birthplace of Vampires, the old capital "Blue Town." Why are Vampires trapped in Blue Town? What are those strange monsters attacking them? Our heroes must fight to solve those mysteries.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Over the Rainbow', 'Special', 1, 'Completed', '2022-06-11', NULL, '5', 'Original anime short that aired during the Fuji TV''s Geinin Anime Kantoku (Entertainer Anime Director) variety show.', 643, 'https://cdn.myanimelist.net/images/anime/1851/124824.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bibury', 'Special', 1, 'Completed', '2017-08-19', NULL, '5', 'A promotional video for the anime studio Bibury, founded by anime director Tensho. The studio is named after the town of Bibury in England. The video was published on the studio''s website.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ozmafia!!', 'TV', 12, 'Completed', '2016-07-07', '2016-09-22', '5', 'The anime will feature an original story from the game on which it is based.', 200, 'https://cdn.myanimelist.net/images/anime/9/80549.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sou: Uchiage Hanabi, Shita kara Miru ka? Yoko kara Miru ka?-hen', 'Special', 1, 'Completed', '2017-08-09', NULL, '5', 'A collaboration between the Lotte brand ice-cream Sou and the film Uchiage Hanabi, Shita kara Miru ka? Yoko kara Miru ka?.', 791, 'https://cdn.myanimelist.net/images/anime/11/87372.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jijia Yingxiong: Ji Dou Yongzhe 2nd Season', 'TV', 8, 'Completed', '2023-11-10', '2023-12-29', '5', '', 90, 'https://cdn.myanimelist.net/images/anime/1109/141139.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Snow Jiko wa No! No! Yuki Daruman no Fuyumichi Koutsuu Anzen', 'OVA', 1, 'Completed', '2003-08-05', NULL, '5', 'A snowman teaches traffic safety for slippery icy winter roads.', 74, 'https://cdn.myanimelist.net/images/anime/11/84778.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eiyuu Densetsu: Head On! Master Senshi', 'OVA', 1, 'Completed', NULL, NULL, '5', 'Transformers Heroic Legend was a VHS promo released at the end of Transformers Headmasters. The tape contained 3 episodes covering the major plots of the previous 3 series in Japan (Tatakae! Chou Robot Seimeitai Transformers, Tatakae! Chou Robot Seimeitai Transformers 2010, and Transformers Headmasters). 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Made in Abyss Movie 1: Tabidachi no Yoake', 'Movie', 1, 'Completed', '2019-01-04', NULL, '8', 'The movie is a compilation of episodes 1-8 of the 2017 television series with new scenes added for the introduction. It covers the period from when Riko descends into the Abyss with her robot companion Reg, reaching the second layer where they meet the White Whistle Ozen who reveals information about Riko''s mother.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nomad: Megalo Box 2', 'TV', 13, 'Completed', '2021-04-04', '2021-06-27', '8', 'Megalo Box is an advanced form of boxing where competitors wear metal frames called Gear. When the first ever Megalonia tournament took place, "Gearless" Joe became its champion and known to all as a legendary fighter. However, soon after, he lost an exhibition match against the second champion and vanished from the public eye.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Major S4', 'TV', 26, 'Completed', '2008-01-05', '2008-06-28', '8', 'Having finished high school, Gorou Honda sets his sights on becoming a professional baseball player. His dreams are much more ambitious than becoming a Japanese Baseball League player, so he instead decides to move to the birthplace of his beloved sport, America, in order to play in the Major League.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('xxxHOLiC Rou', 'OVA', 2, 'Completed', '2010-04-23', '2011-03-09', '8', 'Ten years after the events of xxxHOLiC Shunmuki, a melancholic Kimihiro Watanuki has taken over the shop formerly run by the mysterious Yuuko due to a promise he made to her. His companions Maru, Moro, and Mokona live together with him in relative contentment, and some familiar faces arrive every now and then: former rival turned-steadfast friend Shizuka Doumeki, and the former psychic prodigy Kohane Tsuyuri. While Kohane studies folklore under Doumeki at university, they encounter a case that is perfect for the master of the shop.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece: Episode of Merry - Mou Hitori no Nakama no Monogatari', 'Special', 1, 'Completed', '2013-08-24', NULL, '8', 'After Brook questions the origin of the Mini Merry name, Usopp and Chopper Tony Tony recall the adventures of the Straw Hat Crew''s beloved ship, friend, and crew member—the Going Merry. Usopp abandons the crew for a fight over the Going Merry while Robin Nico leaves with the government''s top assassin group, CP9. In order to bring the crew back together, Monkey D. Luffy and the remaining Straw Hats follow Robin to rescue her from the claws of the World Government.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hachimitsu to Clover II', 'TV', 12, 'Completed', '2006-06-30', '2006-09-15', '8', 'Back from his journey across Japan, Yuuta Takemoto reminisces about his college life so far. He has matured significantly since his second year and is motivated to move forward.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hunter x Hunter: Greed Island', 'OVA', 8, 'Completed', '2003-02-05', '2003-04-16', '8', 'After the battle with the Spiders, the search for Ging continues as Gon and Killua decided to once again attempt to purchase the rare game "Greed Island." However, Gon came up with a better plan, which was to volunteer to complete the game for the billionaire who owned it. But some training must be done, as Gon and Killua''s abilities are still at a developing stage and "Greed Island" is no simple game for anyone to play with. It is the infamous game that could easily lead to one''s death. Based on the manga by Togashi Yoshihiro.', 607, 'https://cdn.myanimelist.net/images/anime/1902/122320.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece Movie 14: Stampede', 'Movie', 1, 'Completed', '2019-08-09', NULL, '8', 'Monkey D. Luffy and the Straw Hats arrive aboard the Sunny to the Pirates Festival, the world''s largest celebration created by and for pirates. Buena Festa, the festival organizer, invites the Straw Hats and all Worst Generation crews to partake in the festivities. Luring even Shichibukai and Marines to its shores, it seems that no pirate or sailor can resist the enticing secrets that the event hides behind its glamor.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan', 'TV', NULL, 'Airing', '1996-01-08', NULL, '8', 'Shinichi Kudou, a high school student of astounding talent in detective work, is well known for having solved several challenging cases. One day, when Shinichi spots two suspicious men and decides to follow them, he inadvertently becomes witness to a disturbing illegal activity. Unfortunately, he is caught in the act, so the men dose him with an experimental drug formulated by their criminal organization, leaving him to his death. However, to his own astonishment, Shinichi lives to see another day, but now in the body of a seven-year-old child.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cardcaptor Sakura', 'TV', 70, 'Completed', '1998-04-07', '2000-03-21', '8', 'Ten-year-old Sakura Kinomoto is an ordinary fourth-grade student living in Tomoeda until, one day, she stumbles upon a mysterious book of cards titled "The Clow." Pondering over her discovery, she unintentionally causes a magical gust of wind to scatter the cards all over town.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cang Yuan Tu 2', 'ONA', 36, 'Completed', '2024-12-06', '2025-08-01', '8', 'The second season of Cang Yuan Tu.', 800, 'https://cdn.myanimelist.net/images/anime/1530/146755.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuroshitsuji: Midori no Majo-hen', 'TV', 13, 'Completed', '2025-04-05', '2025-06-28', '8', 'Queen Victoria of England has ordered her loyal watchdog, 13-year-old Earl Ciel Phantomhive, to investigate a series of suspicious deaths in southern Germany. Across multiple villages, all the victims have one thing in common: they had entered the so-called Werewolves'' Forest right before they developed strange deformities and subsequently died. The rumors put blame on a "witch''s curse," the nearby villagers'' firm belief based on old folklore.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cang Yuan Tu', 'ONA', 26, 'Completed', '2023-06-22', '2023-12-07', '8', 'Meng Chuan witnessed his mother killed before his eyes, so he trained very hard hoping to one day avenge her death. But his peaceful days were broken as his wedding engagement was called off, an invasion by foreign forces, the sanctuary fell into enemy hands... In order to protect the people of Ning City, he picked up his sword and vowed to be the strongest. This is a heavy responsibility and a long journey.', 800, 'https://cdn.myanimelist.net/images/anime/1785/136462.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yoru wa Mijikashi Arukeyo Otome', 'Movie', 1, 'Completed', '2017-04-07', NULL, '8', 'On a mysterious night that seems to last for a year, an ordinary college student continues to chase one of his underclassmen, a girl with black hair—the girl of his dreams. Up until now, he has been relying on a simple plan, which is to calculatingly bump into her every day while making it seem like a meaningful coincidence. However, his efforts remain futile as their relationship is not progressing at all.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga Eiyuu Densetsu: Die Neue These - Seiran 2', 'Movie', 4, 'Completed', '2019-10-25', NULL, '8', 'Marquis Reinhard von Lohengramm''s plot to destabilize the Free Planets Alliance succeeds when the treacherous former Rear Admiral Arthur Lynch instigates a coup on Heinessen. Equipped with a plan crafted by Reinhard himself, Lynch encourages his longtime friend Admiral Dwight Greenhill to supervise the National Salvation Military Council''s toppling of the civilian government. Seeking to defend democracy and restore the Alliance constitution, Admiral Yang Wen-li faces off against his fellow citizens—and, regrettably, the father of his devoted adjutant Lieutenant Frederica Greenhill.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chihayafuru', 'TV', 25, 'Completed', '2011-10-05', '2012-03-28', '8', 'As a child, Chihaya Ayase had only one dream: to see her elder sister Chitose become Japan''s most successful model. However, upon defending her ostracised classmate Arata Wataya from his bully—Chihaya''s childhood friend Taichi Mashima—she discovers the world of competitive karuta and soon becomes enamoured with the sport.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan Movie 20: Junkoku no Nightmare', 'Movie', 1, 'Completed', '2016-04-16', NULL, '8', 'On a dark night, the Japanese police is raided by a spy. Different countries'' intelligence agencies—such as England''s MI6, Germany''s BND, and America''s CIA—as well as the FBI''s secret files are going to be taken, but public safety officers lead by Tooru Amuro arrive just in time. The spy steals a car and escapes. The spy and Amuro are then locked in a dead heat on the highway, and just as it is about to cause an accident with multiple cars, the spy''s car is hit by FBI agent Shuichi Akai''s rifle bullet and falls of the roadway.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Girls & Panzer: Saishuushou Part 3', 'Movie', 1, 'Completed', '2021-03-26', NULL, '8', 'The quarterfinal round of the Winter Continuous Track Cup is in full swing, and each school is going all out. What started as a furious back-and-forth firefight between Ooarai Girls Academy and Chi-Ha-Tan Academy has become a 12-hour jungle slugfest with neither team having the advantage and almost everyone running on fumes. In spite of this, Miho Nishizumi and her teammates continue to fight into the morning, hoping to land a decisive blow before their rivals.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kamisama Hajimemashita: Kamisama, Shiawase ni Naru', 'OVA', 1, 'Completed', '2016-12-20', NULL, '8', 'Nanami Momozono, current land god of Mikage Shrine, and her fox familiar Tomoe have faced many obstacles during their time together, but none so challenging as the one posed by the wealth god Ookuninushi—if Tomoe''s wish to be human is granted, he must learn to live as one, and Nanami will have to return to being a human.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tengen Toppa Gurren Lagann Movie 1: Gurren-hen', 'Movie', 1, 'Completed', '2008-09-06', NULL, '8', 'Animation studio Gainax presented a website for the release of a movie adaptation of the Tengen Toppa Gurren Lagann TV series in the fall of 2008. Both the original director and series script editor will return to work on the new project. Gainax will also be hosting four events to celebrate this occasion at this year''s Tokyo International Anime Fair, featuring voice actors from the anime.', 321, 'https://cdn.myanimelist.net/images/anime/1270/115752.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Little Busters! Refrain', 'TV', 13, 'Completed', '2013-10-05', '2013-12-28', '8', 'Following the Little Busters after they lost their first baseball game, the team decides to have a pancake party. It has been almost one semester since the return of Kyousuke Natsume. As usual, Riki Naoe continues to help the Little Busters'' members—both old and new—with confronting their inner struggles. However, strange happenings begin to occur, leading Rin Natsume and Riki closer to unraveling the truth behind the "secret of this world."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bakuman.', 'TV', 25, 'Completed', '2010-10-02', '2011-04-02', '8', 'As a child, Moritaka Mashiro dreamt of becoming a mangaka, just like his childhood hero and uncle, Tarou Kawaguchi, creator of a popular gag manga. But when tragedy strikes, he gives up on his dream and spends his middle school days studying, aiming to become a salaryman instead.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Digimon Adventure: Last Evolution Kizuna', 'Movie', 1, 'Completed', '2020-02-21', NULL, '8', 'As the Chosen Children and their partner Digimon live happily together in the human world, Taichi Yagami and Yamato Ishida, alongside their friends, dedicate themselves to maintaining this hard-earned peace. Though united by this innate responsibility, each one has already started to take their first steps toward a future beyond being a Chosen Child. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Black Lagoon: The Second Barrage', 'TV', 12, 'Completed', '2006-10-03', '2006-12-19', '8', 'Rokurou "Rock" Okajima has joined the Lagoon Company, a pirate mercenary group which operates out of Roanapur, Thailand. Despite his initial protests, this filthy slum of depraved souls and merciless criminals now serves as the former salaryman''s home. Stranded, with nothing left of his past life but the clothes on his back and his inner morality, Rock is forced to perform jobs alongside the other members of the Lagoon crew. Berated for his lack of spine as he wades through the underbelly of society, he must decide whether to continue on amidst the gunfire and ruthlessness or risk everything he has in an attempt to be free. Whether he chooses the comfort of a familiar land or the freedom of being an outlaw, his decision will have lasting consequences on the crew who gave him a home.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuukoku no Moriarty', 'TV', 11, 'Completed', '2020-10-11', '2020-12-20', '8', 'During the late 19th century, Great Britain has become the greatest empire the world has ever known. Hidden within its success, the nation''s rigid economic hierarchy dictates the value of one''s life solely on status and wealth. To no surprise, the system favors the aristocracy at the top and renders it impossible for the working class to ascend the ranks.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shinigami Bocchan to Kuro Maid', 'TV', 12, 'Completed', '2021-07-04', '2021-09-19', '8', 'As the elegant, frail flower petals wither away into lifeless ashes, the young duke is tragically reminded of the despicable power forced upon him—the ability to kill anything he touches. Scorned by his family, he is sent away to live in near isolation. Fortunately, he is not entirely alone, as the manor''s staff—his dutiful butler Rob and the flirtatious maid Alice—keep him company and make his life less miserable.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Black Jack (TV)', 'TV', 61, 'Completed', '2004-10-11', '2006-03-06', '8', 'Black Jack is an "unregistered" doctor with a clouded, mysterious past. He works with his little assistant Pinoko (who has a massive crush on the doctor), dealing with medical cases not very well known, which can be strange, dangerous, or not known at all. But he is a genius, and can save almost any of his patients'' life (as long as they have the money for it, that is), and is known to many around the world, especially to those of medicine and science. He''s a man of science himself, and does not believe much until he has seen it, yet it is many times he is surprised by love and nature often overpowering the science he bases his life in.  
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Ball Z Special 1: Tatta Hitori no Saishuu Kessen', 'Special', 1, 'Completed', '1990-10-17', NULL, '8', 'Bardock, Son Goku''s father, is a low-ranking Saiyan soldier who was given the power to see into the future by the last remaining alien on a planet he just destroyed. He witnesses the destruction of his race and must now do his best to stop Frieza''s impending massacre.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boku no Hero Academia the Movie 3: World Heroes'' Mission', 'Movie', 1, 'Completed', '2021-08-06', NULL, '8', 'Under the doctrines of Quirk Doomsday Theory, the ideological group Humarise is convinced that all humans with quirks are diseased and must be eradicated. In order to rebuild the world, the group''s extremists have constructed a lethal device known as a "Trigger Bomb" that causes people with quirks to lose control and die. Their leader, Flect Turn, evades capture from the Pro Heroes deployed around the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yume-iro Pâtissière SP Professional', 'TV', 13, 'Completed', '2010-10-03', '2010-12-26', '8', 'Upon her return to Japan after a two year study break in Paris, Ichigo Amano is met with news of Team Ichigo''s separation, as each of the Sweets Princes takes a different path toward their dream. Now in her first year of high school, Henri Lucas has a project in store for her, enlisting the help of Ichigo, Makoto Kashino, and new members Lemon Yamagishi and Johnny McBeal to give rise to a new Team Ichigo. As the four work together on this project, Ichigo and Makoto continue to grow closer, though Johnny and the unrelenting Miya Koshiro will not idly sit by; with Johnny''s eye on Ichigo and Miya still after Makoto, it definitely seems like love won''t come easily.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaguya-sama wa Kokurasetai? Tensai-tachi no Renai Zunousen OVA', 'OVA', 1, 'Completed', '2021-05-19', NULL, '8', 'What do Shuchiin Academy''s model students do outside of their student council duties? After a visit to the swimming pool, Kaguya Shinomiya and Chika Fujiwara take to the showers to wash themselves off. When Chika accidentally drops a bar of soap, the two find themselves in a rather slippery mishap. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahoujin Guruguru', 'TV', 45, 'Completed', '1994-10-13', '1995-09-14', '8', 'There is a small village called Jimuna on the continent of Jamu Jamu. This village is home to a girl named Kukuri. She is the last descendant of the Migu Migu Tribe. She is raised by an old witch who teaches her the secret magic of the tribe, but Kukuri is not a good student.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yong Sheng: Qizhuang Shanhe', 'ONA', 16, 'Completed', '2024-04-19', '2024-07-19', '8', 'How can the hero Fang Han use his own strength to traverse the vast fantastical world? By clinging to an unwavering refusal to accept defeat, he cracked the code of supernatural abilities and transformed his mortal body into an immortal one. Fang Han will reveal a new and prosperous world filled with immortals, demons, and mortals, along with countless innovative magic weapons. In addition, Fang Han will encounter conflicts between immortals and demons, love and hate. It will eventually lead to success.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ojamajo Carnival!!', 'ONA', 1, 'Completed', '2024-03-23', NULL, '8', 'Ojamajo Carnival!! commemorates the 25th anniversary of Ojamajo Doremi.', 1030, 'https://cdn.myanimelist.net/images/anime/1093/142299.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yong Sheng: Shi Nian Zhi Yue', 'ONA', 12, 'Completed', '2023-07-08', '2023-09-16', '8', 'In the majestic fantasy world, how does the protagonist Fang Han traverse the world with his own strength. Relying on an unyielding stubbornness to break through the mysteries of supernatural powers, and forge the physical body into an immortal body. There are endless novel magic weapons, and the brand-new prosperity of the Three Realms of Immortals, Demons and Fans will be opened by the protagonist in turn. It will take you to experience the fantasy demeanor of the immortal sect, demons, gods, kings and emperors. The protagonist will also experience the love and hatred in the world, the entanglement of grievances and resentments, and the disputes between immortals and demons. Finally lead you on the road to the top king.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yozakura-san Chi no Daisakusen', 'TV', 27, 'Completed', '2024-04-07', '2024-10-06', '8', 'After losing his entire family in a car crash, Taiyou Asano tries to pull away from his childhood friend, Mutsumi Yozakura, but she assures him she is not going anywhere. Nevertheless, Taiyou becomes socially awkward, struggling to make friends at school despite the efforts of his persistent classmates.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saijaku Tamer wa Gomi Hiroi no Tabi wo Hajimemashita.', 'TV', 12, 'Completed', '2024-01-12', '2024-03-29', '8', 'Born into a loving family, Femicia appears to have a bright future ahead of her. When she finally turns five, the time comes to go to the church to have her skills appraised. However, while she does receive a monster tamer skill, it turns out that Femicia has zero stars for that ability. To make matters worse, society considers those who have zero stars to be harbingers of misfortune; as a result, Femicia is shunned by everyone—including her family.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gokushufudou Season 2', 'ONA', 5, 'Completed', '2023-01-01', NULL, '8', 'With a wicked scar on his face, a terrifying gaze, and an apron adorned with a teddy bear, ex-yakuza member Tatsu proudly assumes the role of a full-time househusband. Already familiar with the regular challenges of grocery shopping, Tatsu now takes it to the next level by joining a women''s organization—but acceptance is not easily achieved without first mastering the elegance of flower arranging and housekeeping.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hakumei to Mikochi: Neji to Bed to Irori to Bakuchi', 'Special', 1, 'Completed', '2018-06-27', NULL, '8', 'Special episode included in the second Blu-ray/DVD volume.', 510, 'https://cdn.myanimelist.net/images/anime/5/90014.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuru Camp△ Specials', 'Special', 3, 'Completed', '2018-03-28', '2018-07-25', '8', 'When Chiaki Oogaki and Aoi Inuyama start the Outdoor Activities Club at their school, it is only the two of them and an array of ambitious plans. Things do not change much even after a new member—Nadeshiko Kagamihara—joins. And yet, the cheerful, cozy atmosphere seems to bring many curious visitors to their small headquarters. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Strike Witches Movie', 'Movie', 1, 'Completed', '2012-03-17', NULL, '8', 'After fending off the threat of a Neuroi invasion of Romagna and destroying the enemy''s nest over Venezia, Yoshika Miyafuji goes back to her home town in the Empire of Fusou. Despite the loss of her magical and healing abilities, the former officer of the 501st Joint Fighter Wing wants to continue studying medicine. This is in order to help those in need, both civilians and those on the front lines alike. She receives an invitation from a prestigious school in Europe and decides to accept the offer, embarking on a journey back to the war-torn continent.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koutetsujou no Kabaneri Movie 2: Moeru Inochi', 'Movie', 1, 'Completed', '2017-01-07', NULL, '8', 'Compilation film of the second half of the TV series.', 1105, 'https://cdn.myanimelist.net/images/anime/1771/109284.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sword Art Online: Alicization', 'TV', 24, 'Completed', '2018-10-07', '2019-03-31', '8', 'The Soul Translator is a state-of-the-art full-dive interface which interacts with the user''s Fluctlight—the technological equivalent of a human soul—and fundamentally differs from the orthodox method of sending signals to the brain. The private institute Rath aims to perfect their creation by enlisting the aid of Sword Art Online survivor Kazuto Kirigaya. He works there as a part-time employee to test the system''s capabilities in the Underworld: the fantastical realm generated by the Soul Translator. As per the confidentiality contract, any memories created by the machine in the virtual world are wiped upon returning to the real world. Kazuto can only vaguely recall a single name, Alice, which provokes a sense of unease when mentioned in reality.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tada-kun wa Koi wo Shinai', 'TV', 13, 'Completed', '2018-04-05', '2018-06-28', '8', 'Love has never really been a concern for Mitsuyoshi Tada, and as the aspiring photographer enters his second year of high school, it truthfully could not be further from his mind. However, things just might change after he meets a bright and bubbly foreigner named Teresa Wagner while he was taking pictures of a cherry blossom tree. Nevertheless, after she asks him to photograph her, the two soon separate, only to meet each other again twice more that same day. Finding Teresa just as she is caught in a sudden downpour, Tada invites her to his family''s coffee shop to dry off. There, she explains that she was separated from her traveling companion, a no-nonsense redhead named Alexandra "Alec" Magritte. When Alec reunites with Teresa shortly after, they say their goodbyes, expecting to part ways for good—but the two unexpectedly show up as transfer students in his class the next day.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Macross Δ Movie 2: Zettai Live!!!', 'Movie', 1, 'Completed', '2021-10-08', NULL, '8', 'Walküre and Delta Flight used music to save people from the Vár Syndrome, a previously unknown disease that made humans and others go berserk. However, they find themselves facing a new threat…
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fukigen na Mononokean Tsuzuki', 'TV', 13, 'Completed', '2019-01-05', '2019-03-30', '8', 'Despite being burdened with crippling debt to the morose Haruitsuki Abeno, Hanae Ashiya has come to enjoy his job as an exorcist. His ability to communicate with youkai has given him a sense of responsibility regarding the magical creatures, and he continues to work hard to send them to their true home in the Underworld.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Full Metal Panic! Invisible Victory', 'TV', 12, 'Completed', '2018-04-13', '2018-07-18', '8', 'The boisterous student Kaname Chidori and soldier Sousuke Sagara are enjoying a blissful high school life. However, their peaceful days are disrupted by the threatening terrorist organization Amalgam. Leonard Testarossa, a member of the organization who possesses "Whispered," seeks to procure Kaname and her knowledge. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('BanG Dream! 2nd Season', 'TV', 13, 'Completed', '2019-01-03', '2019-03-28', '8', 'Kasumi Toyama and the members of Poppin''Party—their high school band—are now second-year students, but with the new school year comes their latest set of challenges: student council duties, cram school, and part-time jobs, among other things. Furthermore, they are now separated into different classes, and as a result, their free time together is shortened. Looking back, their joyful times together seem like nothing more than an unachievable fantasy when their members are too occupied to even gather in Arisa Ichigaya''s basement for practice sessions. As the band ponders over the situation, an unfamiliar girl suddenly emerges, unknowingly pulling them into the spotlight once more.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Momo e no Tegami', 'Movie', 1, 'Completed', '2012-04-21', NULL, '8', 'After the unexpected death of her father, 11-year-old Momo Miyaura leaves Tokyo with her mother and moves to an old remote island in Seto Inland Sea. The only memento she has from her father is an unfinished letter with only two words inside: "Dear Momo"—along with her heart''s unrest from it.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hana yori Dango', 'TV', 51, 'Completed', '1996-09-08', '1997-08-31', '8', 'Makino Tsukushi, a girl who comes from a poor family, just wants to get through her two last years at Eitoku Gakuen quietly. But once she makes herself known by standing up for her friend to the F4, the four most popular, powerful, and rich boys at the school, she gets the red card: F4''s way of a "Declaration of War." But when she doesn''t let herself be beaten by them and is starting to fall for one of the F4, Hanazawa Rui, she starts to see that there is more than meets the eye...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Higepiyo', 'TV', 39, 'Completed', '2009-04-03', '2010-02-19', '7', 'Higepiyo is a little chick with a mustache, who is seeking to aquire masculinity with his friend Hiroshi but ends up being entangled with a skin of heated milk.', 480, 'https://cdn.myanimelist.net/images/anime/5/23125.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Druaga no Tou: The Aegis of Uruk - Jil no Bouken', 'Special', 1, 'Completed', '2008-04-04', NULL, '7', 'This is a special "back-side" (ura) episode aired on GyaO simultaneously with original broadcast which features the background story from party''s side instead of Jil''s. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toaru Majutsu no Index-tan Movie: Endymion no Kiseki - Ga Attari Nakattari', 'Special', 1, 'Completed', '2013-08-28', NULL, '7', 'Bonus animation featuring Index-tan included with the BD special edition of the Toaru Majutsu no Index: Endymion no Kiseki movie.', 436, 'https://cdn.myanimelist.net/images/anime/9/53541.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gunnm', 'OVA', 2, 'Completed', '1993-06-21', '1993-08-21', '7', 'Doc Ido, a doctor and mechanic who lives and works in the hellish, postapocalyptic "Scrapyard," finds the—miraculously preserved—remains of a female cyborg in a junk heap. After he revives and rebuilds her, the preternaturally strong, amnesiac "Gally" begins to forge a life for herself in a world where every day can bring a fight for life.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seisenshi Dunbine', 'TV', 49, 'Completed', '1983-02-05', '1984-01-21', '7', 'Shou Zama is an ordinary 18-year-old from Tokyo who finds himself summoned to the medieval fantasy world of Byston Well. Upon arrival, he is put into service under the ambitious lord Drake Luft, who seeks to greatly expand his power. Those like Shou who come from "Upper Earth" possess strong aura power and are ordered to pilot "Aura Battlers," insectoid mecha designed by a man named Shot Weapon, who also came from Upper Earth.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Riding Bean', 'OVA', 1, 'Completed', '1989-02-22', NULL, '7', 'Bean Bandit and his partner Rally Vincent are couriers for hire - transporting clients and delivering goods in his custom sports car "Roadbuster" for a hefty price. But when they are hired to escort a kidnapped girl named Chelsea to her home, they don''t realize they''re being framed for kidnapping as their former clients Semmerling and Carrie plan their escape with Chelsea''s father and the ransom money. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hakuouki OVA (2021)', 'OVA', 3, 'Completed', '2021-11-13', '2022-01-29', '7', 'New Hakuoki OVA.', 879, 'https://cdn.myanimelist.net/images/anime/1763/117761.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shadow Skill: Eigi', 'TV', 26, 'Completed', '1998-07-03', '1998-12-25', '7', 'In the land of Kuruda, warriors with magical powers and incredible fighting skills battle for the ultimate prize: the title of Sevaar, the strongest warrior in the land. Elle Ragu, nicknamed Shadow Skill, is the newest Sevaar to emerge, but that doesn''t make her life any easier. Teaching her "little brother," Gau, how to be a warrior, fending off assassins from other kingdoms and thwarting enemy invasions is hard enough, but her biggest challenge will be paying off her drinking debts. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Azumanga Daiou: Gekijou Tanpen', 'Special', 1, 'Completed', '2001-12-25', NULL, '7', 'In this short movie featuring familiar characters from Azumanga Daioh, Osaka is yet again having a strange dream of Chiyo-Chan''s pigtails being posessed. As Chiyo-Chan''s pigtails bounce out of the window, who knows if young Chiyo will ever be happy again.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahoromatic Summer Special', 'Special', 1, 'Completed', '2003-08-15', NULL, '7', 'It''s another normal day in the Misato residence when Mahoro finds yet another pornographic magazine in Suguru''s room. This prompts her and Minawa to make a pact with Chizuko, Rin, Miyuki and Miss Shikijo to search and confiscate all of the perverted stash in the house. Suguru, Kiyomi and Toshiya must do whatever it takes to protect their treasure from the girls. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tetsuwan Birdy', 'OVA', 4, 'Completed', '1996-07-25', '1997-02-25', '7', 'Tsutomu, an average middle school kid busy studying for the final exams to enter high school runs into a man running from someone and gets caught up in the chase. In all the confusion he gets accidentally killed. Luckily Birdy (an interplanetary agent) knows a way to save him, unfortunately that means joining bodies to become one. So now he is stuck with this officer and along for the ride capturing criminals and saving lives.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Digimon X-Evolution', 'Movie', 1, 'Completed', '2005-01-03', NULL, '7', 'A virtual world was created by the present-day network called the "Digital World." The "Digital Monster," which is a digital life object, was born, and the host computer Yggdrasil managed the different Digital World areas. However, it developed the X Program of fear to eliminate all Digimon in the old world and develop a new Digital World for only certain Digimon... Now, the greatest crisis ever approaches the Digital World.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bishounen Tanteidan', 'TV', 12, 'Completed', '2021-04-11', '2021-06-27', '7', 'Mayumi Doujima promises her parents that she will give up on her dreams of becoming an astronaut on her 14th birthday if she cannot find a star she once saw long ago.  Overhearing her troubles, the eccentric Manabu Soutouin offers to help her search for the star alongside the rest of Yubiwa Academy''s mysterious Pretty Boy Detective Club, whose rules are as follows: "Be pretty, be a boy, and be a detective!"
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dirty Pair: Lovely Angels yori Ai wo Komete', 'OVA', 2, 'Completed', '1987-01-01', NULL, '7', 'Released direct to video in Japan after the original TV series was canceled, this OVA is actually the final two episodes of the TV series.', 974, 'https://cdn.myanimelist.net/images/anime/7/29694.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyougoku Natsuhiko: Kousetsu Hyaku Monogatari', 'TV', 13, 'Completed', '2003-10-04', '2003-12-27', '7', 'In an attempt to turn his floundering career around by compiling one hundred ghost stories, struggling author Momosuke Yamaoka roams through Edo-period Japan searching for material. During his travels, the young man wanders deep into the mountains, where he encounters a monk named Mataichi. Failing to heed the monk''s advice to turn back, Momosuke presses forward and soon witnesses a murder carried out by Mataichi and his two associates. As it turns out, Mataichi''s gang also investigates paranormal incidents—aiming to make those in the wrong pay the ultimate price.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hanyou no Yashahime: Sengoku Otogizoushi - Ni no Shou', 'TV', 24, 'Completed', '2021-10-02', '2022-03-26', '7', 'Second season of Hanyou no Yashahime: Sengoku Otogizoushi.', 974, 'https://cdn.myanimelist.net/images/anime/1415/118635.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zero kara Hajimeru Mahou no Sho', 'TV', 12, 'Completed', '2017-04-10', '2017-06-26', '7', 'In a world of constant war between humans and witches, there exist the "beastfallen"—cursed humans born with the appearance and strength of an animal. Their physical prowess and bestial nature cause them to be feared and shunned by both humans and witches. As a result, many beastfallen become sellswords, making their living through hunting witches.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seirei Gensouki', 'TV', 12, 'Completed', '2021-07-06', '2021-09-21', '7', 'When 20-year-old college student Haruto Amakawa dies in a traffic accident, he does not expect to wake up in an unfamiliar world in the body of a young boy named Rio. As their memories and personas fuse, Rio realizes that he now also possesses magical powers. He is relieved to find that his burning passion for revenge against his mother''s murderers has not subsided, despite his newly changed identity.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sora wo Miageru Shoujo no Hitomi ni Utsuru Sekai', 'TV', 9, 'Completed', '2009-01-14', '2009-03-11', '7', 'To save both the Magical Kingdom and the Heavens and restore the flow of akuto, the flow of energy of everything, the Magical King Munto must follow a vision and find the girl Yumemi in the normal world. Yumemi herself is just a normal girl except that she is the only one who can see the islands of the Heavens floating above. When Munto appears before her she starts thinking about hers and others responsibility to the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wan Jie Du Zun 3rd Season', 'ONA', 224, 'Airing', '2024-11-30', NULL, '7', '', 752, 'https://cdn.myanimelist.net/images/anime/1472/146749.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam: The Origin - Movie Edition', 'Movie', 3, 'Completed', '2024-09-13', '2024-10-11', '7', 'In the year 0068 of the Universal Century, Casval Rem Deikun''s life is thrown into chaotic disarray after the assassination of his father, a prolific figure in the crusade towards civil rights for people who live away from the Earth''s surface. Casval and his sister Artesia receive aid from soldiers who were loyal to their father, and the siblings are whisked away from their home, separated, and thrown into a twisted fate that sees them come into their own as soldiers and adults.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kakuriyo no Yadomeshi Ni', 'TV', 12, 'Airing', '2025-10-02', '2025-12-18', '7', 'Second season of Kakuriyo no Yadomeshi.', 341, 'https://cdn.myanimelist.net/images/anime/1619/151364.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nakanohito Genome [Jikkyouchuu]: Knots of Memories', 'OVA', 1, 'Completed', '2020-02-27', NULL, '7', 'An original story included with volume 10 of the Nakanohito Genome [Jikkyouchuu] manga.', 761, 'https://cdn.myanimelist.net/images/anime/1118/103618.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Touken Ranbu: Hanamaru', 'TV', 12, 'Completed', '2016-10-03', '2016-12-19', '7', 'In the year 2205, a special sage known as Saniwa has the ability to breathe life into inanimate objects. At the same time, dark forces have initiated a plot to travel back in time and change the course of history—and the only ones capable of stopping them are the Saniwa and their strongest animations: historical Japanese swords, in the form of handsome young men.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hypnosis Mic: Division Rap Battle - Rhyme Anima', 'TV', 13, 'Completed', '2020-10-03', '2020-12-26', '7', 'In a world overtaken by war and conflict, "Hypnosis Microphones"—devices through which a user channels lyrics that can affect the listener''s brain and even cause physical damage—were introduced to the masses by the Party of Words. Revolutionizing warfare, Hypnosis Mics have transformed words and music into the sole weapons used by gangsters, terrorists, and the military, with physical weapons having been banned from use.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Heroman', 'TV', 26, 'Completed', '2010-04-01', '2010-09-23', '7', 'In California''s Center City, shy but kindhearted Joseph Carter "Joey" Jones lives with his grandmother, working in a coffee shop. Though his family is financially burdened and he is bullied at school, he remains cheerful. A robotics enthusiast, he wants a top-of-the-line toy robot called a Heybo more than anything.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chihayafuru 3: Ima Hitotabi no', 'Special', 1, 'Completed', '2020-01-29', NULL, '7', 'Recap of first fifteen episodes of Chihayafuru 3.', 538, 'https://cdn.myanimelist.net/images/anime/1014/105666.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Qin Shi Mingyue: Junlin Tianxia', 'ONA', 75, 'Completed', '2014-12-25', '2017-11-30', '7', 'Season Five continues the struggle of the Mohists and their allies against the Qin Empire in Sanghai and Crown Prince Fushu has a prominent role. A new character from the Taoist school Leader Xiaomeng appears on the side of the Qin. The Peasant School takes on a major role as leaders of the six Halls struggle for supremacy and to be the Xia Kui successor. The young and powerful General Zhang Han and the Shadow Division also make an entrance. Wei Zhuang and the Quicksand Group form and uneasy alliance with the Mohists and try to enlist the aid of the warring Peasant School. Tianming, Shaoyu and Shi Lan continue their search for Yue-er on the floating city, Mirage. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Juushin Enbu: Hero Tales', 'TV', 26, 'Completed', '2007-10-08', '2008-03-31', '7', 'For citizens of the Ken Empire, justice is a myth. Lord Keiro, the deranged Shogun of the Imperial Army, blazes a trail of terror across the countryside in search of the sacred sword that will make him a god. Standing in his way is Taito, an omnipotent star reborn in human form—a young hero who vows to use his celestial strength to avenge those slaughtered by the villainous Shogun.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cyborg 009 (TV)', 'TV', 26, 'Completed', '1968-04-05', '1968-09-27', '7', 'They fight against evil, they help those in need, they''re the Cyborg fighters! Together with the scientist Dr. Gilmore, this team of nine cyborgs use their special body modifications to fight against a seemingly endless barrage of enemies, including robotic crabs, aliens, and fellow cyborgs.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maison Ikkoku: Bangai-hen - Ikkokujima Nanpa Shimatsuki', 'OVA', 1, 'Completed', '1991-05-21', NULL, '7', 'Yotsuya and Ichinose are enjoying a hot afternoon when they recall the time that the tenants of Ikkoku-kan and Mitaka go off on a cruise to party hard aboard Mitaka''s new boat; however, the boat falls apart, and everyone is shipwrecked on a deserted island. With everyone up to their usual antics and shenanigans, what can happen in such a desolate place?', 540, 'https://cdn.myanimelist.net/images/anime/3/4678.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zombie-Loan', 'TV', 11, 'Completed', '2007-07-04', '2007-09-12', '7', 'Do you know when you are going to die? Michiru Kita does, as she has the ability to see a "ring of death" on the necks of those around her—and the darker the ring, the closer one is to death. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Senkou no Night Raid', 'TV', 13, 'Completed', '2010-04-06', '2010-06-29', '7', 'The year is 1931. The city is Shanghai. Ten years before America will enter World War II, the hydra''s teeth planted by the first great global conflict are beginning to germinate. Hatching like spiders, they weave the complex web of plots and conspiracies destined to inevitably draw entire nations to the brink of destruction. Caught in the heart of these webs, desperately seeking to separate lies from truth, is "Sakurai Kikan," an ultra-secret intelligence agency staffed by extraordinarily talented individuals with abilities far beyond those of normal humans. Their duty: to stop the darkest plots and eliminate the greatest threats. But in a city built on intrigue, can even a team of clairvoyants, telepaths and espers stand against the ultimate forces of destiny?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tensei shitara Slime Datta Ken: Kanwa - Hinata Sakaguchi', 'Special', 1, 'Completed', '2021-01-05', NULL, '7', 'A summary of season one of Tensei shitara Slime Datta Ken with some extra content leading into season two.', 12, 'https://cdn.myanimelist.net/images/anime/1670/111154.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kantai Collection: KanColle', 'TV', 12, 'Completed', '2015-01-08', '2015-03-26', '7', 'With the seas under constant threat from the hostile "Abyssal Fleet," a specialized naval base is established to counter them. Rather than standard naval weaponry, however, the base is armed with "Kanmusu"—girls who harbor the spirits of Japanese warships—possessing the ability to don weaponized gear that allows them to harness the powerful souls within themselves. Fubuki, a young Destroyer-type Kanmusu, joins the base as a new recruit; unfortunately for her, despite her inexperience and timid nature, she is assigned to the famous Third Torpedo Squadron and quickly thrust into the heat of battle. When she is rescued from near annihilation, the rookie warship resolves to become as strong as the one who saved her.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sakura Taisen: Gouka Kenran', 'OVA', 6, 'Completed', '1999-12-18', '2000-12-21', '7', 'The end of the demon wars has ended and now the Flower Division has been able to rest up after their fighting. The second Sakura Wars developes studies on every Flower Division Combatee in every episode while they go on their miscellanious adventures around Japan.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Midori no Makibao', 'TV', 61, 'Completed', '1996-03-09', '1997-07-12', '7', 'Midori Makibao is a small white racehorse. Compared to other thoroughbred horses, he looks more like a donkey with wide nostrils; however, with his guts and speed as his weapon, Makibao wins in every big race.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dual! Parallel Runrun Monogatari Special', 'Special', 1, 'Completed', '1999-12-22', NULL, '7', 'Peace has been brought to both earths, and everyone is living out their lives as normal citizens. But how normal could life be for war hero Kazuki living with five beautiful women under the same roof... Apparently, he doesn''t need to wait long to find out. An ancient artifact that is the key to their adventures in the parallel universes forces Kazuki to hop in the saddle yet again, but this time it''s outer space or bust. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kami-tachi ni Hirowareta Otoko 2nd Season', 'TV', 12, 'Completed', '2023-01-09', '2023-03-27', '7', 'Since reincarnating into a new world, Ryouma Takebayashi has used his god-given graces to tame countless slimes and employ them to improve the lives of everyone around him. With the astonishing success of his laundry shop, Bamboo Forest, he is finally ready to take on new frontiers and open a branch in the neighboring city of Lenaf. Abiding by his promise with his dearest friend, Eliaria Jamil, Ryouma makes every day count, whether learning new techniques, forming connections, or even discovering more species of slime.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ojamajo Doremi OVA', 'OVA', 3, 'Completed', '2001-01-01', '2002-01-01', '7', 'Traffic Safety: Onpu teaches traffic safety.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Captain Tsubasa: Saikyou no Teki! Holland Youth', 'OVA', 1, 'Completed', '1995-12-16', NULL, '7', 'The last Captain Tsubasa movie is about the match between Japan and Holland. After the Japanese team lost two games against this apparently supreme opponent, their confidence is at its lowest point and even Hyuga, having a hurt leg, is desperate. Thus the management tries everything to convince Wakabayashi (living in Germany) and Tsubasa (living in Brazil) to come to Holland and to help them, but both deny. Only in the second half of the third game Tsubasa appears and joins the team, giving them back their confidence and strength. With Tsubasa Ozora as their captain again, the last game ends 11:1 for Japan.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Ball Movie 3: Makafushigi Daibouken', 'Movie', 1, 'Completed', '1988-07-09', NULL, '7', 'Emperor Chiaotzu''s wife has gone missing, and he is told by Master Shen that if he collects the seven dragon balls he can call upon the eternal dragon and wish for her return. Meanwhile, Goku and Krillin attend the World Martial Arts Tournament, which is hosted by the Emperor; Bora and his son Upa attempt to hide the dragon ball they found from the emperor''s forces, which are under the control of the evil Shen and General Tao; and Bulma conducts her own search for the dragon balls with the help of Yamcha, Puar, and Oolong.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Omamori Himari', 'TV', 12, 'Completed', '2010-01-07', '2010-03-25', '7', 'After the death of his parents, Yuuto Amakawa lives a pretty ordinary life in the city. The only problem he has to worry about while attending school alongside Rinko, his next-door neighbor, is his cat allergies. That all changes on his sixteenth birthday, when an Ayakashi—a supernatural creature—attacks him for the sins of his ancestors. Luckily, he is saved by Himari, a mysterious cat-woman with a sword, who explains that Yuuto is the scion of a family of demon-slayers, and she is there to protect him now that the charm that kept him hidden from the supernatural forces of the world has lost its power.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eoneu Nal Jameseo Kkaeeoboni Bagelyeoga Doeeo Isseotda', 'ONA', 15, 'Completed', '2019-11-25', '2019-12-02', '6', 'Bong Gi used to have dreams of making something of his life. But now all that seems like a distant memory. He has become fat, lazy, unemployed, and altogether unlovable. In the real world, people are grossed out by him. He has never had a girlfriend and he spends his late nights fantasizing about women whose pictures he leers at on the internet. His own life appalls him, but he has one escape – his online life. Gaming has become his everything, and he excels at it.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsuru ni Notte: Tomoko no Bouken', 'Movie', 1, 'Completed', '1993-07-17', NULL, '6', 'A young girl named Tomoko visits the Hiroshima Peace Memorial. There she has a mysterious meeting with Sadako, the little girl who was 2 years old when the U.S. dropped the bomb on her city during WWII and 11 when she died from the effects of radiation poisoning. Sadako takes Tomoko on an eye-opening journey.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Live On Cardliver Kakeru', 'TV', 51, 'Completed', '2008-10-05', '2009-09-27', '6', 'Kakeru is a big fan of the Live On card game, like so many kids his age. However he loses every time he plays, no matter how hard he tries. Things change when one day Kakeru saves a small dog-like creature chased by weird people. The “dog” is in fact a Create Monster and gives Kakeru an unusual Live Change card, which in turn allows Kakeru to protect his newfound friend… And gets him involved in something he did not expect…
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fuuma no Kojirou: Fuuma Hanran-hen', 'OVA', 1, 'Completed', '1992-11-21', NULL, '6', 'Hakuo Gakuin used to be a prestigious high school, and famous for martial arts. However, because its rival school; Seishikan, has been cowardly luring it''s superior students, Hakuo was going to decline.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shukufuku no Campanella', 'TV', 12, 'Completed', '2010-07-03', '2010-09-18', '6', 'The story takes place in a trading city Ert''Aria. Leicester Maycraft is an item engineer belonging to an adventurer guild "Oasis." One night, he is at a party with his friends to see a meteor stream on the rooftop of a chapel. One meteor grazes them and hits the steeple of the chapel. There he finds a secret room and a sleeping girl. The girl wakes up and says "You must be my father!" The encounter with the mysterious girl brings an unexpected adventure to Leicester.', 25, 'https://cdn.myanimelist.net/images/anime/3/75556.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Magnerobo Ga-Keen', 'TV', 39, 'Completed', '1976-09-05', '1977-06-26', '6', 'Dr. Kazuki, who perceived of an invasion of Earth by the Izaru people builds a robot based on the science of magnetism and sphere joint theory. Undergoing a dangerous augmentation process, Dr. Kazuki''s daughter Mai becomes the pilot of "Mighty" or "Magnetman Minus". Takeshi Houjou becomes the pilot of "Puraiza" or "Magnetman Plus". 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rinne no Lagrange Season 2 Specials', 'Special', 6, 'Completed', '2012-09-21', '2013-02-22', '6', 'Rinne no Lagrange short specials included in the Rinne no Lagrange Season 2 Blu-rays and DVDs.', 1117, 'https://cdn.myanimelist.net/images/anime/6/60967.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sougen no Shoujo Laura', 'TV', 26, 'Completed', '1975-10-07', '1976-03-30', '6', 'This anime is based on the same work as the famous American live-action TV series Little House on the Prairie.', 607, 'https://cdn.myanimelist.net/images/anime/5/44648.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Machine Robo: Cronos no Dai Gyakushuu', 'TV', 47, 'Completed', '1986-07-03', '1987-05-28', '6', 'The journey of a robot prince begins! The planet Cronos is a world of super-robotic lifeforms, ruled by the wise Master Kirai. But their peaceful existence is shattered by the conquering armies of the Gandora robots. Now, machine combats machine in an epic battle for the planet. Master Kurai''s son, Rom, must lead a company of transformable mecha warriors into the fray!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Catch! Tiniping', 'TV', 52, 'Completed', '2020-03-19', '2021-04-01', '6', 'Catch! Teenieping revolves around mischievous creatures called Teenieping that like to enter people''s minds, but their playful nature and magical powers can wreak havoc in their hosts'' lives. When the Teenieping are set loose on Earth, Princess Romi of the Emotion Kingdom becomes an ordinary girl that has to turn into a magical girl to stop them, all while balancing her new civilian life as a worker for the Bakery Heartrose with her coworkers Ian, Kyle, and Jun.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jungle wa Itsumo Hare nochi Guu: Eizou Tokuten - Maboroshi no Pilot Film', 'Special', 1, 'Completed', '2002-12-21', NULL, '6', '4-minute promo/pilot released with the Deluxe OVA, with a few events from the TV series in a different graphic style.', 802, 'https://cdn.myanimelist.net/images/anime/10/47343.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuruneko: Kurunekobin', 'Special', 4, 'Completed', '2009-12-18', '2010-09-03', '6', 'Specials included on the DVDs.', 211, 'https://cdn.myanimelist.net/images/anime/4/47301.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('009-1: R&B', 'Special', 1, 'Completed', '2007-04-25', NULL, '6', 'Mylene Hoffman, also known by the code name "009-1," is a beautiful cyborg spy. Instructed by her superior "Number Zero," she is assigned to eliminate a Jazz musician who is suspected to be a double agent. However, as she gets closer to the musician, she begins to slowly loses suspicions. Can she complete the mission before she falls in love?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kishin Heidan', 'OVA', 7, 'Completed', '1993-03-25', '1994-08-25', '6', 'October 1941, as the second World War threatens to destroy the civilized world, an unforeseen complication suddenly occurs. An alien invasion! Despite the sudden appearance of these extraterrestrial aggressors, the Axis and Allies continue their destructive conflict. Only the Kishin Corps and their giant Geo-Armor Robots (a.k.a.: Kishin), developed from a captured alien robot soldier, stand between the Earth and total annihilation!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Usavich V', 'TV', 13, 'Completed', '2012-12-05', '2013-07-12', '6', 'The fifth season of Usavich.', 463, 'https://cdn.myanimelist.net/images/anime/10/54017.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Calimero', 'TV', 45, 'Completed', '1974-10-15', '1975-09-30', '6', 'Calimero is a small black bird who has a shell on his head; his dream is to fly like the other birds. When he tries to fly and screws up he is teased by the other birds, but his girlfriend Pricilla is there to cheer him up. Despite his appearance, he is quite smart and thinks up an idea to fly.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tenamonya Voyagers', 'OVA', 4, 'Completed', '1999-06-25', '1999-12-18', '6', 'Paraila was an agent for a war organization in the space, but suddenly the supreme court of planets accused her of betrayal and she was forced to be a fugitive to escape from jail. Now she forms a team with a clueless school teacher, a bazooka lover girl and Paraila''s former sidekick. They will battle against Paraila''s enemies, and try to go to earth to escape from space justice. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Popotan', 'TV', 12, 'Completed', '2003-07-18', '2003-10-03', '6', 'Beautiful sisters Ai, Mai, Mii, their android maid Mea and slippery pet ferret Unagi make an amazing journey together through time and space without ever leaving their beloved mansion behind! Following the clues of the strange dandelion-like "Popotan," the girls are theoretically seeking the person who has the answers to their most personal questions, but they seem to have more than enough time to take side trips, meet new friends, visit hot springs and occasionally operate the X-mas shop they keep in the house along the way!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('RahXephon: Kansoukyoku/Kanojo to Kanojo Jishin to - Thatness and Thereness', 'OVA', 1, 'Completed', '2003-08-07', NULL, '6', 'Quon Kisaragi was surprised when she saw an illusion of herself floating in midair. This other "self" of her claimed that she is a fragment of Quon. Thus an existentialistic dialogue began between the two.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koutetsu Tenshi Kurumi 2', 'TV', 12, 'Completed', '2001-04-12', '2001-06-28', '6', 'Taking place 75 years after the first series, Steel Angel Kurumi 2 brings the Steel Angels in a new mis-adventure. High school student and aspiring cellist Nako Kagura accidentally discovers and kisses Kurumi Mk. II at her home, thus making her Kurumi''s master. But things go awry as Nako''s best friend Uruka gets jealous and tries anything - including her father''s army of top-secret mecha - to destroy Kurumi and win back Nako. Things get more out of control when Saki Mk. II is awakened by Uruka, and Karinka Mk. II joins in to steal Nako away from Kurumi. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsuki ga Noboru made ni', 'OVA', 1, 'Completed', '1991-11-08', NULL, '6', 'A father and daughter are on a trip to see a beautiful view of the moon when they encounter an old man. The old man offers them chocolates and recounts his memories of the last summer of World War II. His experiences, both bitter and sweet, speak to universal human nature that transcends the conflict itself—a shared truth within every person, even if they are on opposing sides of a battle.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ningyo', 'Movie', 1, 'Completed', '1964-09-21', NULL, '6', 'In a fictional place where using the imagination is banned, a boy saves a fish, which surprises everyone by turning into a mermaid. The boy is arrested for imagining this "nonsense", and is robbed of his imagination as punishment. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Soreyuke! Uchuu Senkan Yamamoto Youko II', 'OVA', 3, 'Completed', '1997-08-06', '1997-12-22', '6', 'There is an ancient legend on a distant planet which states (among other things) that four goddesses will one day descend from the skies and all will be right with the world. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Konpeki no Kantai: Sourai Kaihatsu Monogatari', 'Special', 1, 'Completed', '1997-01-01', NULL, '6', 'A special which tells the story of the development of the japanese Sourai interceptor plane.', 436, 'https://cdn.myanimelist.net/images/anime/5/28412.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Arcana Famiglia', 'TV', 12, 'Completed', '2012-07-01', '2012-09-16', '6', '​On the island of Regalo, a group of supernaturally powered mafia-like protectors called the Arcana Famiglia safeguard the people from any who would harm them. The members of their organization, having made contracts with tarot cards, each possess different abilities, such as overwhelming strength, invisibility, or the power to see into someone''s heart. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cheer Danshi!! Recap', 'Special', 1, 'Completed', '2016-08-09', NULL, '6', 'Recap of first 5 episodes of Cheer Danshi!!', 143, 'https://cdn.myanimelist.net/images/anime/9/81428.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sinbad: Soratobu Hime to Himitsu no Shima Pilot', 'Special', 1, 'Completed', '2015-12-16', NULL, '6', 'Sinbad: Soratobu Hime to Himitsu no Shima pilot footage included with the DVD release. It features Sana''s chase scene in which Sinbad first interacts with her. The footage was not recycled for the film and no dialogue is used.', 607, 'https://cdn.myanimelist.net/images/anime/9/78284.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ashita Kirarin', 'OVA', 1, 'Completed', '2004-03-26', NULL, '6', 'Ayako suffers from autism, and all kids in the class mock her except for Yuri - the only girl who shows some kindness towards her. Greatly appreciating that, Ayako gives Yuri a present - a beaded bracelet.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Balala Xiao Mo Xian: Qiji Wubu', 'TV', 52, 'Completed', '2013-04-19', '2014-04-01', '6', 'The kingdom of Gemini is attacked by the evil Queen Halle. The twin princesses of the kingdom are missing, so is the important Night Star Box, which has affected planets including Earth. The fairy Queen had sent Prince You Le and Sally to Earth, looking for the Night Star Box with the help of Maggie and Michelle. Then the gang found out one of the girls who takes dance lessons with Maggie and Michelle is one of the missing princesses, Bei Bei! The mission to find the Night Star Box and the the still missing princess, Ya Ya, is now on the shoulder of the fairies.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Takamiya Nasuno desu! Teekyuu Spin-off Special', 'Special', 1, 'Completed', '2015-08-28', NULL, '6', 'Unaired special included in the Blu-ray and DVD release.', 566, 'https://cdn.myanimelist.net/images/anime/5/76334.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyoufu! Zombie Neko', 'TV', 52, 'Completed', '2015-10-02', '2016-09-30', '6', 'The series of "warm and soothing" anime shorts will follow a cat who is suddenly resurrected from the grave and begins to wander around town. Despite being a zombie, the cat is able to get all the townsfolk to fall in love with it.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dou Hun Wei Zhi Xuan Yue Qiyuan', 'ONA', 12, 'Completed', '2018-06-19', '2018-09-04', '6', 'In ancient times, spiritual holiness that tried to destroy humanity was caused by the soul on Xuan Huang’s Sword. Today, the human desire to develop without limits, plundering resources, destroying the environment, pierced through Xuan Huang’s sword. The rise of spiritual people will be their own dark power on the eve of Luosha teaching. Zhang Shan accidentally involved in the dispute. With soul power, he wants to save the danger of Moon Shang Devil.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Balala Xiao Mo Xian: Caihong Xin Shi', 'TV', 36, 'Completed', '2011-03-26', '2011-12-01', '6', 'After the fairies defeated Gunala, the Evil Goddess, another crisis hit the Fairy Castle!! The magical energy of the world has been devoured by the evil wizards. The Rainbow Flower, the source of the magic power, is soon to wither, and this will destroy the world of Fairy Castle. Only finding the legendary Rainbow Heart Stone and letting it recollect all the essential energy can save the world. To solve this biggest crisis in the history of the Fairy Castle, Prince YouLe, Sally, and their new friend XiaoQian, have to go back to the human world and reunite with Maggie and Michelle to fight the evil again.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ghost Messenger Movie', 'Movie', 1, 'Completed', '2014-05-22', NULL, '6', 'In this anime fantasy, Kanglim is a 5th grade Ghost Messenger on a supernatural mission. When he finds himself trapped in a Soul Phone, Kanglim, who has the power to see mystical spirits, must successfully capture one of them to free himself from the trap.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou no Princess Minky Momo vs. Mahou no Tenshi Creamy Mami', 'Movie', 1, 'Completed', '1985-08-03', NULL, '6', 'Shown as a bonus movie with the theatrical screening of Mahou no Tenshi Creamy Mami: Long Goodbye and Mahou no Princess Minky Momo: Yume no Naka no Rondo. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Usagi no Mofy', 'ONA', 13, 'Completed', '2012-09-30', '2012-12-20', '6', 'The story of a white rabbit and her friends.', 457, 'https://cdn.myanimelist.net/images/anime/10/57215.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eightman', 'TV', 56, 'Completed', '1963-11-07', '1964-12-24', '6', 'A private investigator working a routine case involving stolen technology is mortally wounded. His only hope for survival comes from sacrificing his humanity to become 8Man—a powerful cyborg crime-fighter enhanced with a living human brain. Resurrected as the ultimate high-tech vigilante, it is up to 8Man to bring the lawless to justice and put an end to the escalating cycle of violence. A classic animated thriller that will leave you breathless.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bokura Mangaka: Tokiwasou Monogatari', 'Special', 1, 'Completed', '1981-10-03', NULL, '6', 'Tokiwa was the apartment complex where a group of stellar artists lived in 1953.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ohayou! Spank (Movie)', 'Movie', 1, 'Completed', '1982-03-13', NULL, '6', 'Based on the shoujo manga by Yukimuro Shun''ichi and Takanashi Shizue serialised in Nakayoshi. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chocotan!', 'Special', 1, 'Completed', '2013-03-17', NULL, '6', 'After eating a strange flower, Chocotan the mini dachshund gains the ability to talk! Since then, the eager pup has been able to provide her young owner, Nao Hatori, with earnest support.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Daiyoshi P Produce Ashita no Jobuubu', 'ONA', 10, 'Completed', '2013-08-30', '2013-12-29', '5', 'A collaboration between Taka no Tsume and the Town Work, an employment office whose mascot is a pig called Jobuubu (a play on words of "job" and the Japanese onomatopoeia sounds a pig makes).', 214, 'https://cdn.myanimelist.net/images/anime/7/87586.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Taka no Tsumedan x Uchicomi!', 'ONA', 5, 'Completed', '2019-08-19', '2019-08-29', '5', 'A collaboration between Eagle Talon and Uchicomi the real estate company. Eagle Talon informs various people about Uchicomi''s app and easy ways for them to find housing meeting their specific requirements. Episodes were streamed on Uchicomi''s official YouTube channel and later, a compilation of all of them, were posted to DLE''s official YouTube channel.', 214, 'https://cdn.myanimelist.net/images/anime/1997/102853.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shika to Kanta', 'OVA', 1, 'Completed', '1992-04-01', NULL, '5', 'One day, Kanta, a lonely boy, rescues an orphaned baby deer and names it Poyu. There is something special about Poyu, his golden tail. When hunters go after Poyu, Kanta is determined to protect his golden-tailed friend and the other deer.', 1030, 'https://cdn.myanimelist.net/images/anime/8/72849.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fruity Samurai', 'TV', 13, 'Completed', '2013-08-13', '2013-12-14', '5', 'Classic samurai movies and absurd humor collide when fruit-headed warriors cross blades and tempers!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Noel no Fushigi na Bouken', 'Movie', 1, 'Completed', '1983-04-29', NULL, '5', 'The film is centered around Noel, a young girl and her dog, Pup, who both live on the Planet Noel. While relaxing, Noel comes up with the idea to deliver ice cream to the sun. The two fly off and make their way toward the sun.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doron Coron', 'Movie', 1, 'Completed', '2012-01-01', NULL, '5', 'An amusing 3-minute clay animation that Yuuichi Itou (Harbor Tale, Knyacki!) produced for "The Earth and Children of Tomorrow - Pray for Happiness" campaign by TVK (Television Kanagawa).
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lime-iro Ryuukitan X', 'TV', 13, 'Completed', '2005-01-05', '2005-03-30', '5', 'It was Meiji 38 (1905), the Russo-Japanese War that had begun since the previous year was getting hard. In this severe circumstance, they reorganized the Raimu Squad. The members of the Raimu Squad were the girls. They were just like other ordinary girls who went to schools and yearned for love, except that they had "Raimu."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shinken Seminar Koukou Kouza', 'OVA', 1, 'Completed', '2012-04-04', NULL, '5', 'Shinken Seminar Koukou Kouza is Benesse''s correspondence course that helps middle school students get into their high schools of choice. The story follows a middle school boy named Shouta as he strives to get in the right high school, despite the appearance of a rival.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Docchi ni Suru?', 'Movie', 1, 'Completed', '1999-01-01', NULL, '5', 'Raoul, an alligator, has a bad tooth, and also need a hair cut. Is he going to a barber, or a dentist, or neither of them? Madillo, an armadillo, wonders if he should bring an umbrella, or not. So, what is your choice?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Be-Bop Kaizokuban', 'OVA', 3, 'Completed', '1991-03-22', '1993-06-25', '5', 'Based on a parody manga of Be-Bop Highschool.', 1030, 'https://cdn.myanimelist.net/images/anime/3/62799.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Francesca', 'TV', 24, 'Completed', '2014-07-07', '2014-12-15', '5', 'TV anime adaptation based on the undead idol character Francesca to promote Hokkaido, Japan.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oshiri Tantei Movie 5: Saraba Itoshiki Aibou (Oshiri) yo', 'Movie', 1, 'Completed', '2024-03-20', NULL, '5', 'Oshiri Tantei''s partner who disappeared 10 years ago suddenly reappears. He receives a mysterious message from Suisen and soon finds himself embroiled in a case of counterfeit art involving a massive plot to shake up the art galleries around the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chikomaru Episode 0', 'ONA', 1, 'Completed', '2024-01-25', NULL, '5', '', 681, 'https://cdn.myanimelist.net/images/anime/1262/141140.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jian Xian Zai Ci 2nd Season', 'ONA', 50, 'Completed', '2024-01-27', '2024-07-06', '5', '', 1120, 'https://cdn.myanimelist.net/images/anime/1250/141051.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pui Pui Molcar the Movie: MOLMAX', 'Movie', 1, 'Completed', '2024-11-29', NULL, '5', 'CG animated movie based on Pui Pui Molcar.', 579, 'https://cdn.myanimelist.net/images/anime/1110/145824.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Major S2', 'TV', 26, 'Completed', '2005-12-10', '2006-06-10', '8', 'Gorou Honda has finally returned to Mifune East Junior High School, surprising his friends upon arrival. Now, Gorou is once again surrounded by those he holds closest, and he strives to continue playing and enjoying the game he loves most.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yojouhan Time Machine Blues', 'ONA', 6, 'Completed', '2022-09-14', '2022-10-12', '8', 'On a hot summer day in Kyoto, a young man walks toward his apartment, dreaming of turning on the air conditioner and cooling down. But before he can turn his dream into reality, disaster naturally strikes in the form of Ozu, who spills soda all over the remote. With the air conditioner rendered completely unusable, the man and his friends are left to suffer in the terrible August heat.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Natsume Yuujinchou: Ishi Okoshi to Ayashiki Raihousha', 'Movie', 1, 'Completed', '2021-01-16', NULL, '8', 'Ishi Okoshi
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Non Non Biyori Repeat', 'TV', 12, 'Completed', '2015-07-07', '2015-09-22', '8', 'Far from the hustle and bustle of urban life, and with only a single candy store and bus route to its name, the rural Asahigaoka is certainly not a place for everyone. Nevertheless, the village''s children still manage to cheerfully spend their days exploring and having fun in the wilderness around them. One such child, Renge Miyauchi, the youngest of the group, looks forward to the entrance ceremony of the upcoming school year, signalling her entry into first grade and the beginning of her elementary school life. Attending the only school in town, Renge and her friends, seventh grader Natsumi Koshigaya and her eighth grade sister Komari, make the most out of their rural lifestyle, playing and studying everyday.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimetsu no Yaiba: Katanakaji no Sato-hen', 'TV', 11, 'Completed', '2023-04-09', '2023-06-18', '8', 'For centuries, the Demon Slayer Corps has sacredly kept the location of Swordsmith Village a secret. As the village of the greatest forgers, it provides Demon Slayers with the finest weapons, which allow them to fight night-crawling fiends and ensure the safety of humans. After his sword was chipped and deemed useless, Tanjirou Kamado, along with his precious little sister Nezuko, is escorted to the village to receive a new one.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Initial D Fourth Stage', 'TV', 24, 'Completed', '2004-04-17', '2006-02-18', '8', 'Takumi Fujiwara finally joins Ryousuke and Keisuke Takahashi to create "Project D." Their goal is twofold: Ryousuke wants to develop his "High-Speed Street Racing Theory," while Keisuke and Takumi aim at improving their driving skills by facing powerful opponents on dangerous roads. The idea of Project D is to challenge street racing teams from other prefectures to improve both their uphill and downhill records. In order to attract the attention of the best racing teams, Ryousuke creates a dedicated website to announce the future battles of Project D and post the team''s results.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ballroom e Youkoso', 'TV', 24, 'Completed', '2017-07-09', '2017-12-17', '8', 'Tatara Fujita is a shy middle schooler who has no particular plan for the future. He has gotten through life by avoiding any kind of confrontation and blending in with the crowd. But blending in isn''t enough to get out of trouble, as some bullies harass him for money. Luckily, he is saved by a man named Kaname Sengoku.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bungou Stray Dogs 2nd Season', 'TV', 12, 'Completed', '2016-10-06', '2016-12-16', '8', 'Despite their differences in position, three men—the youngest senior executive of the Port Mafia, Osamu Dazai; the lowest ranking member, Sakunosuke Oda; and the intelligence agent, Ango Sakaguchi—gather at the Lupin Bar at the end of the day to relax and take delight in the company of friends.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('No Game No Life: Zero', 'Movie', 1, 'Completed', '2017-07-15', NULL, '8', 'In ancient Disboard, Riku is an angry, young warrior intent on saving humanity from the warring Exceed, the 16 sentient species, fighting to establish the One True God among the Old Deus. In a lawless land, humanity''s lack of magic and weak bodies have made them easy targets for the other Exceed, leaving the humans on the brink of extinction. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aria the Natural', 'TV', 26, 'Completed', '2006-04-03', '2006-09-25', '8', 'Akari Mizunashi continues her training to become a Prima Undine (a professional tour guide gondolier) along with her friends Aika and Alice in the peaceful city of Neo Venezia. Despite the fact that these three girls are from competing companies, they are constantly together, learning more about how to become better tour guides and more about the mysteries of Neo Venezia.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ouran Koukou Host Club', 'TV', 26, 'Completed', '2006-04-05', '2006-09-27', '8', 'Haruhi Fujioka is a studious girl who has recently enrolled at the prestigious Ouran Academy. One day, while looking for a quiet and peaceful place to study, she stumbles across a seemingly unused music room. Upon entering, Haruhi is welcomed by the members of the well-known Host Club: a club in which attractive boys amuse girls from across the entire school. However, when Tamaki Suou—the founder and president of the club—startles the bright scholarship student, she accidentally breaks an expensive vase.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Higurashi no Naku Koro ni Kai', 'TV', 24, 'Completed', '2007-07-06', '2007-12-18', '8', 'In the small village of Hinamizawa, Rika Furude and her friends live together in relative harmony. Beneath this mask of peace, however, lies a hidden darkness, one that Rika understands all too well. In this eternal summer, she has been witness to unspeakable horrors. Every time the clock resets, Rika must try to find the villain behind these senseless deaths before tragedy strikes again. However, trying to decipher a mystery when only half the clues are present proves time and again to be disastrous, and each time she believes that things will change, she inevitably fails. As the annual festival approaches, Rika begins her descent from hope to despair in her struggle to break the chains of fate entangling them all.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Akira', 'Movie', 1, 'Completed', '1988-07-16', NULL, '8', 'Japan, 1988. An explosion caused by a young boy with psychic powers tears through the city of Tokyo and ignites the fuse that leads to World War III. In order to prevent any further destruction, he is captured and taken into custody, never to be heard from again. Now, in the year 2019, a restored version of the city known as Neo-Tokyo—an area rife with gang violence and terrorism against the current government—stands in its place. Here, Shoutarou Kaneda leads "the Capsules," a group of misfits known for riding large, custom motorcycles and being in constant conflict with their rivals "the Clowns."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kono Subarashii Sekai ni Shukufuku wo! 3: Bonus Stage', 'OVA', 2, 'Completed', '2025-04-25', NULL, '8', 'Original video anime episodes of Kono Subarashii Sekai ni Shukufuku wo!.', 244, 'https://cdn.myanimelist.net/images/anime/1482/146928.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Holo no Graffiti', 'ONA', NULL, 'Airing', '2019-05-05', NULL, '8', 'From unraveling the secrets of opening and closing doors to defusing surprise packages more commonly known as bombs, there is never a dull day at the Hololive Production office! Holo no Graffiti follows an eccentric cast of Virtual YouTubers, also known as "VTubers," going about their absurd yet hilarious daily lives, detailing all their cute moments and mishaps.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lupin III: Cagliostro no Shiro', 'Movie', 1, 'Completed', '1979-12-15', NULL, '8', 'Arsene Lupin III discovers that the spoils from his latest casino robbery are actually "Gothic Bills," legendary counterfeits that are nigh impossible to distinguish from genuine bills. Together with colleague Daisuke Jigen, he heads to the small nation of Cagliostro to investigate the origin of these counterfeits. Upon arrival, they save a girl from a high-speed chase who turns out to be Clarisse d'' Cagliostro, the daughter of the late Duke d'' Cagliostro. She is running from a sinister plot by Count Cagliostro to steal her family''s treasure through a forced marriage.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fate/stay night Movie: Heaven''s Feel - I. Presage Flower', 'Movie', 1, 'Completed', '2017-10-14', NULL, '8', 'The Holy Grail War: a violent battle between mages in which seven masters and their summoned servants fight for the Holy Grail, a magical artifact that can grant the victor any wish. Nearly 10 years ago, the final battle of the Fourth Holy Grail War wreaked havoc on Fuyuki City and took over 500 lives, leaving the city devastated. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dr. Stone: New World', 'TV', 11, 'Completed', '2023-04-06', '2023-06-15', '8', 'With the ambitious Ryuusui Nanami on board, Senkuu Ishigami and his team are almost ready to sail the seas and reach the other side of the world—where the bizarre green light that petrified humanity originated. Thanks to the revival of a skillful chef, enough food is being prepared for the entire crew, and the incredible reinvention of the GPS promises to ensure safety on the open sea.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ao Ashi', 'TV', 24, 'Completed', '2022-04-09', '2022-09-24', '8', 'In a quiet rural town, the spotlight of a local junior high school football team rests on one player: Ashito Aoi. Known for his unpredictable moves and self-centered playing style, Ashito is the sole powerhouse pushing his team through an important high school preliminary tournament. However, their win streak is short-lived—an opponent causes Ashito to lose his temper and act violently, resulting in his removal from the rest of the game.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Non Non Biyori Nonstop: Bukatsu wo Ganbatta', 'OVA', 1, 'Completed', '2022-03-23', NULL, '8', 'Beginning her academic journey as a first grader, Shiori comes face to face with the aspect of school she has heard alarming rumors about—homework! However, her worries quickly turn into excitement as the Asahigaoka girls agree to work together to complete their assignments at Komari and Natsumi Koshigaya''s house. Their plan appears to be successful until an all-too-familiar feeling of procrastination creates a rowdy distraction for Natsumi.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blue Lock', 'TV', 24, 'Completed', '2022-10-09', '2023-03-26', '8', 'Yoichi Isagi was mere moments away from scoring a goal that would have sent his high school soccer team to the nationals, but a split-second decision to pass the ball to his teammate cost him that reality. Bitter, confused, and disappointed, Isagi wonders if the outcome would have been different had he not made the pass. When the young striker returns home, an invitation from the Japan Football Union awaits him. Through an arbitrary and biased decision-making process, Isagi is one of three hundred U-18 strikers selected for a controversial project named Blue Lock. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kotarou wa Hitorigurashi', 'ONA', 10, 'Completed', '2022-03-10', NULL, '8', 'One day, manga author Shin Karino is greeted by four-year-old Kotarou Satou, his new next-door neighbor, who gifts him a box of tissues. In Karino''s eyes, Kotarou is an odd kid: he speaks in an extremely formal manner, and he lives alone in his apartment—no parents or relatives in sight. But Kotarou neither seems to mind, nor wants to rely on people.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dr. Stone: Stone Wars', 'TV', 11, 'Completed', '2021-01-14', '2021-03-25', '8', 'Senkuu has made it his goal to bring back two million years of human achievement and revive the entirety of those turned to statues. However, one man stands in his way: Tsukasa Shishiou, who believes that only the fittest of those petrified should be revived.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lycoris Recoil', 'TV', 13, 'Completed', '2022-07-02', '2022-09-24', '8', 'The number of terrorist acts in Japan has never been lower, thanks to the efforts of a syndicate called Direct Attack (DA). The organization raises orphaned girls as killers to carry out assassinations under their "Lycoris" program. Takina Inoue is an exceptional Lycoris with a strong sense of purpose and a penchant for perfection. Unfortunately, a hostage situation tests her patience, and the resulting act of insubordination leads to her transfer out of DA. Not thrilled about losing the only place she belonged to, she reluctantly arrives at her new base of operations—LycoReco, a cafe in disguise.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hyakuemu.', 'Movie', 1, 'Completed', '2025-09-19', NULL, '8', 'Togashi is born to run. As a kid, he is naturally gifted and wins every 100-meter race without effort. But in sixth grade, he meets Komiya, a transfer student who is full of determination but lacks technique. In teaching him, Togashi gives Komiya a new purpose: to win no matter what. Years pass by, Togashi and Komiya meet again as rivals on the track and reveal their true selves.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koutetsujou no Kabaneri Movie 1: Tsudou Hikari', 'Movie', 1, 'Completed', '2016-12-31', NULL, '8', 'During an era of rapid industrial growth, humanity is beset by the emergence of a mysterious virus, capable of turning humans into mindless creatures called "Kabane." With a desire for nothing but human flesh, these undead beings can only be killed by destroying their hearts—which are encased in a cage of unyielding iron.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Totsukuni no Shoujo', 'OVA', 1, 'Completed', '2019-09-10', NULL, '8', 'Let not an Outsider touch thee,
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Free! Dive to the Future: Soushun no Build-up!', 'Special', 1, 'Completed', '2018-06-23', NULL, '8', 'As they adjust to life in Tokyo, Haruka Nanase and Makoto Tachibana prepare for their university''s opening ceremony. However, while running some errands, they find themselves representing Iwatobi in a regional mascot wrestling tournament. Unbeknownst to them, the rest of the Iwatobi and Samezuka swim club members are watching the event''s live broadcast at a local festival.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Akudama Drive', 'TV', 12, 'Completed', '2020-10-08', '2020-12-24', '8', 'The bustling metropolis of Kansai, where cybernetic screens litter the neon landscape, may seem like a technological utopia at first glance. But in the dark alleys around the brightly-lit buildings, an unforgiving criminal underbelly still exists in the form of fugitives known as "Akudama." 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Re:Zero kara Hajimeru Isekai Seikatsu - Hyouketsu no Kizuna - Manner Movie', 'Movie', 1, 'Completed', '2019-11-08', NULL, '8', 'A manner movie shown before Re:Zero kara Hajimeru Isekai Seikatsu - Hyouketsu no Kizuna.', 945, 'https://cdn.myanimelist.net/images/anime/1599/106827.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ao Haru Ride OVA', 'OVA', 2, 'Completed', '2014-08-25', '2014-12-12', '8', 'Unwritten
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tennis no Oujisama: Another Story - Kako to Mirai no Message', 'OVA', 4, 'Completed', '2009-05-26', '2009-09-25', '8', '1. Naniwa no Oujisama: Zenpen
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchuu Kyoudai: Number Zero', 'Movie', 1, 'Completed', '2014-08-09', NULL, '8', 'Prequel to the TV anime series revolving around the "origin of the dream."', 14, 'https://cdn.myanimelist.net/images/anime/5/61639.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Code Geass: Hangyaku no Lelouch Special Edition - Black Rebellion', 'OVA', 1, 'Completed', '2008-02-22', NULL, '8', 'An OVA summarizing all 25 episodes of season 1 from Lelouch''s viewpoint.', 974, 'https://cdn.myanimelist.net/images/anime/6/23532.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hokuto no Ken 2', 'TV', 43, 'Completed', '1987-03-12', '1988-02-18', '8', 'In the second series after Raoh has been defeated by Kenshiro a new rival appears. The Gentou Kouken warriors. Falco the successor of the Gentou Kouken takes orders from an evil ruler by the name of Jacko. He claims to be the man chosen by the Tentei and issues orders to his subordinates to capture anyone living in order to build up his Imperial Capital. Kenshiro once again rises out of the shadows and puts an end to his tyrannical ways. Amidst the mayhem Lynn gets captured and gets taken to the land of the Shura where only ruthless fighters exist. Now Kenshiro must pursue the captor and defeat the 3 Rasho of the land in order to escape with his life and with Lynn.', 1030, 'https://cdn.myanimelist.net/images/anime/1912/106020.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ranma ½: Yomigaeru Kioku', 'OVA', 2, 'Completed', '1994-12-16', '1995-02-17', '8', '"Reawakening Memories" deals with Akane suddenly remembering a trip to Ryugenzawa when she was a small child. While there she was saved from a giant platypus by Shinnosuke. Akane travels back to Ryogenzawa and once again meets Shinnosuke, who falls in love with her. Akane blames herself for Shinnosuke`s life-threatening injuries, and decides to stay and help out. This irritates Ranma, who thinks that Akane has fallen in love with Shinnosuke, and will do what it takes to get her back.', 879, 'https://cdn.myanimelist.net/images/anime/11/63453.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsubasa Chronicle 2nd Season', 'TV', 26, 'Completed', '2006-04-29', '2006-11-04', '8', 'Syaoran, Sakura, Kurogane, Fai and Mokona''s journey through to different world''s continue as they search for Sakura''s feathers. The fated journey slowly becomes more complicated for our travelers, as they find themselves diving deeper into more dangerous worlds.', 122, 'https://cdn.myanimelist.net/images/anime/4/6554.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kiniro Mosaic: Thank You!!', 'Movie', 1, 'Completed', '2021-08-20', NULL, '8', 'Time flies when you''re having fun, and it seems like only yesterday that Oomiya Shinobu was nervously waiting for her friend Alice Cartelet to arrive from England to study at Shinobu''s school in Japan. Now, in their third and final year, Alice, Shinobu, Aya, and Youko have truly become the best of friends and even Karen, Honoka, and Kana are part of the gang as well. But since it''s their last year, that means their time will be split between preparing for the big senior trip to Nara and Kyoto, and trying to make plans for whatever is to come next in their lives... and in Shinobu''s case, that may mean something so amazing that she''d never even dared to dream it!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Majin Tantei Nougami Neuro', 'TV', 25, 'Completed', '2007-10-03', '2008-03-26', '8', 'Yako Katsuragi is an acclaimed high school detective, who, despite her young age, has solved many cases. In fact, there seems to be no case that she cannot solve, or any culprit that escapes justice. But within the walls of her detective agency lies the secret to her prolific crime-solving skills: the cases are actually solved by her assistant, Neuro Nougami.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Totsukuni no Shoujo (2022)', 'OVA', 1, 'Completed', '2022-03-10', NULL, '8', 'OVA bundled with the special edition of the manga''s side story.', 1105, 'https://cdn.myanimelist.net/images/anime/1957/113267.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Romeo x Juliet', 'TV', 24, 'Completed', '2007-04-05', '2007-09-26', '8', 'On the floating continent of Neo Verona, the Montague family slaughters the entire Capulet family and seizes control of the kingdom. The true heir to the throne, Juliet Fiammata Asto Capulet, manages to escape the onslaught and is hidden away by loyalists for 14 years with hope that she may one day overthrow the cruel Montague regime. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ao no Exorcist Movie', 'Movie', 1, 'Completed', '2012-12-28', NULL, '8', 'As the grand festival of True Cross Academy draws near, exwires and exorcists alike combine their efforts to banish any demon that threatens the celebrations. Among them, Rin Okumura is tasked with exorcising the soul-devouring demon known as the Phantom Train alongside his brother Yukio and Shiemi Moriyama.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fairy Tail', 'TV', 175, 'Completed', '2009-10-12', '2013-03-30', '8', 'In the enchanted Kingdom of Fiore, the lively Lucy Heartfilia has one wish: to join the renowned Fairy Tail—one of the many magical wizard guilds scattered around the continent. Luckily, a chance encounter with Natsu Dragneel, the "Salamander" of Fairy Tail, whisks her into the legendary guild.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hakuouki: Sekkaroku', 'OVA', 6, 'Completed', '2011-08-05', '2012-06-27', '8', 'Rumors about a potential plot to dismantle the Shinsengumi by setting fire to their headquarters have spread amok. As most of the talk stems from an inn in Shimabara, the Shinsengumi place trust in Chizuru Yukimura for help with the investigation. Disguised as a geisha, Chizuru infiltrates the inn to provide intel for the Shinsengumi but quickly finds that the operation is more intricate than they could ever imagine.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ima, Soko ni Iru Boku', 'TV', 13, 'Completed', '1999-10-14', '2000-01-20', '8', 'Shuuzou "Shuu" Matsutani lives his ordinary life in peace. He has friends, a crush, and a passion for kendo. Dejected after losing to his kendo rival, Shuu climbs a smokestack to watch the sunset where he finds Lala-Ru, a quiet, blue-haired girl wearing a strange pendant. Shuu attempts to befriend her, despite her uninterested, bland responses.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Keisatsu Patlabor: New OVA', 'OVA', 16, 'Completed', '1990-11-22', '1992-04-23', '8', 'Special Vehicles Division 2 is back on duty, along with their Ingram Patrol Labor (Patlabor) robots. Using their courage as well as the Ingrams, Captain Goto''s motley crew of officers battle crime in Tokyo city. They also deal with their personal lives, as well as the supernatural. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Soredemo Sekai wa Utsukushii', 'TV', 12, 'Completed', '2014-04-06', '2014-06-29', '8', 'In the Sun Kingdom, sunshine is part of its citizens'' everyday lives, and rain is something that they have never even heard of. However, in a faraway land called the Rain Dukedom, the weather is reversed, and everybody has the power to create rain with their voices.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wonderful Precure!', 'TV', 50, 'Completed', '2024-02-04', '2025-01-26', '8', 'The Wonderful Precure! anime is set in Animal Town, a town where animals and people live together in harmony. Second-year junior high school student Iroha Inukai is best friends with her dog named Komugi. Out for a walk one day, Iroha and Komugi encounter a mysterious creature named Garugaru, who goes on a rampage in the city. Komugi suddenly transforms into a Pretty Cure named Cure Wonderful, to protect Iroha.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Trillion Game', 'TV', 26, 'Completed', '2024-10-04', '2025-03-28', '8', 'After socially awkward technology specialist Manabu "Gaku" Taira is saved from thugs by the outgoing Haru Tennouji, the two men find that they get along with each other well. Years later, Gaku, who is having a tough time getting a job due to his timidness, is convinced by Haru to apply for a position alongside him at Dragon Bank, one of Japan''s largest IT companies.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('COLORs', 'ONA', 1, 'Completed', '2023-03-24', NULL, '8', 'A girl finds herself mesmerized by a young woman with pink hair. After repeated encounters with the woman, the girl realizes the person is one of her aloof classmates—who identifies as a boy in school.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Spy x Family Movie: Code: White Manner Movie', 'Movie', 1, 'Completed', '2023-07-28', NULL, '7', 'Wit Studio and Cloverworks released a new short film using Spy x Family to remind the general public of basic movie theater etiquette. You’ll be able to watch it from all Toho cinemas in Japan. All members of the immediate Forger family are present. It focuses on Loid and Yor teaching Anya how to behave when in a movie theater. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shaonian Ge Xing: Haiwai Xianshan Pian', 'ONA', 26, 'Completed', '2023-10-25', '2024-04-10', '7', 'When facing adversities, it is essential to maintain a peaceful mindset and remain optimistic. The head of the Lei family tragically passed away after the battle at Lei Family Castle, the Sword Deity thus perished. In an attempt to force himself to use his internal energy, Xiao Se pushed himself to the brink of death. The group embarked on a journey to the mysterious Immortal Mountain overseas to find the legendary deity so that they could save Xiao Se. At the same time, the power struggle between the imperial court and the martial arts world was still going on.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Houkago no Breath', 'ONA', 4, 'Completed', '2023-09-06', '2023-12-13', '7', 'Just before the arrival of a certain transfer student, three students at an academy in Paldea are tasked with making a video showcasing their school. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zhen Wu Dianfeng 2nd Season', 'ONA', 52, 'Completed', '2023-05-10', '2023-11-25', '7', 'The second season of Zhen Wu Dianfeng.', 752, 'https://cdn.myanimelist.net/images/anime/1877/135536.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kikansha no Mahou wa Tokubetsu desu', 'TV', 12, 'Completed', '2023-10-08', '2023-12-24', '7', 'After a decade spent fighting monsters in the Shadow Labyrinth—a growing dark cloud of magic that threatens to engulf the world and destroy all life—mage Desir Herrman and his five companions finally face their last foe: the dragon of destruction Boromir Napolitan. Although the group of heroes manages to slay this formidable opponent, the tremendous amount of mana stored within the dragon''s body is released in an unstoppable explosion that annihilates the rest of the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xi Xing Ji: Chongsheng Pian', 'ONA', 12, 'Completed', '2022-06-01', '2022-08-03', '7', 'The fourth season of Xi Xing Ji.', 113, 'https://cdn.myanimelist.net/images/anime/1790/124208.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Persona 5 the Animation: The Day Breakers', 'Special', 1, 'Completed', '2016-09-03', NULL, '7', 'There is a new urban legend circulating Tokyo. It claims that if you make a request in the Ask-a-Thief Channel, the Phantom Thieves of Hearts will show up and bring justice by stealing a corrupt person''s heart and making them regret all their wrongdoings. As strange and inexplicable events continue to happen all around town, more people submit their requests in hope that the mysterious vigilante group will help.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shakunetsu no Takkyuu Musume', 'TV', 12, 'Completed', '2016-10-04', '2016-12-20', '7', 'In the world of Japanese ping pong, a mighty king has fallen. An underdog team suddenly breaks the indomitable Oudou Academy''s nine year winning streak, creating a power vacuum as players everywhere are given hope that they too can reach the national tournament.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Osake wa Fuufu ni Natte kara: Yuzu Atsukan', 'ONA', 1, 'Completed', '2018-10-06', NULL, '7', 'The Osake wa Fuufu ni Natte kara talk event at the Machi★Asobi vol. 20 event announced that the short series will receive a 14th episode. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('GA: Geijutsuka Art Design Class - Aozora ga Kakitai', 'OVA', 1, 'Completed', '2010-04-02', NULL, '7', 'GA: Geijutsuka Art Design Class OVA. "I Want to Draw the Blue Sky"', 30, 'https://cdn.myanimelist.net/images/anime/1463/153612.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ookami to Koushinryou II: Holo no Short Anime', 'Special', 2, 'Completed', '2009-10-07', '2009-11-04', '7', 'Extra short anime featuring Holo from BD volumes 1 and 2.', 143, 'https://cdn.myanimelist.net/images/anime/4/17117.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon Movie 12: Arceus Choukoku no Jikuu e', 'Movie', 1, 'Completed', '2009-07-18', NULL, '7', 'In ages long forgotten, when Earth found itself on a collision course with a meteor, Legendary Pokémon Arceus used its power to avert the danger. However, this feat caused the 16 Plates surrounding it to scatter across the world. Without the Plates providing Arceus with life energy, it began to die. A human named Damon managed to find one of the Plates and returned it to the moribund Pokémon, helping it recover. As a reward, Arceus created the Jewel of Life and gave it to the people of Michina Town, stipulating that it must be returned, but the humans refused, hogging the Jewel to themselves. In the battle that ensued, Damon was killed and Arceus went into slumber, vowing to punish humanity upon its return.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Great Mazinger', 'TV', 56, 'Completed', '1974-09-08', '1975-09-28', '7', 'A manga comic book and anime television series by manga artist Go Nagai, made as a direct continuation of the successful Mazinger Z series. It was aired on Japan in 1974, immediately following the end of the first Mazinger series.', 1030, 'https://cdn.myanimelist.net/images/anime/1505/127976.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shangri-La', 'TV', 24, 'Completed', '2009-04-06', '2009-09-14', '7', 'In a post-apocalyptic society, much of earthquake-riddled Japan has been left to ruin, resulting in an abundance of greenery. Governments manage much of the world''s emissions, resulting in a massive class divide and economic disparity. The Japanese government launches "Project Atlas," a utopian city that will replace Tokyo but can only fit a certain amount of people. This limitation means that some people will have to live outside the city in jungles, as refugees.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nisekoi: OVA', 'OVA', 2, 'Completed', '2016-01-04', NULL, '7', 'Shinkon
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yes ka No ka Hanbun ka', 'Movie', 1, 'Completed', '2020-12-11', NULL, '7', 'Kei Kunieda is a newscaster who strictly maintains an amiable and kind persona while at work. Although he smiles on the outside, he covertly curses at others to his heart''s content. His everyday life is smooth, even if he keeps half of himself hidden at all times, but that changes when he meets Ushio Tsuzuki, an independent stop-motion animator.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Show By Rock!! Mashumairesh!!', 'TV', 12, 'Completed', '2020-01-09', '2020-03-26', '7', 'New Show by Rock!! TV Series featuring the new band Mashumairesh!!.', 480, 'https://cdn.myanimelist.net/images/anime/1297/110719.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tokyo Magnitude 8.0 Recap', 'Special', 1, 'Completed', '2009-12-11', NULL, '7', 'Recap special of Tokyo Magnitude 8.0.', 138, 'https://cdn.myanimelist.net/images/anime/6/18435.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Code Geass: Hangyaku no Lelouch R2 Picture Drama', 'Special', 9, 'Completed', '2008-08-22', '2009-04-24', '7', 'Though it has been one year since the Black Rebellion failed, the battle lives on, as the Holy Empire of Britannia attempts to expand its power worldwide, and the Black Knights work to regain theirs.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hi no Tori', 'TV', 13, 'Completed', '2004-03-21', '2004-06-27', '7', 'From prehistoric times to the distant future, Hi no Tori portrays how the legendary immortal bird Phoenix acts as a witness and chronicler for the history of mankind''s endless struggle in search of power, justice, and freedom.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toaru Kagaku no Railgun S: Motto Marutto Railgun', 'Special', 2, 'Completed', '2013-07-24', '2013-11-27', '7', 'Toaru Kagaku no Railgun S specials that were released on Blu-ray and DVD volumes.', 436, 'https://cdn.myanimelist.net/images/anime/2/52717.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chikyuugai Shounen Shoujo', 'ONA', 6, 'Completed', '2022-01-28', NULL, '7', 'In the year 2045, Internet and artificial intelligence have become widespread in the outer space. Following a massive accident at a space station, a group of children are left behind. Using narrowband and SNS, low intelligence AI, and smartphone-controlled drones, they overcome numerous crises.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bem Movie: Become Human', 'Movie', 1, 'Completed', '2020-10-02', NULL, '7', 'Take place 2 years after the last episode of the TV series.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koisuru Tenshi Angelique: Kokoro no Mezameru Toki', 'TV', 13, 'Completed', '2006-07-08', '2006-09-30', '7', 'A young girl named Ange is summoned to a Sacred Land and is chosen as the Legendary Etoile, whose mission is to save the newly-born Cosmos of the Holy Beast, which has recently fallen under a crisis. With the support of nine Guardians (who have the power of nine elements), she embarks on a journey to save the dying land of the Holy Beast and to discover her true self. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Queen Emeraldas', 'OVA', 4, 'Completed', '1998-06-05', '1999-12-18', '7', 'In a far distant future, a would-be master race seeks to dominate the galaxy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Touch: Cross Road - Kaze no Yukue', 'Special', 1, 'Completed', '2001-02-09', NULL, '7', 'Trying to find his own game of baseball, and not that of his brothers, Tatsuya moves to America and pitches for a poor, struggling minor league baseball team called the Emeralds. Meanwhile, Minami is still in Japan, trying to find her own path after quitting gymnastics. Inspired by a photograph of her final performance, she becomes the photographers assisstant.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tegamibachi: Omakebachi', 'Special', 25, 'Completed', '2010-12-22', '2011-08-26', '7', 'Tegamibachi Reverse DVD short extra episodes.', 683, 'https://cdn.myanimelist.net/images/anime/2/26809.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Isekai Maou to Shoukan Shoujo no Dorei Majutsu', 'TV', 12, 'Completed', '2018-07-05', '2018-09-20', '7', 'When it comes to the fantasy MMORPG Cross Reverie, none can match the power of the Demon King Diablo. Possessing the game''s rarest artifacts and an unrivaled player level, he overpowers all foolish enough to confront him. But despite his fearsome reputation, Diablo''s true identity is Takuma Sakamoto, a shut-in gamer devoid of any social skills. Defeating hopeless challengers day by day, Takuma cares about nothing else but his virtual life—that is, until a summoning spell suddenly transports him to another world where he has Diablo''s appearance! 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Guimi Zhi Zhu: Caidan', 'ONA', 9, 'Completed', '2025-06-28', '2025-08-16', '7', 'Chibi side stories released alongside the main series.', 108, 'https://cdn.myanimelist.net/images/anime/1120/151941.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blue Lock: Episode Nagi - Additional Time!', 'Movie', 4, 'Completed', '2024-04-19', '2024-05-10', '7', 'A series of shorts which aired along with the release of Blue Lock: Episode Nagi. A different short was shown each week during the film''s theatrical run and they were all included with the BD release.', 12, 'https://cdn.myanimelist.net/images/anime/1006/146003.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Great Pretender: Razbliuto', 'ONA', 4, 'Completed', '2024-02-23', '2024-03-15', '7', 'Presumed dead, master con artist and recovering amnesiac Dorothy is discovered by Shanghai Longu-bang, a mob who wants payback for her conning them. With no memories and nowhere to go, she must rely on a local crime underboss to elude Taipei’s criminal underworld all while tracking down leads to her mysterious past.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Madougushi Dahliya wa Utsumukanai', 'TV', 12, 'Completed', '2024-07-06', '2024-09-21', '7', 'Tragically perishing from overwork, a young Japanese woman is reborn as Dahliya Rossetti, daughter of a newly entitled baron. Her father, Carlo, is a beloved magic artificer, a maker of magical tools. Inspired by him, Dahliya uses her memories from her previous life to create practical inventions and become a magic artificer like Carlo.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jiu Chen Fengyun Lu', 'ONA', 40, 'Completed', '2023-07-11', '2023-11-21', '7', 'Yang Chen, the grandson of the Patriarch of the Yang Mansion, was ridiculed by the people in the mansion because he had not awakened his Dao Soul for a long time. In desperation, he breaks through himself to awaken the Dao Soul and Qi Ling Huangyu, and realizes that the crowd headed by his uncle is forcing Grandpa to give up the position of Patriarch. Afterwards, Yang Chen decided to improve his strength to protect his family, and went to Youyun Mountain alone to find medicine. In the end, everyone''s conspiracy was broken and the position of Patriarch was kept.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nijiyon Animation', 'TV', 12, 'Completed', '2023-01-06', '2023-03-24', '7', 'Short anime based on the 4-koma series illustrating the daily lives of the Nijigasaki High School Idol Club’s members.', 974, 'https://cdn.myanimelist.net/images/anime/1977/135538.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kinsou no Vermeil: Gakeppuchi Majutsushi wa Saikyou no Yakusai to Mahou Sekai wo Tsukisusumu', 'TV', 12, 'Completed', '2022-07-05', '2022-09-20', '7', 'Alto Goldfilled, a diligent student at the Ortigia Academy of Magic, aspires to become a powerful sorcerer. But he is unable to become one as, despite his excellent grades and strong commitment to his studies, he fails his summoning class. With the threat of repeating a year hanging over his head, Alto tries following an old, worn-out grimoire in a desperate attempt to resolve his situation.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Okoshiyasu, Chitose-chan', 'TV', 24, 'Completed', '2018-10-06', '2019-03-23', '7', 'Chitose-chan is a penguin who lives in Kyoto. Getting in touch with people and getting fed delicious food as she curiously walks around Kyoto streets is her favourite thing to do. The story features popular places in Kyoto like Kiyomizu Temple, Ginkaku Temple, and Gion from the Penguin''s point of view. This is a short story about a penguin that is nostalgic and warm, curing and relieving the heart. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toaru Kagaku no Railgun S: Daiji na Koto wa Zenbu Sentou ni Osowatta', 'OVA', 1, 'Completed', '2014-03-25', NULL, '7', 'Bundled with the official visual book.', 436, 'https://cdn.myanimelist.net/images/anime/2/76119.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Senkou no Night Raid Specials', 'Special', 3, 'Completed', '2010-06-23', '2010-12-22', '7', 'Three un-aired episodes included on the BD/DVD volumes. See More Info for an episode list.', 14, 'https://cdn.myanimelist.net/images/anime/3/26157.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Musaigen no Phantom World: Mizutama no Kiseki', 'Special', 1, 'Completed', '2016-10-05', NULL, '7', 'A special unaired episode of Musaigen no Phantom World bundled with the series'' seventh DVD/BD volume.', 494, 'https://cdn.myanimelist.net/images/anime/7/82387.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kawaru Machi, Kawareru Machi, Ishinomaki feat. Jun', 'ONA', 1, 'Completed', '2022-02-11', NULL, '6', 'The Ishinomori Manga Museum released an animated short directed by Takuya Inaba based on Shotaro Ishinomori''s semi-autobiographical and wordless manga Jun: Shotaro no Fantasy World. The short was inspired by Ishinomori''s hometown of Ishinomaki wishing to pay tribute to the work while also paying tribute to the ongoing rebuilding and recovery of Ishinomaki from the Tohoku earthquake and tsunami of March 2011.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Twisted-Wonderland: Glorious Masquerade PV', 'Special', 1, 'Completed', '2022-10-25', NULL, '6', 'Students of Night Raven College are invited to a gathering of prospective mages being held at Noble Bell College, in the distant City of Flowers. Clothed in borrowed finery, the visiting delegates anticipate the glorious masquerade that will mark the climax of the cultural exchange. Meanwhile, the bell that is the college''s namesake rings relentlessly.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koi wa Futago de Warikirenai', 'TV', 12, 'Completed', '2024-07-10', '2024-09-25', '6', 'Jun Shirasaki and the Jinguuji sisters are childhood friends and neighbors. When Jun''s first girlfriend, the older sister Rumi, breaks up with him, she says something that complicates the three people''s relationship, their first loves, and their romance—?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Your Forma', 'TV', 13, 'Completed', '2025-04-02', '2025-06-25', '6', 'In an alternate 2023, the Your Forma, a miraculous "smart thread" technology initially developed to treat a massive outbreak of viral encephalitis, has become an integral part of daily life. But these convenient devices come with an invasive drawback—they record every sight, sound, and even emotion their users experience.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Appleseed XIII', 'OVA', 13, 'Completed', '2011-06-03', '2012-01-25', '6', 'After facing massive destruction from a devastating war, the city Olympus has become the last stronghold as the center of command for the world. In order to protect the city from a group of terrorists known as the Argonauts, former LAPD SWAT member, Deunan Knotts, runs special military forces consisting of Biroids (cloned humans) and her cyborg partner Brialeos. Knotts must protect the city at all costs but is met with difficulties when Al Ceides, the Argonaut leader thought to be dead, resurfaces and causes problems. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bakugan Battle Brawlers: Mechtanium Surge', 'ONA', 46, 'Completed', '2018-09-01', '2018-01-01', '6', 'After returning from the feuding realms of Gundalia and Neathia, Danma Kuusou and his companions continue their lives on Earth. Now, a year later, the virtual reality world of Bakugan Interspace has finally recovered from the alien invasion and has once again become a place for brawlers to gather and challenge themselves.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Komori-san wa Kotowarenai!', 'TV', 12, 'Completed', '2015-10-04', '2015-12-20', '6', 'Fifteen-year-old Komori Shuri is a junior high school girl who is too nice to decline requests. Constantly doing favors for other people has given her incredible strength?! But even so, she is also an adolescent junior high school girl.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Air Recap', 'Special', 1, 'Completed', '2005-04-01', NULL, '6', 'A recap of Air. It was also included on its own DVD release, separate from the original show''s DVD/BD releases.', 494, 'https://cdn.myanimelist.net/images/anime/12/87100.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sekkou Boys', 'TV', 12, 'Completed', '2016-01-08', '2016-03-25', '6', 'As luck would have it, on her first day at Holbein Entertainment Co., Miki Ishimoto is tasked with managing a brand new idol group! A recent college graduate, Ishimoto is eager to begin her career in the industry. However, her department''s responsibility is...statues?!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Devilman: Crybaby - Digest Eizou', 'ONA', 1, 'Completed', '2018-03-24', NULL, '6', 'A short web recap of the Devilman: Crybaby series, posted on Aniplex''s official YouTube channel.', 781, 'https://cdn.myanimelist.net/images/anime/1046/122722.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiong Bing Lian', 'ONA', 33, 'Completed', '2017-06-01', '2018-04-19', '6', 'Sun Goddess of the Solari, Leona came to Earth in 2014. The genetics of God hidden on Earth has started to awaken. The first few awakenings include the Power of the Galaxy and God of War. An invasion by the alien Tao Tie, just to entertain Death God Karthus, are on the way to Earth.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Karakuri Circus: Makuai - Soshite Mata Kaimaku Bell', 'Special', 1, 'Completed', '2019-01-24', NULL, '6', 'Recap of the first 14 episodes of Karakuri Circus.', 958, 'https://cdn.myanimelist.net/images/anime/1806/98431.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dance with Devils: Fortuna', 'Movie', 1, 'Completed', '2017-11-04', NULL, '6', 'Ritsuka Tachibana. She lives a calm and unchanging life. Ritsuka''s older brother Lindo returns from studying abroad in the United Kingdom. Shikou Academy student council president Rem Kaginuki calls on the girl, and she begins having mysterious encounters with the student council members. Her life changed a little from that day, but Ritsuka expected nothing more. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Hurricane Polymar', 'OVA', 2, 'Completed', '1996-09-21', '1997-02-21', '6', 'Remake of old superhero show of the same name.', 436, 'https://cdn.myanimelist.net/images/anime/1221/142865.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('UFO Senshi Dai Apolon', 'TV', 26, 'Completed', '1976-04-06', '1976-09-28', '6', 'The story is about 16 years old boy Takeshi who recently formed an American football team at the BlueSky orphanage. One day the game is interuppted by a light in the sky. Takeshi discovers he is the son of the king of the planet Apolon, spirited away to Earth by his father''s retainer Rabi to avoid death at the hands of General Dazaan. He turns out to have special energy abilities which can control UFO saucers from under the ocean floor, which in turn can become robots that are synchronized to their movements.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blue: Line Step Brush', 'Special', 1, 'Completed', '2020-02-14', NULL, '6', 'Promotional video for Amgakuin (AMG), a school for artists who want to become active in the entertainment industry. This PV is directed by Kengo Saitou and produced for the institute''s 25th anniversary. All key figures to this animation are alumni from AMG and are now successfully working in the anime industry. The theme song is "Ikiru" by the band UNDER GRAPH.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aitsu to Lullaby: Suiyobi no Cinderella', 'Movie', 1, 'Completed', '1987-08-01', NULL, '6', 'On a Wednesday morning, Kenji goes touring to Hakone pass with his girlfriend Tomomi. There, he sees other riders waiting for something and stops his bike. One of the riders, Hayase Junichi, explains to him that a legendary female driver nicknamed Wednesday Cinderella passes this place every Wednesday in her white Porsche. Kenji becomes interested in this mysterious driver; however, racing with her proves more dangerous than it first seems to be.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gall Force: The Revolution', 'OVA', 4, 'Completed', '1996-10-02', '1997-03-21', '6', 'East Force meets West Force and all Hell breaks loose. The Solonoids, that lovable race of female warriors, are at it again, fighting amongst themselves. During a heated battle, however, it looks like the leaders of the two factions have hung their warriors out to dry. In the middle of all this fighting and chaos, East Force detects a transmission from an unidentified planet. The Gall Force gals leave their posts to go. Lufy, the West Force''s Ace Pilot, who is after Rabby, follows them to the planet.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Akai Kiba: Blue Sonnet', 'OVA', 5, 'Completed', '1989-07-16', '1990-06-25', '6', 'Sonnet is a cyborg/esper from a harsh background and now trained to be the ultimate warrior and most powerful weapon in the world. She is sent to Japan to watch Komatsuzaki Lan, who is thought to be controlled by the rage of the esper Akai Kiba (Crimson Fang). Lan is a quiet girl who knows she''s different from everybody else and starts to show signs of Crimson Fang after coming into contact with Sonnet. In the course of fighting with Lan, Sonnet starts to rediscover her humanity. At the same time Lan has to fight to retain her humanity and control the Crimson Fang.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gudetama: Muhou Chitai de Jiyuu mo Fujiyuu', 'ONA', 18, 'Completed', '2021-01-21', '2021-09-30', '6', 'Web shorts focusing on the Sanrio character Gudetama.', 329, 'https://cdn.myanimelist.net/images/anime/1141/119570.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Garugaku. II: Lucky Stars', 'TV', 50, 'Completed', '2022-01-10', '2022-03-18', '6', 'Sequel of Gal-gaku.: Hijiri Girls Square Gakuin, featuring Lucky2 as the cast.', 621, 'https://cdn.myanimelist.net/images/anime/1225/120623.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bremen 4: Jigoku no Naka no Tenshi-tachi', 'Special', 1, 'Completed', '1981-08-23', NULL, '6', 'TV anime created as a part of "24-Hour Television". Since 1978, Japanese TV network NTV has been doing charity event "24-Hour Television" every summer. Tezuka Production created anime specials for the event under the supervision of Osamu Tezuka. "Bremen 4: Jigoku no Naka no Tenshi-tachi" was produced for the 1981 event. Its title means "Bremen 4: Angels in Hell" in English.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyouryuu Tankentai Born Free', 'TV', 25, 'Completed', '1976-10-01', '1977-03-25', '6', 'When a meteor crashes to Earth, it briefly changes the climate and dinosaurs once again roam the planet. It''s up to a newly formed expedition team to relocate the dinosaurs to a safe environment.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yoroiden Samurai Troopers Message', 'OVA', 5, 'Completed', '1991-03-21', '1991-08-23', '6', 'A 300-year-old book is discovered which chronicles the adventures of the legendary Samurai Troopers… centuries before they happen! But what does this mean? Are the Troopers merely puppets in some cosmic play, acting out parts? 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bucchigiri', 'OVA', 4, 'Completed', '1989-10-27', '1991-03-25', '6', 'To all his schoolmates, Jin comes across as a hot-headed class clown from typically barging in late and sleeping the whole way through to always responding to any situation with reckless stupidity. The fact that he used to be the charismatic leader of a legendary biker gang has turned into an urban legend; however, after starting a rivalry with the captain of the school baseball team, he and two former members, become their star players. But it''s not long before his past catches up to him...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Goddamn', 'OVA', 2, 'Completed', '1990-04-27', '1990-08-16', '6', 'Car racing anime, based on the manga by Kaoru Shintani that serialised in Big Comic Superior from 1988 to 1990.', 950, 'https://cdn.myanimelist.net/images/anime/1499/112278.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Naniwa Yuukyouden', 'OVA', 1, 'Completed', '1992-03-13', NULL, '6', 'Taido Kaimon is the leader of the Kinshu Group ganster syndicate in Kansai region. His gang is a cluster of wisecracking madmen, eternally running into trouble with the law, each other, and the local girls who give as good as they get.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Akuyaku Reijou Tensei Ojisan Mini', 'ONA', 13, 'Completed', '2025-01-07', '2025-03-31', '6', '', 39, 'https://cdn.myanimelist.net/images/anime/1108/148086.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ochibi-san Tanpen Movie', 'ONA', 2, 'Completed', '2019-07-05', '2021-06-16', '6', 'Short videos to commemorate the releases of volumes 9 and 10 of Ochibi-san.', 477, 'https://cdn.myanimelist.net/images/anime/1560/139009.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shinkai no Kantai: Submarine 707', 'OVA', 1, 'Completed', '1997-01-10', NULL, '5', 'A mysterious object attacks and destroys any ship or submarine. Submarine 707 has the mission to search for that mysterious object, when summoned by a whale to follow it. The whale leads them to the world of Mu. But on their way they meet the mysterious object. They find out , it is Commander Red Silver, who had attacked the world of Mu to get Mu''s magma sources. Submarine takes up the battle to defeat Red Silver and save Mu, and the world for that matter. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuugen Kaisha: Jiken File 00 - Hajimari wa Ayashiku mo Hanayaka ni', 'Special', 1, 'Completed', '1994-07-25', NULL, '5', 'Prologue episode. The first half features main characters in their chibi forms introducing each other and explaining the premise of the show. The second half features footage of seiyuus working, talking about the show and doing some funny stuff.', 538, 'https://cdn.myanimelist.net/images/anime/10/87489.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Princess Minerva', 'OVA', 1, 'Completed', '1995-05-01', NULL, '5', 'Princess Minerva enters a tournament that offers the winner a fortune. But when her bodyguard gets kidnapped by an evil sorceress, things really start to heat up.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dennou Sentai Voogie''s★Angel', 'OVA', 3, 'Completed', '1997-07-24', '1998-07-24', '5', 'A hundred years after Earth is invaded by aliens, the last remnants of the human race dwell in underwater "Aqua Bases." A team of five cybernetically enhanced women is trained for the purpose of carrying out guerilla attacks against the occupying forces. Earth''s last hope for salvation is...Voogie''s Angels.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Houkago no Tinker Bell', 'OVA', 1, 'Completed', '1992-07-22', NULL, '5', 'Based on a story from the After School Series line of light novels.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Be-Boy Kidnapp''n Idol', 'OVA', 1, 'Completed', '1989-12-22', NULL, '5', 'Despite Kazuya Shinohara becoming an explosively popular idol, his relationship with his classmate Akihiko Kudo remains much the same. The duo eat meals together and Akihiko provides Kazuya with much-needed respite from his busy performance schedule. However, when a villainous entertainment agency attempts to forcibly recruit Kazuya, Akihiko must rethink what Kazuya means to him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jikuu Ihoujin Kyoko: Chocola ni Omakase!', 'OVA', 1, 'Completed', '2001-08-02', NULL, '5', 'Preparing a party for her anniversary with the King, when he failed to show up Chocola decided to run away from the castle.', 1047, 'https://cdn.myanimelist.net/images/anime/1/1613.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dallos Special', 'OVA', 1, 'Completed', '1985-05-08', NULL, '5', 'An edited compendium of the four OVAs were spliced together to create a movie which aired in theaters. Included within the was also a prologue, which used 50 extra shots that introduced the world of Dallos before the opening credits.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Futsal Boys!!!!!', 'TV', 12, 'Completed', '2022-01-09', '2022-03-27', '5', 'Haru Yamato was never interested in futsal ever since the sport gained international fame 10 years ago. However, a chance to watch Japanese futsal player Tokinari Tennoji compete at the U-18 World Cup completely changed his perspective. When given the opportunity on his first day at Koyo Gakuen High School, Haru enthusiastically joins the futsal club.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Shinka no Mi Gekijou', 'ONA', 15, 'Completed', '2022-11-04', '2023-04-01', '5', 'Shin Shinka no Mi: Shiranai Uchi ni Kachigumi Jinsei shorts streamed on the official YouTube channel prior to the series'' premiere.', 39, 'https://cdn.myanimelist.net/images/anime/1839/130989.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('C Danchi', 'TV', 4, 'Completed', '2022-10-02', '2022-10-23', '5', '"Housing Complex C" centers around Kimi, who lives in a small, low-cost housing complex located in the seaside town of Kurosaki. Trouble seems to follow her wherever she goes, and horrific incidents begin to occur. Is an ancient evil stalking the residents of Housing Complex C? 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ai Mai! Moe Can Change!', 'OVA', 1, 'Completed', '2012-05-25', NULL, '5', 'The OVA adaptation Moe Can Change! is created by Frontier Works, based on a free-to-play game developed by Ambition for mobile phones. The original "playful bishoujo Miroid-raising / clothes-changing moe game" has the player joining a beta test program for androids, who the player must raise and dress up as girls.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tokimeki Restaurant☆☆☆ MIRACLE6 Movie', 'Movie', 1, 'Completed', '2018-02-10', NULL, '5', '', 704, 'https://cdn.myanimelist.net/images/anime/8/88601.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mori no Kokoro-Koro', 'Special', 1, 'Completed', '2005-01-01', NULL, '5', 'An animated commercial for Aska Corporation Inc., an additive-free cosmetics and health food company. The commercial features their Kokoro-Koro mascot, a forest spirit, embodying the innocent heart of mankind.', 1050, 'https://cdn.myanimelist.net/images/anime/1818/90865.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Guang Yu Shi', 'ONA', 1, 'Completed', '2019-09-11', NULL, '5', 'A cosmic darkness threatens to overcome three former teammates who were thought to have perished.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chen Feng Gui', 'ONA', 1, 'Completed', '2020-07-24', NULL, '5', 'Not forgiven. Not forgotten. See the story of brothers torn asunder.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yun Zhongju San Zi', 'ONA', 26, 'Completed', '2024-01-17', '2024-05-29', '5', 'In an ancient world where gods, demons, and mortals coexisted, the immortal Chang''er and his apprentice Xiao Liang lived in seclusion in the Floating Light Cave. Their peaceful life was shattered by the pursuing demon king Dapeng. The timid Xiao Liang was forced to team up with the clever and cunning scholar Jiang Cheng and the resolute and stubborn monk Chongming, embarking on a journey to find the legendary immortal''s abode, Cloud Dwelling. Along the way, the three would face numerous hardships, experience heart-fluttering romance, and endure trials of friendship and life-or-death situations. Meanwhile, a grand conspiracy involving forces from all three realms was unfolding around them.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Monster Strike Anime: Masamune - Shimei no Akaki Yaiba', 'ONA', 2, 'Completed', '2023-12-29', '2023-12-30', '5', '', 1125, 'https://cdn.myanimelist.net/images/anime/1661/140989.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sakuretsu! Amabie-hime. Season 3', 'TV', 12, 'Completed', '2024-01-14', '2024-03-31', '5', 'The third season of Sakuretsu! Amabie-hime.', 154, 'https://cdn.myanimelist.net/images/anime/1621/141030.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Muupon 2nd Season', 'TV', 22, 'Completed', '2000-04-01', '2000-08-25', '5', '', 298, 'https://cdn.myanimelist.net/images/anime/1059/140896.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Muupon', 'TV', 52, 'Completed', '1999-04-03', '2000-03-25', '5', '', 298, 'https://cdn.myanimelist.net/images/anime/1696/140895.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The Fable', 'TV', 25, 'Completed', '2024-04-07', '2024-09-29', '8', 'Fable, an assassin who works in organized crime, has been raised to the legendary status of a ruthless killer capable of murdering any man within six seconds. Six years after his debut, his boss fears that Fable has started to attract too much attention from the legal authorities, and he orders him to hide in Osaka for a year. Accompanied by his driver who assumes the identity of his sister, Fable is bound by a special condition: he must act as a civilian and not murder anyone lest he and his partner lose their lives.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toaru Kagaku no Railgun T', 'TV', 25, 'Completed', '2020-01-10', '2020-09-25', '8', 'The Daihasei Festival has begun, and that of course means that Tokiwadai Middle School—a prestigious all-girls'' middle school—is competing too. Despite the participation of the "Ace of Tokiwadai," Mikoto Misaka, the other students who are participating are still putting their utmost effort into winning, no matter how impossible the feat may seem against her overwhelming might.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Noragami Aragoto', 'TV', 13, 'Completed', '2015-10-03', '2015-12-26', '8', 'Yato and Yukine have finally mended their relationship as god and Regalia. As a minor and unknown deity, Yato continues to take odd jobs for five yen apiece in hopes of one day having millions of worshippers and his own grand shrine. He has yet to fix Hiyori Iki''s loose soul, but she cheerily prepares for high school nonetheless.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Princess Tutu', 'TV', 38, 'Completed', '2002-08-16', '2003-05-23', '8', 'In a fairy tale come to life, the clumsy, sweet, and gentle Ahiru seems like an unlikely protagonist. In reality, Ahiru is just as magical as the talking cats and crocodiles that inhabit her town—for Ahiru really is a duck! Transformed by the mysterious Drosselmeyer into a human girl, Ahiru soon learns the reason for her existence. Using her magical egg-shaped pendant, Ahiru can transform into Princess Tutu—a beautiful and talented ballet dancer whose dances relieve people of the turmoil in their hearts. With her newfound ability, Ahiru accepts the challenge of collecting the lost shards of her prince''s heart, for long ago he had shattered it in order to seal an evil raven away for all eternity.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Black Clover', 'TV', 170, 'Completed', '2017-10-03', '2021-03-30', '8', 'Asta and Yuno were abandoned at the same church on the same day. Raised together as children, they came to know of the "Wizard King"—a title given to the strongest mage in the kingdom—and promised that they would compete against each other for the position of the next Wizard King. However, as they grew up, the stark difference between them became evident. While Yuno is able to wield magic with amazing power and control, Asta cannot use magic at all and desperately tries to awaken his powers by training physically.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sono Bisque Doll wa Koi wo Suru', 'TV', 12, 'Completed', '2022-01-09', '2022-03-27', '8', 'High school student Wakana Gojou spends his days perfecting the art of making hina dolls, hoping to eventually reach his grandfather''s level of expertise. While his fellow teenagers busy themselves with pop culture, Gojou finds bliss in sewing clothes for his dolls. Nonetheless, he goes to great lengths to keep his unique hobby a secret, as he believes that he would be ridiculed were it revealed. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shinigami Bocchan to Kuro Maid 3rd Season', 'TV', 12, 'Completed', '2024-04-07', '2024-06-23', '8', 'Although everything the young duke touches perishes, his existence is far from lonely. His spirited siblings Viola and Walter, loyal butler Rob, and the eccentric witches Cuff and Zain are regularly livening up his secluded mansion. But it is the duke''s flirty maid, Alice Lendrott, who fills him with the promise of a beautiful tomorrow and the determination to break this hellish spell cast upon him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Horimiya: Piece', 'TV', 13, 'Completed', '2023-07-01', '2023-09-23', '8', 'As the graduation ceremony at Katagiri High School comes to an end, Kyouko Hori, her boyfriend Izumi Miyamura, and their friends begin to look back on their time as students. The moments they shared together may be fleeting, but each one is a colorful piece of their precious memories.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shen Yin Wangzuo', 'ONA', 26, 'Completed', '2022-04-28', '2022-09-29', '8', 'Six thousand years ago, mankind''s glorious reign ended as a result of an invasion of the demon race, brought about by the emergence of 72 demon gods. To safeguard the remnants of humanity, the Alliance of Temples appeared to stop the demons'' progress and temporarily stabilize the situation.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Major: Message', 'OVA', 1, 'Completed', '2010-12-17', NULL, '8', 'Thirteen years after achieving major success with the Indiana Hornets, Gorou Honda''s career as a pitcher ended abruptly after sustaining a horrible injury. Inspired by his father, who continued playing baseball despite major setbacks, Gorou plans to restart his baseball career and play in a new position. However, his strong dedication to train has puzzled his family, especially his young daughter Izumi, who is frustrated with the absence of her father from her lives. Faced by another tough obstacle, Gorou once again decides to prove his resolve through his beloved sport.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Working!!! Lord of the Takanashi', 'Special', 1, 'Completed', '2016-03-30', NULL, '8', 'The light-hearted Working!! franchise comes to a close in this final episode of the concluding season. Will Aoi Yamada get the closure she so desperately needs with her distant mother? Will the relationship between Yachiyo Todoroki and Jun Satou continue to remain stagnant and awkward? Perhaps even Souta Takanashi and Mahiru Inami will take a step forward in deepening their eccentric friendship. And in the end, Wagnaria Restaurant might finally get a new chief!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('IDOLiSH7 Second Beat!', 'TV', 15, 'Completed', '2020-04-05', '2020-12-27', '8', 'Following their performance at the Black or White event, the idol group IDOLiSH7 is at the height of its popularity, with offers for various concerts and work coming in every day, much to the joy of the seven boys and their manager. However, as their fame continues to rise, Riku Nanase''s health begins worsening due to the heavy workload.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyoukai no Kanata Movie 2: I''ll Be Here - Mirai-hen', 'Movie', 1, 'Completed', '2015-04-25', NULL, '8', 'After Akihito Kanbara reunites with Mirai Kuriyama—whom he believed had vanished after defeating Beyond the Boundary—he discovers a heartbreaking fact: Mirai has lost all memory of him, their friends, and her past as a Spirit Warrior. Akihito is utterly devastated, but realizes that she has a unique opportunity. Mirai can finally live the life of a normal girl—where she''ll be completely devoid of the supernatural society that both shunned and used her. While it''s all for the sake of Mirai''s happiness, the price is costly—Akihito and his friends must keep her true origins a secret from her, and as a result avoid befriending her. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam: The Origin - Zenya Akai Suisei', 'TV', 13, 'Completed', '2019-04-29', '2019-08-12', '8', 'What was the tragedy that decided the fates of Char Aznable, the man later nicknamed the "Red Comet" as an ace pilot of the Zeon forces, and his sister Sayla Mass?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eizouken ni wa Te wo Dasu na!', 'TV', 12, 'Completed', '2020-01-06', '2020-03-23', '8', 'Midori Asakusa sees the world a bit differently. Always having her nose in a sketchbook, Asakusa draws detailed landscapes and backgrounds of both the world around her and the one within her boundless imagination. Even the simple act of doodling on a wall evolves into an emergency repair on the outer hull of her spaceship. She is only brought back to reality by her best friend Sayaka Kanamori. The pair are stark opposites, with Asakusa''s childlike wonder contrasted by Kanamori''s calculated approach to life. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nodame Cantabile: Paris-hen', 'TV', 11, 'Completed', '2008-10-10', '2008-12-19', '8', 'Shinichi Chiaki conquers his fear of flying, and Megumi "Nodame" Noda''s exceptional performance at a piano competition earns her an invitation to study at the prestigious Conservatoire de Paris. The pair go to Paris together to take the next step in their careers: Chiaki as a new rising conductor under the wing of the great maestro Franz von Stresemann, and Nodame as a pupil of the esteemed piano professor Charles Auclair.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga Eiyuu Densetsu Gaiden', 'OVA', 24, 'Completed', '1998-02-09', '1998-09-26', '8', 'Ginga Eiyuu Densetsu Gaiden is the first of two OVA adaptations of side stories from the Ginga Eiyuu Densetsu novel series. This first adaptation follows the achievements of Reinhard von Müsel and Siegfried Kircheis of the Galactic Empire before the fateful Battle of Astarte.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaze Tachinu', 'Movie', 1, 'Completed', '2013-07-20', NULL, '8', 'Although Jirou Horikoshi''s nearsightedness prevents him from ever becoming a pilot, he leaves his hometown to study aeronautical engineering at Tokyo Imperial University for one simple purpose: to design and build planes just like his hero, Italian aircraft pioneer Giovanni Battista Caproni. His arrival in the capital coincides with the Great Kanto Earthquake of 1923, during which he saves a maid serving the family of a young girl named Naoko Satomi; this disastrous event marks the beginning of over two decades of social unrest and malaise leading up to Japan''s eventual surrender in World War II.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaiba', 'TV', 12, 'Completed', '2008-04-11', '2008-07-25', '8', 'In a world where memories exist in memory chips separate from the body, death of the body no longer means death of the soul. It is possible for memories to be viewed, altered, and transferred between bodies. These memory chips are used by the rich to obtain eternal lives in carefully selected bodies, while for the poor, selling their own bodies and conserving their souls in the chips often become the only way to earn a living. An electrolytic cloud in the sky serves as a barrier between the heavens of the fortunate and the underworld of the destitute, making this social division impregnable. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eiga Daisuki Pompo-san', 'Movie', 1, 'Completed', '2021-06-04', NULL, '8', 'Joelle Davidovich Pomponette, better known as simply "Pompo," is an extremely talented movie producer, having inherited her grandfather''s connections and cinematic eye. Despite her promising outlook, Pompo refuses to produce anything other than trashy B-movies. That is, until she hands her assistant, Gene Fini, a script for an ambitious screenplay about the life of a composer and announces that he has earned his first directorial credit.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Interstella5555: The 5tory of The 5ecret 5tar 5ystem', 'Movie', 1, 'Completed', '2003-12-01', NULL, '8', 'This musical film is the visual realization of "Discovery", an album by Daft Punk. It tells the story of a band of four extraterrestrial musicians who are kidnapped and brought back to Earth by an evil manager. Their only hopes lie with a space pilot from their home planet who, after receiving a distress call broadcasted during the abduction, seeks out to rescue them.', 1030, 'https://cdn.myanimelist.net/images/anime/1618/146985.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Death Parade', 'TV', 12, 'Completed', '2015-01-10', '2015-03-28', '8', 'After death, either Heaven or Hell awaits most humans. But for a select few, death brings them to Quindecim—a bar where only pairs of people who die at the same time can enter. Attending the bar is an enigmatic figure known as Decim, who also acts as the arbiter. He passes judgment on those who wind up at Quindecim by challenging them to a life-threatening game. These games determine if the patron''s soul will reincarnate into a new life, or be sent into the void, never to be seen again.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaguya-sama wa Kokurasetai: Ultra Romantic Teaser PV - Ishigami Yuu wa Kataritai', 'Special', 1, 'Completed', '2021-10-21', NULL, '8', 'Every Thursday, Shuchiin Academy student council secretary Yuu Ishigami can be found in a state of anxiety. He counts down the hours until he can escape to the student council chamber to read the latest chapter of the popular seinen manga series, "Momo Doesn''t Think." Joining Ishigami in his weekly reading, student council president Miyuki Shirogane swiftly grows excited at the news of a third season of the manga''s anime adaptation.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Given: Uragawa no Sonzai', 'OVA', 1, 'Completed', '2021-12-01', NULL, '8', 'Since the night of "given''s" first live performance, the relationship between Mafuyu Satou and Ritsuka Uenoyama has been smooth sailing. Their shared love of music reinforces their bond, and every moment spent together makes them more inseparable. Nevertheless, there will come times when they will suffer setbacks, with both of them consumed by their inner turmoil.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tensei shitara Slime Datta Ken', 'TV', 24, 'Completed', '2018-10-02', '2019-03-19', '8', 'Thirty-seven-year-old Satoru Mikami is a typical corporate worker, who is perfectly content with his monotonous lifestyle in Tokyo, other than failing to nail down a girlfriend even once throughout his life. In the midst of a casual encounter with his colleague, he falls victim to a random assailant on the streets and is stabbed. However, while succumbing to his injuries, a peculiar voice echoes in his mind, and recites a bunch of commands which the dying man cannot make sense of.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tokidoki Bosotto Russia-go de Dereru Tonari no Alya-san', 'TV', 12, 'Completed', '2024-07-03', '2024-09-18', '8', 'Seirei Academy is a prestigious school attended by the very best students in Japan. Alisa Mikhailovna "Alya" Kujou, the half-Russian and half-Japanese treasurer of the school''s student council, is known for her intelligence, stunning looks, and rigid personality. Contrasting her near-flawless persona, Alya''s unmotivated classmate Masachika Kuze slacks off during lessons and seems to show no interest in her.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('BanG Dream! Morfonication', 'Special', 2, 'Completed', '2022-07-28', '2022-07-29', '8', 'Two special episodes featuring a violin rock band, Morfonica.', 756, 'https://cdn.myanimelist.net/images/anime/1411/124237.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yondemasu yo, Azazel-san.', 'OVA', 4, 'Completed', '2010-02-23', '2014-06-23', '8', 'The great detective Akutabe has an assistant, Rinko Sakuma, who is trying to learn to summon demons. This is the story of her misadventure when she actually manages to summon 2 demons unexpectedly. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Air Gear: Kuro no Hane to Nemuri no Mori - Break on the Sky', 'OVA', 3, 'Completed', '2010-11-17', '2011-06-17', '8', 'First episode is based on the 16th volume of the manga. Features Ikki vs. Ringo.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tamayura: More Aggressive', 'TV', 12, 'Completed', '2013-07-03', '2013-09-18', '8', 'The second season of Tamayura: Hitotose.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fairy Tail Movie 2: Dragon Cry', 'Movie', 1, 'Completed', '2017-05-06', NULL, '8', 'Dragon Cry is a magical artifact of deadly power, formed into a staff by the fury and despair of dragons long gone. Now, this power has been stolen from the hands of the Fiore kingdom by the nefarious traitor Zash Caine, who flees with it to the small island nation of Stella. Frightened that the power has fallen into the wrong hands, the King of Fiore hastily sends Fairy Tail to retrieve the staff. But this task proves frightening as a shadowy secret lies in the heart of the kingdom of Stella. Dragon Cry follows their story as they muster up all their strength to recover the stolen staff and save both kingdoms.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yama no Susume Second Season', 'TV', 24, 'Completed', '2014-07-09', '2014-12-24', '8', 'Continuing their treks through the high peaks of Japan, the mountaineering girls are back for more! First-year high school student Aoi Yukimura, a shy girl with a fear of heights, and her wildly energetic friend Hinata Kuraue set out once again to conquer the perils of backyard camping trips, summer homework, and even a climb on the mountain of their dreams. Joined by middle school student Kokona Aoba and their knowledgeable upperclassman Kaede Saitou, the squad members are ready to take on whatever slopes and challenges they might face, no matter how steep. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Majo Minarai wo Sagashite', 'Movie', 1, 'Completed', '2020-11-13', NULL, '8', '27-year-old Tokyo office worker Mire Yoshizuki just returned to Japan, while 22-year-old fourth-year college student Sora Nagase aspires to be a teacher, and 20-year-old boyish Reika Kawatani is a part-time Hiroshima okonomiyaki shop worker and freelancer. What draws together these three women from completely different walks of life is a magic gem. A "New Magical Story" begins when they are mysteriously brought together by chance and embark on a journey.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchuu Senkan Yamato 2205: Aratanaru Tabidachi', 'OVA', 8, 'Completed', '2021-10-08', '2022-02-04', '8', 'Gamilans are facing their biggest hurdle yet: their planet is dying at an alarming pace. To save his people and relocate them to habitable land, Aberdt Desler feigns submission to the oppressive rule of the planet Galman, which houses a race almost identical to the Gamilans. Desler''s true objective is to seize control and accelerate the salvation of his nation. However, as Gamilans begin their migration, an unidentified massive power attacks them and completely warps their twin planet—Iscandar, Queen Starsha''s home.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ore wo Suki nano wa Omae dake ka yo: Oretachi no Game Set', 'OVA', 1, 'Completed', '2020-09-02', NULL, '8', 'The original video anime episode will serve as the final chapter to the television series, focusing on the rivalry between the "the protagonist" Amatsuyu Kisaragi (Jouro) and Yasuo Hazuki (Hose), "the background character."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Heya Camp△: Sauna to Gohan to Sanrin Bike', 'Special', 1, 'Completed', '2020-05-27', NULL, '8', 'Upon returning from school one day, Rin Shima encounters an unfamiliar three-wheeled motorcycle parked outside her house. After asking her father about it, she learns that the vehicle is a temporary loaner while her moped undergoes its annual maintenance.  
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kami no Tou', 'TV', 13, 'Completed', '2020-04-02', '2020-06-25', '8', 'There is a tower that summons chosen people called "Regulars" with the promise of granting their deepest desires. Whether it be wealth, fame, authority, or something that surpasses them all—everything awaits those who reach the top.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Radiant 2nd Season', 'TV', 21, 'Completed', '2019-10-02', '2020-02-26', '8', 'After fleeing from Rumble Town, Seth, Doc and Melie are back at the Artemis Institute. Thanks to Alma, Seth learns more about Piodon, his mysterious brother. But the quest for the Nemeses mythical nest Radiant has already waited too long, so the Horned Boy and his friends head to the island-continent of the Wizard Knights.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kara no Kyoukai Movie 1: Fukan Fuukei', 'Movie', 1, 'Completed', '2007-12-01', NULL, '8', 'A series of eerily similar suicides occupy newspaper headlines in late ''90s Japan. Amidst all the bizarre resemblances, there is one detail that stands out above the rest: the victims have all taken their lives by leaping from the Fujou building, a run-down abandoned structure rising high above the city.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ushio to Tora (TV)', 'TV', 26, 'Completed', '2015-07-03', '2015-12-25', '8', 'Ushio Aotsuki is a stubborn middle school student and son of an eccentric temple priest who goes about life without care for his father''s claims regarding otherworldly monsters known as youkai. However, as he is tending to the temple while his father is away on work, his chores lead him to a shocking discovery: in the basement he finds a menacing youkai impaled by the fabled Beast Spear.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Arakawa Under the Bridge', 'TV', 13, 'Completed', '2010-04-05', '2010-06-28', '8', 'Kou Ichinomiya is the son of a wealthy businessman who holds a firm belief in his elite status. As such, he is determined to avoid becoming indebted to anyone; but one day, after a run-in with some mischievous kids on Arakawa Bridge, he ends up falling into the river running underneath. Luckily for him, a passerby is there to save him—but now, he owes his life to this stranger!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan: Kuro no Soshiki to Taiketsu no Rekishi', 'Special', 1, 'Completed', '2007-12-17', NULL, '8', 'A special episode aired after ep. 490, it summarizes the history of confrontation with the black organization.', 990, 'https://cdn.myanimelist.net/images/anime/1309/121762.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Biao Ren', 'ONA', 15, 'Completed', '2023-06-01', '2023-08-17', '8', 'A extraordinary guard walks in the desert of the Western regions. On the way escaping the killing by the government, he took a guarding task with destination to the capital Chang ''an. The task was thought as just a simple one, but actually it is a road full of crisis and danger. A journey affecting the fate of the world begins......
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Keisatsu Patlabor the Movie', 'Movie', 1, 'Completed', '1989-07-15', NULL, '8', 'The Babylon Project is a massive renovation of Tokyo''s neighborhoods, including the creation of artificial islands in the Bay. Utilizing "Labors," or robots created for the express purpose of doing work, architects and construction crews are able to more efficiently progress development of the overhaul. When a key figure in the Project''s conception is found dead after committing suicide under mysterious circumstances, Captain Kiichi Gotou''s Patlabor police unit is tasked with getting to the bottom of the bizarre situation.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuru Yuri', 'TV', 12, 'Completed', '2011-07-05', '2011-09-20', '8', 'After a year in grade school without her childhood friends, first year student Akari Akaza is finally reunited with second years Yui Funami and Kyouko Toshinou at their all-girls'' middle school. During the duo''s first year, Yui and Kyouko formed the "Amusement Club" which occupies the now nonexistent Tea Club''s room. Shortly after Akari joins, one of her fellow classmates, Chinatsu Yoshikawa, pays the trio a visit under the impression that they are the Tea Club; it is only once the three girls explain that the Tea Club has been disbanded that they can convince Chinatsu to join the Amusement Club—a group with no purpose other than to provide entertainment for its members.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ga-Rei: Zero', 'TV', 12, 'Completed', '2008-10-06', '2008-12-22', '8', 'In Japan, there exists a government agency known as the Supernatural Disaster Countermeasures Division (SDCD), whose duty is to protect the citizens from creatures unseen. They are able to dispatch these monsters swiftly and without alerting the general public. But currently, they face a different challenge: the betrayal of one of their own.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wushen Zhuzai', 'ONA', 720, 'Airing', '2020-03-08', NULL, '8', 'The protagonist Qin Chen, who was originally the top genius in the military domain, was conspired by the people to fall into the death canyon in the forbidden land of the mainland. Qin Chen, who was inevitably dead, unexpectedly triggered the power of the mysterious ancient sword.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zhu Xian', 'ONA', 26, 'Completed', '2022-08-02', '2023-01-17', '8', 'Zhang Xiaofan, who turned into an orphan overnight, becomes a disciple of the Qingyun Sect. After five years of training, he performs well in the Seven Peak Martial Arts Competition. He''s sent to the Kongsang Mountain to defeat the evil. During the journey, he and his senior, Lu Xueqi, met with an accident, and got to know and save the lady of the cult, Bi Yao. At the same time, new danger is ahead of him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Quest: Dai no Daibouken (TV)', 'TV', 46, 'Completed', '1991-10-17', '1992-09-24', '8', 'After the defeat of the demon lord Hadlar all of the monsters were unleashed from his evil will and moved to the island of Delmurin to live in peace. Dai is the only human living on the island. Having been raised by the kindly monster Brass, Dai''s dream is to grow up to be a hero. He gets to become one when Hadlar is resurrected and the previous hero, Avan, comes to train Dai to help in the battle. But Hadlar, announcing that he now works for an even more powerful demon lord, comes to kill Avan. To save his students Avan uses a Self-Sacrifice spell to attack, but is unable to defeat Hadlar. When it seems that Dai and Avan''s other student Pop are doomed a mark appears on Dai''s forehead and he suddenly gains super powers and is able to fend off Hadlar. The two students then go off on a journey to avenge Avan and bring peace back to the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('InuYasha Movie 1: Toki wo Koeru Omoi', 'Movie', 1, 'Completed', '2001-12-22', NULL, '8', 'During their quest in the feudal era to recover the shards of the miraculous Shikon Jewel, Inuyasha, Kagome Higurashi, and their friends become the target of Menoumaru Hyouga—a demon awakened by one of the Shikon fragments, now in pursuit of Inuyasha''s heirloom sword Tessaiga. Following a clash between the fathers of Inuyasha and Menoumaru, the weapon is the only means to restore Menoumaru his rightful family heritage.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jewelpet Twinkle☆: Hohoemi no Niji ni Dokki☆Doki!', 'Special', 1, 'Completed', '2013-07-22', NULL, '7', 'Special episode included with the Blu-ray box set of the original Jewelpet Tinkle anime series.', 871, 'https://cdn.myanimelist.net/images/anime/2/73944.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Senkaiden Houshin Engi', 'TV', 26, 'Completed', '1999-07-03', '1999-12-25', '7', 'Thousands of years ago, it was a time of witchcraft and dark magic. An evil sorceress has bewitched the emperor of the mighty dynasty and he has become a mindless puppet. The country is in shambles, and evil spirits lurk everywhere. The human world is on the verge of utter destruction. A bold mission is planned by the Confederation of the Immortal Masters. They send a young master wizard to hunt down the villains and evil warlocks in the devastated lands.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaiketsu Zorori', 'TV', 52, 'Completed', '2004-02-01', '2005-02-06', '7', 'Adapted from the popular storybooks of the same name by Yutaka Hara, Kaiketsu Zorori follows the adventures of a scheming fox named Zorori, who is determined to become the King of Mischief with his very own castle and beautiful bride.  Although Zorori is notorious for his pranks and tricks, his conniving plots often backfire and end up helping his targets, and despite appearing to be villainous and immoral, he is actually caring and sentimental.  Nevertheless, Zorori has the wits, intelligence, and dexterity to always find a solution out of the most hopeless of situations.  Travelling with a pair of twin boar bandits, Ishishi and Noshishi, he continues on his journey to make his deceased mother proud.', 53, 'https://cdn.myanimelist.net/images/anime/1330/131495.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shakugan no Shana-tan', 'Special', 4, 'Completed', '2006-01-25', '2007-04-04', '7', 'Shana-tan specials bundled with the first and fifth volume pre-orders of the Shakugan no Shana DVD, the limited edition Shakugan no Shana guide book, and the limited edition Shakugan no Shana Movie preview DVD special.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gakuen Utopia Manabi Straight!: Natsu da! Manabi da! Kyouka Gasshuku da!', 'Special', 1, 'Completed', '2007-10-10', NULL, '7', 'This episode takes place before the actual planning of the School Fair and shows how the girls spend their summer holidays.', 1192, 'https://cdn.myanimelist.net/images/anime/8/26354.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shaonian Bai Ma Zui Chunfeng', 'ONA', 20, 'Completed', '2022-07-27', '2023-02-08', '7', 'The story takes place twenty years before Shaonian Ge Xing. Baili Dongjun, who later became the number one in the world, was still the only grandson of Zhenxihou''s mansion who was loved by thousands of people. Although he has a father with peerless kung fu and a mother who is the daughter of the head of the Wen family, he is not good at martial arts and prefers to brew wine. Ten years later, the best wine can be brewed. Finally, he stole a land deed from his home and ran hundreds of miles to Chaisang City to open a wine shop. But a long street is already full of evil stars. Only he is really a young boy who is serious about making wine. Because of this, he was inexplicably involved in the disputes between the two families. On the way, he accidentally met Sikong Changfeng, a vagabond wandering around the rivers and lakes without father and mother, and Lei Mengsha, the son of Zhuo Mo, who rushed from Tianqi City, because they were grateful to each other. He decided to help Lei Mengsha rescue his good brother, Gu Jianmen, the son of Lingyun, who was trapped in his mansion. This is an era in which young talents come forth in large numbers, and no era can surpass it. Xie Xuan, who later became Confucian Sword Immortal, Yan Zhantian, who became Nujian Immortal, and Luo Qingyang, who became Lone Sword Immortal, were all still unknown at this time. They were waiting for the day when they would meet each other and then become famous all over the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nasu: Suitcase no Wataridori', 'OVA', 1, 'Completed', '2007-10-24', NULL, '7', 'Riding off their success in La Vuelta, Pepe Benengeli and the rest of the Pao Pao Beer team prepare to take on a newly established cycling race in Japan. However, when they receive the news that team member Jean-Louis Chochi''s former mentor has died by suicide, their plans are suddenly shrouded in doubt. Struggling with their personal feelings on top of the challenges presented by the new course, the team wonders whether they still have the strength to pedal on.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Digimon Tamers: Bousou Digimon Tokkyuu', 'Movie', 1, 'Completed', '2002-03-02', NULL, '7', 'Locomon, a train digimon, has suddenly appeared in the real world. All the tamers scramble to stop the train before it reaches its final destination: the portal into the Digital world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Street Fighter II V', 'TV', 29, 'Completed', '1995-04-10', '1995-11-27', '7', 'Ryu and Ken Masters are close friends and both are martial artists. In order to become better fighters and learn new techniques, they travel the world and are exposed to many different fighting styles, as well as meeting new people. During their journey, they find themselves caught up in a conspiracy perpetrated by a mysterious organisation called Shadowlaw, both now face their ultimate challenge and must fight for their lives as they combat the evil M. Bison. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece: Kinkyuu Kikaku One Piece Kanzen Kouryakuhou', 'Special', 1, 'Completed', '1999-12-22', NULL, '7', 'This is the first recapitulation episode, covering the first five episodes with only the difference being that the episode follows the manga storyline and begins with Luffy and Shanks at the bar. Also, in the ending, the current Straw Hats have a small conversation about their goals.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Qin Shi Mingyue: Wanli Changcheng', 'TV', 37, 'Completed', '2012-09-30', '2013-01-02', '7', 'The fourth season takes place after the Mechanical City has collapsed and the Mohists are almost eliminated. The Qin Empire plans for a period of peace and prosperity and the Emperor utilizes a huge amount of labor to build the Great Wall and plans more sophisticated programs. There is apprehension in the city about the function of the giant boat "Mirage" which appears off the coast. Various rebel factions came together in Shanghai to defeat the Emperor''s ambition. The Emperor and his forces, including the Quicksand group, the Yin-Yang School, Net Trap Organization and swordsman Shengqi are all arraigned against the rebel group comprising the Mohists, Confucianists and the Taoists. Tianming''s education and training continue as he is faced with more and more challenges as leader of the Mohists. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wan Jie Xian Zong 5th Season', 'ONA', 288, 'Completed', '2021-06-26', '2024-07-01', '7', 'Fifth season of Wan Jie Xian Zong.', 752, 'https://cdn.myanimelist.net/images/anime/1897/116128.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ochame na Futago: Claire Gakuin Monogatari', 'TV', 26, 'Completed', '1991-01-05', '1991-11-02', '7', 'Patricia and Isabel O''Sullivan arrives at the St. Claire, a college for girls, to study and live in the new home. In there place, they meet to Alison, Wella, Catherine and Doris, who live too in the St. Claire, and join with their in the team spirit. All together, the girls play games and fun long time, living in harmony until appears Winfred, a sulky rude and antisocial girl that no will doubt in to create all kind of troubles for the O''Sullivan twins and their friends...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Grander Musashi RV', 'TV', 39, 'Completed', '1998-04-04', '1998-12-26', '7', 'Sequel to Grander Musashi. A young but experienced fisherman named Musashi Kazama and his two friends travel around the world in search of seven mysterious objects of fantastic power called "Legenders", each one in the form of a fish. Legenders are said to grant anyone who catches them the power to change the world. Unfortunately, Musashi ends up competing with several other fishermen who share his ambition of capturing a Legender. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Devilman: Youchou Sirene-hen', 'OVA', 1, 'Completed', '1990-02-25', NULL, '7', 'After Akira Fudou fused with the demon Amon to become the being known as Devilman, he has struggled with striking a balance between his human heart and his new violent tendencies. However, as other demons become aware of him and wreak havoc on the lives of those he cares about, Akira has little choice but to fight them tooth and nail. As he fights Jinmen, a turtlelike demon with living human faces embedded in his shell; and Sirene, a fearsome winged demon, Akira must use every scrap of his strength if he is going to stay alive.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Danball Senki W', 'TV', 58, 'Completed', '2012-01-18', '2013-03-20', '7', 'One year after the fight with the Innovators, a new terrorist organization called the Detectors threatens the world using LBXs. Ban joins up with new and old friends to stop the Detectors.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Iria: Zeiram The Animation', 'OVA', 6, 'Completed', '1994-06-23', '1994-11-21', '7', 'Iria is the story of a girl and the Alien being she loves to hate. The series begins with her brother, Gren, taking a job. He is a bounty hunter, and one well known for his incredible skill. Iria, being a skilled apprentice bounty hunter herself, tags along. What is the job, one might ask. It is to find out what has happened to the crew and cargo of a Space Station. Needless to say, nothing is as it seems, and the war between Iria and Zeiram begins in earnest.', 92, 'https://cdn.myanimelist.net/images/anime/1193/112905.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rockman.EXE Stream', 'TV', 51, 'Completed', '2004-10-02', '2005-09-24', '7', 'A comet burns in the sky, its brilliant light shining down upon the people of Earth. At that time, a giant army of viruses invade the real world, crushing everything in their path. Netto and Enzan use cross fusion to intervene, but are whisked away to an unknown location, only to be confronted by the one responsible for the attack - Duo! 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Escaflowne', 'Movie', 1, 'Completed', '2000-06-24', NULL, '7', 'Hitomi Kanzaki is in a very depressed mood. She only wants to sleep and fade away. Her misery summons Lord Folken who sends her to Gaea. The people of Gaea think she is the Wing Goddess, who can call upon the legendary Dragon Armor called Escaflowne. On Gaea, King Van, the sole survior of the White Dragon Clan, is also in a depressed state. Swearing an oath to get his revenge on the Black Dragon Clan that obliterated Van''s kingdom, he lives by the sword. Now that the Wing Goddess has finally appeared, she posseses Gaea''s world fate in her heart. Escaflowne will either lead Gaea to peace or total ruin.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sasameki Koto', 'TV', 13, 'Completed', '2009-10-08', '2009-12-31', '7', 'Murasame Sumika is popular in the high school for her excellence in the marks and sports. However, she has a secret: she is in love with her classmate Kazama Ushio. Ushio also has a liking to the love between girls, but she hasn''t noticed Sumika''s feelings and has always been refused by other girls.', 25, 'https://cdn.myanimelist.net/images/anime/9/75225.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Manie-Manie: Meikyuu Monogatari', 'Movie', 3, 'Completed', '1987-09-25', NULL, '7', 'Manie-Manie: Meikyuu Monogatari is an anthology film composed of three short films by acclaimed directors Rintaro, Yoshiaki Kawajiri, and Katsuhiro Otomo.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Urusei Yatsura Movie 1: Only You', 'Movie', 1, 'Completed', '1983-02-13', NULL, '7', 'Lum doesn''t need much assistance going ballistic when everyone in Tomobiki gets an invitation to Ataru''s wedding -- and she''s not listed as the bride! It seems that some 11 years ago, Ataru played "Shadow Tag" with a young girl named Elle and won. Unfortunately, Elle was yet another Alien Princess; and on her planet, if a boy steps on a girl''s shadow, they have to marry. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meiji Tokyo Renka', 'TV', 12, 'Completed', '2019-01-09', '2019-03-27', '7', 'Mei Ayazuki is just your ordinary, everyday high-school girl. That is until one night, when the moon is full and red, she’s transported through time to the Meiji Period by Charlie, a self-proclaimed magician.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nichijou: Original Jikai Yokoku', 'Special', 25, 'Completed', '2011-06-24', '2012-06-29', '7', 'Original next episode trailers included in the Blu-ray and DVD volumes of Nichijou.', 494, 'https://cdn.myanimelist.net/images/anime/2/29848.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Negima!? Haru Special!?', 'OVA', 1, 'Completed', '2006-10-25', NULL, '7', 'Sometime after all the events which took place during Negi''s first year as a teacher, Class 2-A goes on a school trip to a beautiful island for Spring break. Everything is fine now, but troubles continue for Negi, because he''s still the main attraction of the class. But he has something else to worry about, Asuna is angry at him because he told her she had nothing to do with his studies as a wizard. During the trip, the situation gets intense as Asuna''s friends try to help Negi make up with her.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gi(a)rlish Number', 'TV', 12, 'Completed', '2016-10-07', '2016-12-23', '7', 'College student Chitose Karasuma is determined not to do boring things as she enters the adult world. To this end, this bad-mannered beauty barges into a facility that trains would-be voice actors and actresses, somehow landing a job at "Number One Produce," a seiyuu agency managed by her older brother, Gojou. In Chitose''s mind, she''s poised for greatness, but finds herself at a loss when she continues to only get minor roles. As she clashes with other girls in the agency, including a cunning airhead and a girl with a Kansai accent, Chitose is about to learn that there''s more to succeeding in this competitive industry than she imagined.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Double Decker! Doug & Kirill', 'TV', 13, 'Completed', '2018-09-30', '2018-12-23', '7', 'The once peaceful city-state of Lisvalletta has found itself beset by a dangerous new drug called Anthem. The side effects of the drug allow the user to enter a state of Overdrive, wherein they mutate into superpowered beasts with inhuman abilities. With the police powerless to stop this new threat, the responsibility falls upon the Special Crime Investigation Unit SEVEN-O. To offset the dangers of this work, the investigators work under the patented "Double Decker" system, which requires them to team up in "buddy cop" pairs.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kurokami: Tora to Tsubasa', 'Special', 1, 'Completed', '2009-12-22', NULL, '7', 'Half a year after the battle in Okinawa, Excel was looking for a new Mototsumitama to revenge on Reishin. Excel met Mikami and decided to contract with her. Before making the contract, Excel looked back at the encounter with Steiner.', 974, 'https://cdn.myanimelist.net/images/anime/5/23018.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Crayon Shin-chan Gaiden: Kazokuzure Ookami', 'ONA', 13, 'Completed', '2017-02-22', '2017-05-17', '7', 'Master butt-swordsman Hiroshinosuke Nohara (Lone Wolf) travels with his family seeking employment. The family encounters a mysterious girl Hazumi and a wild dog Shiro, and decides to travel together. The group is attacked by various assassins, eventually their lives are threatened by the butt-swordsmen''s enemy, the armpit-swordsmen of the Demon Bull Clan. Who will win: butts or armpits? Against an array of idiosyncratic enemies, Hiroshinosuke Nohara and his son Shinnosuke have the chance to display their swashbuckling skills.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Quest: Your Story', 'Movie', 1, 'Completed', '2019-08-02', NULL, '7', 'Following in his father''s footsteps, Luca must find the hero who wields the zenithian sword to save his mother from Ladja. Based on Dragon Quest V: Hand of the Heavenly Bride game''s story.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nobunaga no Shinobi: Nobunaga to Minarai Shinobi', 'Special', 1, 'Completed', '2016-03-25', NULL, '7', 'Oda Nobunaga saves a girl from drowning one day. She clumsily tells him that she''s a shinobi. Instead of attempting to kill him, she swears to serve him one day after hearing his plans to unify Japan.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mokke Specials', 'Special', 2, 'Completed', '2008-01-25', '2008-05-23', '7', 'Mokke Special Episodes:
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koufuku Graffiti', 'TV', 12, 'Completed', '2015-01-09', '2015-03-27', '7', 'The path to becoming a fine wife begins with being an accomplished cook—at least, that is what Ryou Machiko''s late grandmother had led her to believe. For a middle schooler, Ryou''s cooking skills are incomparable; but recently, though Ryou''s food looks appetizing and smells inviting, the taste has not been delicious. Just when the dejected art student comes to terms with the possibility that she might continue living alone for the rest of her life, her aunt tells her that Kirin Morino—Ryou''s second cousin—will begin staying with her every weekend since the younger girl has joined a cram school in Tokyo and aims to attend the same school as Ryou.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Porphy no Nagai Tabi', 'TV', 52, 'Completed', '2008-01-06', '2008-12-28', '7', 'Porfy, his younger sister Mina, and their parents live a humble but happy life in the Grecian countryside. They''ve just started running a gas station, much to Porphy''s joy, and it seems like only good things are in store for their future. However, a huge earthquake changes all that, leaving Porfy without a home or a family -- sans Mina, who seems to have disappeared in the commotion. Now, Porfy is determined to find his sister and be able to live together happily again.', 607, 'https://cdn.myanimelist.net/images/anime/11/5585.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('City Hunter: Ryou no Propose', 'OVA', 1, 'Completed', '2016-05-01', NULL, '7', 'A scan of the upcoming issue of Monthly Comic Zenon magazine, revealed that City Hunter will be receiving a new OVA adaptation. It will be bundled with the release of the new version of the manga, City Hunter XYZ Edition, on July 18. This announcement was made to commemorate the 30th anniversary of City Hunter. The OVA will promote the new animation and cast members.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Isshuukan Friends. Tomodachi to no Omoide', 'Special', 1, 'Completed', '2014-10-15', NULL, '7', 'Recap episode voiced over by Kaori and Saki, who talk about the developments in the show.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Strait Jacket', 'OVA', 3, 'Completed', '2007-11-26', '2008-04-28', '7', 'It is the world where magic and science coexist. Rayotte Steinberg, a lone wolf "tactical sorcerist", fights against monsters. They used to be human beings, but they had overused forbidden power, "magic", to turn into monsters. What he wears is "mold", the straight jacket that keeps him being a human. What he holds on his hand is "staff", a magical wand that explodes everything. If he casts magic, he moves one step to be a monster. If he doesn''t, he will be killed. Among the harsh battles, he will face a sin he had committed in the past. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kamisama ni Natta Hi', 'TV', 12, 'Completed', '2020-10-11', '2020-12-27', '7', 'Dressed in a conspicuous outfit and armed with an eccentric spirit, Hina Satou goes around insisting that she is the Asgardian god "Odin." When she crosses paths with a boy named Youta Narukami, she uses her precognition abilities to warn him about an impending catastrophe threatening the end of the world. But being a teenager preoccupied with his problems, Youta finds it hard to believe such a preposterous claim.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ookami Shoujo to Kuro Ouji Recap', 'Special', 1, 'Completed', '2014-12-28', NULL, '7', 'Recap of Ookami Shoujo to Kuro Ouji TV series.', 999, 'https://cdn.myanimelist.net/images/anime/9/78439.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yaoguai Mingdan', 'ONA', 18, 'Completed', '2014-12-13', '2015-09-11', '7', 'A foxy temptress. A strange misty tree demon. A girl with the power of the goddess Xianjia! Being caught between these women is a feat in it of itself, but our hero Feng Xi must fight in order to protect the peace and save the world!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gakusen Toshi Asterisk', 'TV', 12, 'Completed', '2015-10-03', '2015-12-19', '7', 'In the previous century, an unprecedented disaster known as the Invertia drastically reformed the world. The powers of existing nations declined significantly, paving the way for a conglomerate called the Integrated Empire Foundation to assume control. But more importantly, the Invertia led to the emergence of a new species of humans who are born with phenomenal physical capabilities—the Genestella. Its elite are hand-picked across the globe to attend the top six schools, and they duel amongst themselves in entertainment battles called Festas.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon Movie 09: Pokemon Ranger to Umi no Ouji Manaphy', 'Movie', 1, 'Completed', '2006-07-15', NULL, '7', 'Satoshi and his friends get lost in an unknown wasteland.  They eventually come across a "Water Pokemon Show" performed by the star of the Mariner Troupe, Hiromi.  Hiromi is a descendant of the troupe of Water People able to communicate with water pokemon, and she tells our heroes the legend that''s been passed down by her people for generations.   According to legend, a temple the Water People built called "The Water Temple Akuusha" rests somewhere in the ocean, and a treasure called "The Water Crown" is hidden there.  It''s said that no one has ever seen this treasure, but that changes when a Pokemon Ranger named Jack Walker (aka Jackie) appears to chase aftert it.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fate/kaleid liner Prisma☆Illya 2wei! Specials', 'Special', 5, 'Completed', '2014-09-26', '2015-01-30', '7', 'Short specials included with the Blu-ray/DVD releases of the TV series.', 761, 'https://cdn.myanimelist.net/images/anime/11/64197.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Grappler Baki', 'OVA', 1, 'Completed', '1994-08-21', NULL, '7', 'Doppo Orochi sits down to watch the final match of his karate school''s youth tournament. Atsushi Suedou, one of his disciples, faces off against Baki Hanma, a fresh teenage boy breezing through the matches. Intrigued by the boy''s strength, Doppo, alongside another of his disciples—Kiyosumi Katou— visits the notorious Tokugawa underground ring—a hidden freestyle fighting arena that prohibits only weaponry in its matches. Upon arriving, they learn that Baki is set to face none other than Koushou Shinogi: an infamous karate master and user of the lethal Cord-Cutting technique.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ged Senki', 'Movie', 1, 'Completed', '2006-07-29', NULL, '7', 'Calamities are plaguing the land of Earthsea and dragons have been seen fighting above the clouds—something which has never happened before. Sparrowhawk, a powerful Archmage, sets out to uncover the mystery behind these concerning events and meets Prince Arren along the way. Arren is the fugitive heir to the Kingdom of Enlad and a seemingly quiet and distressed lad. Wandering aimlessly in an attempt to escape the dark presence haunting him, he decides to tag along Sparrowhawk on his journey.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fantascope: Tylostoma', 'OVA', 1, 'Completed', '2006-08-01', NULL, '7', 'A man who appears every 700 years.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hakaima Sadamitsu', 'TV', 10, 'Completed', '2001-01-17', '2001-03-21', '7', 'Tsubaki Sadamitsu is a young delinquent and the leader of the Corpse Gang, who after a chance encounter with an alien robot is forced to take up the task of capturing intergalactic criminals named Exiled Ones. His job is made harder with the appearance of the Vulture, a last-ditch effort to keep the Exiled Ones under control.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('To Heart 2 AD', 'OVA', 2, 'Completed', '2008-03-26', '2008-08-08', '7', 'Based on the Visual Novel ToHeart 2 AD (Another Days), the sequel to ToHeart 2.', 169, 'https://cdn.myanimelist.net/images/anime/3/75476.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aoi Blink', 'TV', 39, 'Completed', '1989-04-07', '1990-03-16', '7', 'Story of a young boy named Kakeru and his adventures together with a magical blue pony named Blink.', 1021, 'https://cdn.myanimelist.net/images/anime/1272/147717.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Weiß Kreuz OVA', 'OVA', 2, 'Completed', '1999-11-25', '2000-02-23', '7', 'Someone out there is determined to see the fall of Weiss Kreuz, and it looks like they have found the perfect plan for it. The four assassins find themselves trapped in a deadly game of deceit, where the question of honor versus duty comes to surface. Now they must fight for their own reasons to survive--and there can be only be one victor in this field of death.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kamisama Minarai: Himitsu no Cocotama Movie - Kiseki wo Okose♪ Tepple to Dokidoki Cocotama-kai', 'Movie', 1, 'Completed', '2017-04-28', NULL, '6', 'Kokoro''s school is teaming up with another to form a bazaar so they can sell/re-home gently used items everyone no longer uses around their homes. On her way from from school Tama Elder tells her that she and her Cocotama friends won a trip to the Cocotama World. Here they see how full fledged Cocotama gods work. Elder Tama asks for Kokoro''s help in helping humans realize the value of their items instead of so easily tossing them away. But Tepple had snuck into the Cocotama world with the others and taken a key acorn which unlocks the Happy Tree that contains Happy Stars, the source of magic for their world. Elder Tama found out it was missing and the Cocotama gang try to track it down. He says that mushrooms are appearing on tossed away items that as they are born from the feelings of sadness, and they emit a negative energy that effects both humans and Cocotama. Cocotama can get rid of them but not without the acorn and not at the speed humans are currently discarding items at.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oishi-sa Hajikeru! One Piece', 'Special', 1, 'Completed', '2016-09-11', NULL, '6', 'A collaboration between Fanta and One Piece. The first episode features Luffy and Chopper rapping with Fanta Grape and Fanta Orange respectively in hand.', 1030, 'https://cdn.myanimelist.net/images/anime/12/82171.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Trickster: Edogawa Ranpo "Shounen Tanteidan" yori', 'TV', 24, 'Completed', '2016-10-04', '2017-03-28', '6', 'Kogorou Akechi is the founder of a private investigation firm known as the Boy Detectives'' Club. Together, this group takes on cases both great and small. One of their junior members, Kensuke Hanasaki, is out solving a case one day when he happens upon Yoshio Kobayashi, a mysterious amnesiac boy with an inability to die. After seeing his abilities in action, Kensuke offers Yoshio a deal: join the Boy Detectives'' Club and help them solve cases, and in exchange he will find a way to help Yoshio die.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yatogame-chan Kansatsu Nikki', 'TV', 12, 'Completed', '2019-04-04', '2019-06-20', '6', 'After growing up in Tokyo, high school student Jin Kaito moves to Nagoya where he meets Yatogame Monaka, a fellow student who puts her Nagoya dialect on full display. With her cat-like appearance and unvarnished Nagoya dialect, Yatogame won''t open up to him at all. This popular local comedy is increasing the status of Nagoya through observation of the adorable Yatogame-chan! 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cinderella Girls Gekijou: Extra Stage', 'ONA', 48, 'Completed', '2020-03-24', '2021-04-13', '6', 'Fifth season of Cinderella Girls Gekijou.', 1143, 'https://cdn.myanimelist.net/images/anime/1224/106098.jpg');
