INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou no Mako-chan', 'TV', 48, 'Completed', '1970-11-02', '1971-09-27', '6', 'Mako is a young siren and daughter to the King of the Sea. In a stormy day she rescues the young sport Akira from a wrecked ship, but ends up falling in love with him. So, with help from the Witch of the Sea, she''s transformed into a human, and becomes a highschool student who helps everyone with her strong sense of love and justice and her magical pendant, the "Tear of the Mermaid."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chiichai! Maou-sama!!', 'ONA', 24, 'Completed', '2022-07-17', '2023-10-01', '6', 'Mini anime for Hataraku Maou-sama!! released on Twitter and YouTube.', 39, 'https://cdn.myanimelist.net/images/anime/1594/127715.jpg');
