INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('MonHun Nikki Girigiri Airou Mura G', 'TV', 13, 'Completed', '2011-07-01', '2011-09-29', '6', 'This sequel will depict the comical adventures of the Airuu (Felyne), a feline monster species in CAPCOM''s Monster Hunter game franchise, as they face numerous quests.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Morimori Shima no Mogu to Perol', 'ONA', 1, 'Completed', '2018-01-19', NULL, '6', 'Mogu is always making tasty dishes but Perol is taking far more than his share. One day Moog is looking to collect some berries (to make into a cake) but Perol eats some off the bush raw. They taste sour and Perol thinks Moog tricked him and claims they aren''t friends anymore. Perol stops visiting but he becomes quite zombie-like and Moog misses his company too.', 1160, 'https://cdn.myanimelist.net/images/anime/1760/90149.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Himegoto', 'TV', 13, 'Completed', '2014-07-07', '2014-09-29', '6', 'Constantly on the run from loan sharks, Hime Arikawa has to deal with the debt left over from his parents'' lousy spending habits, which they left under his name. Fleeing in a maid outfit forced upon him by the moneylenders, he is found and rescued by Shimoshina High School''s student council, who pay the debt in full. However, now indebted to the student council for saving him, they not only make Hime transfer schools, but also make him a part of the student council as their servant!
