INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ninkuu: Knife no Bohyou', 'Special', 1, 'Completed', '1994-10-01', NULL, '6', 'After the war, Fuusuke, Aicho and Touji head to a port town searching for Makoto, the younger sister of an old friend who died in combat and left his knife for her as an inheritance. But when they arrive, they discover that the citizens are being attacked by pirates! Now, the three Ninku must help Makoto defeat Rasen Ryuu and his crew.', 939, 'https://cdn.myanimelist.net/images/anime/1884/127435.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Piace: Watashi no Italian', 'TV', 12, 'Completed', '2017-01-11', '2017-03-29', '6', 'While on her summer break, Morina Nanase starts a new part-time job as a waitress at Trattoria Festa, an Italian restaurant. Finding the restaurant adorable and coincidentally close to her house, Morina quickly settles into her new profession.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shabake (ONA)', 'ONA', 1, 'Completed', '2021-07-19', NULL, '6', 'Special produced to celebrate the 20th anniversary of the Shabake novel series.', 811, 'https://cdn.myanimelist.net/images/anime/1782/116029.jpg');
