INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuuki no Hana ga Hiraku Toki: Yanase Takashi to Anpanman no Monogatari', 'Special', 1, 'Completed', '2019-02-10', NULL, '5', 'A biographical anime about Sore Ike! Anpanman creator Takashi Yanase, based on Kumiko Kakehashi''s novel of the same name, and celebrates what would have been the 100th birthday of the manga creator.', 990, 'https://cdn.myanimelist.net/images/anime/1432/98577.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Heisei Matsue Kaidan: Ayashi', 'ONA', 2, 'Completed', '2017-03-17', '2018-04-01', '5', 'A Matsue City collaboration anime with Eagle Talon. Yoshida book-ends the story as horror tales, both modern and historical, originated within the city are narrated by another person.', 214, 'https://cdn.myanimelist.net/images/anime/12/84746.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Luna-tan: 1-mannen no Himitsu', 'ONA', 10, 'Completed', '2017-06-05', '2017-07-29', '5', 'There was a land that kept the prosperity of the world using the energy Mana of the titans called Luna. However, when a tsunami struck the world, the land was destroyed. The story takes place ten thousand years after the huge tsunami in the underground. Mokugyo and Toriiruka are the main characters, who are strange animals. "Why are we here?" "I thought we were in somewhere peaceful..." What exactly happened ten thousand years ago? Can Mokugyou and Toriiruka safely return to the surface?
