INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Megane no Mahou', 'ONA', 1, 'Completed', '2018-09-24', NULL, '6', 'Chugai Pharmaceutical''s promotion anime bringing awareness to rheumatoid arthritis.', 1009, 'https://cdn.myanimelist.net/images/anime/1661/96886.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ikkyuu-san (1978)', 'TV', 26, 'Completed', '1978-04-10', '1978-10-23', '6', 'High-school student Ikkyuu knows nothing about baseball, but his talents are recognized by the manager of the baseball club, and he takes up this enchanting sport. While his ignorance of the game leads him to make many mistakes, Ikkyuu - who is in fact a descendant of ninja - displays his superhuman abilities and leads the team to the High School Baseball Championships.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('TV Yarou Nanaana: Wakuwaku Doukutsu Land', 'TV', 24, 'Completed', '2019-04-11', '2019-09-19', '6', 'After the TV station gets acquired by "Nanazon Prime Video," departments that don''t get high ratings will be restructured (aka fired). The shooting crew takes on a large-scale plan for their survival. The Banakawa Family was an extremely wealthy family in the Edo period but their gold was hidden somewhere in a cave (that even the surviving members of the Banakawa Family can''t find). So the crew''s program will feature them exploring the underground world in search of this hidden treasure that so far major TV station networks with big budgets could not find.', 873, 'https://cdn.myanimelist.net/images/anime/1383/99945.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Trickster: Edogawa Ranpo "Shounen Tanteidan" yori OVA', 'OVA', 2, 'Completed', '2016-12-22', NULL, '6', 'The first episode will focus on the past between Kogorou Akechi and the Fiend With Twenty Faces, while the second will focus on the Boy Detectives Club before Kobayashi and Hanazaki met.', 990, 'https://cdn.myanimelist.net/images/anime/9/83323.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bubuki Buranki', 'TV', 12, 'Completed', '2016-01-09', '2016-03-26', '6', 'Away from home for 10 years, Azuma Kazuki had no idea what was awaiting him upon his return. He certainly did not expect to be attacked by dozens of heavily armed people and taken as their prisoner. Fortunately, Azuma''s stay in captivity is short. Wielding a strange sentient weapon—known as "Bubuki"—upon her right arm, his childhood friend, Kogane Asabuki, rescues him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zoku Attacker You! Kin Medal e no Michi', 'TV', 52, 'Completed', '2008-01-01', NULL, '6', 'Young and ambitious girls strive to do their very best to become NO.1 team in the sport world of volleyball. Outside the court, they face the problem of termination if they don’t win along with family, love and friendship dilemmas.', 484, 'https://cdn.myanimelist.net/images/anime/1731/149624.jpg');
