INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dou Hun Wei Zhi Xuan Yue Qiyuan II', 'ONA', 13, 'Completed', '2018-11-27', '2019-02-19', '5', 'Second season of Dou Hun Wei Zhi Xuan Yue Qiyuan.', 1130, 'https://cdn.myanimelist.net/images/anime/1148/105446.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dou Hun Wei Zhi Xuan Yue Qiyuan III', 'ONA', 13, 'Completed', '2019-05-27', '2019-08-19', '5', 'Third season of Dou Hun Wei Zhi Xuan Yue Qiyuan.', 1130, 'https://cdn.myanimelist.net/images/anime/1843/106146.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Poccolies', 'TV', 50, 'Completed', '2020-04-06', '2021-03-15', '5', 'The 2018 LINE sticker set Poccolies is inspiring a series of anime shorts. The story of the sticker set is that a positive and honest boy named Patsuhiko lives on Pokkori Island, along with the shrewd and mysterious Ham, and a reliable older brother figure named Kangaroo. The sticker set follows their daily lives. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pichiko Dakyuubu USA-hen', 'Special', 3, 'Completed', NULL, NULL, '5', '', 214, 'https://cdn.myanimelist.net/images/anime/8/75831.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pichiko Dakyuubu', 'TV', 29, 'Completed', '2010-02-01', NULL, '5', '', 214, 'https://cdn.myanimelist.net/images/anime/2/75830.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dennou Senshi Dokan-kun: Champ Dokan', 'Special', 1, 'Completed', '2007-06-20', NULL, '5', 'A DVD special of Dennou Senshi Dokan-kun released on the 3rd DVD of "Fight Tension☆Depart," the variety program that originally aired the anime as one of its segments. The episode parodies Ashita no Joe.', 214, 'https://cdn.myanimelist.net/images/anime/1864/105570.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tobidase! Dokan-kun Specials', 'Special', 2, 'Completed', '2012-08-24', NULL, '5', 'DVD specials of Tobidase! Dokan-kun.', 214, 'https://cdn.myanimelist.net/images/anime/1590/105571.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Olga no Russia-go Kouza', 'TV', 11, 'Completed', '2007-01-15', '2007-03-26', '5', 'Shorts that aired within "Fight Tension☆Depart," a variety program that originally aired the anime as one of its segments. A blonde Russian woman named Olga gives Russian language hints and comedic cultural tips.', 214, 'https://cdn.myanimelist.net/images/anime/1416/105573.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Arms Rally', 'TV', 11, 'Completed', '2007-01-15', '2007-03-26', '5', 'A flash animation about a long distance tank race in the Taklimakan desert (a real desert in Northwest China). It aired within "Fight Tension☆Depart," a variety program that originally aired the anime as one of its segments.', 434, 'https://cdn.myanimelist.net/images/anime/1888/105574.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Overman King Gainer Recap', 'Special', 1, 'Completed', '2014-03-31', NULL, '5', 'Short summary of the first 11 episodes included in the "Overman King Gainer BD Memorial Box" volume.', 974, 'https://cdn.myanimelist.net/images/anime/1806/105585.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mori no Ongakudan', 'ONA', 13, 'Completed', '2015-07-30', '2016-11-16', '5', '', 974, 'https://cdn.myanimelist.net/images/anime/1105/95109.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Neko Enikki', 'TV', 13, 'Completed', '2015-08-02', '2015-09-24', '5', 'The autobiographical manga utilizes both drawings and photos of cats to chronicle the life of a woman who lives by herself in order to live with her cats. She is described as a "himono-onna," a Japanese slang word that means "a woman who is proper in public but lazy at home."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kirakira Shougakusei Celeb-chan', 'TV', 11, 'Completed', '2007-01-15', '2007-03-26', '5', 'Shorts that aired within "Fight Tension☆Depart," a variety program that originally aired the anime as one of its segments. Celeb-chan is a narcissistic school girl who believes that she is a celebrity because her family is incredibly wealthy. She tries to do typical rich people things such as starting her own heavy makeup line, becoming a singer, saving an endangered species, buying a teacup poodle, etc. The results are never how she expects it.', 214, 'https://cdn.myanimelist.net/images/anime/1620/105673.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dokkiri Doctor Special', 'Special', 1, 'Completed', '1999-08-10', NULL, '5', 'Dokkiri Doctor special. Also known as Episode 27.', 939, 'https://cdn.myanimelist.net/images/anime/12/44077.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuroko no Basket', 'TV', 25, 'Completed', '2012-04-08', '2012-09-22', '8', 'For the last three years, Teikou Middle School has dominated the national basketball scene with its legendary lineup: the "Generation of Miracles." It consisted of five prodigies who excelled at the sport, but a "Phantom Sixth Man" lurked in the shadows and helped earn the team their revered status. Eventually, their monstrous growth jaded them from the sport they loved and made them go their separate ways in high school.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece Film: Strong World', 'Movie', 1, 'Completed', '2009-12-12', NULL, '8', 'Upon hearing news that islands in East Blue are being destroyed, Monkey D. Luffy and his crew go to investigate. On their way, however, an outlandish pirate ship appears out of the sky, helmed by the infamous pirate Shiki "the Golden Lion"—a man who ate the Float-Float Fruit and the first ever prisoner to escape from Impel Down. In his quest to defeat the World Government, Shiki kidnaps Nami to be his own navigator and sends the rest of the Straw Hat Pirates to his floating islands as hostages, leaving her in a dilemma. Separated in a land under Shiki''s absolute control, Luffy and his crew must survive the mystifying terrain in order to bring back their navigator and friend.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toradora!', 'TV', 25, 'Completed', '2008-10-02', '2009-03-26', '8', 'Ryuuji Takasu is a gentle high school student with a love for housework; but in contrast to his kind nature, he has an intimidating face that often gets him labeled as a delinquent. On the other hand is Taiga Aisaka, a small, doll-like student, who is anything but a cute and fragile girl. Equipped with a wooden katana and feisty personality, Taiga is known throughout the school as the "Palmtop Tiger."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gosick', 'TV', 24, 'Completed', '2011-01-08', '2011-07-02', '8', 'Kazuya Kujou is a foreign student at Saint Marguerite Academy, a luxurious boarding school in the Southern European country of Sauville. Originally from Japan, his jet-black hair and dark brown eyes cause his peers to shun him and give him the nickname "Black Reaper," based on a popular urban legend about the traveler who brings death in the spring.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yowamushi Pedal: Grande Road', 'TV', 24, 'Completed', '2014-10-07', '2015-03-31', '8', 'Second season of the Yowamushi Pedal series.', 990, 'https://cdn.myanimelist.net/images/anime/12/67799.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Paprika', 'Movie', 1, 'Completed', '2006-11-25', NULL, '8', 'The world of dreams can be an incredible window into the psyche, showing one''s deepest desires, aspirations, and repressed memories. One hopeful tech lab has been developing the "DC Mini," a device with the power to delve into the dreams of others. Atsuko Chiba and Kosaku Tokita have been tirelessly working to develop this technology with the hopes of using it to deeply explore patients'' minds and help cure them of their psychological disorders.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('World Trigger 2nd Season', 'TV', 12, 'Completed', '2021-01-10', '2021-04-04', '8', 'After successfully holding off the invasion by Aftokrator, the Border Defense Agency prepares an away mission into the Neighbor''s dimension. However, like in previous scouting expeditions, only A-rank teams are certain to secure a spot. As the B-rank wars continue, Osamu Mikumo and the rest of Tamakoma-2 quickly fight to the top in an attempt to obtain a promotion before the operation begins.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('No Game No Life', 'TV', 12, 'Completed', '2014-04-09', '2014-06-25', '8', 'Sixteen sentient races inhabit Disboard, a world overseen by Tet, the One True God. The lowest of the sixteen—Imanity—consists of humans, a race with no affinity for magic. In a place where everything is decided through simple games, humankind seems to have no way out of their predicament—but the arrival of two outsiders poses a change.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan Movie 03: Seikimatsu no Majutsushi', 'Movie', 1, 'Completed', '1999-04-17', NULL, '8', 'Kaitou Kid dares to challenge the police once more, setting his sights on the Russian Imperial Easter Egg. With the date, time, and place, the Osaka police force scrambles to stop him. But this time, Kid may have bitten off more than he can chew—Conan Edogawa, Heiji Hattori, and numerous others are also trying to get their hands on the jeweled egg.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan Movie 25: Halloween no Hanayome', 'Movie', 1, 'Completed', '2022-04-15', NULL, '8', 'Shibuya, Tokyo, is bustling with the Halloween season. A wedding is being held at Shibuya Hikarie, where Sato is dressed in a wedding dress. While Conan and the other invited guests are watching, an assailant suddenly bursts in, and Takagi, who was trying to protect Sato, is injured. Takagi survived and the situation was settled, but in Sato''s eyes, the image of the grim reaper that she had seen when Jinpei Matsuda, the man she had been in love with, had been killed in a series of bombings three years ago, overlapped with Takagi''s.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Golden Boy', 'OVA', 6, 'Completed', '1995-10-27', '1996-06-28', '8', 'Kintarou Ooe is a specialist in part-time work, riding all over the highways and byways of Japan on his trusty steed, the Mikazuki 5, and finding employment wherever he can. His adventures bring him knowledge and experience that can''t be taught in a classroom, from political corruption to the delicacy of a young woman''s heart. With nothing but the open road before him—not to mention the many beautiful women along the way—Kintarou pursues his spirit of education while attempting to hold down his various odd jobs, however undignified they may be. As he learns from each task he takes on, who knows what could happen? He might even be able to save the world one day. One thing is for sure—this will all be very educational!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('FLCL', 'OVA', 6, 'Completed', '2000-04-26', '2001-03-16', '8', 'Naota Nandaba is an ordinary sixth grader living in a city where nothing amazing ever seems to happen. After his brother Tasuku leaves town to play baseball in America, Naota takes it upon himself to look after everything Tasuku left behind—from his top bunk bed to his ex-girlfriend Mamimi Samejima, who hasn''t stopped clinging to Naota since Tasuku left. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gridman Universe', 'Movie', 1, 'Completed', '2023-03-24', NULL, '8', 'A year has passed since the events of SSSS.Gridman. The world is at peace and no one except for Rikka and Utsumi remembers the kaiju, Gridman, or Akane Shinjou. This includes Yuuta, who despite serving as Gridman''s host, has no memory of the most important moments of his life. So when a new Kaiju appears, he leaps at the chance to prove to himself that he too can be the hero by merging with Gridman once more.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dorohedoro', 'TV', 12, 'Completed', '2020-01-13', '2020-03-30', '8', 'Hole—a dark, decrepit, and disorderly district where the strong prey on the weak and death is an ordinary occurrence—is all but befitting of the name given to it. A realm separated from law and ethics, it is a testing ground to the magic users who dominate it. As a race occupying the highest rungs of their society, the magic users think of the denizens of Hole as no more than insects. Murdered, mutilated, and made experiments without a second thought, the powerless Hole dwellers litter the halls of Hole''s hospital on a daily basis.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Darker than Black: Kuro no Keiyakusha', 'TV', 25, 'Completed', '2007-04-06', '2007-09-28', '8', 'It has been 10 years since Heaven''s Gate appeared in South America and Hell''s Gate appeared in Japan, veiling the once familiar night sky with an oppressive skyscape. Their purposes unknown, these Gates are spaces in which the very laws of physics are ignored. With the appearance of the Gates emerged Contractors, who, in exchange for their humanity, are granted supernatural abilities.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jibaku Shounen Hanako-kun 2 Part 2', 'TV', 12, 'Completed', '2025-07-06', '2025-09-21', '8', 'Due to frequent misadventures with the supernatural and her hectic school life, Nene Yashiro can barely catch a break until Kamome Academy''s annual sleepover event comes around. Nene is excited to blow off some steam with her best friend Aoi Akane and the rest of her class at the get-together. Unbeknownst to her, the sleepover falls on the same date as Urabon, when the line between the dead and the living gets distorted, allowing wicked spirits to come out to the surface.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Akatsuki no Yona', 'TV', 24, 'Completed', '2014-10-07', '2015-03-24', '8', 'The kingdom of Kouka is blessed with a beautiful princess whose childlike innocence charms all who come across her. Named Yona, she has grown up sheltered in the royal palace, shielded from any danger that may befall her. However, all good things must come to an end.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fate/stay night: Unlimited Blade Works Prologue', 'Special', 1, 'Completed', '2014-10-05', NULL, '8', 'In Fuyuki City, a long-lived ritual involving battles between seven magi and their servants is taking place. This ritual is known as the Holy Grail War and it promises to grant the victor any wish. With the war now entering its fifth iteration, the stage is set for Rin Toosaka to succeed her father''s legacy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lovely★Complex', 'TV', 24, 'Completed', '2007-04-07', '2007-09-29', '8', 'Love is unusual for Risa Koizumi and Atsushi Ootani, who are both striving to find their ideal partner in high school—172 cm tall Koizumi is much taller than the average girl, and Ootani is much shorter than the average guy at 156 cm. To add to their plights, their crushes fall in love with each other, leaving Koizumi and Ootani comically flustered and heartbroken. To make matters worse, they''re even labeled as a comedy duo by their homeroom teacher due to their personalities and the stark difference in their heights, and their classmates even think of their arguments as sketches.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan Movie 10: Tantei-tachi no Requiem', 'Movie', 1, 'Completed', '2006-04-15', NULL, '8', 'After receiving a strange invitation, Kogorou Mouri pays a visit to the Miracle Land theme park along with his daughter Ran, Conan Edogawa, and the Detective Boys. Once there, Kogorou and Conan are tasked with finishing an unsolved case by a mysterious stranger. Realizing that the invitations were actually an elaborate trap, the two have just 12 hours to solve the case or face grave danger.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shijou Saikyou no Deshi Kenichi', 'TV', 50, 'Completed', '2006-10-08', '2007-09-30', '8', 'Whenever he is not getting pummeled in the karate club after school, high schooler Kenichi Shirahama can be found with his head buried in one of the many self-help books he carries with him every day. One day, on the way to school, Kenichi accidentally frightens the new student in his class, leading her to throw him down onto the ground. After apologizing for her violent reflexes, she introduces herself as Miu Furinji and asks Kenichi to be her friend.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kill la Kill', 'TV', 24, 'Completed', '2013-10-04', '2014-03-28', '8', 'After the murder of her father, Ryuuko Matoi has been wandering the land in search of his killer. Following her only lead—the missing half of his invention, the Scissor Blade—she arrives at the prestigious Honnouji Academy, a high school unlike any other. The academy is ruled by the imposing and cold-hearted student council president Satsuki Kiryuuin alongside her powerful underlings, the Elite Four. In the school''s brutally competitive hierarchy, Satsuki bestows upon those at the top special clothes called "Goku Uniforms," which grant the wearer unique superhuman abilities. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Black Lagoon', 'TV', 12, 'Completed', '2006-04-09', '2006-06-25', '8', 'Salaryman Rokurou Okajima spends his days trying to climb his company''s corporate ladder, until one day when a business negotiation in Thailand goes awry. During the botched deal, he falls hostage to the Lagoon Company—a band of ruthless pirate mercenaries. Left to the whims of his captors after his managers refuse to pay his ransom, Rokurou does the unthinkable: instead of begging for his life, he joins the very crew who kidnapped him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuru Camp△ Season 3', 'TV', 12, 'Completed', '2024-04-04', '2024-06-20', '8', 'Within the narrow walls of the Outdoor Activities Club room, the few but lively members carry on the camping spirit as they have fun with DIY club experiments. Exciting experiences such as these have brought Nadeshiko Kagamihara deep into the world of camping, making her want to once again go on a solo trip.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hibike! Euphonium', 'TV', 13, 'Completed', '2015-04-08', '2015-07-01', '8', 'Now that Kumiko Oumae has enrolled in Kitauji High School, she hopes to forget about her past. Despite her desire for a fresh start, she gets dragged into the school''s band club by her new friends—Sapphire Kawashima and Hazuki Katou—and is once again stuck playing the euphonium. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('PriPara', 'TV', 140, 'Completed', '2014-07-05', '2017-03-28', '8', 'Every little girl waits for the day she''ll get her special ticket, one that will grant her entry into the world of PriPara (Prism Paradise). PriPara is a world of music, fashion, and daily auditions for a chance to become a pop idol. Laala Manaka''s friends and classmates aspire to become idols, but her school forbids elementary school students from participating in the idol competitions.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka', 'TV', 13, 'Completed', '2015-04-04', '2015-06-27', '8', 'Life in the bustling city of Orario is never dull, especially for Bell Cranel, a naive young man who hopes to become the greatest adventurer in the land. After a chance encounter with the lonely goddess, Hestia, his dreams become a little closer to reality. With her support, Bell embarks on a fantastic quest as he ventures deep within the city''s monster-filled catacombs, known only as the "Dungeon." Death lurks around every corner in the cavernous depths of this terrifying labyrinth, and a mysterious power moves amidst the shadows.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lupin III: Episode 0 "First Contact"', 'Special', 1, 'Completed', '2002-07-26', NULL, '8', 'Jigen tells the story of the gang''s first meeting. Jigen, still a member of the Mafia, is hired to protect an ancient artifact - one that Lupin and Fujiko are both trying to steal. Meanwhile, Inspector Zenigata, then of the Japanese police force, has come to the U.S. on Fujiko''s trail, and Ishikawa Goemon is searching for the lost treasure of his clan. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Initial D Battle Stage 3', 'OVA', 1, 'Completed', '2021-03-05', NULL, '8', 'Initial D: Battle Stage 3 is the eleventh and final installment of the Initial D series. It features every race from Fifth Stage and Final Stage. Unlike the previous two battle stages, it does not feature any new battles, and doesn''t feature any character dialogue.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga Tetsudou 999 (Movie)', 'Movie', 1, 'Completed', '1979-08-04', NULL, '8', 'Tetsurou Hoshino is a boy bent on obtaining an immortal mechanical body in order to take revenge against his mother''s murderer, the machine man Count Mecha. However, due to the incredible cost of obtaining what he seeks, his only hope is to steal a boarding pass for the Galaxy Express 999, a space train that travels across the galaxy and whose final stop is a planet where the metal replacements are provided for free. After swiping a pass, Tetsurou is pursued by the police and ends up collapsing into the arms of a mysterious woman named Maetel, who closely resembles his mother. Once he awakens, she tells the boy that she will provide him entry onto the 999 as long as he agrees to travel with her. Accepting her proposition, Tetsurou boards the cosmic railway with Maetel and begins a journey across the galaxy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Darker than Black: Kuro no Keiyakusha - Sakura no Hana no Mankai no Shita', 'Special', 1, 'Completed', '2008-03-26', NULL, '8', 'A side-story of Darker than Black, also called Episode 26, that takes place during the events of Kuro no Keiyakusha. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tonari no Seki-kun', 'TV', 21, 'Completed', '2014-01-06', '2014-05-26', '8', 'All Rumi Yokoi wants to do is focus during school, but she is constantly distracted by Toshinari Seki, her neighboring classmate. Paying attention during class is the least of Seki''s worries, as he obsesses over intricate setups created using an assortment of items, from an elaborate domino course on his desk to a treacherous war played out with shogi pieces. Yokoi desperately attempts to focus in class, only to be repeatedly sucked into his intriguing eccentricities; however, they always seem to end up with her getting in trouble with their teacher. Fortunately, lessons will never be dull with Seki''s antics around!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aa! Megami-sama! Sorezore no Tsubasa', 'TV', 22, 'Completed', '2006-04-07', '2006-09-15', '8', 'One year after goddess Belldandy emerged from Keiichi Morisato''s mirror and promised to stay with him forever, a new threat to their happiness emerges, one that could end the contract between Belldandy and Keiichi.', 25, 'https://cdn.myanimelist.net/images/anime/4/78931.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saki Achiga-hen: Episode of Side-A Specials', 'Special', 4, 'Completed', '2013-02-20', '2013-08-21', '8', 'The semifinal round of the Inter-High Mahjong Championship is still in full swing. After witnessing the extraordinary might of the champion Teru Miyanaga of Shiraitodai High School, the girls of Achiga High School are left bewildered. However, even if the odds are against them, it''s not too late yet—the game has just begun.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Patapata Hikousen no Bouken', 'TV', 26, 'Completed', '2002-01-05', '2002-06-29', '8', 'Jane''s mother dies when she is born, and her father, a rich English aristocrat, soon remarries to a woman with a son, William, who despises his new father and brother. George and Jane grow up with a dream to make a flying machine. George believes the distant Asian sands hold a secret: a mysterious cerulean sand which can make machines fly. He goes on an expedition to find it, and soon is reported executed for treason. William disappears too. After she recieves an unsigned letter holding a handful of pale-blue sand which floats in the air, Jane is sure her brother is alive and leaves to the East to find him and prove him innocent. There are many mysteries to unravel in store for Jane and her new friends on her journey. But perhaps a mystery should forever remain a mystery... 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Tennis no Oujisama', 'TV', 13, 'Completed', '2012-01-05', '2012-03-29', '8', 'Ryouma Echizen is one of 50 nationally ranked middle school tennis players to receive an invitation for the Japan U-17 tennis training camp. Previously open only to high school players, the exclusive regiment trains the best players in the country for the upcoming U-17 World Cup. The high schoolers are not pleased that these middle schoolers are allowed into the camp, but the middle schoolers easily overwhelm them before they are halted by the coaches.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chiyu Mahou no Machigatta Tsukaikata', 'TV', 13, 'Completed', '2024-01-06', '2024-03-30', '8', 'Ken Usato, an ordinary high schooler, wishes for something fantastical to occur in his unremarkable life. Such an opportunity arrives when he is transported to another world alongside Kazuki Ryuusen and Suzune Inukami, two prodigious members of his school''s student council. Arriving in Llinger Kingdom, the three are deemed to be the heroes tasked with stopping the impending invasion by the Demon Lord''s army. However, this is a misunderstanding—Usato was summoned by accident and, unlike his two friends, is not one of the heroes.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsurezure Children', 'TV', 12, 'Completed', '2017-07-04', '2017-09-19', '8', 'Young love—it takes many unique and fascinating forms that flourish as children begin to mature into adults. From being unable to confess to not knowing what real love actually feels like, various obstacles can arise when learning about romantic attraction for the first time. But underneath all that, young love is something truly beautiful to behold, leading to brand new experiences for those young and in love.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jigoku Sensei Nube', 'TV', 49, 'Completed', '1996-04-13', '1997-06-21', '8', 'Nube is a clumsy, easygoing, and very kind teacher, but he has a secret under his glove on the left hand. He has a monster hand, and he also has the ability to sense ghosts and evil spirits. So he protects his dear students from these evil spirits with his monster hand, proving to be very powerful.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Utawarerumono Specials', 'Special', 6, 'Completed', '2006-08-23', '2007-02-21', '8', 'DVD specials of comedic events that occurred during the story of Utawarerumono. The specials are included in the DVD Box special disc.', 621, 'https://cdn.myanimelist.net/images/anime/1319/99303.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aa! Megami-sama! Movie', 'Movie', 1, 'Completed', '2000-10-21', NULL, '8', 'For centuries, a god named Celestin has been imprisoned on the moon for betraying the kingdom of Yggdrasil. Released by the fairy Morgan Le Fey, Celestin travels to Earth to reunite with his former pupil, the goddess Belldandy. Things go awry as Celestin erases Belldandy''s memories of her boyfriend Keiichi and uses her as a catalyst to wreak havoc on Earth and Yggdrasil.', 25, 'https://cdn.myanimelist.net/images/anime/5/71211.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Poputepipikku 2nd Season', 'TV', 11, 'Completed', '2022-10-02', '2022-12-11', '8', 'High school girl duo Popuko and Pipimi are back and more unhinged than ever after their initial efforts to create a full-fledged anime production were met with a great reception. With no regard for their audience, they continue to live their reckless everyday lives consisting of comedy skits and parodies of epic proportions. No one is immune to the effects of their antics—including hapless live actor Shouta Aoi, who is on the run and stuck trying to be a hero in the wrong series.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The Big O', 'TV', 26, 'Completed', '1999-10-13', '2003-03-27', '8', 'Paradigm City, a city of amnesia and a place of belonging. It remains populated by forgotten pasts and the ruins of their labors due to a calamity 40 years ago. Shrouded in a fog-like mystery, it is up to people like Roger Smith to shine a light through the mist. Acting as a professional negotiator and suave agent, Roger is a self-tailored ladies man whose only love is for funeral black. However, as he gets deeply involved with his clients, what often starts as a simple negotiation evolves into Roger saving Paradigm from crime and peril.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Taiho Shichau zo (TV)', 'TV', 47, 'Completed', '1996-10-05', '1997-09-27', '8', 'Tokyo Highway Patrolwomen Natsumi and Miyuki get off to a bad start when Miyuki busts Natsumi for reckless moped driving on her way to work. Things get worse when they find out they''re going to be partners!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shounen Onmyouji', 'TV', 26, 'Completed', '2006-10-04', '2007-03-28', '8', 'Masahiro is the grandson of the great onmyouji, Abe no Seimei. However, he lost his sixth sense that enables him to see supernatural beings, which is very important for an onmyouji. Thus, he is left with no choice but to try and pick a different career. But one day, a strange mononoke appears, which he names Mokkun, who shows him his true potential powers after fighting a demon. With the assistance of Mokkun, his quest to become the greatest onmyouji begins.', 879, 'https://cdn.myanimelist.net/images/anime/1865/106109.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Baki: Dai Raitaisai-hen', 'ONA', 13, 'Completed', '2020-06-04', NULL, '8', 'Weakened by the poison from his last battle, Baki Hanma finds himself on the verge of death with no salvation in sight. However, after Baki''s friend, Retsu Kaiou, brings him to China, he learns about the centurial Raitai Tournament, where the fiercest warriors fight to be crowned as the strongest martial artist in all of China. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('To LOVE-Ru Darkness 2nd Specials', 'Special', 2, 'Completed', '2016-02-26', NULL, '8', 'Extra episodes of To LOVE-Ru Darkness 2nd bundled with the seventh Blu-ray and DVD volume.', 1117, 'https://cdn.myanimelist.net/images/anime/9/79330.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boku no Hero Academia the Movie 4: You''re Next', 'Movie', 1, 'Completed', '2024-08-02', NULL, '8', 'Deku, Bakugo, Todoroki and the rest of U.A. High Class 1-A must face off against Dark Might and the obscure crime organisation under his control, the Gollini Family.', 138, 'https://cdn.myanimelist.net/images/anime/1480/143549.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boukyaku Battery (TV)', 'TV', 12, 'Completed', '2024-04-10', '2024-07-03', '8', 'Haruka Kiyomine and Kei Kaname were once recognized as the most formidable pitcher-catcher duo in middle school baseball. Known as the "General," Kaname paired his expert strategies with Kiyomine''s explosive pitches, crushing the dreams of many starry-eyed players who hoped to one day make it to the big leagues.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Arifureta Shokugyou de Sekai Saikyou Season 3', 'TV', 16, 'Completed', '2024-10-14', '2025-02-17', '7', 'En route to conquer a Great Labyrinth with his allies and former classmates, Hajime Nagumo is sidetracked by a tragedy that befalls his party member Shea Haulia. After encountering a group of rabbitmen caught in an ambush, Nagumo learns that members of Shea''s Haulia Tribe have been abducted by soldiers of the Hoelscher Empire. To alleviate the anxiety of Shea, whose father may be in mortal danger, Nagumo decides to head toward the empire and rescue the missing Haulias.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Reikenzan: Hoshikuzu-tachi no Utage', 'TV', 12, 'Completed', '2016-01-09', '2016-03-26', '7', 'Long ago in the nine provinces of Kyushu, a calamitous event was prophesied to take place: falling comets would exhaust the spiritual energies of both the heavens and the lands and thus bring about an age of chaos upon the world. But contrary to the prophecy, the comets passed by with no calamity taking place. At the same time, as if touched by the phenomenon, a boy was born in a remote village of the Sokei region by the name of Ouriku.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Grisaia no Rakuen Specials', 'Special', 5, 'Completed', '2015-08-26', '2015-12-25', '7', 'Short specials included in the Blu-ray and DVD releases.', 12, 'https://cdn.myanimelist.net/images/anime/10/75439.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hayate no Gotoku! Cuties', 'TV', 12, 'Completed', '2013-04-09', '2013-07-02', '7', 'Taking place after the events that occurred in Hayate no Gotoku! Can''t Take My Eyes off You. Hayate, Nagi and Maria return to their daily lives at the Sanzenin Mansion and the Violet Mansion.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Natsu-iro Kiseki', 'TV', 12, 'Completed', '2012-04-06', '2012-06-29', '7', 'Throughout life, people come and go, eventually departing with a goodbye. For childhood friends Natsumi Aizawa, Yuka Hanaki, and Rinko Tamaki, they are confronted with this harsh reality when they are told their group''s fourth member, Saki Mizukoshi, is moving away at the end of summer. With this news threatening their friendship, the four girls seek out a magic stone from local folklore—hoping to use its rumored wish-granting powers to keep them together. After following the steps of the supposed legend, they are surprised to discover that the magic is real.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Full Metal Panic! Movie 1: Boy Meets Girl', 'Movie', 1, 'Completed', '2017-11-25', NULL, '7', 'Shikidouji, the illustrator of Shoji Gatoh''s Full Metal Panic! light novel series, revealed that production has been green-lit on a "director''s cut" version of the first Full Metal Panic!! television anime series from 2002. The director''s cut will consist of three films. The announcement does not state if the film trilogy will add new footage. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Full Metal Panic! Movie 3: Into the Blue', 'Movie', 1, 'Completed', '2018-01-20', NULL, '7', 'Shikidouji, the illustrator of Shoji Gatoh''s Full Metal Panic! light novel series, revealed that production has been green-lit on a "director''s cut" version of the first Full Metal Panic!! television anime series from 2002. The director''s cut will consist of three films. The announcement does not state if the film trilogy will add new footage. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wo Shi Jiang Xiaobai (2018)', 'ONA', 1, 'Completed', '2018-05-25', NULL, '7', 'Jiang Xiaobai has regained his memories, and Tong Li cannot bring herself to face him. Separately, they confront the truths left unsaid for 10 years—about the band September, to which Jiang Xiaobai and Mu Xiyu dedicated their youth; about the love triangle between Jiang Xiaobai, Mu Xiyu, and Tong Li; and about the painful circumstances that brought the trio together and ultimately led to the terrible tragedy that occurred on the day Tong Li left for America. At the end of it all, can Jiang Xiaobai and Tong Li accept the past and face the future together?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aishen Qiaokeli-ing...II', 'ONA', 15, 'Completed', '2017-12-21', '2018-04-05', '7', 'Jiang Hao Yi, a normal, high school student who is extremely scared of getting into trouble, suddenly becomes the Harem King of his school when a bunch of beautiful girls confess to him! Unfortunately for Jian Hao, he doesn''t know any of the girls who have confessed to him... What on Earth is happening?', 108, 'https://cdn.myanimelist.net/images/anime/5/89258.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Slow Start', 'TV', 12, 'Completed', '2018-01-07', '2018-03-25', '7', 'Hana Ichinose, a 17-year-old high school student who is not only introverted, but also insecure and timid, has just moved and will be attending a new school. To make her situation more difficult,  Hana is a "slow start," which means that she missed a year and worries about attending a class where everyone is younger than her.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koro-sensei Quest!', 'ONA', 12, 'Completed', '2016-12-23', '2017-03-10', '7', 'One day, class 3-E of Kunugigaoka Magic School receives a special mission: to kill their homeroom teacher, the Demon King Koro-sensei. To increase their chances of succeeding, the class searches for the three most powerful warriors—Karma Akabane, Itona Horibe, and Ritsu—who later join their company. Even with their help, accomplishing the mission becomes an insurmountable task as they are not the only ones after the Demon King''s life.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Super Senko-san Time Episode 12', 'Special', 1, 'Completed', '2019-09-25', NULL, '7', 'Unaired episode 12 of the special segment "Super Senko-san Time" included in the 3rd BD volume of Sewayaki Kitsune no Senko-san.', 241, 'https://cdn.myanimelist.net/images/anime/1861/101663.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blame! Movie', 'Movie', 1, 'Completed', '2017-05-20', NULL, '7', 'A young girl named Zuru sets out on an expedition through a post-apocalyptic city controlled by machines in a desperate hunt for food. Things go awry when her team accidently triggers the city''s AI defense program called the Safeguard. Attacked by the machines, her companions are on the verge of being annihilated when a mysterious man named Killy arrives and exterminates the hostile units.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Joker Game', 'TV', 12, 'Completed', '2016-04-05', '2016-06-21', '7', 'With World War II right around the corner, intelligence on other countries'' social and economic situation has become a valuable asset. As a result, Japan has established a new spy organization known as the "D Agency" to obtain this weapon.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xi Xing Ji: Jijie Pian', 'ONA', 22, 'Completed', '2019-09-28', '2020-01-31', '7', 'The journey to the West was a conspiracy of heaven! After Sutra went missing for more than a decade, Heaven sent its army to search, in order not to let the Sutra once again fall into the hands of heaven, the journey to West begin again.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Huyao Xiao Hongniang 8: Jin Chenxi Pian', 'ONA', 10, 'Completed', '2020-06-19', '2020-08-14', '7', 'Eighth season of Huyao Xiao Hongniang.', 369, 'https://cdn.myanimelist.net/images/anime/1459/153695.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan: Kinga Shinnen Mouri Kogorou', 'Special', 1, 'Completed', '2015-01-03', NULL, '7', 'Special episode consisting of two short stories. The first being an expanded version of Detective Conan: The Fugitive Kogorou Mouri, which was never aired on TV till now. The second half being a brand new New Years Day segment.', 990, 'https://cdn.myanimelist.net/images/anime/4/82692.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Danball Senki', 'TV', 44, 'Completed', '2011-03-02', '2012-01-11', '7', 'In 2046, a revolutionary 80% shock-absorbing reinforced cardboard has been developed, rapidly transforming the world''s exports. The reinforced cardboard would soon become the battleground for a popular children''s hobby called "LBX" (Little Battler eXperience).
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('NG Knight Ramune & 40', 'TV', 38, 'Completed', '1990-04-06', '1991-01-04', '7', 'Lamune is an ordinary 4th grade boy who loves playing video games. He buys one from a peddler girl and helps her sell the rest. At home, he plays the game called "King Sccasher" &amp; beats it. The peddler girl then comes out of the TV screen and asks for his help, calling him "The Blood Relative of the Chosen Hero Lamuness". She is Princess Milk and takes him to Hara-Hara World where his role is to revive the Guardian Knights. To do this, he had to find an unlock the shrine which held Tama-Q, a robot who became Lamuness'' Advisor Robot, and key to freeing the Guardian Knights. All of the Knights are free-thinking mechas except for King Sccasher which is piloted by Lamuness. Opposing Lamuness is Don Harumage and his minions Da Cider and Lesuka. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Baka to Test to Shoukanjuu Ni!: Mahou Hideyoshi Hideyoshi', 'Special', 1, 'Completed', '2011-10-26', NULL, '7', 'A short special included on the second volume of Baka to Test to Shoukanjuu Ni! Blu-ray/DVD release.', 761, 'https://cdn.myanimelist.net/images/anime/8/63597.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('ef: A Tale of Memories. - Prologue', 'Special', 1, 'Completed', '2007-08-24', NULL, '7', 'The prologue for ef - a tale of memories, released on a separate DVD two months before the premiere of the TV series.', 791, 'https://cdn.myanimelist.net/images/anime/13/26046.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tennis no Oujisama: Oshougatsu Special', 'Special', 1, 'Completed', '2003-03-07', NULL, '7', 'The New Year has finally arrived for the Seishun Academy Boys'' Tennis Team. As part of the festivities, Ryouma Echizen and his fellow first-year club members—Satoshi Horio, Kachirou Katou, and Katsuo Mizuno—celebrate by reminiscing about the past year. As the freshmen revel in nostalgia, it seems as if a strange hanetsuki tournament has begun among the rest of the team.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kousoku Denjin Albegus', 'TV', 45, 'Completed', '1983-03-30', '1984-02-08', '7', 'Three talented students of a technical high school, Daisaku, Tetsuya and Hotaru create award-winning robots as part of a school competition. At this time, the evil Derinja race that plans control of all space extends its ambitions to Earth. To combat this threat, Hotaru''s father, Professor Mizuki, takes the three robots and modifies them for battle. Albegas, a super robot, is born. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsubasa to Hotaru', 'Special', 1, 'Completed', '2014-03-16', NULL, '7', 'After joining her new school, the enthusiastic 15-year-old Tsubasa Sonokawa believes she immediately experienced a fated encounter. While in trouble, she was helped by her upperclassman and fell in love with him. However, due to her habit of overdoing things, Tsubasa''s feelings are not reciprocated.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saint Seiya: Jashin Eris', 'Movie', 1, 'Completed', '1987-07-18', NULL, '7', 'Eris is the goddess of chaos and uses the body of Elien, who is a friend of Hyoga, to revive herself. She obtains the golden apple to drain Athena''s life energy to make her ressurection complete and to be able to turn the world in a place filled with chaos. But to be able to attack Eris, Seiya and his friends will first have to defeat the Ghost Knights. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wanwan Sanjuushi', 'TV', 26, 'Completed', '1981-10-02', '1982-03-26', '7', 'The story begins with the arrival of a brave young boy in Paris. His ambition is to join the glorious Imperial Guards, but fierce competition and the minimum age requirement hinder him from joining. The boy then challenges the well-known Three Musketeers in order to demonstrate his excellent skills with the sword. However, at the very moment the fight begins, a power-hungry group cuts in. Realizing their wicked intention, the boy D''artagnan and the Three Musketeers quickly cooperate and defeat them. This is the beginning of their friendship and commitment to fight conspiracy.', 607, 'https://cdn.myanimelist.net/images/anime/1993/129946.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Honoo no Mirage: Minagiwa no Hangyakusha', 'OVA', 3, 'Completed', '2004-07-28', '2004-11-26', '7', 'Takaya was sent to Kyoto to investigate the re-awakening of Ikko sect and Araki Murashige, a member of the Ikko sect who deserted the clan.With the help of his vassal Haruie, Takaya is finally successful in tracing Araki who hunts down a 400-years-old mandala (Buddhist artifact for meditating) that was made of the hair of the deceased Araki clansmen. Unfortunately, by the time they meet, Haruie recognizes Araki as Shintarou, her lover in her past-life. Takaya orders her to eliminate Araki, who is a threat, but will she be able to do it. Furthermore Takaya finally meets Naoe... 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yozakura Quartet', 'TV', 12, 'Completed', '2008-10-03', '2008-12-19', '7', 'The world of Yozakura Quartet is actually not one, but two worlds: one of humans, and one of youkai. Despite appearing mostly human, youkai may have animal like physical traits, along with a number of special abilities. Normally youkai are confined to their world, but some have found their way into the realm of humanity. As a symbol of peace, and a bridge between the two realms, a city was constructed within the protective barrier of seven magical trees, otherwise known as the Seven Pillars. This city of Sakurashin is home to both humans and youkai, with the peace between them maintained by the Hizumi Life Counseling Office.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lamune', 'TV', 12, 'Completed', '2005-10-11', '2005-12-27', '7', 'Lamune tells the story of a boy named Kenji and his childhood friend Nanami. Although, everyone seems to know that they have a relationship, neither are determined to push it anymore than close friends. The story goes through flashbacks, explaining why they are such close friends and any action doesn''t seem to push them apart, but draw them closer.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('PopoloCrois', 'TV', 26, 'Completed', '2003-10-05', '2004-03-28', '7', 'Pinon, the boy who flows within his body, the blood of the three races (the Dragons, the fairies and the humans), is actually the son of the Courageous One, Pietro. Pinon''s encounter with a mysterious animal, Pap, opens up the door to an adventurous journey. He befriends Luna and Marco on the way. However, when he learns that his adventure will determine the fate of PoPoLoCrois, Pinon hardens his heart and leaves his friends. Unknown to him, this is an introductory chapter to a new adventure and Pinon will realise that he must resolve the bigger crisis present in PoPoLoCrois. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Inazuma Eleven Go Specials', 'Special', 2, 'Completed', '2011-12-08', '2011-12-23', '7', 'Recap episodes of Inazuma Eleven Go made to catch viewers up in the newest franchise in preparation for the Inazuma Eleven Go: Kyuukyoku no Kizuna Gryphon film being released at the same time period (the 2nd recap ep aired on the same day the movie came out). Both recap episodes were included on the 12th DVD volume of the main anime as well.', 621, 'https://cdn.myanimelist.net/images/anime/12/86762.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shingetsutan Tsukihime', 'TV', 12, 'Completed', '2003-10-10', '2003-12-26', '7', 'Shiki Toono wakes up in a hospital ward with the ability to see invisible lines. These thin threads, which make up all matter in Shingetsutan, instantly destroy an object when severed. Shiki discovers that if he traces the lines of something, its destruction soon follows. While keeping his supernatural vision a secret, Shiki proceeds to live his sophomore life in peace. However, this peace is short-lived when Shiki encounters a mysterious woman with bright red eyes on his way back from school. Following a sudden psychotic lapse, he appears to kill the woman, and passes out shortly after. As if things couldn''t get any worse, Shiki is assailed by a pair of demonic hounds the next day—facing certain death, Shiki is saved by the timely arrival of the same woman from yesterday. She introduces herself as Arcueid Brunestud, a vampire princess. Deciding to team up, Shiki and Arcueid embark on a journey to uncover the truth behind their lineage and the recent string of murders around town.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fushigi Yuugi: Eikouden', 'OVA', 4, 'Completed', '2001-12-21', '2002-06-25', '7', 'After years of hardships interfered with their love, Miaka Yuuki and Taka Sukunami are finally married and expecting a baby—the pinnacle of their unbreakable bond. Unfortunately, not everyone rejoices alongside the blessed couple. Mayo Sakaki, one of Taka''s students, has a crush on him and cannot bear witnessing the pair''s flourishing relationship.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lupin III: Bye Bye Liberty - Kiki Ippatsu!', 'Special', 1, 'Completed', '1989-04-01', NULL, '7', 'In this adventure, Lupin III tries to erase the files about him in the world police network. He finds out about the Ultravirus, a computer virus that controls all others and its location is only known by a little kid. Meanwhile, he steals the Statue of Liberty to look for a diamond the size of a football that is said to be hidden somewhere in it. Apparently, the diamond and the ultravirus are somehow related... 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shinkyoku Soukai Polyphonica', 'TV', 12, 'Completed', '2007-04-04', '2007-06-20', '7', 'Phoron Tatara''s no ordinary musician. As one of the rare Dantists who can summon elder spirits using music called Commandia, his gift is so strong that his spirit partner is none other than the infamous Corticarte Apa Lagranges. Sure, she may look like a young girl in her human form, but you don''t get nicknames like "The Crimson Annihilator" and "The Bloody Duchess" for sitting back and watching the daisies grow.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Brave Witches', 'TV', 12, 'Completed', '2016-10-06', '2016-12-29', '7', 'As humanity''s war with the Neuroi—a mysterious, hostile alien race possessing weapons of unparalleled power—continues being fought across Europe and Africa, a new fighter squadron is formed. The 502nd Joint Fighter Wing, also known as the Brave Witches, operates on the eastern front, scouring the icy vastness of Orussia in search of alien invaders.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shuumatsu Touring', 'TV', 12, 'Airing', '2025-10-04', '2025-12-20', '7', 'All alone after the end of days, two girls bike through the empty ruins of Japan—and they''re not about to let the collapse of civilization get in the way of sightseeing! Even when the world ends, their journey goes on.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shu Tian Fu Mo Lu', 'ONA', 16, 'Completed', '2023-05-26', '2023-09-15', '7', 'The Yuan brothers awaken their bloodline to slay demons and monsters, forming a brand-new westward journey team with the celestial messenger Xiao Ba A Sha and the demon thief Zi Zhu, embarking on an adventure about faith and courage!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kinnikuman: Kanpeki Choujin Shiso-hen', 'TV', 11, 'Completed', '2024-07-14', '2024-09-22', '7', 'Following an epic series of fierce fights between various factions of Choujin—beings blessed with supernatural physical abilities that hail from all corners of the galaxy—the former enemies of Seigi Choujin, the victorious group, negotiate a fragile ceasefire. However, peace is short-lived, and a group of seven Perfect Choujin—led by Strong the Budo and called the Perfect Large Numbers—invade Japan, defeating several Seigi Choujin and burning the peace treaty.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pupipo!', 'TV', 15, 'Completed', '2013-12-21', '2014-03-29', '7', 'Himeji Wakaba is a 5th year elementary school student, and she has the ability to see things that others can''t. They are mostly frightening evil spirits, and they tend to do bad things to people who are close to her. As a result, Wakaba has no friends and rarely smiles. On a couple of occasions, she brings home stray animals, but her parents won''t let her keep them. However, they''re worried about their sad, creepy daughter, so one day they decide that whatever Wakaba brings home next, they''ll let her keep.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kemono no Souja Erin Recap', 'Special', 10, 'Completed', '2010-01-09', '2010-03-13', '7', 'Summarized version of the 50-episode TV series. Includes all the highlights.', 704, 'https://cdn.myanimelist.net/images/anime/11/19317.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Freezing', 'TV', 12, 'Completed', '2011-01-08', '2011-04-07', '7', 'Decades into the future, humanity is under siege by an alien race known as the Novas. These inhuman beings leave devastation in their wake whenever they appear, with the efforts to stave them off becoming known as Nova Clashes. Young women known as "Pandoras" and young men known as "Limiters" are implanted with stigmata to give them superhuman powers and are trained in military academies, where they must learn to work together if humanity is to have a chance of surviving.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou Shoujo Site Recaps', 'Special', 2, 'Completed', '2018-05-10', '2018-06-13', '6', 'Recaps of the Mahou Shoujo Site created by Avex Entertainment. Narrated by AI Kizuna and Nobuhiko Okamoto.', 1176, 'https://cdn.myanimelist.net/images/anime/1255/93332.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ketsuekigata-kun! 4', 'TV', 12, 'Completed', '2016-01-12', '2016-03-29', '6', 'Is asking an A Type for cold medicine the best on sick days? What does a B Type wish for on New Year''s? Can an AB Type really outsmart a demon? What are O Types like when they end up in the hospital? Which type has the best plan for the dreaded "Valentine''s Day and White Day at the office" scenario? Find out the answers to these typical situations and more in the fourth season of Ketsuekigata-kun!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sangokushi II: Amakakeru Otoko-tachi', 'Special', 1, 'Completed', '1986-08-22', NULL, '6', 'The sequel to Sangokushi (1985).', 802, 'https://cdn.myanimelist.net/images/anime/8/72949.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Trapp Ikka Monogatari Specials', 'Special', 2, 'Completed', '2001-06-01', NULL, '6', 'A summary of the Trapp Ikka Monogatari full series aired as a TV specials.', 607, 'https://cdn.myanimelist.net/images/anime/5/64139.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Puraore! Pride of Orange', 'TV', 12, 'Completed', '2021-10-06', '2021-12-22', '6', 'Third-year junior high schooler Manaka Mizusawa is tasked by her teacher to put a poster up about a trial ice hockey class sponsored by the Dream Monkeys, their city''s local professional team. Interested in attending the class herself, Manaka also persuades her younger sister Ayaka and her clubmates Kaoruko Yanagida and Mami Ono to join her.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('New Dream Hunter Rem: Yume no Kishi-tachi', 'OVA', 1, 'Completed', '1990-12-16', NULL, '6', 'Rem is an ordinary woman in our world but, in the world of dreams, she becomes a dream warrior, defending humanity from the evils there. When dream demons reach the waking world, she fights them with the help of her pets which transform into a tiger and wolf.', 949, 'https://cdn.myanimelist.net/images/anime/1452/94153.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blassreiter: Navi', 'Special', 1, 'Completed', '2008-06-22', NULL, '6', 'This special aired between episodes 11 and 12 and recaps the events of the first eleven episodes.', 341, 'https://cdn.myanimelist.net/images/anime/6/23361.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nameko-ke no Ichizoku', 'OVA', 13, 'Completed', '2013-12-20', '2014-07-16', '6', 'It will be about the daily life of a big family of mushrooms living together.', 1159, 'https://cdn.myanimelist.net/images/anime/12/55085.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Appaga Piryohae', 'Movie', 1, 'Completed', '2005-01-01', NULL, '6', 'The short film "Wolf Daddy" directed by Chang Hyung-yun won the Hiroshima Award at the 11th Hiroshima Animation Festival. The 10 minute long animation film features the story of a werewolf novelist who gets to play the role of daddy for a six-year-old girl. Produced in 2005, the animation also won the 2005 Korean Animation Award and a Tokyo International Anime Fair award.', 184, 'https://cdn.myanimelist.net/images/anime/7/72704.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Onikirimaru', 'OVA', 4, 'Completed', '1994-09-09', '1995-07-21', '6', 'For decades, a strange man has wandered across Japan, known solely by the name of the sword he carries—Onikirimaru. Despite his human appearance, he is an ogre who has sworn to eliminate the rest of his kind, hoping to one day become fully human. As he walks this bloody path, he witnesses innumerable human tragedies and knows that he is the only one standing between the ogres and the total destruction of humanity.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Souten no Ken Specials', 'Special', 4, 'Completed', '2007-05-24', '2007-06-14', '6', 'Episodes 16, 17, 18 and 21 of the Souten no Ken anime series, which were not originally aired, but released on DVD. Because of this, these episodes are uncut/uncensored. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bouken Yuuki Pluster World', 'TV', 52, 'Completed', '2003-04-03', '2004-03-25', '6', 'According to the legend, the once peaceful "Pluster World" plunged into chaos and darkness due to the manifestation of the evil MINASUTA. At that time, selected Plusters were combined with humans, and successfully sealed away the evil MINASUTA. It was then believed that the peace which had returned would continue forever. Greenery and trees filled the land, flowers bloomed everywhere, living creatures soar in the blue sky, run on the land, and swim in the seas.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ningyohime Marina no Bouken', 'TV', 26, 'Completed', '1991-02-02', '1991-07-27', '6', 'Marina is a mermaid who is in love with Prince Justin, a human prince from a kingdom on the shore. Marina saves Justin when he almost drowns after a chase from a giant Cyclops and a shipwreck attack from a three-headed sea serpent. She then makes a deal with Hedwig the sea witch to become human temporarily to try to win Justin''s love. Justin and Marina become close but Justin thinks that Princess Cecily, a human princess, was the one who saved him from drowning and therefore he gets engaged to her. Justin eventually remembers that Marina was the one who saved his life but by then Marina becomes a mermaid again. The two continue to secretly meet and try to find a way to be together while dealing with Hedwig''s plans to take over the kingdom, and Cecily''s attempts to get Justin to marry her. Marina and Justin are aided by their underwater friends, Winnie the seahorse, Bobo the tropical fish, and Ridley the sea otter. They are also aided by the wizard Anselm and by Chauncey, Justin''s page.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('AIKa Zero', 'OVA', 3, 'Completed', '2009-07-06', '2009-12-22', '6', 'Aika''s story continues, she is now 19 years-old, 3 years older than in R-16 and 7 younger than in Agent AIKa. Strange phenomena have been occuring at a girls academy. Slowly but persistently the most cute and beautiful girls are joining an internal club, but instead of a sing-in they just get abducted by a strange being that takes control over them by some indecent means. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Miracle Train: Chuo-sen e Youkoso', 'Special', 1, 'Completed', '2009-08-18', NULL, '6', 'Five of the Chuo train stations have been turned into the proud leader Zero Tokyo (Hiroyuki Yoshino,) the girl-wooing Rintarou Shinjuku (Ryotaro Okiayu,) the ramen-loving otaku Riku Nakano (Hiroshi Kamiya,) the charming yet acerbic Takuto Kichijouji (Miyu Irino,) and the gentle yet risk-taking Lune Tachikawa (Kouki Miyata.) The anime version will be the first anime based on a title from Yomban, Bandai Visual''s original content website.  This is the 1 min introduction.  The main thing is the drama CD called  "Special Seat e Youkoso!" (ドラマCD 「スペシャルシートへようこそ」)', 1141, 'https://cdn.myanimelist.net/images/anime/9/18390.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ore, Twintail ni Narimasu. Recap', 'Special', 1, 'Completed', '2015-04-05', NULL, '6', 'A recap episode of Ore, Twintail ni Narimasu. that aired exclusively on BS-TBS. It starts with a chibi Souji and Aika speaking to the viewer before delving into the body of the recap where they comment about the events of the TV anime. The voice actors of Souji and Aika both represent themselves and the characters they voice flipping between sounding like their characters and speaking casually as real people. The recaps ends with chibi Souji and Aika thanking the viewer and then talking about how fun the Ore, Twintail ni Narimasu. live-event was (which clips are shown of) and asking viewers to visit the official site to find news about future events.', 705, 'https://cdn.myanimelist.net/images/anime/1845/99646.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kakuchou Shoujo-kei Trinary', 'ONA', 34, 'Completed', '2017-04-12', '2017-11-29', '6', 'Born from the strong emotions of their creators, self-contained pocket dimensions known as Phenomenon have begun forming across Japan. These false worlds overwrite the reality of an affected area and will only be undone if the maker is defeated or appeased. In response, a military-sponsored task force known as Trinary is formed, and its three members—Miyabi Koigasaki, Gabriela Lotaryńska, and Ayami Kunimasa—specialize in dispersing Phenomenon.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gundam: G no Reconguista - From the Past to the Future', 'Special', 1, 'Completed', '2015-03-21', NULL, '6', 'Bell and Aida are scouting the zone around Towasanga, when they''re attacked by Mask Squad. Mask is piloting a new unit, a pitch black Phenex.', 974, 'https://cdn.myanimelist.net/images/anime/4/76243.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchida Shungicu no Noroi no One-Piece', 'Special', 1, 'Completed', '1992-08-25', NULL, '6', 'An omnibus horror TV special where three girls encounter a beautiful rose patterned yellow one-piece dress which curses them as they try to gain the attention of a man they like in their lives.', 494, 'https://cdn.myanimelist.net/images/anime/1524/107399.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Micchiri Wanko! Animation', 'TV', 24, 'Completed', '2020-04-01', '2020-09-09', '6', 'Spin-off of Micchiri Neko.', 170, 'https://cdn.myanimelist.net/images/anime/1793/106522.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fushigi na Somera-chan', 'TV', 12, 'Completed', '2015-10-07', '2015-12-23', '6', 'The story follows the everyday life of Somera Nonomoto who can use the strongest kenpo, Nonomoto Mahou-ken, which is inherited from her mother with her younger sister Kukuru.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sakura Kakumei: Hanasaku Otome-tachi', 'ONA', 1, 'Completed', '2020-09-02', NULL, '6', 'A special anime based on the beginning of iOS/Android RPG by the same name.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Neko Neko Fantasia', 'OVA', 1, 'Completed', '1991-12-13', NULL, '6', '"Shiro" is a black cat who loves her family very much. She loves them so much she wants to help them out in times of need and trouble…but it’s difficult to do this if she''s just a cat. So one night, she wishes on the moon to make her able to help, and the next day, she has turned into a human girl.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toukiden 2', 'ONA', 3, 'Completed', '2016-06-30', '2016-07-12', '5', 'Promotional anime for Koei-Tecmo game Toukiden 2 by Studio 4°C.', 849, 'https://cdn.myanimelist.net/images/anime/11/80662.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('dwarf Movie Lab', 'ONA', 13, 'Completed', '2014-05-02', NULL, '5', 'Various shorts made by studio dwarf using original characters from franchises they worked on such as Domo-kun and Komaneko as well as original ones. Includes 12 "Vol." numbered episodes and one "Uma no Hi Kodomo" titled episode.', 1160, 'https://cdn.myanimelist.net/images/anime/13/88392.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Glasslip', 'TV', 13, 'Completed', '2014-07-03', '2014-09-25', '5', 'What if you hold the power to hear the voices or see fragments of images from the future? Would that be a good thing or a bad thing? Glasslip follows the life of Touko Fukami, an aspiring glass artist born from a glass artisan family. She enjoys her worry-free life in Fukui, save for the fragments of images that she sees on occasion.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sugio: Mori de Koi wo Shite', 'ONA', 3, 'Completed', '2015-09-27', NULL, '5', 'The shorts follow a cedar tree named Cedric, who falls in love with a human woman. In order to remain with her, he hopes that she will use him to build her home.', 214, 'https://cdn.myanimelist.net/images/anime/8/76608.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chuumon no Ooi Ryouriten (1993)', 'Movie', 1, 'Completed', '1993-08-03', NULL, '5', 'Two gentlemen from the city go out hunting. After getting lost on a mountain road they found a cheap restaurant. But everything is not as it seems.', 540, 'https://cdn.myanimelist.net/images/anime/6/74516.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Poppen-sensei to Kaerazu no Numa', 'Special', 1, 'Completed', '1982-04-29', NULL, '5', 'A short TV special based on the children''s book series Poppen-sensei which follows a biology assistant professor at Udo University who gets wrapped up in his fantasies in nature.', 563, 'https://cdn.myanimelist.net/images/anime/10/72657.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou x Shounen x Days!!!!!', 'Special', 1, 'Completed', '2015-06-24', NULL, '5', 'Spreading love and hope to save the world—we are the Magic Sabers!!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The One Piece', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'Remake of One Piece.', 1105, 'https://cdn.myanimelist.net/images/anime/1105/140422.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Honzuki no Gekokujou: Shisho ni Naru Tame ni wa Shudan wo Erandeiraremasen - Ryoushu no Youjo', 'TV', NULL, 'Upcoming', '2026-04-01', NULL, '5', 'Anime adaptation of part three of the Honzuki no Gekokujou light novel.', 1105, 'https://cdn.myanimelist.net/images/anime/1983/150931.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sinbi Apartment: Ghost Ball Zero - Du Beonjjae Iyagi', 'TV', 15, 'Completed', '2023-11-30', '2024-03-14', '5', '', 855, 'https://cdn.myanimelist.net/images/anime/1918/139337.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Full Metal Panic? Fumoffu', 'TV', 12, 'Completed', '2003-08-26', '2003-11-18', '8', 'Sergeant Sousuke Sagara returns to Jindai High School to protect the precious war asset, Kaname Chidori, from any threat. However, his lack of social skills and real-life experience result in comical yet dangerous situations, endangering the peaceful school life Kaname longs for. As Sousuke continues to bring a wide range of weapons to school as a means to solve threats—real or fake—Kaname struggles to fulfill her duty as the student council vice president all while keeping him in check. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Karakai Jouzu no Takagi-san 2', 'TV', 12, 'Completed', '2019-07-07', '2019-09-22', '8', 'Even after spending a considerable amount of time with Takagi, Nishikata is still struggling to find a perfect plan to defeat the expert teaser. A battle of wits, a contest of physical prowess, a test of courage—any strategy he employs to expose her weaknesses is to no avail. On the contrary, Nishikata''s pitiful attempts only reveal more of his own flaws, which Takagi takes advantage of to become increasingly daring in her teasing attempts. To make things worse for Nishikata, rumors about him and Takagi may have spread in class due to the frequent interactions between them.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yahari Ore no Seishun Love Comedy wa Machigatteiru. Zoku OVA', 'OVA', 1, 'Completed', '2016-10-27', NULL, '8', 'After accepting a weekend invitation, Hachiman Hikigaya accompanies Isshiki Iroha around the Chiba Prefecture to brainstorm ideas suitable for an ideal date with Hayato Hayama. As the duo wanders from place to place without a plan, they seemingly enjoy each other''s company. Yet, through these straightforward and sincere interactions, the meaning behind what it means to be genuine continues to intrigue Hachiman and his outlook for the future of the Volunteer Service Club and its members.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Black Lagoon: Roberta''s Blood Trail', 'OVA', 5, 'Completed', '2010-06-27', '2011-06-22', '8', 'Crime never sleeps in Roanapur, and neither does Roberta—a devoted maid and skilled guerilla soldier in service to the Venezuelan Lovelace family. After the assassination of her superior by the US Secret Service, Roberta returns to the city of debauchery in search of vengeance and his killer''s head.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Omae Umasou da na', 'Movie', 1, 'Completed', '2010-10-16', NULL, '8', 'By a twist of fate, a herbivorous dinosaur finds a lost egg and brings it back to her nest. When the egg hatches, however, a carnivorous dinosaur emerges. Unable to abandon the child, she names him "Heart" and raises him in exile alongside her own child. As Heart comes of age, he struggles to eat the same food as his family and runs away in disgrace when he learns that he cannot live properly without meat. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wan Sheng Jie 2', 'ONA', 12, 'Completed', '2020-10-14', '2020-12-16', '8', '"Dear Mom and Dad, it''s already been a year since I left home. Don''t worry- I''m doing great! I can take care of myself now. And I''ve learned to take care of others, too. Before, I never could have imagined having so many friends. But now, I can hardly imagine living without them. I think... Here, is my second home."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dennou Coil', 'TV', 26, 'Completed', '2007-05-12', '2007-12-01', '8', 'In the near future, augmented reality has become a key part of daily life. A gentle middle school girl named Yuuko "Yasako" Okonogi and her family have just moved to Daikoku City despite rumors of people disappearing. There, her grandmother, nicknamed "Mega-baa," runs a shop called Megasia that specializes in illegal tools which interact with parts of the virtual world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Glass no Kamen (2005)', 'TV', 51, 'Completed', '2005-04-06', '2006-03-29', '8', 'Two Girls. One Dream. And the entire world for a stage.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('xxxHOLiC Shunmuki', 'OVA', 2, 'Completed', '2009-02-17', '2009-06-23', '8', 'For the appropriate price, your dearest wish can be granted at the shop of the peculiar Yuuko. Kimihiro Watanuki wishes to be rid of his ability to see spirits, and so as payment, he works for Yuuko doing whatever she needs him to do, from cleaning to errands to even helping out Yuuko''s other clients. In xxxHOLiC Shunmuki, Watanuki and his friend and rival Shizuka Doumeki enjoy a meal with their friend Kohane Tsuyuri and her grandmother, reminiscing about how they have changed since meeting each other.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan Movie 04: Hitomi no Naka no Ansatsusha', 'Movie', 1, 'Completed', '2000-04-22', NULL, '8', 'On a rainy afternoon, the Detective Boys witness a murder across the street. Barred by traffic, the culprit slips away and Conan Edogawa is left a single clue by a dying detective. Days later, another detective is found murdered in a parking lot, leaving the police rattled. Suspicious that the culprit is one of their own, everyone in the police department without an alibi is suspect. But despite being on high alert, they are outmaneuvered and suffer yet another attack—this time with Ran Mouri finding herself in the crossfire.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Keisatsu Patlabor 2 the Movie', 'Movie', 1, 'Completed', '1993-08-07', NULL, '8', 'Three years after the Babylon Project conspiracy is resolved, the members of Kiichi Gotou''s Patlabor unit have gone their separate ways. Gotou remains with the Patlabor team, accompanied by Shinobu Nagumo, his romantic crush and comrade.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsuki ga Kirei', 'TV', 12, 'Completed', '2017-04-07', '2017-06-30', '8', 'With a new school year comes a new crowd of classmates, and for their final year of junior high, aspiring writer Kotarou Azumi and track team member Akane Mizuno end up in the same class. Though initially complete strangers, a few chance encounters stir an innocent desire within their hearts. A yearning gaze, a fluttering heart—the hallmarks of young love slip into their lives as fate brings their paths to a cross.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga Nagareboshi Gin', 'TV', 21, 'Completed', '1986-04-07', '1986-08-22', '8', 'Having been born a brindle ("Tora-ge" or tiger striped) Akita, Gin ("Silver", named after his fur color) is destined to become a successful bear-hunting dog. However, when he witnesses his father''s death at the hands of the man-eating demon bear Akakabuto, he is chosen above his siblings to become his father''s successor and defeat the monstrous bear that terrorizes his home village. As Akakabuto gathers his own allies, Gin must travel across Japan in search of dogs to join him in an all out war of dog vs. bear.', 1030, 'https://cdn.myanimelist.net/images/anime/3/47461.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shadows House 2nd Season', 'TV', 12, 'Completed', '2022-07-09', '2022-09-24', '8', 'After the resolution of the debut, Kate and her Doll Emilico have officially become residents of the Shadows House. However, they are under constant vigilance by the Star Bearers—an elite group in charge of the children''s wing. In order to escape from their surveillance and the morbid methods they use to keep everyone''s loyalty in check, Kate and Emilico must be wary of who to trust and aim to become Star Bearers themselves.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Naruto', 'TV', 220, 'Completed', '2002-10-03', '2007-02-08', '8', 'Twelve years ago, a colossal demon fox terrorized the world. During the monster''s attack on the Hidden Leaf Village, the Hokage—the village''s leader and most powerful ninja—sacrifices himself to seal the beast inside a newborn, relieving civilization from destruction while dooming the baby to a lonely life.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mairimashita! Iruma-kun 2nd Season', 'TV', 21, 'Completed', '2021-04-17', '2021-09-11', '8', 'After many trials and tribulations, Iruma Suzuki is finally happily living among demons despite having to hide his true identity as a human. Even more so, he has now found his ambition in life: keep ranking up in this world!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Apocalypse Hotel', 'TV', 12, 'Completed', '2025-04-09', '2025-06-25', '8', 'In the year 2157, Gingarou Hotel, a luxury establishment in Ginza, Tokyo, employs advanced hotelier robots to provide best-in-class hospitality. Unfortunately, no one has visited the hotel in decades, as humanity has long abandoned Earth due to its toxic atmosphere.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mononoke Movie 1: Karakasa', 'Movie', 1, 'Completed', '2024-07-26', NULL, '8', 'Within the Inner Chambers—the luxurious garden of women destined only for the ruler of the nation—work burdens everyone from the lowest maid to the highest-ranking concubine. After arriving on the same day to start as servants, Asa and Kame quickly become friends. The two vow to overcome any challenges in their way as they begin their splendid new lives.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimi ni Todoke', 'TV', 25, 'Completed', '2009-10-07', '2010-03-31', '8', 'Known for her semblance to the Sadako character of The Ring series, Sawako Kuronuma is given the nickname "Sadako" and misunderstood to be frightening and malicious like her fictional counterpart, despite having a timid and sweet nature. Longing to make friends and live a normal life, Sawako is naturally drawn to the cheerful and friendly Shouta Kazehaya, the most popular boy in her class. From their first meeting, Sawako has admired Kazehaya''s ability to be the center of attention and aspires to be like him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kara no Kyoukai Movie 3: Tsuukaku Zanryuu', 'Movie', 1, 'Completed', '2008-02-09', NULL, '8', 'On a solemn night in July 1998, teenager Fujino Asagami is mercilessly raped by a street gang in a dilapidated bar. No matter what physical or sexual abuse they deal, however, the girl regards her captors with the same apathetic expression. The next day, mangled bodies are discovered in that same building, so torn apart that investigators find it infeasible to even consider the culprit human.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pui Pui Molcar', 'TV', 12, 'Completed', '2021-01-05', '2021-03-23', '8', 'Due to an adorable evolutionary miracle, guinea pigs have become furry automobiles known as "Molcars." Now, drivers can enjoy the fluffy interior of their vehicles while fulfilling their every transportation need. However,  Molcars are not simply lettuce-fueled machines; they are also sentient creatures with their own worries and desires. Whether in their drivers'' presence or among each other, these motorized rodents are swept up into many wild and eventful situations—the likes of which only a Molcar could wind up in.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Summer Wars', 'Movie', 1, 'Completed', '2009-08-01', NULL, '8', 'OZ, a virtual world connected to the internet, has become extremely popular worldwide as a spot for people to engage in a large variety of activities, such as playing sports or shopping, through avatars created and customized by the user. OZ also possesses a near impenetrable security due to its strong encryption, ensuring that any personal data transmitted through the networks will be kept safe in order to protect those who use it. Because of its convenient applications, the majority of society has become highly dependent on the simulated reality, even going as far as entrusting the system with bringing back the unmanned asteroid explorer, Arawashi.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tonikaku Kawaii: SNS', 'OVA', 1, 'Completed', '2021-08-18', NULL, '8', 'When Tsukasa Yuzaki receives a brand new smartphone as a surprise gift from her husband Nasa, she is delighted, quickly adding in contacts and mastering the arts of LINE and sticker-sending. However, her joy is short-lived: a former coworker calls in Nasa for a difficult job, and Tsukasa is dismayed to learn that her beloved might have to work through the night.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('5-toubun no Hanayome ∬', 'TV', 12, 'Completed', '2021-01-08', '2021-03-26', '8', 'Through their tutor Fuutarou Uesugi''s diligent guidance, the Nakano quintuplets'' academic performance shows signs of improvement, even if their path to graduation is still rocky. However, as they continue to cause various situations that delay any actual tutoring, Fuutarou becomes increasingly involved with their personal lives, further complicating their relationship with each other.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mignon', 'ONA', 12, 'Completed', '2023-08-11', NULL, '8', 'Underneath the bright city lights lies a bloodied arena bursting with frantic screams and roars. Strong men engage in boxing matches for money, while their audience desperately hopes that their chosen participants will bring them fortune. For the young rising star Mignon, there is only one place that is an escape from the chaos of the ring and his tough life. Mysterious underground doctor Oh Young-One offers his services to injured fighters, and the wide-eyed Mignon finds solace in his quiet infirmary.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Modern Love Tokyo: Kare ga Kanaderu Futari no Shirabe', 'ONA', 1, 'Completed', '2022-10-20', NULL, '8', 'Though her high school days are long behind her, Tamami Sakurai is still just as awkward and clumsy as ever. At night, she is often seen at a local Tokyo bar, which has become a safe haven from her stressful job. After a few too many drinks, Tamami begins to feel as if she is invincible, but the hangover afterward begs to differ.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuroko no Basket: Baka ja Katenai no yo!', 'OVA', 1, 'Completed', '2013-12-04', NULL, '8', 'Bundled with the 25th volume of Kuroko no Basket manga. The anime based on the Baka Ja Katenai no yo (バカじゃ勝てないのよ) story that was featured in the manga''s fifth volume.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Crayon Shin-chan Movie 18: Chou Jikuu! Arashi wo Yobu Ora no Hanayome', 'Movie', 1, 'Completed', '2010-04-17', NULL, '8', 'Comical action adventure film set in the future world, like a dystopian science fiction. Shinnosuke''s future fiancee, Tamiko Kaneari comes from the future via the time machine. She says her father Masuzo Kaneari captures adult Shinnosuke in the future world and they needs the power of Shinnosuke at age 5 to rescue him. She takes Shinnosuke and Kasukabe Defense Forces members to the future big city Neotokio, which is the world ruled by Masuzo Kaneari, the president of the electric power company Kaneari Electric. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Persona 3 the Movie 1: Spring of Birth', 'Movie', 1, 'Completed', '2013-11-23', NULL, '8', 'At the stroke of midnight, the Dark Hour appears—a secret hour which most are unaware of. Those not trapped in coffins during this time, unfortunate enough to find themselves conscious, are met by dangerous creatures known as Shadows. A select few, however, possess the potential to wield Persona: a special power used to defeat these beings. This secret group is called SEES (Specialized Extracurricular Execution Squad), and their mission is to uncover the reason behind the Dark Hour''s appearance.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yu☆Gi☆Oh! The Dark Side of Dimensions', 'Movie', 1, 'Completed', '2016-04-23', NULL, '8', 'Obsessed with revenge against the King of Games, Seto Kaiba commences an excavation in Egypt to find the fragments of the Millennium Puzzle, which once retained the spirit of the "counterpart Yuugi." However, a cloaked man steals two pieces of the Puzzle and disappears before it could be reconstructed. Meanwhile, now in their final year of high school, Yuugi Mutou and his friends plan for their futures, unaware of the danger lurking close by. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuan Zun', 'ONA', 26, 'Completed', '2024-05-30', '2024-08-29', '8', 'A young man with his brush plunges into a chaotic world and lights up the heavens. In a world where cultivators are paramount, will the vermilion bird swallow the dragon, or will the dragon transcend beyond all else?!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hinomaruzumou', 'TV', 24, 'Completed', '2018-10-05', '2019-03-29', '8', 'In professional sumo, there are no weight classes. It''s a savage sport where the strongest survive, and anyone willing to test their mettle can step into the ring. There is, however, a minimum size requirement to be a pro sumo wrestler, and young Hinomaru Ushio, incredibly talented and hardworking though he may be, does not meet that requirement. This small boy has big dreams of reaching the highest class of  sumo, Hinoshita Kaisan. The only way he could possibly go pro is if he becomes the High School Yokozuna, a title given to the strongest wrestler in high school tournaments.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Isshuukan Friends.', 'TV', 12, 'Completed', '2014-04-07', '2014-06-23', '8', 'Sixteen-year-old Yuuki Hase finally finds the courage to speak to his crush and ask her if she wants to become friends. The object of his affection, Kaori Fujimiya, is a quiet and reserved girl who cuts herself off from everyone and does not spare him the same blunt rejection she gives everybody else.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Drifters (OVA)', 'OVA', 2, 'Completed', '2017-12-23', NULL, '8', 'Despite the Ends’ attack on Verlina being successfully repelled, the war has not yet ended. With the monster armies regrouping, the Black King tightens his grasp on the already conquered territory. New conflicts erupt all across Orte, as its remaining forces struggle to retain control over long-oppressed demi-human races.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Asobi Asobase: Cosplay Taikai/Otona no Watashi e', 'OVA', 1, 'Completed', '2018-12-26', NULL, '8', 'After getting permission to show their film at the cultural festival, the Pastime Club fervently discusses what they plan to wear for the big event. The conversation soon takes to the next level, and the three girls begin to put their costume ideas to the test.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yamada-kun to 7-nin no Majo', 'TV', 12, 'Completed', '2015-04-12', '2015-06-28', '8', 'When Ryuu Yamada entered high school, he wanted to turn over a new leaf and lead a productive school life. That is why he chose to attend Suzaku High School, where no one would know of his violent delinquent reputation. However, much to Ryuu''s dismay, he is soon bored; now a second year, Ryuu has reverted to his old ways—lazy with abysmal grades and always getting into fights.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yao Shen Ji 3rd Season', 'ONA', 40, 'Completed', '2018-09-25', '2019-02-08', '8', 'Third season of Yao Shen Ji.', 752, 'https://cdn.myanimelist.net/images/anime/1134/95151.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boku no Hero Academia the Movie 1: Futari no Hero', 'Movie', 1, 'Completed', '2018-08-03', NULL, '8', 'U.A. High School''s students of Class 1-A have made it to summer break. Izuku Midoriya accompanies his mentor All Might to a celebratory superhero festival on I-Island, an isolated patch of land dedicated to researching Quirks and everything else associated with the hero business. Midoriya is granted the opportunity to meet All Might''s friend Dave and Dave''s daughter Melissa, two talented hero equipment engineers. He also encounters his classmates, most of whom have been given the opportunity to spend part of their summer break at the festival.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Re:Zero kara Hajimeru Isekai Seikatsu - Memory Snow - Manner Movie', 'Movie', 1, 'Completed', '2018-10-06', NULL, '8', 'Subaru Natsuki finally gets to take a breather, but he does not waste any time as he prepares for a date with his beloved Emilia. He scouts the nearby village for the right dating spot, and with the help of the village children, he finds a wonderful location. With that, he is well prepared for his date! Unfortunately for Subaru, cold weather suddenly sweeps across Roswaal''s mansion on his important day, leaving him with no choice but to postpone the date. Overnight, it becomes even colder and unbearable. Subaru must get to the bottom of this because, at this rate, his date will be the least of his worries.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Durarara!!x2 Ten: Onoroke Chakapoko', 'Special', 1, 'Completed', '2016-01-27', NULL, '8', 'In spite of the mayhem that has been taking place in Ikebukuro, Shinra Kishitani and Celty Sturluson have decided to go on a short trip. Excited to finally be going out with the one he loves, the underground doctor makes it his priority to give Celty his undivided attention, even if it means rejecting phone calls from his good friend Izaya Orihara.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Katekyou Hitman Reborn! Vongola Family Soutoujou! Vongola Shiki Shuugakuryokou, Kuru!!', 'ONA', 1, 'Completed', '2010-03-01', NULL, '8', 'An internet-only stand-alone special episode of Katekyou Hitman Reborn! on the Shounen-Jump website, where the main characters go to various tourist spots in Japan. It will be made available on DVD in July 2010, and extra scenes will be included.', 86, 'https://cdn.myanimelist.net/images/anime/7/27088.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Slam Dunk: Shouhoku Saidai no Kiki! Moero Sakuragi Hanamichi', 'Movie', 1, 'Completed', '1995-03-04', NULL, '8', 'After losing the titanic match against Kainan High, Team Shohoku and a newly shaven Hanamichi Sakuragi are challenged to an exhibition match by virtual basketball unknowns Ryoukufu High. Coach Anzai sees this as an opportunity for Shohoku to regain their confidence, but Ryoukufu are revealed to have a newly assembled championship calibre lineup and may give Sakuragi &amp; Co their toughest test yet.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam 00 Special Edition', 'OVA', 3, 'Completed', '2009-10-27', '2010-02-23', '8', 'Condensed version of both the first and second seasons of Gundam 00 featuring some new animated sequences and some partially re-recorded dialogue.', 974, 'https://cdn.myanimelist.net/images/anime/11/17217.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsurune Movie: Hajimari no Issha', 'Movie', 1, 'Completed', '2022-08-19', NULL, '8', 'A recap of Tsurune: Kazemai Koukou Kyuudoubu with new scenes.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Karakai Jouzu no Takagi-san: Water Slide', 'OVA', 1, 'Completed', '2018-07-12', NULL, '8', 'Joining Mano and Nakai on their trip to the water park are classmates Nishikata and Takagi. However, before they can decide on what to do first, Nakai runs off with Nishikata, leaving his saddened girlfriend behind with Takagi. Mano explains that Nakai promised to ride down the water slide with her—which is rumored to make tandem riders fall in love. Unsurprisingly, Takagi devises a plan to regroup the couple in a way that also permits her to spend time teasing Nishikata.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Crayon Shin-chan Movie 10: Arashi wo Yobu Appare! Sengoku Daikassen', 'Movie', 1, 'Completed', '2002-04-20', NULL, '8', 'A full-scale historical drama set in the last days (the year 1574) of the Sengoku Era of feudal Japan. It is the story of the Nohara family, who has been transferred into the Sengoku Era by time warp, and a tragic love between a princess Ren Kasuga (a daughter of the feudal lord Kasuga at the Province of Musashi) and a samurai warrior Matabei Ijiri (a retainer of the Lord Kasuga).
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchuu Patrol Luluco', 'TV', 13, 'Completed', '2016-04-01', '2016-06-24', '8', 'Living an abnormal existence in Ogikubo, an intergalactic melting pot of humans and aliens as well as the only Space Immigration Zone on Earth, Luluco is a bubbly middle school girl who just wants to be normal. One morning, however, her father, who works at the Space Patrol, eats a volatile sleep capsule by mistake and is frozen solid! To make matters worse, Luluco accidentally breaks him, so she hurries off to his office for help. There, the chief of the Space Patrol, Over Justice, hires Luluco as a space temp worker for undercover investigations, so that the institution may crack down on crime within her school.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Natsume Yuujinchou: Hitoyoshi Kuma de no Yasashii Jikan', 'Special', 1, 'Completed', '2021-04-21', NULL, '8', 'Takashi Natsume and his loyal feline protector Madara take a trip to Hitoyoshi Kuma, a peaceful area in Kumamoto. From admiring the Kaname Falls to relaxing at the Tsurukame hot spring, the duo unwind and take in the beautiful scenery throughout the eventful day.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('JoJo no Kimyou na Bouken', 'OVA', 6, 'Completed', '1993-11-19', '1994-11-18', '8', 'Kujo Jotaro is a normal, popular Japanese high-schooler, until he thinks that he is possessed by a spirit, and locks himself in prison. After seeing his grandfather, Joseph Joestar, and fighting Joseph''s friend Muhammad Abdul, Jotaro learns that the "Spirit" is actually Star Platinum, his Stand, or fighting energy given a semi-solid form. Later, his mother gains a Stand, and becomes sick. Jotaro learns that it is because the vampire Dio Brando has been revived 100 years after his defeat to Jonathan Joestar, Jotaro''s great-great-grandfather. Jotaro decides to join Joseph and Abdul in a trip to Egypt to defeat Dio once and for all.', 38, 'https://cdn.myanimelist.net/images/anime/1171/106036.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doraemon Movie 15: Nobita to Mugen Sankenshi', 'Movie', 1, 'Completed', '1994-03-12', NULL, '8', 'Tired of the daily life and being the weakest, slowest, and dumbest, Nobita seeks comfort in his dreams where, using Doraemon''s tools, he sets out on a fantasy journey. But when Nobita''s dream world gets threatened by an evil sorcerer, Nobita gathers his friends to join him in his dream to fight the evil as the Three Musketeers.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Magia Record: Mahou Shoujo Madoka☆Magica Gaiden 2nd Season - Kakusei Zenya', 'TV', 8, 'Completed', '2021-08-01', '2021-09-26', '7', 'After a daring escape from the Memory Museum, Sayaka Miki returns to Mitakihara City with unsettling news. Troubled by what she has learned, Sayaka reveals to Madoka Kaname and Homura Akemi the whereabouts of Mami Tomoe—but more importantly—the disturbing truth behind the existence of magical girls. Despite knowing the cruel fate that awaits them, the three quickly resolve to work together and save Mami once and for all.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Umineko no Naku Koro ni', 'TV', 26, 'Completed', '2009-07-02', '2009-12-24', '7', 'Considered as the third installment in the highly popular When They Cry series by 07th Expansion, Umineko no Naku Koro ni takes place on the island of Rokkenjima, owned by the immensely wealthy Ushiromiya family. As customary per year, the entire family is gathering on the island for a conference that discusses the current financial situations of each respective person. Because of the family head''s poor health, this year involves the topic of the head of the family''s inheritance and how it will be distributed.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Watashi to Watashi: Futari no Lotte', 'TV', 29, 'Completed', '1991-11-09', '1992-09-05', '7', 'Outspoken Luise and shy Lotte meet at summer camp and realize they are identical twins who were separated at birth by their divorced parents. The girls become friends and decide to switch places with each other so that they can each learn about the parent they never knew, and perhaps bring together their broken family.', 1036, 'https://cdn.myanimelist.net/images/anime/10/17854.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Machine-Doll wa Kizutsukanai', 'TV', 12, 'Completed', '2013-10-07', '2013-12-23', '7', 'The Walpurgis Royal Academy of Machinart was founded alongside the development of "Machinart," machine magic capable of giving life and intelligence to mechanical dolls subsequently called as "automaton." Its aim: train skilled puppeteers to control the automatons, as militaries across the globe have begun incorporating Machinart into their armies.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hiatari Ryoukou!', 'TV', 48, 'Completed', '1987-03-29', '1988-03-20', '7', 'Kishimoto Kasumi, a 15-year-old girl, was supposed to live at her auntie''s house in order to go to high school since April. However, when she moved to the house she was surprised with the fact that there were already four new male students living in the same house. To make the matter worse, that day while she was taking a bath, Takasugi Yusaku, one of those boys, came into the bath and saw her naked. This is how Kasumi''s troublesome high school days started. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahoutsukai Tai!', 'OVA', 6, 'Completed', '1996-05-25', '1997-10-25', '7', 'One sunny day invaders came from space. They weren''t little green men or funny girls wearing school uniforms, though. They were ugly robots which defeated the UN forces in seconds. After that the invaders (known as "eyeballs") roamed around and observed human society. In fact, they were peaceful unless attacked. They were polite and followed all the traffic laws, too. Still, they were aliens and the people of Earth wanted them to go home. The Kitanohashi High School Magic Club took it on themselves to defeat these foul robots and free the world. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boku wa Tomodachi ga Sukunai: Relay Shousetsu wa Ketsumatsu ga Hanpanai', 'OVA', 1, 'Completed', '2012-09-26', NULL, '7', 'When the Neighbor''s Club struggles to find an activity to do, Kodaka Hasegawa suggests they pass the time by writing a round-robin story—a narrative where everyone takes turns writing a section. But as they begin the project, chaos ensues as every member writes the story according to their personal preferences while trying to outdo each other. At this rate, will the story ever reach a fitting conclusion?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan OVA 12: Excalibur no Kiseki', 'OVA', 1, 'Completed', '2012-05-24', NULL, '7', 'The Miracle of Excalibur is the twelfth OVA of the anime and manga franchise Detective Conan. The plot is based on Gosho Aoyama''s short story "Excalibur."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tottoko Hamtarou', 'TV', 296, 'Completed', '2000-07-07', '2006-03-31', '7', 'He''s small, fluffy, and absolutely adorable: Hamtarou is one perfect little hamster! After moving to a new house with his owner, 5th grader Hiroko Haruna, Hamtarou discovers other hamsters and quickly makes friends.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Code Geass: Hangyaku no Lelouch Recaps', 'Special', 2, 'Completed', '2006-12-01', '2007-02-16', '7', 'Recap episodes of Code Geass. Also known as episodes 8.5 and 17.5.', 974, 'https://cdn.myanimelist.net/images/anime/7/22569.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Akazukin Chacha OVA', 'OVA', 3, 'Completed', '1995-12-06', '1996-03-06', '7', 'Following the original TV series, the story tells the efforts of Momiji Gakuen, Chacha''s rival school principal, to discover what is so special about Urara Gakuen students and what she could do to "produce" the best students.', 325, 'https://cdn.myanimelist.net/images/anime/1404/95392.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Animal Yokochou', 'TV', 51, 'Completed', '2005-10-04', '2006-09-26', '7', 'On the first day her family moved to their new house, 5-year-old Ami-chan made friends with three talking animals who came out of a door in her bedroom floor, which she finds out leads to Animal Yokocho, another world. The three are Issa, an overly innocent, soft-spoken panda, Kenta, a highly strung, red-scarf-loving bear who puts on an almost constant tough-guy act, and Iyo, a rabbit who usually holds her own well-being and enjoyment over the happiness (and safety) of her friends. Even at only 5 years old, Ami-chan is easily the most rational of the group, and she''s a little wary at first, but she eventually comes around and starts spending her free time with them. A typical day involves Ami-chan and the three doing different things to pass the time, often playing a seemingly innocent game, but in AniYoko style. Unfortunately for Ami-chan, the AniYoko version usually turns out to be drastically different, much less logical, and usually more dangerous than the ordinary version.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Red Garden', 'TV', 22, 'Completed', '2006-10-04', '2007-03-14', '7', 'Strange suicides have been taking place in New York. One day, four girls from the same high school wake up in the morning feeling tired and dizzy and not being able to remember anything about the previous night. In school, they find out that one of their classmates has committed suicide. School is canceled for the rest of the day, but instead of going home, the girls are drawn to a park by butterflies only they can see. Suddenly a man and a woman approach the girls, telling them that they all died the previous night. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Crayon Shin-chan Movie 19: Arashi wo Yobu Ougon no Spy Daisakusen', 'Movie', 1, 'Completed', '2011-04-16', NULL, '7', 'Comical action spy film including an indecent material (flatus) and a story of a girl who had obeyed her parents, but becomes self-aware. A mystery spy girl Lemon Sunomono suddenly appears in front of Shinnosuke, and she calls herself an emissary of Action Kamen. She had trained as a spy by her parents in the Sukashipestan Republic, and works for the Queens. Under her guidance, Shinnosuke decides to be a spy to fight for justice, and receives spy training. Under the instruction of Action Kamen, Lemon and Shinnosuke perform a mission to creep into the laboratory in the Hedelna Kingdom and recapture a capsule from an evil professor, but Lemon finds the real purpose of the Queens, and they fight to foil the plot of the Queens. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Happy Birthday: Inochi Kagayaku Toki', 'Movie', 1, 'Completed', '1999-07-27', NULL, '7', 'After being abused by her mother physically and mentally Asuka gets taken in by her grandparents. Slowly she learns her own worth as a human being and overcomes many obstacles.', 540, 'https://cdn.myanimelist.net/images/anime/1567/94728.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuro no Shoukanshi', 'TV', 12, 'Completed', '2022-07-09', '2022-09-24', '7', 'To prepare for reincarnation in another world, Kelvin gives up select memories from his previous life in exchange for powerful abilities, additional skill points, and an S-class summoner title. As a bonus, the goddess facilitating his rebirth, Melfina, offers him a choice of any companion to give him a head start in his summoner role. Kelvin—who has fallen head over heels for Melfina at first sight—promptly chooses the deity, confident that his passionate feelings for her will resurface even without all of his memories.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Neko ni Naritai Tamagawa-kun', 'Special', 1, 'Completed', '2025-01-05', NULL, '7', 'For Tamagawa, volunteering at a cat café is the only relief from his stressful job. The manager tells him to, "relax and learn to be spoiled," but he doesn''t know what that means until a new customer, Rai Shindou, comes to the café and tells Tamagawa he wants to keep him as a cat! Enter their strange, but fateful relationship. A pure-hearted and soothing romantic comedy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Star Wars: Visions Volume 3', 'ONA', 9, 'Completed', '2025-10-29', NULL, '7', 'Third volume of Star Wars: Visions.', 704, 'https://cdn.myanimelist.net/images/anime/1007/151669.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Anhe Zhuan Part 2', 'ONA', 14, 'Completed', '2024-04-17', '2024-07-10', '7', 'The second part of Anhe Zhuan.', 672, 'https://cdn.myanimelist.net/images/anime/1556/142631.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Good Night World', 'ONA', 12, 'Completed', '2023-10-12', NULL, '7', 'In the online game "Planet," there is a powerful team of four players. This team goes by the name "The Akabane Family," and its members are a pseudo-family that only exists in the game. Although they aren''t aware of it, these four players are actually a broken family in real life.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yarinaoshi Reijou wa Ryuutei Heika wo Kouryakuchuu', 'TV', 12, 'Completed', '2024-10-09', '2024-12-25', '7', 'Jill Savelle—fiancée of the crown prince Gerald der Kratos and known as the "Lady Goddess of War"—is being hunted down by the same country she swore to protect. Betrayed by her betrothed, she is framed as a traitor and imprisoned. In her last moments, Jill is filled with regret, but just as death approaches, she awakens six years in the past. This time, she will not be a mere pawn.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yu☆Gi☆Oh! The Dark Side of Dimensions Special: Eien no Rival - Yuugi to Kaiba!', 'Special', 1, 'Completed', '2016-04-17', NULL, '7', 'A summary special hosted by Jounouchi and Mokuba discussing the rivalry between Yuugi and Kaiba. They introduce the setting of the series, recap the best quotes from both Yuugi and Kaiba and their ace monsters, show highlights of their duel in Battle City, and lastly showcase the first 3 minutes of the film a week before it is released in theaters.', 325, 'https://cdn.myanimelist.net/images/anime/11/81859.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('No Game No Life Specials', 'Special', 6, 'Completed', '2014-06-25', '2014-11-26', '7', 'Picture drama specials included on the Blu-ray/DVD volumes.', 538, 'https://cdn.myanimelist.net/images/anime/7/71783.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bakuretsu Tenshi', 'TV', 24, 'Completed', '2004-04-07', '2004-09-15', '7', 'In Japan''s not-too-distant future, crime has become so common that the government has legalised firearms for citizens to use in self-defence. To combat this new wave of wrongdoing, the Recently Armed Police of Tokyo was established in hopes of hunting down criminals with lethal force.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mecha-ude', 'ONA', 1, 'Completed', '2018-09-30', NULL, '7', 'Long ago, alien lifeforms came to Earth, fusing with people on the planet. Due to their appearance, they were dubbed "Mecha-ude," as when fused, they bore a striking resemblance to mechanized limbs.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oscar''s Oasis', 'TV', 78, 'Completed', '2011-02-28', '2011-06-15', '7', 'Oscar is a lizard living in a non-specific desert that has features from several different real deserts, like the Sahara, Kalahari Desert, and North American deserts. An asphalt concrete highway runs through the area, used from time to time by various cargo trucks. Oscar is generally searching for food or water; he sometimes discovers liquid, in bottles or elsewhere, but is usually frustrated from recovering it for drink. An oasis supplies the only fresh water in the area, but its thick population of irascible and hungry crocodiles renders it inaccessible. At considerable personal risk (lizard is a delicacy for chickens), Oscar occasionally manages to steal an egg from a nearby hen coop, and he sometimes explores one of the piles of trash that litter the parched landscape. Popy, a fennec fox; Buck, a vulture; and Harchi, a hyena, inhabit a derelict school bus situated on a neighboring hill, but they mostly race about on a cast-off warehouse or grocery cart powered by Harchi and directed by Popy. Like Oscar, the trio constantly search for food and water - often competing with him, sometimes abusing him as a means, but occasionally cooperating with him when it suits their purpose. The main characters often find themselves falling off cliffs a la Wile E. Coyote chasing the Road Runner, wherein the law of gravity is briefly suspended while the character comes to realize their imminent doom.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece: Long Ring Long Land-hen', 'Special', 1, 'Completed', '2015-12-11', NULL, '7', 'A 75-minute recap of episodes 207-219, covering the Long Ring Long Land Arc. It was only aired once and was never released on home video.', 1030, 'https://cdn.myanimelist.net/images/anime/12/83503.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Marulk-chan no Nichijou', 'Movie', 4, 'Completed', '2020-01-17', '2020-02-07', '7', 'Shorts played before Made in Abyss Movie 3: Fukaki Tamashii no Reimei in Japan''s theatrical screenings.', 480, 'https://cdn.myanimelist.net/images/anime/1331/135406.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nisekoimonogatari', 'Special', 1, 'Completed', '2015-04-01', NULL, '7', 'Trailer for a fake crossover anime created by Shaft as an April Fools'' Day joke, celebrating their 40th anniversary.', 791, 'https://cdn.myanimelist.net/images/anime/1940/121746.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dash! Yonkurou', 'TV', 25, 'Completed', '1989-10-03', '1990-03-27', '7', 'The story is a succession of races in imaginative paths and runs to suit her run. The story will focus increasingly what is the real Emperor, will be discovered having this many mini title that will compare against the Emperor of Yonkuro, the epilogue to the epic challenge of the Rally of hell in this race will challenge a group of thugs who want to take advantage of Best of Mini 4WD racers to be able to recover a hidden treasure.The story centers on a brother and sister, Tatsuya and Kiyoko, the children of a scientist at the Twin X facility. This story is used by the very popular main character Yonkuro Hinomaru.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rockman.EXE Beast+', 'TV', 26, 'Completed', '2006-04-08', '2006-09-30', '7', 'Beast+ continues from where Beast left off, though it is marketed as a stand-alone series. Episodes are reduced to approximately ten minutes in length, airing in the thirty minute time-slot Oha Coliseum alongside the Saru Getchu anime. Beast+ consists of a string of arcs beginning with the appearance of the Professor and Zero (both from Mega Man Network Transmission). 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('CB Chara Go Nagai World', 'OVA', 3, 'Completed', '1991-02-21', '1991-06-27', '7', 'Various characters from Go Nagai works including Devil Man, Mazinger, and Violence Jack, become trapped in a parody world where they all become super deformed. They get trapped in this mishmash, fighting each other and are trying to figure a way back to their own world.', 1053, 'https://cdn.myanimelist.net/images/anime/1318/118557.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon Omega Ruby & Alpha Sapphire: Mega Special Animation', 'ONA', 1, 'Completed', '2014-11-16', NULL, '7', 'The Pokemon Company streamed the "Mega Special Animation" short inspired by the upcoming Pokémon Omega Ruby and Pokémon Alpha Sapphire games on Sunday. The short features Pokémon undergoing the newly discovered Mega Evolution and Primal Reversion in the Hoenn region.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('30th Gundam Perfect Mission', 'OVA', 1, 'Completed', '2009-08-25', NULL, '7', '30th Gundam Perfect Mission is a short original video animation (OVA) officially released by Sunrise in celebration of the 30th anniversary of the Gundam metaseries. It features all the titular and mascot gundams of the main series in a non-cannon conjoint mission.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mijikamon', 'ONA', 12, 'Completed', '2014-07-03', '2014-09-28', '7', '2-minute specials for Barakamon featuring chibi characters. These specials were streamed exclusively on YouTube only in Japan after every episode of the main series.', 480, 'https://cdn.myanimelist.net/images/anime/11/75964.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cardfight!! Vanguard Movie: Neon Messiah', 'Movie', 1, 'Completed', '2014-09-13', NULL, '7', 'A hybrid anime/live-action movie for the series to be released Fall 2014.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('F', 'TV', 31, 'Completed', '1988-03-09', '1988-12-23', '7', 'Gunma Akagi, a teenager from the countryside, frequently causes a ruckus with his turbocharged tractor, much to the chagrin of his father, aspiring politician Souichirou Akagi, who urges the family to set a good example to ensure his success.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Neo Angelique Abyss', 'TV', 13, 'Completed', '2008-04-07', '2008-06-30', '7', 'While the young Angelique lives out her days peacefully in her school, attacks from the monstrous Thanatos has been increasing everywhere else. Two Purifiers show up one day, men with the power to exterminate the Thanatos. One of them, Nyx, attempts to convince Angelique to join them in their work, as she has the power to be the only female Purifier. As Angelique hesitates, a Thanatos shows up in their school. Nyx and the other Purifier, Rayne, fight a losing battle. With her classmates falling prey to the Thanatos, and the Purifiers beaten to submission, Angelique''s desire to save everyone awakens. She became the only female Purifier in their land of Arcadia, the one known as the "Queen''s Egg".', 1141, 'https://cdn.myanimelist.net/images/anime/3/20960.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gakuen Handsome', 'TV', 12, 'Completed', '2016-10-04', '2016-12-20', '7', 'High school student Yoshiki Maeda is starting a new year in the all-boys Baraman High School. On the first day, Yoshiki reconnects with his childhood friend, Takuya Saotome, and meets his odd and dramatic homeroom teacher, Teruhiko Saionji. Yoshiki''s younger sister, Yuu, is aware of many of these handsome boys and seems to take pleasure in teasing her big brother about them.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koko wa Green Wood', 'OVA', 6, 'Completed', '1991-11-22', '1993-03-26', '7', 'Hasukawa Kazuya is in a terrible bind. His brother''s new wife is also the woman that Kazuya secretly loves. Determined to avoid them both, Kazuya leaves home to live in the student dorm called Greenwood. There, he hopes to find peace of mind. Unfortunately for Kazuya, stability and peace are the last things one might find at Greenwood - home of the weirdest characters on campus.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Peter Pan no Bouken', 'TV', 41, 'Completed', '1989-01-15', '1989-12-24', '7', 'Wendy and her two little brothers are brought to the land of adventures, Neverland, by Peter pan, a boy who will never grow up. In Neverland they encounter exciting events and meet with little fairies, mermaids, Indians, and pirates. Required to act as a mother, Wendy never has a moments peace with all that is happening around her, including breath-taking fights with pirates. Later in the series, they set off to find a buried treasure with a map that they obtain from the pirates.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jigoku Sensei Nube: Kyoufu no Natsuyasumi!! Ayashi no Umi no Densetsu!', 'Movie', 1, 'Completed', '1997-07-12', NULL, '7', 'When Nube and his class arrive at a small island to carry out beach activities, they heard a forbodding tale from an old man residing on the island. Legend has it that there is a creature known as the sea spider in the open seas around the island. When the creature is past 200 years old, it will turn into a monster and devour humans to satisfy its appetite. However, curiousity kills the cat and Yukime decides to pursue the authenticity of the legend. And then, a girl suddenly appears on the beach. Possessed with a strange charm, she immediately attracts Hiroshi''s attention and overcomes him. Soon later, strange things start to happen to the others whereby Kyoko and Ritsuko-sensei got attacked under strange circumstances. The true identity behind the mysterious girl is questioned and the legend behind the sea creature seems to be true after all.', 1030, 'https://cdn.myanimelist.net/images/anime/9/21282.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Super Robot Taisen OG: Divine Wars', 'TV', 25, 'Completed', '2006-10-05', '2007-03-29', '7', 'It is two hundred years after the beginning of the Space Era, when human civilization on Earth began expanding into space. However, by the start of the 21st century, two meteors struck the planet, sending humanity into chaos. By the year 179 of the Space Era, secret technology, dubbed Extra-Over Technology, or EOT, was discovered by the Earth Federal Government within a third meteor that hit Earth in the Marquesas Islands of the South Pacific. Dr. Bian Zoldark, head of the EOTI Institute (Extra-Over Technological Investigative Institute), had evidence the creators of the EOT were heading to Earth, in order to reclaim it...or worse, invade the planet. In order to defend humanity from extraterrestrial threats, the government begins to research and develop humanoid mecha called Personal Troopers.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Koihime†Musou', 'TV', 12, 'Completed', '2009-10-05', '2009-12-21', '7', 'Following the battle for Touka Village and clearing the area of bandits, Unchou Kan''u, Chouhi Yokutoku, and Shokatsuryou Koumei prepare for the next step of their journey. They encounter someone surprising—a young woman claiming to be Gentoku Ryuubi! After being framed for various crimes, Ryuubi is on a mission to reclaim her family heirloom, the sword of Chuuzan Seiou, and clear her name from the evil deeds she allegedly committed.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yu☆Gi☆Oh! Zexal Special', 'Special', 1, 'Completed', '2012-09-17', NULL, '6', 'A short special aired in the middle of information about Yu-Gi-Oh! with real people.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Arata naru Sekai: World''s/Start/Load/End', 'OVA', 1, 'Completed', '2012-10-20', NULL, '6', 'Four high school girls in uniforms walk silently on the barren earth. These girls are time travelers who had been sent 6000 years into the future, from their present in which the same day is endlessly repeated, in order to evade human extinction.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('TO-Y', 'OVA', 1, 'Completed', '1987-10-01', NULL, '6', 'To-Y Fujii is the frontman of GASP, a band rapidly growing in popularity in Tokyo''s underground punk scene. Just when it seems like the band has gotten their big break and booked a major venue, an executive from the large Koyama Productions tries to scout To-Y as a solo act. Unwilling to abandon his bandmates, he boldly declares that he does not need Koyama''s support. However, when the spurned executive starts to put obstacles in their way, To-Y must decide if his integrity is worth holding on to.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Getsumen to Heiki Mina', 'TV', 11, 'Completed', '2007-01-14', '2007-03-25', '6', 'An animated spin-off from the Densha Otoko (Trainman) TV drama.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Young Herlock wo Oe! Cosmo Warrior Zero Gaiden', 'Special', 2, 'Completed', '2002-06-21', NULL, '6', 'Space captain Warrius Zero, who lost his family to evil cyborgs, wages battle against Captain Harlock, a space rebel defending the Machine Men.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Babel Nisei', 'TV', 39, 'Completed', '1973-01-01', '1973-09-24', '6', 'Life seems simple for Koichi, a young student, until he learns that he is the reincarnation of an alien protector who crashed onto the mantle of responsibility as "defender of the Earth," Koichi/Babel teams up with a trio of super-powered alien companions to battle the the dark forces of an evil cult leader. The war to save humanity takes Babel from the deserts of southern Asia to the upper east side of Manhattan and ultimately to a final showdown with "the master" in a hidden base nestled in the Swiss Alps. The action is fast-paced and deadly. The fate of the world rests in the ability of this courageous youth to tame his latent psychic power and use it to defeat the enemies of mankind.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece: Barto no Himitsu no Heya!', 'Special', 4, 'Completed', '2021-12-26', '2023-10-08', '6', 'Bartolomeo and a few mysterious guests recap the adventures of the Straw Hat Crew in the Land of Wano. From Monkey D. Luffy''s first encounter with Otama to even the worst generation pirates'' final confrontation with Big Mom and Kaido on the roof of Onigashima. The retelling of this exciting tale is just as riveting as the first.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tenshi Kinryouku', 'OVA', 3, 'Completed', '2000-05-25', '2000-08-25', '6', 'Setsuna Mudo is a 16-year-old high school student just trying to get by without running afoul of his bullying seniors. It doesn''t help that he''s in love with his younger sister, Sara, who only sees him once a month. But there''s more to his life than just keeping his head down.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Momentary Lily: Tsuzuiteiku Kappou, Kappou!', 'Special', 1, 'Completed', '2025-03-30', NULL, '6', 'Episode 14 of Momentary Lily. The episode released on AT-X and was later included in the BD volume 4.', 339, 'https://cdn.myanimelist.net/images/anime/1715/148881.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nohara Hiroshi: Hiru Meshi no Ryuugi', 'TV', 12, 'Airing', '2025-10-03', '2025-12-19', '6', 'This series follows Hiroshi Nohara''s ultimate lunchtime philosophy, as he carefully selects and enjoys his midday meals within the constraints of a limited budget and break time.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sawaranaide Kotesashi-kun', 'TV', 12, 'Airing', '2025-10-06', '2025-12-22', '6', 'Kouyou Kotesashi, possesses exceptional massage skills and dreams of becoming a sports doctor. To secure a scholarship to medical school, he enrolls at Seiwa University Affiliated High School, a powerhouse in athletics.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mashin Souzouden Wataru', 'TV', 24, 'Completed', '2025-01-12', '2025-06-22', '6', 'New Wataru project.', 116, 'https://cdn.myanimelist.net/images/anime/1550/145123.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Vampire Dormitory', 'TV', 12, 'Completed', '2024-04-07', '2024-06-23', '6', 'Homeless and fresh out of employment, Mito Yamamoto faces familiar loneliness and despair. Luck is simply not on Mito''s side; when he stumbles upon a cafe and cuts his hand, a strange server named Ruka Saotome licks the blood from his wound and even dramatically retches at its apparent disgusting taste. Offended and dispirited, Mito runs off to a bridge, hoping to put an end to his misery.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Suki na Ko ga Megane wo Wasureta Short Episode', 'ONA', 4, 'Completed', '2023-07-31', '2023-09-24', '6', 'Suki na Ko ga Megane wo Wasureta short anime streamed online and included with exclusive bonus episodes in the Blu-ray release of the show.', 339, 'https://cdn.myanimelist.net/images/anime/1023/138280.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kigyou Senshi Yamazaki: Long Distance Call', 'OVA', 1, 'Completed', '1997-10-25', NULL, '6', 'A 42-year-old salaryman is made to serve his company beyond the grave when his brain is installed in a super-powered android body in order to carry out corporate espionage.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bikkuriman 2000', 'TV', 68, 'Completed', '1999-11-01', '2001-02-22', '6', 'More adventures of Bikkuriman.', 871, 'https://cdn.myanimelist.net/images/anime/1477/96439.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shounen Sunday CM: Yugami-kun ni wa Tomodachi ga Inai', 'Special', 2, 'Completed', '2013-11-26', '2014-09-18', '6', 'Despite being the most talented player on the Kamihoshi High School baseball team, Yuuji Yugami is a loner and ostracized by his classmates. Yugami, however, is optimistic and adamant about remaining friendless—which is what he tells new transfer student Chihiro Watanuki.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wave!! Surfing Yappe!! (TV)', 'TV', 12, 'Completed', '2021-01-12', '2021-03-30', '6', 'Energetic and cheerful, 14-year-old Masaki Hinaoka takes his pet corgi on morning runs along the beach bathed in the rising sun. Suddenly, Masaki''s eyes sparkle in awe: a blond boy surfs, delicate and breathtaking, with a slight smile gracing his kind face. Before long, Masaki encounters him again as a new classmate named Shou Akitsuki.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kabatotto', 'TV', 300, 'Completed', '1971-01-01', '1972-09-30', '6', 'Thomas is a cunning bird who sponges on Hyppo, the good-natured hippopotamus. Although Thomas is a dependent, living in Hyppo''s big mouth, he always acts lordly and tries to outsmart his simpleminded host. However, their basic friendship and cooperation endures despite their frequent quarrels. The two play a prime role in this comic series, short yet full of originality. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kerokero Keroppi no Christmas Eve no Okurimono', 'OVA', 1, 'Completed', '1992-11-01', NULL, '6', 'A star who tries to act like an adult falls from the sky. Keroppi helps nurse it back to health and regain its confidence to shine once again.', 352, 'https://cdn.myanimelist.net/images/anime/1111/119463.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hengen Taima Yakou Karura Mau! Nara Onryou Emaki', 'Movie', 1, 'Completed', '1989-04-08', NULL, '6', 'Shoko and Maiko Ougi are apparently two ordinary schoolgirls in pursuit of graduating and having fun. Shii-chan is the more serious while Mai-chan is more fun-loving. In reality, the two sisters are powerful exorcists from the Karura temple. Each wields half the power...Shii-chan can "see" the spirits, and Mai-chan can banish them. This is the movie adaptation of a spooky series with heavy emphasis on traditionally Japanese occult themes. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mirai Kara Kita Shounen Super Jetter', 'TV', 52, 'Completed', '1965-01-07', '1966-01-20', '6', 'A time patroller from the 30th century goes back to the 20th century to stop a meteor from destroying the world.', 986, 'https://cdn.myanimelist.net/images/anime/13/68185.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chibikko Remi to Meiken Kapi', 'Movie', 1, 'Completed', '1970-03-17', NULL, '6', 'Based on Sans Famille by Hector Malot.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Regalia: The Three Sacred Stars Recaps', 'Special', 2, 'Completed', '2016-08-15', '2016-08-22', '6', 'Recap episodes of Regalia: The Three Sacred Stars narrated by Kaede Hondo.', 48, 'https://cdn.myanimelist.net/images/anime/1913/116144.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cleopatra D.C.', 'OVA', 3, 'Completed', '1989-04-28', '1991-05-24', '6', 'The Cleopatra Corns Group, aka Cleopatra DC, is a powerful financial conglomerate controlling most of the United States economy, almost as powerful as the US government itself. At the top of the organization is the beautiful, smart and brave Ms. Cleo, the Group''s young, talented Chairman. This is good--it means she can handle the repair bill when that airplane crashes into her bedroom. With stolen artifacts, corporate kidnappings, and top-secret cyborg projects gone awry, her luck only gets worse from there. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Haitai Nanafa', 'TV', 13, 'Completed', '2012-10-06', '2012-12-29', '6', 'Nanafa Kyan lives in Okinawa with her grandmother who runs the "Kame Soba" soba shop, her beautiful older sister Nao who is in high school, and her younger sister Kokona, who is in elementary school and has a strong ability to sense the supernatural.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Vocaloid China Project Senden Animation', 'Special', 5, 'Completed', '2012-06-07', '2012-11-14', '6', 'A 3-minute full animation promotion video series of the Chinese Vocaloid 3 Package.', 788, 'https://cdn.myanimelist.net/images/anime/11/39405.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Otome Nadeshiko Koi Techou', 'OVA', 1, 'Completed', '2012-01-26', NULL, '6', 'The story follows a 16-year-old girl who is experiencing her first love during Japan''s Taishou period (1912-1926).
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mitsu x Mitsu Drops', 'OVA', 2, 'Completed', '2006-04-28', '2006-07-28', '6', 'Students at the Houjou academy are perfectly normal—except for those who take the Kuge course. This special course is reserved only for elite and rich students and their "honeys." Hagino Yuzuru enrolls in the course through Kai Renge, and she quickly regrets it.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lupin tai Holmes', 'Special', 1, 'Completed', '1981-05-05', NULL, '6', 'Based on a story by Maurice Leblanc.', 1030, 'https://cdn.myanimelist.net/images/anime/1412/139527.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Umi Monogatari: Kanon to Iku Amamikoshima', 'ONA', 13, 'Completed', '2009-07-01', '2009-09-25', '6', 'Short ONA specials of Umi Monogatari that were originally released on the official website and later included on DVD volumes. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dolls'' Frontline', 'TV', 12, 'Completed', '2022-01-08', '2022-03-26', '6', 'After World War III decimated the world''s population and rendered large amounts of land uninhabitable, various private military contractors began using combat androids—also known as "T-Dolls"—to maintain peace in unstable countries. While they are physically superior to flesh-and-blood fighters, T-Dolls are incapable of formulating complex plans and thus require a human commander to issue orders.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kanojo, Okarishimasu 3rd Season: Kanokari Call', 'Special', 25, 'Completed', '2023-11-29', '2023-12-20', '6', 'A short type of picture dramas released with blu-ray volumes 1-2 of Kanojo, Okarishimasu 3rd Season.', 990, 'https://cdn.myanimelist.net/images/anime/1962/141902.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Million Doll: Otaku Go Kouza', 'Special', 1, 'Completed', '2015-11-20', NULL, '5', 'Picture drama included in the BD that explains various otaku terms used in the show.', 90, 'https://cdn.myanimelist.net/images/anime/1768/113956.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yurumi to Shimeru', 'ONA', 1, 'Completed', '2008-04-03', NULL, '5', 'The Mukai siblings, Sunao and Ai, were having a normal day, when suddenly, a space ship suddenly fell into the yard of their house!? What came from within the ship was a little girl who called herself Yurumi. "We''re from the cosmic repair shop, ''Rutsubo Mechanic Company,''" said another girl, Yurumi''s partner, Shimeru, who stepped out afterwards. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hulaing Babies Aratame - Staying Babies: Chikyuu wo Mamore! Staying Babies with Yuusha Hayami-san', 'ONA', 1, 'Completed', '2020-07-19', NULL, '5', 'Episode 4.5 of Hulaing Babies Aratame - Staying Babies.', 306, 'https://cdn.myanimelist.net/images/anime/1345/108661.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('MapleStory Special', 'Special', 1, 'Completed', '2008-09-26', NULL, '5', 'Unaired episode of the MapleStory series included on the 9th DVD Volume.', 538, 'https://cdn.myanimelist.net/images/anime/12/68281.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Teinenpi Shoujo Heidi', 'ONA', 8, 'Completed', '2009-05-01', '2010-07-01', '5', 'Commercial web animation made for Nissan Note. Despite being a commercial, the content is highly independent, starting with a little girl keep asking everyone what is "Teinenpi", a kanji word meaning low fuel cost. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Arabian Night: Sindbad no Bouken', 'Movie', 1, 'Completed', '1962-06-16', NULL, '5', 'This is a work by Toei Animation Co., Ltd. with screenplay by Tezuka Osamu in cooperation with novelist Kita Morio. Sinbad and a boy, Ali, are stowaways on the transport ship "Boulder," but they win their proper places on the ship after currying the favor of the captain. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seihou Tenshi Angel Links: Meifon no Special Kaisetsu Corner', 'Special', 1, 'Completed', '2000-01-01', NULL, '5', 'Meifon (and Taffei) talk about the space ships and equipment the Angel Links organization uses to carry out its mission.', 974, 'https://cdn.myanimelist.net/images/anime/5/61647.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shiritsutantei: Toki Shouzou Trouble Note - Hard & Loose', 'OVA', 1, 'Completed', '1992-01-07', NULL, '5', 'Based on the manga by Tsuchiya Garon (aka Marley Carib), art by Kawaguchi Kaiji, serialised in Action in the 80s.', 86, 'https://cdn.myanimelist.net/images/anime/8/55271.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dounika Naru Hibi', 'Movie', 1, 'Completed', '2020-10-23', NULL, '5', 'Love is love. Someday, the pain of being in love will be an endearing memory. No matter who the feelings are toward, no matter what form it takes, all love and lifestyles have the same value. An omnibus anime tells the stories of "The wedding of an ex," "a student and a teacher at an all-boys'' school," and "childhood friends whose bodies and hearts change with adolescence."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yawaraka Atom', 'ONA', 7, 'Completed', '2007-10-01', '2008-10-01', '5', 'Yawaraka Atom, a parody of Astro Boy (Atom) as a squishy tank, went to stop catastrophe and evil.', 281, 'https://cdn.myanimelist.net/images/anime/8/56203.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('DPR Special Movie', 'Special', 1, 'Completed', '2013-10-17', NULL, '5', 'An anime made for JAXA (Japan Aerospace Exploration Agency) and NASA (National Aeronautics and Space Administration) that promotes the GPM/DPR (Global Precipitation Measurement/Dual-frequency Precipitation Radar) space mission.', 1102, 'https://cdn.myanimelist.net/images/anime/13/56803.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Otona no Bouguya-san (Rimen)', 'ONA', 3, 'Completed', '2019-03-06', '2019-03-20', '5', '', 405, 'https://cdn.myanimelist.net/images/anime/1191/99230.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sparrow''s Hotel', 'TV', 12, 'Completed', '2013-04-09', '2013-06-25', '5', 'The comedy revolves around Sayuri Satou, the new front desk worker at the Sparrow''s Hotel—"the closest hotel to Heaven". Her special features are her large breasts and her skills of assassination. She takes down people who cause trouble in the business hotel with those skills, but she is in fact very unskilled when talking to the male hotel manager, and often bites her tongue.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Arisa☆Good Luck', 'OVA', 1, 'Completed', '1999-10-30', NULL, '5', 'Arisa, a 16-year-old high school girl, accidentally has an extreme fighting suit that her brother invented implanted in her body. It''s a slightly embarrassing suit that makes her emit an H voice when she transforms. Moreover, from that day on, Arisa is forced against her will to fight a secret society of evil.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Big Wars: Kami Utsu Akaki Kouya ni', 'OVA', 1, 'Completed', '1993-09-25', NULL, '5', 'It is the dawn of the 21st century. Mankind has terraformed and colonized Mars. But we are not alone in the universe. An ancient race of alien beings, known only as "The Gods," has been watching mankind''s progress ...and waiting. Now, these mysterious aliens have returned to halt mankind''s expansion into space ...by force.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ramen Chai-nyan', 'OVA', 1, 'Completed', '2001-02-14', NULL, '5', 'Chai Nyan is a 14-year-old girl who came all the way from China to spread the way of Ramen! However, a drunk named Yoiyoi refuses to accept that Chai Nyan''s ramen shop neither sells alcohol nor allows drinking. And so, the drunk decides to destroy the shop with robots and so on. Will Chai Nyan be able to weather this storm?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ashita no Eleven-tachi', 'Special', 1, 'Completed', '1979-01-07', NULL, '5', 'A boy from the farm with amazing running speed is asked to join a newly formed national soccer team and discovers a natural talent for the game. The movie is inspired by Japan''s hosting of the world soccer championships that year.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Himitsu no AiPri Movie: Mankai Buzzlume Live!', 'Movie', 1, 'Upcoming', '2026-03-13', NULL, '5', 'First Himitsu no AiPri movie.', 621, 'https://cdn.myanimelist.net/images/anime/1091/153909.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Quanneng Gaoshou', 'ONA', 20, 'Airing', '2025-11-01', NULL, '5', '"I came from the wilderness, raised by five incredibly powerful grandparents. To uncover the truth behind my parents'' murder, I return to the city." Watch as this young hero, skilled in martial arts, music, chess, medicine, and cooking, feigns weakness to outsmart others, surrounded by beautiful women, rises against all odds, solves a shocking mystery, and vows to become the city''s all-around master, the undisputed ruler of this land!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Prism Rondo', 'ONA', 20, 'Upcoming', '2026-01-15', NULL, '5', 'In early-1900s London, Lili Ichijouin, a Japanese exchange student travels to England to enroll in the prestigious Saint Thomas Art Academy. Determined to become a painter, she arrives under pressure: her parents expect her to rise to the top of her class within six months or return home.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tadaima, Ojamasaremasu!', 'TV', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'So is this what it means to have roommates now?! Office worker Rinko, 24, lives alone and is secretly an otaku. One day, her apartment gets connected to the two neighboring rooms through a "hole" in the wall.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chiikawa Movie: Ningyo no Shima no Himitsu', 'Movie', 1, 'Upcoming', '2026-01-01', NULL, '5', 'Anime adaptation of the Siren arc.', 206, 'https://cdn.myanimelist.net/images/anime/1110/153808.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Long Hun', 'ONA', 11, 'Airing', '2025-12-01', NULL, '5', 'For millennia, the ancient and mysterious Dragon Clan has thrived on the Central Continent. Yet the struggle between the Light and Dark Souls of the Divine Realm drags the dragons into conflict. The clan is torn apart by brutal civil strife, facing the threat of extinction. In this desperate hour, Ao Xue, the long-absent prince of the East Sea, returns with formidable power, determined to save the Dragon Clan from peril.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tian Guan Xueyuan', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'To resist invasions from other worlds, the Heavenly Great Sage founded Tianguan Academy. Every year, the Academy would recruit new students—but in the end, only nine could become the official Heavenly Officers. Gu Tian, a young soccer player, accidentally awakened his hidden power while saving someone on the field. Invited by his senior Xia Zhi, he boarded Subway Line 36 to Tianguan Academy. With the world''s finest teachers, strict assessments, and a brutal elimination system, the Academy pushes its students to the limit. By a stroke of fortune, Gu Tian became the 81st student to pass the entrance trial. Under the guidance of celestial masters, he studied spells and divine decrees, honed his combat skills against powerful rivals, and strode forward step by step toward the ultimate goal of becoming one of the Nines.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ye Bu Shou', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', '2283, in a post-nuclear wasteland, Fortress City 021 was controlled by Ark Corporation. Their so-called "Savior Guardians" appeared to protect humanity but secretly conducted human experiments using X chips and manipulated public opinion. Young Han Che witnessed his brother''s murder by the false Guardians and unexpectedly awakened the "1307 Source System" within him, gaining superpowers. He joined the Yebushou organization, rebuilt by Guan Shanhu, and fought alongside hacker Tian Xin and engineer Kang Di. Yebushou infiltrated Ark training camps and Ghost Island Prison, exposing a plot to create a superpowered army using experiments and mutants. As Han Che unlocked new abilities and faced formidable enemies like Emperor Angel and Divine-Eye Immortal, he embarked on a path of vengeance, truth, and salvation. However, the hidden AI "Lefu" was plotting to control all human consciousness.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yi Zhan Cangqiong', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'In the darkest moment of Celestial Realm, the crippled youth Gu An seized the power of an ancient god amid life-or-death peril. Wielding infinite spiritual energy and a mortal blade, he destroyed evildoers, avenged deep grudges, and struck down the heavens.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sanxian Lun Hui', 'ONA', 18, 'Airing', '2025-12-05', NULL, '5', 'The Yellow River, Yangtze River, and Lancang River originate from the same source, and three families known as "Water Evils" (Ding, Jiang, and Yi) live along the river. What are "Water Evils"? They can move freely in the water and possess the skills of geomancy, feng shui, and treasure hunting. Yi Sa, the last Water Evil of the Yi family, runs an "underwater bank" business along the Lancang River. During a "Golden Fortress" excavation, Yi Sa encounters and saves Zong Hang. To uncover the truth of what happened and to save himself, Yi Sa trains Zong Hang to become a professional Water Evil, and together with Ding Yudie, a Water Evil from the Ding family, the three enter the "Ancestral Golden Fortress."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('You Shou Yan 5th Season', 'ONA', 12, 'Upcoming', '2026-02-01', NULL, '5', 'Fifth season of You Shou Yan.', 284, 'https://cdn.myanimelist.net/images/anime/1383/153742.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shi Yiren', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'A low-level office worker accidentally consumed a demon and underwent a mutation. Struggling to survive, he hunted evil, seeking light and justice.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiong Chumo: Nizhuan Shikong', 'Movie', 1, 'Completed', '2024-02-10', NULL, '5', '', 280, 'https://cdn.myanimelist.net/images/anime/1572/140109.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Random Chatting-ui Geunyeo PV', 'Special', 1, 'Completed', '2018-12-24', NULL, '5', 'Promotional video for the Naver Webtoon manhwa Random Chat.', 948, 'https://cdn.myanimelist.net/images/anime/1445/140128.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiong Chumo: Ban Wo "Xiong Xin"', 'Movie', 1, 'Completed', '2023-01-22', NULL, '5', '', 280, 'https://cdn.myanimelist.net/images/anime/1098/140063.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fiction Shigi Yama', 'Movie', 1, 'Completed', '2023-04-17', NULL, '5', 'A story about a dharmapala, a Buddhist deity that often takes on the form of a child, who helps a monk on various adventures. From healing a sick emperor to returning a stolen rice bowl, this charming story is rooted in the mythology of Chougosonshi-ji temple on Mt. Shigi in Nara, Japan.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shuwawan!', 'TV', NULL, 'Airing', '2023-03-22', NULL, '5', 'Shuwawan! chronicles the family life of real-life photographer and essayist Harumichi Saitou. Saitou and his wife are both deaf, his children are both hearing, and the family communicates in sign language. The anime draws on Saitou''s own Ikuji Manga Nikki (Child-rearing Manga Diary) work.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sanguo Yanyi 2nd Season: Zhulu Zhongyuan', 'ONA', 20, 'Completed', '2019-04-23', '2019-08-27', '5', '', 1132, 'https://cdn.myanimelist.net/images/anime/1141/126921.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sakura to Sakurin', 'OVA', 1, 'Completed', '2012-01-01', NULL, '5', 'Sakura is a 3rd grader who meets a cherry blossom (sakura) spirit named Sakurin when she visited a cherry blossom park. She shows her the history of the park and how the mini forest came to be as it was humans who caused deforestation but also humans who realized their mistake and fixed situation.', 265, 'https://cdn.myanimelist.net/images/anime/1825/98612.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wan Sheng Jie 3', 'ONA', 12, 'Completed', '2022-01-26', '2022-04-06', '8', 'Third season of Wan Sheng Jie.', 284, 'https://cdn.myanimelist.net/images/anime/1995/117071.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Slayers Next', 'TV', 26, 'Completed', '1996-04-05', '1996-09-27', '8', 'In the kingdom of Xoana, Lina Inverse and Gourry Gabriev unexpectedly come across their old companions, Zelgadis Graywords and Princess Ameilia Wil Tesla Saillune. Upon their reunion, the friends end up easily foiling the King of Xoana and his daughter''s dastardly plans of world conquest.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kono Subarashii Sekai ni Shukufuku wo! 2: Kono Subarashii Geijutsu ni Shukufuku wo!', 'OVA', 1, 'Completed', '2017-07-24', NULL, '8', 'On one noteworthy day in the Adventurer''s Guild, Kazuma Satou encounters someone unexpected—a fan of his named Ran. Surprised that he even has a fan, Kazuma attempts to play it cool to impress her. Unfortunately for him, the guild''s receptionist arrives with a request to defeat a giant golem guarding some ancient ruins, and Kazuma accepts only to keep Ran''s admiration.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Juuni Kokuki', 'TV', 45, 'Completed', '2002-04-09', '2003-08-30', '8', 'Youko Nakajima has only ever wanted to be normal. She does what she is asked, gets good grades, is the class president, and even helps her classmates whenever she can—but because of her red hair, she has never fit in. With her pushover attitude, Youko lets classmates take advantage of her, so she has nobody she can really call a friend.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ruri no Houseki', 'TV', 13, 'Completed', '2025-07-06', '2025-09-28', '8', 'While shopping, high school student Ruri Tanigawa is captivated by a crystal necklace. Due to its high price, she can only dream of owning one—until her mother tells her about a mountainous area where Ruri''s grandfather used to discover numerous minerals. As she makes her way to the location in the hope of finding materials to make her own accessories, Ruri meets Nagi Arato, a graduate student, who gladly shows her the way.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ao no Exorcist: Yosuga-hen', 'TV', 12, 'Completed', '2025-01-05', '2025-03-23', '8', 'Unlike his twin brother, Yukio, Rin Okumura never wished to know about their parents and the circumstances surrounding his own birth. Yet the master of time, Mephisto Pheles, gives Rin a key that transports him 40 years into the past when his late mother, Yuri Frederick Egin, was merely a child. With Mephisto''s guidance, Rin leaps through the years of Yuri''s childhood and her adolescence as an exorcist-in-training.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ranma ½ (2024)', 'TV', 12, 'Completed', '2024-10-06', '2024-12-22', '8', 'During their martial arts training expedition in China, Ranma Saotome and his father Genma suffered an accident, which in turn, afflicted them with a curse—whenever they are doused with cold water, Ranma transforms into a girl, while his father turns into a panda! Only hot water can reverse these changes, but any further contact with cold water opens the can of worms once more.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan Movie 15: Chinmoku no Quarter', 'Movie', 1, 'Completed', '2011-04-16', NULL, '8', 'The momentous day of the opening of the new Tokyo subway, the Touto Line, has come, but a bombing incident puts all celebrations to a halt. The governor of Tokyo is caught in the blast while onboard the train, but he and everyone else present is fortunately saved by the quick thinking and actions of Conan Edogawa.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam 0080: Pocket no Naka no Sensou', 'OVA', 6, 'Completed', '1989-03-25', '1989-08-25', '8', 'Alfred Izuruha is a 10-year-old who lives in the neutral colony cluster of Side 6 and, like most boys his age, is obsessed with the war between the Earth Federation and the Principality of Zeon. Unbeknownst to him, Al''s next-door neighbor, Christina, is the test pilot of a prototype Gundam being developed in secret by the Earth Federation in the colony. A Zeon Special Forces team is assembled and tasked with infiltrating the colony in order to either steal or destroy it.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Baby Steps 2nd Season', 'TV', 25, 'Completed', '2015-04-05', '2015-09-20', '8', 'After having decided to play tennis at the professional level, Eiichirou Maruo now needs to convince his parents to support his decision. To do so, he makes a wager: if he cannot win the All-Japan Junior Tennis Tournament, he will give up on his dream. However, he will need to improve his skills quickly if he wants to qualify for the tournament and have any chance of defeating the best players in the country. For this reason, his new coach Ryuuhei Aoi suggests that Eiichirou travel abroad to train at the Florida Tennis Academy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fullmetal Alchemist: Brotherhood Specials', 'Special', 4, 'Completed', '2009-08-26', '2010-08-25', '8', '1. Moumoku no Renkinjutsushi (The Blind Alchemist)
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tokyo Magnitude 8.0', 'TV', 11, 'Completed', '2009-07-10', '2009-09-18', '8', 'Middle school student Mirai Onozawa is dissatisfied with her family circumstances and, in a moment of frustration, wishes to tear everything apart. Unfortunately, these destructive thoughts seem to come true in the form of a magnitude 8.0 earthquake just a few moments later.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('BanG Dream! Movie: Episode of Roselia - II: Song I Am.', 'Movie', 1, 'Completed', '2021-06-25', NULL, '8', 'After overcoming numerous tribulations, the members of Roselia promised to appear on FUTURE WORLD FES.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Evangelion Movie 1: Jo', 'Movie', 1, 'Completed', '2007-09-01', NULL, '8', 'In a post-apocalyptic world, the last remaining human settlement in Japan is the heavily fortified city of Tokyo-3. Fourteen-year-old Shinji Ikari is brought to the headquarters of NERV, an underground organization lead by his estranged father, Gendou. He requests that Shinji become a pilot of an "Evangelion," a colossal android built to fight against monstrous and destructive alien creatures known as "Angels" that wreak havoc on the planet and threaten the survival of the remaining human race.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saiunkoku Monogatari 2nd Season', 'TV', 39, 'Completed', '2007-04-07', '2008-03-08', '8', 'Shuurei Kou and her friend Eigetsu To, a boy prodigy of humble origins, have been appointed co-governors of the Sa province, one of the eight provinces in Saiunkoku. Together, they decide to make the province an academic research center in the hopes of bringing a long overdue prosperity to the region.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('SK∞', 'TV', 12, 'Completed', '2021-01-10', '2021-04-04', '8', 'High school student Reki Kyan is passionate about one thing: skateboarding. When night falls, he heads to "S," an illegal underground race inside a mine where skaters compete in highly dangerous situations. After a loss that results in his skateboard being destroyed and his arm being broken, Reki is now incapable of practicing at all.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('D.Gray-man', 'TV', 103, 'Completed', '2006-10-03', '2008-09-30', '8', 'Losing a loved one is so painful that one may sometimes wish to be able to resurrect them—a weakness that the enigmatic Millennium Earl exploits. To make his mechanical weapons known as "Akuma," he uses the souls of the dead that are called back. Once a soul is placed in an Akuma, it is trapped forever, and the only way to save them is to exorcise them from their vessel using the Anti-Akuma weapon, "Innocence."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Magi: The Labyrinth of Magic', 'TV', 25, 'Completed', '2012-10-07', '2013-03-31', '8', 'A Magi is a magician whose inclination toward magic is so immense that they can be said to shape the world. With their significant influence, each Magi chooses a worthy candidate to become a king, then helps them conquer strange labyrinths called "Dungeons" and acquire the power of mythical djinns within. Above all else, the Magi supervises their elected representative as they build a country that might one day bring the world to its knees.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toaru Kagaku no Railgun S', 'TV', 24, 'Completed', '2013-04-12', '2013-09-27', '8', 'Mikoto Misaka and her friends are back, investigating rumors across Academy City. Soon, Mikoto discovers something terrifying: horrific experiments are taking place throughout the city, involving the murder of thousands of espers. Moreover, these espers are far from just ordinary people: they are clones of Mikoto herself. Feeling responsible for their treatment, she sets off to put an end to the experiments; however, the forces opposing her are much more dangerous than she anticipated, and Mikoto finds herself up against some of the most powerful espers imaginable.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yahari Ore no Seishun Love Comedy wa Machigatteiru.', 'TV', 13, 'Completed', '2013-04-05', '2013-06-28', '8', 'Hachiman Hikigaya is an apathetic high school student with narcissistic and semi-nihilistic tendencies. He firmly believes that joyful youth is nothing but a farce, and everyone who says otherwise is just lying to themselves. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ranma ½ (2024) 2nd Season', 'TV', NULL, 'Airing', '2025-10-05', NULL, '8', 'Second season of Ranma ½ (2024).', 527, 'https://cdn.myanimelist.net/images/anime/1011/152084.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('BanG Dream! 3rd Season', 'TV', 13, 'Completed', '2020-01-23', '2020-04-23', '8', 'As the all-girl band Poppin’Party continues to rise in fame, they find a poster for an event at the legendary Nippon Budoukan. Now determined to participate in the "BanG Dream," Kasumi Toyama and the other members of Poppin’Party aim to reach new heights and prove their worth by performing on that renowned stage.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam: Dai 08 MS Shoutai', 'OVA', 12, 'Completed', '1996-01-25', '1999-07-25', '8', 'In year 0079 of the Universal Century, the Earth Federation initiates Operation Odessa—a full-scale assault to retake a major Ukrainian city from the Principality of Zeon. It is a success, and the remaining Zeon forces scatter across the globe. The Earth Federation gains the upper hand in the One Year War and deploys its ground troops around the planet to hunt down the stragglers.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saint Seiya: The Lost Canvas - Meiou Shinwa', 'OVA', 13, 'Completed', '2009-06-24', '2010-04-21', '8', 'A Holy War, from ancient mythology, where the Goddess Athena and Hades have fought against each other while defending the earth repeatedly over the span of 200 years. The story takes place in 18th century Europe, 243 years prior to the original "Saint Seiya" Three small children, Tenma, Alone, and Sasha have all shared a very happy childhood together. Tenma who is quite aggressive but upstanding has moved to Sanctuary to become a saint. It is there that he is reunited with Sasha who is the sister of Alone and learns that she is the reincarnation of Goddess Athena. Alone, who is kind, gentle and loves painting was chosen for the body of enemy King Hades. Tenma eventually becomes a saint of Pegasus and engages in a fierce battle with his best friend Alone, the King of Hades. Pegasus Tenma, King Hades, and the Goddess Athena and through the twist of their 3 fates merge together which unfolds a prologue to the original Saint Seiya.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Clannad', 'TV', 23, 'Completed', '2007-10-05', '2008-03-28', '8', 'Tomoya Okazaki is a delinquent who finds life dull and believes he''ll never amount to anything. Along with his friend Youhei Sunohara, he skips school and plans to waste his high school days away.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Metropolis', 'Movie', 1, 'Completed', '2001-05-26', NULL, '8', 'During an investigation, private detective Shunsaku Ban and his nephew Kenichi travel from Japan to Metropolis—a restless high-tech city where people brutally persecute their robot cohabitants and a dictatorial force rises in power. The two are investigating Dr. Laughton, a scientist suspected of human organ trading, who is supposedly hiding there. Unbeknownst to all, Dr. Laughton has built a cutting-edge female android called Tima for the most influential man in Metropolis, Duke Red.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hello! Lady Lynn', 'TV', 36, 'Completed', '1988-05-12', '1989-01-26', '8', 'This is the second series of Lady Lady. Every year at Lynn''s school, an honorable “Lady Quest” is given to the most sophisticated lady. Lynn strives to receive this honor.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mashiro no Oto', 'TV', 12, 'Completed', '2021-04-03', '2021-06-19', '8', 'Setsu Sawamura runs away from his small home village following the death of his grandfather, the legendary shamisen master Matsugorou Sawamura. On his deathbed, Matsugorou told Setsu to give up the shamisen if he was only going to imitate others instead of playing in his own way. Grieving, Setsu heads for Tokyo, hoping that the big city can inspire him to discover his own unique playing style. But Tokyo defies his expectations by drowning out all other sounds with the deafening noise of its city life. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yao Shen Ji 5th Season', 'ONA', 52, 'Completed', '2021-10-30', '2022-04-20', '8', 'Fifth season of Yao Shen Ji.', 752, 'https://cdn.myanimelist.net/images/anime/1390/119371.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Persona 4 the Animation', 'TV', 25, 'Completed', '2011-10-07', '2012-03-30', '8', 'Serial murders have recently plagued Inaba, with the police struggling to find any leads. Despite this, due to his parents going abroad for work, Yuu Narukami moves to the small town to live with his uncle for a year. He enrolls at Yasogami High School, where he meets and befriends Yousuke Hanamura, Chie Satonaka, and Yukiko Amagi.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('So Ra No Wo To Specials', 'Special', 2, 'Completed', '2010-06-23', '2010-09-22', '8', 'Two extra episodes included in the Blu-ray and DVD volumes 4 and 7 of "Sora no Woto".
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('R.O.D: The TV', 'TV', 26, 'Completed', '2003-09-01', '2004-03-16', '8', 'Anita King, Maggie Mui, and Michelle Cheung are the Paper Sisters. They run the Three Sisters Detective Agency in Hong Kong which is dedicated to solving cases involving books. They are hired as local guides for Nenene Sumiregawa, a Japanese novelist who has been struggling with writer''s block following the disappearance of her longtime friend, Yomiko Readman. The sisters are all Paper Masters—individuals with the power to control paper—and with their abilities, they save Nenene from the dangerous terrorists targeting her at a book signing. But in case they strike again, the sisters remain as her bodyguards to protect her from further harm.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hakumei no Tsubasa', 'ONA', 7, 'Completed', '2020-01-15', '2020-08-06', '8', 'Galar is a region where Pokemon battles have developed into a cultural sensation. Over the span of seven episodes, Pokemon: Twilight Wings will show in detail the dreams of Galar''s residents, the realities they face, the challenges they must overcome and the conflicts they must resolve. In addition to these new stories, fans can expect to see a variety of Pokemon originally discovered in the Galar region appearing in the capsule series. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mitsudomoe: Oppai Ippai Mama Genki', 'Special', 1, 'Completed', '2011-02-23', NULL, '8', 'Hitoha, the youngest of the Marui triplets, frequently gets into trouble with her sister Futaba, who likes the sensation of playing with her soft cheeks. Hitoha''s predicament worsens when a pimple resembling a breast appears on her cheek, and she begins attracting unwanted attention at school. Meanwhile, the oldest sister, Mitsuba, messes with sports equipment, putting herself in tough situations. No matter the circumstances, the sisters'' time together never grows dull.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Irozuku Sekai no Ashita kara', 'TV', 13, 'Completed', '2018-10-06', '2018-12-29', '8', 'Despite the kaleidoscopic magic ingrained in everyday life, Hitomi Tsukishiro''s monochrome world is deprived of emotion and feeling. On a night as black and white as any other, amidst the fireworks spreading across the sky, Hitomi''s grandmother Kohaku conjures a spell, for which she has been harnessing the moon''s light for 60 years, to send Hitomi back in time to the year 2018 when Kohaku was in high school.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kono Kaisha ni Suki na Hito ga Imasu', 'TV', 12, 'Completed', '2025-01-06', '2025-03-24', '8', 'Coworkers Yui Mitsuya and Masugu Tateishi are the last people anyone would expect to get along—especially with their constant office quarrels. However, looks can be deceiving: they are actually dating! Afraid to lose the peace of their professional lives, Yui and Masugu play up their discord even more to ensure nobody discovers their secret.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Benghuai: Xing Qiong Tiedao - Fei Guang', 'ONA', 1, 'Completed', '2023-05-10', NULL, '8', 'Year 7380 Star Calendar, Jingliu, the mara-stricken swordmaster of the Luofu, slashed her way out of Starskiff Haven, cutting through the Cloud Knights tasked to subdue her before vanishing in the mist of history.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bleach: Sennen Kessen-hen - Ketsubetsu-tan Recap', 'Special', 1, 'Completed', '2023-09-02', NULL, '8', 'Recap of the first 8 episodes of Bleach: Sennen Kessen-hen - Ketsubetsu-tan.', 939, 'https://cdn.myanimelist.net/images/anime/1364/138054.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Watashi no Shiawase na Kekkon: Watashi no Shiawase na Katachi', 'OVA', 1, 'Completed', '2024-03-15', NULL, '8', 'Though hesitant, Miyo Saimori decides she is finally ready to attend a party with her fiancé Kiyoka Kudou. She has been practicing the etiquette needed for such an occasion with the help of Kiyoka''s sister, Hazuki. At first, Miyo feels pressured by all the attention she receives; however, she eventually grows used to the unfamiliar environment and makes new acquaintances. Through these encounters, Miyo learns more about her family''s past and the significance of creating connections with others.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hokkyoku Hyakkaten no Concierge-san', 'Movie', 1, 'Completed', '2023-10-20', NULL, '8', '"The word ''no'' doesn''t exist in a concierge''s dictionary." That''s just one of the demanding rules that Akino must abide by in her new job as a saleswoman at the elegant and expansive Hokkyoku Department Store. It''s a very special store — the customers are all animals, and the most valued among them are of extinct species. Sea minks, laughing owls, Japanese wolves, even an enormous mammoth — that''s Mr. Woolly, the celebrated sculptor whose works are showcased at the store. It''s still a luxury retail space, though, and anxious Akino finds her hands full with the customers'' challenging requests. These range from hard-to-find merchandise to more complicated matters of the heart. Can the inexperienced Akino fulfill their whims and meet their expectations? If she wants to keep her job, she''ll have to succeed while under constant observation by the fussy floor manager Mr. Todo, a creepy consultant eager to downsize the staff, and the store''s enigmatic president (who is not a penguin, by the way!).
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kamonohashi Ron no Kindan Suiri', 'TV', 13, 'Completed', '2023-10-02', '2023-12-25', '8', 'Ron Kamonohashi, the best student in the history of the elite Detective Training Academy BLUE, has been living as a recluse since BLUE expelled him five years ago. Moreover, he is forbidden to work as a detective, having barely escaped execution after getting involved in a murder case while he was still attending the school. Ron''s situation changes drastically when police detective Totomaru Isshiki, following the advice of a senior colleague, seeks him out for help with a criminal case that has remained unsolved for months. Ron reluctantly agrees to help Totomaru and uses his phenomenal intuition to discover the culprit in less than a day. However, it appears that Ron suffers from a mysterious condition that can cause those around him to lose their lives. To Ron''s great surprise, Totomaru manages to save the life of someone whom Ron put in jeopardy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jijou wo Shiranai Tenkousei ga Guigui Kuru.', 'TV', 13, 'Completed', '2023-04-09', '2023-07-02', '8', 'Akane Nishimura''s quiet nature makes her classmates perceive her as a gloomy and unlikeable person. Combined with her intimidating gaze, it earns Akane the ominous nickname "Grim Reaper," condemning her to endless bullying for her supposed cursed powers that bring misfortune to everyone around her.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Murai no Koi', 'ONA', 12, 'Completed', '2024-09-04', '2024-11-20', '8', 'Murai is a second-year student at Takebe Gakuen High School enrolled in the college preparatory course. His homeroom teacher, Tanaka, summons him to her office after he declares that his post-high school plans are to marry her. Tanaka rejects Murai, telling him that she would never be interested in a boy with long, black hair. Secretly an otaku, she has eyes only for Hitotose, a character from an otome video game. The next day, Murai appears before Tanaka a changed man. Having cut his hair short and dyed it blond, Murai looks exactly like her beloved Hitotose. Tanaka is unable to hide her shock at this sudden development and tries to distance herself from Murai, while Murai presses on in his attempts to romance his teacher.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kono Subarashii Sekai ni Bakuen wo!', 'TV', 12, 'Completed', '2023-04-06', '2023-06-22', '8', 'Megumin is a young and passionate wizard from the Crimson Demon Village, a remote community of mages with red eyes and a flair for the dramatic. She has devoted her life to mastering explosion magic, a powerful but impractical spell that leaves her drained of mana and unable to move for the rest of the day. Regardless, she refuses to learn any other skills.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mitsudomoe', 'TV', 13, 'Completed', '2010-07-03', '2010-09-26', '8', 'When Satoshi Yabe, the newest teacher at an elementary school, is assigned as the homeroom teacher of class 6-3, he is in for a shock. The class is full of chaos and eccentric students, but none are more troublesome than the mischievous Marui triplets. Mitsuba is sadistic and unusually mature for her age; Futaba is both lewd and incredibly strong; and Hitoha, often absorbed in her erotic books, is quiet and ominous.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Inu x Boku SS: Miketsukami-kun Henka/Switch/Omamagoto', 'Special', 1, 'Completed', '2012-09-26', NULL, '8', 'Unaired episode released with the seventh volume of the Blu-ray &amp; DVD. It consists of three short episodes newly written by the manga author Fujiwara Cocoa. Fujiwara also designed a new character called Hana-chan for the episode.', 227, 'https://cdn.myanimelist.net/images/anime/10/41927.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nobunaga Concerto', 'TV', 10, 'Completed', '2014-07-12', '2014-09-20', '8', '"Who cares about what happened in Japan''s past? It has nothing to do with my life."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Golden Kamuy 2nd Season OVA', 'OVA', 3, 'Completed', '2019-03-19', '2020-09-18', '8', '1. Koi wo Shita kara Datsugoku Suru Koto ni Shita/Kyoufu no Moudoku Dai Shitou! Hokkaido Ouchi ni Kyodai Hebi wa Sonzai Shita! (Love Made Me Escape from Prison/The Terrifying Battle of Deadly Poison! A Massive Snake Deep in the Hokkaido Wilderness!)
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('VTuber Nandaga Haishin Kiri Wasuretara Densetsu ni Natteta', 'TV', 12, 'Completed', '2024-07-07', '2024-09-22', '7', 'Third-generation VTuber Awayuki Kokorone''s fans know her as a prim, proper, and graceful idol. Though she has considerably less fans compared to other VTubers in the Live-On agency, Awayuki''s loyal following supports her every step of the way.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tales of Symphonia The Animation: Sekai Tougou-hen Specials', 'Special', 3, 'Completed', '2011-11-23', '2012-10-24', '7', 'Specials that came with the DVDs of Sekai Tougou Hen.', 1192, 'https://cdn.myanimelist.net/images/anime/10/35705.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaibutsu Oujo (OVA)', 'OVA', 3, 'Completed', '2010-12-09', '2011-10-07', '7', 'Based on a manga by Mitsunaga Yasunori, serialised in Monthly Shounen Sirius.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Girls & Panzer: Fushou Akiyama Yukari no Sensha Kouza', 'Special', 6, 'Completed', '2012-12-21', '2013-06-21', '7', 'Girls &amp; Panzer specials with Yukari Akiyama explaining the background of tank units that appear in the series.', 48, 'https://cdn.myanimelist.net/images/anime/2/49297.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fate/kaleid liner Prisma☆Illya', 'TV', 10, 'Completed', '2013-07-13', '2013-09-14', '7', 'Mage''s Association members Rin Toosaka and Luviagelita "Luvia" Edelfelt are tasked with finding and retrieving seven Class Cards, medieval artifacts containing the life essence of legendary Heroic Spirits. To aid them in their mission, they are granted the power of Ruby and Sapphire, two sentient Kaleidosticks that would enable them to transform themselves into magical girls and drastically increase their abilities. However, the two mages are on anything but good terms, prompting the Kaleidosticks to abandon them in search for new masters. They stumble upon two young schoolgirls—Illyasviel von Einzbern and Miyu—and quickly convince them to form a contract. With their new powers and responsibilities, Illya and Miyu set forth to collect all the Class Cards.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uta no☆Prince-sama♪ Maji Love 1000%', 'TV', 13, 'Completed', '2011-07-03', '2011-09-24', '7', 'Haruka Nanami, an aspiring composer from the countryside, longs to write music for her beloved idol, Hayato Ichinose. Determined to accomplish this goal, she enrolls into Saotome Academy, a highly regarded vocational school for the performing arts.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sword Art Online Alternative: Gun Gale Online', 'TV', 12, 'Completed', '2018-04-08', '2018-07-01', '7', 'Clad in desert pink and the size of a mere child, the infamous "Pink Devil" mercilessly hunts down other players in the firearm-centered world of the virtual reality game Gun Gale Online. But in real life, this feared player killer is not quite who anyone would expect.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyou no 5 no 2 (TV): Takarabako', 'OVA', 1, 'Completed', '2009-10-06', NULL, '7', 'An OVA bundled with the limited edition of the tankobon of the Kyou no Go no Ni manga. The staff and the cast of the OVA are the same as those of the Kyou no Go no Ni TV anime.', 1117, 'https://cdn.myanimelist.net/images/anime/5/14378.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Promare: Lio-hen', 'ONA', 1, 'Completed', '2019-05-24', NULL, '7', 'A direct continuation of Side:Galo set a day before the film.', 1054, 'https://cdn.myanimelist.net/images/anime/1289/108896.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aikatsu! Music Award: Minna de Shou wo MoracchaimaShow!', 'Movie', 1, 'Completed', '2015-08-22', NULL, '7', 'An Aikatsu! All-Star awards ceremony will take place. The film will feature songs and stages featured throughout the anime series.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('MM!', 'TV', 12, 'Completed', '2010-10-02', '2010-12-18', '7', 'Taro Sado is a high school student who lives his day to day life with a big secret—he''s a masochist! Encouraged by his cross-dressing best friend Tatsukichi Hayama, Taro asks the Second Voluntary Club for help with his problem and ends up joining the club after they vow to "fix" him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kodomo no Jikan OVA', 'OVA', 3, 'Completed', '2007-09-11', '2011-01-21', '7', 'A series of OVA episodes released with the limited edition manga volumes.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zhen Hun Jie 2nd Season: Chongzhi Ban', 'ONA', 10, 'Completed', '2021-05-15', '2021-06-26', '7', 'Rakshasa Street, where evil spirits are attracted to in order to destroy them. A place where spirits and humans co-exist, not all humans can enter Requiem Street. Only those rare-soul users with guardian spirits can enter. Xia Ling was just a normal university intern, but a meeting by chance changes her ordinary life... In this world full of evil spirits, can you cooperate with your guardian spirit in order to survive? 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pikmin Short Movies', 'Movie', 3, 'Completed', '2014-10-25', NULL, '7', 'Three short stories from the Nintendo Pikmin game series.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hoshi wo Katta Hi', 'Movie', 1, 'Completed', '2006-01-03', NULL, '7', 'A young boy, tired of the city, escapes into the country. When trying to bring vegetables to the market to sell, his cart breaks down and he exchanges the vegetables for a mystical seed. Returning home he plants the seed in a normal pot—only to find it growing into a planet.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsurupika Hagemaru-kun', 'TV', 59, 'Completed', '1988-03-03', '1989-10-06', '7', 'Hagemaru Hageda is a young kid, studying in fourth standard living with his parents in Japan. Only child of his parents, he and his parents are a big misers. They do anything for saving money and this is the basic plot of the show. Hagemaru also has a pet dog named Pesu, who often comments about Hagemaru''s family being too miser and not giving him anything to eat.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tesagure! Bukatsumono Encore', 'TV', 12, 'Completed', '2014-01-12', '2014-03-30', '7', 'Second season of Tesagure! Bukatsumono.', 1127, 'https://cdn.myanimelist.net/images/anime/7/58483.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kikoushi Enma', 'OVA', 4, 'Completed', '2006-08-25', '2007-03-23', '7', 'Enma is a character created by the genius manga artist Go Nagai. Now, the popular character makes his appearance in an alluring Japanese horror anime for adults. It''s a hair-raising erotic suspense in which Enma takes on complicated and gruesome incidents caused by demons who lurk in the darkness. But humans have lit up the darkness of the night with neon lights and turned their world into one that never sleeps, so demons now lurk in the "darkness of the human heart." Unfulfilled hearts, suppressed hearts, despair,...such darkness of the heart is the place they lurk.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mekakucity Actors', 'TV', 12, 'Completed', '2014-04-13', '2014-06-29', '7', 'On the hot summer day of August 14, Shintarou Kisaragi is forced to leave his room for the first time in two years. While arguing with the cyber girl Ene who lives in his computer, Shintarou Kisaragi accidentally spills soda all over his keyboard. Though they try to find a replacement online, most stores are closed due to the Obon festival, leaving them with no other choice but to visit the local department store. Venturing outside makes Shintarou extremely anxious, but the thought of living without his computer is even worse. It''s just his luck that on the day he finally goes out, he''s caught in a terrifying hostage situation.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimi no Iru Machi OVA', 'OVA', 2, 'Completed', '2014-01-17', '2014-03-17', '7', 'The limited-edition of the 26th manga volume will include an anime adaptation of the popular special flashback chapter "Uchi ga Kita Machi" (The Town Where I Arrived). The story reveals how Haruto, Akari, and Takashi first met during childhood, and serves as a prologue to the TV anime.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xing Wushen Jue', 'ONA', 40, 'Completed', '2021-01-28', '2021-05-30', '7', 'In the whole world there lays twelve paths to climb the Tower of God, and in legends these twelve pathways leads toward legendary road of immortality. However these paths in the Tower of God, are far too long, without end.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kodomo no Jikan Ni Gakki', 'OVA', 3, 'Completed', '2009-02-20', '2009-07-24', '7', 'The second season of Kodomo no Jikan.', 238, 'https://cdn.myanimelist.net/images/anime/3/39447.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mashin Eiyuuden Wataru 2', 'TV', 46, 'Completed', '1990-03-09', '1991-03-08', '7', 'This is the sequel to Mashin Eiyuden Wataru first season. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuro no Su: Chronus', 'Movie', 1, 'Completed', '2014-03-01', NULL, '7', 'For as long as he can remember, Makoto Nakazono has had the power to see grim reapers watching people shortly before their deaths and escorting their souls to heaven. He realized long ago that nobody would believe him if he talked about his ability. Since there is nothing he can do to alter people''s fates, he tries his best to pretend that he does not see anything out of the ordinary.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yamato Takeru', 'TV', 37, 'Completed', '1994-04-09', '1994-12-24', '7', 'In the 25th century, a spaceship carrying 300 people leaves the earth in search of a new world in the solar system, but an unexpected accident occurs. They crash into a black hole which is connected to another universe. The people on the ship are cast adrift in an emergency capsule to a planet called Ismo. The story begins 12 years after they have reached Ismo.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hoshi no Oujisama Petit Prince', 'TV', 35, 'Completed', '1978-07-04', '1979-03-27', '7', 'The Little Prince lives on Asteroid B612, a tiny rock floating in space. He spends his days cleaning out the three small volcanoes on the asteroid (which he also uses to cook his breakfast) weeding out the baobob trees that threaten to take over, and caring for his friend the Rose Girl. When he gets lonely for company he catches a comet in his butterfly net and flies off to Earth for all sorts of adventures.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Naruto Narutimate Hero 3: Tsuini Gekitotsu! Jounin vs. Genin!! Musabetsu Dairansen Taikai Kaisai!!', 'OVA', 1, 'Completed', '2005-12-22', NULL, '7', 'Konohagakure hosts a special tournament for ninjas of all ranks, stirring up fervor among the rookies who are eager to prove themselves in a competition against their superiors. Additionally, the winner is granted the opportunity to create their own village decree! Despite his enthusiasm to claim the prize, Naruto Uzumaki fails to focus on the game''s objective as he becomes obsessed with confronting his teacher, Kakashi Hatake, in single combat.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Alien 9', 'OVA', 4, 'Completed', '2001-06-25', '2002-02-25', '7', 'Soon after entering middle school, Yuri Otani is coerced into joining the "Alien Party," a single-minded group with one goal: capture any alien attempting to enter school grounds. Terrified of aliens her entire life, Otani is anything but thrilled, and to make matters worse, her kit includes a "Borg"—an alien-like creature tasked with ensuring her safety. Despite this, she finds solace in her two partners: the independent and reliable Kumi Kawamura, and the smart and energetic Kasumi Tomine.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hidan no Aria', 'TV', 12, 'Completed', '2011-04-15', '2011-07-01', '7', 'In response to the worsening crime rate, Japan creates Tokyo Butei High, an elite academy where "Butei" or armed detectives hone their deadly skills in hopes of becoming mercenary-like agents of justice. One particular Butei is Kinji Tooyama, an anti-social and curt sophomore dropout who was once a student of the combat-centric Assault Division. Kinji now lives a life of leisure studying logistics in order to cover up his powerful but embarrassing special ability. However, his peaceful days soon come to an end when he becomes the target of the infamous "Butei Killer," and runs into an emotional hurricane and outspoken prodigy of the highest rank, Aria Holmes Kanzaki, who saves Kinji''s life and demands that he become her partner after seeing what he is truly capable of.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Totsuzen! Neko no Kuni Banipal Witt', 'Movie', 1, 'Completed', '1995-06-10', NULL, '7', 'Fifth-grader, Toriyasu, and his little sister, Meeko, have a dog named Papadoll who has been missing for the past week. One night, two cats take the two children to the distant cat land of Banipal Witt, where Papadoll was abducted. Because of his long exposure to Banipal Witt''s sun, Papadoll mutated into a giant dog monster, terrorizing the city under the control of the evil Princess Buburina, who has the curse of turning anyone she touches into balloons. Toriyasu, Meeko, and the cats have until the next sunrise to turn Papadoll and the ballooned citizens of Banipal Witt back to normal and return to their home planet—or end up with the same fate as their dog.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Huyao Xiao Hongniang: Yue Hong 2', 'ONA', 1, 'Completed', '2021-08-14', NULL, '7', 'The story centers on Dongfang Yuechu and Tushan Honghong, recounting their love story from 500 years ago. Young Dongfang Yuechu mistakenly enters Tushan, where he lives as a "lowly servant." Years later, to fulfill Tushan Honghong''s wish—peaceful coexistence between humans and demons—Dongfang Yuechu resolutely leaves Tushan to join the Yi Qi Dao Alliance, becoming its leader. However, just when everything seems to be progressing smoothly, danger is slowly approaching…
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Venus Senki', 'Movie', 1, 'Completed', '1989-03-11', NULL, '7', 'In the 21st century, mankind lives on two worlds. Following the collision of an ice asteroid, massive terraforming has made Venus a planet now capable of supporting life. Colonists from Earth tamed the hostile world and have thrived for four generations. But they also brought the darker side of humanity. Venus is about to get hostile again.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cossette no Shouzou', 'OVA', 3, 'Completed', '2004-04-11', '2004-12-22', '7', 'Eiri Kurahashi is a Japanese art student who works in an antique shop. His friends begin to notice a dramatic, and rather concerning, change in Eiri, as he becomes more absent-minded and his behavior completely changes. They quickly decide to blame their friend''s troubles on a girl.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimi to Boku no Saigo no Senjou, Aruiwa Sekai ga Hajimaru Seisen Season II', 'TV', 12, 'Completed', '2024-07-10', '2025-06-26', '7', 'Over a century ago, astral mages under persecution from the Empire banded together and established the Nebulis Sovereignty under three founding families: Lou, Hydra, and Zoa. With the leadership of Millavair Lou Nebulis VIII, the Sovereignty aims to minimize casualties in their conflict with the Empire—a stance the extremist Zoas disagree with. Tensions rise between the families as the upcoming election to decide the next leader approaches. The Zoas are willing to do anything to achieve success; however, a world-ending war may ensue should they be victorious.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Captain Tsubasa: Ayaushi! Zen Nihon Jr.', 'Movie', 1, 'Completed', '1985-12-21', NULL, '7', 'The second movie is about the return match between the All Europe Soccer Team and Japan. At the beginning Hyuga denies to join the team due to his 3. defeat against Nankatsu. He practices hard with Kyra to perfect his Tiger Shot. Misaki can''t come and Wakabayashi isn''t allowed to play for he normally plays for a German team. With those lacks and Schneider''s (the European''s captain) improved skills, Tsubasa and the Japanese team have grave problems. Despite the new rules, Schneider finally want''s to beat his rival Wakabayashi with his new "illusion shot", thus he injures Wakashimazu and Murisaki (the second and third goal keeper) with brutal face shots until Wakabayashi is finally allowed to play. In the course of the match Hyuga manages to perfect his Tiger Shot and joins the team. With those legendary players united and Hyugas new power they manage to defeat their opponent 4:3 in the last minutes.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('s.CRY.ed Alteration II: Quan', 'Movie', 1, 'Completed', '2012-03-10', NULL, '7', 'Second part of the s.CRY.ed recap.', 974, 'https://cdn.myanimelist.net/images/anime/4/73950.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Stratos 4 Advance', 'OVA', 6, 'Completed', '2005-03-05', '2006-01-27', '7', 'Having failed the Comet Blaster exams mysteriously, Mikaze and her friends are sent back to the Shimoji Island base, where, with three new Meteor Sweeper trainees around, they have been promoted to instructor positions.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Taiyou no Mokushiroku: A Spirit of the Sun', 'Special', 2, 'Completed', '2006-09-17', '2006-09-18', '7', 'On August 10 2002, the eruption of Mount Fuji, as well as a series of large-scale earthquakes tsunamis inflict tremendous damage to Japan, sending the country into a state of emergency. Furthermore, another massive earthquake hit Japan on August 15, splitting the country into two. While Japanese refugees were taken in by various countries, the Japanese government accepted aid from China and the United States, which eventually caused China to govern the North, and the USA to govern the South. 15 years later, the Japanese refugees residing in Taiwan and the Taiwanese citizens find themselves clashing with one another, due to job competition and the unimproving conditions of the Japanese refugees. Genichiro Ryu is a survivor of the catastrophic events that took place in Japan, but was raised in Taiwan by a couple who adopted him. He gets himself involved in the situation between the Taiwanese and the Japanese, hoping that the two parties will be able to coexist with one another. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('DearS: Kin no Tama desu no?', 'Special', 1, 'Completed', '2005-03-16', NULL, '7', 'Miu wins the grand prize in the local shopping district raffle, which is a free pass for up to four people to Yuniataru Studio, a spa resort. She decides to take Takeya, Ren and Neneko since her grandparents couldn''t attend.', 226, 'https://cdn.myanimelist.net/images/anime/7/83451.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ranma ½: DoCo Music Video', 'OVA', 1, 'Completed', '1995-08-19', NULL, '7', 'This was a collection of the opening and ending OAV themes performed by DoCo, the musical group made up of Ranma ½ cast members. Also included is an interview with the cast during their recording of the "Tunnel of Lost Love" OAV. The interviewed voice actors included: Kappei Yamaguchi, Megumi Hayashibara, Noriko Hidaka, Keniichi Ogata, Minami Takeyama, Kikuko Inoue, Ryunosuke Obayashi, Hiromi Tsuru, Rei Sakuma, Toshikiko Seki, Miyoko Asou, Koichi Yamadera, Hirotaka Suzuoki, Saeko Shimazu, and Shigeru Chiba.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Working''!! Announcement Specials', 'ONA', 2, 'Completed', '2011-04-01', '2011-04-02', '7', 'Several characters announce the new season.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cue!', 'TV', 24, 'Completed', '2022-01-08', '2022-06-25', '7', 'As a new agency, AiRBLUE''s roster consists of voice actresses with absolutely no experience. Expecting to hone their skills and build courage at a gradual pace, the girls are taken aback when the head of their agency, Masaki Ootori, announces that they will be partaking in an audition for Bloomball—a popular sports manga receiving an anime adaptation. Despite all odds being stacked against them, each of the girls is now presented with a momentous chance to make their debut in the unrelenting world of voice acting. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Witch Craft Works: Takamiya-kun to Imouto no Warudakumi', 'OVA', 1, 'Completed', '2015-01-07', NULL, '7', 'DVD OVA of Witch Craft Works bundled with the eighth manga volume.', 436, 'https://cdn.myanimelist.net/images/anime/1685/112971.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pole Princess!! Movie', 'Movie', 1, 'Completed', '2023-11-23', NULL, '6', 'Theatrical release of Pole Princess!!.', 1009, 'https://cdn.myanimelist.net/images/anime/1213/138485.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hametsu no Oukoku', 'TV', 12, 'Completed', '2023-10-07', '2023-12-23', '6', 'Bestowed with magic from God, witches worked to guide humanity toward progress, garnering adoration and fear alike from humans. However, times have since changed. With the advancement of scientific knowledge, humans now stand on an equal footing with witches. Determined to weave their own destinies and establish supremacy over the world, the mighty Redia Empire has ordered the extermination of all witches, which may bring the era of magic to an end.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Ball Z x Kao', 'Special', 1, 'Completed', '2018-02-20', NULL, '6', 'Dragon Ball Z does a commercial with the Japanese brand Kao. It starts off with Bulma telling Vegeta to clean the bathroom. Vegeta notices how dirty the bathroom is and gets mad and uses his power to clean it, destroying a part of the bathroom. Soon after Bulma tells Vegeta there is another way to clean the bathroom by using Kao cleaning sprays.', 1030, 'https://cdn.myanimelist.net/images/anime/1376/124922.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saint Seiya: Knights of the Zodiac - Battle Sanctuary', 'ONA', 12, 'Completed', '2022-07-31', '2022-10-09', '6', 'Second season of Saint Seiya: Knights of the Zodiac.', 1030, 'https://cdn.myanimelist.net/images/anime/1473/129466.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ple Ple Pleiades Special Edition', 'ONA', 1, 'Completed', '2015-09-30', NULL, '6', 'A special edition of "Pure Ple Pleiades" released in commemoration of the release of the first volume of the TV anime "Overlord" BD &amp; DVD.', 945, 'https://cdn.myanimelist.net/images/anime/1103/121227.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saint Seiya: Legend of Sanctuary', 'Movie', 1, 'Completed', '2014-06-21', NULL, '6', 'From the dawn of time, there have been warriors who protected the Goddess Athena. Once forces of evil appear, these warriors, called the Saints will present themselves. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Usuzumizakura: Garo', 'Movie', 1, 'Completed', '2018-10-06', NULL, '6', 'Set during the Heian Period, Kyo is a beautiful city that is proud of its glory. Two beautiful onmyouji meet, and the sad and short-lived beautiful cherry blossom starts to stir after 1000 years.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blade', 'TV', 12, 'Completed', '2011-07-01', '2011-09-16', '6', 'The story revolves around Blade, a "Daywalker" vampire hunter who was born with vampire and human blood after a vampire attacked his mother. While visiting Japan on a mission, Blade tracks down Deacon Frost, the vampire who killed his mother. Blade confronts "Existence," a mysterious organization composed of vampires modified by Frost. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Persona 3 the Movie Meets "Walkman"', 'Special', 1, 'Completed', '2016-02-14', NULL, '6', 'Standing on the rooftop of Gekkoukan High School, Makoto Yuuki watches the snow fall on a peaceful winter night. With a Sony Walkman in hand, Makoto puts on his headphones. The music flowing through his ears brings about the birth of spring, showing the splendor of the device.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga Tetsudou 999: Akai Hoshi Betelgeuze - Inochi no Kagayaki', 'Movie', 1, 'Completed', '2014-01-04', NULL, '6', 'Another Ginga Tetsudou 999 movie that was screened in several Planetariums in Japan.', 1030, 'https://cdn.myanimelist.net/images/anime/5/72906.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Asobi ni Iku yo!: Asobi ni Oide - Owari', 'Special', 1, 'Completed', '2011-06-15', NULL, '6', 'Kio Kakazu is having a good time with a Catian Assistroid, a robot from the planet Catia that helps with tasks. By showing different pictures from an album, Kio teaches the little robot the importance of memories.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga Hyouryuu Vifam: Kieta 12-nin', 'OVA', 1, 'Completed', '1985-02-25', NULL, '6', 'This episode is a sidestory and can be inserted somewhere between episodes #18 and #21. This is a "mystery" and so the present writer does not tell the whole story. The Janus is sailing towards Taut when something unexpected happens.', 974, 'https://cdn.myanimelist.net/images/anime/11/59747.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kurage no Shokudou', 'OVA', 1, 'Completed', '2016-03-09', NULL, '6', 'One fateful day, Youtarou Misaki is rescued by a man named Arashi Mutou from drowning in the sea. After getting him to dry land, Arashi wakes Youtarou up and asks for his name. Youtarou''s memories quickly surge back, but instead of telling Arashi his name, he decides to lie and act clueless about his past. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dokyuu Hentai HxEros OVA', 'OVA', 2, 'Completed', '2020-11-04', '2021-03-04', '6', 'The first original video episode will follow three of the main heroines in an original story.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shinkalion: Change the World', 'TV', 39, 'Completed', '2024-04-07', '2025-02-02', '6', 'Once upon a time, an unidentified enemy, the Unknown, suddenly appeared. The "Super Evolutionary Railway Development Agency," had developed the "Shinkalion," a robot that transforms into a bullet train, as a countermeasure against this threat.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Azur Lane 4th Anniversary: A Day at the Port Ice Cream Shop', 'ONA', 1, 'Completed', '2022-08-13', NULL, '6', 'Le Malin, Dunkerque and Magdeburg are in the ice cream shop. Seems like something interesting happened - let''s check it out!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Monk Seishin', 'ONA', 1, 'Completed', '2023-05-17', NULL, '6', 'In the 19th century, a rice merchant encounters a mother who tries to buy rice in exchange for her own child''s clothes. The merchant becomes Monk Seishin and relieves the islanders of Miyajima from poverty by digging wells and starting the wooden ladle industry.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('"Ayakai Shima" e Youkoso! Mitaman no Ayakashima Kankou Annai', 'ONA', 16, 'Completed', '2023-06-23', '2023-10-03', '6', '', 39, 'https://cdn.myanimelist.net/images/anime/1580/136658.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ikimono-san', 'TV', 12, 'Completed', '2023-07-08', '2023-09-30', '6', 'A new series of anime shorts based on Atsushi Wada''s original short film and game My Exercise.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nanjyamo no Aibou wa Nanimono nanja!? (Donna Monja TV)', 'ONA', 2, 'Completed', '2022-10-12', '2022-10-14', '6', 'Digital influencer, streamer, and Gym Leader Nanjyamo introduces herself and asks the audience to guess what her partner Pokémon is.', 413, 'https://cdn.myanimelist.net/images/anime/1197/129096.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bloomy*Cafe', 'ONA', 25, 'Completed', '2021-09-09', '2022-07-07', '6', 'CG shorts included in Aikatsu Planet! Mirror In☆Lab variety show.', 116, 'https://cdn.myanimelist.net/images/anime/1643/121685.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Active Raid: Kidou Kyoushuushitsu Dai Hachi Gakari', 'TV', 12, 'Completed', '2016-01-07', '2016-03-24', '6', 'In a futuristic, post-disaster Tokyo, the "Special Public Security Fifth Division Third Mobile Assault Eighth Unit," or "Unit Eight," is a police unit specializing in handling criminals who wield dangerous wearable technology called "Willwear." Equipped with Willwear of their own, the squadron is often criticized by the public for their carelessness and disregard for protocol.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyushu Love Milk Club', 'Special', 4, 'Completed', '2006-01-01', '2022-01-01', '6', 'Animated commercials for Kyushu Love Milk Club, a Kyushu raw milk sales agricultural cooperative federation, that connects small time dairy farmers into a collective to sell their region brand of milk.', 1050, 'https://cdn.myanimelist.net/images/anime/1969/90864.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Soul Eater NOT!', 'TV', 12, 'Completed', '2014-04-09', '2014-07-02', '6', 'Soul Eater NOT! is a spin-off and side story that takes place one year prior to the events of the original Soul Eater. At the Death Weapon Meister Academy, humans born with the power to transform into weapons and those with the power to wield these weapons (Meisters) train to hone their natural talent. The characters of the main series are enrolled in the Especially Advantaged Talent class, where they train to become warriors of justice capable of defeating what threats prey on innocent lives—or even the entire world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Muteking the Dancing Hero', 'TV', 12, 'Completed', '2021-10-03', '2021-12-19', '6', 'Set in a city modeled after San Francisco in the 1980s, the protagonist has transformed into the hero Muteking and is fighting against evil aliens for some reason. Such a cheerful hero will return in 2020! Sci-fi hero love comedy Muteking the Dancing Hero, singing and dancing with pop music.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tokyo Futago Athletic', 'TV', 8, 'Completed', '2016-12-30', '2017-01-07', '6', 'Having cleared the preliminaries, twenty-four pairs of twins face gargantuan challenges on an enormous athletic field. On this man-made island in Tokyo Bay, the bonds between twins are pushed to the limit in the Ultimate Athletic Tournament!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Haja Kyosei G Dangaiou', 'TV', 13, 'Completed', '2001-04-06', '2001-07-06', '5', 'A mysterious explosion on Futagami Island begins a new chapter in the Dangaioh mythos! Led by the evil Professor Katou, a band of warriors calling themselves the "Tartarus Knights" have begun their campaign to lay waste to the world by way of a small research station on Futagami Island. Katou''s victory seems almost certain until he encounters an advanced fortress guarding the island. From it, a group of three humanoid robots are launched—Dangaioh!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gundam UC x Nike SB', 'Special', 1, 'Completed', '2021-09-21', NULL, '5', 'A special PV advertising Gundam Unicorn themed Nike Sneakers with original animation by Sunrise.', 974, 'https://cdn.myanimelist.net/images/anime/1088/118083.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gattai Robot Atranger', 'OVA', 1, 'Completed', '2011-12-29', NULL, '5', 'After a decades-long war against the Dark Ones reaches a stalemate, the giant robot Atlanger is about to be formally retired. But when the Earth is suddenly attacked, it''ll be up to Asuka Ken and a group of ragtag rookie pilots to save everyone.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hit wo Nerae! Specials', 'Special', 4, 'Completed', '2004-05-19', '2004-06-30', '5', 'DVD only specials.', 423, 'https://cdn.myanimelist.net/images/anime/3/5357.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kakko Kawaii Sengen!', 'TV', 5, 'Completed', '2010-11-05', '2010-12-03', '5', 'Shorts run during Shueisha''s Saki-yomi Jum-Bang! television program starting on November 5, 2010. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ami no Monomane 150 Renpatsu', 'Special', 1, 'Completed', '2009-04-30', NULL, '5', 'A scene left out of episode 6. Included as a bonus content on the BD/DVD of Toradora PSP premium box.', 436, 'https://cdn.myanimelist.net/images/anime/1620/121310.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Märchen Mädchen', 'TV', 10, 'Completed', '2018-01-11', '2018-03-29', '5', 'Hazuki Kagimura is a socially awkward girl with no friends; and having been recently adopted, she struggles to connect with her new family as well. Her only refuge from this painful reality is between the pages of stories where her vivid imagination allows her to live out her dreams of friendship and adventure. However, one day, an old and mysterious text appears in her book bag. On her way back to the library to return it, Hazuki sees a familiar girl who is seemingly invisible to everyone but her. Deciding to follow her, Hazuki is led a hidden library where a world she thought only existed in her dreams awaits her. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kämpfer Picture Drama', 'Special', 1, 'Completed', '2009-12-23', NULL, '5', 'A very special episode included with the Blu-ray release. The Entrails Animals and Akane discuss philosophical topics such as existence, purpose, and low-quality merchandise.', 612, 'https://cdn.myanimelist.net/images/anime/6/25042.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Runningman', 'ONA', 1, 'Completed', '2012-02-22', NULL, '5', 'A father works hard for the family. Due to being overweight and not fitting on the couch with his wife and daughter he sets out to lose weight.', 260, 'https://cdn.myanimelist.net/images/anime/2/80667.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jinji Xingzhe', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'On the world''s dark edge, forbidden powers are growing. When high schooler Yan Feng is drawn into a deadly incident, he joins a secret organization to save his sister, contain sinister artifacts, and battle villains bent on unleashing these powers. As the fight intensifies, he begins to uncover the truth about his own origins.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shaonian Ge Xing: Nanming Li Huo', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'After the Heaven-Splitting Sword was drawn, the divine weapons scattered across the land began to show unusual signs. Xiao Se, together with several sworn friends from the jianghu, set out to seek the divine weapons and save the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hua Jianghu: Bu Liang Ren Ba', 'ONA', NULL, 'Upcoming', '2027-01-01', NULL, '5', 'Having survived a life-or-death ordeal in the northern deserts, Li Xingyun finally returns to his homeland. Faced with the sudden changes at Huan Yin Fang and the many mysteries surrounding Ji Ruxue, how will he break through the predicament? In this world, grudges are easily settled, but the boat of the heart is hard to cross. Crisis resurfaces in the Central Plains; let''s see how Bu Liang Ren once again quell the turmoil!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zhu Xian: Zuizhong Ji', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'Gui Li ventures into the Demon-Suppressing Cave to end the threat of the Beast God, joining forces with Lu Xueqi to defeat it. The Ghost King captures the ferocious mythological animal, turning against Gui Li, and the two engage in a fierce battle, which is stopped by You Ji. Meanwhile, Dao Xuan and Tian Buyi disappear. Gui Li reunites with his mentor at the mortuary. Gui Li, Tian Buyi, and Lu Xueqi battle the demonized Dao Xuan, ultimately resulting in Tian Buyi''s death. The Four Spirits Blood Array is completed, and the Ghost King, merging with the power of the Bright King, attacks Qingyun. In this perilous moment, Gui Li wields the Immortal-Slaying Sword in a desperate battle against the Ghost King, saving the world. Afterwards, Lu Xueqi reunites with Zhang Xiaofan, who is living in seclusion in Grass Temple Village.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kakunaru Ue wa', 'TV', NULL, 'Upcoming', NULL, NULL, '5', 'Dweeby high schooler Yuuki Uehara has created the perfect romantic comedy heroine—she''s bashful, airheaded, and completely chaste. When an editor at Uehara''s dream publisher coldly dismisses his manga story as trite and lacking realism, it sends Uehara into a spiral of despair that pushes him into the path of his bubbly, gorgeous classmate, Niina Miyamoto—an aspiring manga artist herself! Having gotten similar feedback on her own manga, Miyamoto proposes she and Uehara engage in a fake relationship, since neither of them have any romantic experience. But Miyamoto is far from the perfect heroine Uehara''s concocted, and he certainly isn''t the cocky hero from her story either. Can their wacky relationship turn their manga dreams into reality, or will it lead to even more comic disasters?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kai', 'ONA', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'In an out-of-control world, survivors faced a thrilling and perilous apocalyptic battlefield.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bai Ri Cheng Wang', 'ONA', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'One second the restaurant was filled with joy, the next it was a river of blood… The king, who clearly loved his people, suddenly became a bloodthirsty beast… "Ming" has lost everyone he cared about; this terrible king is truly awful! I will take my revenge! Wait, you mean the soul in front of me with only 100 days left to live is the real "Lie"? Alright, alright! 100 days—let''s both be crowned kings together!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wangu Zhizun: Li Yunxiao Chuan', 'ONA', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'Gu Feiyang, the third strongest warrior on the Tianwu Continent and the Martial Emperor Pojun, was bound by the world''s rules, his cultivation stuck at the Nine Heavens Martial Emperor realm for many years, unable to break through. To escape this predicament, he used the affections of Qu Hongyan, the mistress of the Shenxiao Palace, to orchestrate a grand scheme, sacrificing extraterrestrial demonic energy to reincarnate and cultivate anew. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wo Zai Feitu Shijie Sao Laji', 'ONA', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'Zhu Ning, a warrior who slayed in all directions in a zombie apocalypse, unexpectedly dies and is transported to a wasteland filled with unknowns and fantasy. She becomes a fifth-class citizen, the lowest rank in the world, forced to make a living by "scavenging garbage." However, she discovers the strangeness and danger of this world in her work: various bizarre polluting monsters, the world''s strange operating rules, and even her own strange self… Zhu Ning gradually uncovers a huge secret hidden behind the world, which also brings her immense danger. In this unknown post-apocalyptic world, Zhu Ning is forced into complex conflicts, searching for the truth about herself and the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bai Gui Ri Xing', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'A parasitized boy killed his cruel master and became the strongest supernatural hunter. Using his bizarre form, he hunted the mysterious, ultimately transforming into a "Mad Killing God," saving humanity at the cost of everything he cherished.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jipin Tian Shi', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'The hero, gifted with extraordinary abilities and from a powerful Daoist sect, left his sect at his master''s invitation to exorcise ghosts. After clearing two haunted houses, he became entangled in a series of bizarre events while facing challenges from various factions: he clashed with a Thai sorcerer, dealt a crushing blow to Japanese Onmyoji, fended off a Korean witch''s challenge, and humiliated Western exorcists—defeating and banishing masters from across the world. In a realm where technology intertwined with the supernatural, he slayed demons and spirits, growing into a legendary Celestial Master.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kami no Shizuku', 'TV', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'Shizuku Kanzaki is the only son of world-renowned wine critic Yutaka Kanzaki. From a young age, Shizuku has been subjected to strange education from his father all for the sake of wine. From learning to gracefully decant a drink to intently remembering the smell of leather belts and pencils, the training causes him to grow resentful of everything related to wine. Discontent with his father, he leaves home to become an average sales representative for a beer company, refusing to ever touch wine again.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zhen Hun Jie 5th Season', 'ONA', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'The world of Rakshasa Street is engulfed in conflict, with various forces stirring with ambition. The united forces of Cao, Sun, and Liu, are unstoppable, the Hall of Heroes suffers a devastating blow, and the Spirit Realm''s rule is on the verge of collapse. Countless heroes are emerging, and a new crisis is about to erupt due to the ambitions of the Kingdom Organization. In the world of Rakshasa Street, no one dares to say "no!" Cao Yanbing''s path to becoming king has officially begun!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsumiki no Ie', 'Movie', 1, 'Completed', '2008-06-10', NULL, '8', 'In a flooded town where the waters are ever-rising, an old man must constantly build new floors onto his home in order to keep dry. But when his favorite smoking pipe falls into the watery abyss beneath him, he dives into the depths of not only his house, but memories of years past.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Haibane Renmei', 'TV', 13, 'Completed', '2002-10-10', '2002-12-19', '8', 'Born from a cocoon in the village of Old Home, a young Haibane—a being with a halo and small gray wings—awakens to a world she does not understand without memories of her past. Named Rakka for the dream of falling she had while inside the cocoon, she soon becomes accustomed to life in the strange town. However, there are strict rules for the Haibane, such as being forbidden to leave the village or go near the walls surrounding it. These, along with mysterious disappearances of their kind on their "Day of Flight," begin to unsettle Rakka and the others since they know almost nothing about their own kind.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shingeki no Kyojin Movie 2: Jiyuu no Tsubasa', 'Movie', 1, 'Completed', '2015-06-27', NULL, '8', 'Recap of episodes 14-25.', 1105, 'https://cdn.myanimelist.net/images/anime/2/72510.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaichou wa Maid-sama!', 'TV', 26, 'Completed', '2010-04-02', '2010-09-24', '8', 'Misaki Ayuzawa is a unique phenomenon within Seika High School. In a predominantly male institution, she became the first-ever female student council president through her honesty and diligence. Ever since Misaki got promoted to the position, she has been working tirelessly to ensure a better school life for all girls. Despite that, Misaki is very strict with the boys, which has earned her the title "Demon President." 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuri!!! on Ice: Yuri Plisetsky GPF in Barcelona EX - Welcome to The Madness', 'Special', 1, 'Completed', '2017-05-26', NULL, '8', 'In his exhibition performance for the Grand Prix of Figure Skating Final in Barcelona, 15-year-old Yuri Plisetsky seeks to defy his "Russian Fairy" nickname by showing off wild new choreography, the likes of which have never been seen from him on the ice before.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boku no Hero Academia 3rd Season', 'TV', 25, 'Completed', '2018-04-07', '2018-09-29', '8', 'As summer arrives for the students at UA Academy, each of these superheroes-in-training puts in their best efforts to become renowned heroes. They head off to a forest training camp run by UA''s pro heroes, where the students face one another in battle and go through dangerous tests, improving their abilities and pushing past their limits. However, their school trip is suddenly turned upside down when the League of Villains arrives, invading the camp with a mission to capture one of the students. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kami nomi zo Shiru Sekai: Megami-hen', 'TV', 12, 'Completed', '2013-07-09', '2013-09-24', '8', 'Having freed a myriad of women from the runaway spirits possessing their hearts, the "God of Conquest" Keima Katsuragi is confronted with a new task: find the Jupiter Sisters, the goddesses that sealed Old Hell in the past. Diana, the goddess that resides inside his childhood friend Tenri Ayukawa, explains that they have taken shelter in the hearts of the girls he had assisted previously. Moreover, once Diana and her sisters are reunited, their power can seal the runaway spirits away for good and relieve Keima of his exorcising duties. Though he is initially reluctant to get involved in yet another chore, everything changes when tragedy befalls one of the hosts.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kara no Kyoukai Movie: Mirai Fukuin', 'Movie', 1, 'Completed', '2013-09-28', NULL, '8', '​Shiki Ryougi, Mikiya Kokutou, and Touko Aozaki begin investigating a bomber after they witness a nearby explosion. That same night, Shiki catches a glimpse of the bomber, and as a result, he becomes fixated on her. To get rid of her, the madman plays a game of cat and mouse in attempts to lure her to an empty parking garage. And bombs are not the only thing he has in his arsenal: he also possesses the ability to see the future, and he intends to bring an end to Shiki.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bungou Stray Dogs Wan!', 'TV', 12, 'Completed', '2021-01-13', '2021-03-31', '8', 'Atsushi Nakajima has finally grown accustomed to the crazy lifestyle that comes with being part of the Armed Detective Agency. But even during peaceful periods of time, there is bound to be chaos! As Atsushi, his friends, and the agency''s rival group—the Port Mafia—go about their days roaming the streets of Yokohama, there are no limits to the strange situations they are unwillingly thrown into. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zombieland Saga Revenge', 'TV', 12, 'Completed', '2021-04-08', '2021-06-24', '8', 'The Franchouchou girls are back and better than ever! Unfortunately for them, they are also heavily in debt. After a concert bombs, the undead members are forced to take day jobs to pay off the venue, and their normally eccentric manager, Koutarou Tatsumi, sinks into alcoholism.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hanada Shounen-shi', 'TV', 25, 'Completed', '2002-10-02', '2003-03-26', '8', 'Ichiro Hanada is a hyperactive little boy who lives with his parents, sister, and grandfather in a rural town. He is always up to some kind of mischief, often teasing his sister or making rude comments to others. Consequently, his mother constantly scolds him, and even the neighbours express disturbance from time to time on how rowdy he can be.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('ef: A Tale of Melodies.', 'TV', 12, 'Completed', '2008-10-07', '2008-12-23', '8', 'In a story set years in the past, Himura Yuu is a studious and diligent young man intent solely on maintaining his top academic position at Otowa Academy. One day, he meets a mysterious girl named Amamiya Yuuko, who, to his surprise, recognizes him. Memories of a distant childhood, memories rather left forgotten... meeting Yuuko again will force Yuu to confront the regrets and sorrows of their collective pasts and presents.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Touch', 'TV', 101, 'Completed', '1985-03-24', '1987-03-22', '8', 'The story centers around three characters—Uesugi Kazuya, his twin older brother Tatsuya, and Asakura Minami. Kazuya is the darling of his town as he''s talented, hardworking, and the ace pitcher for his middle school baseball team. Tatsuya is a hopeless slacker who''s been living the life of giving up the spotlight to Kazuya, despite the fact that he may be more gifted than him. Minami is the beautiful childhood girlfriend and for all intents, sister from next door who treats both of them as equals. Society largely assumes Kazuya and Minami will become the perfect couple, including Tatsuya. Yet as time progresses, Tatsuya grows to realize that he''s willing to sacrifice anything for the sake of his brother, except at the expense of giving up Minami to Kazuya. And thus the story is told of Tatsuya trying to prove himself over his established younger brother, how it affects the relationship between the three, and both brothers'' attempts to make Minami''s lifelong dreams come true.', 351, 'https://cdn.myanimelist.net/images/anime/3/53087.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eve no Jikan', 'ONA', 6, 'Completed', '2008-08-01', '2009-09-18', '8', 'In future Japan, in a time when android housekeepers have become commonplace, society strictly abides by the Three Laws of Robotics, which all androids must follow. Under the influence of the Robot Ethics Committee, androids are treated the same way as lesser technology, such as household appliances. However, a minority with an adoration for androids exists, categorized as "android-holics," and are shunned by the general public.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Black Clover: Mahou Tei no Ken', 'Movie', 1, 'Completed', '2023-06-16', NULL, '8', 'As a lionhearted boy who can’t wield magic strives for the title of Wizard King, four banished Wizard Kings of yore return to crush the Clover Kingdom.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aria the OVA: Arietta', 'OVA', 1, 'Completed', '2007-09-21', NULL, '8', 'Akari Mizunashi dreams of life after attaining her goal of becoming a Prima Undine, but upon waking realizes that she might not actually have the confidence to run Aria Company on her own. Wary of the future, she seeks advice from her mentor Alicia Florence—one of the three great "Water Fairies" of Neo-Venezia.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Ball', 'TV', 153, 'Completed', '1986-02-26', '1989-04-12', '8', 'Gokuu Son is a young boy who lives in the woods all alone—that is, until a girl named Bulma runs into him in her search for a set of magical objects called the "Dragon Balls." Since the artifacts are said to grant one wish to whoever collects all seven, Bulma hopes to gather them and wish for a perfect boyfriend. Gokuu happens to be in possession of a dragon ball, but unfortunately for Bulma, he refuses to part ways with it, so she makes him a deal: he can tag along on her journey if he lets her borrow the dragon ball''s power. With that, the two set off on the journey of a lifetime.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Komi-san wa, Comyushou desu. 2nd Season', 'TV', 12, 'Completed', '2022-04-07', '2022-06-23', '8', 'After an exciting and momentous cultural festival, Shouko Komi continues her endeavor to make one hundred friends alongside her friend and classmate Hitohito Tadano. As winter begins, the class is joined by the seemingly delinquent student Makoto Katai, who has been absent since the first week of school. Despite his intimidating appearance, Katai has difficulty communicating with others and just wants to befriend his classmates.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimi ni Todoke 2nd Season', 'TV', 12, 'Completed', '2011-01-12', '2011-03-30', '8', 'After a momentous New Year''s vacation and with Valentine''s Day approaching, Sawako Kuronuma is beginning to get along with her classmates. However, now that Sawako has realized her romantic feelings for the popular Shouta Kazehaya, she grows hesitant toward giving him obligatory chocolates and decides to not give him any. In turn, Kazehaya, who likes Sawako, feels a distance between them.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hachimitsu to Clover', 'TV', 24, 'Completed', '2005-04-15', '2005-09-27', '8', 'Yuuta Takemoto, a sophomore at an arts college, shares a cheap apartment with two seniors—the eccentric Shinobu Morita, who keeps failing to graduate due to his absenteeism, and the sensible Takumi Mayama, who acts as a proper senior to Takemoto, often looking out for him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bleach', 'TV', 366, 'Completed', '2004-10-05', '2012-03-27', '8', 'Ichigo Kurosaki is an ordinary high schooler—until his family is attacked by a Hollow, a corrupt spirit that seeks to devour human souls. It is then that he meets a Soul Reaper named Rukia Kuchiki, who gets injured while protecting Ichigo''s family from the assailant. To save his family, Ichigo accepts Rukia''s offer of taking her powers and becomes a Soul Reaper as a result.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aishang Ta de Liyou Extra', 'ONA', 1, 'Completed', '2024-02-13', NULL, '8', '', 736, 'https://cdn.myanimelist.net/images/anime/1569/141456.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Violet Evergarden CMs', 'Special', 2, 'Completed', '2016-05-27', '2017-03-16', '8', 'Special trailers released on YouTube announcing Violet Evergarden''s anime adaptation. Features all original animation not used in the series.', 494, 'https://cdn.myanimelist.net/images/anime/1485/125509.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Honzuki no Gekokujou: Shisho ni Naru Tame ni wa Shudan wo Erandeiraremasen', 'TV', 14, 'Completed', '2019-10-03', '2019-12-26', '8', 'Urano Motosu loves books and has an endless desire to read literature, no matter the subject. She almost fulfills her dream job of becoming a librarian before her life is ended in an accident. As she draws her last breath, she wishes to be able to read more books in her next life.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Durarara!!x2 Shou', 'TV', 12, 'Completed', '2015-01-10', '2015-03-28', '8', 'Although peace has finally returned to Ikebukuro, many of the odd occurrences have become common sights around the city. One such case is the police''s constant pursuit of Celty Sturluson, the Headless Rider. Moreover, someone has placed a large bounty on her, igniting the motivation of gang members all over to begin searching for the supernatural creature as well. Meanwhile, Mikado Ryuugamine is approached by Aoba Kuronuma, a mysterious underclassman with unknown intentions, who reveals that he knows Mikado''s true identity.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuroshitsuji: Sono Shitsuji, Kougyou', 'Special', 1, 'Completed', '2009-09-30', NULL, '8', 'Earl Ciel Phantomhive''s Funtom Corporation is sponsoring a charity performance of Hamlet to be shown to a group of poor children as a celebration of its third anniversary. However, when the theater company hired for the stage play is suddenly delayed and won''t make it in time for the scheduled performance, the company is faced with a dilemma. With the promise of plenty of press coverage, Ciel must find a way to rectify the situation and commands his butler, Sebastian Michaelis, to ensure the success of the play.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Haikyuu!! Tokushuu! Haru-kou Volley ni Kaketa Seishun', 'OVA', 1, 'Completed', '2017-08-04', NULL, '8', 'The OVA episode revisits the primary matches from the spring tournament and features interviews with players.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kemono Friends', 'TV', 12, 'Completed', '2017-01-11', '2017-03-29', '8', 'Japari Park is an untamed paradise where many humanoid animals, known as "Friends," live their everyday lives in all corners of the natural environmental park.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sword Art Online: Alicization - War of Underworld 2nd Season', 'TV', 11, 'Completed', '2020-07-12', '2020-09-20', '8', 'The final battle against the Dark Territory drags on, as players from all over the world flood the Underworld''s servers and plunge the Human Empire into utter chaos. Asuna Yuuki and her friends defend their new allies with everything they have, but their numbers are falling. Meanwhile, Alice Zuberg heads toward the World''s End Altar while Gabriel "Vecta" Miller relentlessly pursues her.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Utawarerumono: Futari no Hakuoro', 'TV', 28, 'Completed', '2022-07-03', '2022-12-25', '8', 'After the events of Mask of Deception, the Yamato Empire is now ruled with an iron fist by a ruthless usurper who seeks to subjugate all before him. It''s up to a couple of familiar faces to band together against the might of the Imperial army, and the fate of the world hangs in the balance as nations and generals must pick a side to fight with in this perilous civil war. Secrets will be revealed, friendships will be tested, and battles will be fought. Will peace and order be restored or will victory at any cost be the beginning of the end? 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Golgo 13 (TV)', 'TV', 50, 'Completed', '2008-04-12', '2009-03-28', '8', 'Golgo 13 is not his real name. Then again, neither is Duke Togo, Tadashi Togo, or any number of the aliases he goes by. A man of mystery, not even the world''s most prominent intelligence agencies can determine who Golgo really is, or just where he came from. But all agree that his skills are nothing short of legendary.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Demi-chan wa Kataritai', 'TV', 12, 'Completed', '2017-01-08', '2017-03-26', '8', 'High school biology teacher Tetsuo Takahashi may look like your average everyday instructor, but beneath his gentle appearance lies something less ordinary: his fascination for the "Ajin," more commonly known as "Demi." Although these half-human, half-monster beings have integrated into human society, Takahashi believes that much about them will remain unknown unless he interacts with them firsthand.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hataraku Saibou Black', 'TV', 13, 'Completed', '2021-01-10', '2021-03-19', '8', 'Due to poor lifestyle choices, a certain human''s body is in constant turmoil. With germs, bacteria, and foreign substances abound, the jobs of various cells become increasingly difficult and dangerous. As some of the unfortunate ones who matured in this chaotic environment, Sekkekkyuu AA2153 and Hakkekkyuu U-1196 strive to fulfill their duties—even if it means seeing many of their fellow cells lose their lives in duty.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hidamari Sketch Specials', 'Special', 2, 'Completed', '2007-10-19', NULL, '8', 'The four girls at Hidamari apartment complex continue her lives having a good time together. On the first episode of this special, they go together to the pool, and on the second episode Hiro receives a love letter on her locker, who could have sent it?', 791, 'https://cdn.myanimelist.net/images/anime/9/14372.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toaru Majutsu no Index II', 'TV', 24, 'Completed', '2010-10-08', '2011-04-01', '8', 'As tensions between the world of magic and Academy City continues to rise, Touma Kamijou and his hand of negation must face off against both esper and magician in order to protect the lives of those around him. Of course, he is not alone in his fight; whether by his side or out of sight, allies and enemies both old and new will enter the fray to help him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Momoko, Kaeru no Uta ga Kikoeru yo.', 'Movie', 1, 'Completed', '2003-07-23', NULL, '8', 'Momoko, who attends a special school, is both mentally and physically disabled. Every morning she becomes peevish because she can''t go to the ordinary school with her twin brother Riki. Her family soothes Momoko by singing her favorite song "The Song of Frogs."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Over Drive', 'TV', 26, 'Completed', '2007-04-04', '2007-09-26', '8', 'Mikoto Shinozaki is a high school student lacking in social awareness. In addition, due to his untidy appearance and low self-esteem, he is an easy target for bullies. Regardless, any misfortune that falls upon Mikoto is partly his own fault—at least, that is what Yuki Fukuzawa, the most popular girl in class, believes. With this assumption, Yuki invites Mikoto to join the school''s bicycle club, in hopes he can improve himself and gain new friends. Motivated by feelings he has for Yuki, Mikoto has no reason to decline her offer—except for the fact that he does not know how to ride a bicycle.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Final Fantasy VII: Advent Children - Venice Film Festival Footage', 'Movie', 1, 'Completed', '2005-09-14', NULL, '8', 'Advent Children Special Edition is the 25 minute version of the movie which was shown at the 62nd Venice Film Festival in 2005. Available as dvd bonus on 2-disc special edition.', 834, 'https://cdn.myanimelist.net/images/anime/9/13516.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shiroi Suna no Aquatope', 'TV', 24, 'Completed', '2021-07-09', '2021-12-17', '8', 'After leaving her idol career behind, Fuuka Miyazawa finds herself on a spontaneous flight to Okinawa instead of returning home to her pity party in Morioka. Bearing a heavy heart and nowhere to go, she aimlessly wanders around the area until she stumbles upon Gama Gama Aquarium—an aging aquarium on the verge of closing down.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xingchen Bian', 'ONA', 12, 'Completed', '2018-10-05', '2018-12-14', '8', 'Having problems with his meridians and thus rendered incapable of practicing the internal arts, Qin Yu lives in seclusion with Grandfather Lian. To cheer up a depressed Qin Yu, Lian gifts him a peculiar bird, which the former names Xiao Hei.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Net-juu no Susume', 'TV', 10, 'Completed', '2017-10-10', '2017-12-12', '8', 'For the first time since graduating high school, 30-year-old Moriko Morioka is unemployed—and she couldn''t be happier. Having quit her long-standing job of over 11 years, Moriko quickly turns to online games to pass her now-plentiful free time, reinventing herself as the handsome and dashing male hero "Hayashi" in the MMO Fruits de Mer. With the pesky societal obligations of the real world out of the way, she blissfully dives headfirst into the realm of the game, where she promptly meets the kind and adorable healer Lily. Befriending each other almost instantly, the two become inseparable just as Moriko herself becomes more and more engrossed in her new "life" as Hayashi. Eventually, Moriko adopts the reclusive lifestyle in its entirety, venturing out from the safety of her apartment only when absolutely necessary.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oban Star-Racers', 'TV', 26, 'Completed', '2006-09-23', '2007-03-25', '8', 'Eva''s birthday has just passed, and she hasn''t heard from her father. Despising the Boarding School she attends, she escapes using her Rocket Bike that she just completed. Taking on the alias "Molly," Eva sneaks with the Earth team to Alwas for the Great Race because the winner of the race gets any one wish granted. Little does the Earth Team know what danger awaits them...', 357, 'https://cdn.myanimelist.net/images/anime/12/3702.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kiniro Mosaic: Pretty Days', 'Movie', 1, 'Completed', '2016-11-12', NULL, '8', 'The episode is set during a school festival where Shinobu is assigned to write a script and make outfits for her class play. Youko and Alice notice that Shinobu is sleepy every morning and are worried that she might be getting tired of all the work. Will Shinobu be able to successfully complete all her tasks in time?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ling Long: Incarnation Special', 'ONA', 1, 'Completed', '2021-05-15', NULL, '8', 'Special chapter of Ling Long: Incarnation.', 1122, 'https://cdn.myanimelist.net/images/anime/1057/114752.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam SEED Freedom', 'Movie', 1, 'Completed', '2024-01-26', NULL, '8', 'In C.E.75, the fighting still continues.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boku ga Aishita Subete no Kimi e', 'Movie', 1, 'Completed', '2022-10-07', NULL, '8', 'A world where it has been established that people routinely swing between slightly different parallel worlds...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yu☆Gi☆Oh! Duel Monsters', 'TV', 224, 'Completed', '2000-04-18', '2004-09-29', '8', 'Yuugi Mutou is a naïve and lonely high school student who is fascinated by games. While staying with his grandfather, the owner of a game shop, he comes across an ancient Egyption relic known as the "Millennium Puzzle." Rumored to grant any wish to those who solve the Puzzle, Yuugi becomes determined to solve it to wish for some friends. After years of struggling, Yuugi manages to complete the puzzle and mysteriously finds that his wish has been fulfilled.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece Movie 04: Dead End no Bouken', 'Movie', 1, 'Completed', '2003-03-01', NULL, '8', 'Luffy and crew arrive at the harbour of Anabaru. The local casino is holding a competition in which the winner will obtain a huge monetary reward if he reaches the finishing line first. Nami is elated and decides to participate in the competition. However, there is a conspiracy going behind the competition and the mastermind is an ex-military commander, Gasparde. His plan is to lure all the pirates to the military base and send them to their deaths. Luffy and gang have to overcome the numerous tests and tribulations along the way to complete this dead-end adventure.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fugou Keiji: Balance:Unlimited', 'TV', 11, 'Completed', '2020-04-10', '2020-09-25', '8', 'Daisuke Kanbe, a man of extraordinary wealth, is assigned to the Modern Crime Prevention Headquarters as a detective. It is there that he gets partnered with Haru Katou, a humane detective who values justice above all. The two are polar opposites, and their morals clash time and time again. Haru despises Daisuke for using monetary wealth to solve cases, as he believes that money is not everything. They will have to combine their efforts, however, to solve the mysteries that are coming their way.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oishinbo', 'TV', 136, 'Completed', '1988-10-17', '1992-03-17', '7', 'Oishinbo is a drama about newspaper reporters. The main character is a cynical food critic named Yamaoka. Oishinbo is a popular mainstream comic for adults in Japan. It is even mentioned in an episode of "Iron Chef."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Danball Senki Wars', 'TV', 37, 'Completed', '2013-04-03', '2013-12-25', '7', 'Year 2055, four years after the events in Danball Senki W. LBXs have become the world’s largest hobby, big enough for pro leagues to be established, and people to make their entire living off being an LBX player. 14-year-old Arata is a new transfer student at Kamui Daimon Integrated Academy on Kamui Island, near Japan. Known to be the most prestigious institution in the world for raising LBX players and mechanics, entrance to the academy requires an extremely competitive hurdle of being the champion of at least three official tournaments. Along with other members of his platoon, they face rivals and delve into the secrets lurking within the academy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kiddy Grade: Maelstrom', 'Movie', 1, 'Completed', '2007-06-23', NULL, '7', 'A recap of the original anime''s second quarter.', 341, 'https://cdn.myanimelist.net/images/anime/2/56969.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('You Yao 2', 'ONA', 24, 'Completed', '2023-09-27', '2024-02-07', '7', 'This story takes place in ancient Liang, where many locals, upon their deaths, have their bodies inhabited by souls from 2,000 years in the future, transforming into time travelers. These time travelers bring advanced experiences and knowledge to Liang, simultaneously raising suspicions and concerns among the reigning emperor. Amidst the changing tides, a time traveler named Lou Zhu, who advocates for peace, forms a deep bond with Zuo Yunqi, a native member of a prominent family, and attempts to find a path to progress and coexistence for all. However, tensions between the imperial court and radical time travelers escalate rapidly. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kindaichi Shounen no Jikenbo: Kuromajutsu Satsujin Jiken-hen', 'OVA', 2, 'Completed', '2012-12-17', '2013-03-15', '7', 'Kindaichi is back with another mystery to solve.', 1030, 'https://cdn.myanimelist.net/images/anime/3/45070.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Geragera Boes Monogatari', 'TV', 52, 'Completed', '1987-04-07', '1988-03-29', '7', 'Farm life has never been this wacky. Where else could you find a turtle with a built in TV under his shell, a bald lion, an elephant whose trunk doubles as a garden hose and an inflatable octopus. All run by a good-natured ox named Olly.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doraemon Movie 16: Nobita no Sousei Nikki', 'Movie', 1, 'Completed', '1995-03-04', NULL, '7', 'Nobita had to find a topic for his summer break research homework. As he was blaming everything to Adam and Eve for sinning and causing their descendants to suffer (from homework), Doraemon decided to provide him with a gadget to observe the creation of the world so that he may write it in a diary-like report. Suneo, Giant and Shizuka eventually joined them and together they watch over the birth of tribes and civilizations. Meanwhile, the time patrol is looking for an illegal time machine whose controllers accidentally heard Giant speaking of the genesis diary project. They captured Giant and Suneo; leaving Nobita, Shizuka and Doraemon to watch over the genesis set and to rescue them. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Stranger: Mukou Hadan Pilot', 'Special', 1, 'Completed', '2008-04-11', NULL, '7', 'Young Nanashi is a drifting samurai under the service of an enigmatic monk who teaches the ways of life. In search for the meaning of life, Nanashi is forced to partake in certain horrendous acts to overcome the corrupt governments of China and Japan. The mysterious and observant samurai is forced to show a dark side to accomplish his goals and rescue society.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Takahashi Rumiko Gekijou Ningyo no Mori', 'TV', 11, 'Completed', '2003-10-05', '2003-12-21', '7', 'According to an ancient legend, mermaid''s flesh can grant immortality if eaten. 500 years ago, Yuta unknowingly ate a piece of mermaid''s flesh. For centuries, he travels across Japan, hoping to find a mermaid, thinking she may be able to make him a normal human again. When he finally finds one, he discovers that she and her companions have been raising a girl to be their food so they can eat her and take on her youthful looks. That is how mermaids stay young. Yuta kills the mermaids and rescues her, but she has already eaten some of the mermaid''s flesh. Although he had to kill the mermaids, Yuta isn''t too disappointed. Yuta''s once lonely existence is now over, as he has found a companion in Mana. And Mana, who had been trapped in a small hut her whole life, finds delight in even the simplest of things. Together, Yuta and Mana attempt to seek out more mermaids, trying to become normal humans again. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yami no Matsuei', 'TV', 13, 'Completed', '2000-10-02', '2000-12-18', '7', 'Even after death, life is full of paperwork and criminals. Tsuzuki Asato is a 26 year old, happy-go-lucky, and dorky shinigami (god of death) whose job is to makes sure that those who are dead remain dead and stay in their proper realms. Even though he''s had this job for over 70 years, he is in the worst division with horrible pay. He also has a knack for not keeping partners (since shinigami work in pairs), but now he seems to have one that will stick around; stubborn, smart-mouthed, serious and defensive 16 year old, Kurosaki Hisoka. With each case they investigate, they come closer to the conspiracies of the serial killer Dr. Muraki Kazutaka. Tsuzuki''s relationship with Hisoka is growing stronger and closer...but there is a dark past to how Tsuzuki died that will not give him peace. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fate/Zero Remix', 'Special', 2, 'Completed', '2012-03-25', '2012-04-01', '7', 'Two recap specials titled "Fate/Zero Remix I" and "Fate/Zero Remix II" serve to summarize the first 13 episodes of Fate/Zero.', 1192, 'https://cdn.myanimelist.net/images/anime/1629/122105.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wasurenagumo', 'Special', 1, 'Completed', '2012-03-12', NULL, '7', 'Legend says that centuries ago, a colossal spider ravaged Tokyo. Resistance was futile, as none could quell the havoc wrought upon the city by the beast. Fortunately, one man—the legendary exorcist—stopped the devastation. Using his divine powers, he sealed the monster away and the world has enjoyed peace ever since. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ichigo Mashimaro Episode 0', 'Special', 1, 'Completed', '2005-06-08', NULL, '7', 'A brief special where the girls pretend to be astronauts.', 226, 'https://cdn.myanimelist.net/images/anime/10/19666.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Taiho Shichau zo Special', 'TV', 20, 'Completed', '1999-03-30', '1999-04-30', '7', 'Best friends and partners Miyuki Kobayakawa and Natsumi Sujimoto, along with the rest of the gang at Bokuto station, confront a motley group of offenders ranging from hi-tech panty thieves, purse-snatchers, and traffic violators. Using Miyuki''s driving prowess and tech knowledge, as well as Natsumi''s spunk and strength, the duo at times must resort to unconventional methods to see that justice is served.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Galaxy Angel', 'TV', 24, 'Completed', '2001-04-08', '2001-09-30', '7', 'The Angel Brigade, an elite branch of the Transbaal Empire military, are assigned to search for The Lost Technology, mysterious items from the past that hold unknown powers. Led by the soon to retire Colonel Volcott O'' Huey, the Angel Brigade travel to different planets using their specially designed Emblem Frame ships to search for Lost Technology. Unfortunately, they usually mess up somehow and end up getting into all kinds of weird and troublesome situations.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('B''T X', 'TV', 25, 'Completed', '1996-04-06', '1996-09-21', '7', 'Teppei is going to visit his older brother Kotaro Takamiya during a scientific conference after training with a mysterious woman named Karen for the past 11 years. However his plans for a family reunion become stalled when a woman named Aramis kills everyone in the conference to kidnap Kotaro. Teppei on the way to save his brother encounters a broken mechanical horse called B''t X who revives thanks to Teppei''s blood and is now his aide to save his brother from the mysterious Machine Empire.', 990, 'https://cdn.myanimelist.net/images/anime/1900/139246.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Madlax', 'TV', 26, 'Completed', '2004-04-06', '2004-09-28', '7', 'In the country of Gazth-Sonika, civil war rages. There, a mercenary called Madlax plies her trade, with almost supernatural skill. In the seemingly peaceful country of Nafrece, Margaret Burton lives a tranquil life. As separate as their lives may seem, the two are connected by ties of mystery, and by a holy book that is also sought by the shadowy organisation, Enfant. As Margaret and Madlax follow the path of their destiny, they come ever closer to uncovering the truth - with no guarantee that it is a truth they can bear to learn.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mashiro-iro Symphony: The Color of Lovers', 'TV', 12, 'Completed', '2011-10-05', '2011-12-21', '7', 'When boys suddenly get into places where they''ve never been allowed before, some girls tend to get upset. So when the decision is made to merge the elite Yuihime Girls'' Private Academy and the coeducational Kagamidai Private Academy, everyone wants to take extra care in avoiding trouble while bringing the two Privates together. Therefore, rather than just bringing the Kagamidai boys into the Yuihime girls'' school all at once, a plan is concocted in which a group of test males will be inserted into the Girls'' Private Academy first.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mamoru-kun ni Megami no Shukufuku wo!', 'TV', 24, 'Completed', '2006-10-06', '2007-03-30', '7', '"Beatrice". It is a mysterious power that responds to people’s will and realize all of them. Tokyo Beatrice University Attached High School is the only school that teaches Beatrice called "magic appears in the real world".
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tokimeki Memorial: Only Love', 'TV', 25, 'Completed', '2006-10-03', '2007-04-03', '7', 'Aoba Riku has just transferred to a new high school because of his father''s job, and things aren''t quite what he expected. The headmaster''s secretary controls the school while espousing the virtues of academic freedom, the teachers are even stranger than normal teachers, and half the student body is walking around with animal ears on. On his very first day, Riku is unfortunate enough to find himself at the center of the student council''s latest event, which has him running for his life. All this on top of the normal high school rigour of popularity contests, crushes, and homework makes it unsure whether Riku will be able to survive this new school.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Asatte no Houkou.', 'TV', 12, 'Completed', '2006-10-06', '2006-12-22', '7', 'About to enter junior high school, Karada Iokawa is a cheerful and reliable girl, who hates being treated as a child more than anything. After her parents'' deaths, her older brother, Hiro, comes back from studying abroad to take care of her. His ex-girlfriend Shouko Nogami, a composed yet sometimes childish and stubborn young woman, follows him to Japan in order to find out why he left her. Between the two girls, the atmosphere is tense, which eventually leads to Shouko calling Karada childish.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sekirei', 'TV', 12, 'Completed', '2008-07-02', '2008-09-17', '7', 'Struggling yet brilliant 19-year-old Minato Sahashi has failed his college entrance exams for the second time, resulting in him being regarded as worthless by those around him. However, the course of his seemingly bleak future is altered dramatically when a beautiful, supernatural woman falls from the sky and into his life. That woman, Musubi, is a unique being known as a "Sekirei," a humanoid extraterrestrial with extraordinary abilities. These aliens are known for kissing humans carrying the Ashikabi gene in order to awaken additional latent powers deep within.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Soredemo Ayumu wa Yosetekuru', 'TV', 12, 'Completed', '2022-07-08', '2022-09-23', '7', 'When middle school kendo champion Ayumu Tanaka begins his first year in high school, he does not take the expected route of joining the Kendo Club; he signs up for the unofficial Shogi Club instead. His sole motive is falling in love at first sight with Urushi Yaotome—the club''s president and only member—and will do anything to get closer to her. However, Ayumu decides not to confess to Urushi until he can beat her in a match of shogi fair and square.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blue Gender', 'TV', 26, 'Completed', '1999-10-08', '2000-03-31', '7', 'Blue Gender takes place in the not too distant future in a world where things have gone terribly wrong for humanity. Humans have been replaced at the top of the food chain by the Blue, a race of bug-like aliens that have colonized Earth and pushed humans aside. A space station, Second Earth, has been constructed as a safe haven for humans, with the hope of one day reclaiming the Earth once more.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blue Thermal', 'Movie', 1, 'Completed', '2022-03-04', NULL, '7', 'Tamaki Tsuru joins Aonagi University in hopes of making friends, getting a boyfriend, and living a typical university student life. She decides to try out for the tennis club in order to make friends and avoid anything too athletic. But when she is distracted by a model glider during tryouts, Tamaki ends up hitting a tennis ball right at it, smashing it into pieces. Daisuke Sorachi, a member of the Aviation Club, demands that she pay for the damages.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Terra Live', 'ONA', 8, 'Completed', '2025-05-16', '2025-06-27', '7', '', 826, 'https://cdn.myanimelist.net/images/anime/1060/149836.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zaiyuki Pilot', 'ONA', 1, 'Completed', '2023-12-30', NULL, '7', 'Pilot version of the upcoming Zaiyuki series released on Twitter.', 1086, 'https://cdn.myanimelist.net/images/anime/1167/140701.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boku no Hero Academia: UA Heroes Battle', 'Movie', 1, 'Completed', '2023-10-20', NULL, '7', 'The stage this time is the UA dormitory, taking place just before the Endeavor Internship arc.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hananoi-kun to Koi no Yamai', 'TV', 12, 'Completed', '2024-04-04', '2024-06-20', '7', 'Hotaru Hinase has lived nearly sixteen years without romance. She is satisfied alone as long as she can enjoy the little things in life with her beloved friends and family. In her mind, she is not meant to fall in love, nor does she understand the concept.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaii to Otome to Kamikakushi', 'TV', 12, 'Completed', '2024-04-10', '2024-06-26', '7', 'Adult life has brought its share of disillusions to 28-year-old writer Sumireko Ogawa, who was once considered a child prodigy in literature. Facing hostility from editors, she struggles to publish her work and progress in writing her new novel. As Sumireko starts to resign herself to the uneventful life of a book clerk, she is brutally plunged into the realm of mysteries after she reads poetry from a strange book, as she unexpectedly becomes a child again.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boukensha ni Naritai to Miyako ni Deteitta Musume ga S-Rank ni Natteta', 'TV', 13, 'Completed', '2023-09-28', '2023-12-21', '7', 'While on an errand in the forest, retired E-rank adventurer Belgrieve stumbles upon a basket that holds an abandoned baby girl. Taking pity on her, Belgrieve decides to adopt the infant and names her Angeline.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin no Nakama ja Nai to Yuusha no Party wo Oidasareta node, Henkyou de Slow Life suru Koto ni Shimashita 2nd', 'TV', 12, 'Completed', '2024-01-07', '2024-03-24', '7', 'Finally free of her Blessing''s impulses, former Hero Ruti has settled into her idyllic slow life with assassin housemate Tisse in the border town of Zoltan. She''s happy to once again be close to her apothecary brother Red, the former Guide of her previous Hero''s Party, while he''s living his best loved-up life with his partner (and soon-to-be fiancee) Princess Rit. Unfortunately, there''s a new Hero on the scene whose fundamentalist interpretation of his Blessing''s urges will bring conflict and despair to sleepy Zoltan…
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dekoboko Majo no Oyako Jijou', 'TV', 12, 'Completed', '2023-10-01', '2023-12-17', '7', 'While walking through the forest one day, a witch named Alyssa finds a bush glowing with a magical aura. She discovers a baby who, although not a witch, possesses magic that is too strong for that of a mere human. As such, Alyssa decides to raise the child as her own, naming her Viola.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kitaku-bu Katsudou Kiroku', 'TV', 12, 'Completed', '2013-07-05', '2013-10-11', '7', 'When a friend asks Natsuki what high school club she''s going to join, she cheerfully responds "the go-home club" (meaning, she''s not going to join any of them). However, she soon realizes that this club actually exists at her high school, and she''s just expressed interest in joining it! Before she knows it, she ends up as one of the two new members of "the go-home club," which is a small group of eccentric school girls. One of the girls likes fighting bears, while another is ridiculously rich. But what exactly constitutes the activities of "the go-home club"?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Natsu-iro Kiseki: 15-kaime no Natsuyasumi', 'OVA', 1, 'Completed', '2012-08-29', NULL, '7', 'A seven minute epilogue to the TV series, released as an OVA.', 974, 'https://cdn.myanimelist.net/images/anime/6/41923.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Code:Realize - Sousei no Himegimi - Set a Thief to Catch a Thief', 'OVA', 1, 'Completed', '2018-05-17', NULL, '7', 'It has been a month since London was struck with tragedy, and a ceremony symbolizing peace and restoration will soon be held. In light of these events, Arsène Lupin plans to throw a party for Cardia Beckford to honor the fulfillment of her wish. Lupin sets out on a search for the perfect gift to offer her; however, he finds himself caught up in the theft of a valuable jewel, and he is framed and believed to be the culprit. With Lupin locked behind bars, his friends work along with Cardia and an unexpected ally to clear Lupin''s name and find the real perpetrators behind the heist. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gundam Build Fighters: Battlogue', 'ONA', 5, 'Completed', '2017-08-04', '2017-12-08', '7', 'This is a dynamic dream battle featuring many types of Gunpla skirmishing in all sorts of situations.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shuumatsu no Izetta', 'TV', 12, 'Completed', '2016-10-01', '2016-12-17', '7', 'After Germania invaded a neighboring country in 1939, Europe spiraled into a devastating war. During the war, Germania set its sights on the weak alpine country of Elystadt. Boasting a far superior military and having achieved profuse success earlier in the war, it was expected that Germania would conquer Elystadt with ease.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gundam Build Fighters Try: Island Wars', 'Special', 1, 'Completed', '2016-08-21', NULL, '7', 'One year after winning the Gunpla Battle National Championships, Team Try Fighters is invited by Yajima Trading to a remote island to test the company''s new battle system. Sekai and Fumina arrive on the island, only to discover that Gyanko, Shia and Minato were also invited. Yuuma declines the offer as he is assisting Mirai on a photoshoot, only to realize that he and his teammates are on the same island. Meanwhile, the Nielsen Lab experience an anomaly when their new Plavsky particles form a giant crystal and cause Gunpla on the island to go out of control. The Gunpla Fighters must band together to stop the crystal from wreaking havoc on all Gunpla Battle Systems around the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Re-Kan!', 'TV', 13, 'Completed', '2015-04-03', '2015-06-26', '7', 'Hibiki Amami would be a regular high school girl if it weren''t for one thing: a sixth sense that allows her to see ghosts. Rather than being scared, Amami is more interested in befriending and helping the apparitions. This often leads to her human friends witnessing paranormal activity as the ghosts try to help Amami with everyday tasks. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sora no Method', 'TV', 13, 'Completed', '2014-10-05', '2014-12-28', '7', 'A group of friends—Nonoka Komiya, Koharu Shiihara, Shione Togawa, and twins Yuzuki and Souta Mizusaka—once attempted to summon a flying saucer to grant their wishes. After thinking that they failed, they called it a day. However, soon afterward, Nonoka abruptly moved out of Kiriya City, breaking the bond of their circle. Little did the group know, they were successful and the saucer has been floating in the sky since then, waiting to fulfill its purpose.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chuunibyou demo Koi ga Shitai! Depth of Field: Ai to Nikushimi Gekijou', 'Special', 7, 'Completed', '2012-12-19', '2013-06-19', '7', 'Specials bundled with the first season''s BD/DVD volumes that displays a mech fight between Rikka Takanashi and Sanae Dekomori.', 494, 'https://cdn.myanimelist.net/images/anime/9/43245.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Black Lagoon Omake', 'Special', 7, 'Completed', '2009-12-23', '2010-03-25', '7', 'Special omake episodes from the Blu-Ray releases, showing the heroines and foes in funny, uncommon situations.', 538, 'https://cdn.myanimelist.net/images/anime/13/22266.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Quanzhi Fashi II', 'ONA', 12, 'Completed', '2017-09-15', '2017-12-01', '7', 'After defeating Yu Ang at the cost of revealing his lightning element, Mo Fan has been granted seven days to train in the Underground Holy Spring, where it is said that one can greatly increase their power level.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mayonaka no Occult Koumuin', 'TV', 12, 'Completed', '2019-04-08', '2019-06-24', '7', 'The Nocturnal Community Relations Division is a team of people who specialize in solving cases involving the ominous occult creatures of the night unseen by ordinary humans. Young and unsuspecting Arata Miyako has been assigned to the Shinjuku Ward Office of the division, where he meets his fellow members Theo Himezuka and Kyouichi Sakaki. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ochikobore Fruit Tart', 'TV', 12, 'Completed', '2020-10-12', '2020-12-28', '7', 'Ino Sakura has just moved to Tokyo to join the newly formed Fruit Tart, an idol group composed of three members besides herself—Roko Sekino, a washed-up child actor; Hayu Nukui, a failed musician; and Nina Maehara, a model who is still waiting for her first gig. They soon begin their new life together in their dormitory, the Mouse House. But there is no time to get settled as the girls awaken to a shocking reality: Fruit Tart is in a deep debt of one hundred million yen and has not even started yet!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chuubyou Gekihatsu Boy', 'TV', 11, 'Completed', '2019-10-04', '2019-12-13', '7', 'When Mizuki Hijiri transferred to a new school, all she wanted was to live a normal school life, but that did not prove to be the case when she met the infamous Hero Club. All of its members are boys suffering from various types of chuunibyou—Yamato Noda is a righteous hero, using his athletic abilities to perform noble deeds and protect others; Kazuhiro Nakamura claims to be the reincarnation of "Touga Ryushouin," the result of the forbidden union between a demon and an angel; Tomoki Takashima is a pretty-boy otaku whose one true love is the 2D anime girl Sora; and Rei Tsukumo plays the role of a schemer, covertly pulling the strings.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Andersen Monogatari (TV)', 'TV', 52, 'Completed', '1971-01-03', '1971-12-26', '6', 'Adaptations of numerous stories written by Hans Christian Andersen.', 587, 'https://cdn.myanimelist.net/images/anime/7/69035.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tobiuo no Boy wa Byouki desu', 'Movie', 1, 'Completed', '1982-01-01', NULL, '6', 'An anime about Operation Castle and the demise of the crew on the Daigo Fukuryuu Maru (S.S. Lucky Dragon 5). On March 1st 1954, a hydrogen bomb went off (that ended up being similar sized to the atomic bomb dropped on Hiroshima). The radioactive ash fell on the crew, poisoning them.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Don Chuck Monogatari', 'TV', 73, 'Completed', '1976-04-07', '1978-03-25', '6', 'More adventures for Chuck and his friends.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Midnight Eye: Gokuu II', 'OVA', 1, 'Completed', '1989-12-22', NULL, '6', 'When private detective Gokuu Fuurinji is contacted by Ryoko Kadoma about locating her missing brother, Ryuu, Gokuu knows this is no normal case. Ryuu was the victim of a cruel genetic experiment and will soon become a mindlessly violent superbeing without proper treatment. Armed with the world''s most powerful supercomputer implanted in his left eye, the detective sets out to locate the missing boy. But as the case becomes more complex, Gokuu is forced to question whether it is possible to save Ryuu or if he will have to kill him before he fully transforms.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ushio to Tora: Comical Deformer Gekijou', 'OVA', 1, 'Completed', '1993-10-01', NULL, '6', 'Ushio encounters a strange purple monster that seems to be helpful, Tora deals with a kitten, and finally there is a mass chase, reprising all of the monsters from the OVA series.', 674, 'https://cdn.myanimelist.net/images/anime/1305/127095.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fuuma no Kojirou: Yasha-hen', 'OVA', 6, 'Completed', '1989-06-01', '1989-08-02', '6', 'Hakuo Academy was once a respected school where many students dreamed of being admitted. Now, its rival academy Seishikan is on a mission to assimilate all other schools, and Hakuo Academy is its next target. Supported by the fearsome Yasha clan, Seishikan students frequently visit Hakuo''s campus to assault and forcibly convince their best students and athletes to transfer to Seishikan.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Anpanman to Hajimeyou! Iro, Kazu, Katachi Wakaru ka na Iro, Katachi', 'OVA', 1, 'Completed', '2006-07-26', NULL, '6', 'Part of the "Let''s start with Anpanman" series of educational animation for kindergarten children featuring characters from Anpanman.', 990, 'https://cdn.myanimelist.net/images/anime/13/52397.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Happy Seven: The TV Manga', 'TV', 13, 'Completed', '2005-10-03', '2005-12-26', '6', 'Amano Sakogami is a girl who has an unnatural amount of bad luck. One day, she stumbles into the clubroom of the Better Fortune Research Organization, which consists of a boy and seven other girls who secretly use the power of the luck deities to fight against the Magatsugami, monsters who can affect a person''s luck &amp; well-being. Amano soon becomes the club''s manager, and joins the club in their fight against the Magatsugami and their controller, Kukitomoe.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Isuca: Gokuraku', 'OVA', 1, 'Completed', '2015-08-26', NULL, '6', 'Shinichirou Asano, Sakuya Shimazu, and their friends arrive at one of the Shimazu family''s private islands for a vacation. However, what starts as a fun and relaxing outing soon takes a turn for the supernatural when the group heads into the island''s forest. As their companions mysteriously vanish one after the other, Shinichirou and Sakuya quickly find themselves all alone on a seemingly uninhabited island.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Code Geass: Soubou no Oz Picture Drama', 'OVA', 5, 'Completed', '2013-01-10', NULL, '6', 'Code Geass: Soubou no Oz Picture Drama following the lives of two characters from opposite sides of the barricades: Orpheus Zevon—young theorist from KMF searching for the killer of his mistress and Oldrin Zevon—protiteristické member unit of the British Empire "Glindyni knights." Drama quite obviously inspired by the classic story of The Wizard of Oz.', 974, 'https://cdn.myanimelist.net/images/anime/9/61133.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Megumi no Daigo: Kajiba no Baka Yarou', 'Movie', 1, 'Completed', '1999-07-27', NULL, '6', 'Daigo Asahina is Medaka Gumi #2''s/Me Gumi''s new rookie firefighter, and already he''s done crazy things, like throwing people off of a rooftop to save them from an explosion. He had good intentions, but his deeds are starting to hurt the company''s reputation. At Sengoku City''s Concert Hall, a fire breaks, and the some Emergency Rescue Squad needs rescuing. Daigo will do all he can to keep his promise: Not to let anyone die on the job.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon''s Heaven', 'OVA', 1, 'Completed', '1988-02-25', NULL, '6', 'In the year 3195, there was a war between an army of robots and the humans. When Shaian, a sentient combat armor, lost his companion in battle, he shut down until his internal systems spotted a new human. It''s now almost a 1000 years later, and Shaian''s greatest enemy is still alive and doing battle in Brazil. With a new friend`s help, Shaian may be able to stop this evil force before another war rages over the continent.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Beatless', 'TV', 20, 'Completed', '2018-01-13', '2018-06-30', '6', 'With great advancements in technology, mankind has created hIEs, human-like robots that act as public and personal servants for society. Unlike many others, the kind-hearted high school student Arato Endou treats hIEs as equals, but his financial situation keeps him from ever owning one.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Megami Kouhosei Special Curriculum', 'OVA', 1, 'Completed', '2002-05-25', NULL, '6', 'A retelling of the TV series from the point of view of one of the Goddess Pilots.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Battle Spirits: Mirage', 'ONA', 4, 'Completed', '2021-10-29', '2022-04-01', '6', 'Sequel to Battle Spirits: Kakumei no Galette.', 116, 'https://cdn.myanimelist.net/images/anime/1314/120786.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Onegai My Melody: Yuu & Ai', 'Movie', 1, 'Completed', '2012-08-11', NULL, '6', 'Set before the events of Sweets Dance Princess, it focuses about My Melody''s summer camping in Mary Land and how her friendship with Kuromi is becoming better, despite the upsetting experiences and misunderstandings she had during camp.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ni Zhenshi Ge Tiancai', 'ONA', 24, 'Completed', '2022-04-23', '2022-07-09', '6', 'In another world, there are two continents, east and west. The northern part of the Western Continent lives with the mysterious Snow Mountain tribe, while the southern part is occupied by the prosperous Daqin Empire. Magic is the source of energy in the world. The Daqin Empire relied on the power of magic to defeat countless enemies and disasters, and established a prosperous civilized world. A boy from a tribe with a forbidden demon physique from the north started a journey of magic cultivation in the southern continent full of magic power.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sore Ike! Anpanman: Yomigaere Bananajima', 'Movie', 1, 'Completed', '2012-07-07', NULL, '6', 'In the southern country of Banana island, the energetic princess and his humble servant Banna invite Anpanman and his friends to their biggest festival "Banana Matsuri". But when they arrive a stormy and cold day bestows the island and withers all the Banana crop. While searching for the cause on the Banana Mountain a water monster appears that threatens to take back the island to the water world. With the help of Banna, can Anpanman and his friends rescue the island from this crisis?', 990, 'https://cdn.myanimelist.net/images/anime/3/39427.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bokutachi no Remake Recap', 'Special', 1, 'Completed', '2021-08-14', NULL, '6', 'Recap of the first 6 episodes of Bokutachi no Remake.', 1162, 'https://cdn.myanimelist.net/images/anime/1776/117125.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi SD Gundam Mk-I', 'Special', 3, 'Completed', '1988-03-12', '1988-05-25', '6', 'A collection of short parodies of the Mobile Suit Gundam saga. Episode 1 pokes fun at key events that occurred during the One Year War. In episode 2, Amuro, Kamille and Judau fight over who runs the better pension when Char comes in to crash their party. Episode 3 is the SD Olympics, an array of athletic events pitting man with mobile suit.', 974, 'https://cdn.myanimelist.net/images/anime/3/51035.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Naze Ikiru: Rennyo Shounin to Yoshizaki Enjou', 'Movie', 1, 'Completed', '2016-05-21', NULL, '6', 'Ryouken, a young man who hates temples and monks, laments his misfortunes but finds hope in his soon-to-be-born child. An unfortunate accident took everything from Ryouken. In the days of self-abandonment and suffering in darkness, Ryouken finds the teachings of the high priest Rennyo. In it, he finds answers to the question "Why live" as explained by the sage Shinran. As he is drawn into the teachings and no longer hesitates, Ryouken becomes Rennyo''s apprentice. The number of worshippers increase, but the Honganji temple becomes a target of the other sects, forcing Ryouken and Rennyo to flee from Kyoto. In order to find a new place to teach, they arrive in Yoshizaki (now in Fukui Prefecture) in the Hokuriku region.', 879, 'https://cdn.myanimelist.net/images/anime/12/79603.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Time Bokan 24', 'TV', 24, 'Completed', '2016-10-01', '2017-03-18', '6', 'Tokio is a junior high student living in the present time who is recruited to be a member of the 24th century''s Space-Time Administration Bureau. Together with his partner Calen, their mission is to uncover the "True History", the part of history that the textbooks doesn''t tell. But in their way is the Akudama Trio that intends to prevent the True History from being revealed for their own personal gains.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Go! Go! Atom', 'TV', 52, 'Completed', '2019-10-03', '2020-10-01', '6', 'The eco-systems of planet Earth are endangered. Lucky for us, a super-powered robot boy is flying to rescue! astro in on a mission to help anyone anywhere in the world with a problem involving natural phenomena. Go little Astro Boy! GO! 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cop Craft: Utsukushiki Onna Kishi! Toraware no Yousei wo Oe!', 'Special', 1, 'Completed', '2019-09-10', NULL, '6', 'Recap of the first four episodes of Cop Craft series from Tilarna''s perspective.', 566, 'https://cdn.myanimelist.net/images/anime/1815/103061.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shiohi Girls: Vongole Bianco', 'ONA', 48, 'Completed', '2019-11-13', '2020-04-24', '6', '', 215, 'https://cdn.myanimelist.net/images/anime/1284/105657.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchuu no Kishi Tekkaman Blade II: Virgin Memory', 'Special', 1, 'Completed', '1998-06-05', NULL, '6', 'A recap episode of Tekkaman Blade II, included on the Tekkaman Blade LD BOX in 1998 and later also included on the BD Box in 2016.', 1009, 'https://cdn.myanimelist.net/images/anime/1447/108299.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchuu Kaizoku Mito no Daibouken Pilot', 'Special', 1, 'Completed', '1999-01-01', NULL, '6', 'A short prequel to Uchuu Kaizoku Mito no Daibouken series.', 1053, 'https://cdn.myanimelist.net/images/anime/8/70405.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Harbor Tale', 'Movie', 1, 'Completed', '2011-12-17', NULL, '6', 'In this mixed media stop motion / CG animation short Harbor Tale (ハーバーテイル), Yuuichi Itou anthropomorphises a red brick who has resided on the corner of a red brick building since the times when the clack of geta could be heard on the busy streets of Yokohama.  The building is only a couple of blocks from the harbour and when the building was new the red brick recalls seeing a white sailboat coming into port. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Time Bokan Series: Gyakuten Ippatsuman', 'TV', 58, 'Completed', '1982-02-13', '1983-03-26', '6', 'Gyakuten! Ippatsuman is the sixth in the Time Bokan series. In the 1990s-era Osteandel City is the headquarters of Time Lease, a business that leases almost everything you could ask for including powerful robots. They are proud of themselves for being number one in the international ranking of billionaires, for the past ten consecutive years. Meanwhile there is another lease company in the same city called Skull Lease where the notorious villain trio work as top executives. Their ostensible object is to disgrace the credit of Time Lease and replace them as the leading enterprise. In fact, however, they have a scheme to secure a footing for world conquest. One day a transport robot of Time Lease is assaulted by the villain trio and it is time for Ippatsuman to get on the move to fight for justice.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ane Log: Moyako Neesan no Honpen wo Tobidashite Tomaranai Monologue', 'OVA', 6, 'Completed', '2014-04-18', NULL, '6', 'Short flash episodes included on the Ane Log Fan Disc.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Iya na Kao sare nagara Opantsu Misete Moraitai 2', 'ONA', 6, 'Completed', '2019-11-22', '2019-12-27', '6', 'A project where a number of women in different costumes show their panties while they make a disgusted face.', 16, 'https://cdn.myanimelist.net/images/anime/1682/100905.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tenjouhen: Utsunomiko', 'Movie', 1, 'Completed', '1990-09-22', NULL, '6', 'Prequel of Utsunomiko.', 1030, 'https://cdn.myanimelist.net/images/anime/6/12812.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zenmai Zamurai', 'TV', 215, 'Completed', '2006-04-03', '2009-02-06', '6', '200 years ago, Zenmai Zamurai was a thief by profession. While stealing from a house one night, he fell down a well and died. He was then resurrected by Daifukunokami and a wind-up key was placed on his head. If the key wound down, Zennosuke would die. The only way the key can be wound is by Zennosuke doing good deeds. In order to achieve this end, he is given the Dango-ken, which is a sword with Japanese Dumplings skewered onto it. Whenever Zenmai Zamurai sees people doing injustice or generally being out of control, he uses his sword to shoot the dumplings into their mouths. When the dumplings are eaten, the people suddenly become happy and realize the error of their ways. He helps out the people of his village in many ways, big and small. Whenever he has done well, a rainbow comes out of the sky to wind up his key.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rokumon Tengai Mon Colle Knights Movie: Densetsu no Fire Dragon', 'Movie', 1, 'Completed', '2000-12-21', NULL, '6', 'An alternative interpretation of the series'' start.', 879, 'https://cdn.myanimelist.net/images/anime/13/10678.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Battle Mode', 'Special', 1, 'Completed', '1990-01-01', NULL, '6', 'Promotional video for an anime shop "Parody" in Nara Prefecture.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Umi no Yami, Tsuki no Kage', 'OVA', 3, 'Completed', '1989-10-14', NULL, '6', 'Ruka and Rumi Kobayakawa are twin sisters in love with the same man, athletic upperclassman Katsuyuki Touma. Rumi seems supportive of Ruka''s fledgling romance with Katsuyuki, until the twins are infected with a strange bacterium that transforms Rumi''s personality and gifts the twins with terrifying psychic powers. Now Rumi will stop at nothing - or no one,  that gets between her and Katsuyuki, including her own twin sister...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shokupan Mimi Specials', 'Special', 4, 'Completed', '2011-10-07', NULL, '5', 'Episodes 13 through 16 of Shokupan Mimi included in the DVD release.', 457, 'https://cdn.myanimelist.net/images/anime/7/78817.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiong Chumo: Conglin Zong Dong Yuan', 'TV', 104, 'Completed', '2013-07-13', '2014-09-25', '5', 'Third season of Boonie Bears.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shounen Sunday CM: Tokiwa Kitareri!!', 'Special', 1, 'Completed', '2016-01-12', NULL, '5', 'A Tokiwa Kitareri!! commercial produced by J.C. Staff that serves as a promotion for the manga.', 436, 'https://cdn.myanimelist.net/images/anime/13/79284.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ice Movie', 'Movie', 1, 'Completed', '2008-11-29', NULL, '5', 'The year is 2012. Due to an environmental contaminant, the human population has been decimated, including all males, leaving only women behind. Facing extinction, some have decided to accept their doom and live to seek pleasure; others are still trying to use science to fight off that fate. In central Tokyo, one of the last inhabited areas in the world, these two groups face off in a struggle over a hidden sample of "ICE," a substance that could save humanity.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maze', 'Movie', 1, 'Completed', '2012-01-01', NULL, '5', 'Abstract stop motion animation by Tochka.', 1029, 'https://cdn.myanimelist.net/images/anime/9/69165.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('47 Todoufuken', 'TV', 26, 'Completed', '2011-04-07', '2011-09-29', '5', '"47 Prefecture Dogs" is a short flash animation from a voice over variety TV program in Japan called "SAY! YOU! SAY! ME!" The animation takes Japan''s 47 prefectures—or more specifically, the local delicacies or famous landmarks from each of the regions—and gives them a canine makeover. For example, the "Fukuoka-ken" (Fukuoka dog),—Fukuoka of course being home to asianbeat HQ—uses the delicacy "mentaiko" (spicy pollack roe) as the motif for its canine characterization.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Suiren no Hito', 'Movie', 1, 'Completed', '2000-01-01', NULL, '5', 'An elderly man walks along his house and sees a turtle munching on a turnip. He does not disturb the creature but lets it eat in peace. Later that night, he has a dream of his late wife...', 1040, 'https://cdn.myanimelist.net/images/anime/1266/113004.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bishoujo Mobage: Mobami-chan', 'Special', 1, 'Completed', '2014-08-14', NULL, '5', 'DeNA promotional anime video for its line of mobile game. The mascot character for the line of games is called Mobami (a combination of "mobile" and "beauty.")
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Abciee Shuugyou Nikki', 'TV', 12, 'Completed', '2021-01-07', '2021-03-25', '5', 'ABCiee is a bit klutzy and ditsy, but he''s full of spunk and he starts his dream job at a TV station! This is a work comedy filled with all kinds of hijinks! "I never knew it was so hard working at a TV station, ciee!" Despite having to face the unknown rules of the TV business, unique coworkers, and guest stars who have very particular quirks, ABCiee takes them head on with his positivity. Work, love, family, whatever goes!! Please watch over ABCiee as he takes on the TV business.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The Impression of First Gundam', 'Special', 1, 'Completed', '1998-08-01', NULL, '5', 'Screened together with Gundam: Mission to the Rise at Gundam''s 20th Anniversary event "Gundam Big Bang Sengen" in Pacifico Yokohama National Convention Hall.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doctor Chichibuyama', 'TV', 2, 'Completed', '1988-04-03', '1988-07-31', '5', 'Based on the manga by Tanaka Keiichi.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Huo Feng Liao Yuan San', 'ONA', NULL, 'Upcoming', '2027-01-01', NULL, '5', 'In 193 AD, Guo Jia presented the dark military strategy of "slaughtering one city to subdue ten," leading Cao Cao to attack Xuzhou under the pretext of "avenging his father." Historical records state that "hundreds of thousands of men and women were killed." Liaoyuan Huo, posing as Zhao Yun, aided the people of Xuzhou in their desperate defense, outwitting and outmaneuvering Cao Cao''s army, while secretly recruiting Liu Bei to join the fight against Cao Cao. Lu Bu, lying in wait in Chenliu, launched a surprise attack on Cao Cao''s rear, following the advice of his strategist Chen Gong. Zhuge Liang and Sima Yi also arrived in Xuzhou, stirring up the war. The Battle of Xuzhou saw Lu Bu, Xu Chu, Dian Wei, Zhao Yun, and other powerful figures engage in a fierce battle that shook the world. After this battle, the tables have turned in Xuzhou. Cao Cao then turns his attention to his powerful northern enemy, and a top-level strategic game that would determine the fate of the world begins.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Di Yi Xulie 2', 'ONA', 26, 'Upcoming', '2026-01-01', NULL, '5', 'Nuclear winter has arrived, civilization has collapsed, and humanity is no longer the master of the world. Species mutations and scarce resources create an unpredictable future and environment, leading to a series of crises. To protect themselves, humanity has built walls, but outside these walls, survival depends on blood and fire. The protagonist, Ren Xiaosu, and his younger brother, Yan Liuyuan, are among them. They were just ordinary teenagers in the wilderness, without shelter or a way out; their only support was each other. But fate granted them the power to awaken in their dire circumstances. The Jingshan earthquake caused the collapse of Wall 113, fully shattering the post-apocalyptic chaos. During their escape, Ren Xiaosu and his family rescued Luo Lan, the military leader, and entered Wall 109. A new life was about to begin, but the real test had only just begun…
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wareware wa Uchuujin', 'Movie', 1, 'Upcoming', '2026-01-01', NULL, '5', 'One summer in the third grade, a quiet boy named Tsubasa meets Kyotaro, a boy everyone in the class looked up to, and the two become close friends. Within their small world, they share irreplaceable moments—until a small incident suddenly tears them apart. Spanning more than thirty years, this gentle, contemplative story invites the audience to reflect on the meaning of life through the paths their lives take.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blue Gale Xabungle Side R', 'Special', 1, 'Completed', '2025-11-12', NULL, '5', '', 974, 'https://cdn.myanimelist.net/images/anime/1291/153642.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mata Korosarete Shimatta no desu ne, Tantei-sama', 'TV', NULL, 'Upcoming', '2026-04-01', NULL, '5', 'Sakuya Otsuki is the son of a legendary detective, working to follow in his father''s footsteps with his assistant, Lilithea. However, something''s different about this high-school sleuth. Wherever he goes, he always manages to get himself entangled in his cases—as a murder victim! When Sakuya is tasked to infiltrate a luxury cruise ship, he finds himself killed once again. But every time he reopens his eyes, Lilithea is there by his side, ready to help him get to the bottom of the mystery...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Leichte Chousaroku', 'ONA', 1, 'Completed', '2022-10-01', NULL, '5', '', 1186, 'https://cdn.myanimelist.net/images/anime/1722/153600.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wan Sheng Jie', 'ONA', 12, 'Completed', '2020-04-01', '2020-05-27', '8', 'In this world, angels, demons, and other supernatural beings peacefully coexist with humans. Neil Bowman is a demon who is unlike most; he is mesmerized with human culture, and no matter how hard he tries, he can''t do anything evil. Thus, he runs away from Hell and up to Earth.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Akagami no Shirayuki-hime 2nd Season', 'TV', 12, 'Completed', '2016-01-12', '2016-03-29', '8', 'Shirayuki and Zen Wistalia have finally confirmed their romantic feelings for each other, and everyone has resumed their daily lives. Shirayuki remains an apprentice court herbalist at the royal palace of Clarines, and Zen continues his duties alongside his aides.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wolf''s Rain OVA', 'OVA', 4, 'Completed', '2004-01-23', '2004-02-25', '8', 'As the world accelerates toward its own destruction, Kiba and Cheza—with the help of Tsume, Hige, Toboe, and Blue—race to reach true paradise before the entire world is rendered uninhabitable. Now reunited, Cher and Hubb decide to accompany the wolves in hopes of seeing the journey through to its end, while a distraught and confused Quent wanders aimlessly into the wasteland with his mind fixated on revenge.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('xxxHOLiC', 'TV', 24, 'Completed', '2006-04-07', '2006-09-29', '8', 'Kimihiro Watanuki can see spirits and other assorted supernatural creatures, which is quite a bothersome ability he strongly dislikes. On the way home one day, while plagued by some spirits, he is inexplicably compelled to enter a strange house. There, he encounters Yuuko, a mysterious woman who claims to be able to rid him of the ability to see and attract the troublesome creatures—for a price. She demands that he work at her "store" that grants wishes to people, and thus begins Watanuki''s adventures through weird and wonderful events.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('School Rumble Ni Gakki', 'TV', 26, 'Completed', '2006-04-03', '2006-09-25', '8', 'We still have no idea what''s really going on with this show, beyond the fact that the weirdness is piling up!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Vampire Hunter D (2000)', 'Movie', 1, 'Completed', '2000-08-25', NULL, '8', 'When the soothing comfort of sunlight starts to fade, beings of seraphic beauty become the undisputed masters of the night, instilling fear in every living creature. Water turns into ice before these blood-sucking monsters, and their victims realize that this uncanny chill is the harbinger of their inevitable demise. Fortunately, the number of vampires is dwindling thanks to the dauntless bounty hunters who track down and slay the near-immortal predators.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koukaku Kidoutai: Stand Alone Complex 2nd GIG - Individual Eleven', 'OVA', 1, 'Completed', '2006-01-27', NULL, '8', 'Compilation movie of the "Individual Eleven" story from Ghost in the Shell: SAC 2nd Gig series.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shokugeki no Souma: San no Sara', 'TV', 12, 'Completed', '2017-10-04', '2017-12-20', '8', 'The Moon Festival is Tootsuki Academy''s annual gourmet gala, where students compete against each other to earn the most profit through selling their cuisine of choice. But for Souma Yukihira, it is also his first opportunity to challenge the Elite Ten, the supreme council that rules over the academy.  
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('My Melody & Kuromi', 'ONA', 12, 'Completed', '2025-07-24', NULL, '8', 'Get ready for a delightful adventure as My Melody &amp; Kuromi brings the beloved Sanrio characters to life in a charming stop-motion animation series. Celebrating the 50th anniversary of My Melody and the 20th anniversary of Kuromi, the series takes viewers on an adventure in Mariland, their whimsical home.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Code Geass: Hangyaku no Lelouch III - Oudou', 'Movie', 1, 'Completed', '2018-05-26', NULL, '8', 'Lelouch Lamperouge''s dreams of destroying the Holy Britannian Empire are slowly crumbling. His sister, Nunnally, has been kidnapped by Schneizel el Britannia, and Suzaku Kururugi is ignoring his desperate pleas for assistance. The Black Knights are slowly losing faith in Lelouch as their leader, and the United Federation of Nations has declared global war on Britannia.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shingeki no Kyojin Season 2 Movie: Kakusei no Houkou', 'Movie', 1, 'Completed', '2018-01-13', NULL, '8', 'Eren Yeager and others of the 104th Training Corps have just begun to become full members of the Survey Corps. As they ready themselves to face the Titans once again, their preparations are interrupted by the invasion of Wall Rose—but all is not as it seems as more mysteries are unraveled. As the Survey Corps races to save the wall, they uncover more about the invading Titans and the dark secrets of their own members.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuuki Yuuna wa Yuusha de Aru: Washio Sumi no Shou 3 - Yakusoku', 'Movie', 1, 'Completed', '2017-07-08', NULL, '8', 'The third and final movie in the Washio Sumi no Shou trilogy.', 896, 'https://cdn.myanimelist.net/images/anime/7/86984.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Durarara!!x2 Ten', 'TV', 12, 'Completed', '2015-07-04', '2015-09-26', '8', 'In Ikebukuro, the lives of its citizens continue intertwining with each other as if their fates are predestined. Mikado Ryuugamine is now one step closer to his goal of living an exciting life, and in turn, delves deeper into the darker side of Ikebukuro. After gaining absolute control over a former rival, he uses his newfound power as he pleases, purging the Dollars from the inside to mold it into the ideal organization. This proves to be as challenging as it sounds as Mikado must now deal with unwanted outside interference, most notably a re-emerging and dearly missed friend. Meanwhile, Izaya Orihara still has some schemes up his sleeve, although a rival information exchange center has proven to be quite the hindrance, lurking within everyone''s favorite downtown district. Undoubtedly, sooner or later, chaos will strike again.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('ReLIFE', 'TV', 13, 'Completed', '2016-07-02', '2016-09-24', '8', 'Dismissed as a hopeless loser by those around him, 27-year-old Arata Kaizaki bounces around from one job to another after quitting his first company. His unremarkable existence takes a sharp turn when he meets Ryou Yoake, a member of the ReLife Research Institute, who offers Arata the opportunity to change his life for the better with the help of a mysterious pill. Taking it without a second thought, Arata awakens the next day to find that his appearance has reverted to that of a 17-year-old.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gake no Ue no Ponyo', 'Movie', 1, 'Completed', '2008-07-19', NULL, '8', 'A goldfish sneaks away from home and floats off on the back of a jellyfish. After getting stuck in a glass jar, she drifts to the shore where she is freed by Sousuke, a five-year-old boy who lives with his mother Lisa in a house by the sea while his father Koichi works on a fishing boat. After healing a cut on Sousuke''s finger by licking it, the goldfish is named Ponyo by her new friend.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kakushigoto', 'TV', 12, 'Completed', '2020-04-02', '2020-06-18', '8', 'Kakushi Gotou is a somewhat popular manga artist whose works are known for inappropriate content. Because of this raunchiness, when his daughter Hime was born, he vowed to keep his profession hidden from her, believing that she will be disillusioned if she finds out. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Youjo Senki', 'TV', 12, 'Completed', '2017-01-06', '2017-03-31', '8', 'Tanya Degurechaff is a young soldier infamous for predatorial-like ruthlessness and an uncanny, tactical aptitude, earning her the nickname of the "Devil of the Rhine." Underneath her innocuous appearance, however, lies the soul of a man who challenged Being X, the self-proclaimed God, to a battle of wits—which resulted in him being reincarnated as a little girl into a world of magical warfare. Hellbent on defiance, Tanya resolves to ascend the ranks of her country''s military as it slowly plunges into world war, with only Being X proving to be the strongest obstacle in recreating the peaceful life she once knew. But her perceptive actions and combat initiative have an unintended side effect: propelling the mighty Empire into becoming one of the most powerful nations in mankind''s history.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('IDOLiSH7 Vibrato', 'ONA', 8, 'Completed', '2018-02-17', '2019-03-07', '8', 'On a cold night, idol group TRIGGER reunite at a bar to celebrate the anniversary of the day they started working together. Two years prior, Ryuunosuke Tsunashi leaves his Okinawan home and heads to Tokyo, hoping to become an idol and pay off his father''s debt. While waiting for the manager, he is instead picked up by Gaku Yaotome—son of Yaotome Productions'' CEO and Ryuunosuke''s future co-worker—and they go to meet the mysterious Ten Kujou, the last member of the group.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koukaku Kidoutai 2.0', 'Movie', 1, 'Completed', '2008-07-12', NULL, '8', 'Set in the year 2029 and following World Wars III and IV, a Japanese-led Asian block dominates world affairs. The alliance maintains its international supremacy through its elite security force whose cybernetically enhanced operatives tackle an array of hi-tech terrorists and other threats to international security. These augmented agents can "ghost hack" (i.e., download their consciousness) via the now omnipresent internet into other machines and human/machine cross breeds.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hokuto no Ken', 'TV', 109, 'Completed', '1984-10-11', '1987-03-05', '8', 'In the year 19XX, after being betrayed and left for dead, bravehearted warrior Kenshirou wanders a post-apocalyptic wasteland on a quest to track down his rival, Shin, who has kidnapped his beloved fiancée Yuria. During his journey, Kenshirou makes use of his deadly fighting form, Hokuto Shinken, to defend the helpless from bloodthirsty ravagers. It isn''t long before his exploits begin to attract the attention of greater enemies, like warlords and rival martial artists, and Kenshirou finds himself involved with more than he originally bargained for.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kurenai no Buta', 'Movie', 1, 'Completed', '1992-07-18', NULL, '8', 'After a curse turned him into a pig, World War I ace Marco Pagot becomes Porco Rosso, a mysterious bounty hunter who takes down sky pirates in the Adriatic Sea. He whiles away his days on a secluded island, rarely leaving other than to collect bounties or to visit the beautiful Gina, a songstress and owner of the Hotel Adriano.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rurouni Kenshin: Meiji Kenkaku Romantan - Seisou-hen', 'OVA', 2, 'Completed', '2001-12-19', '2002-03-20', '8', 'Kaoru goes to the harbor every day to see if Kenshin has returned. After a while, she starts looking back at her life with Kenshin and all the things that have happened.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fanren Xiu Xian Chuan 2nd Season', 'ONA', 51, 'Completed', '2021-11-14', '2022-10-15', '8', 'Second season of Fanren Xiu Xian Chuan.', 647, 'https://cdn.myanimelist.net/images/anime/1875/120145.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Natsu e no Tunnel, Sayonara no Deguchi', 'Movie', 1, 'Completed', '2022-09-09', NULL, '8', 'Kaoru Touno''s family is falling apart. After the death of a sibling and his parents'' divorce, he no longer feels any peace at home. Following a heated confrontation with his father, Kaoru runs out of his house and finds himself before a mysterious tunnel, which pulls him in. Bewildered by what he sees inside, he rushes to the exit, picking up a bird that looks identical to his deceased pet on his way out.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Da Wang Rao Ming', 'ONA', 12, 'Completed', '2021-12-03', '2022-02-11', '8', 'Lü Shu is a frail teenager with an iron will. After losing his parents, he enrolls in a prestigious high school while working for a living and looking after his adoptive sister, Lü Xiaoyu. However, Lü Shu''s quiet life abruptly changes when a car accident awakens his latent cultivation superpowers. Now cured of his physical weakness, he decides to hide his newfound abilities, as the art of cultivation is still shrouded in mystery—and the fate of cultivators uncertain.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsubasa Chronicle', 'TV', 26, 'Completed', '2005-04-09', '2005-10-15', '8', 'Sakura and Syaoran live peaceful lives in the desert country of Clow. Despite the King''s disapproval of the budding romance between the princess and her archeologist friend, their days remain blissful if not a little dull. But that soon changes when Sakura appears in front of Syaoran in a trance with wings on her back. When the wings dissolve into feathers and Sakura loses consciousness, Syaoran is spurred to action.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toriko', 'TV', 147, 'Completed', '2011-04-03', '2014-03-30', '8', 'Hamburgers that grow out of the ground like four-leaf clovers, mountain ranges carved out of ice cream, and warm servings of mac and cheese that stew deep within the stomachs of volcanoes fill the landscape. This world of delectable natural wonders has reached a prime age of exploration—the Gourmet Age! Citizens and chefs alike aspire to taste and prepare the finest dishes, while adventurers called "Gourmet Hunters" seek out delicious rare ingredients.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('To LOVE-Ru Darkness OVA', 'OVA', 6, 'Completed', '2012-08-17', '2015-04-03', '8', 'Bundled with the 5th, 6th, 8th, 9th, 12th and 13th limited-edition volumes of the manga.', 1117, 'https://cdn.myanimelist.net/images/anime/9/41251.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Precure All Stars Movie DX3: Mirai ni Todoke! Sekai wo Tsunagu☆Nijiiro no Hana', 'Movie', 1, 'Completed', '2011-03-19', NULL, '8', 'Precure 10th Anniversary Movie and 3rd Precure All Stars DX. Enemies are from all the Precure works.', 1030, 'https://cdn.myanimelist.net/images/anime/1539/94597.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Flying Witch', 'TV', 12, 'Completed', '2016-04-10', '2016-06-26', '8', 'In the witches'' tradition, when a practitioner turns 15, they must become independent and leave their home to study witchcraft. Makoto Kowata is one such apprentice witch who leaves her parents'' home in Yokohama in pursuit of knowledge and training. Along with her companion Chito, a black cat familiar, they embark on a journey to Aomori, a region favored by witches due to its abundance of nature and affinity with magic. They begin their new life by living with Makoto''s second cousins, Kei Kuramoto and his little sister Chinatsu.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wakaokami wa Shougakusei! Movie', 'Movie', 1, 'Completed', '2018-09-21', NULL, '8', 'After reluctantly being dragged to a festival at her parents'' rural hometown, Oriko "Okko" Seki must face her sudden harsh reality: the death of both of her parents in a car accident shortly after they arrive. Now, Okko must live at her grandmother''s traditional hot springs inn, which she is surprised to find is occupied by the ghost of a barefoot child. He encourages Okko to follow in her grandmother''s footsteps and prepare to inherit the inn.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Donten ni Warau Gaiden: Shukumei, Soutou no Fuuma', 'Movie', 1, 'Completed', '2018-06-09', NULL, '8', 'Fuuma ninja clan is a secret ninja tribe that is waiting for the "Orochi" (gigantic snake) to resurrect for generations. Shirasu and his twin brother Ichiu grew up in this viscous environment and this tells how they become the leaders of the clan.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shakugan no Shana III (Final)', 'TV', 24, 'Completed', '2011-10-08', '2012-03-24', '8', 'Yuji disappeared the fateful night he was supposed to choose between a life combating evil by Shana''s side or as a normal teenager. He returns from near-death to lead the Crimson Denizens in a dubious plot to bring peace to the universe, but Shana isn''t fooled. In an explosive reunion, the fiery warrior faces her unlikeliest of foes while Flame Hazes from across the world join forces to ignite a war that will determine the fate of all supernatural kind.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Huyao Xiao Hongniang 2: Wangquan Pian', 'ONA', 14, 'Completed', '2016-01-08', '2016-04-15', '8', 'Second season of Huyao Xiao Hongniang.', 369, 'https://cdn.myanimelist.net/images/anime/1153/153688.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hibike! Euphonium: Kakedasu Monaka', 'Special', 1, 'Completed', '2015-12-16', NULL, '8', 'After the Kitauji High School concert band''s auditions for club member participation in the Kyoto Prefectural Concert Band competition, 10 members fail to pass the strict evaluation. Despite being unable to play with the rest of the wind ensemble, the group—who decide to name themselves Team Monaka—is determined to support their peers in any way possible until the day of the competition.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zombieland Saga', 'TV', 12, 'Completed', '2018-10-04', '2018-12-20', '8', 'Sakura Minamoto dreams of becoming an idol. Unfortunately, reality hits her like a truck, and she dies in a sudden traffic accident. Ten years later, she wakes up in Saga Prefecture, only to find herself a zombie with no memory of her past. While still coming to terms with her demise, she meets a man named Koutarou Tatsumi, who explains that he has resurrected her and six other zombie girls from different eras for the purpose of economically revitalizing Saga by means of an idol group. Assuming the role of an abrasive manager, Koutarou begins scheduling events; the girls go along with it, eventually deciding to name their idol group Franchouchou.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Special A', 'TV', 24, 'Completed', '2008-04-07', '2008-09-15', '8', 'Hikari Hanazono has always been able to do things that normal people cannot. As a child, she assumed no one could beat her—until she met Kei Takishima. Thinking she would win, Hikari challenged him to a match. But things didn’t go as planned; she lost not once but each time she rechallenged him. From that point on, she has sworn to best Kei at everything, ranging from academics to athletics.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('To LOVE-Ru Darkness 2nd OVA', 'OVA', 3, 'Completed', '2016-01-04', '2016-12-02', '8', 'A scan of Jump SQ''s September issue, to be released on August 4, revealed that the fifteenth volume of To LOVE-Ru Darkness will bundle a new OVA, which will be released on January 4. Consisting of two episodes, the OVA will run for a total of 25 minutes. One episode, titled Ghost Story Kowai no wa Ikaga (How about something scary?), will adapt a side-story from volume nine. The second episode, titled Clinic Sunao ni Narenakute (Without becoming obedient), will adapt chapter 38.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shoubushi Densetsu Tetsuya', 'TV', 20, 'Completed', '2000-10-07', '2001-03-24', '8', 'In the year 1947, the people of Shinjuku are down on their luck. With little money to buy food or necessities, some resort to gambling in order to survive. Traveling Tetsuya chooses to spend his time at Mahjong parlors where he is wiping the floor clean with his adversaries. However, when Tetsuya meets the intensely skilled Boushu-san, he realizes that his skills are still lacking.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Itai no wa Iya nanode Bougyoryoku ni Kyokufuri Shitai to Omoimasu.', 'TV', 12, 'Completed', '2020-01-08', '2020-03-25', '8', 'After an enthusiastic invitation from her friend, Kaede Honjou reluctantly agrees to try New World Online: a very popular VRMMO played by thousands of people across Japan. Naming her in-game character Maple, she sets out on her journey. As a complete novice to such games, she allocates all of her stat points into vitality, desiring to not get hurt. With not a single point in any other stat, Maple has extraordinarily high defense, but she can''t move quickly or hit hard.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ling Long: Incarnation Middle Chapter', 'ONA', 1, 'Completed', '2019-11-17', NULL, '8', '', 1122, 'https://cdn.myanimelist.net/images/anime/1422/109518.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hayate no Gotoku!', 'TV', 52, 'Completed', '2007-04-01', '2008-03-30', '8', 'According to Murphy''s Law, "anything that can go wrong, will go wrong," and truer words cannot describe the unfortunate life of the hard-working Hayate Ayasaki. Abandoned by his parents after accumulating a debt of over one hundred fifty million yen, he is sold off to the yakuza, initiating his swift getaway from a future he does not want. On that fateful night, he runs into Nagi Sanzenin, a young girl whom he decides to try and kidnap to pay for his family''s massive debt.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Heroic Age', 'TV', 26, 'Completed', '2007-04-02', '2007-10-01', '8', 'When the Golden Race invited other races to join them in the stars, three sentient races answered their call. The Goldens called them the Bronze, Silver and Heroic Tribes. Just before the Gold Tribe left to travel to another Universe, a fourth race appeared, traveling to the stars on their own accomplishments. The Golds named the human race the Iron Tribe. During the passing of time, humanity suffers at the hands of the more dominant races and is now facing extinction. Following a prophecy left by the Gold Tribe, Princess Deianeira sets out to search for the powerful being who might be able to save humankind. She meets a wild haired boy on an abandoned planet—a fateful encounter that will not only change the fortunes of Humanity, but also the fate of the universe.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Baka to Test to Shoukanjuu', 'TV', 13, 'Completed', '2010-01-07', '2010-04-01', '8', 'Fumizuki Academy is not a typical Japanese high school. This unique institution has implemented a new and innovative system to sort its students. At the end of their freshman year, students take a test that divides up the student body. The highest scorers are placed into A class, all the way down until F class, for the lowest of the low.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ling Long: Incarnation Final Chapter', 'ONA', 2, 'Completed', '2021-05-01', '2021-05-05', '8', 'Final installment of Ling Long: Incarnation.', 1122, 'https://cdn.myanimelist.net/images/anime/1916/114704.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan Magic File 2: Kudou Shinichi Nazo no Kabe to Kuro Lab Jiken', 'OVA', 1, 'Completed', '2008-04-19', NULL, '8', 'Magic File 2 was sold at select retailers (7-11 branded equivalents) in Japan, along with PPV episodes of the show (episodes released long before, such as the NY case). The first disc housed the Movie 12 Side-Story OVA, which features Kudou Shinichi and details a bit of the backstory from the upcoming movie. The second disc was the one with the PPV episodes.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bleach Movie 3: Fade to Black - Kimi no Na wo Yobu', 'Movie', 1, 'Completed', '2008-12-13', NULL, '8', 'After a mysterious pair attack Rukia Kuchiki and erase her memories while she is in Seireitei, Ichigo Kurosaki, a substitute Soul Reaper, briefly forgets Rukia, until he is reminded of her by Kon, an Underpod Mod-Soul. Confused, he seeks his town''s candy-shop owner, Kisuke Urahara, who opens the pathway to Seireitei for them. Ichigo is then shocked to find that his allies in Seireitei, the Shinigami of the Soul Society, have forgotten him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doraemon Movie 34: Shin Nobita no Daimakyou - Peko to 5-nin no Tankentai', 'Movie', 1, 'Completed', '2014-03-08', NULL, '8', 'This is a remake of the 1982 film, Doraemon: Nobita''s Great Demon, which was written by original Doraemon co-creator Fujiko F. Fujio.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fushigi no Umi no Nadia', 'TV', 39, 'Completed', '1990-04-13', '1991-04-12', '8', 'In 1889, the world is on the pinnacle of great discoveries in technology. In mankind''s grasp for the future, a sinister foe known only as Gargoyle, obsessed with restoring the former Atlantean empire to the glory it once held, begins his plans to take over the world. Nadia, with the help of a young inventor, Jean Roque Lartigue, and Captain Nemo of the submarine Nautilus, must fight to save the world from Gargoyle and Neo-Atlantis. Based on the Novel ''20,000 Leagues Under the Sea'' by Jules Verne.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Otome wa Boku ni Koishiteru', 'TV', 12, 'Completed', '2006-10-08', '2006-12-24', '7', 'Mizuho can''t believe his ears when Grandpa''s will is read out. Grandpa''s final wish is for Mizuho to attend the same academy as Mizuho''s mother. The catch is it''s an all-girls school. With the help of friend Mariya however, he gets a makeover good enough to fool everyone at the academy. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gantz 2nd Stage', 'TV', 13, 'Completed', '2004-08-26', '2004-11-18', '7', 'Despite having seemingly returned to their normal lives, Kei Kurono, Masaru Katou, and Kei Kishimoto are forced back into the lethal game after Gantz''s recent activity. The black sphere continues to summon recently deceased people to fight alien invaders. And having survived the two previous encounters, the trio are more than prepared for the upcoming missions.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Medaka Box', 'TV', 12, 'Completed', '2012-04-05', '2012-06-21', '7', 'Medaka Kurokami is, in the truest sense of the word, perfect. Beautiful, intelligent, and athletic, Medaka''s dream is to make others happy. So when she runs for Student Council President of the prestigious Hakoniwa Academy, winning the election with 98% of the votes is only to be expected. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam: GQuuuuuuX', 'TV', 12, 'Completed', '2025-04-09', '2025-06-25', '7', 'In the year Universal Century 0079, the Earth Federation and Principality of Zeon battled on opposite sides of the deadly One Year War. During one skirmish, infamous Zeon pilot Char Aznable successfully infiltrated an enemy base and stole a prototype mobile suit called the Gundam. With this powerful weapon, Char helped his allies achieve a decisive victory. However, in a freak accident involving the Gundam''s advanced technology, Char vanishes alongside his signature red mobile suit.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yoru wa Neko to Issho Season 3', 'ONA', 40, 'Completed', '2024-12-04', '2025-09-03', '7', 'Third season of Yoru wa Neko to Issho.', 945, 'https://cdn.myanimelist.net/images/anime/1241/144618.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kanojo mo Kanojo Season 2', 'TV', 12, 'Completed', '2023-10-07', '2023-12-23', '7', 'Naoya Mukai''s crazy lifestyle of balancing his time between both of his girlfriends, Saki Saki and Nagisa Minase, is still as hectic as ever. Additionally, the blonde bombshell Rika Hoshizaki also has her sights on Naoya, complicating his already convoluted love life.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaiko sareta Ankoku Heishi (30-dai) no Slow na Second Life', 'TV', 12, 'Completed', '2023-01-07', '2023-03-25', '7', 'For more than 30 years, Dariel has been a loyal soldier in the Demon King''s army, having been raised by Granbarza, one of the Four Heavenly Generals. However, as Dariel lacks any magical potential, he is nothing but a disgrace in the eyes of Granbarza''s son, Bashbarza, who fires Dariel right after assuming his father''s position as a general.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ro-Kyu-Bu! SS', 'TV', 12, 'Completed', '2013-07-05', '2013-09-27', '7', 'After their loss against Suzuridani Academy, the members of the Keishin Academy girls'' basketball team—Tomoka Minato, Maho Misawa, Airi Kashii, Hinata Hakamada, and Saki Nagatsuka, along with their coach, Subaru Hasegawa—exert more of their time and effort in improving in the sport day by day. However, this time around, new rivals with strengths possibly exceedings theirs and friends appear on their way to the top.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Magic-Kyun! Renaissance', 'TV', 13, 'Completed', '2016-10-02', '2016-12-25', '7', 'A world where art becomes magic. In this world, people who can inspire passion with their Magic Arts are called Artistas, and are employed in show business. In Hoshinomori Private Magical Arts High School, where Artistas are taught, a strange new student named Kohana Aigasaki transfers into the school.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyoukaisenjou no Horizon', 'TV', 13, 'Completed', '2011-10-02', '2011-12-25', '7', 'In the far future, humans abandon a devastated Earth and traveled to outer space. However, due to unknown phenomenon that prevents them from traveling into space, humanity returns to Earth only to find it inhospitable except for Japan.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Inazuma Eleven: Chou Jigen Dream Match', 'Movie', 1, 'Completed', '2014-06-13', NULL, '7', 'A new movie featuring a match between fan-voted members of the Inazuma Best Eleven team and the special Battle Eleven team.', 621, 'https://cdn.myanimelist.net/images/anime/3/62875.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Full Metal Panic! Movie 2: One Night Stand', 'Movie', 1, 'Completed', '2018-01-13', NULL, '7', 'Shikidouji, the illustrator of Shoji Gatoh''s Full Metal Panic! light novel series, revealed that production has been green-lit on a "director''s cut" version of the first Full Metal Panic!! television anime series from 2002. The director''s cut will consist of three films. The announcement does not state if the film trilogy will add new footage. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ajin Part 2 OVA', 'OVA', 1, 'Completed', '2017-04-07', NULL, '7', 'Bundled with the limited edition tenth manga volume. It focuses on the backstory of when Satou captured the first ever Ajin in Africa and discovered that he himself is an Ajin.', 695, 'https://cdn.myanimelist.net/images/anime/1575/132721.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuuki Yuuna wa Yuusha de Aru: Hidamari', 'Special', 1, 'Completed', '2017-11-18', NULL, '7', 'A recap episode of the original series made to connect Yuuki Yuuna wa Yuusha de Aru: Washio Sumi no Shou to the sequel series Yuuki Yuuna wa Yuusha de Aru: Yuusha no Shou.', 896, 'https://cdn.myanimelist.net/images/anime/7/89061.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mushibugyou OVA', 'OVA', 3, 'Completed', '2014-07-18', '2015-01-16', '7', 'OVAs bundled with the 15-17th volumes of the Mushibugyou manga.', 787, 'https://cdn.myanimelist.net/images/anime/7/67127.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Manga Sekai Mukashibanashi', 'TV', 127, 'Completed', '1976-10-07', '1979-03-28', '7', 'Each episode of this series tells the story of a famous fairy tale from all around the world. Some of them are adapted from famous books such as "The Iliad".
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Precure Dream Stars! Movie', 'Movie', 1, 'Completed', '2017-03-18', NULL, '7', '', 1030, 'https://cdn.myanimelist.net/images/anime/1332/142469.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Binan Koukou Chikyuu Bouei-bu LOVE! LOVE!', 'TV', 12, 'Completed', '2016-07-08', '2016-09-23', '7', 'After pulling the plug on the space reality TV show "Can I Destroy the Earth? 2," the Defense Club and the Conquest Club return to their peaceful high school lives. Time has passed since that fearsome battle, and it''s now autumn. The five Defense Club members have stopped serving as the Battle Lovers, and are enjoying a soak in the Kurotama Bath like always, when the Conquest Club broaches a subject that will change a great deal about events to come...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Strike the Blood', 'TV', 24, 'Completed', '2013-10-04', '2014-03-28', '7', 'Kojou Akatsuki''s days as an ordinary high school student in the Demon District of Itogami Island come to an abrupt end after a fateful encounter leaves him with the remarkable abilities of a vampire.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nekopara: Koneko no Hi no Yakusoku', 'ONA', 1, 'Completed', '2018-07-27', NULL, '7', 'Six months before the opening of the patisserie La Soleil, Chocola and Vanilla are still kittens trying to fit into the Minazuki household. As the two youngest catgirls under Kashou and Shigure''s care, the two learn from and mature alongside four other catgirls⁠—Azuki, Maple, Cinnamon, and Coconut⁠⁠. Soon, they approach their first Christmas together as a family.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mirai Shounen Conan (Movie)', 'Movie', 1, 'Completed', '1979-09-15', NULL, '7', 'Twenty years after a ravaging war drastically transformed the face of the Earth, an old man and his energetic grandson Conan remain the sole survivors of their once larger community. Believing themselves to be the last humans on the planet, the two are surprised to one day discover a girl lying unconscious on the shore of their solitary isle.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Photon', 'OVA', 6, 'Completed', '1997-11-21', '1999-02-18', '7', 'Photon Earth is a young and gentle boy with superhuman strength and "Baka" (meaning "idiot" in Japanese) scribbled on his forehead (apparently by his troublemaking friend Aun Freya). One day, he finds himself engaged to the beautiful fugitive pilot Keyne Acqua after writing "baka" on her forehead. And that''s the least of his worries as he must protect both Aun and Keyne from the evil Papacharino, who seeks to steal the secrets of "Aho" (another word for idiot) energy from Keyne''s grandfather''s ship.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Code Geass: Boukoku no Akito 2 - Hikisakareshi Yokuryuu Picture Drama', 'Special', 1, 'Completed', '2013-12-25', NULL, '7', 'Special included in the Code Geass: Boukoku no Akito 2 BD/DVD release.', 974, 'https://cdn.myanimelist.net/images/anime/4/70539.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Azur Lane: Bisoku Zenshin!', 'TV', 12, 'Completed', '2021-01-12', '2021-03-30', '7', 'In a seemingly peaceful time without looming threats of Sirens or war, shipgirls from different nations live together in harmony. Some girls, such as the destroyers Ayanami, Javelin, Laffey, and Z23, attend school. Others immerse themselves into various other activities, including sports, foraging, training, going to formal parties, or even vying for the commander''s attention! But one thing is for certain: the girls will continue to deepen their friendship in the pleasant port of Azur Lane!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zinba', 'TV', 52, 'Completed', '2013-08-24', '2013-10-13', '7', 'The juvenile Kan from the earth is summoned to the Kingdom of Toria , where he encounters attack from the giant creature Zinba, and he''s rescued by the linker Shibuki and Uranus. Later, he accidentally gets on the linker squad DUX truck to the maze valley, finding in a cave a golden Zinba.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Otome wa Boku ni Koishiteru: Futari no Elder The Animation', 'OVA', 3, 'Completed', '2012-07-30', '2012-10-01', '7', 'Two years after Mizuho''s graduation... Mikado Chihaya was truant at his school because of harassment in the school and of a distrust in men. His mother cannot bear to watch him be in trouble, so she makes him transfer to Seiou Girls'' School, her old school. He dresses as a girl and introduces himself as Kisakinomiya Chihaya. Chihaya meets Nanahara Kaoruko, who once rescued him from a playboy, and he begins to live in the dormitory building. He becomes the focus of public attention due to his attractive face and figure, and due to high grades at studies.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Crayon Shin-chan Movie 07: Bakuhatsu! Onsen Wakuwaku Daikessen', 'Movie', 1, 'Completed', '1999-04-17', NULL, '7', 'The Nohara family and "Onsen G-Men", the secret government agency maintaining all the hot springs in Japan, fight against "Yuzame", a bath-hating terrorist organization plotting to wipe out all the hot springs in Japan.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou Sensei Negima! Movie: Anime Final', 'Movie', 1, 'Completed', '2011-08-27', NULL, '7', 'An animated feature film based on the Negima! Magister Negi Magi manga.', 791, 'https://cdn.myanimelist.net/images/anime/1282/133685.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hanasakeru Seishounen Recaps', 'Special', 3, 'Completed', '2009-06-28', '2009-10-18', '7', 'Recap specials of Hanasakeru Seishounen.', 939, 'https://cdn.myanimelist.net/images/anime/13/15465.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koukou Butouden Crows', 'OVA', 2, 'Completed', '1994-01-28', '1994-06-24', '7', 'Bouya Harumichi is a new transfer student to Suzuran all-boys high school, a place where only the worst delinquents assemble. Due to its large amount of delinquents who are hated by the general people for their inauspiciousness, similarly to crows, it is also known as "Crows High School."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Macross 7 Plus', 'Special', 11, 'Completed', '1995-01-21', '1996-01-25', '7', 'A series of 2-3 minute shorts revealing the everyday life of some characters, back-story of others, and the occasional music video. Originally included as extras on the Macross 7 VHS and laserdisc releases.', 92, 'https://cdn.myanimelist.net/images/anime/6/13816.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gegege no Kitarou (1968)', 'TV', 65, 'Completed', '1968-01-03', '1969-03-30', '7', 'Kitarou, a ghost, spends his afterlife helping humans in need of his skills. He thwarts the plans of evil spirits who live to torment humanity.', 1030, 'https://cdn.myanimelist.net/images/anime/13/27398.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragonaut: The Resonance - Kotou - Tozasareta Kyousou', 'Special', 1, 'Completed', '2008-09-24', NULL, '7', 'An unaired 26th episode that will be in the final DVD.', 341, 'https://cdn.myanimelist.net/images/anime/9/31303.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Silent Möbius', 'TV', 26, 'Completed', '1998-04-07', '1998-09-29', '7', 'The year is 2023 and Alien Beings known as "Lucifer Hawks" have begun invading earth from another dimension. All that stands between them and the enslavement of the human race is the Attacked Mystification Police Department - a special division of the Tokyo Police staffed by women with amazing paranormal abilities.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Innocent Venus', 'TV', 12, 'Completed', '2006-07-27', '2006-10-26', '7', 'In the year 2010 AD, Hyper Hurricanes born concurrently all over the world caused severe damage. Five billion people lost their lives, decreasing the world''s population to 3 billion. Existing economies and military were wiped out. Countries were frozen under solid ice, plains sank beneath seas, the world was changed dramatically.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nagagutsu wo Haita Neko: 80-nichikan Sekai Isshuu', 'Movie', 1, 'Completed', '1976-03-20', NULL, '7', 'Brave cat Pero once had a bet with treacherous multimillionarie Grumon that he can travel around the world in 80 days. The stake is high, in case of success Grumon will give all of his fortune to Pero, but in case of failure Pero becomes slave of Grumon for the rest of his life. Pero departs together with his faithful friends behemoth Kato and brave Small Mouse. Grumon tries everything to prevent their arrival to the finish. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon Movie 06: Nanayo no Negaiboshi Jirachi', 'Movie', 1, 'Completed', '2003-07-19', NULL, '7', 'The Millennium Comet is about to make its long-awaited appearance in the sky again, supposedly granting the wishes of all those who see it in the skies above them. Of course, Satoshi and friends are equally interested in the Millennium Festival, especially when they attend a magic performance by the Great Butler. Even more interesting is the mysterious cocoon in Butler’s possession—from which Masato hears a mysterious voice calling! When Jirachi emerges from its slumber, Masato has a new friend—sadly, it’s only for the brief few days that the Millennium Comet appears in the sky.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Vandread: Taidou-hen', 'OVA', 1, 'Completed', '2001-01-21', NULL, '7', 'Vandread The First Stage (season one) was immediately followed up by this OVA. This OVA, also known as Vandread Taidouhen Stage (The Movement Stage) was a recap of the first 13 episodes with additional footage. So, Vandread Taidouhen is not really a bridge between Vandread The First Stage and Vandread The Second Stage (season two). It was made to bring new viewers up to date as to what happened during the first season
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maoyuu Maou Yuusha: Kono Monogatari wa, Niku dake de wa Nai no ja!', 'Special', 1, 'Completed', '2013-03-09', NULL, '7', 'A recap of episodes 1-9 of Maoyuu Maou Yuusha.', 85, 'https://cdn.myanimelist.net/images/anime/2/47281.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The Kabocha Wine', 'TV', 95, 'Completed', '1982-07-05', '1984-08-27', '7', 'Transfer student, Aoba Shunsuke, arrived at Sunshine School only to find the premises empty. He was secretly gleeful to be the first to reach the school, oblivious to the fact that it was Foundation Day and a rest day for the institution. At that moment, a big-sized "L"(Eru) beauty by the name of Natsumi appeared before him and the two of them hit off together even though Shunsuke was so much smaller than her. Shunsuke''s mother runs a women''s apparel busines but the shop is in need of manpower. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Ball Z Movie 10: Kiken na Futari! Super Senshi wa Nemurenai', 'Movie', 1, 'Completed', '1994-03-12', NULL, '7', 'After his loss to Goku, Broly crash lands and hibernates on earth. After some time, he is awakened by Trunks and Goten, who Broly believes is Kakarott, and goes on a rampage to kill both of them. At the same time, Gohan is on his way to challenge the Legendary Super Saiyan alone.', 1030, 'https://cdn.myanimelist.net/images/anime/1191/93673.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Delicious Party♡Precure Movie: Yume Miru Oko-sama Lunch!', 'Movie', 1, 'Completed', '2022-09-23', NULL, '7', '', 1030, 'https://cdn.myanimelist.net/images/anime/1548/126145.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Vassalord.', 'OVA', 1, 'Completed', '2013-03-15', NULL, '7', 'Charley, a cyborg vampire who does the Vatican''s dirty work, is the thrall of the local vampire playboy Johnny Rayflo. As the two fight crime—and each other—hilarity, violence and sacrilege ensue! But can Charley resist his own desperate cravings for blood? Find out as the devilish duo go up against a childlike vampire princess, a mysterious branch of the Unitarian Church...and one another. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shokei Shoujo no Virgin Road', 'TV', 12, 'Completed', '2022-04-02', '2022-06-18', '7', 'Average student Mitsuki Mutou suddenly finds himself transported to another realm. Summoned by the king of this world for the remarkable power he is supposed to possess, Mitsuki is thrown out when it appears that he lacks a Special Concept. Moping about, he encounters a priestess named Menou who explains that Japanese people like him are known as Lost Ones, and such individuals never fail to have Special Concepts.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tenshi ni Narumon!', 'TV', 26, 'Completed', '1999-04-07', '1999-09-29', '7', 'Yuusuke was just a normal kid going to high school. Then one day, the cute and behaloed Noelle fell, quite literally, into his life, naked as a baby and every bit as innocent. Before he can even fathom what''s just happened, Yuusuke is inducted into a rather odd family of otherworldly beings. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Naruto: Takigakure no Shitou - Ore ga Eiyuu Dattebayo!', 'Special', 1, 'Completed', '2003-12-20', NULL, '7', 'After safely escorting the cowardly Takigakure leader Shibuki to his homeland, Naruto Uzumaki, Sasuke Uchiha, and Sakura Haruno are taken aback by the village''s sudden invasion of rogue ninjas. As their teacher Kakashi Hatake had departed for Konohagakure beforehand, the team is left to deal with the attacking forces on their own. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tales of Phantasia The Animation', 'OVA', 4, 'Completed', '2004-11-25', '2006-02-24', '7', 'Tragedy strikes the lives of Cless Alvein, a young swordsman, and Chester Barklight, a young archer, as they return to their village of Totus to find it razed to the ground by the mysterious Black Knight. To take over the world, the Black Knight seeks to claim the power of the Demon King, Dhaos—sealed away by the ancestors of Cless and a young cleric named Mint Adnade. Dhaos'' reawakening signals not only the end of the Black Knight, but potentially the world. Cless and Mint must now journey a century into the past to rally allies capable of vanquishing the Demon King once and for all.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sakura Taisen: New York', 'OVA', 6, 'Completed', '2007-04-04', '2007-08-01', '6', 'New York City, the late 1920s. The battle with Nobunaga is over, the city restored to peace...until the owner of Little Lip Theater informs Shinjiro... "This time, the leading lady will be...you." Thus Shinjiro, disguised as the actress Petitmint, is forced into the role of "Cleopatra." The Star Division members set out to persuade a reluctant Shinjiro, beginning a chase across the five boroughs. Meanwhile, a dark-skinned youth and his servant have appeared unexpectedly in the midst of the flourishing city. His eyes, concealing a silent wrath, are fixed upon nothing less than the Statue of Liberty. Now Shinjiro and company must protect this city of hopes and dreams from a new menace while safely raising the curtain on a new show.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('To Heart 2: Dungeon Travelers', 'OVA', 2, 'Completed', '2012-02-22', '2012-07-25', '6', 'According to Amazon Japan, a two-volume OVA series "ToHeart 2 Dungeon Travelers" was announced.  "ToHeart 2 Dungeon Travelers" is an RPG game on PlayStaion Portable released in 2011.', 169, 'https://cdn.myanimelist.net/images/anime/8/74021.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yurumates wa?', 'OVA', 1, 'Completed', '2011-06-24', NULL, '6', 'Yurume Aida has settled into her life at the Maison du Wish, a boarding house full of young students hoping to pass college entrance exams despite rarely progressing in their studies. When Sae Kawano''s younger sister moves into the house as a last-ditch effort to get Sae to buckle down, the residents'' lazy lifestyle is threatened. Now deep within their ranks, Sae''s sister may be the missing piece that can turn this group of misfits around—as long as she can resist the urge to succumb to their slothful ways.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yu☆Gi☆Oh! Sevens', 'TV', 92, 'Completed', '2020-04-04', '2022-03-27', '6', 'In the ever-growing world of Duel Monsters, as duelists improve their skills and rise up the ranks, duels become increasingly complex. By adhering to strict rules, in addition to using and learning proven strategies, one can develop into a strong duelist. However, as a boy who loves inventions and discovering new possibilities, elementary school student Yuuga Oudou finds the current way of dueling predictable and rigid—in other words, boring.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mamono Hunter Youko', 'OVA', 5, 'Completed', '1990-12-01', '1995-07-01', '6', 'Yohko Mono is a regular girl making her way through high school--until she learns that she is the 108th successor to a line of warriors charged with defending the earth against demons. Eventually she must fight her ultimate battle against the demon who started it all. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shikkakumon no Saikyou Kenja', 'TV', 12, 'Completed', '2022-01-08', '2022-03-26', '6', 'At birth, mages randomly acquire one of the four "crests" that represents the extent of their magical capability. Equipped with a crest specializing in creation, a man named Gaius reached the ceiling of his potential, becoming known as the world''s strongest sage. Despite his overwhelming power, he is unsatisfied with his abilities and desires to possess the mark suitable for close combat. Knowing that a person''s crest is unchangeable, Gaius decides to reincarnate far into the future, hoping to alter his fate.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece: Dr. Chopper no Bouken Karte - Shinyuu-tachi no Crossroad', 'Special', 1, 'Completed', '2025-06-22', NULL, '6', 'The seventh recap special of the Egghead arc.', 1030, 'https://cdn.myanimelist.net/images/anime/1991/150670.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaijuu-iro no Shima PV', 'Special', 1, 'Completed', '2021-03-04', NULL, '6', 'Promotional video for the Dragon Age Extra manga Kaijuu-iro no Shima.', 786, 'https://cdn.myanimelist.net/images/anime/1311/127149.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sore Ike! Anpanman: Omusubiman', 'Movie', 1, 'Completed', '1990-07-07', NULL, '6', '', 990, 'https://cdn.myanimelist.net/images/anime/9/52081.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Junk Boy', 'OVA', 1, 'Completed', '1987-12-16', NULL, '6', 'Ryouhei Yamazaki is a young man hoping to score a position working for Poteto Boy, the hottest gentleman''s magazine around. When he becomes visibly aroused during the job interview, though, he thinks all is lost until the beautiful head editor, Yuki Oda, tells him to come back the next morning. As a writer in touch with the magazine''s core demographic, Ryouhei offers his unique perspectives on different photoshoots. Excited as he may be, Ryouhei has much to learn if he wants to succeed both as a journalist and a mature lover.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Donyatsu', 'Movie', 12, 'Completed', '2013-06-01', '2013-12-20', '6', 'The "loosely science-fiction adventure" is set in the summer sometime in the 21st century. Tokyo''s Shinjuku ward has become a wasteland, void of all humans due to an unexplained catastrophe. What remains are these strange creatures such as "Donyatsu," the half-cat, half-doughnut hybrid, and "Begaru," a feline bagel composite.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Duel Masters Movie 1: Yami no Shiro no Maryuuou', 'Movie', 1, 'Completed', '2005-03-12', NULL, '6', '', 903, 'https://cdn.myanimelist.net/images/anime/9/22612.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eikyuu Kazoku', 'Movie', 1, 'Completed', '1997-04-01', NULL, '6', 'Eternal Family is the most popular reality show in the world, where five societal dropouts live together with an actor. From people with eccentric personalities or sordid pasts to abandoned children, these displaced individuals were implanted with false memories to believe the six of them formed a family. While their memories have been overwritten, the characteristics that made them outcasts of society remain, fueling an incredibly chaotic lifestyle. But when an accident leads to the breakdown of the facility detaining them, the family becomes loose on the streets. Now that they have a taste of the outside world, returning to their captivity may be an impossible feat.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lime-iro Senkitan', 'TV', 13, 'Completed', '2003-01-04', '2003-03-29', '6', 'Around the the 37th year of the Meiji Era (1904), in the midst of the Russo-Japanese war, the small Japanese army, in need of assistance, uses its special flying (thanks to a benevolent demon) ship, the Amanohara, to attack Russia''s major base at Port Arthur (Lushun).
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Haitai Nanafa 2nd Season', 'TV', 13, 'Completed', '2013-04-06', '2013-06-29', '6', 'Continuation of the first season.', 673, 'https://cdn.myanimelist.net/images/anime/7/47233.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('ABC Tenkiyohou', 'Special', 1, 'Completed', '2016-01-01', NULL, '6', 'A weather forecast background video that follows a teeny tiny old man as he embarks on a journey, wherever his feet and the wind take him. Using stop-motion photography on location, it is an experimental work that explores the coexistence of the sense of speed of location shooting with the precision of animation shooting.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ishida to Asakura', 'TV', 12, 'Completed', '2013-01-06', '2013-03-24', '6', 'High School isn''t easy, especially for Asakura, who is struggling to graduate. Luckily for him, he has lots of friends who are willing to go the extra mile. Asakura is obsessed with female anatomy, which frustrates his other classmates! One classmate wants them to run a flower shop together, while another one wants to run a bookstore with him! With everyone vying for his complete attention, will Asakura ever graduate!?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Barbapapa Sekai wo Mawaru', 'TV', 50, 'Completed', '1999-07-05', '1999-10-08', '6', '"Barbapapa around the world", is a fun-filled collection of 5-minute animated cartoons for preschool children. Barbapapa and his family return to TV for the first time in 25 years with 50 completely new and original episodes.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mujaki no Rakuen', 'OVA', 3, 'Completed', '2014-08-29', '2016-08-29', '6', 'Shouta Handa is a jobless 25 year old who is sick and tired of his boring life. One evening, at the class reunion, he gets to meet all of the cute girls that used to be his classmates. He soon discovers that they are all successful with interesting careers, and even more importantly—really beautiful now, with bigger curves. Unfortunately, it seems that they are all aware of his boring, unsuccessful life, so they mock him and call him a loser, just like in the old days.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Muv-Luv Alternative', 'TV', 12, 'Completed', '2021-10-07', '2021-12-23', '6', 'The world has been engulfed in a desperate, three-decade-long war against the BETA—an alien species that invaded the planet in 1973. Amid this chaos, a high school student named Takeru Shirogane suddenly wakes up from a terrifying nightmare where he sees mankind in utter defeat. Soon after, he realizes that his dream was nothing more than the recollections of his life in an alternative universe. In those memories, the Alternative V project is implemented, sending hundreds of thousands of people into space as a last resort to preserve humanity, while leaving the remaining billion on Earth to suffer a cruel fate.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Master of Epic: The Animation Age', 'TV', 12, 'Completed', '2007-01-08', '2007-03-26', '6', 'Over millions of years, there have been many ages - war, gods, and future to name a few. Each of these was infinitely less exciting than the current Animation Age! In this RPG-esque existence, becoming stronger is paramount to one''s survival and leveling up is a must. From pacifists to news casting, from fishing woes to love advice, there''s nothing the Animation Age can''t show or teach us about life in a game world! Armed with healing spells, changes of clothes and plenty of summoned familiars, the characters of Master of Epic will do what it takes to level up and live to fight another day!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Vlad Love', 'ONA', 12, 'Completed', '2020-12-18', '2021-03-14', '6', 'Mitsugu Banba is a high school girl who finds meaning in donating blood. She frequently visits a blood bank to donate blood, despite being harshly treated by the nurse. One day, she encounters a beautiful girl who looks like she''s from overseas at the blood bank. The pale girl looks like she''s about to faint any minute, but then, she starts destroying the blood bank. The girl loses consciousness and Mitsugu takes her home... 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('We', 'Special', 1, 'Completed', '2019-08-05', NULL, '6', 'The Hanwha Eagles Campaign was created with the hope to make children from multicultural families can enjoy baseball without prejudice.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chivas 1-2-3', 'OVA', 2, 'Completed', '1999-08-21', '1999-09-21', '6', 'Ruthless sorcerer Chivas Scotch is hired by a count named Cuttlefish to destroy an evil monster attacking a nearby village. But things go awry when Chivas fails to destroy the monster and he''s forced to transfer his spirit in the body of his beautiful servant Gin Fizz. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Transformers Superlink Special', 'Special', 1, 'Completed', '2004-11-03', NULL, '6', 'Episode 43.5, "Distribution", is a comedic special show which commemorates 500 episodes of Transformers in Japan (however, since that total includes assorted Japanese series, the west is still some distance away from this number). When aired in Japan, it did not air in the usual timeslot for Superlink, and is not in any sort of chronological order - It features the Autobots playing a video game training simulator, which they certainly do not have time to do between episodes 42 and 44.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zero Tester: Chikyuu wo Mamore!', 'TV', 27, 'Completed', '1974-07-01', '1974-12-30', '6', 'Second season of Zero Tester, series of space accidents turn out to be the work of the Armanoid aliens, who planned to invade planet Earth. Professor Tachibana alongside other world leader gathers a team around him at the Future Science Invention Center and prepares five state-of-the-art vehicles for Shin, Go, Lisa, and Captain Kenmotsu to counter the impending Armanoid aliens invasion with forming special Zero Tester Squad.', 974, 'https://cdn.myanimelist.net/images/anime/1005/97256.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Avenger', 'TV', 13, 'Completed', '2003-10-02', '2003-12-25', '6', 'Mars has been colonized and is a world where children have been replaced by robot servants known as "dolls." Layla is a skilled fighter with a tragic past who travels about the world. Her companions are Nei, a strange and unique doll with some unknown ties to Layla, and Speedy, who is a doll breeder. The founders of Mars see the trio as a threat to their world, and each time they attack Layla and Nei a bit more of their mysterious past and future is revealed.', 122, 'https://cdn.myanimelist.net/images/anime/13/19921.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shachou, Battle no Jikan desu!', 'TV', 12, 'Completed', '2020-04-05', '2020-06-28', '6', 'Long ago, a goddess descended from Heaven and blessed the desolate land of Gatepia. As a result, gigantic gates appeared, leading to dungeons abundant in "kirakuri," crystals containing the energy needed for the foundation of the world. This led to the formation of various companies of adventurers who would harvest kirakuri from the dungeons.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Petit Forma: Denhan Kyoku Nisshi', 'ONA', 5, 'Completed', '2025-03-28', '2025-06-24', '6', 'The anime is a spin-off that follows the everyday lives of SD versions of Echika and friends.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shadowverse Flame: Arc-hen Recaps', 'Special', 2, 'Completed', '2024-06-22', '2024-08-17', '6', 'Recap episodes of the Shadowverse Flame: Arc-hen.', 1145, 'https://cdn.myanimelist.net/images/anime/1856/143672.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wakusei Daikaiju Negadon', 'Movie', 1, 'Completed', '2005-10-16', NULL, '5', 'A world of the future, madly over populated, searches for a new home on Mars to help support humanity. After terraforming Mars into a habitable landscape a Japanese ship returning from the planet crash-lands on a Tokyo street, unleashing a terrible monster. The only man who can stop Negadon is Dr. Narasaki, and his robot Miroku...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meisou-Ou Border', 'OVA', 1, 'Completed', '1991-09-01', NULL, '5', 'Featuring a modern-day odd couple, the naive virgin Kubota and the handsome charmer Hachisuka, who meet up by accident in a Middle Eastern desert and return to Japan to hustle their way through life. They start by getting involved in shady TV dealings, where they get jobs making fake docmentaries.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yumekuri', 'OVA', 1, 'Completed', '2012-11-28', NULL, '5', 'The story revolves around Yukami Makoto, a high school boy whose hobby is visiting hot springs. His 100th hot spring visit is at Miyama-kan, an inn run by four poster girls: Tokura, Akino, Tsutsuji and Mitomo. There, Makoto spies Yuri, a goddess of the hot springs, and unexpectedly usurps her powers. Makoto ends up working at the inn. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Megami Paradise', 'OVA', 2, 'Completed', '1995-06-07', '1995-08-04', '5', 'Mama Megami, the mother goddess and ruler of paradise is retiring. Her successor appoints a young mage named Lilith to be one of her guardians. Lilith''s first assignment is to recruit two more worthy guardians for the new Mama Megami. Not an easy task, as Stashia, the first candidate on Lilith''s short list is not interested. Lilith didn''t even have a chance to ask the second person on the list, a warrior named Juliana due to a misunderstanding caused by Stashia''s little sister Rurubell. Rurubell wants to be a guardian, but Lilith turned her down due to her very young age and lack of experience. Meanwhile, Paradise is under attack by an evil goddess who wants to dominate it, and it''s up to Lilith, Stashia, Rurubell, and Juliana to thwart the attackers.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Firestorm', 'TV', 26, 'Completed', '2003-04-06', '2003-09-28', '5', 'It is the year 2104 AD. The terrible war is over and peace seemed close in the world. However, there is one thing that can bring down this peace. That is the criminal organisation who''s power and actions are widespread across the world... The Black Orchid.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mugen no Ryvius: Illusion', 'ONA', 6, 'Completed', '1999-01-01', '2000-01-01', '5', 'Short ONA episodes streamed on the TV Tokyo''s and Bandai''s official websites.', 974, 'https://cdn.myanimelist.net/images/anime/6/37031.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Angel''s Feather', 'OVA', 2, 'Completed', '2006-04-28', '2006-05-26', '5', 'In the Binfield Kingdom Chronicle, it is said that there was once a small, peaceful country called the Kingdom of Winfield, whose king and royal family possessed great white wings.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sousei no Aquarion: Myth of Emotions', 'TV', 12, 'Completed', '2025-01-10', '2025-03-28', '5', '"Remember, when you had wings."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Clione no Akari', 'TV', 12, 'Completed', '2017-07-12', '2017-09-27', '5', 'The story centers around an illness-stricken, constantly bullied orphan girl named Minori. After one rainy day, she doesn''t turn up at school, having been admitted into a hospital in a distant town. Two months pass, and the girl''s two school friends, Takashi and Kyouko, receive a mysterious email with no sender listed. The email reveals a summer festival taking place at a nearby town...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Funi Funi Marshmallow', 'ONA', 1, 'Completed', '2017-02-15', NULL, '5', 'An Kamio Japan character line, Funi Funi Marshmallow was originally released as a 3DS game people could purchase from the Japan Nintendo eShop. Now these cute marshmallow critters have their own show!', 462, 'https://cdn.myanimelist.net/images/anime/11/84312.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nora to Oujo to Noraneko Heart', 'TV', 11, 'Completed', '2017-07-12', '2017-09-27', '5', 'Nora Handa is a boy who lives with Shachi Yuuri, who was adopted by his mother. With everyone supporting, the two of them grew up healthily even after their parents passed away. Shachi, who likes Nora the most, wakes him up every morning.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sono Me ga Mitsumeru Mono', 'Special', 1, 'Completed', '2017-06-19', NULL, '5', 'A web-exclusive collaboration between Santen an eye drops company and One Piece. The commercial is promoting the new Sante FX eye drops in a stylish Luffy model and Trafalgar Law model. On October 31, 2017 another commercial was released with the same animation but showcasing a Sanji model and Zoro model instead.', 1030, 'https://cdn.myanimelist.net/images/anime/2/87540.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Death Stranding: Isolation', 'ONA', NULL, 'Upcoming', '2027-01-01', NULL, '5', 'Once, there was an explosion...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fangkai Nage Nuwu', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'Modern man Cheng Yan unexpectedly dies and his soul travels to a medieval European-style otherworldly continent, becoming Roland, the fourth prince of the Kingdom of Graycastle. This playboy prince saves the witch Anna at an execution scene and is shocked to discover that magic really exists in this medieval-style otherworld.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kashita Maryoku wa "Revo Barai" de Kyousei Choushuu', 'TV', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'Lent is part of the up-and-coming party known as the "Skypiercers," and thanks to his unique Gift, he can loan massive amounts of magic to others. No MP? No problem with Lent around! Except, now that his companions have become formidable heroes (thanks to his skill), his usefulness is questioned. Kicked out of the group, Lent is furious...until he discovers a hidden power to his Gift. Now, with his adorably devious fairy partner, he''s going to claw back every last scrap of magic from his former party—with interest!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sorotani no Keibatchi Season 3', 'TV', 4, 'Completed', '2025-11-05', '2025-11-26', '5', 'Third season of Sorotani no Keibatchi.', 214, 'https://cdn.myanimelist.net/images/anime/1962/153512.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Needy Girl Overdose', 'TV', NULL, 'Upcoming', '2026-04-01', NULL, '5', 'Needy Girl Overdose is a "multi-ending adventure" depicting daily life with "OMGkawaiiAngel-chan," a young girl with a rather extreme need for approval attempting to become the #1 "Internet Angel" (streamer). Gradually build up OMGkawaiiAngel-chan''s number of followers as she spends her days streaming, using various "stress relievers," and generally being kinda messed up. Experience all the different crazy ups and downs and find out for yourself whether this story is even capable of having a happy ending.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tuer Ni Wudile Xiashan Qu Ba', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'The Ye family was suddenly massacred—Ye Beichen''s parents and brothers were slaughtered, and he himself was ruthlessly thrown into the moat, clinging to life by a thread. Rescued by his senior sister, he was taken to Kunlun Mountain, where he spent five grueling years mastering martial arts. Five years later, he returned in full force, armed with the peerless skills taught by 99 invincible masters. Back in the mortal world, when faced with old enemies and powerful factions, Ye Beichen showed no fear. With extraordinary martial prowess and overwhelming strength, he unleashed chaos across the city, carving a path of revenge and dominance—turning the tables and crushing all who once sought his downfall.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yong Sheng: Tai Yuan Xian Fu', 'ONA', NULL, 'Upcoming', '2025-12-20', NULL, '5', 'Fifth season of Yong Sheng.', 645, 'https://cdn.myanimelist.net/images/anime/1825/153461.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zuoshou Shanglan 3', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'Xu Xingze ended up at Jingbei Affiliated High School by chance, where he met a group of supportive and comrades-in-arms on the basketball team. Through a series of intense games, he gradually discovered the meaning of playing basketball and strengthened his resolve. He longed to defeat Cheng Feng''s Beihai Middle School to prove himself, but before that, they have to overcome the formidable obstacle of Jingshi Affiliated High School…
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zhan Shen: Fanchen Shenyu II', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'After the Cangnan crisis was resolved, Lin Qiye completed the year-long Night Watchman training and assessment at Jinnan Mountain and became a formal Night Watchman. He then returned to Squad 136 and, together with his partners, embarked on a new battle against the Church of the Ancient Gods... A new Western evil god made his debut, and the pinnacle of humanity gathered in Cangnan, where a massive storm of disaster was quietly brewing.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ojisan wa Kawaii Mono ga Osuki.', 'TV', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'Mitsutaka Oji is a 40-year-old, handsome office worker that is admired by his colleagues. Of course, he has a secret he is trying to hide from everyone: he loves cute things. But with his nephew going to his apartment, Mitsutaka''s secret is now in danger!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Guanglin Diqiu', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'Aliens mistake "animation" for military information. Agent "Xiguang" is ordered to sneak into the earth to investigate the truth about animation. He encounters the earth girl "Qingyan". The two form the most unreliable interstellar investigation team in history and embark on a bizarre, ridiculous and magical journey.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yi Wanjia Zhi Ming', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'In the city, people lived under the protection of a barrier, enjoying a peaceful life. Secretly, the Fortune Star agents of the Sword Bureau had been battling the calamity creatures for decades. When Fortune Star agents were kidnapped, the creatures swarmed the city, bringing devastation. The reclusive youth Chen Kefan, competing in an e-sports tournament, encountered an invasion of bloodblade bugs and witnessed the killer of his parents reappear. In the desperate fight, his latent Fortune Star power awakened, setting him on a path of revenge. Yet, as he and his comrades fought bloodily and risked their lives, they discovered that the apocalypse was merely a game played by the gods.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chou Kaguya-hime!', 'ONA', 1, 'Upcoming', '2026-01-22', NULL, '5', 'Chou Kaguya-hime! reimagines Japan''s oldest folktale with a modern touch by integrating music, fantasy, and contemporary animation.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rhapsody', 'ONA', 4, 'Completed', '2023-11-20', NULL, '5', '', 344, 'https://cdn.myanimelist.net/images/anime/1766/139762.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Guardy Girls', 'Movie', 1, 'Completed', '2022-10-14', NULL, '5', 'Three amazing girls--the far-too-strong Silvia, the gun-totin'', bullet-blastin'' Laurie, and the scientific magical girl Fumi--have formed the Guardy Girls, a brand new team of heroes! They''re faced with a rogues gallery of wacky, off-kilter villains--and fellow do-gooders, too! It''s a grand way to kick off the Girls'' daunting, amazing dream of a hero run! 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('I''m Late', 'Movie', 1, 'Completed', '2021-01-01', NULL, '5', 'If your girlfriend would tell you "my period hasn’t come yet," or if your period hasn’t come after the affairs with your boyfriend, how would you feel and how would you behave?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kirakira Shougakusei Celeb-chan Specials', 'Special', 7, 'Completed', '2007-06-20', NULL, '5', 'DVD specials of Kirakira Shougakusei Celeb-chan. These were ''original draft'' episodes. As in, these episodes were created for the TV broadcast but were either cut entirely or their concepts were extremely reworked. For example, Celeb-chan''s toy poodle rather than being an aggressive small dog, is portrayed as a large-bodied  severely inbred dog for most of these specials.', 214, 'https://cdn.myanimelist.net/images/anime/1695/105713.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ganbare-bu Next!', 'TV', 6, 'Completed', '2015-06-08', '2015-07-13', '5', '', 241, 'https://cdn.myanimelist.net/images/anime/3/75881.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hikawa Maru Monogatari', 'Movie', 1, 'Completed', '2015-08-22', NULL, '5', 'Hirayama Jirou has lost his mother in the Great Kanto Earthquake and now runs a soba stall with his father. He decides to join the crew of the famous ocean liner Hikawa Maru and finds work cooking in the ship''s galley. Through his eyes, the film explores the ship''s 85-year history.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lulin Da Maoxian', 'Movie', 1, 'Completed', '2013-01-19', NULL, '5', 'When a girl named Rainie runs away from home after her mom forgot about her birthday, she is magically transported from the big city to an enchanted jungle in an unfamiliar land where she meets Blue. With the help of Blue''s grandfather and their newfound friend Mulla, they embark on an epic adventure to help Blue become the leader he is destined to be and save the rainforest from the villainous Boss Cain. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nangoku Shounen Papuwa-kun: Hoshifuru Yoru ni Aimashou', 'OVA', 1, 'Completed', '1994-12-07', NULL, '5', '', 607, 'https://cdn.myanimelist.net/images/anime/1188/105819.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oshiete Hokusai! The Animation', 'ONA', 10, 'Completed', '2021-03-07', '2021-03-14', '5', 'Tenkorin Okakura is a high school slacker girl. While dreaming of a painter god, she makes a wish that her dreams can come true without practice or effort. The god Raijin hears her wish, summons real-life historical artists, and tells Tenkorin to have these artists teach her so that she can fulfill her dreams. Guided by their teachings, Tenkorin aims to become a real painter with a promising future.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rainbow Ruby', 'TV', 26, 'Completed', '2017-03-02', '2017-08-25', '5', 'At Ruby''s house, a small event related to the main plot of each episode occurs, before a red jewellery on the chest of Choco, Ruby''s Teddy bear, flashes with a melody. Ruby then takes Choco to her room, and the two ''transport'' themselves to the Rainbow Village. There, Ruby hears an explanation from Ling Ling, the mayor of Rainbow Village, and transforms herself using her Rainbow Roller into an appropriate clothing to solve problems. Each episode concludes, back home, with another small event.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nintama Rantarou: Ninjutsu Gakuen to Nazo no Onna - Kore wa Jiken da yo! no Dan', 'Special', 1, 'Completed', '2013-03-20', NULL, '5', 'While Rantarou and Fushikizou are out running an errand, Fushikizou happens to spot a mysterious woman who''s being chased by some of the Tasogaredoki Castle ninjas. It turns out the woman is actually the disguised leader of the Dokutake Castle ninjas, Hieta Happousai, and the entire Ninjutsu Academy ends up getting involved in the events.', 53, 'https://cdn.myanimelist.net/images/anime/5/74597.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nintama Rantarou: Dokutake Onsen no Dan', 'Special', 1, 'Completed', '2007-05-04', NULL, '5', 'The Lord of Maitake Castle asks the Ninjutsu Academy Headmaster to accompany him when he sneaks out incognito to visit a dango shop, and Rantarou, Kirimaru and Shinbei tag along for the trip as well. However, it turns out that the shop is actually a Dokutake Castle trap, and they''re not the only ones who have been caught.', 53, 'https://cdn.myanimelist.net/images/anime/10/74596.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Norasco: Cinema Point Card-hen', 'Movie', 11, 'Completed', '2014-04-25', '2015-04-04', '5', 'Norasco episodes made for and screened at 109 Cinemas during previews. The films were fully included intermittently on the 4-disc DVD release of Norasco. The first and sixth episode were also posted on the official youtube page at later dates.', 457, 'https://cdn.myanimelist.net/images/anime/5/74576.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Norasco (TV)', 'TV', 43, 'Completed', '2014-05-19', '2015-03-31', '5', 'musicる TV signed up Norasco for their channel. Some of the ONA''s episodes were shown and then the episodes became mostly musicる TV exclusive.', 457, 'https://cdn.myanimelist.net/images/anime/7/74585.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tunshi Xingkong Movie: Xueluo Dalu', 'ONA', 1, 'Completed', '2024-12-07', NULL, '8', 'It''s time for battle! It''s time for excitement! It''s time for thrills! "This trial has a 98% mortality rate." "Then... I''ll eliminate everyone who threatens my life." Luo Feng travels to the Blood Continent for the trial to protect Earth. On this continent, he constantly pushes his limits, makes good friends and encounters powerful enemies, but he never retreats. Instead, he perseveres step by step, carrying the burden of his journey. Ultimately, he completes his infinite advancement, gaining the powerful ability to protect Earth.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rising Impact Season 2', 'ONA', 14, 'Completed', '2024-08-06', NULL, '8', 'Second season of Rising Impact.', 507, 'https://cdn.myanimelist.net/images/anime/1161/144669.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cheng He Titong', 'ONA', 24, 'Completed', '2024-06-14', '2024-10-25', '8', 'Yu Wanyin is teleported into a novel about palace struggles. The female protagonist of the novel is also teleported into it. To reverse her fate as a villain, Yu Wanyin chooses to join forces with a tyrant, who also turns out to be a modern man teleported in. Yu Wanyin hopes for the three modern people to put aside the palace struggles and just play cards and eat hotpot together peacefully. However, the female protagonist believes she is the chosen one, and still chooses to go against Yu Wanyin and the male protagonist King Duan''s team. Thus, Yu Wanyin has to carry out a series of actions in order to survive and help Xia dynasty prevent the drought crisis...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('New Panty & Stocking with Garterbelt', 'TV', 13, 'Completed', '2025-07-10', '2025-09-25', '8', 'Panty and Stocking Anarchy, the angel twin sisters, have even more ghosts to exorcize in Daten City, thanks to the failed opening of the Hell Gate. They must continue their ghost hunt alongside their longtime rivals, the sisters Scanty and Kneesocks Demon, who must earn Hell Coins to return to Hell. On top of that, the Demon sisters are staying at the church with Garterbelt, the priest in charge of the Anarchy sisters. These two polar opposite duos will have to set aside their differences if they wish to collect enough Heaven and Hell Coins to complete their mission and return to their respective realms.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Youkoso Jitsuryoku Shijou Shugi no Kyoushitsu e 3rd Season', 'TV', 13, 'Completed', '2024-01-03', '2024-03-27', '8', 'Third season of Youkoso Jitsuryoku Shijou Shugi no Kyoushitsu e.', 510, 'https://cdn.myanimelist.net/images/anime/1332/139318.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ookiku Furikabutte: Natsu no Taikai-hen', 'TV', 13, 'Completed', '2010-04-02', '2010-06-25', '8', 'Picking up where the original series left off, Ren Mihashi, the ace pitcher of the newly-formed Nishiura High School baseball team, and his teammates face the Sakitama High School team in the next round of the High School Baseball Invitational Tournament as they aim to play in the finals at legendary Hanshin Koushien Stadium.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hyouge Mono', 'TV', 39, 'Completed', '2011-04-07', '2012-01-26', '8', 'The story is set during Japan''s Sengoku Jidai (Era of the Warring States) and centers on Furuta Sasuke, a vassal of the great warlord Oda Nobunaga and a man obsessed with tea ceremony and material desires in his pursuit of a fortuitous life. Having learned from Oda and the legendary tea master Sen no Soueki, Furuta walks the way of the Hyouge Mono.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Working!!!', 'TV', 13, 'Completed', '2015-07-05', '2015-09-27', '8', 'As the stories of those connected to Wagnaria come to a close, only one thing is certain: the workplace is about to get crazier than ever before! Whether it be incredibly awkward romances, relentless searches for lost relatives, or even uncomfortable family reunions, lover of all things cute and tiny Souta Takanashi and his motley crew have plenty on their plates. With more Napoleon complexes, androphobia, and katana-wielding than you can shake a frying pan at, Working!!! delivers a final serving of the staff''s hilarious misadventures working at everybody''s favorite family restaurant.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou Shoujo Lyrical Nanoha A''s', 'TV', 13, 'Completed', '2005-10-02', '2005-12-25', '8', 'After solving the incident of the scattered Jewel Seeds, Nanoha Takamachi happily returns to her everyday life, though now with added magic practice in the morning. Exchanging video messages with Fate Testarossa and the crew of the Arthra, Nanoha eagerly awaits the chance to speak with them in person again. But while studying in her room one day, Raising Heart suddenly calls out to Nanoha and warns her of an incoming attack!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maoujou de Oyasumi', 'TV', 12, 'Completed', '2020-10-06', '2020-12-22', '8', 'The Demon Lord Tasogare''s castle is a dark and frightening place, filled to the brim with various monsters. Any soul unfortunate enough to be imprisoned here is sure to be terrified by the horrors within. However, the human princess Aurora Suya Rhys "Syalis" Kaymin is a different case. Rather indifferent to her situation, Syalis worries about one thing and one thing only—sleep. Ever since the demon lord kidnapped her from her kingdom, she has not had a single good night''s rest.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Girls & Panzer: Saishuushou Part 1', 'Movie', 1, 'Completed', '2017-12-09', NULL, '8', 'Rumor has it that Momo Kawashima, former student council member at Ooarai Girls Academy, is bound to repeat a year. Having failed her university entry exams, she is far from spending another year at Ooarai, but her plight is unenviable nevertheless.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('High Score Girl: Extra Stage', 'OVA', 3, 'Completed', '2019-03-20', NULL, '8', 'Four years after they first met, Haruo Yaguchi , Akira Oono, and Koharu Hidaka remain the best of friends. Tensions start to build up as Akira''s teacher, Gouda Moemi, becomes stricter than ever before, and Hidaka develops feelings for Haruo. Though he may not be the most composed and thoughtful person around, he has within him the one thing that started it all: his unconditional love for video games.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yi Nian Yong Heng', 'ONA', 52, 'Completed', '2020-08-12', '2021-07-21', '8', 'One will to create oceans. One will to summon the mulberry fields.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sword Art Online: Progressive Movie - Hoshi Naki Yoru no Aria', 'Movie', 1, 'Completed', '2021-10-30', NULL, '8', 'Excelling socially and academically, Asuna Yuuki is on track to ace her high school entrance exams. Her friend and classmate, Misumi "Mito" Tozawa, advises her to take a short break from studying and join her on the launch day of Sword Art Online (SAO)—the highly anticipated online virtual reality multiplayer game. Asuna accepts her offer and soon meets her in the game.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eve no Jikan (Movie)', 'Movie', 1, 'Completed', '2010-03-06', NULL, '8', 'In the Japan of the future, employing androids for various purposes is nothing out of the ordinary. However, treating androids on the same level as humans is frowned upon, and there is constant paranoia surrounding the possibility of robots defying humans, their masters. Those who appear too trustworthy of their androids are chided and labeled "dori-kei," or "android-holics."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aria the Benedizione', 'Movie', 1, 'Completed', '2021-12-03', NULL, '8', 'The successor and branch manager of the Himeya Company—one of the many Undine associations housing female gondoliers—Aika S. Granzchesta surprises everyone when she rejects tradition and refuses to inherit the company''s legendary gondola. Aika''s apprentice Azusa B. McLaren, unable to wrap her mind around her mentor''s unexpected decision, confronts her directly but to little effect. To better understand her reasoning, Azusa and her fellow Undines secretly plan to arrange a meeting with Aika.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bishoujo Senshi Sailor Moon: Sailor Stars', 'TV', 34, 'Completed', '1996-03-09', '1997-02-08', '8', 'Like the R Season, Sailor Stars is divided into two parts:
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yofukashi no Uta', 'TV', 13, 'Completed', '2022-07-08', '2022-09-30', '8', 'Kou Yamori is an average middle school student who struggles with grasping the complex concept of love. Because he sees little sense in surrendering to the norm, he soon stops going to school. Plagued with insomnia due to his idleness, Kou begins roaming the lonesome streets at night.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('5-toubun no Hanayome∽', 'Special', 2, 'Completed', '2023-09-02', '2023-09-09', '8', 'Featuring stories from the manga not adapted in the main anime.', 791, 'https://cdn.myanimelist.net/images/anime/1567/135752.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Macross F Movie 2: Sayonara no Tsubasa', 'Movie', 1, 'Completed', '2011-02-26', NULL, '8', 'Second Macross Frontier movie.', 780, 'https://cdn.myanimelist.net/images/anime/13/76398.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wotaku ni Koi wa Muzukashii OVA', 'OVA', 3, 'Completed', '2019-03-29', '2021-10-14', '8', 'Tarou Kabakura, a third-year high school student and captain of the boys'' volleyball team, is constantly being harassed by his underclassman Hanako Koyanagi, who is in charge of the girls'' team. Koyanagi insists that since the girls have a match coming up, Kabakura should give up the courts to let them practice. When he refuses, she pulls out photographic evidence exposing his secret hobby.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kobato.', 'TV', 24, 'Completed', '2009-10-06', '2010-03-23', '8', 'The friendly and sincere Kobato Hanato has a wish to go to a particular place no matter what. To fulfill this desire, she is tasked with helping people in their times of distress. For each mended broken heart, a small candy-like fragment is produced and fills a special bottle. Once the bottle is full, her wish will be granted.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Major Movie: Yuujou no Winning Shot', 'Movie', 1, 'Completed', '2008-12-13', NULL, '8', 'Goro briefly returns to Japan after a triumphant campaign in the US. He is heading towards Fukuoka where he played baseball when he was a fifth grader. Having just moved into a new town, this is where Goro faced a critical point in his life. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam Thunderbolt: December Sky', 'Movie', 1, 'Completed', '2016-06-25', NULL, '8', 'Federation troops and Zeon forces carry out a fierce battle in the Thunderbolt Sector in what was once Side 4 "Moore." The Thunderbolt Sector is a shoal zone composed of the debris of destroyed space colonies, named for the electrical discharges from the metal debris. MS pilot Io Flemming is among the Federation soldiers who are dispatched to the area, where Zeon sniper Daryl Lorenz awaits them on the battlefield.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam Thunderbolt', 'ONA', 4, 'Completed', '2015-12-25', '2016-04-22', '8', 'In Universal Century 0079, forces of the Earth Federation and Principality of Zeon engage in a battle within the Thunderbolt Sector during the One Year War. This section of space—known for its constant strikes of electricity—proves to be a deadly battlefield, as Federation pilot Io Fleming leads a charge against Zeon''s ace Daryl Lorenz and his squad of snipers. With the fighters on both sides proving to be formidable soldiers, neither side is willing to back down, fighting strategically amongst the remnants of colonies.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimagure Orange☆Road', 'TV', 48, 'Completed', '1987-04-06', '1988-03-07', '8', 'Kyousuke Kasuga is no stranger to being the new kid at school. Despite only being a third-year middle schooler, he has spent his entire childhood avoiding those who discover his family''s paranormal powers, and he has had to change schools seven times as a result. Upon catching a beautiful girl''s hat, he becomes optimistic and hopes that he and his family have finally moved for the last time.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bobobo-bo Bo-bobo', 'TV', 76, 'Completed', '2003-11-08', '2005-10-15', '8', 'In a futuristic world, the Maruhage Empire is a militant organization out to steal everyone''s hair, and thus their freedom. But a brave man with an afro of gold and nose hairs of steel stands up against their tyranny. Bobobo-bo Bo-bobo, trained in the ways of hair, rescues a teenager named Beauty from the grunts of the Maruhage Empire. Together, they start on a journey to defeat Emperor Tsuru Tsurulina IV. As Bo-bobo meets new friends and battles foes along the way, so too does he begin his quest to save all the hairs of the world!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tensei shitara Ken deshita', 'TV', 12, 'Completed', '2022-10-05', '2022-12-21', '8', 'A nameless sword wakes up to discover he has been reincarnated from his former life as a human. With his power of telekinesis, he moves around this new world, acquiring several skills and abilities. When the sword comes upon a forest filled with monsters, he meets a young girl fleeing from a beast. Grabbing the sword, the girl easily defeats the monster. After introducing herself as Fran, she names the sword "Shishou" and officially becomes his wielder.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fullmetal Alchemist: The Conqueror of Shamballa', 'Movie', 1, 'Completed', '2005-07-23', NULL, '8', 'In desperation, Edward Elric sacrificed his body and soul to rescue his brother Alphonse, and is now displaced in the heart of Munich, Germany. He struggles to adapt to a world completely foreign to him in the wake of the economic crisis that followed the end of World War I. Isolated and unable to return home with his alchemy skills, Edward continues to research other methods of escaping the prison alongside colleagues who bear striking resemblances to many of the people he left behind. As dissent brews among the German citizenry, its neighbors also feel the unrest of the humiliated nation.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Un-Go: Inga-ron', 'Movie', 1, 'Completed', '2011-11-19', NULL, '8', 'Prequel film of UN-GO telling the encounter of Shinjuurou and Inga.', 138, 'https://cdn.myanimelist.net/images/anime/5/35071.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Slam Dunk: Zenkoku Seiha Da! - Sakuragi Hanamichi', 'Movie', 1, 'Completed', '1994-08-20', NULL, '8', 'Set during the Inter High Championships, Shohoku take on Tsukubu, one of this year''s dark horses. It''s a clash of acquaintances as Anzai will face his former student which is now the coach of Tsukubu, while Akagi &amp; Kogure meet Godai their former classmate and Tsukubu''s captain. Finally Sakuragi is irked by the presence of Nango, Tsukubu''s center, who vies for Haruko''s attention.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Towa no Quon 4: Guren no Shoushin', 'Movie', 1, 'Completed', '2011-09-10', NULL, '8', 'The story follows a boy named Quon and others who suddenly wake up with supernatural powers.', 138, 'https://cdn.myanimelist.net/images/anime/1014/94473.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hellsing', 'TV', 13, 'Completed', '2001-10-11', '2002-01-17', '8', 'Hellsing, an organization specializing in dealing with supernatural threats, is called in to eliminate a vampire that is turning the villagers of Cheddar into ghouls. To put an end to this, the leader of the organization, Sir Integra Fairbrook Wingates Hellsing, dispatches her most formidable asset: a powerful vampire known as Alucard.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sugar Sugar Rune', 'TV', 51, 'Completed', '2005-07-02', '2006-06-24', '8', 'Chocolat Meilleure and Vanilla Mieux are both witches and childhood friends, pitted against each other in a contest to see who will become the next queen of the Magic World! In order to win, the two queen candidates must attend school in the human world, cultivating relationships to bring out their classmates hearts of friendship and love... But if a witch gives their heart to a human, they''ll die?! 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yondemasu yo, Azazel-san. (TV)', 'TV', 13, 'Completed', '2011-04-08', '2011-07-01', '8', 'Akutabe is a detective who summons devils to solve the troubles of his clients. One day, a low class devil Azazel Atsushi is summoned by Akutabe and is used harshly by him and his assistant Rinko.', 704, 'https://cdn.myanimelist.net/images/anime/4/75284.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tanoshii Muumin Ikka Bouken Nikki', 'TV', 26, 'Completed', '1991-10-10', '1992-03-26', '8', 'In the remote and mysterious Moomin Valley live the Moomin trolls, gentle and peaceful creatures. Young Moomin and his family experience many strange adventures, both magical and mundane. Based on the children''s stories by Tove Jansson.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Charlotte: Tsuyoimono-tachi', 'Special', 1, 'Completed', '2016-03-30', NULL, '8', 'Takehito Kumagami''s clairvoyance leads his group of friends to another child with supernatural powers: Iori Sekiguchi, a mind reader. However, as they try to approach her, they realize her power makes her nearly impossible to pin down. Having been chosen by the club to handle this case, Nao Tomori and Yuu Otosaka must find a way to get around the child''s unique ability before it is too late.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hoshi wo Ou Kodomo', 'Movie', 1, 'Completed', '2011-05-07', NULL, '8', 'If you could turn all your memories into a song, what would it resemble?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Be-Bop Highschool', 'OVA', 7, 'Completed', '1990-01-26', '1998-10-01', '8', 'For the invincible and basically happy punk lads Hiroshi and Toru, what they care about every day is to get a lot of attention from girls and to win the fights against the lads from other schools. Whenever provoked, they just go out fighting and settle the situation no matter what it costs.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Casshern Sins', 'TV', 24, 'Completed', '2008-10-02', '2009-03-16', '8', 'In a distant future, Earth has become a wasteland and humanity as we know it has died out. All that remains are sentient robots. They were supposed to be able to live forever—until the one called Luna died and the Ruin started. Their bodies will rust, and there is nothing that can be done to fix it. Now the robots are left only to contemplate their deaths, kept going only by the rumor that if they eat the one called Casshern, they will gain immortality.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xian Wang de Richang Shenghuo 4', 'ONA', 12, 'Completed', '2023-12-17', '2024-02-25', '7', 'Fourth season of Xian Wang de Richang Shenghuo.', 520, 'https://cdn.myanimelist.net/images/anime/1443/138753.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tiger & Bunny 2 Part 2', 'ONA', 12, 'Completed', '2022-10-07', NULL, '7', 'Second half of the second season of Tiger &amp; Bunny.', 116, 'https://cdn.myanimelist.net/images/anime/1941/128060.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meng Qi Shi Shen: Huanxi Zhui Hun', 'ONA', 12, 'Completed', '2022-07-05', '2022-09-13', '7', 'The third season of Meng Qi Shi Shen.', 1098, 'https://cdn.myanimelist.net/images/anime/1511/125055.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon Generations', 'ONA', 18, 'Completed', '2016-12-09', '2017-02-02', '7', 'Pokémon Generations revisits each generation of the Pokémon video game series to shed new light on some timeless moments. From the earliest days in the Kanto region to the splendor of the Kalos region, go behind the scenes and witness Pokémon history with new eyes!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gochuumon wa Usagi desu ka?', 'TV', 12, 'Completed', '2014-04-10', '2014-06-26', '7', 'Kokoa Hoto is a positive and energetic girl who becomes friends with anyone in just three seconds. After moving in with the Kafuu family in order to attend high school away from home, she immediately befriends the shy and precocious granddaughter of Rabbit House cafe''s founder, Chino Kafuu, who is often seen with the talking rabbit, Tippy, on her head.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Isekai Izakaya: Koto Aitheria no Izakaya Nobu', 'ONA', 24, 'Completed', '2018-04-13', '2018-09-14', '7', 'Experienced head chef Nobuyuki Yazawa and friendly waitress Shinobu Senke run a traditional Japanese izakaya called Nobu—a bar known for serving a tasty array of food and drink. Welcoming any and all customers, the pair strive to showcase Nobu''s exclusive menu and provide the best possible experience.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Owari no Seraph', 'TV', 12, 'Completed', '2015-04-04', '2015-06-20', '7', 'With the appearance of a mysterious virus that kills everyone above the age of 13, mankind becomes enslaved by previously hidden, power-hungry vampires who emerge in order to subjugate society with the promise of protecting the survivors, in exchange for donations of their blood.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon League', 'TV', 39, 'Completed', '1993-05-07', '1994-02-27', '7', 'Tokio and his father Amon go to the soccer country of Elevenia where they see a parade of the strongest soccer team of that country, the Winners. Amon challenges the team captain Leon to a soccer battle and, when Amon loses, Leon turns him into a miniature dragon. Tokio sees the fight and decides to challenge against Leon so that Amon can become human again.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('BanG Dream!', 'TV', 13, 'Completed', '2017-01-21', '2017-04-22', '7', 'When Kasumi Toyama was out camping as a child, she heard the rhythm of the "Star Beat" while admiring the starry night sky. This sparkling, heart-pounding sound left a lasting impression on her, and since then, she has constantly been seeking to rediscover that exciting thrill.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oshiete! Galko-chan', 'TV', 12, 'Completed', '2016-01-08', '2016-03-25', '7', 'At first glance, Galko, Otako, and Ojou are three high school girls who seem like they wouldn’t have anything to do with each other. Galko is a social butterfly with a reputation for being a party animal, even though she is actually innocent and good-hearted despite her appearance. Otako is a plain-looking girl with a sarcastic personality and a rabid love of manga. And Ojou is a wealthy young lady with excellent social graces, though she can be a bit absent-minded at times. Despite their differences, the three are best friends, and together they love to talk about various myths and ask candid questions about the female body.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seiyou Kottou Yougashiten: Antique', 'TV', 12, 'Completed', '2008-07-04', '2008-09-19', '7', 'Even though he is the top salesman at his company, Keiichirou Tachibana decides to quit his job to open a bakery. While looking over résumés for a head patissier, one name sticks out in particular: Yuusuke Ono, the young man who confessed his feelings to Keiichirou in high school—and whom Keiichirou harshly shot down. Now, Yuusuke is known both as a genius patissier for his skills in the kitchen, and for possessing a demonic charm that attracts even straight men into his bedroom.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mizuiro Jidai', 'TV', 47, 'Completed', '1996-04-04', '1997-02-27', '7', 'Yuuko is a shy middle school girl who has feelings for her childhood friend, the boy next door. When she finds out that her best friend also likes him, she is unsure what to do. The story explores the relationships between these three characters as they confront everyday junior high problems.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jungle no Ouja Tar-chan', 'TV', 50, 'Completed', '1993-10-14', '1994-09-29', '7', 'Ta-chan is the king of jungle. He was abandoned in savanna, and has been raised by a chimpanzee, Etekichi. He has a dearest wife, Jane who used to be a top model in New York, but now she looks... Anyway, to protect animals from poachers, Ta-chan is fighting against them with his disciple, Pedro, and a master of Chinese martial arts, Ryo.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ninkuu', 'TV', 55, 'Completed', '1995-01-14', '1996-02-24', '7', 'In the war, a group of warriors called Ninku fought against the Imperial Army and almost annihilated it. But in the end, the Ninku lost and got shattered. After the war, the imperial army established themselves as the defender of the people with the help of propaganda. They also managed to get the people to think the Ninku were the villains and had started the war. Fusuke looks like a child but he is the former captain of the first Ninku division. His mother was taken during the war and after the Ninku were defeated, he goes on a journey to find her. On his journey he meets Aicho and Touji, both also former Ninku captains, and together they fight against the imperial army that tries to kill the last remaining Ninkus.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Juuni Senshi Bakuretsu Eto Ranger', 'TV', 39, 'Completed', '1995-04-07', '1996-01-26', '7', 'The Eto Rangers ride in Space-Time Transmitting Machine Kirinda to repair the Novel Worlds of Mugen. The Eto Rangers themselves are anthropomorphic animals, each representing one of the 12 Chinese zodiac animals (and The Twelve Branches in Buddhism). In Japan they are known as the Eto animals. The Novel Worlds are stories created by the human imagination, such as old folk tales as well as newer books. These living worlds play out repeatedly, and are necessary for the good of humanity. Princess Aura rules Mugen, which is an island continent hanging over an ocean from the skybound Novel Pole. The Great God Goal gives her power, but she may never leave the small palace island area. Their nemesis is the forgotten Spirit of Cats, Nyanma (real name, Chocolat), who was excluded from the choice of 12 protectors by being disqualified from the race (in actual legend there are many versions of this story). She seeks her revenge by distorting Novel Worlds with Jarei Monsters.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jahy-sama wa Kujikenai!', 'TV', 20, 'Completed', '2021-08-01', '2021-12-19', '7', 'The great Jahy will not be defeated! Simultaneously combating starvation, the lack of A/C, and the unavoidable weakness of turning child-sized, Jahy—previously the second strongest being in the Dark Realm—is under great stress. If it weren''t for the destruction of the mana crystal which used to power the Dark Realm, Jahy would still be living a life of power and luxury. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eikoku Koi Monogatari Emma: Intermission', 'Special', 1, 'Completed', '2007-04-10', NULL, '7', 'This special is a recap of the first season of Eikoku Koi Monogatari Emma: Intermission as well as a preview of the second season Eikoku Koi Monogatari Emma: Molders Hen.', 53, 'https://cdn.myanimelist.net/images/anime/8/3091.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uta no☆Prince-sama♪ Maji Love Revolutions', 'TV', 13, 'Completed', '2015-04-05', '2015-06-28', '7', 'The third anime adaptation of the otome game Uta no☆Prince-sama♪.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('11-nin Iru!', 'Movie', 1, 'Completed', '1986-11-01', NULL, '7', 'After the Interstellar Alliance established peace among most of the planets in the universe, they created the Cosmo Academy. The academy is renowned as the most elite school in existence, with its graduates guaranteed virtually any job they desire. However, one can only become a student if they pass the entrance examinations held every three years, making the competition for admission extremely fierce.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuusha, Yamemasu', 'TV', 12, 'Completed', '2022-04-05', '2022-06-21', '7', 'When Demon Queen Echidna begins her invasion of the human realm, the people turn to the hero Leo Demonheart to protect them. Blessed with insurmountable power, Leo easily repels Echidna''s army, thereby saving the world. But instead of gratitude or admiration, Leo is met with disdain and scorn from his fellow humans, who fear his overwhelming strength and believe that it may eventually cause humanity''s demise.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Suite Precure♪ Movie: Torimodose! Kokoro ga Tsunagu Kiseki no Melody♪', 'Movie', 1, 'Completed', '2011-10-29', NULL, '7', 'After Cure Muse''s mission of restoring her father''s kind heart was accomplished, Ako and Mephisto decided to return to Major Land together. Suddenly, a howling noise rang through the city, and when it died down, all music was gone. Ako and Mephisto tried to establish contact with Major Land, but could not get a response.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Soukou no Strain', 'TV', 13, 'Completed', '2006-11-02', '2007-02-15', '7', 'Eleven-year-old Sara Werec''s elder brother, Ralph, was sent to the frontlines of an interstellar war 130 light years away, and Sara vowed to reunite with him one day as a comrade. Five years later, Sara is a student at Grapera Space Armed Soldier Academy, training to become a Reasoner, a pilot of an advanced weapons system called a "Strain."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shuffle!', 'TV', 24, 'Completed', '2005-07-08', '2006-01-06', '7', 'In present times, Gods and Demons coexist together with Humans after the door between each of these worlds had opened. Tsuchimi Rin is a normal young high school student attending Verbena Academy, spending his days living peacefully with his childhood friend Kaede. Unexpectedly, one day the King of Gods, the King of Demons and their families move in to be Rin''s next door neighbors. Apparently the daughter of the Gods, Sia, and the daughter of the demons, Nerine, are both deeply in love with Rin after having met him in the past. Along with his playful friendship with upperclassmen Asa and his encounter with the silent but cute Primula, Rin has much on his hands dealing with the affections of each of these girls. Based on the eroge by Navel.', 1153, 'https://cdn.myanimelist.net/images/anime/1290/133860.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lupin III: Alcatraz Connection', 'Special', 1, 'Completed', '2001-08-03', NULL, '7', 'Zenigata arrives on the ship "Machine Gun Kelly", a casino on the water owned by the mafia, because Lupin plans on stealing the casino''s money. Lupin and his gang manages to break into the ship''s vault but was unable to escape with the money due to Zenigata''s shooting. However, there was another purpose the ship had, one that Lupin was aware of; to search for a sunken ship filled with gold. Lupin managed to steal this data while he was on the ship, however, now they have to contend with Zenigata, the mafia, and a secret organization whose base is under Alcatraz, as they attempt to uncover the secret behind the organization and the sunken treasure.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shakunetsu Kabaddi', 'TV', 12, 'Completed', '2021-04-03', '2021-06-19', '7', 'Tatsuya Yoigoshi, a once nationally recognized soccer player, is now a first-year student at Noukin High School. Due to his developed hatred for sports, he has abandoned his previous aspirations to become a famous livestreamer on the internet. One day, Souma Azemichi, a first-year on the kabaddi team, seeks to recruit Yoigoshi and spontaneously interrupts his livestream.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gintama on Theater 2D: Kintama-hen', 'Movie', 1, 'Completed', '2024-11-22', NULL, '7', 'A compilation film of the Kintama Arc, episodes 1–4 in the third season, featuring additional footage. The movie is a part of the "Gintama 20th Anniversary Project."', 116, 'https://cdn.myanimelist.net/images/anime/1185/145136.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Geu Yeoreum Movie', 'Movie', 1, 'Completed', '2023-06-07', NULL, '7', 'The 61-minute long movie follows the life of 18-year-old Yi-gyeong (Yoon Ah-Young), a quiet, ordinary student who meets Suyi (Song Harim), an athletic girl who stirs up new romantic feelings in her, causing her to realize her identity. Over the next two years, their relationship helps both women grow, but ironically, because of this development, Yi-gyeong realizes her thoughts about Suyi have begun to change.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sengoku Youko: Yonaoshi Kyoudai-hen', 'TV', 13, 'Completed', '2024-01-11', '2024-04-04', '7', 'Aspiring samurai Shinsuke Hyoudou''s world is turned upside down when he witnesses hermit Jinka Yamato and fox girl Tama Youko slay a brigands'' lair in the blink of an eye. Tama happens to be katawara, a magically gifted species, who can share her powers with Jinka through a special ritual. Together, they travel the world as vigilantes to stop evil beings, be they katawara or human.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Onmyouji', 'ONA', 13, 'Completed', '2023-11-28', NULL, '7', 'Onmyouji tells the story of renowned onmyouji Abe no Seimei, who meets and befriends the straightforward court noble Minamoto no Hiromasa. Together, they deal with strange cases in the Heian capital surrounding demons and curses.', 559, 'https://cdn.myanimelist.net/images/anime/1757/139317.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ookami Shoujo to Kuro Ouji', 'TV', 12, 'Completed', '2014-10-05', '2014-12-21', '7', 'Erika Shinohara has taken to lying about her romantic exploits to earn the respect of her new friends. So when they ask for a picture of her "boyfriend," she hastily snaps a photo of a handsome stranger, whom her friends recognize as the popular and kind-hearted Kyouya Sata.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ze Tian Ji 2nd Season', 'ONA', 12, 'Completed', '2016-07-20', '2016-10-05', '7', 'The second season of Ze Tian Ji.', 295, 'https://cdn.myanimelist.net/images/anime/1592/90238.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Urusei Yatsura Movie 6: Itsudatte My Darling', 'Movie', 1, 'Completed', '1991-08-18', NULL, '7', 'Lupica, another one of the legion of space princesses that all seem to have found out about Earth in some tour book, appears and abducts Ataru! 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dirty Pair: Bouryaku no 005-bin', 'OVA', 1, 'Completed', '1990-01-25', NULL, '7', 'It''s Chief Gooley''s worst nightmare come true. The Lovely Angels are back on the job, but this time the 3WA''s Central Computer has assigned them two cases at the same time: investigate a space liner explosion in which three hundred people died, but no one`s come forward to claim any insurance money; and find a missing scientist and his family.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kikaider 01 The Animation', 'OVA', 4, 'Completed', '2001-11-21', '2002-03-20', '7', 'Ever since the fall of the DARK organization, Jiro has been wandering everywhere and wondering if he would ever see Mitsuko again or not. During his journey Jiro meets a beautiful girl named Rieko who is protecting Akira, a little boy from the evil Professor Gill. Ironicly, he''s the son of Professor Gill, but he is also the key to Gill’s menacing secret weapon and his plans to conquer the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dear Boys', 'TV', 26, 'Completed', '2003-04-07', '2003-09-29', '7', 'Aikawa Kazuhiko was the captain of Tendoji high school prestigious basketball team. He moves into a new town to attend Mizuho high school and joins its basketball team. However, Mizuho high''s basketball team is far from being prestigious, in fact, it''s now defunct. Nevertheless to say, Kazuhiko''s persistence, passion and basketball skills inspired other team members of the dysfunctional basketball team to gear up and start practicing again.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Viewtiful Joe', 'TV', 51, 'Completed', '2004-10-02', '2005-09-24', '7', 'Joe, a red-headed movie buff, and Silvia, his girlfriend, are having a bit of relationship trouble. Silvia feels that Joe is taking her for-granted and wants to do something together for once, so Joe decides to take her to see an old action movie featuring his favorite hero, Captain Blue. What started out as a cute movie date takes a turn for the worst when Silvia is pulled into the movie by the leader of the evil organization, Jado.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Happy☆Lesson The Final', 'OVA', 3, 'Completed', '2004-05-25', '2004-10-22', '7', 'When Mitsuki learns that the highschool is going to destroy the old school building, she is saddened at the thought of so many memories being erased. Chitose and the rest of the moms spring into action to stop the demolition. During their efforts, Fumitsuki, Chitose, and Mitsuki finally realize their true feelings.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Happy☆Lesson Advance', 'TV', 13, 'Completed', '2003-07-03', '2003-09-28', '7', 'Hitotose Chitose is now living together with his 5 teachers as his mothers when a mysterious girl appears and becomes their neighbor which turns out that that person is Nagatsuki Kuron who wants Mu-chan to be her mother so another sibling rivalry ensues as to who would end up as Mu-chan''s child. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shinpi no Sekai El-Hazard Season 2', 'OVA', 4, 'Completed', '1997-03-21', '1997-10-25', '7', 'Continuing the from OVAs; When Fujisawa, suffering from cold feet, leaves Miz at the altar, an enraged Priestess drafts Makoto and friends to go find him. In the couse of locating the hapless (and gutless) teacher, they find another Ifurita. Meanwhile Jinnai and Diva searching for a new Bugrom homeland stumble upon another yet another Demon God, the impish Kalia. However, unlike Ifurita she has a mind, and a mission, of her own... 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ijigen no Sekai El-Hazard', 'TV', 13, 'Completed', '1998-01-08', '1998-03-26', '7', 'Miz plans to retire as a Great Priestess of Water to married life with her darling Fujisawa and as replacement the young Qawoor Towles arrives to Floristica. Jinnai sees Qawoor''s initiation ceremony as a chance to infiltrate Makoto''s laboratory but accidentally activates a mysterious thingy that sends them all through the dimensions to a grey industrial city protected by a huge castle in an alternative world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saint Seiya: Saishuu Seisen no Senshi-tachi', 'Movie', 1, 'Completed', '1989-03-18', NULL, '7', 'Lucifer has been awoken from his eternal slumber by the spirits of Eris, Abel and Poseidon. He has come to kill Athena and fulfill his heart''s burning desire: becoming the strongest of all the gods.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Black Clover: Jump Festa 2016 Special', 'OVA', 1, 'Completed', '2016-11-27', NULL, '7', 'An OVA episode bundled with the 11th manga volume.', 400, 'https://cdn.myanimelist.net/images/anime/7/84639.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Poketoon (2025)', 'ONA', 3, 'Airing', '2025-10-03', NULL, '7', 'Three short episodes featuring Mega Evolution Pokémon released on the Pokémon Official YouTube Channel. Episode one features Mega Kangaskhan, episode two features Mega Gardevoir, and episode three features Mega Altaria.', 870, 'https://cdn.myanimelist.net/images/anime/1503/152957.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Digimon Story: Time Stranger Prelude', 'ONA', 1, 'Completed', '2025-10-13', NULL, '7', 'Set to Digimon Story Time Stranger''s theme song "wherever you are", the Prelude short focuses on Inori and her younger brother just before the main story''s events.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('7Fates: Chakho', 'ONA', 1, 'Completed', '2025-04-03', NULL, '7', '', 183, 'https://cdn.myanimelist.net/images/anime/1810/148985.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kao ni Denai Kashiwada-san to Kao ni Deru Oota-kun', 'TV', 12, 'Airing', '2025-10-04', '2025-12-20', '7', 'With a smirk, Oota disregards his single-digit test scores and searches for a new source of amusement. He is soon captivated by his classmate Kashiwada, a mysterious student who consistently wears a blank face. Oota conspires to break her placid demeanor through scares and mischievous schemes, though his tactics always seem to backfire.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimi to Koete Koi ni Naru', 'TV', 12, 'Airing', '2025-10-14', '2025-12-30', '7', 'When high schooler Mari bumps into a fellow tardy student, she''s surprised to find out he''s a beastfolk who''s to attend her school! After all, it''s not rare for beastfolk to coexist alongside humans, but it''s still uncommon, with the prejudice and all. Nervous to meet one at first, Mari soon learns there''s more to him than his furry exterior. In fact, the more she gets to know him, the more she finds herself drawn to him, his steadfastness, his kindheartedness, and... his body...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wujin Shenyu', 'ONA', 80, 'Completed', '2024-08-18', '2025-05-15', '7', 'Seven years ago, the family of the mortal prince Li Han was killed by seven immortals. When he was dying, he and his sister Li Yao were saved by the legendary Endless God Realm. Seven years later, Li Han returned. In order to wake up his sister, he must constantly improve his cultivation according to the requirements of the God Realm to protect the people. At the same time, he also vowed to find the murderer of that year and take revenge! But things are more complicated than he imagined. As the truth is revealed bit by bit, Li Han must make a choice between revenge and gratitude...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Class no Daikirai na Joshi to Kekkon suru Koto ni Natta.', 'TV', 12, 'Completed', '2025-01-03', '2025-03-21', '7', 'There is only one person that high school student Saito Houjou truly cannot stand—and that is his temperamental classmate, Akane Sakuramori. The two have always been on bad terms; their contrasting views and personalities only lead to endless fighting. However, everything changes when Saito''s grandfather and Akane''s grandmother arrange a sudden meeting and insist that the two get married!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Princess Principal: Crown Handler 3 - Cost for Custom Cars', 'Special', 1, 'Completed', '2023-11-22', NULL, '7', 'Short special included with the Princess Principal: Crown Handler 3 Blu-ray release.', 48, 'https://cdn.myanimelist.net/images/anime/1604/152156.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hyakushou Kizoku', 'TV', 12, 'Completed', '2023-07-07', '2023-09-22', '7', 'Renowned manga artist Hiromu Arakawa has an unusual backstory: she used to work on a farm in Hokkaido, the food warehouse of Japan, for seven years! To her editor, Ishii, harvesting produce and milking cows are foreign concepts; but as the daughter of two multigenerational farmers, Arakawa is there to explain the challenging yet noble job of being a farmer.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Level 1 dakedo Unique Skill de Saikyou desu', 'TV', 12, 'Completed', '2023-07-08', '2023-09-23', '6', 'As a corporate slave, Ryouta Satou experiences the worst forms of stress, overwork, and loneliness. Even after he is hospitalized due to exhaustion, his days of toil only become worse. Soon enough, the sheer fatigue catches up to him and kills him in his sleep. However, Ryouta is given a second chance at life: he wakes up in another world as a slime drop—much to the surprise of Emily Brown, the petite blonde girl who defeated said slime.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece: Mugiwara no Ichimi kara no Kansen Yobou Message', 'Special', 9, 'Completed', '2020-03-16', NULL, '6', 'The One Piece: Infection Prevention Message from the Straw Hat Pirates is a series of animated PSAs that were made by Toei Animation and aired on Fuji TV near the start of the COVID-19 pandemic in March 2020. Each PSA features a member of the Straw Hat Pirates giving viewers brief advice about keeping themselves and others safe from the COVID-19 virus. The Straw Hats are all voiced by their regular anime voice actors.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oniichan dakedo Ai sae Areba Kankeinai yo ne! Specials', 'Special', 6, 'Completed', '2012-12-26', '2013-05-29', '6', 'Short specials included in the Onii-chan Dakedo Ai sae Areba Kankeinai yo ne Blu-rays and DVDs.', 761, 'https://cdn.myanimelist.net/images/anime/6/46981.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Miss Monochrome The Animation: Soccer-hen', 'ONA', 1, 'Completed', '2014-06-17', NULL, '6', 'Special of Miss Monochrome. It''s about football. Aired on the official Miss Monochrome YouTube channel.', 756, 'https://cdn.myanimelist.net/images/anime/10/63625.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lupin III 3DCG', 'Special', 1, 'Completed', '2012-03-28', NULL, '6', 'Pilot for a hypothetical Lupin 3DCG project included with the 40th anniversary Master File BD/DVD.', 560, 'https://cdn.myanimelist.net/images/anime/11/89649.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hibike! Euphonium Movie: Photo Session e Youkoso', 'Movie', 3, 'Completed', '2017-09-30', NULL, '6', 'Short theater manners animations shown before Hibike! Euphonium Movie: Todoketai Melody.', 494, 'https://cdn.myanimelist.net/images/anime/1043/92924.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yami Shibai 6', 'TV', 13, 'Completed', '2018-07-07', '2018-09-29', '6', 'Late at night, in a clearing within a dark fog-filled forest, there sits a kamishibai storyboard. A visitor approaches, and suddenly, the fog recedes. A shape begins to take form beside the board—this figure is the masked Storyteller, who once again starts to spin tales of horror and despair.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kung Fu Liaoli Niang', 'ONA', 1, 'Completed', '2011-07-04', NULL, '6', 'A young, starving traveler finds himself in the middle of a kung fu fight between two food vendors who try and entice him to eat at their shops.', 1106, 'https://cdn.myanimelist.net/images/anime/1286/102359.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Robot Town Sagami 2028', 'ONA', 1, 'Completed', '2016-04-12', NULL, '6', 'A promotional anime made with Tezuka Productions and Kanagawa''s Industrial Labor Bureau to showcase a future where there is harmony between humans and robots.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nuwa Chengzhang Riji', 'ONA', 30, 'Completed', '2016-04-12', '2016-11-01', '6', 'This story follows an orphan girl rumoured to be a successor of "Nuwa", the goddess of creation in ancient Chinese mythology.', 108, 'https://cdn.myanimelist.net/images/anime/7/79259.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Teekyuu 5 Specials', 'Special', 2, 'Completed', '2015-11-27', NULL, '6', 'Unaired specials included in the Blu-ray and DVD release.', 566, 'https://cdn.myanimelist.net/images/anime/10/76333.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mini Hama: Minimum Hamatora', 'TV', 8, 'Completed', '2015-11-01', '2015-12-21', '6', 'Super deformed Hamatora.', 510, 'https://cdn.myanimelist.net/images/anime/6/76833.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kurokan', 'ONA', 33, 'Completed', '2013-01-01', '2014-01-01', '6', 'To Kirino High, the goal of getting into Koshien Stadium becomes important because the 100th anniversary is around the corner. However, Kurokan''s unique way of training has upset the Kirino High Baseball Team Support Association and Alumni Club. Morioka, on the other hand, is a preferrable coach beacuse of his solid style. At the same time, Kurokan''s decision on player positions has caused confusions to the team.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tottoko Hamtarou OVA 3: Hamuchanzu to Niji no Kuni no Oujisama - Sekai de Ichiban no Takaramono', 'OVA', 1, 'Completed', '2004-03-24', NULL, '6', 'Based on the third Hamtaro game (fourth in Japan), Prince Bo falls from the sky when the rainbow disappears. Now Hamtaro and the Ham-Hams must help him bring back the rainbow. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Madobe Nanami no Windows 7 de PC Jisaku Ouen Commercial!!', 'Special', 1, 'Completed', '2010-05-09', NULL, '6', 'Madobe Nanami is a computer store employee who instructs customers on how to magically assemble their PCs.  She also shows them some of the features of Windows 7.', 745, 'https://cdn.myanimelist.net/images/anime/1387/147466.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cue! Short Anime', 'ONA', 12, 'Completed', '2019-09-07', '2022-08-17', '6', 'Short anime released in the mobile app, and then later bundled with the Blu-ray volumes of Cue!.', 1141, 'https://cdn.myanimelist.net/images/anime/1805/123255.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon (2019): Natsuyasumi Chokuzen 1-jikan Special', 'Special', 1, 'Completed', '2021-07-02', NULL, '6', 'Recap TV Special that aired after episode 72 of Pokemon (2019).', 621, 'https://cdn.myanimelist.net/images/anime/1977/122521.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Akuma-kun: Youkoso Akuma Land e!!', 'Movie', 1, 'Completed', '1990-03-10', NULL, '6', '', 1030, 'https://cdn.myanimelist.net/images/anime/1234/148922.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Onsen Yousei Hakone-chan', 'TV', 13, 'Completed', '2015-10-04', '2015-12-27', '6', 'After many years of dormant rest, a hot springs fairy awakens in modern-day Japan. However, while she slept, she took on the appearance of a young girl. She decides to cooperate with the locals whilst trying to regain her powers.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Petit☆Dream Stars! Let''s La Cooking? Showtime!', 'Movie', 1, 'Completed', '2017-10-28', NULL, '6', 'A 3DCG short screened alongside Kirakira☆Precure A La Mode Movie: Paritto! Omoide no Mille-Feuille!.', 1030, 'https://cdn.myanimelist.net/images/anime/3/89867.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Joshikausei', 'TV', 12, 'Completed', '2019-04-06', '2019-06-22', '6', 'Momoko Futo is an average high-school girl going about her everyday life. Though laid-back and cheerful, her life is anything but mundane as her eccentricity and clumsiness never fail to spice up her days. Her two best friends are always with her: the cute and innocent Mayumi Furui, and the calm and cool Shibumi Shibusawa. Without any spoken dialogue or narration, Joshikausei aims to recount the comedic shenanigans these girls get up to through the expressive sounds and gestures that they make.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Santa no Yama Yousei no Mori', 'OVA', 2, 'Completed', '1996-10-25', '1996-11-05', '6', 'A two volume VHS release about Santa Claus. The first volume is about how elves try to keep Santa from moving from the cold North Pole. The second volume is about Santa trying to go on a diet because he''s eating too much of Mrs. Clause''s delicious food.', 1002, 'https://cdn.myanimelist.net/images/anime/1460/147145.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('True Tears Recap', 'Special', 1, 'Completed', '2013-01-29', NULL, '6', 'Recap of the first ten episodes of True Tears, included on the Blu-ray Box volume.', 653, 'https://cdn.myanimelist.net/images/anime/1956/98464.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sengoku Choujuu Giga: Otsu', 'TV', 13, 'Completed', '2017-01-15', '2017-04-09', '6', 'Second season of Sengoku Choujuu Giga.', 403, 'https://cdn.myanimelist.net/images/anime/7/83737.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shounen Ashibe: Go! Go! Goma-chan 4', 'TV', 24, 'Completed', '2019-04-02', '2019-12-17', '6', 'Fourth season of Shounen Ashibe: Go! Go! Goma-chan.', 146, 'https://cdn.myanimelist.net/images/anime/1713/112181.jpg');
