INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oniwa no Soto', 'ONA', 2, 'Completed', '2014-06-23', '2014-08-14', '5', 'Saigo no Shudan''s advertisement movies for the 2014 Shibukaru Festival hosted by the Parco department store. A regular version and long version exist of the advertisement, though both share very little footage between each other.', 770, 'https://cdn.myanimelist.net/images/anime/1663/95536.jpg');
