INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Iro wo Kuu Akuma', 'ONA', 1, 'Completed', '2015-08-24', NULL, '5', 'Anthology produced by Adobe Creative Cloud''s Japan division to promote their software suite. It showcases the talents of various Japanese experimental animators.', 998, 'https://cdn.myanimelist.net/images/anime/1151/102844.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kandagawa Jet Girls Recap', 'Special', 1, 'Completed', '2019-11-05', NULL, '5', 'Recap of the first four episodes of Kandagawa Jet Girls.', 991, 'https://cdn.myanimelist.net/images/anime/1851/103980.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Anitore! EX', 'TV', 12, 'Completed', '2015-10-13', '2015-12-29', '5', '"Move your soul and body!" Each episode contains a variety of routines, such as push-ups, sit-ups, spine twists, dance, yoga, stretches, trunk training, and taichi. Five girls aiming to become idols will exercise with you, and that troubling body fat percentage will go down by 1000%...!?', 745, 'https://cdn.myanimelist.net/images/anime/3/77048.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Suzakinishi The Animation', 'TV', 12, 'Completed', '2015-07-08', '2015-09-23', '5', 'Voice actresses Aya Suzaki and Asuka Nishi announced at an event in Tokyo on Sunday that their Suzakinishi radio program will get a television anime adaptation starting in July. The Suzakinishi The AanimationN anime will air on Tokyo MX TV, TV Kanazawa, and Sun TV.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Agukaru: Play with Ibaraki-hen Episode 0', 'ONA', 1, 'Completed', '2015-03-28', NULL, '5', 'The first half of the episode recaps the first episode of the first season and the second half is all new animation setting up for the second season as the characters go to cities rather than being out in the countryside.', 945, 'https://cdn.myanimelist.net/images/anime/3/73822.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shironeko Project: Zero Chronicle', 'TV', 12, 'Completed', '2020-04-06', '2020-06-22', '5', 'The world is divided into two kingdoms: the Kingdom of White, which floats in the heavens and is ruled by their queen Iris, and the Kingdom of Black, which stands upon desolate land below and houses the King of Darkness as its ruler. As of late, forces of evil have amassed great power, posing a threat to the entire world. Being the main representative of the Light, it is Iris'' duty to maintain the balance of the world and fight off the darkness in her kingdom.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fengkuang Dongwu Cheng: Dongwu Cheng Ri Yu Ye', 'ONA', 4, 'Completed', '2025-11-04', NULL, '5', 'A special collaboration between Disney China and the Shanghai Animation Film Studio to promote Zootopia 2.', 792, 'https://cdn.myanimelist.net/images/anime/1564/153328.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nigashita Sakana wa Ookikatta ga Tsuriageta Sakana ga Ookisugita Ken', 'TV', NULL, 'Upcoming', '2026-04-01', NULL, '5', 'Maria, the daughter of a duke, grew up believing she would one day inherit her father''s dukedom. Accordingly, she focused her attentions on honing her martial arts prowess, while thoughts of marriage fell by the wayside. But the arrival of a baby brother in her family means she''s losing her role as heir! Now that she''s decided it''s time to marry after all, she''s arrived a little late to the game! Are there even any eligible bachelors left?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Omae wa Mada Gunma wo Shiranai: Reiwa-ban', 'TV', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'Light anime for Omae wa Mada Gunma wo Shiranai.', 422, 'https://cdn.myanimelist.net/images/anime/1156/153079.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bungou Stray Dogs Wan! 2', 'TV', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'Second season of Bungou Stray Dogs Wan!.', 138, 'https://cdn.myanimelist.net/images/anime/1199/153220.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aikatsu! Memorial Stage: Kagayaki no Unit Cup', 'Movie', 1, 'Completed', '2025-06-20', NULL, '5', 'It has been announced that the "Unit Cup" will be held at Starlight School''s middle school.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dark Gathering 2nd Season', 'TV', NULL, 'Upcoming', NULL, NULL, '5', 'Second season of Dark Gathering.', 621, 'https://cdn.myanimelist.net/images/anime/1141/153080.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nijusseiki Denki Mokuroku: Eureka Evrika', 'TV', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'In an alternate version of the early 20th-century, where steam power developed rapidly and progress has now stagnated—Kyoto is shrouded in soot, smoke, and steam.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ghost Concert: Missing Songs', 'TV', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'In a world where songs have been banned, instead of humans playing instruments and creating music, a music app titled "MiucS" is in charge of these things. High school student Seria Aiba goes out with her friends one day, but she happens to hear someone singing, which is supposed to be prohibited. What she finds is a lone ghost, a "Great Ghost" who has appeared from outside this world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam: Tekketsu no Orphans - Urdr Hunt: Chiisana Chousensha no Kiseki', 'Movie', 1, 'Completed', '2025-10-31', NULL, '5', 'Year P.D. 323. Gjallarhorn''s political intervention into the Arbrau central parliament escalated into an armed conflict using mobile suits. The incident was brought to an end by Tekkadan, a group of boys who came from Mars.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('No.5', 'Special', 1, 'Completed', '2003-02-25', NULL, '5', 'A promotional video by Kamikaze Douga for Taiyo Matsumoto''s No.5. It was included with the first issue of Monthly Ikki.', 461, 'https://cdn.myanimelist.net/images/anime/1380/139670.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xingxing Meng', 'TV', 50, 'Completed', '2015-06-01', '2015-07-01', '5', '', 156, 'https://cdn.myanimelist.net/images/anime/1331/130505.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bao Dan Jing Ying', 'ONA', 12, 'Completed', '2015-02-13', '2016-03-24', '5', '', 4, 'https://cdn.myanimelist.net/images/anime/1079/127203.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('High Score Girl II', 'TV', 9, 'Completed', '2019-10-26', '2019-12-21', '8', 'The year is 1996, and second-year high school students Haruo Yaguchi, Akira Oono, and Koharu Hidaka live their lives as passionately about video games as they were five years ago. Brought together by arcade games, what began as a healthy rivalry and friendship has turned into something more. As they endeavour towards understanding their unfamiliar feelings, they work with allies, navigate high school, and find that, although life has its many challenges, there''s always a game or two they can rely on.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kono Oto Tomare!', 'TV', 13, 'Completed', '2019-04-07', '2019-06-30', '8', 'Gen Kudou, a koto maker, believes that his delinquent grandson Chika would never understand the profoundness of the traditional musical instrument. In an attempt to make up for his naivety and understand the words of his late grandfather, Chika tries to join the Tokise High School Koto Club. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kanon (2006)', 'TV', 24, 'Completed', '2006-10-06', '2007-03-16', '8', 'As a young child, Aizawa Yuuichi had often visited his cousin in the city; however, something drastic happened to keep him away for seven long years. Now, Yuuichi returns, his memories of those days are simply gone.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aria the Origination: Sono Choppiri Himitsu no Basho ni...', 'Special', 1, 'Completed', '2008-06-25', NULL, '8', 'With Aria Company closed for the day and her friends attending to other matters, Akari Mizunashi seizes this rare opportunity to go on a casual outing around Neo-Venezia with President Aria Pokoteng. Although her Prima Undine gondola training has taken her to many remarkable tourist spots, Akari finds greater exhilaration reveling in the ordinary sights and sounds of the town. As Akari and President Aria stroll through Neo-Venezia on their own exciting itinerary, some familiar faces are not far behind. Drawn into their private tour, they too may discover a new perspective of the city.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tennis no Oujisama: Zenkoku Taikai-hen - Final', 'OVA', 7, 'Completed', '2008-04-25', '2009-01-23', '8', 'After their victory over Shitenhouji Middle School in the semifinals, Ryouma Echizen and the Seishun Academy Boys Tennis Team must now face off against the two-time defending champions of Rikkai University-Affiliated Middle School in order to claim the national title. Rikkai is not only seeking revenge for its team''s previous loss to Seishun at the Kanto Regional Tournament, but they also are aiming to win the national title for a third consecutive year.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Noragami', 'TV', 12, 'Completed', '2014-01-05', '2014-03-23', '8', 'In times of need, if you look in the right place, you just may see a strange telephone number scrawled in red. If you call this number, you will hear a young man introduce himself as the Yato God.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tekkon Kinkreet', 'Movie', 1, 'Completed', '2006-12-23', NULL, '8', 'The streets of Treasure Town are said to belong to "The Cats." They know everything that goes on in the city, and no one can stir up trouble without going through them first. In reality, The Cats are a pair of orphan boys called Black and White, who aren’t afraid of anything or anyone. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kindaichi Shounen no Jikenbo', 'TV', 148, 'Completed', '1997-04-07', '2000-09-11', '8', 'Hajime Kindaichi''s unorganized appearance and lax nature may give the impression of an average high school student, but a book should never be judged by its cover. Hajime is the grandson of the man who was once Japan''s greatest detective, and he is also a remarkable sleuth himself.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fate/Grand Order: Zettai Majuu Sensen Babylonia', 'TV', 21, 'Completed', '2019-10-05', '2020-03-21', '8', 'A.D. 2016, the foundations of humanity have been incinerated by the Mage King Solomon. Chaldea, a secret mages organization with the mission to preserve humanity''s future, foresaw mankind''s extinction in 2015. Thus commenced the operation to repair the Singularities in history caused by Holy Grails dispersed across time and space—Operation Grand Order. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Douluo Dalu', 'ONA', 26, 'Completed', '2018-01-20', '2018-07-14', '8', 'Tang San is one of Tang Sect martial art clan''s most prestigious disciples and peerless in the use of hidden weapons. With high expectations, the sect''s elders believe his future will be bright; yet Tang chooses to forsake this life at the cost of obtaining the sect''s forbidden lore—an action punishable by death. Tang, now content with his ascension of knowledge, sees no reason to keep on living and jumps from Hell''s Peak, but little did he know that that would not be the end of his existence. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kobayashi-san Chi no Maid Dragon: Samishigariya no Ryuu', 'Movie', 1, 'Completed', '2025-06-27', NULL, '8', 'Miss Kobayashi, Tohru, Kanna, and Iruru''s peaceful lives are shattered when Kanna''s father, Kamun Kamui, leader of the Chaos Forces, arrives and forces her to return to the Dragon World to fix a past mistake. With a war brewing between Chaos and Harmony, Kanna must find a way to unite the two worlds but is torn between her loyalty to her friends and her father''s demands. Miss Kobayashi, however, refuses to let her go and tries to mend Kanna and Kamui''s broken bond. As dragons clash, Iruru uncovers a hidden force manipulating the war. Can they stop the war before it consumes both worlds?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zhu Xian 2nd Season', 'ONA', 26, 'Completed', '2024-03-30', '2024-08-10', '8', 'Ten years have passed since the great war between good and evil. Zhang Xiaofan, now known as Gui Li, fights against internal strife within the demonic sect. At this time, a rare treasure emerges in the Death Swamp, sparking a struggle among various forces. Gui Li and Lu Xueqi reunite, their love and hate deepening. Later, Gui Li investigates the disappearance of his subordinates at Fenxiang Valley, where he unexpectedly rescues the nine-tailed celestial fox, Xiao Bai, and obtains clues about the ancient witch clan. After countless near-death experiences, Gui Li finally persuades a powerful sorcerer with the ability to summon spirits to agree to go and heal Bi Yao. What will become of his ten-year-long wish…?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jibaku Shounen Hanako-kun 2', 'TV', 12, 'Completed', '2025-01-12', '2025-03-30', '8', 'There is a rumor in Kamome Academy that somewhere within the school premises lies a clock that governs the passage of time in the academy. That clock is overseen by three clock keepers—each representing the past, present, and future. Despite this, an unforeseen event causes mayhem, with students rapidly aging and the academy''s infrastructure falling apart.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aikatsu! 10th Story: Mirai e no Starway (2023)', 'Movie', 1, 'Completed', '2023-01-20', NULL, '8', '', 116, 'https://cdn.myanimelist.net/images/anime/1837/130395.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hanma Baki: Son of Ogre 2nd Season', 'ONA', 27, 'Completed', '2023-07-26', '2023-08-24', '8', 'Second season of Hanma Baki: Son of Ogre.', 990, 'https://cdn.myanimelist.net/images/anime/1800/135847.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hidamari Sketch x Honeycomb', 'TV', 12, 'Completed', '2012-10-05', '2012-12-21', '8', 'Studying at the Yamabuki Arts High School has been a dream-come-true for Yuno, and she''s learned so much already! And not just from her instructors, but from her friends and neighbors who''ve become her second family and made the Hidamari Apartments such a safe and nurturing home. But as the day of her "big sisters" Sae and Hiro''s graduation draws slowly closer, it''s time for Yuno to start seriously taking on the same role for Nazuna, Nori and the other budding young artists who''ve entered Hidamari''s protective cocoon. And it''s also time to tackle some really challenging artistic assignments. That doesn''t mean there won''t still be time for fun with Miyako and all the others, but it''s definitely time to pencil in her plans for the future. And sometimes that means you have to put the art before the course! 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sakasama no Patema', 'Movie', 1, 'Completed', '2013-11-09', NULL, '8', 'Patema is a plucky young girl from an underground civilization boasting an incredible network of tunnels. Inspired by a friend that mysteriously went missing, she is often reprimanded due to her constant excursions of these tunnels due to her royal status. After she enters what is known as the "forbidden zone," she accidentally falls into a giant bottomless pit after being startled by a strange creature.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nagi no Asu kara', 'TV', 26, 'Completed', '2013-10-03', '2014-04-03', '8', 'Long ago, all humans lived beneath the sea. However, some people preferred the surface and abandoned living underwater permanently. As a consequence, they were stripped of their god-given protection called "Ena" which allowed them to breathe underwater. Over time, the rift between the denizens of the sea and of the surface widened, although contact between the two peoples still existed.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Densetsu Kyojin Ideon: Hatsudou-hen', 'Movie', 1, 'Completed', '1982-07-10', NULL, '8', 'Pushed out to the far reaches of the galaxy, the crew of the Solo Ship faces impossible odds of survival. With the Earth destroyed and the remnants of the Buff Clan pushing them to their limit, the Ideon shows as the last line of defense for the battered remains of humanity. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Takarajima', 'TV', 26, 'Completed', '1978-10-08', '1979-04-01', '8', 'Jim Hawkins is a young boy lead by progressive events to embark on a search journey for the legendary treasure of the once dreaded pirate, Captain Flint. On their way to Treasure Island, John Silver, Jim''s best friend, take over command of the ship revealing his true self as the ruthless pirate who once was the right hand of Flint himself. Feeling betrayed, Jim now has to deal with his mixed feelings and face Silver who still consider himself and Jim as friends. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Non Non Biyori', 'TV', 12, 'Completed', '2013-10-08', '2013-12-24', '8', 'Hotaru Ichijou''s lifestyle completely changes when she leaves Tokyo and moves with her family to the isolated Asahigaoka village. Her new school has only five students including herself, all sharing a single classroom regardless of grade level. There are no convenience stores in the area, and it can take up to two hours for a bus to arrive.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Macross: Do You Remember Love?', 'Movie', 1, 'Completed', '1984-07-07', NULL, '8', 'After warping light-years away from Earth, the spacecraft Macross carries a city of civilians and soldiers back home. They continuously fight off the threat of the Zentradi and Meltrandi, giant alien races with whom humanity wages war. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hikaru no Go: Hokuto Hai e no Michi', 'Special', 1, 'Completed', '2004-01-03', NULL, '8', 'Hikaru is given a phone call asking him to appear in the Japan/China/Korea Junior''s Tournament but he finds out he will have to take place in a preliminary tournament to choose Japan''s three contestants. Upon discussing this with Akira, he discovers that Akira has already been chosen for the tournament and will not be taking place in the preliminaries. Hikaru then decides not to visit Akira''s Go Salon until he takes his place on the team with Akira. That may be tougher than originally planned, as not only does Hikaru have to battle with old friends for one of two coveted spots, but he may have a new challenger, in a promising player from the Kansai Go Institute. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Full Moon wo Sagashite', 'TV', 52, 'Completed', '2002-04-06', '2003-03-29', '8', 'Two years ago, Mitsuki Kouyama''s friend, Eichi Sakurai, moved to America before she could confess her feelings to him. Though she cannot contact him, they made a promise to fulfill their respective dreams: Mitsuki wants to become a professional singer, and Eichi an astronomer. She hopes that one day her music will reach him across the world with a brilliance like that of the full moon.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boku no Hero Academia the Movie 2: Heroes:Rising', 'Movie', 1, 'Completed', '2019-12-20', NULL, '8', 'Izuku "Deku'''' Midoriya and his fellow students in Class 1-A of UA High''s hero course have been chosen to participate in a safety program on Nabu Island. To further improve their skills and gain experience in more ordinary heroics, the students aid the kind citizens with small services and everyday chores. With the low crime rate in the quiet community, all seems well and good, but the rise of a new villain threatens to put the students'' courage to the test and challenge their capabilities as heroes.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bai She: Yuan Qi', 'Movie', 1, 'Completed', '2019-01-11', NULL, '7', 'Xiao-Bai, a white snake demon, is sent on a mission to assassinate the Emperor''s Taoist advisor, who has been killing snakes en masse in order to achieve immortality and curry the Emperor''s favor. Xiao-Bai, however, is attacked by the advisor''s lackeys before she can reach him and is subsequently defeated. Luckily, the demonic hairpin she was granted by the Snake Mother is able to save her life at the cost of her memories.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hello World', 'Movie', 1, 'Completed', '2019-09-20', NULL, '7', 'The year is 2027, and the city of Kyoto has undergone tremendous technological advancement. Within the city live two classmates: Naomi Katagaki, a socially awkward and introverted boy; and Ruri Ichigyou, a girl with a cold personality who is often blunt with people. Despite sharing Ruri''s love of reading, Naomi is afraid to approach her due to her unfriendly nature.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nanbaka 2', 'ONA', 12, 'Completed', '2017-01-04', '2017-03-22', '7', 'The second part of Nanbaka. The prisoners and their guards continue their comfortable lives at Nanba Prison. However, from the shadows emerges a new threat: Enki Gokuu, a person from Samon''s past, who has mysterious goals of his own.', 780, 'https://cdn.myanimelist.net/images/anime/1294/127370.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ling Long: Incarnation', 'ONA', 6, 'Completed', '2019-07-13', '2019-09-21', '7', 'In the not-too-distant future, the human world has long been overpopulated. Humanity marched to the stars in search of a new home, and just as this was going on, the moon''s alignment caused massive earthquakes to ripple across the world, lasting several decades. Humanity was demolished. When the land finally recovered, humanity reemerged to face this strange yet familiar world. Will we, who once lorded over this domain, still remain the masters of this world?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aikatsu!', 'TV', 178, 'Completed', '2012-10-08', '2016-03-31', '7', 'An idol''s brilliance illuminates the dreams of humanity. Starlight Academy, a holy ground for celebrities in training, seeks to realize this belief. Behind its rigorous entrance requirements lie not only the top young stars in the entertainment business, but some of the best memories these students will ever have.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Arslan Senki (TV): Fuujin Ranbu', 'TV', 8, 'Completed', '2016-07-03', '2016-08-21', '7', 'Continuing on his quest to retake Ecbatana, Prince Arslan and his company march toward the city. But upon receiving news that the neighboring Kingdom of Turan is launching an assault on the Parsian stronghold at Peshawar Citadel, the prince is forced to turn back in order to defend the fortress. Amid holding off the invading forces, the Parsian army is met by an unexpected visitor.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaichou wa Maid-sama!: Omake da yo!', 'Special', 1, 'Completed', '2011-05-11', NULL, '7', 'Upon returning home from her part-time job, Misaki Ayuzawa asks her mother to mend her maid uniform, which she accidentally tore while moving potted plants at Maid Latte. However, Misaki''s younger sister, Suzuna, volunteers to fix the uniform instead. After quickly repairing the damage, Suzuna shows interest in trying on the maid attire, greatly alarming Misaki. As she attempts to prevent the embarrassing situation from escalating, Misaki must also tend to unexpected guests in her house!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Magic Knight Rayearth II', 'TV', 29, 'Completed', '1995-04-10', '1995-11-27', '7', 'Little time has passed since the Magic Knights’ final confrontation with Princess Emeraude’s "Mashin." Still haunted by the princess’ death, Hikaru Shidou returns to Tokyo Tower. There, she meets her friends Umi Ryuuzaki and Fuu Hououji for the first time since their spontaneous quest to save Cephiro. Plagued by nightmares of the realm she had left behind, Hikaru is relieved to find that her companions too want to return and serve the kingdom they once so dutifully protected.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('D-Frag!', 'TV', 12, 'Completed', '2014-01-07', '2014-03-25', '7', 'The Kazama Family—a gang of three wannabe delinquents and close friends, spearheaded by Kenji Kazama, is trying to make a name for themselves at Fujou Academy. On the first day of the term, the gang finds themselves putting out a fire in the Game Development Club. Instead of thanking them, the eccentric club members attack and knock out Kenji''s two friends, forcing Kenji to fight for his life. Failing to escape, the gang leader is coerced into joining the Game Development Club.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aa! Megami-sama! (TV) Specials', 'Special', 3, 'Completed', '2005-04-01', '2005-12-23', '7', 'Due to the recent events that happened on the last episodes of the season, the Goddess have some stability problems with their body systems. The always adult looking Urd becomes a little girl and has a fateful encounter with a boy, whereas little Skuld becomes an adult and wants to experiment adulthood together with Keiichi.', 25, 'https://cdn.myanimelist.net/images/anime/2/17893.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gintama: Monster Strike-hen', 'ONA', 2, 'Completed', '2019-08-29', '2019-09-04', '7', 'Collaboration anime between Gintama and Monster Strike.', 116, 'https://cdn.myanimelist.net/images/anime/1806/124660.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chuunibyou demo Koi ga Shitai! Kirameki no... Slapstick Noel', 'Special', 1, 'Completed', '2013-06-19', NULL, '7', 'Although Yuuta Togashi and Rikka Takanashi have just started dating, they do not know how to progress their young relationship. Due to both of them being shy, neither of them are capable of making the first move. Rikka decides to ask her class representative Shinka Nibutani for some love advice, and she advises Rikka get closer to Yuuta during the Christmas season. Following the suggestion of Yuuta''s friend, Makoto Isshiki, they hold a Christmas party at Sanae Dekomori’s place.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ike! Ina-chuu Takkyuu-bu', 'TV', 26, 'Completed', '1995-04-06', '1995-09-28', '7', 'When the Inaho Junior High Ping-Pong Club grows apathetic about an upcoming tournament, their new manager, Kyoko Iwashita, boosts their morale with something they cannot refuse—a "sex pass," a voucher that grants the best player on the team unadulterated access to her body for a whole month. This is just one of many ways that this peculiar ping-pong club exceeds the realm of normalcy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hello!! Kiniro Mosaic', 'TV', 12, 'Completed', '2015-04-06', '2015-06-22', '7', 'Although learning different languages continues to be an interest for Shinobu and her friends, the new school year brings unexpected difficulties. Not only is there always something new and different to distract them from their studies, but Alice and Yoko also are having trouble adjusting to being in a different class from Shinobu and Aya.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kappa no Coo to Natsuyasumi', 'Movie', 1, 'Completed', '2007-07-28', NULL, '7', 'Kouichi Uehara is a fourth grade student living in the suburb of Tokyo. One day, he picks up a large stone which turns out to be a fossil of a baby "Kappa" who has been sleeping underground for the past 300 years, and names it "Coo." They become good friends and Coo starts living with Kouichi''s family. However, Coo has a hard time adjusting to life among humans and misses his kind.', 802, 'https://cdn.myanimelist.net/images/anime/10/4001.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shen Lan Qi Yu Wushuang Zhu', 'ONA', 15, 'Completed', '2022-07-23', '2022-10-15', '7', 'In the 2501st year of the Glacier Calendar, the asteroid where the demons and the orcs survive flew to and hit the only continent on the phalanx - the fairy continent, known as the cataclysm in history. After the human ancestor Tianxing predicted the cataclysm with the Book of Prophecy, the two great powers, the demons and the spirits, joined all races to refine the seven-sacred artifact to fight against the collision and avoid the destruction of the world. The Fairy Continent was then torn apart and turned into seven seas and six regions. More than 300 years after the cataclysm, the demons gradually awakened and extended their minions to the Seven Seas and Six Regions... By chance, the two human teenagers obtained the Peerless Pearl among the Seven Gods Pearls, giving them the ability to The ability to summon each other. And the fate of mankind is about to be rewritten!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lord El-Melloi II-sei no Jikenbo: Rail Zeppelin Grace Note Special', 'Special', 1, 'Completed', '2021-12-31', NULL, '7', 'A letter is delivered to Lord El-Melloi II informing him of a Clock Tower reunion. One morning, as the reunion''s date draws near, Lord El-Melloi II takes a look in the mirror and reels in shock. He is suddenly a full decade younger! Lord El-Melloi II has become Waver Velvet, his former self! Believing himself to be in the grip of a powerful, magically induced delusion, Lord El-Melloi II immediately begins investigating how this could have happened. On the day of the reunion, he makes his way to the gathering of his contemporaries, planning to confront whoever transformed his body and hoping to reveal their intentions. However, when Touko Aozaki arrives, things take a sudden turn...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yawara!', 'TV', 124, 'Completed', '1989-10-16', '1992-09-21', '7', 'High school student Yawara Inokuma lives a completely happy and ordinary life. She aspires to an average lifestyle as a delicate young lady with a handsome boyfriend in the near future.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xingchen Bian 3rd Season', 'ONA', 12, 'Completed', '2021-09-05', '2021-10-03', '7', 'After reuniting with his brothers Hei Yu and Hou Fei, Qin Yu sets his eyes on the Immortal Manor. As Qin Yu possesses one of the nine Jade Swords that serves as a key to the mansion, an inevitable battle ensues with the Hall of Nine Demons and various other sects vying for the key.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wangan Midnight', 'TV', 26, 'Completed', '2007-06-15', '2008-09-13', '7', 'From dusk until dawn, street racers gather on a Tokyo highway—the Wangan Route—in search of only one thing: speed. Among them, a newcomer attracts the attention of the route''s veterans after he purchases a Nissan Fairlady Z, a car infamously nicknamed The Devil Z. The newcomer ignores the warnings of Eriko Asakura, who lost her brother, Akio, in an accident involving the same vehicle. The Devil Z''s new owner, who coincidentally shares the exact same name as Eriko''s brother, becomes bewitched by the car''s mysterious power—even after crashing twice.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tasogare Otome x Amnesia: Taima Otome', 'Special', 1, 'Completed', '2012-11-28', NULL, '7', 'Tired of Yuuko''s antics for causing more ghost stories to be spread amongst the students, Kirie challenges her to a series of games which if Yuuko loses, she must behave.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shion no Ou', 'TV', 22, 'Completed', '2007-10-14', '2008-03-23', '7', 'Defying the odds, middle school student Shion Yasuoka is becoming a rising star of the professional shogi world. Despite losing her family at a young age and being unable to speak due to the trauma, in her loving adoptive family and at the shogi association, she has found the necessary emotional support to move on with her life and very demanding career.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shuumatsu no Walküre II', 'ONA', 10, 'Completed', '2023-01-26', NULL, '7', 'In a shocking turn of events, humanity has won its first battle in the Ragnarök tournament—a series of 13 fights that will decide the fate of mankind. Zeus, the head of gods, sends the demigod Heracles for the next round to avenge the humiliated Greek pantheon. To face this hero loved by gods and humans alike, the Valkyrie Brunhilde decides to use Heracles'' complete moral opposite: the infamous serial killer Jack the Ripper—leaving human beings unsure who they should support.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yami Shibai', 'TV', 13, 'Completed', '2013-07-15', '2013-09-30', '7', 'The mysterious, yellow-masked Storyteller is a man whose true name and origin are both unknown. He appears at dusk where children gather and recites sinister tales based on Japanese urban legends, to which his young audience eerily intakes. However, the Storyteller is no ordinary teller of tales. He incorporates a kamishibai, a traditional paper-scrolling device, to add visuals to his already demented narration.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Inazuma Eleven: Reloaded - Soccer no Henkaku', 'Special', 1, 'Completed', '2018-01-21', NULL, '7', 'Special prologue episode of the Inazuma Eleven: Ares no Tenbin series. It is a remake of the original Inazuma Eleven episode 27.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Watashi ga Motenai no wa Dou Kangaetemo Omaera ga Warui!', 'TV', 12, 'Completed', '2013-07-09', '2013-09-24', '7', 'After living 50 simulated high school lives and dating over 100 virtual boys, Tomoko Kuroki believes that she is ready to conquer her first year of high school. Little does she know that she is much less prepared than she would like to think. In reality, Tomoko is an introverted and awkward young girl, and she herself is the only one who doesn''t realize it! With the help of her best friend, Yuu Naruse, and the support and love of her brother Tomoki, Tomoko attempts to brave the new world of high school life.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chain Chronicle: Haecceitas no Hikari Part 3', 'Movie', 1, 'Completed', '2017-02-11', NULL, '7', 'Set in the land of Yuguto, the people thought that the land they live is the size of the world, but it’s actually divided into several areas, each with a respective king. Even though there were small wars among areas, the kings had roundtable meetings to maintain peace and balance. It was until a dark group of dark monsters appeared...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maria†Holic', 'TV', 12, 'Completed', '2009-01-05', '2009-03-23', '7', 'In search of true love, Kanako Miyamae transfers to Ame no Kisaki Catholic school, inspired by how her parents fell in love with each other there. There is just one difference, though: because men make Kanako break into hives, she has actually come to the all-girls school to find a partner of the same sex.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Super Lovers 2', 'TV', 10, 'Completed', '2017-01-12', '2017-03-16', '7', 'Second season of Super Lovers.', 879, 'https://cdn.myanimelist.net/images/anime/9/83807.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mewkledreamy', 'TV', 48, 'Completed', '2020-04-05', '2021-04-04', '7', 'The story begins when a middle school girl named Yume sees something fall from the sky, and meets a pale violet-colored kitten named Mew. It turns out that Mew has the power of "Yume Synchro" (Dream Synchro), the power to enter dreams. In the dream world, the girl and Mew collect Dream Stones. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gakkou no Kaidan: Kubinashi Rider!! Shi no Noroi', 'Special', 1, 'Completed', '2001-08-24', NULL, '7', 'A TV special of Gakkou no Kaidan that aired almost 5 months after the original anime. However, this event takes place before the Finale episode of the TV series.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yankee-kun na Yamada-kun to Megane-chan to Majo', 'Special', 1, 'Completed', '2015-08-26', NULL, '7', 'The official website for the Yamada-kun and the Seven Witches television anime series revealed on Sunday that the anime''s first Blu-ray Disc and DVD box sets will include a Yankee-kun to Megane-chan collaborative manga and anime. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Muteki Choujin Zambot 3', 'TV', 23, 'Completed', '1977-10-08', '1978-03-25', '7', 'There once existed a planet named Beal, until it was wiped out by the mysterious entity known as Gaizok. The few remaining survivors escaped to Earth and split into three families, named Jin, Kamie, and Kamikita respectively. While attempting to start a new life, the collectively known "Jin Family" prepared for the inevitable Gaizok invasion on Earth and its giant mechanical beasts known as "Mecha Boosts". In order to defend their new home, they have built three vehicles which when combined form the mighty Zambot 3. The Jin Family must not only defend against Gaizok attacks, but also harsh criticisms from the very people they protect, who blame the Jin Family for the invasion in the first place.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Inukami! The Movie: Tokumei Reiteki Sousakan Karina Shirou!', 'Movie', 1, 'Completed', '2007-04-21', NULL, '7', 'In 2007, the Punishment of Sexual Perversions Law came into effect. The city is surrounded by a squadron wearing protective suits and they begin to arrest any who look like perversions. No wonder that Inukami Master Keita and Inukami Yoko are wanted for Class A perversions. What will happen to Keita, Yoko, Kaoru''s Inukami, and the other lovely perversions? What about Karina?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ougon Yuusha Goldran', 'TV', 48, 'Completed', '1995-02-04', '1996-01-27', '7', 'Goldran follows the adventures of three young boys who are tasked with finding alien robot fighters, or Braves, that are sleeping in the form of crystals. Their major antagonist is the flamboyant and thoroughly incompetent Walter, and the villains that follow him are often similarly humorous. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kamigami no Asobi', 'TV', 12, 'Completed', '2014-04-06', '2014-06-22', '7', 'After discovering a mysterious sword in the storehouse of her home, third-year high school student Yui Kusanagi finds herself suddenly transported to a different world. While exploring her new surroundings, she meets five strange yet handsome men before coming face to face with Zeus: the king of the gods. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tongari Boushi no Memole', 'TV', 50, 'Completed', '1984-03-03', '1985-03-03', '7', 'Memoru is one of 245 people who came to earth from the Riruru Star when their ship had an emergency crash-landing on earth. Memoru''s people have such tiny bodies that they could stand on a human''s palm. One day she hears lovely music, and she follows its source and comes upon a huge house she hasn''t seen before to find a girl taller than her playing on the piano. Memoru visited her again secretly with her friends Popitu, Rupangu, and Pi, but the human girl, Marielle, seemed sick and likely to die any moment. Feeling sad for the girl, Memoru''s tear drops on the girl''s lips. The girl gets better and a strong friendship starts between them. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuusha Shirei Dagwon', 'TV', 48, 'Completed', '1996-02-03', '1997-01-25', '7', 'A huge space monster appeared in a city and began to destroy the city. People were escaping with screaming. Among them, there were five high school students, En, Kai, Shin, Yoku, and Ryu. However, they failed to escape, and they rushed into a patrol car parked nearby. The monster was approaching to them. When they began to accept their death, the patrol car glowed blue white and disappeared into a mysterious space carrying them. When they were astonished, it was an alien that appeared in front of them. He was a Bravian who is an officer of the Space Police Organization that was responsible for the peace and order of the universe. He explained them that he was aimed at by ferocious aliens in the Space Prison Sargasso. He added that he had given them a battle machine "Dag Beagle" made by copying machines on the Earth in order to fight against Sargasso.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saiyuuki (OVA)', 'OVA', 2, 'Completed', '1999-04-23', '1999-08-27', '7', 'The story of Sanzo and his three companions in their quest to the west, to stop the resurrection of Gyuumao. On the way they are fighting youkai, getting into trouble and helping the townspeople.', 1033, 'https://cdn.myanimelist.net/images/anime/10/67873.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Solty Rei: Surechigau Kimochi de, Omoi Au Kokoro de.', 'Special', 1, 'Completed', '2006-07-26', NULL, '7', 'This is a two part story that happened after Rose moved in to Roy''s apartment. During the preparations for Appreciation Day, Solty watches people in the city going about and preparing for the celebration and is confronted with a thought: what is true happiness? While trying to understand happiness and the complexity of human emotions, a young girl who has had a falling out with her mother confronts Solty and Rose asking for their help. "Love Shared" is actually the second half of "Opportunities Missed", while "Opportunities Missed" shows the entire story.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Twisted-Wonderland 1-shuunen Kinen PV', 'Special', 1, 'Completed', '2021-03-17', NULL, '7', 'The mischievous cat-like monster Grim—who attends the prestigious Night Raven College under special circumstances—relives memories of the events he has experienced and the students he has met so far in his first year of training to become an extraordinary magic user.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Daisougen no Chiisana Tenshi: Bush Baby', 'TV', 40, 'Completed', '1992-01-12', '1992-12-20', '7', 'When Jackie Rhodes, a british girl living in Kenya with her family, finds an ill animal called a Bushbaby, she adopts him, calls him Murphy and nurses him back to health. Murphy, Jackie, her family and their friends go on many adventures involving wild animals, poachers and more. But when Jackie''s father is recalled to England, Jackie must leave her life in Africa behind. However, before she can go, Jackie, Murphy and Tembo, a friend of Jackie''s father, go on one last adventure: they must cross the dangerous savannah to escape the poachers and corrupt police officers chasing them. Along the way, Jackie teaches the now domesticated Murphy to survive in the wild, so that, before she leaves, she can release him in his natural habitat.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hua Jianghu: Bu Liang Ren IV', 'ONA', 13, 'Completed', '2021-04-29', '2021-07-08', '7', 'The Ten Thousand Mountains are fraught with danger, and the journey to Raojiang is fraught with peril. What untold secrets do the mysterious Twelve Caves hold? Faced with powerful forces from all sides, can Li Xingyun and his companions escape unscathed? This enigmatic journey to Raojiang is about to begin...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jungle Book Shounen Mowgli', 'TV', 52, 'Completed', '1989-10-09', '1990-10-29', '7', 'After his parents died, Mowgli is raised by the Wolf Pack of the Seeonee Forest led by Akela and other wild animals such as Bagheera and Baloo. The young boy goes through several heartwarming, bittersweet, and life-threatening adventures as he seeks after his true purpose in life. And one of many dangers he has to face is the man-eating tiger, Shere Khan...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shakugan no Shana-tan III (Final): Final Destruction', 'Special', 2, 'Completed', '2012-01-27', '2012-05-30', '7', 'Shakugan no Shana-tan: Final Destruction specials bundled with the limited edition second and sixth volumes of the Shakugan no Shana III (Final) Blu-ray and DVD.', 436, 'https://cdn.myanimelist.net/images/anime/11/36063.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tenjou Tenge: The Ultimate Fight', 'OVA', 2, 'Completed', '2005-03-16', NULL, '7', 'Continues from where the original series left off. The characters try to settle their conflicts with each other in this 2 episode OAV. Aya confronts her sister Maya about Nagi, while Nagi receives a challenge from Mitsuomi to fight to the death. Meanwhile, Bob trains as hard as he can for the tournament. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Makai Ouji: Devils and Realist', 'TV', 12, 'Completed', '2013-07-08', '2013-09-23', '7', 'Seventeen-year-old William Twining takes pride in his lineage as well as his devotion to modern science. When he learns that his family has gone bankrupt, the pompous noble is faced with the reality that he can no longer afford his tuition or the lifestyle he is accustomed to. In a desperate search for valuables in his manor, William discovers a hidden room and accidentally summons the arrogant demon Dantalion, the Grand Duke of Hell.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Futari wa Precure: Max Heart', 'TV', 47, 'Completed', '2005-02-06', '2006-01-29', '7', 'Shortly after the fall of the Wicked King, the Queen of the Garden of Light lost her memory and came to Earth, in the form of a 12-year-old girl named Hikari Kujou. Now, she—with the help of Nagisa and Honoka, endowed with new costumes and powers—must find the 12 Heartiels, which hold the key to restoring the Queen''s lost memories. For together once again, they are Pretty Cure.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Keikenzumi na Kimi to, Keiken Zero na Ore ga, Otsukiai suru Hanashi.', 'TV', 12, 'Completed', '2023-10-06', '2023-12-22', '7', 'To the shy and reclusive Ryuuto Kashima, associating himself with his popular classmate Runa Shirakawa is nothing but a distant fantasy—or so he thought. After losing a bet with his friends and being coerced into confessing to Runa, Ryuuto''s world is flipped upside down: instead of the cruel rejection he was expecting, Runa agrees to go out with him!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bastard!! Ankoku no Hakaishin Part 2 (ONA)', 'ONA', 11, 'Completed', '2022-09-15', NULL, '7', 'Despite being betrayed by two members of the Four Divine Kings, the army of Kall-Su and Abigail continues its advance against the Metallicana Kingdom with the intent to unleash the god of destruction, Anthrasax. As Gara and Nei Arshes lead a brave counter-offensive against Abigail''s innumerable army of undead soldiers, they appear powerless against army commander Lynch, who wields one of the Three Demonic Treasures, Demon-Mail. Meanwhile, Yoko Tia Noto tries to revive the savior of Metallicana, Dark Schneider, in hopes that he will be able to thwart Kall-Su and Abigail''s grim plans.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rinne no Lagrange: Kamogawa Days', 'OVA', 1, 'Completed', '2012-06-23', NULL, '7', 'As Yoko has her assistant scour the seabed in search of something, Madoka, unable to pilot Midori properly again, returns to Kamogawa to see the New Year in. Upon returning home, Madoka receives New Year''s letters from Lan and Muginami, updating her about what''s going on in their lives, to which Madoka makes a prompt reply. As the months pass by and Madoka moves up a year in school, Lan and Muginami visit an intergalactic replica of Kamogawa on the tourist planet Polyhedron.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Utawarerumono: Tusukuru-koujo no Karei Naru Hibi', 'OVA', 1, 'Completed', '2018-04-26', NULL, '7', 'Included with the premium collection release of the PS4 remake of Utawarerumono: Chiriyukumono e no Komoriuta. The anime will tell the story of Kuon''s childhood days. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Macross Δ Movie: Gekijou no Walküre', 'Movie', 1, 'Completed', '2018-02-09', NULL, '7', 'The movie recompiles scenes from the Macross Δ television anime with new scenes to tell a different story.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shining Star', 'TV', 52, 'Completed', '2017-10-16', '2018-12-03', '7', 'At the prestigious Shining Star School, every girl dreams of becoming the best idol, called "Muse". Nara, an ordinary girl, decides to attend the school in order to fulfill her dream.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Masamune-kun no Revenge', 'TV', 12, 'Completed', '2017-01-05', '2017-03-23', '7', 'When Masamune Makabe was a child, he was rejected by a rich, beautiful girl named Aki Adagaki, who gave him the nickname ''''Piggy'''' for being overweight. Devastated, Masamune put great effort into working out to improve his appearance. Now a handsome yet narcissistic high school student, Masamune is determined to exact revenge—he will have Aki fall madly in love with him and ultimately reject her the next time they meet.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bananya', 'TV', 13, 'Completed', '2016-07-04', '2016-09-26', '7', 'Above a nondescript kitchen counter quietly hangs a bunch of ripe, yellow bananas. Suddenly, one of the slender fruits begins to shake, gently at first but slowly increasing in ferocity until it tears itself away from the rest. With a graceful landing, the long and curvy edible gradually rolls back its golden peels, revealing what lies beneath its firm covering to be something unexpected: a cat!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Garo: Honoo no Kokuin - Home', 'Special', 1, 'Completed', '2015-09-16', NULL, '7', 'Unaired episode included in the eighth Blu-ray and DVD volume.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Digimon Adventure: 20-shuunen Memorial Story', 'ONA', 5, 'Completed', '2019-11-22', '2020-12-25', '7', 'A crowdfunding campaign opened for the "Digimon Adventure Memorial Story Project." It was for 5 shorts that included a prequel of the upcoming film and side stories about the daily lives of the Digimon characters and their partners, which are stories that did not make it into the film. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tobidasu PriPara: Mi~nna de Mezase! Idol☆Grand Prix', 'Movie', 1, 'Completed', '2015-10-24', NULL, '7', 'The 2nd PriPara film, unlike the first this shown in stereoscopic 3D.', 2, 'https://cdn.myanimelist.net/images/anime/5/75800.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Itoshi no Muco', 'TV', 25, 'Completed', '2015-10-03', '2016-03-26', '7', 'Muco is the sweetest, most lovable dog in the neighborhood. This sparkly-nosed Shiba Inu lives with her owner and best friend, Komatsu, a glassblower who lives in the mountains. These two companions have wonderful adventures, from going on walks to playing in the pond in front of their house. No matter where they go or what they do, Muco will always love her best friend Komatsu!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shinmai Maou no Testament Burst: Toujou Basara no Shigoku Heiwa na Nichijou', 'OVA', 1, 'Completed', '2016-01-26', NULL, '7', 'An OVA that will be bundled with the seventh volume of the Shinmai Maou no Testament manga, to be released January 2016.', 705, 'https://cdn.myanimelist.net/images/anime/1568/95614.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Buzzer Beater 2nd Season', 'TV', 13, 'Completed', '2007-07-04', '2007-09-26', '7', 'After being drafted into the Earth Team, a basketball team comprised solely of humans, street-punk-turned-pro Hideyoshi couldn''t be more cocky. The team is still up against the Gorons, a physically superior race of aliens who have dominated the game for some time. New challenges and problems stand in their way. Hideyoshi is unhappy with the team and the Gorons have new tricks up their sleeves.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Ace wo Nerae!', 'TV', 25, 'Completed', '1978-10-14', '1979-03-31', '7', 'Heroine, Hiromi Oka, has just entered a high school famous for its tennis club. She has started playing tennis yearning after Madam Butterfly. She was expecting to enjoy playing tennis with her best friend, Maki, but the situation changes when the new coach, Mr. Munakata, suddenly picks out Hiromi to be one of the players for the upcoming tournament and starts giving Hiromi tough lessons. She strives under any circumstance. The more the new coach gives her training, the better she seems to get. Finally she becomes the representative in the junior match tournament.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kono Danshi, Sekka ni Nayandemasu.', 'OVA', 1, 'Completed', '2014-12-03', NULL, '7', 'Ayumu Tamari suffers from a condition known as "Crystallization Syndrome." In moments of high stress, parts of his body begin to crystallize and become extremely difficult to move. Unfortunately, Ayumu''s severe social anxiety makes him completely unable to speak to anyone in his class, and ultimately causes him to crystallize so frequently that he has to repeat a year in high school.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchuu Senkan Yamato 2199: Tsuioku no Koukai', 'Special', 1, 'Completed', '2014-10-11', NULL, '7', 'Recap of Uchuu Senkan Yamato 2199.', 1117, 'https://cdn.myanimelist.net/images/anime/11/62689.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Deatte 5-byou de Battle', 'TV', 12, 'Completed', '2021-07-13', '2021-09-28', '7', 'It was just a usual morning.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sankaku Mado no Sotogawa wa Yoru', 'TV', 12, 'Completed', '2021-10-03', '2021-12-19', '7', 'Kousuke Mikado has been able to see spirits for as long as he can remember. Extremely terrified of them, he tries to suppress his ability by wearing glasses. One day, while working at a bookstore, he catches the attention of Rihito Hiyakawa, an eccentric medium who is convinced that they were destined to meet each other.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Imanara Maniau! Log Horizon', 'Special', 1, 'Completed', '2013-11-11', NULL, '7', 'Recap of the first six episodes of Log Horizon, aired between episode 6-7.', 780, 'https://cdn.myanimelist.net/images/anime/1917/122380.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuusha ni Narenakatta Ore wa Shibushibu Shuushoku wo Ketsui Shimashita. OVA', 'OVA', 1, 'Completed', '2014-03-07', NULL, '7', 'Raul''s sister has come all the way from Raul''s home village to see her brother who has "become a hero." Raul and his fellow co-workers think its a better idea to trick his sister to thinking Raul is a real hero.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Candy Boy: Nonchalant Talk of the Certain Twin Sisters in Daily Life', 'ONA', 7, 'Completed', '2008-05-02', '2009-05-08', '7', 'Yukino and Kanade Sakurai are twin sisters that live together in a high school dorm. Although they are twins, they tend to act romantic toward each other, holding hands and going on dates. One day, Kanade sees Yukino hanging out with a new girl, Sakuya Kamiyama. Realizing how much time these two spend together, Kanade assumes they are dating, and she begins to distance herself from her sister. Yukino promptly notices and pleads with Kanade not to leave. In reality, Sakuya has only been asking for advice about Kanade, revealing her obsessive love. How will this love triangle play out?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Happy Sugar Life', 'TV', 12, 'Completed', '2018-07-14', '2018-09-29', '7', 'Satou Matsuzaka is a beautiful high schooler who has a reputation for being permissive with men. However, a chance encounter with a young girl named Shio Koube makes Satou realize that this is her first and only true feeling of love.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blue Seed Omake', 'Special', 14, 'Completed', '1995-01-21', '1996-06-21', '7', 'Extra bits meant to add to the Blue Seed story.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Calimero', 'TV', 52, 'Completed', '1992-10-15', '1993-09-09', '6', 'The series tells about many adventures of the small fledgling Calimero and his friends, who uncover many secrets, sometimes getting into trouble along the way.', 1087, 'https://cdn.myanimelist.net/images/anime/12/61017.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tenkuu Senki Shurato Recaps', 'Special', 2, 'Completed', '1989-12-07', '1990-01-25', '6', 'Recaps of the original show. Also known as "Episode 32.5" and "Episode 39".', 1009, 'https://cdn.myanimelist.net/images/anime/1314/147683.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Super Bikkuriman', 'TV', 44, 'Completed', '1992-05-17', '1993-04-04', '6', 'After of the big war between angels and demons, the Earth is almost destroyed and his cities devastated. Wanted to restore the peace and the harmony, four young child decides to fight against the army of evil that rules the world for to eradicate to the Earth and give them back to hell. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Neko Machi', 'OVA', 1, 'Completed', '2006-08-01', NULL, '6', 'A fantasy world with only cats as far as the eye can see. The awe and fear a person can feel in a world that doesn’t know mankind, the world of Cat City invented by HAGIWARA Sakutaro, is depicted with sense by the art of KANAIDA Etsuko. The commercial editor URAHAMA Shojiro edits the story narrated by the musician and poet MACHIDA Kou with a taste of fantastic for this new Ga-nime. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('A Piece of Phantasmagoria', 'OVA', 15, 'Completed', '1995-01-01', NULL, '6', 'A collection of 15 short episodes depicting the magic world of Phantasmagoria.', 712, 'https://cdn.myanimelist.net/images/anime/1577/92716.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('An Jie Shen Shi', 'ONA', 22, 'Completed', '2020-12-25', '2021-05-21', '6', 'In order to find the missing friend Xiao Yuan, the protagonist, Jiang Yao, sneaked into an abandoned villa to investigate, but was caught by a mysterious black shadow by accident and almost doomed. However, this was only the beginning of his bad luck. Behind the chain of events, Jiang Yao gradually realized that he was following him as a person who "shouldn''t exist". The shadowy crisis, the truth about the disappearance of his friends, the hidden organization of the dark world... Behind the bizarre incident, a conspiracy that spans a thousand years has quietly awakened, and the battle between righteous and evil is about to begin. The animation incorporates suspense, adventure, inspiration and other elements, presenting the audience a struggle story of self-improvement and positive energy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('God Mazinger', 'TV', 23, 'Completed', '1984-04-05', '1984-10-23', '6', 'In the ancient, legendary past, the peaceful kingdom of Mu is under siege by the war-like Dragonian Empire. With a woeful amount of fire power and only a giant statue of a deity to watch over them, the young Queen Aira and her people are no match for the Dorado, the Golden King,and his army of dinosaurs.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kujibiki♥Unbalance', 'TV', 12, 'Completed', '2006-10-07', '2006-12-23', '6', 'Once a year prestigious Rikkyouin High School has a lottery to determine the next year''s Student Council membership. On their first day of school Chihiro Enomoto wins the presidency while his childhood friend Tokino Akiyama picks the vice-president''s ticket. There is one catch though, they must first pass a one year apprenticeship under the current Student Council and any failure to perform the tasks assigned, however minor, will result in immediate expulsion from the school.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koukaku Kidoutai Arise: Ghost in the Shell - Logicoma Specials', 'Special', 4, 'Completed', '2013-07-26', '2014-09-24', '6', 'Short 3D CG Specials included in the Blu-rays of the Ghost in the Shell: Arise movies.', 704, 'https://cdn.myanimelist.net/images/anime/10/57657.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Topo Gigio', 'TV', 21, 'Completed', '1988-04-27', '1988-09-21', '6', 'Created by Maria Perego, Topo Gigio has been a beloved character for more than two decades. This animated TV series features numerous exciting stories and introduces many friends.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuiba Zhi Shu Tu', 'ONA', 7, 'Completed', '2021-01-17', '2021-02-21', '6', 'The story takes place in Lingshan, where a group of "hopeless" people are gathered on the earth. Most of them are poor, vicious, or extremely evil, abandoned by the society in Lingshan. This is where the fourth generation of Kuiba Mi Lin was born. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kinnikuman (Movie)', 'Movie', 1, 'Completed', '1984-07-14', NULL, '6', 'Mari and Kinnikuman''s Championship Belt are stolen by the Octopus Dragon and his minions. Now Kinnikuman and the other Justice Choujins must travel to Planet Metro and compete in a tournament in order to win them back.', 1030, 'https://cdn.myanimelist.net/images/anime/1457/98817.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gakkatsu! 2nd Season', 'TV', 25, 'Completed', '2013-01-16', '2013-09-25', '6', '2nd season of Gakkatsu!.', 281, 'https://cdn.myanimelist.net/images/anime/13/46063.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boukensha: The Man Was from Spain', 'TV', 26, 'Completed', '1992-11-28', '1993-03-30', '6', 'Christopher Columbus is a man of strong will. His life is full of drama.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Quest: Dai no Daibouken (2020): Bouken no Kiseki, Kore kara no Tabiji', 'Special', 1, 'Completed', '2021-06-26', NULL, '6', 'Recap of first 37 episodes of Dragon Quest: Dai no Daibouken (2020) to look back on Dai''s Adventure so far.', 1030, 'https://cdn.myanimelist.net/images/anime/1762/116118.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kasumin 3rd Season', 'TV', 26, 'Completed', '2003-04-09', '2003-10-01', '6', 'Kasumi Haruno is a fourth grade student. She came to Kasumi Town to see off her zoologist parents on their trip to Africa to do research. In the center of the town, surrounded by forest, is the large mansion belonging to the Kasumi family where Kasumi will be staying from now on.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Thermae Romae x Yoyogi Animation Gakuin Collaboration', 'Special', 1, 'Completed', '2012-07-09', NULL, '6', 'Lucius ends up at Yoyogi Animation Academy, where he experiences a guided tour of the academy, learning various aspects of animation along such as moe and after-recording along the way.', 214, 'https://cdn.myanimelist.net/images/anime/8/38659.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tanpen Unico: Kuroi Kumo to Shiroi Hane', 'OVA', 1, 'Completed', '1979-04-05', NULL, '6', 'The Goddess Venus is jealous of the beautiful human girl Psyche and blames her pet unicorn, Unico, as Psyche''s source of good luck that keeps her from the harm of the goddess'' cruel intentions. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rifle Is Beautiful', 'TV', 12, 'Completed', '2019-10-13', '2020-01-18', '6', 'Rifle-shooting sports are competitive activities testing accuracy and precision using a rifle. In Japan, carrying firearms is prohibited, so most of the participants are members of the defense force. When the use of rifles using a light beam instead of real bullets as ammunition became common, rifle-shooting competitions became accessible to the younger population, giving way to school contests.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Choujuu Kishin Dancougar: Ushinawareta Mono-tachi e no Requiem', 'OVA', 1, 'Completed', '1986-04-21', NULL, '6', 'The Dancouga team prepares for its final showdown with their arch-enemy Zorbados. The team has to travel to the strange dimension of the alien invaders to once and for all save the earth. Fighting on the home-grounds of the enemy will take all their strength and cunning. The Dancouga will have to fight its way to the strange alien red dimension before it can start its final assault and assure the safety of mankind forever. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seraphim Call', 'TV', 12, 'Completed', '1999-10-06', '1999-12-22', '6', 'What''s it like to feel like an average girl in everything.​.. except for your one special gift.​ Eleven young hearts with eleven dreams.​ Deep in their hearts,​ each girl has a secret dream of love and sadness.​ They meet together at Acropolis Tower to see if their dreams will come true.​ Imagine what happens when eleven average girls with eleven special talents join together to make the world a better place!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sengoku Choujuu Giga: Kou', 'TV', 13, 'Completed', '2016-10-09', '2017-01-08', '6', 'The history, either daily life or life stories of Sengoku warriors, is described using animals. We invite popular young actors and unique casts to voice out those Sengoku warriors while joking about them. An anime that teases Japan''s history and Sengoku warriors; that''s "Sengoku Choujuu Giga."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Puzzle & Dragons CMs', 'Special', 2, 'Completed', '2015-10-12', '2016-01-24', '6', 'Studio Colorido has created a short, animated commercial for the GungHo Online Entertainment''s popular mobile game, Puzzles &amp; Dragons.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hortensia Saga', 'TV', 12, 'Completed', '2021-01-07', '2021-03-25', '6', 'A violent rebellion in the capital led by Duke Rugis Camellia wreaks havoc on the Kingdom of Hortensia, leaving every member of the royalty either dead or missing. Barely escaping with his life, knight Maurice Baudelaire flees the ensuing chaos after his brother, Fernando Albert, is killed by a werewolf in battle. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chouon Senshi Borgman: Madnight☆Gigs!', 'OVA', 1, 'Completed', '1989-02-08', NULL, '6', 'A music clip OVA using full versions of songs that were from the anime. While most of the OVA is re-purposed footage from the original show, this release does contain footage that never aired previously showing some events that occurred after the final episode.', 92, 'https://cdn.myanimelist.net/images/anime/3/73416.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Majutsushi Orphen Hagure Tabi', 'TV', 13, 'Completed', '2020-01-07', '2020-03-31', '6', 'In a world of magic and monsters, Krylancelo Finrandi and his foster sister Azalie Cait-Sith were once promising students of sorcery, prodigies at the famous Tower of Fangs. But an experiment gone horribly wrong warps Azalie''s appearance, trapping her in the form of a dragon.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shukufuku no Campanella Specials', 'Special', 6, 'Completed', '2010-09-22', '2011-02-24', '6', 'Short extra anime "Isshoni Bath Time". The main characters taking a bath will be displayed three dimensionally on 3D TV. Normal 2D versions are also available.', 25, 'https://cdn.myanimelist.net/images/anime/2/25404.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi SD Gundam Matsuri', 'Movie', 1, 'Completed', '1993-03-13', NULL, '6', 'The movie is divided into 3 different parts:
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bouken-tachi Gamba to Nanbiki no Nakama', 'Movie', 1, 'Completed', '1984-03-04', NULL, '6', 'When a badly injured mouse staggers off a ship in Tokyo Harbor, he tells the local mice that he has escaped from Devil''s Island, where Noroi, the evil white weasel, has crushed the mice with his reign of terror. Tough-guy Gamba rashly promises to help depose Noroi.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gegege no Kitarou: Chisougan', 'Movie', 1, 'Completed', '1980-07-12', NULL, '6', 'An abbreviated 12 minute version of episode 37 from the 1971 TV anime. This was shown as part of the summer 1980 Toei Manga Matsuri and uses entirely recycled footage.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchuu Ace', 'TV', 52, 'Completed', '1965-05-08', '1966-04-28', '6', 'Dr. Tatsunoko of Tatsunoko Research Center goes undersea accompanied by his daughter Asari to inquire into some mysterious radiation and discovers there a giant shell and it is known that the radiation comes from a globe laid inside the shell. Then Asari finds an object in the shape of compact with a message in it. It says that a space alien from the Planet of Parlum which is on the verge of extinction is lying in the globe. Suddenly a boy with a strange look appears out of the globe and goes wild. He is the very person mentioned in the message with the name of Ace. His source of energy for superhuman power is what is called space food and he can fly with the help of Silver Ring made with energy collected instantly in the aerial environment. Also he is able to use it as a weapon to fight the enemy with. Supported by his friends including Asari, Ibo the robot dog, and Hermit Crab Reporter, he gallantly goes into action to settle various difficulties caused by mystic robots and brutal space invaders.', 1009, 'https://cdn.myanimelist.net/images/anime/2/83908.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Time Bokan Series: Zenderman', 'TV', 52, 'Completed', '1979-02-03', '1980-01-26', '6', 'Dr Monja is a scientist who is curious about the nature of the legendary Elixir of Life which grants the drink eternal lifetimes and forever youth. He built a device called the "Time Tunnel" in order to let a team of youngsters to start a quest down the timeline and various spaces to find an exact answer. A trio of villains, however, is also seemingly after the exact same thing.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('High School Jingi', 'OVA', 1, 'Completed', '1992-02-10', NULL, '6', 'The impulsive Yakuza Jouji was ordered by his boss to teach at a misfit-filled school. He now has to settle the score with a fated rival while falling head over heels for a colleague in the process.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Komatsu Sakyou Anime Gekijou', 'TV', 24, 'Completed', '1989-10-19', '1990-03-29', '6', 'The collection of short SF stories.', 321, 'https://cdn.myanimelist.net/images/anime/7/61619.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Adachi to Shimamura Mini Anime', 'ONA', 30, 'Completed', '2020-09-11', '2021-03-02', '6', 'Short episodes with super-deformed characters posted on the official Twitter account.', 1021, 'https://cdn.myanimelist.net/images/anime/1865/113847.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zettai Yareru Greece Shinwa', 'TV', 13, 'Completed', '2008-10-04', '2008-12-27', '6', 'Comedy show based on Greek myths about how perverted the gods are.', 14, 'https://cdn.myanimelist.net/images/anime/3/53619.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Urikupen Kyuujo-tai', 'TV', 156, 'Completed', '1974-09-30', '1975-03-29', '6', 'Four young animals, rabbit Seitaro Usagi, squirrel Risu, bear Kuma, and penguin Penguin (U-Ri-Ku-Pen), are part of a team of brave young animals that rescues others in peril. Other team members included a dog, a boar, a deer, a koala, a mouse, a seagull, and a lion. The animals would win a prize for completing a mission, as would the viewers, who were encouraged to write in and guess which of the creatures would save the world by each Friday (a single mission stretched over a week of TV). Created by Mitsuru Kaneko, this show was given a limited broadcast on some American local TV stations for the Japanese community.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nissan Note x The World of Golden Eggs', 'Special', 5, 'Completed', '2008-01-16', '2008-10-08', '5', 'Animated TV commercials for the Nissan Note featuring the cast from The World of Golden Eggs. The commercials were also released on a limited number of DVDs that were given away to test drivers of the Note.', 873, 'https://cdn.myanimelist.net/images/anime/1278/108906.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Arei no Kagami: Way to the Virgin Space', 'Movie', 1, 'Completed', '1985-03-16', NULL, '5', 'The story follows Daichi Meguru and Mayu, a young boy and a pilot, as they flee their war torn planet and into space. Upon their ship a stowaway android named Zero joins their quest as they travel through Halley''s Mirror.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Techno Police 21C', 'Movie', 1, 'Completed', '1982-08-07', NULL, '5', 'The plot consists of a chase of a hijacked MBT-99A tank, designed by the United States Air Force (which is odd, but will become the saviour of Eleanor, as she can be ejected before the tank explodes, like a fighter jet). The audience is expected to be enamored with this vehicle. At one scene when it looks like the tank is sure to get away, the background music turns into cocktail-lounge jazz and sparkly lights swirl around the tank. The tank carries six ATGM launchers (which Ken is somehow able to dislodge with minimal trouble, along with a piece of the turret, towards the end of the movie), three to each side of the turret, and a laser-based machine-gun-esque installment, in addition to its rifled main gun. The tank''s treads are dual-mounted (the tread is split in half, making four sets of treads for the tank).
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Listeners', 'TV', 12, 'Completed', '2020-04-04', '2020-06-20', '5', 'Set in a world where the concept of music ceases to exist. The story begins when a boy encounters Myuu, a mysterious girl who possesses an audio input jack in her body. The two intermingle with the history of rock music and embark on an unforgettable journey.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Makyou Gaiden Le Deus', 'OVA', 1, 'Completed', '1987-12-01', NULL, '5', 'In a post-apocalyptic world, the treasure hunter Riot and his pretty sidekicks are searching for Eyes of Zalem, which they hope will guide them to Rido, the treasure of a long-lost Quall civilization. A limitless energy source, the Rido has the power to even restore life; but unfortunately for Riot, the evil Demsters are after it too. (from ANN)', 92, 'https://cdn.myanimelist.net/images/anime/1449/96410.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ariel Visual', 'OVA', 2, 'Completed', '1989-07-21', '1989-08-21', '5', 'To save the Earth from alien invaders and their giant monsters, Dr. Kishida does what any other red-blooded mad scientist would do: he builds a giant robot—the ultimate feminine fighting robot!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tokyo Gambo', 'TV', 5, 'Completed', '2020-11-22', '2020-12-20', '5', 'The story will take place 100 years after the world was destroyed in the 21st century due to environmental destruction and depletion of resources. The story follows four girls who work at PARK, based on a real store in Harajuku that follows the theme of "Fashion × Otaku × Creation."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Prayers', 'OVA', 2, 'Completed', '2005-08-26', '2005-11-25', '5', 'It is the year of 2014, Shibuya is independent from Japan, and it becomes an independent nation. It is a town of chaos where only young people are living. The life necessity, such as electricity, water, and food are transported by the pipelines out from the Shibuya. The pipelines are running like cobweb in the sky, the young people in Shibuya looked like bugs trapped in the cobweb.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('SD Gundam Force', 'TV', 52, 'Completed', '2004-01-07', '2004-12-29', '5', 'The land of Neotopia is attacked by the Dark Axis, evil invaders from another dimension who wish to conquer this land. Neotopia''s answer: the secret Super Dimensional Guard and their defenders, the Gundam Force. Led by Captain Gundam, the Gundam Force and its team of Gundams with special abilities are aided by a boy named Shute as they stop at nothing to defend the land from the Dark Axis and to defeat them once and for all. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyoukasho ni Nai!', 'OVA', 2, 'Completed', '1998-04-21', '1998-05-21', '5', 'Oraku is a lucky man. He has a comfortable job teaching at a local High School. He has Satsuki, a fellow teacher whom he hopes to marry someday. He has Aya, a beautiful student who has fallen in love with him. He has Aya''s father, a wealthy man who wants so much for his little girl to be happy that he has sent her to live with Oraku. Oraku is a very lucky man.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gundress', 'Movie', 1, 'Completed', '1999-03-20', NULL, '5', 'In 2100, the newly built Bayside City serves as Japan''s premier international port. The Angel Arms Company is established by a former policewoman named Takako, to help wage war on terrorism with armed security suits. When the mayor is assassinated, the women of Angel Arms end up protecting the evil crime-lord Hassan, in hopes that his information will help bring down a global terror ring. Takako''s back is to the wall as a band of criminals plot to kill Hassan, and the organization''s leader is revealed to be the former lover of Angel Arms'' own Alisa.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('D-1 Devastator', 'OVA', 2, 'Completed', '1992-12-11', '1993-02-26', '5', 'To follow in his missing friend Masato''s footsteps, Ryo joined the vehicle company Yaesu. Ryo became involved with the Makuhari test course that Masato was also a part of. The leader, Gray Gear, told Ryo, "If you want to know about Masato, come to the test course late at night and ride the new machine."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gekkan Mousou Kagaku', 'TV', 12, 'Completed', '2024-01-11', '2024-03-28', '5', 'Gekkan Mousou Kagaku is set in Most City in an unknown country in a small publishing house that prints a monthly magazine about the most outlandish of things. Everything changes when the staff of the magazine, editor-in-chief Tarou, his assistant Jirou and dog Saburou, meet with scientist Gorou Satou...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eternity', 'Movie', 1, 'Completed', '2022-12-10', NULL, '5', 'A 21-minute journey through space that repeats creation and expansion.', 573, 'https://cdn.myanimelist.net/images/anime/1003/134010.jpg');
