INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hero Inside', 'TV', 11, 'Completed', '2023-11-08', '2024-01-21', '5', 'Heroes can pop out of their comic books when summoned in this comedic action-adventure.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaji to Kouma', 'Movie', 1, 'Completed', '1978-01-01', NULL, '5', 'A fire safety video meant as a teaching aid for schools. Not much is known about this film except that Yoshikazu Yasuhiko did the character designs as it was mentioned in on page 117 of the "Yoshikazu Yasuhiko Design Notes" booklet published as an add-on to the December issue of Animage no. 56.', 90, 'https://cdn.myanimelist.net/images/anime/1908/112081.jpg');
