INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ghost Tale', 'ONA', 1, 'Completed', '2023-10-31', NULL, '6', 'Su and Uh use the power of telekinesis to impress Lah by lifting up objects. Lah then tries to use telekinesis, too, but lacks this power, so Su and Uh help her.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ongaku Shoujo', 'Movie', 1, 'Completed', '2015-03-22', NULL, '6', 'On her way to her first day of high school, Eri Kumagai is captivated by a girl''s singing. Her song is beautiful but ends abruptly when the girl steps on a cat''s tail and disrupts the moment. Eri pushes this out of her mind until that same girl rushes into her class late, cat in hand, and claims that the name on the attendance list—Chiharu Yuzuka—is her "false name" and she is actually called Haru Chitose.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tamayura: More Aggressive Picture Drama', 'Special', 1, 'Completed', '2013-10-30', NULL, '6', 'Picture drama included in the 1st Blu-ray and DVD volumes.', 999, 'https://cdn.myanimelist.net/images/anime/5/64405.jpg');
