INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Annyeong Jadoo', 'TV', 122, 'Completed', '2011-07-18', '2016-02-01', '6', 'Hello Jadoo is a South-Korean TV show about a girl named Choi Jadoo who is a very free-spirited girl. In every episode, she would always get into drama, whether it was with her parents or school. At the same time, she meets new people and she tries to solve problems occurring.', 97, 'https://cdn.myanimelist.net/images/anime/8/86812.jpg');
