INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hashire Melos (1981)', 'Special', 1, 'Completed', '1981-02-07', NULL, '5', 'Melos, a Greek country man gets arrested accused of conspiracy against the king. The king gives him three days to travel to his sister''s wedding while Selinentius the sculptor and friend of Melos stays as a hostage. Will he get back in time before the king executes Selinentius instead of him?', 1030, 'https://cdn.myanimelist.net/images/anime/4/76807.jpg');
