INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aladdin to Mahou no Lamp no Koutsuu Anzen', 'OVA', 1, 'Completed', '2011-01-01', NULL, '5', 'An educational film about traffic safety staring Aladdin and the Genie from the magic lamp.', 1030, 'https://cdn.myanimelist.net/images/anime/9/74433.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tobidashi wa Abunaizo! Mushimushi Mura no Koutsuu Anzen', 'OVA', 1, 'Completed', '2012-01-01', NULL, '5', 'An educational film about traffic safety starring insects. This film talks about more advanced traffic safety rules.', 1030, 'https://cdn.myanimelist.net/images/anime/11/74432.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hanakappa no Koutsuu Anzen: Cake wo Momomete Migi, Hidari, Migi', 'OVA', 1, 'Completed', '2010-01-01', NULL, '5', 'An educational film about traffic safety staring Hanakappa.', 1030, 'https://cdn.myanimelist.net/images/anime/13/74431.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Deban desu yo! Onigirizu', 'TV', 6, 'Completed', '2015-06-01', '2015-10-31', '5', 'A short series created to commemorate the 25th anniversary of the NECO broadcast channel. It focuses on the backstage chatter and concerts of a band called Onigirizu.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boo Boo Boy', 'TV', 26, 'Completed', '2015-07-04', '2015-12-26', '5', 'A young boy has adventures with his transforming car.', 214, 'https://cdn.myanimelist.net/images/anime/5/79707.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tennis no Oujisama', 'TV', 178, 'Completed', '2001-10-10', '2005-03-23', '8', 'At the request of his father, tennis prodigy Ryouma Echizen has returned from America and is ready to take the Japanese tennis scene by storm. Aiming to become the best tennis player in the country, he enrolls in Seishun Academy—home to one of the best middle school tennis teams in Japan. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zhu Xian 3rd Season', 'ONA', 26, 'Completed', '2025-06-12', '2025-10-01', '8', 'The Beast God is born, blood bathing the world, Daoxuan stands up to fight, the forces of good and evil usher in a huge change, Gui Li and Xueqi once again stand at the intersection of fate. After the catastrophe, people''s hearts and artifacts are both on the verge of being shattered...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('You Shou Yan 3rd Season', 'ONA', 12, 'Completed', '2024-05-17', '2024-07-26', '8', '', 284, 'https://cdn.myanimelist.net/images/anime/1102/142342.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Giji Harem', 'TV', 12, 'Completed', '2024-07-05', '2024-09-20', '8', 'Eiji Kitahama has a dream shared by many high school guys: to be popular and have a harem of girls fawning over him. Luckily for him, his new junior in the drama club, Rin Nanakura, has decided to help him realize this wish. Using her impressive acting abilities, she takes on many personalities, from teasing to calm and collected, to play characters in Eiji''s simulated harem.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wan Sheng Jie 4', 'ONA', 12, 'Completed', '2023-07-05', '2023-07-15', '8', 'Fourth season of Wan Sheng Jie.', 284, 'https://cdn.myanimelist.net/images/anime/1567/137044.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Trigun Stampede', 'TV', 12, 'Completed', '2023-01-07', '2023-03-25', '8', 'On the planet Noman''s Land, reporters Meryl Stryfe and Roberto De Niro traverse the desert in search of the infamous outlaw Vash the Stampede. But the man they find near the desolate town of Jeneora Rock is a far cry from the lethal terrorist they expect. In reality, Vash is a passive and carefree drifter; he is a proponent of peace, beloved by the residents of the town. His inaccurate reputation actually stems from the widespread atrocities committed by his twin brother Millions Knives. Still, Vash is dubbed "The Humanoid Typhoon'''' due to the tendency for violent chaos to follow in his wake.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hanasaku Iroha Movie: Home Sweet Home', 'Movie', 1, 'Completed', '2013-03-09', NULL, '8', 'Ohana Matsumae has been working at Kissui Inn as a waitress for a while now. However, she realizes that she is starting to lose her desire to sparkle, having grown accustomed to the routines of her job. As this was a desire she had when she first moved to the inn, the realization bothers her. While having Yuina Wakura—Ohana''s classmate, friend, and the daughter of rival Fukuya Inn''s owner—under her as an apprentice, Ohana stumbles upon some old archives that mention her mother, Satsuki. Ohana does not know much about her mother, but these archives could shed some light on her past.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Owarimonogatari 2nd Season Recaps', 'Special', 2, 'Completed', '2017-08-12', '2017-08-13', '8', 'Two recaps aired before the first episode of the day at the time Owarimonogatari 2nd Season was airing.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuroko no Basket Movie 3: Winter Cup - Tobira no Mukou', 'Movie', 1, 'Completed', '2016-12-03', NULL, '8', 'The Winter Cup finals have arrived, and the Seirin High School basketball team braces itself for the game against its indomitable opponent, Rakuzan High School. With the former Generation of Miracles leader Seijuurou Akashi as their captain, Rakuzan has established itself as the unyielding emperor of the court. Akashi''s innate ability, known as the Emperor Eye, allows him to predict his enemies'' next move and meticulously dismantle each play, further cementing his absolute authority over the court. Seirin''s "light and shadow" duo, Taiga Kagami and Tetsuya Kuroko, now find themselves given the ultimate test of teamwork in which they must play with the strongest synergy possible to break through Akashi''s omniscience. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Durarara!! Specials', 'Special', 2, 'Completed', '2010-08-25', '2011-02-23', '8', 'Celty Sturluson is tasked to deliver a suspicious red handbag as part of her courier duties—the problem is: it is being sought by several organizations. As she makes her way through Ikebukuro toward the place the bag is supposed to be brought to, she is chased by mysterious men speaking a foreign language, and her package ends up dragging many of the city''s residents into the conflict.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shingeki no Kyojin: Lost Girls', 'OVA', 3, 'Completed', '2017-12-08', '2018-08-09', '8', 'Wall Sina, Goodbye
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hidamari Sketch x 365', 'TV', 13, 'Completed', '2008-07-04', '2008-09-26', '8', 'After passing her entrance exam, Yuno enrolls at Yamabuki High School as part of an art degree. She stays at the Hidamari Apartments along with best friend Miyako, and seniors Hiro and Sae. Each episode follows a day in her life as she mingles with her friends, close peers, overly hyper teachers and closely follows the mundane lives of the high school girls.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tentai Senshi Sunred 2nd Season', 'TV', 26, 'Completed', '2009-10-03', '2010-03-27', '8', 'The second season of Tentai Senshi Sunred.', 26, 'https://cdn.myanimelist.net/images/anime/7/15051.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kono Subarashii Sekai ni Shukufuku wo!: Kono Subarashii Choker ni Shukufuku wo!', 'OVA', 1, 'Completed', '2016-06-24', NULL, '8', 'While exploring Wiz''s magic shop with his party, Kazuma Satou finds a magical wish-granting choker and decides to try it on. Only then does Wiz tell him that the choker strangles its wearer to death in four days unless their desires are fulfilled. This wouldn''t be a problem if Kazuma knew what his wish was. Fearing for Kazuma''s life, Aqua, Megumin, and Lalatina Ford "Darkness" Dustiness all agree to do his bidding in order to satisfy his desires and hopefully grant his wish, no matter what he asks for.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sekaiichi Hatsukoi Movie: Yokozawa Takafumi no Baai', 'Movie', 1, 'Completed', '2014-03-15', NULL, '8', 'Movie adaptation of the Sekaiichi Hatsukoi: Yokozawa Takafumi no Baai BL light novel.', 879, 'https://cdn.myanimelist.net/images/anime/11/65927.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Magi: Sinbad no Bouken (TV)', 'TV', 13, 'Completed', '2016-04-16', '2016-07-02', '8', 'In the small, impoverished Tison Village of the Parthevia Empire, a boy, Sinbad, is born to the jaded ex-soldier Badr and his kind-hearted wife Esra. His birth creates a radiant surge throughout the rukh, a declaration of a singularity to those who stand at the pinnacle of magical might: the "Child of Destiny" is here. Despite his country being plagued by economic instability and the repercussions of war, Sinbad leads a cheerful life—until a stranger''s arrival shatters his peaceful world, and tragedy soon befalls him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Michiko to Hatchin', 'TV', 22, 'Completed', '2008-10-16', '2009-03-19', '8', 'Under the unrelenting heat of the South American sun, hardened criminal Michiko Malandro breaks out of a high security prison for the fourth time in search of a man from her past. Michiko finds a clue in the form of Hana Morenos, a young girl trapped under the fists of her abusive foster family. In her powerlessness, Hana fantasizes about the day when she is finally whisked away from her captors by her very own Prince Charming. Little does she know that her fated prince would turn out to be the buxom and husky convict who charges in atop a stolen motorbike, claiming to be her mother.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuusha-Ou GaoGaiGar', 'TV', 49, 'Completed', '1997-02-01', '1998-01-31', '8', 'In the year 2005, a race of alien monsters called Zonders emerge from underground and launch a series of attacks on the city of Tokyo. The only defense against these creatures is the secret agency known as the Gutsy Geoid Guard (or 3G) and their ultimate weapon, the awesome giant robot GaoGaiGar. GaoGaiGar''s pilot, Guy Shishio, is a former astronaut who was nearly killed two years before when the Zonders first crashed to earth. Guy''s life was spared when a mysterious robot lion called Galeon pulled him from the burning shuttle and brought him to Earth. Guy''s father, Leo, then used Galeon''s technology to rebuild his shattered son as a cyborg, in the hopes that he could stop the aliens when they appear. Now, with Galeon as its core, GaoGaiGar fights to protect Earth. He is aided by a team of transforming robots and by a young boy named Mamoru, who has the power to purify the Zonders'' cores, and seems to be connected to the mysterious Galeon. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Free! Movie 5: The Final Stroke - Kouhen', 'Movie', 1, 'Completed', '2022-04-22', NULL, '8', 'After his first appearance on the competitive world stage, Haruka is held captive by the swimming of the unmistakable champion, Albert, and feels like he''s lost his way. With the current state of things, his swimming and what the water means to him are called into question. Haruka begins to sink to the bottom of the murky water as he struggles on his own.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ano Hi Mita Hana no Namae wo Bokutachi wa Mada Shiranai. Movie', 'Movie', 1, 'Completed', '2013-08-31', NULL, '8', 'A year after their deceased friend Honma Meiko appeared to them, Jinta Yadomi and the other members of the Super Peace Busters decide to write letters in her memory. Attempting to enjoy their summer together, they reminisce about their time together before and after her death.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Beastars Final Season', 'ONA', 12, 'Completed', '2024-12-05', NULL, '8', 'The anthropomorphic animal society stands at a precipice. Following the unmasking of the carnivorous murderer at Cherryton Academy, the school introduces a new segregation policy to protect herbivores, further fueling public disdain for carnivores. Meanwhile, the black market for meat thrives like never before, and the Shishi-gumi, a powerful gang of lions, faces upheaval after losing their leader. A shadowy, violent figure emerges, intending to seize control of the Shishi-gumi with the introduction of an appetizing energy drink for carnivores.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Musekinin Kanchou Tylor', 'TV', 26, 'Completed', '1993-01-25', '1993-07-19', '8', 'Justy Ueki Tylor is an average 20-year-old man: lazy, greedy, and a passionate womanizer. He plans to land an easy job with the United Planets Space Force that pays decently and is also far away from the rigorous combat raging throughout the galaxy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mairimashita! Iruma-kun 3rd Season', 'TV', 21, 'Completed', '2022-10-08', '2023-03-04', '8', 'Following their heroic efforts at Walter Park, the students of the misfit class return to Babyls Demon School after their summer vacation. What awaits them is not only adoration and admiration but also the shocking revelation that, in order to stay in the luxurious Royal One classroom, the entire class must be promoted to Dalet rank before entering the second year.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yamato yo, Towa ni: Rebel 3199', 'Movie', NULL, 'Airing', '2024-07-19', NULL, '7', 'Sequel to Uchuu Senkan Yamato 2205: Aratanaru Tabidachi.', 1180, 'https://cdn.myanimelist.net/images/anime/1856/143246.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Da Li Si Rizhi 2nd Season', 'ONA', 12, 'Completed', '2022-11-26', '2023-01-28', '7', 'Second season of Da Li Si Rizhi.', 603, 'https://cdn.myanimelist.net/images/anime/1375/126818.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hanbun no Tsuki ga Noboru Sora', 'TV', 6, 'Completed', '2006-01-13', '2006-02-24', '7', 'After contracting hepatitis A, Ezaki Yuuichi has been confined to a hospital, away from his friends and family, much to his displeasure. To relieve his boredom, he has taken to sneaking out of the hospital, usually putting himself on the receiving end of a beating from his nurse. Upon meeting a girl his age also staying in the hospital, he is immediately captivated by her beauty. Akiba Rika''s personality is not quite as captivating as her beauty however. In fact, she is rather selfish, moody, and bossy. But as the two spend more time with each other, they become closer, sharing the ordinary joys and trials of a budding teenage romance, even when darkened with impending tragedy—for Rika''s condition does not leave her much longer to live.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaleido Star: Aratanaru Tsubasa - Extra Stage', 'OVA', 1, 'Completed', '2004-09-24', NULL, '7', 'Sora Naegino has finally consolidated herself as Kaleido Stage''s greatest star ever, and a new star starts to shine as Rosetta Passel is selected to participate in the next attraction in a main role. But when things start to go wrong in the rehearsals, Rosetta starts to question her abillity to take the role, as her own capacity to remain in Kaleido Stage. Meanwhile, Fool also struggles with his demons from the past.', 341, 'https://cdn.myanimelist.net/images/anime/10/23761.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ijiranaide, Nagatoro-san 2nd Attack', 'TV', 12, 'Completed', '2023-01-08', '2023-03-26', '7', 'Hayase Nagatoro and Naoto Hachiouji have grown closer: the girl spends more time than ever in the art club room with her senpai. Although he is always on edge, Naoto no longer seems to mind Nagatoro''s presence. Time and again, Naoto demonstrates his hidden, cool demeanor, and Nagatoro displays her possessive tendencies. However, they still can not seem to completely close the distance between them. It is clear to everyone else that the pair have feelings for each other.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hokuto no Ken: Raoh Gaiden Junai-hen', 'Movie', 1, 'Completed', '2006-03-11', NULL, '7', 'Kenshiro is the heir of the legendary martial arts known as Hokuto Shinken, which can kill a man with a single blow, by striking the pressure points in the enemy''s body. Hokuto Shinken can be passed only to one successor at a time. When he was chosen as the successor, he parted ways with his brothers, Toki and Raoh. The former decided to use what he knew of the art to cure people... while the latter has chosen to use his supreme strength to install peace in the world by power. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shakugan no Shana', 'TV', 24, 'Completed', '2005-10-06', '2006-03-23', '7', 'The world has become a slaughtering ground for the Crimson Denizens, mysterious beings from a parallel universe who thrive on the life energy of humans. These merciless murderers only leave behind scant remainders of souls called "Torches," which are mere residues that will eventually be destroyed, along with the very fact of the victims'' existence from the minds of the living. In an ambitious endeavor to put an end to this invisible, hungry massacre, warriors called Flame Hazes relentlessly fight these monsters.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Psycho-Pass 3', 'TV', 8, 'Completed', '2019-10-25', '2019-12-13', '7', 'Thanks to the Sibyl System, the mental states of society can now be measured on a numerical scale. Using these "crime coefficients," a culprit can be apprehended before they ever commit a crime. But is it a perfect system? For Inspectors Kei Mikhail Ignatov and Arata Shindou, that remains to be seen, as their career with the Public Safety Bureau''s Crime Investigation Department has only just begun. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('5-toubun no Hanayome*', 'Special', 2, 'Completed', '2024-12-24', NULL, '7', '5-toubun no Hanayome* centers on the honeymoon trip of Fuutarou Uesugi and the Nakano sisters.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nanatsu no Taizai: Mokushiroku no Yonkishi 2nd Season', 'TV', 12, 'Completed', '2024-10-06', '2024-12-29', '7', 'Second season of Nanatsu no Taizai: Mokushiroku no Yonkishi.', 1016, 'https://cdn.myanimelist.net/images/anime/1109/145389.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Captain Tsubasa Season 2: Junior Youth-hen', 'TV', 39, 'Completed', '2023-10-01', '2024-06-30', '7', 'The International Junior Youth Tournament in Paris, France, is about to begin, and Tsubasa, Misaki, Wakabayashi, Hyuga, and Wakashimazu are ready. Japan’s team of elite players is to face off against the best the soccer world has to offer. Germany’s Schneider, France’s Pierre, Argentina’s Diaz, and Italy’s Hernandez await, along with a host of other new rivals. Let the battle begin!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nozomanu Fushi no Boukensha', 'TV', 12, 'Completed', '2024-01-08', '2024-03-25', '7', 'While exploring a labyrinth, Rentt Faina, an adventurer with lots of experience but little to show for it, is killed by a dragon upon discovering its lair. Shockingly, he wakes up to find himself turned into a skeleton, the lowest class of undead monsters. As Rentt fights against the other monsters of the labyrinth, he discovers that slaying them gains him experience towards higher stages of undead evolution—even ones with flesh! With this revelation in hand, Rentt obtains a new objective in his undeath: keep evolving in the hope of eventually becoming a vampire, the highest form of undead that is nearly indistinguishable from human beings.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou Shoujo Lyrical Nanoha: Reflection', 'Movie', 1, 'Completed', '2017-07-22', NULL, '7', 'The dying planet of Eltria is the only home of Kyrie Florian, her older sister Amitie, and her parents, who are scientists researching ways to save it. Unfortunately, the Florians must leave the planet behind to seek medical care for their father, who has contracted a lethal illness.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hetalia World Series', 'ONA', 48, 'Completed', '2010-03-26', '2011-03-11', '7', 'The pasta-loving North Italy, stalwart Germany, and timid Japan continue their misadventures through history as they reenact various events leading up to and during the Second World War. This includes the turbulent relationship between Hungary and Prussia, the War of Austrian Succession, Lithuania''s early days, and the Invasion of Poland. During such tumultuous times, how will these personified nations work their way through the conflicts?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yozakura Quartet: Tsuki ni Naku', 'OVA', 3, 'Completed', '2013-10-09', '2014-11-07', '7', '"Tsuki ni Naku" will take the story content from volume 11 of the manga, which features a visit to a onsen by the members of the Hiizumi Life Councelling Office, while the town''s police force have to deal with a new youkai-hunter threat.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Code Geass: Boukoku no Akito 2 - Hikisakareshi Yokuryuu', 'Movie', 1, 'Completed', '2013-09-14', NULL, '7', 'With her previous triumphs under her belt, Leila Malcal has now been promoted to Lieutenant Colonel and commanding officer of W-0. After having foiled an attempt to kidnap the General of the European army, she recruits the three perpetrators in order to make up for the lack of W-0''s pilots. Ayano Kosaka, Yukiya Naruse, and ringleader Ryou Sayama accept, in hopes of finding a place to belong. When they are ordered to perform a commando raid by dropping into enemy lines, Leila decides to join them to prevent unnecessary casualties.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gabriel DropOut', 'TV', 12, 'Completed', '2017-01-09', '2017-03-27', '7', 'For centuries, Heaven has required its young angels to live and study among humans in order to become full-fledged angels. This is no different for top-of-her-class Gabriel White Tenma, who believes it is her mission to be a great angel who will bring happiness to mankind. However, Gabriel grows addicted to video games on Earth and eventually becomes a hikikomori. Proclaiming herself a "Fallen Angel," she is apathetic to everything else—much to the annoyance of Vignette April Tsukinose, a demon whom Gabriel befriended in her angelic early days on Earth.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiao Lu He Xiao Lan', 'ONA', 72, 'Completed', '2018-08-27', '2019-02-16', '7', '"I''ve been holding a few words back for a long time — I like you!"
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aishiteruze Baby★★', 'TV', 26, 'Completed', '2004-04-03', '2004-10-09', '7', 'Katakura Kippei is in every way a high school playboy. Spending his days flirting with any girl he can see, responsibility is the last thing on his mind. Life takes an unexpected turn for him as one day he returns home to find himself with the full-time task of caring for his 5-year-old cousin. Kippei''s aunt Miyako had disappeared, appearing to have abandoned his cousin, Yuzuyu. With Kippei''s lack of responsibility and knowledge of childcare and Yuzuyu''s injured heart with the disappearance of her mother, their time together is in for a bumpy ride.', 990, 'https://cdn.myanimelist.net/images/anime/2/69665.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Days: Touin Gakuen-sen!', 'OVA', 3, 'Completed', '2018-03-16', '2018-07-17', '7', 'Sequel to DAYS.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mugen no Juunin: Immortal', 'ONA', 24, 'Completed', '2019-10-10', '2020-03-26', '7', 'Manji is an infamous swordsman in feudal Japan who is known as the "Hundred Man Killer," as he has killed one hundred innocent men. However, there is something far more frightening than his ominous reputation: the fact that he is immortal. This is the handiwork of eight-hundred-year-old nun Yaobikuni, who placed bloodworms capable of healing almost any wound in Manji''s body.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tales of Symphonia The Animation: Tethe''alla-hen', 'OVA', 4, 'Completed', '2010-03-25', '2011-02-25', '7', 'The second arc of Tales of Symphonia that takes place in the flourishing world of Tethe''alla. This OVA takes place up to two-thirds of the game, prior to the Derris-Kharlan arc.', 1192, 'https://cdn.myanimelist.net/images/anime/9/23211.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kara no Kyoukai Movie 6: Boukyaku Rokuon', 'Movie', 1, 'Completed', '2008-12-20', NULL, '7', 'With strange events occurring at Reien Girls'' Academy during winter break, Azaka Kokutou, a student and apprentice mage, is sent by her master to investigate. It turns out that another mage has been stealing the students'' memories using fairies that, despite her magical talent, are invisible to Azaka. So Shiki Ryougi, an acquaintance with special eyes who can see what Azaka cannot, is also sent to the academy to help with the crisis.  
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Joshiraku', 'TV', 13, 'Completed', '2012-07-06', '2012-09-28', '7', 'Joshiraku follows the conversations of five rakugo storyteller girls relating the odd things that happen to them each day. Their comedic and satirical chatting covers all kinds of topics, from pointless observations of everyday life, to politics, manga, and more. Each girl has something new to add to the discussion, and the discourse never ends in the same place it began.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Friends: Mononoke Shima no Naki', 'Movie', 1, 'Completed', '2011-12-17', NULL, '7', 'On an island, legend has it that monsters have lived there since ancient times. Because of this, the residents have named the island “Monster Island.” In actuality, the monsters living on the island are friendly, but live in fear of humans. A child named Kotake wanders onto the island. A grumpy red ogre named Naki ends up taking care of the child. What strange things might this encounter cause?', 804, 'https://cdn.myanimelist.net/images/anime/2/35815.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Leadale no Daichi nite', 'TV', 12, 'Completed', '2022-01-05', '2022-03-23', '7', 'The previously bedridden Keina Kagami finds herself in the world of her favorite VRMMORPG—titled Leadale—after the life support keeping her alive fails. Reincarnated in the body of her high-level character, "Cayna," she notices that the world of Leadale is different from what she remembers playing.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fate/Grand Order: Fujimaru Ritsuka wa Wakaranai Season 2', 'ONA', 26, 'Completed', '2024-08-03', '2024-12-31', '7', 'Second season of Fate/Grand Order: Fujimaru Ritsuka wa Wakaranai.', 214, 'https://cdn.myanimelist.net/images/anime/1412/144623.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan vs. Kaitou Kid', 'Movie', 1, 'Completed', '2024-01-05', NULL, '7', 'A special edited version of the TV series that presents the birth of the magician under the moon, Kaito Kid, and the first confrontation with the biggest and eternal rival Conan / Shinichi with new scenes!!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seiyuu Radio no Uraomote', 'TV', 12, 'Completed', '2024-04-10', '2024-06-26', '7', 'Experienced voice actor Yasumi Utatane works hard to maintain her image as a pure and innocent idol to please her fans, even as she struggles to find more jobs in the industry. But Yasumi has a secret—she is actually Yumiko Satou, a high school girl who prefers loose clothes and flashy jewelry, a complete contradiction to her false professional persona.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rougo ni Sonaete Isekai de 8-manmai no Kinka wo Tamemasu', 'TV', 12, 'Completed', '2023-01-08', '2023-03-26', '7', 'Mitsuha Yamano could not have had it worse. After failing to enter her university of choice and losing her entire family in an accident, she finds herself plummeting off a cliff due to an especially fragile guardrail. Through what seems to be the only bit of the fortune left in her life, Mitsuha''s firm unwillingness to die allows her to be transported to another world, where she ends up surviving.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uma Musume: Pretty Derby - 1st Anniversary Special Animation', 'Special', 1, 'Completed', '2022-02-22', NULL, '7', 'Initially unveiled on the Pakatube! Channel''s "Paka Live TV Vol.14 1st Anniversary Special!" stream, a special animation was shown commemorating the 1st anniversary of the Uma Musume: Pretty Derby mobile game starring Kitasan Black and Satono Diamond.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('A-Channel: +A-Channel', 'Special', 11, 'Completed', '2011-05-25', '2011-10-26', '7', 'Extra specials from the DVD/BDs.', 896, 'https://cdn.myanimelist.net/images/anime/9/29573.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kono Danshi, Mahou ga Oshigoto desu.', 'TV', 4, 'Completed', '2016-02-05', '2016-02-26', '7', 'Chiharu Kashima, captain of the Wizard Bureau''s Crisis Countermeasures Division, is among a handful of people who can use magic. While frequenting his favorite bar, he is approached by a friendly man named Toyohi Utsumi. Having always dreamt of being a wizard, Toyohi is enthralled by the idea of meeting one. Much to the young Captain''s surprise, Toyohi confesses that he has fallen in love with Kashima. While little time has passed, the two begin to spend more time together. Not all is well, however, as Kashima fears that magic is all that he has and Toyohi is only in love with Kashima the Wizard.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maria†Holic Alive', 'TV', 12, 'Completed', '2011-04-08', '2011-06-24', '7', 'When Kanako Miyamae transferred to a new all-girls school, she hoped to find true love. What she found instead was the beautiful Mariya Shidou, a charming classmate Kanako met on her first day. But Mariya has one flaw: she is actually a cross-dressing boy! After discovering Mariya''s secret and becoming stuck with him as her roommate, Kanako''s life has become a series of misfortunes. All she wants is to find the girl of her dreams, which is hard to do with the meddling of the sadistic Mariya and his sharp-tongued maid Matsurika Shinouji.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nanatsu no Taizai: Seisen no Shirushi', 'TV', 4, 'Completed', '2016-08-28', '2016-09-18', '7', 'The Seven Deadly Sins, along with Elizabeth Liones and Hawk, have won the Kingdom of Leones back from the Holy Knights. At long last, it''s their time to indulge in the peaceful lives they fought for. From inedible meat pies, overdue battles, unexpected stalkers, and the butterflies of first love, the Sins are accompanied by their friends in their carefree, fun-filled time together. However, the calm is broken with the premonition of a new threat, bringing upon the signs of Holy War and threatening to shatter the peace of the Sins'' easygoing days.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Starmyu 3rd Season', 'TV', 12, 'Completed', '2019-07-01', '2019-09-16', '7', 'Following a successful graduation performance, Yuuta Hoshitani and the rest of the second years begin preparations for the upcoming Ayanagi Festival. This year''s festival is the first time the students will be without their Kao Council mentors, giving them the creative freedom to do what they want. Hoping to perform alongside each other for once, the second years decide to put on a joint production together. The festival’s opening ceremony will also serve another purpose—to reveal next year''s Kao Council candidates. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou Shoujo Ikusei Keikaku', 'TV', 12, 'Completed', '2016-10-02', '2016-12-18', '7', 'For many girls in N-City, playing the popular social role-playing game Magical Girl Raising Project is as close as they could come to being a real magical girl. However, for some rare players, that dream can become a reality. One such girl is Koyuki Himekawa, who receives a notification one night that she has been selected to become a magical girl, her in-game avatar Snow White.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Keppeki Danshi! Aoyama-kun', 'TV', 12, 'Completed', '2017-07-03', '2017-09-18', '7', 'He is charming, cool, athletic, a good cook, but more importantly, he''s a clean freak. Aoyama is idolized and respected by everyone, but they can only admire him from afar due to his mysophobia. Despite that, he plays soccer—a rather dirty sport!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Vanitas no Karte: En Route Pour le Gévaudan', 'Special', 1, 'Completed', '2022-01-08', NULL, '7', 'Recap of the first 12 episodes narrated by Tomoaki Maeno, with a sneak peek of the second cours.', 138, 'https://cdn.myanimelist.net/images/anime/1570/120423.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Senki Zesshou Symphogear GX: Senki Zesshou Shinai Symphogear', 'Special', 4, 'Completed', '2015-11-25', '2016-02-24', '7', 'Original short episodes featuring characters in super-deformed style.', 780, 'https://cdn.myanimelist.net/images/anime/8/77264.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Metal Fight Beyblade', 'TV', 51, 'Completed', '2009-04-05', '2010-03-28', '7', 'A new cast of characters take on the continued battle between good and evil. Ginga, our hero, and his group of loyal friends take on a dangerous group called the Dark Nebula. The Dark Nebula’s sole mission is to take over the world and unleash their evil upon it; but before they can do so, they must destroy Ginga as he is the only person that’s strong enough to stand in their way. The plot thickens as friends become enemies and enemies become allies. Everything starts and ends with Ginga as he struggles to find the strength to defend his world and the honor of Beyblade.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Arifureta Shokugyou de Sekai Saikyou: Arifureta Yorimichi de Sekai Saikyou', 'Special', 1, 'Completed', '2022-03-23', NULL, '7', 'Unaired episode included in the first Blu-ray volume.', 1153, 'https://cdn.myanimelist.net/images/anime/1981/120698.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Strike the Blood II', 'OVA', 8, 'Completed', '2016-11-23', '2017-05-24', '7', 'The second season of Strike the Blood which adapts three arcs from the 9th, 11th, and 12th light novel volumes.', 761, 'https://cdn.myanimelist.net/images/anime/1600/111675.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gunslinger Girl: Il Teatrino OVA', 'OVA', 2, 'Completed', '2008-10-24', NULL, '7', 'Episodes 14 and 15 of Gunslinger Girl: Il Teatrino.', 86, 'https://cdn.myanimelist.net/images/anime/12/12641.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Soukyuu no Fafner: Dead Aggressor - Exodus Special', 'Special', 1, 'Completed', '2015-02-04', NULL, '7', 'An expanded version of the first episode of Soukyuu no Fafner: Dead Aggressor - Exodus included in the Blu-ray &amp; DVD Vol.1.', 400, 'https://cdn.myanimelist.net/images/anime/9/77029.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hurricane Live! 2032', 'Special', 6, 'Completed', '1988-04-24', NULL, '7', 'Elements of the Bubblegum Crisis series in an MTV-styled rock video. Clips from the series are combined with the music of Kinuko Omori and the Knight Sabers.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou Shoujo Pretty Sammy (1996)', 'TV', 26, 'Completed', '1996-10-04', '1997-03-28', '7', 'The carefree Tsunami is next in line to rule over the Magical Kingdom of Juraihelm. But before she is officially crowned as queen, she must restore balance to the universe that has come to favor darkness. To accomplish her goal, Tsunami gives the ordinary Sasami Kawai a magical baton that can transform her into a magical girl. She also appoints the rabbit-like creature Ryou-Ouki to aid Sasami in the battle against evil.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tetsujin 28-gou (1980)', 'TV', 51, 'Completed', '1980-10-03', '1981-09-25', '7', 'Shotaro Kaneda is a young boy whose dead scientist father created the giant robot Tetsujin 28 after realizing the chances of attacks from outer galaxies. Shotaro has possession of the only controller, kept in an attaché case, which enables him to have direct command of the all mighty Tetsujin 28. If the controller goes into the hands of the enemy, this could lead Tetsujin 28 to fight for villains who want to destroy The Earth. Whenever peace in this world is threatened, Shotaro together with his friends, Dr. Shikishima, Detective Otsuka, must unleash the power of our metallic super hero.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chocchan Monogatari', 'Movie', 1, 'Completed', '1996-03-20', NULL, '7', 'This feature length film is based on autobiography of Cho "Chocchan" Kuroyanagi, who is better known as the mother of an actress Tetsuko Kuroyanagi.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Juushin Liger', 'TV', 43, 'Completed', '1989-03-11', '1990-01-27', '7', 'It is 199X A.D. In Kushiro, Hokkaido, three bodies of Dragonite appear. Possessing overwhelming destructive force, they attack the city. They also awaken the evil Jashin Drago from the holy seal he was trapped in. 200 years ago, Drago was trapped in the seal by a holy warrior with the tattooed mark of the Liger. Assuming that the warrior is dead, Drago and Empress Zara are free to conquer the Earth using their army of biomechanical beasts. Even the Japan Self-Defense Forces are no match for the Dragonites'' awesome power. One of the people fleeing is the protagonist, a milquetoast 16 year old boy named Ken Taiga. Unbeknownst to the Dragonites, Ken realizes that he is the descendant of the Liger warrior! In a burst of anger, Ken''s Liger birthmark appears, and he rises his palm into the air, shouting the henshin command, "LIGER!!!", which then covers him in demonic long-haired biomechanical armor. Ken transforms into Jushin Liger to fight the evil forces of the Dragonite! 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Arifureta Shokugyou de Sekai Saikyou', 'TV', 13, 'Completed', '2019-07-08', '2019-10-07', '7', 'The ordinary life of 17-year-old otaku Hajime Nagumo is disrupted when he and his classmates are summoned to a fantasy world and tasked with saving mankind. While his classmates are gifted with impressive abilities useful in combat, Hajime is belittled for only gaining an inferior transmutation skill that lacks any real offensive power. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ninja Hattori-kun (2012)', 'TV', 52, 'Completed', '2012-05-13', '2015-02-16', '7', 'Remake of the Ninja Hattori-kun series.', 802, 'https://cdn.myanimelist.net/images/anime/9/50285.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shirayuki Hime no Densetsu', 'TV', 52, 'Completed', '1994-04-06', '1995-03-29', '7', 'Snow White was a very happy princess, until the day her stepmother, the Queen Christelle, finally reveals her personality and wants to kill the girl. Snow White flees from the castle and got lost in the woods, where she meets seven dwarfs.', 1009, 'https://cdn.myanimelist.net/images/anime/3/59509.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chou Denji Robo Combattler V', 'TV', 54, 'Completed', '1976-04-17', '1977-05-28', '7', 'The first of Tadao Nagahama''s Romance Super Robot Trilogy. (#2: Chou Denji Machine Voltes V, #3: Toushou Daimos)
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Moero! Top Striker', 'TV', 49, 'Completed', '1991-10-10', '1992-09-24', '7', 'Hikaru Kicker is a 13-year-old boy who loves football. He has grown up playing with a football at all times ever since his father''s friend gave him one when he was still only a baby.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Visual Prison', 'TV', 12, 'Completed', '2021-10-09', '2021-12-25', '7', 'Vampires have existed for centuries and live under the rule of the Scarlet Moon. Once a year, "Visual Prison" occurs, a visual kei competition where the vampire who sings the most beautiful song is bestowed with great power by the Scarlet Moon. At the forefront of the competition are ECLIPSE—the reigning champions who stand for an established order, and LOST EDEN—a group that believes the strongest should rule.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kikou Senki Dragonar', 'TV', 48, 'Completed', '1987-02-07', '1988-01-30', '7', 'A.D. 2087 - the United Lunar Empire Giganos wages war on the Earth Federation Military to take control of the planet and establish a "rebirth" of the human race. During an invasion of a colony by Giganos'' forces, three civilian men stumble upon a trio of top-secret Metal Armor units called "Dragonars" and pilot them to combat the enemy forces.', 974, 'https://cdn.myanimelist.net/images/anime/13/11236.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dokidoki! Precure', 'TV', 49, 'Completed', '2013-02-03', '2014-01-26', '7', 'Middle schooler Mana Aida is known for her vivid passion and kind-hearted disposition, especially by her friends Rikka Hishikawa and Alice Yotsuba. While the girls are on a school field trip, otherworldly villains from the "Trump Kingdom" appear and create giant monsters from the civilians'' selfish desires to cause havoc. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mamahaha no Tsurego ga Motokano datta', 'TV', 12, 'Completed', '2022-07-06', '2022-09-21', '7', 'Listless geek Mizuto Irido and introverted nerd Yume Ayai seemed like a match made in heaven, connected by their mutual love for literature. Unfortunately, their differences gradually grew, and they separated just after their middle school graduation. But, as if by divine comedy, the two find themselves reunited as step-siblings.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahoutsukai Tai! (TV)', 'TV', 13, 'Completed', '1999-07-07', '1999-10-06', '7', 'The Magic User''s Club is a group of five well-meaning misfits who do more than card tricks—they can use actual magic. And with that magic, they managed to defeat a giant ship from outer space! But their close encounter left an enormous cherry blossom tree right in the middle of the city. It''s so big that it blocks out the sun!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shichinin no Nana', 'TV', 25, 'Completed', '2002-01-10', '2002-06-27', '7', 'On the last Valentine''s Day before her high school entrance exams, Nana Suzuki tries to build up the courage to confess to her longtime crush. However, when her chocolates are accidentally ruined, she rushes back to her house to make more—not realizing that the microwave has been turned into a strange invention by her grandfather. Suddenly, six additional copies of Nana appear, each possessing their own extreme personality and a crystal that grants them magic powers!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sora no Otoshimono Final: Eternal My Master', 'Movie', 1, 'Completed', '2014-04-26', NULL, '7', 'The second movie of Sora no Otoshimono that concludes the anime series.', 705, 'https://cdn.myanimelist.net/images/anime/3/58059.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shadowverse Flame', 'TV', 50, 'Completed', '2022-04-02', '2023-03-25', '7', 'Shadowverse Flame features a new protagonist Light Tenryu and its story is set in Shadowverse College, a facility that trains professional players of the Shadowverse game. Tenryu Light, a transfer student, decides to join "Seventh Flame," one of the seven Shadowverse clubs. However, Seventh Flame is on the verge of closure due to a lack of members! In order to avoid the club''s demise, Light decides to look for new members. But what awaits him are powerful rivals who control a wide variety of cards...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kono Danshi, Uchuujin to Tatakaemasu.', 'OVA', 1, 'Completed', '2011-10-10', NULL, '7', 'All hope seems lost when the world is suddenly invaded by aliens. Earth''s only defense is a small three-person team known as the Special Counter-Aliens Task Force, consisting of an anonymous director, the tyrannical Shiro, and the easygoing Arikawa.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koukaku Kidoutai: Stand Alone Complex 2nd GIG - Individual Eleven - Tachikoma na Hibi', 'Special', 1, 'Completed', '2006-01-27', NULL, '7', 'Tachikomatic Days short that was released on the Individual Eleven DVD.', 704, 'https://cdn.myanimelist.net/images/anime/5/30204.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shi Cao Lao Long Bei Guan Yi E Long Zhi Ming', 'ONA', 12, 'Completed', '2022-07-30', '2022-10-08', '7', 'A 5000-year-old herbivorous dragon was living peacefully when one day a young girl showed up in his cave. She offered herself as a sacrifice in order to gain favor for her village. He played along as the great "Evil Dragon, the Demon Lord''s Army Leader" in order to get rid of her. However, his little white lie awoke her hidden powers and his peaceful life suddenly ended. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Azumanga Web Daiou', 'ONA', 1, 'Completed', '2000-12-28', NULL, '7', 'Chiyo brings a video camera to school for a class project. But when Tomo gets a hold of it, heaps of trouble happen all over campus.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senkan Nadesico: The Prince of Darkness', 'Movie', 1, 'Completed', '1998-08-01', NULL, '7', 'Two years have passed since the end of the "Martian Successor Nadesico." Akito and Yurika have disappeared. The Jovians and the Earthlings have joined forces and Ruri is now captain of Nadesico B. As the popularity of Boson Jumping grows, a vast transportation network has been developed. Dubbed the Hisago Plan, this network of Chulip portals holds the answers to the mysteries behind Bose particles and their power. If those secrets should fall into the wrong hands, it could mean big trouble. And big trouble there is. A Martian splinter group has launched an offensive, leaving the United Forces befuddled and desperate. So much so, in fact, that the former crew of the Nadesico is called back to active duty for a special unsanctioned mission-to save us all. Does this menagerie of misfits have what it takes? Who will win the race for the Boson technology? And what the heck happened to Akito and Yurika?', 1117, 'https://cdn.myanimelist.net/images/anime/10/51253.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maburaho', 'TV', 24, 'Completed', '2003-10-14', '2004-04-06', '7', 'In the world of Maburaho, everyone is born with the ability to use magic and are thus labeled magicians. However, the magical ability of each person is not equal. The number of times you can use magic determines the amount of respect you receive, and since one’s magical power is determined at birth by traits and genetics, those who have a bloodline stemming from famous magicians are highly sought after.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pop in Q', 'Movie', 1, 'Completed', '2016-12-23', NULL, '6', 'The story begins the day before the graduation ceremony. Five middle school girls each are preoccupied with their real everyday lives. These girls meet each other in a fantasy world after being sent there through a sudden occurrence. There, they learn about the impending crisis that this world is facing. The way to avert this crisis is for the five to collaborate and bring their five hearts together as one through dance.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tiger & Bunny: Too Many Cooks Spoil the Broth.', 'Special', 1, 'Completed', '2015-09-19', NULL, '6', 'The official website for the Tiger &amp; Bunny anime announced on Friday that the Pacifico Yokohama''s National Convention Hall of Yokohama would host special Tiger &amp; Bunny concerts September 19th and 20th. The franchise''s composer Yoshihiro Ike is personally conducting the "Sternbild Orchestra &amp; Band" for live performances of music from the television series and two films.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Space☆Dandy 2nd Season Picture Drama', 'Special', 3, 'Completed', '2014-11-21', '2015-01-28', '6', 'Picture drama episodes included on the Blu-ray/DVD volume eight, nine, and ten.', 138, 'https://cdn.myanimelist.net/images/anime/6/72373.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gebäude Bäude', 'TV', 10, 'Completed', '2020-11-08', '2020-12-10', '6', 'Final chapter of Disney''s Fireball series.', 444, 'https://cdn.myanimelist.net/images/anime/1631/112290.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oh! Family', 'TV', 26, 'Completed', '1986-10-06', '1987-03-30', '6', 'This story takes place in Florida, USA. The main characters are the lovable members of the Anderson family; each has their own characteristics which both conflict with and support the others''. By going through many events together (meaningful events as well as weird ones), the bond between them grows stronger and tighter.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dance with Devils', 'TV', 12, 'Completed', '2015-10-07', '2015-12-23', '6', 'Ritsuka Tachibana has always been a good student, so she is completely shocked when she is suddenly summoned by the student council for breaking school rules. Led by Rem Kaginuki, the student council—also consisting of Urie Sogami, Shiki Natsumezaka, and Mage Nanashiro—tries to interrogate her, but it soon becomes clear that they have ulterior motives. However, this is only the beginning of Ritsuka''s misfortune. When her mother gets kidnapped, her life is turned upside down, and Ritsuka gets drawn into a battle for supremacy between vampires and devils. Both groups are searching for the "Grimoire," a forbidden item that allows its owner to rule the world, and Ritsuka is somehow connected to this strange artifact.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hare Tokidoki Buta', 'Movie', 1, 'Completed', '1988-08-23', NULL, '6', 'Noriyasu seems like an average third-grader, but his life goes haywire after he catches his mother reading his private daily journal. In an effort to astonish her, he begins writing outlandish lies about a giant snake in the bathroom, cooking pencils for dinner, and a rain of pigs, but Noriyasu is the one who''s shocked when his writings play out in reality and everyone else treats the events as normal.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fuichin-san', 'OVA', 1, 'Completed', '2004-03-20', NULL, '6', 'Based on Ueda Toshiko''s shoujo manga.', 67, 'https://cdn.myanimelist.net/images/anime/11/62189.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ippon Bouchou Mantarou', 'OVA', 2, 'Completed', '1991-06-21', '1991-12-21', '6', 'Based on the manga by Big Joe (ビッグ錠).', 436, 'https://cdn.myanimelist.net/images/anime/1501/111468.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Strange+', 'TV', 12, 'Completed', '2014-07-11', '2014-09-26', '6', 'Second season of Strange+.', 785, 'https://cdn.myanimelist.net/images/anime/11/75522.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Let''s Nupu Nupu', 'TV', 16, 'Completed', '1998-10-07', '1998-11-03', '6', 'With four-frame comic origins, this animated title preserves the same quick pace by following the regular cast of colorful characters through separate but interwoven story lines in every episode. From Ms. Shitara''s relentless but always ineffective sexual pursuit of young Takagi to the adventures of the heroicly stupid but cute Sushi Cat, you will be mystified at the silliness of it all but find yourself laughing for the same reason! 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ikkyuu-san to Yancha Hime', 'Movie', 1, 'Completed', '1978-03-18', NULL, '6', 'Ikkyuu must talk a tomboy into behaving in a more lady-like manner before her habit of calling herself by the boy''s name Tsuyumaru and attacking shogun Yoshimitsu Ashikaga with a wooden sword gets her into trouble.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kakumeiki Valvrave Recaps', 'ONA', 3, 'Completed', '2013-09-20', '2013-09-22', '6', 'Three edited ONAs that summarize Valvrave the Liberator 1st season were broadcasted on Nico Nico Live on September 20-22, 2013. They are also were included in BD and DVD limited edition volume one of Kakumeiki Valvrave 2nd Season.', 974, 'https://cdn.myanimelist.net/images/anime/7/56851.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jungle Taitei Movie', 'Movie', 1, 'Completed', '1966-07-31', NULL, '6', 'The first 2 minutes of this film are taken from the Jungle Emperor Leo (1965) TV series, while the rest is all original. Tezuka was very pleased that this film conveyed his story accurately, something he wasn''t able to do with the TV series. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The iDOLM@STER Live For You!', 'OVA', 1, 'Completed', '2008-02-28', NULL, '6', 'On the day before the 765 Productions Fan Appreciation Event, each of the idols prepare to head home. However, Chihaya Kisaragi, uneasy about tomorrow''s events, decides to have a last minute personal rehearsal. One thing leads to another as Chihaya, Miki and Haruka are dragged from one exciting situation to the next. What is the truck driver''s true destination? What is the secret behind the old house? Will the girls make it in time for the event? Watch as Miki, Haruka, Chihaya and the other idols join together for their biggest adventure yet!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dream Hunter Rem', 'OVA', 4, 'Completed', '1985-12-15', '1987-02-25', '6', 'Rem is an ordinary woman in our world but, in the world of dreams, she becomes a dream warrior, defending humanity from the evils there. When dream demons reach the waking world, she fights them with the help of her pets which transform into a tiger and wolf.', 76, 'https://cdn.myanimelist.net/images/anime/1538/94531.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ippatsu Kiki Musume', 'TV', 16, 'Completed', '1999-10-05', '1999-10-29', '6', 'Kunyan lives her crazy life of misadventures from episode to episode. This comedy series is accompanied by a narrator who scientifically explains all that happens to her.', 351, 'https://cdn.myanimelist.net/images/anime/6/34133.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maicching Machiko-sensei', 'TV', 95, 'Completed', '1981-10-08', '1983-10-06', '6', 'Machiko Mai is the newest teacher at Asama Elementary; she''s young, beautiful, and has the perfect proportions—traits that attract the attention of not only her students, but the rest of the perverted faculty as well. Whether it''s luring her in and spraying up her skirt with a hose or leaps and bounds to grab her breasts, there''s nothing that Machiko''s first year students won''t try to do. Regardless of her embarrassing plight, Machiko is always a good sport and tries her best to help out her students—at any cost to her dignity!', 939, 'https://cdn.myanimelist.net/images/anime/7/60423.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koi to Producer: EVOLxLOVE', 'TV', 12, 'Completed', '2020-07-16', '2020-10-01', '6', 'After her father passed away, a young woman inherited his production company, Miracle Entertainment, along with its most successful program, "Miracle Finder." In recent years, however, the show has fallen off the radar and it is now mostly forgotten. In an attempt to save the show from being canceled, this young woman desperately tries to look for a unique topic to use as inspiration. She finds it in the form of "Evol," a mysterious gene that has granted certain people special powers and is considered the next step in human evolution. But, as marvelous as this gene seems, its existence may lead to an unstoppable battle between humans for survival.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Anime Oyako Gekijou', 'TV', 26, 'Completed', '1981-10-09', '1982-03-29', '6', 'The series beings at the home of a young boy named Sho Azuka discovers the magical Bible "Superbook" that speaks and sends him, his friend Azusa Yamato, and his toy robot Zenmaijikake back in time to the early events of the Old Testament.', 1009, 'https://cdn.myanimelist.net/images/anime/1478/146212.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kawasaki Frontale x Tentai Senshi Sunred 2nd Season', 'Special', 1, 'Completed', '2010-03-05', NULL, '6', 'The second collaboration between Kawasaki Frontale and Tentai Senshi Sunred.', 26, 'https://cdn.myanimelist.net/images/anime/3/21809.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Captain', 'Special', 1, 'Completed', '1980-04-02', NULL, '6', 'Before Captain became a TV series it was a one-shot TV special that garnered the highest ratings of any anime that month. For its re-run on August 20th, 30 minutes of new content was added in which brought in more ratings that trumped the previous statistic.', 263, 'https://cdn.myanimelist.net/images/anime/7/67651.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Glass no Kamen desu ga to Z', 'TV', 14, 'Completed', '2013-04-28', '2013-07-28', '6', 'A continuation of the previous season under a new director and new name.', 214, 'https://cdn.myanimelist.net/images/anime/3/66851.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koneko no Rakugaki', 'Movie', 1, 'Completed', '1957-05-13', NULL, '6', 'A young cat is enjoying drawing pictures on a wall. However, when his pencil is stolen, he has no choice but to enter the world of his drawings in order to get it back.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Duel Masters Victory V', 'TV', 51, 'Completed', '2012-04-07', '2013-03-30', '6', 'This series continues the adventures of Katta Kirifuda, Bucyake and Yohdel throughout the school season. They meet new classmates such as Leo to duel against. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('All That Gundam', 'Special', 1, 'Completed', '1989-01-01', NULL, '6', 'Animated video created just for a 1989 event that featured all the major mobile suit robots from the first 10 years of the Gundam anime franchise.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wagahai wa Neko de Aru', 'Special', 1, 'Completed', '1982-02-17', NULL, '6', '"I" is a cat without a name who lives with an English teacher, Mr. Kushami (Mr. Sneeze). "I" can''t believe how stupid human beings are and chronicles some of their most incredible foibles. In particular, he is fascinated by Kushami''s student Mizushima who falls in love with Haruko, the only daughter of businessman Kaneda.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tobidase! Machine Hiryuu', 'TV', 21, 'Completed', '1977-10-05', '1978-03-29', '6', 'The bosses of rival car companies decide to fight each other in the sporting arena by backing different race car teams. Chairman Gapporin hires Okkanabichi the supreme racer, while Chairman Misaki hires Riki Kazama, a relatively untried driver for the flying car known as Machine Hiryu. Mixing elements of Speed Racer with Time Bokan, this Tatsunoko production ticks the same boxes, with Riki''s cute girlfriend Nana, mini-mechanic Chuta, the cute ape and pooch, and the comic and glamorous villains lurking in the background. Early work from many big names, including Yoshitaka Amano and Kunio Okawara, is strictly in the studio mould. Manga versions of the story ran in several magazines, such as Terebi Magazine and Terebi Land. Racing fever seemed to have struck the Japanese animation business at this time: compare to the same year''s Arrow Emblem.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Kujakuou', 'OVA', 2, 'Completed', '1994-05-20', '1994-06-17', '6', 'A young mystic without a past, Kujaku was born under a dark omen possessed of incredible supernatural powers. Raised by priests, he has learned to use these powers for good. But the evil Siegfried von Mittgard seeks to steal his birthright, and rule the world as the Regent of Darkness. He has dispatched bloodthirsty minions to destroy Kujaku before he can awaken to his destiny. Now, Kujaku must unravel the riddle of his past, before the power within consumes him! 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyoto Animation: Hoshi-hen', 'Special', 1, 'Completed', '2011-08-19', NULL, '6', 'An incomplete storyboard rests on a desk. Within it, are a boy and girl who suddenly jump to life and escape the confines of the sheet of paper in order to kickstart their story—one defined by their own actions. As they journey across the desk, the world around them begins to transform and signals the start of their vivid new adventure.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ayane-chan High Kick!', 'OVA', 2, 'Completed', '1997-01-21', '1997-04-25', '6', 'Ayane Mitsui dreams of becoming a professional wrestler, and trains hard in hopes of facing her idol Manami Toyota at the All-Japan Women''s International Championship. However, she is devastated when she fails her tryout for All-Japan Pro Wrestling. Seeing her potential, a man under the guise of representing an indie promotion scouts her out. The man who scouted her turns out to be Kunimitsu Tangay, a veteran trainer.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gregory Horror Show: The Bloody Karte', 'Special', 12, 'Completed', '2001-04-07', '2001-06-30', '6', 'The fourth series, The Bloody Karte (presented as a side series on the DVDs) is a set of 12 stories about Catherine working in a mysterious hospital.  
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mikeneko Holmes no Yuurei Joushu', 'OVA', 1, 'Completed', '1992-07-21', NULL, '6', 'Based on Akagawa Jirou''s popular book series about hapless detective Katayama Yoshitaro who lives with his sister Harumi and their cat Holmes, which has a sixth sense when it comes to solve mysteries. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('X Densha de Ikou', 'OVA', 1, 'Completed', '1987-11-06', NULL, '6', 'Ishihara Toru is an everyday guy with an on-and-off girlfriend and a position working for a train buff. Things become complicated when a ghostly vehicle dubbed the X Train begins to ride the rails, destroying everything in its path. Somehow, it seems that Toru is connected with the X Train by a strange power, which draws the attention of some very dangerous and power hungry people who would wield it for their own...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Outlanders', 'OVA', 1, 'Completed', '1986-12-16', NULL, '6', 'Tetsuya Wakatsuki, a young photographer, documents an alien invasion that brutally annihilates the human population. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Iruka to Shounen', 'TV', 13, 'Completed', '1975-07-30', '1975-08-15', '6', 'The series presents the adventures of Zoum, a white dolphin and his friends, two children who live with their sailor uncle. The cast includes several animals including a mynah bird (who understands the dolphin language in addition to the language of the other animals and the humans on the island and acts as a translator), a koala, and a sloth.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jungle Kurobee', 'TV', 31, 'Completed', '1973-03-02', '1973-09-28', '6', 'Urobe was a son of the great chief of Pyrimi, Africa. One day he hung on an airplane and came to Japan. Because of the cold and hunger, he fell on to the yard of Shishio’s house, and Shishio nursed him. Kurobe was very thankful for him and began to repay for his kindness. Kurobe dug a big hole in the yard.Every time he returns the favor, he threw a stone into the hole until stones would fill the hole.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tachiguishi Retsuden', 'Movie', 1, 'Completed', '2006-04-08', NULL, '5', 'Immediately following the end of the World War II, Tokyo was trying to emerge from the rubble. In a corner of the black market stood a flimsy soba (buckwheat noodle) eatery. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sango no Umi to Ouji', 'OVA', 1, 'Completed', '2000-02-01', NULL, '5', 'On the island of Okinawa, driven by his kindhearted nature, a boy named Ray determines to stop the destruction of the island''s natural forests and coral reef, no matter what he has to give. What will he give to stop a tidal wave from killing the island''s people?', 1030, 'https://cdn.myanimelist.net/images/anime/3/28054.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Okubyou na Venus', 'OVA', 1, 'Completed', '1986-03-21', NULL, '5', 'Story about a singer/dancer. There is music and singing throughout almost the entire OVA.', 1030, 'https://cdn.myanimelist.net/images/anime/1733/112137.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Legend of Lemnear: Kyokuguro no Tsubasa Valkisas Pilot Film', 'Special', 1, 'Completed', '1998-09-03', NULL, '5', 'Original pilot for the "Legend of Lemnear" OVA.', 25, 'https://cdn.myanimelist.net/images/anime/1775/91153.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuro-Nikuru Girls', 'ONA', 3, 'Completed', '2016-12-16', '2017-02-23', '5', 'The digital sale/airing of the Chain Chronicle: Haecceitas no Hikari movies includes its own unique version of the Chain Chronicle chibi shorts, different from the chibi shorts shown with the theater airing. Their focus is on the female cast.', 945, 'https://cdn.myanimelist.net/images/anime/10/83832.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Milk House Dreaming: Ai no Shiki', 'OVA', 1, 'Completed', '1987-11-28', NULL, '5', 'An image video, setting watercolors from Yumiko Kawahara''s 1983 manga to a series of 11 pop songs.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Taka no Tsume x Megane Super', 'ONA', 2, 'Completed', '2016-06-30', '2016-11-22', '5', 'A collaboration anime between Taka no Tsume and Megane Super, an eyeglasses company in Japan.', 214, 'https://cdn.myanimelist.net/images/anime/11/81662.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mellow', 'OVA', 1, 'Completed', '1993-07-23', NULL, '5', 'A story about a crossdressing teacher handling a delinquent class.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Duel Masters Special Movie: Douka', 'Special', 1, 'Completed', '2024-03-31', NULL, '5', '', 436, 'https://cdn.myanimelist.net/images/anime/1123/142436.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Benghuai: Xing Qiong Tiedao - Yongjie Lun Wu', 'ONA', 1, 'Completed', '2024-03-18', NULL, '5', 'Animated short for the game Honkai: Star Rail.', 736, 'https://cdn.myanimelist.net/images/anime/1873/142288.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The King of Fighters: Awaken PV', 'Special', 1, 'Completed', '2020-07-30', NULL, '5', 'A trailer for an unreleased film, intended to be a sequel to The King of Fighters: Destiny. Announced in 2020 with a 2022 release date, but with no further news since then, only the trailer is available.', 1167, 'https://cdn.myanimelist.net/images/anime/1727/152315.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yankee Hamster Season 4', 'ONA', 50, 'Completed', '2023-10-06', '2024-09-19', '5', 'The fourth season of Yankee Hamster.', 684, 'https://cdn.myanimelist.net/images/anime/1581/138432.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Azur Lane: Bisoku Zenshin! Ni!!', 'TV', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'Second season of Azur Lane: Bisoku Zenshin!.', 864, 'https://cdn.myanimelist.net/images/anime/1720/149372.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Metal Cardbot', 'TV', 26, 'Completed', '2023-03-30', '2023-09-13', '5', 'A long time ago, there was a planet named Machina where a race of sentient machines, or Metal Cardbots, resided. One day, the planet suddenly explodes, forcing its inhabitants to live on Earth. To not attract attention, the Cardbots disguise themselves as everyday vehicles. In the present day, Jun, an elementary school kid who loves BMX, accidentally discovers the Metal Breath, a wrist gadget that allows him to capture and power up the Cardbots with different abilities.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hanlu', 'Movie', 1, 'Completed', '2018-06-12', NULL, '5', 'In a restaurant in China, waiters try to swat flies while a number of diners eat their food.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaleido Star: Legend of Phoenix - Layla Hamilton Monogatari', 'OVA', 1, 'Completed', '2005-12-11', NULL, '8', 'Layla is going to perform Phoenix in Broadway. Playing this important role, she sets out on a journey by bicycle alone without leaving any message in order to find out what she''s missing inside.', 341, 'https://cdn.myanimelist.net/images/anime/7/28863.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boku no Hero Academia', 'TV', 13, 'Completed', '2016-04-03', '2016-06-26', '8', 'The appearance of "quirks," newly discovered super powers, has been steadily increasing over the years, with 80 percent of humanity possessing various abilities from manipulation of elements to shapeshifting. This leaves the remainder of the world completely powerless, and Izuku Midoriya is one such individual.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seihou Bukyou Outlaw Star', 'TV', 24, 'Completed', '1998-01-09', '1998-06-26', '8', 'Gene Starwind has always dreamed of piloting his own ship out into the vast sea of stars. Unfortunately, not all dreams come true, as he spends his days working odd jobs alongside his partner, James Hawking, on the small planet Sentinel III instead. However, this all takes a turn when the duo takes on a job from Rachel Sweet who, unbeknownst to them, is actually a treasure-hunting outlaw. Tasked with protecting a mysterious girl known as Melfina, the meeting irrevocably changes the pair''s lives as they are sent out into the great unknown aboard the highly advanced ship, Outlaw Star.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tokyo Revengers', 'TV', 24, 'Completed', '2021-04-11', '2021-09-19', '8', 'Takemichi Hanagaki''s second year of middle school was the highest point in his life. He had respect, a gang of friends he could count on, and even a girlfriend. But that was twelve years ago. Today, he''s a nobody: a washed-up nonentity made fun of by children and always forced to apologize to his younger boss. A sudden news report on the Tokyo Manji Gang''s cruel murder of the only girlfriend he ever had alongside her brother only adds insult to injury. Half a second before a train ends his pitiful life for good, Takemichi flashes back to that same day 12 years ago, when he was still dating Hinata Tachibana.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tiger & Bunny', 'TV', 25, 'Completed', '2011-04-03', '2011-09-18', '8', 'In Stern Bild City, those with special abilities are called NEXT, and can use their powers for good or bad. A unique organized group of NEXT appear regularly on Hero TV, where they chase down evildoers to bring limelight to their sponsors and earn Hero Points in the hopes of becoming the next King of Heroes.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shingeki no Kyojin: Chronicle', 'Movie', 1, 'Completed', '2020-07-17', NULL, '8', 'The compilation film recaps the anime''s 59 episodes from seasons one to three.', 1105, 'https://cdn.myanimelist.net/images/anime/1786/110717.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kengan Ashura Season 2 Part 2', 'ONA', 16, 'Completed', '2024-08-15', NULL, '8', 'Part two of Kengan Ashura Season 2.', 506, 'https://cdn.myanimelist.net/images/anime/1086/144400.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oomuro-ke: Dear Sisters', 'Movie', 1, 'Completed', '2024-02-02', NULL, '8', 'A spin-off of Yuru Yuri featuring Sakurako and her sisters.', 673, 'https://cdn.myanimelist.net/images/anime/1401/140053.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tokyo Revengers: Tenjiku-hen', 'TV', 13, 'Completed', '2023-10-04', '2023-12-27', '8', 'After succeeding in their winter conflict against Taiju Shiba and his Black Dragons, the Tokyo Manji Gang absorbs their group''s remaining members. Due to his heroic courage and indomitable spirit, Takemichi Hanagaki should have accomplished his goal of defeating the tragic fate awaiting his girlfriend, Hinata Tachibana.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bishoujo Senshi Sailor Moon Cosmos Movie', 'Movie', 2, 'Completed', '2023-06-09', '2023-06-30', '8', 'The final battle for the Sailor Guardians begins as they face Sailor Iron Mouse, Sailor Aluminum Siren, Sailor Lead Crow, Sailor Tin Nyanko and more.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seitokai Yakuindomo Movie', 'Movie', 1, 'Completed', '2017-07-21', NULL, '8', 'Ousai Academy was originally an all-girls high school. Due to the declining birth rates in recent years, it was converted into a co-ed school. The first year male students would find themselves surrounded by girls and unfortunately, Tsuda Takatoshi is one of them. What''s worse, he gets scolded on his first day by the student council president Shino Amakusa, which did not give a good first impression of him. Tsuda also meets the other student council members while getting scolded, and in the end, he gets late for class. As an apology for ruining his morning, Shino lets him join the student council for various of "reasons" and he accepts it, or rather, he''s forced to accept. Thus begins his days as Tsuda soon realizes that he''s the only normal student in Ousai Academy...', 339, 'https://cdn.myanimelist.net/images/anime/1655/114726.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Enen no Shouboutai: Ni no Shou', 'TV', 24, 'Completed', '2020-07-04', '2020-12-12', '8', 'After his confrontation in the Nether with his younger brother Shou, Shinra Kusakabe''s resolve to become a hero that saves lives from the flame terror strengthens. Finding a way to turn the Infernals back into people, unraveling the mystery of the Evangelist and Adolla Burst, and saving his mother and Shou—these are the goals Shinra has in mind. However, he has come to realize that attaining these goals will not be easy, especially with the imminent danger the Evangelist poses.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('New Initial D Movie: Legend 2 - Tousou', 'Movie', 1, 'Completed', '2015-05-23', NULL, '8', 'After witnessing the race between Takumi Fujiwara''s Toyota AE86 and Keisuke Takahashi''s Mazda RX7, Takeshi Nakazato from the Myougi Night Kids sends out a challenge to defeat the AE86 in a downhill battle. Despite his Nissan Skyline GT-R completely outclassing the AE86, Nakazato is told that he will never beat Takumi—a statement that enrages him. Believing that grip racing is far superior to flashy drift racing, Nakazato is dead set on defeating the AE86 to prove that he is the better racer.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Akachan to Boku', 'TV', 35, 'Completed', '1996-07-11', '1997-03-26', '8', 'Takuya Enoki is living a difficult life for a fifth grader. His mother passed away in a tragic car accident a few months ago, forcing him to pick up the slack and take care of his baby brother, Minoru, as his father works the endless hours typical of a Japanese salaryman.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jibaku Shounen Hanako-kun', 'TV', 12, 'Completed', '2020-01-10', '2020-03-27', '8', 'The famous Seven Mysteries that every school seems to have are a staple of Japanese urban legends. One of the most well-known of these tales is that of Hanako-san: the ghost of a young girl who haunts the school''s bathrooms.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchouten Kazoku', 'TV', 13, 'Completed', '2013-07-07', '2013-09-29', '8', 'Kyoto has been populated by groups of tanuki and tengu for years, living alongside humans who are oblivious to the existence of these creatures. Yasaburou Shimogamo is the third son of an influential tanuki family who spends his carefree days taking care of an old tengu, observing humans through his ability to shapeshift, and dealing with the mysterious woman named Benten.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Suzumiya Haruhi no Yuuutsu', 'TV', 14, 'Completed', '2006-04-03', '2006-07-03', '8', 'If a survey were conducted to see if people believed in aliens, time travelers, or maybe espers, most would say they do not; average high school student Kyon considers himself among the non-believers. However, on his first day of school, he meets a girl who soon turns his world upside down.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Go! Princess Precure', 'TV', 50, 'Completed', '2015-02-01', '2016-01-31', '8', 'Ever since she was young, Haruka Haruno has always aspired to become a princess. Despite being mocked for this seemingly childish wish, Haruka perseveres to make her dream a reality, ultimately culminating in her acceptance into the prestigious Noble Academy—the birthplace of people''s fantasies.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Danshi Koukousei no Nichijou Specials', 'Special', 6, 'Completed', '2012-04-03', '2012-09-04', '8', 'The clueless boys of Sanada North High School never lack a new topic to dissect. Questions about girls are endless, the true meaning of being a man could be hidden in questionable chivalry, and there might be a moral side to silly pranks. With a different predicament always ongoing, the daily lives of high school boys are anything but boring.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam: Senkou no Hathaway', 'Movie', 1, 'Completed', '2021-06-11', NULL, '8', 'Thanks to the sacrifices of war heroes like Amuro Ray, the Universal Century''s 105th year sees an era of hard-won but short-lived peace. The Earth Federation keeps a militaristic hold on the planet and its surrounding space colonies. Although Char Aznable''s rebellion against the neglectful Federation met its ultimate failure, his revolutionary philosophy of true freedom for all human beings lives on.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Capeta', 'TV', 52, 'Completed', '2005-10-04', '2006-09-26', '8', 'After losing his mother at a very young age, elementary school student Capeta Taira is forced to become more independent to avoid his father worrying for him. Working in a paving company, his father is often busy and has to work overtime to make ends meet. However, no matter how tough he acts in front of his father, Capeta is ultimately just a lonely kid with a rough life. In addition to his typical house duties, he has to deal with the bully Nobu Andou which makes him feel worse, despite support from his classmate, Monami Suzuki.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('91 Days', 'TV', 12, 'Completed', '2016-07-09', '2016-10-01', '8', 'As a child living in the town of Lawless, Angelo Lagusa has witnessed a tragedy: his parents and younger brother have been mercilessly slaughtered by the Vanetti mafia family. Losing everything he holds dear, he leaves both his name and hometown behind, adopting the new identity of Avilio Bruno.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Ball Z Special 2: Zetsubou e no Hankou!! Nokosareta Chousenshi - Gohan to Trunks', 'Special', 1, 'Completed', '1993-02-24', NULL, '8', 'It has been thirteen years since the Androids began their killing rampage and Son Gohan is the only person fighting back. He takes Bulma''s son Trunks as a student and even gives his own life to save Trunks''s. Now Trunks must figure out a way to change this apocalyptic future. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ansatsu Kyoushitsu: Deai no Jikan', 'Special', 1, 'Completed', '2014-11-09', NULL, '7', 'Koro-sensei reminisces about his first meeting with Karasuma, where they first butted heads and fought against each other, ultimately coming to respect one another. However, Karasuma eventually points out their actual meeting wasn''t nearly as eventful.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('SSSS.Dynazenon', 'TV', 12, 'Completed', '2021-04-02', '2021-06-18', '7', 'One day after school, first-year high school student Yomogi Asanaka comes across a starving man under a bridge. Introducing himself as Gauma, the strange drifter informs Yomogi that he is a "kaiju user," a person who deals with the "kaiju"—monsters who bring harm to the city and its citizens.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Digimon Adventure tri. 1: Saikai', 'Movie', 1, 'Completed', '2015-11-21', NULL, '7', 'The gate to the Digital World has been closed for three years. Taichi Yagami and his friends have since moved on, and now that he is in his second year of high school, it is time for him to grow up. While everyone else knows what they want to do with their lives, Taichi remains unsure. Meanwhile, the group drifts further apart as they follow their own paths.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tamayura: More Aggressive - Ichinichi dake no Shuugakuryokou, nanode', 'Special', 1, 'Completed', '2014-06-07', NULL, '7', 'Extra episode in the 7th Blu-ray and DVD volumes.', 999, 'https://cdn.myanimelist.net/images/anime/9/63207.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bleach Movie 1: Memories of Nobody', 'Movie', 1, 'Completed', '2006-12-16', NULL, '7', 'When a life ends, its soul departs to its final resting place known as the Soul Society. However, if a soul is left to wander in the human world for too long, it ends up turning into a corrupted "Hollow" that feeds on other souls. In such cases, spirits called "Soul Reapers" are needed to eliminate the Hollows and guide the lost souls to the Soul Society.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuusha-Ou GaoGaiGar Final Grand Glorious Gathering', 'TV', 12, 'Completed', '2005-04-11', '2005-06-27', '7', 'Following Gutsy Galaxy Guard''s victory over the Zonder Empire and the 31 Primevals, a new threat makes their appearance on Earth. GGG - with Guy Shishio and the newly-constructed GaoFighGar - team up with their French counterpart Chasseur to battle the evil organization BioNet. Among Chasseur''s ranks is Renais Cardiff Shishioh - a former BioNet cyborg with the relentless pursuit of destroying those who took away her humanity. But as GGG and Chasseur fight the BioNet, GGG''s bases around the world are suddenly attacked, and the recently-discovered "Q-Parts" and the original Gao Machines are stolen by Mamoru Amami, who has been abducted and cloned by an even greater threat known as the "Eleven Kings of Sol." Evicted from Earth by the United Nations, GGG must now travel to the far reaches of the galaxy to battle the Eleven Kings of Sol and save Mamoru before it''s too late.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shingeki no Kyojin: Ano Hi Kara', 'Special', 1, 'Completed', '2013-07-07', NULL, '7', 'Recap of the events in Shingeki no Kyojin that happened prior to episode 14.', 1105, 'https://cdn.myanimelist.net/images/anime/3/51715.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Grimm Meisaku Gekijou', 'TV', 24, 'Completed', '1987-10-21', '1988-03-30', '7', 'The series consists of mostly stand-alone episodes which retell different fairy or folk tales.  Despite the title, they are not all based on fairy tales collected by the Grimm Brothers.', 607, 'https://cdn.myanimelist.net/images/anime/1562/96991.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hetalia: The Beautiful World Specials', 'Special', 4, 'Completed', '2013-04-24', '2013-10-30', '7', 'Special episodes released with the Hetalia: The Beautiful World BD/DVDs.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yokohama Kaidashi Kikou', 'OVA', 2, 'Completed', '1998-05-21', '1998-12-02', '7', 'After a disaster leaves the world in a state of decline, the remaining human population lives out their lives peacefully and quietly in the twilight of the human age. Alpha Hatsuseno is an android who works at a cafe bordering Yokohama that rarely gets visitors, and is waiting for her owner to return.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aggressive Retsuko (ONA) 5th Season', 'ONA', 10, 'Completed', '2023-02-16', NULL, '7', 'The red panda accountant Retsuko and her hyena coworker, Haida, have finally started dating. Things seem to be looking up in Retsuko''s life; however, Haida is now grappling with unemployment and an evolving gaming addiction. As Haida attempts to keep his struggles from his girlfriend, cracks begin to form in their relationship. Moreover, Haida is evicted from his apartment and seeks refuge in an internet cafe, where he meets his online friend, a skunk named Shikabane.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meng Qi Shi Shen: Zaijie Liangyuan', 'ONA', 12, 'Completed', '2021-10-09', '2021-12-18', '7', 'Ye Jiayao is a modern-day celebrity chef who loves traditional Chinese recipes and often experiments with them. However, when a food experiment goes wrong, she travels back in time to the ancient times, where she becomes the daughter of a magistrate with the name Ye Jin Xuan. When she wakes up she is suddenly kidnapped to Hei Fang Camp where she meets the leader of the bandits, Xia Chun Yu, the young master of the Jing An Marquis manor, who is actually an undercover agent for the king. He had infiltrated the Black Wind Fortress bandits to investigate a plot to overthrow the king. The two then get engaged in a fake marriage. Ye Jia Yao starts to win over hearts, including Xia Chun Yu''s, with her superb cooking skills and modern street smarts.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tennis no Oujisama: Another Story II - Ano Toki no Bokura', 'OVA', 4, 'Completed', '2011-08-26', '2011-10-26', '7', '1. Tanjou! Buchou Shiraishi Kuranosuke
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pretty Rhythm: Aurora Dream', 'TV', 51, 'Completed', '2011-04-09', '2012-03-31', '7', 'Aira Harune, a clumsy yet happy-go-lucky girl, is suddenly dragged into the popular world of Prism Shows—an idol show based on figure skating, where performers called "Prism Stars" wear outfits encased in Prism Stones and perform stylistic Prism Jumps. Captivated by the dazzling fashion and gorgeous Prism Jumps, Aira decides to become a Prism Star herself.  
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Samurai 7', 'TV', 26, 'Completed', '2004-06-12', '2004-12-25', '7', 'In the far distant future, on a planet that might have been called "earth", there was a war between samurai who mechanized their bodies. After the long war, people enjoyed a modest peace.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toradora!: Bentou no Gokui', 'Special', 1, 'Completed', '2011-12-21', NULL, '7', 'An unaired episode included in the Blu-ray box set.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saihate no Paladin: Tetsusabi no Yama no Ou', 'TV', 12, 'Completed', '2023-10-07', '2023-12-23', '7', 'Second season of Saihate no Paladin.', 621, 'https://cdn.myanimelist.net/images/anime/1031/138515.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Genjitsu Shugi Yuusha no Oukoku Saikenki Part 2', 'TV', 13, 'Completed', '2022-01-09', '2022-04-03', '7', 'Together with his talented aides, the "Realist Hero" Kazuya Souma continues his quest of reinvigorating the Elfrieden Kingdom through administrative reform. Having successfully conquered Van—the capital city of the Principality of Amidonia—Kazuya now faces the envoy from Gran Chaos Empire, who wishes to impose punishment for breaching the ban on war established by the Mankind Declaration Treaty. Despite the dire situation, Kazuya sees a path to avoid unnecessary conflict whilst gaining new allies. With his plan being seemingly perfect, the only barrier to success is gaining approval from the envoy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mini Dragon Specials', 'Special', 8, 'Completed', '2021-07-08', '2022-01-19', '7', 'Includes 3 special Mini Dragon episodes released within Kobayashi-san Chi no Maid Dragon S''s broadcast period and 5 BD/DVD extras.', 494, 'https://cdn.myanimelist.net/images/anime/1100/116698.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bai Yao Pu: Luoyang Pian', 'ONA', 12, 'Completed', '2025-08-08', '2025-09-05', '7', 'Fairies Albums Luoyang Arc follows Tao Yao, Mister Liu, Moya, and Gun Gun as they set out on a quest to find the missing Fairy Album in Luoyang City. Jiang Jun, Xian Shu, Fo Yan, Xuan Jiao, Ying Yuan, Ren Qu, and Xia Guai are among the many unusual and enigmatic creatures they meet along the route. They also face off against the formidable ultimate boss behind the Fairy Album in an exciting battle of cunning. There''s a voyage of mystery, legend, and imagination ahead!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Burn the Witch #0.8', 'Special', 1, 'Completed', '2023-12-29', NULL, '7', 'Prequel to Burn the Witch.', 870, 'https://cdn.myanimelist.net/images/anime/1522/139282.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cocoon: Aru Natsu no Shoujo-tachi yori', 'Special', 1, 'Completed', '2025-03-30', NULL, '7', 'San and Mayu are two schoolgirls living in Okinawa during the closing months of the Pacific War. Together with their classmates, the two friends are drafted into the war effort as nurses for wounded soldiers. When ordered to die for their country, the remaining members of the group escape only to face the harsh environment of a tropical paradise that has become a hellish battlefield.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maou 2099', 'TV', 12, 'Completed', '2024-10-13', '2024-12-29', '7', 'Five hundred years ago, the fantasy world of Alneath was torn apart by a war between magically gifted immortals and mortals armed with magical artifacts. The conflict came to an end when mortals'' hero, Gram, slayed the Demon Lord Veltol Velvet Velsvolt. In 2099, the world looks a bit different. Alneath and technologically advanced Earth have fused in an event known as Fantasion. Immortals have been hunted down to near extinction, and technological implants called Familia allow mortals to use magic.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jintian Kaishi Zuo Mingxing', 'ONA', 13, 'Completed', '2019-12-27', '2020-03-20', '7', 'Qin Ze is a young man who has just entered university. From an early age he excels in singing but following a trauma, he is no longer able to sing in public.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Anne Happy♪', 'TV', 12, 'Completed', '2016-04-07', '2016-06-23', '7', 'Tennomifune Academy is an elite institution for the best and the brightest, with the exception of Class 1-7, the so-called "Happiness Class." Each member of the classroom copes with personal misfortunes, and the special class is geared to help them move past their issues and find true happiness. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sakura Trick', 'TV', 12, 'Completed', '2014-01-10', '2014-03-28', '7', 'Having been best friends since middle school, Haruka Takayama and Yuu Sonoda plan to attend Misato West High School together. However, despite being assigned to the same class, a cruel twist of fate has them seated on the opposite ends of their classroom! To make matters worse, their school will shut down in three years, making them the final intake of first-year students. Undeterred by this chain of unfortunate events, Haruka is set on sticking with Yuu, striving to create many wonderful memories with her.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Crayon Shin-chan Movie 16: Chou Arashi wo Yobu Kinpoko no Yuusha', 'Movie', 1, 'Completed', '2008-04-19', NULL, '7', 'A comical fantasy adventure on a fight against invaders from another world. The ruler of dark world "Don Kurai," Dark, plots to dominate the human world. There is a legend about three treasures and a hero in Don Kurai, and Dark takes over one of the three treasures, a bell of copper, but a man sent other two treasures (a sword of gold and a shield of silver) to the human world. Shinnosuke falls into Dark''s trap and opens the door between the human world and Don Kurai, but he becomes the hero selected by the spear of gold. With the power of a girl from Don Kurai, Mata Tami, the Nohara Family transform into various things and fight against Dark.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sonic★the★Hedgehog', 'OVA', 2, 'Completed', '1996-01-26', NULL, '7', 'Living in the wreckage of a rusty old airplane on the shimmering shores of South Island, Sonic the Hedgehog and his buddy Miles "Tails" Prower have not a care in the world. The president of Planet Freedom urgently summons the duo, but trouble is afoot when Sonic and Tails instead find the good-for-nothing Dr. Eggman lounging about his office as if it were his own.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Taiho Shichau zo: Full Throttle - Watashitachi no Iru Basho', 'Special', 1, 'Completed', '2008-08-22', NULL, '7', 'Rounding off season 3, Natsumi and Miyuki reminiscince about their lives at Bokuto station while hearing from people they''ve met through work. (This is limited to characters they''ve met in season 3.)
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Crayon Shin-chan Movie 03: Unkokusai no Yabou', 'Movie', 1, 'Completed', '1995-04-15', NULL, '7', 'A member of the Time Patrol finds out that there is a disturbance in Japan, 1570. While heading to that particular time and location to investigate, she is attacked and ends up stuck underground the Nohara residence at the end of the 20th century Japan. Having limited resources at hand, she is forced to ask for the help of the Nohara family. Together they go back in time and meet with a samurai named Fubuki-maru who believes that they are the legendary three persons and dog whom someone from her family would eventually meet in a crucial moment. The lonely samurai asks for their assistance in defeating the man that possesses strange magical powers, the sinister Unkokusai lord.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kinnikuman II Sei: Ultimate Muscle', 'TV', 13, 'Completed', '2004-04-08', '2004-07-01', '7', 'The Chojin Crown, the tournament which Mantaro (Kid Muscle) reluctantly participates in. After going along with the obstacles (most of which were created to try and eliminate him), he qualified.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Love Live! School Idol Project Recap', 'Special', 1, 'Completed', '2013-12-25', NULL, '7', 'Narrated recap of the Love Live! School Idol Project series included on the official  Blu-ray fandisc release.', 974, 'https://cdn.myanimelist.net/images/anime/4/57505.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Black Jack (TV): Hizouban Specials', 'Special', 2, 'Completed', '2006-07-17', NULL, '7', 'This was originally from the Black Jack (2004), but weren''t aired then, only later. There are two episodes in this:
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hyper Police', 'TV', 25, 'Completed', '1997-04-04', '1997-09-26', '7', 'Sasahara Natsuki is a poor bounty hunter in a world where monsters and humans live together. Most of her cases involve monsters infringing upon the rights of humans, who are protected by law from their generally more powerful neighbors. Being half-human and half cat-beast, Natsuki straddles the two societies and tries to understand and respect both while enforcing the law. She is assisted by a werewolf named Batanen who is afraid to admit he loves her; another werewolf named Tommy; and a Kyubi fox demon named Sakura who has her own plans--which include eating Natsuki to complete her her nine tails and thereby her magical powers. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kachou Ouji', 'TV', 13, 'Completed', '1999-07-08', '1999-10-07', '7', 'Oji Tanaka has a wife, a child and a mundane job as a salary man in Tokyo''s modern society. But life wasn''t dull for him to begin with; 15 years ago, he was known as "Gabriel", leader of a short-lived heavy metal band called Black Heaven. Oji''s life gets a sudden change in direction when he is invited by a mysterious blonde woman named Layla to pick up his Gibson Flying V and once again display his "legendary" guitar skills, not knowing that his music generates power for a massive weapon in an intergalactic war. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Renkin San-kyuu Magical? Pokaan', 'TV', 12, 'Completed', '2006-04-05', '2006-06-21', '7', 'Renkin San-kyuu Magical? Pokaan follows the daily lives of four young girls. There is just one catch: they are anything but normal. This group of friends—the energetic werewolf Liru, the joyful witch-in-training Uma, the motherly android Aiko, and the seductive vampire Pachira—are actually princesses from the netherworld who have traveled to the human world in search of a new home. Unfortunately, their naivety and severe lack of knowledge make living peacefully among earthlings much more difficult than they imagined. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Digimon Tamers: Boukensha-tachi no Tatakai', 'Movie', 1, 'Completed', '2001-07-14', NULL, '7', 'Takato and Guilmon go on vacation to Okinawa and meet a fellow tamer, Minami. Back in Japan, a popular computer pet suddenly becomes a virus, infecting all of the computers who have it. As the virus spreads, Takato tries to figure out why digimon are all attacking his new friend, and what her connection is to the virus.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kawaii dake ja Nai Shikimori-san', 'TV', 12, 'Completed', '2022-04-10', '2022-07-10', '7', 'Yuu Izumi leads a high school life filled with one mishap after another. No matter how improbable the situation, unfortunate events strike him at every turn. In possession of such terrible luck, Izumi enters his second year with a single wish in mind—to spend more time with his affectionate girlfriend, Micchon Shikimori.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The iDOLM@STER Million Live!', 'TV', 12, 'Completed', '2023-10-08', '2023-12-24', '7', 'Mirai Kasuga, who wants to carry on a dream she has yet to see. Shizuka Mogami, who yearns to be an idol and is shaken. Tsubasa Ibuki, who does not know what she can be serious about.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kiddy Grade: Ignition', 'Movie', 1, 'Completed', '2007-04-07', NULL, '7', 'A recap of the original anime''s first quarter.', 341, 'https://cdn.myanimelist.net/images/anime/9/23600.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Air Master', 'TV', 27, 'Completed', '2003-04-02', '2003-10-01', '7', 'A former gymnast, Aikawa Maki has turned her skills to a different way of life—street fighting. The only thing that truly makes her feel alive is violence. With amazing power and grace, she fights opponent after opponent, repeatedly demonstrating the gymnastic talent that earns her her nom de guerre, "Airmaster."', 1030, 'https://cdn.myanimelist.net/images/anime/2/21019.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon Diamond & Pearl Specials', 'Special', 2, 'Completed', '2011-02-03', NULL, '7', 'One-hour special split into 2 episodes during the airing of Pokemon Best Wishes! featuring the old characters from the Diamond &amp; Pearl series Hikari and Takeshi with their Pokemon.', 621, 'https://cdn.myanimelist.net/images/anime/1978/142700.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lupin III: Tenshi no Tactics - Yume no Kakera wa Koroshi no Kaori', 'Special', 1, 'Completed', '2005-07-22', NULL, '7', 'Stolen from the famous "secret" Air Force base, Area 51, Lupin''s most recently stolen treasure holds a secret. Four "Bloody Angels," the toughest women Lupin has ever faced, want the treasure for their own terrorist purposes. Meanwhile Zenigata teams up with a female police officer to hunt Lupin and the terrorists down.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('SF Saiyuuki Starzinger', 'TV', 73, 'Completed', '1978-04-02', '1979-08-26', '7', 'The Great Planet is dying, since its Queen is old and powerless... and the universe will perish along with it. Princess Aurora of the Moon volunteers to become the new Queen, so she must set out in a dangerous travel... along with her friends and escorts: the powerful Cyborgs Jan Kogo, Sa Jogo and Don Hakka. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('.hack//Sign', 'TV', 26, 'Completed', '2002-04-04', '2002-09-26', '7', 'A young wavemaster, only known by the alias of Tsukasa, wakes up in an MMORPG called The World, with slight amnesia. He does not know what he has previously done before he woke up. In The World, the Crimson Knights suspects him of being a hacker, as he was seen accompanying a tweaked character in the form of a cat. Unable to log out from the game, he wanders around looking for answers, avoiding the knights and other players he meets along the way.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sugar Sugar Rune: Les deux sorcières', 'ONA', 1, 'Completed', '2025-07-05', NULL, '7', 'A 20th anniversary commemorative short for Sugar Sugar Rune.', 477, 'https://cdn.myanimelist.net/images/anime/1182/150986.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Digimon Adventure 25-shuunen Kinen PV: Digimon Adventure - Beyond', 'Special', 1, 'Completed', '2025-03-20', NULL, '7', 'A PV to commemorate the 25th anniversary of Digimon Adventure.', 1141, 'https://cdn.myanimelist.net/images/anime/1537/148675.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ore no Imouto ga Konnani Kawaii Wake ga Nai: SD Chara ni Yoru Character Commentary', 'Special', 16, 'Completed', '2010-12-22', '2011-07-27', '7', 'Special episodes from the BD/DVDs.', 397, 'https://cdn.myanimelist.net/images/anime/8/28061.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lupin III: Ai no Da Capo - Fujiko''s Unlucky Days', 'Special', 1, 'Completed', '1999-07-30', NULL, '7', 'When Fujiko acquires and memorizes papers called the Columbus Files, she is attacked and loses her memory. Lupin, a treasure hunter named Rosaria, and the cackling villain Nazaroff all pursue Fujiko, as she is the only key to the location of Columbus'' Egg, a treasure connected to the mysterious Orgone Energy. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Asobi ni Iku yo!: Asobi ni Oide', 'OVA', 1, 'Completed', '2011-06-15', NULL, '7', 'Ever since Eris, a Catian alien from another planet, came to Earth and moved to Kio Kakazu''s house, there has not been a dull moment. Wanting to learn more about Earth and its inhabitants, she begins investigating human pastimes by trying out different board games with Kio and other girls who have their eyes on the boy. To spice things up, the group decides to have various humiliating materials as the prizes. Even though the stakes are high, they are sure to have fun together.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Munto', 'OVA', 1, 'Completed', '2003-03-18', NULL, '7', 'Above Earth, invisible to humans, float the Heavens—a collection of floating island kingdoms supported by the magic of their godlike inhabitants. The mysterious power source known as Akuto enables this magic to exist, but this is quickly running out. In response to this energy crisis, most of the kingdoms in the Heavens agree to use the minimum amount of Akuto required to sustain themselves, except for the Magical Kingdom. The leader of this kingdom, the Magical King Munto, believes that Akuto can be replenished if he travels to Earth and meets a mysterious girl shown to him by a seer. While Munto sets off on the dangerous journey, the other kingdoms attempt to destroy the Magical Kingdom and acquire the remaining Akuto for themselves.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Given: 10th Mix', 'OVA', 1, 'Completed', '2025-10-01', NULL, '7', 'A brilliant epilogue depicting the dazzling "present" of those who have grown since "those days" and the important people surrounding them!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hotel Inhumans', 'TV', 13, 'Completed', '2025-07-06', '2025-09-28', '7', 'Ikurou Hoshi and Sara Haizaki are the concierges at Hotel Inhumans, a hotel that specifically caters to assassins. They fulfill all the requests their guests may ask of them, never uttering the word "no." While Ikurou specializes in research into their clients'' backgrounds and careers, Sara protects the hotel with skills to match that of the hotel''s patrons.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimi ni Todoke: Digest Eizou', 'ONA', 1, 'Completed', '2023-12-30', NULL, '7', 'A video of series highlights looking back at major moments from the first two seasons involving Kazehaya, Sawako and the other characters has been released! Reexperience each scene with newly produced visuals.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gaishi Dizun', 'ONA', 52, 'Completed', '2023-07-30', '2024-01-21', '7', 'In ancient times, saints fought for hegemony. A young man known as the "Sleeping God" turned out to be a blessing in disguise and opened up a heaven-defying skill. From then on, a genius with unparalleled physical strength dominated the world, slashed the stars with his sword, and thousands of geniuses crawled and trembled under his feet. In a world where heroes are rising, I am the only one who dominates.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zhongguo Qi Tan', 'ONA', 8, 'Completed', '2023-01-01', '2023-02-12', '7', 'A collection of eight short stories about Chinese folklore "monsters."', 792, 'https://cdn.myanimelist.net/images/anime/1099/131981.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shy', 'TV', 12, 'Completed', '2023-10-03', '2023-12-19', '7', 'In the middle of the 21st century, powerful individuals with superhuman strength appeared all across the world. These people who wore flashy clothes and performed incredible feats in the name of peace became known as heroes—symbolic figures of the nation they came from. In Japan, 14-year-old middle school student Teru Momijiyama is widely known by her secret identity as Japan''s hero, Shy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Muhyo to Rouji no Mahouritsu Soudan Jimusho', 'TV', 12, 'Completed', '2018-08-03', '2018-10-19', '7', 'Are you a victim of unwanted spirit possession? Is there a ghost you need sent up and away...or down to burn for all eternity? If the answer is yes, then you need Muhyo and Roji, experts in magic law. Serving justice to evil spirits is their specialty.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sword Art Online II', 'TV', 24, 'Completed', '2014-07-05', '2014-12-20', '7', 'A year after escaping Sword Art Online, Kazuto Kirigaya has been settling back into the real world. However, his peace is short-lived as a new incident occurs in a game called Gun Gale Online, where a player by the name of Death Gun appears to be killing people in the real world by shooting them in-game. Approached by officials to assist in investigating the murders, Kazuto assumes his persona of Kirito once again and logs into Gun Gale Online, intent on stopping the killer.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Okusama ga Seitokaichou! Seitokaichou to Ofuro Asobi', 'OVA', 1, 'Completed', '2016-01-27', NULL, '7', 'The student council president, Ui Wakana, organizes a campaign encouraging the act of holding hands. While Ui hangs up posters, her husband and vice president, Hayato Izumi, injures his hand when he tries to save her from falling. Feeling guilty and wanting to make up for the incident, Ui assists Izumi with bathing—even when he insists that he does not need help.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Long Riders!', 'TV', 12, 'Completed', '2016-10-08', '2017-02-05', '7', 'Falling in love at first sight with a collapsible bicycle outside the station, Ami Kurata, first-year university student empties her account without a second thought and buys the bicycle. Now she enjoys weekend cycling trips with Aoi, her childhood friend, and Hinako, a senior at her university. "Owning a road bike may change your view of the world completely." Prompted by the comment, Ami purchased a road bike, and she is really impressed with the traveling performance. As soon as she places her feet on the pedals and presses down, everything about riding a road bicycle—the lightness of the pedal, the speed, the acceleration—is nothing like she has ever experienced. Ami''s cycle life gets going with the new road cycle as her partner!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Houkago Saikoro Club', 'TV', 12, 'Completed', '2019-10-03', '2019-12-19', '7', 'Miki Takekasa is an introverted high schooler who does not socialize with her classmates. However, she wants to know what "fun" really is, waiting for someone who could help her understand its true meaning. One day after school, she crosses paths with her classmate Aya Takayashiki, who takes her on a little adventure. Miki discovers wonders she had never seen before, opening a way to change her withdrawn life.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Caramel Honey', 'ONA', 30, 'Completed', '2018-06-08', '2018-08-24', '7', 'Ayato transfers into a new school hoping for a fresh start.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aho Girl', 'TV', 12, 'Completed', '2017-07-04', '2017-09-19', '7', 'Yoshiko Hanabatake is an idiot beyond all belief. Somehow managing to consistently score zeroes on all of her tests and consumed by an absurd obsession with bananas, her senseless acts have caused even her own mother to lose all hope. Only one person is up to the task of keeping her insanity in check: childhood friend Akuru "A-kun" Akutsu.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou Shoujo Lyrical Nanoha ViVid', 'TV', 12, 'Completed', '2015-04-03', '2015-06-19', '7', 'Vivio Takamachi, a Sankt Kaiser royalty of ancient Belka, was previously subjected to mistreatment. Fortunately, she now lives a peaceful life with family and friends while practicing martial arts with her coach, Nove Nakajima. However, Vivio soon becomes the target of the mysterious fighter Heidi E. S. Ingvalt, who demands Nove to reveal the location of the ancient Belkan royals. Refusing to disclose this information, Nove finds herself in a losing battle but Heidi soon falls unconscious. In addition, Nove discovers Heidi''s true identity to be a middle school student named Einhald Stratos.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Victory Gundam', 'TV', 51, 'Completed', '1993-04-02', '1994-03-25', '7', 'In the year 153 of the Universal Century, the tyrannical Zanscare Empire has taken hostile control over Side 2, a space colony outside of Earth''s orbit. Following in the footsteps of the long expired Principality of Zeon and the more recent Crossbone Vanguard, Zanscare rules over its subjects with cruelty, routinely using a large guillotine for public executions.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Strike Witches: 501 Butai Hasshin Shimasu! Movie', 'Movie', 1, 'Completed', '2019-10-04', NULL, '7', 'Yoshika Miyafuji spends her days peacefully after returning to her hometown. Her former superior officer Mio Sakamoto and others arranged for Yoshika to study abroad at a medical school in Europe. Yoshika returns to Europe with Shizuka Hattori, who was Sakamoto''s student at the naval academy. As Yoshika returns to Europe and new signs of Neuroi emerge, the other former members of the 501st Joint Fighter Wing, who were scattered in various locations, also begin to gather again. A powerful Neuroi then appears before Yoshika and Shizuka.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ushinawareta Mirai wo Motomete: Ushinawareta Natsuyasumi wo Motomete', 'Special', 1, 'Completed', '2015-08-01', NULL, '7', 'Upon regaining her senses, Yui Furukawa discovers that the current day is July 13—a starting point that she has never experienced prior. However, despite the unfamiliar circumstances, she resolves to spend her summer vacation with the other members of the Astronomy Club at Nagisa Hanamiya''s family villa. The house and its surrounding area have a rich history; a renowned scientist, Nagisa''s great-grandmother researched and developed technology at the nearby military manufacturing plant.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shinmai Maou no Testament Specials', 'Special', 6, 'Completed', '2015-03-27', '2015-08-28', '7', 'Specials included on the Blu-ray/DVD volumes. Chibi versions of Mio and Maria narrate Basara''s various erotic encounters.', 705, 'https://cdn.myanimelist.net/images/anime/1815/109046.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seikaisuru Kado', 'TV', 12, 'Completed', '2017-04-07', '2017-06-30', '7', 'Cool-headed and rational, Koujirou Shindou is a government official and master negotiator with a well-earned reputation. While departing on a business trip, a giant cube materializes and his plane is taken undamaged into the mysterious, indestructible structure.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimi to Boku no Saigo no Senjou, Aruiwa Sekai ga Hajimaru Seisen', 'TV', 12, 'Completed', '2020-10-07', '2020-12-23', '7', 'A force known as Astral power permeates throughout the world, wielded by astral mages. Fearing its destructive power, the "Empire" persecutes those who show their abilities. The tormented mages then founded the Nebulis Sovereignty to flee from their oppressors. Since then, the two nations have been in bitter conflict, the war still going strong for more than a century.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yakeato no, Okashi no Ki', 'Special', 1, 'Completed', '2006-08-15', NULL, '6', 'The fifth film in Shin-Ei''s series of annual WWII themed anime television movies for children "Sensou Douwa" (war story).
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xinghe Zhizun', 'ONA', 45, 'Completed', '2021-06-10', '2021-10-30', '6', 'Once the most dazzling blue earth star of the first door of the star clan, accidentally got the world of the treasure "star map," attracted the eyes of the lord of the world. In order to get the star map, the lord of the world induces the high level of the star clan to go to the Holy Star domain and imprisons them in the "Holy Star Domain." In order to regain his former glory, Chu Xinghe, the younger suzerainty, seeks the imprisoned father and the high-level of the star clan, and leads several disciples under the gate to break through the twelve star circles, defeat the twelve star spirits of the Lord of the world, and eventually, rescue his father and all the people of the star clan from the Lord of the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Houkago Midnighters', 'Movie', 1, 'Completed', '2012-08-25', NULL, '6', 'Mako, Miko, and Mutsuko are three young girls visiting St. Claire Elementary, a school filled with strange legends. They have an abrupt encounter with Kunstrijk, a human body anatomy model, and Goth, a skeleton model. Both haunt the soon-to-be-demolished science room. Seeking revenge for being vandalized by the three girls, Kunstrijk invites them to the school''s midnight party in order to scare them. Together, the five go on a quest to collect three mythical medals that can grant a wish and hopefully save the science room.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Honoo no Labyrinth', 'OVA', 2, 'Completed', '2000-09-25', '2000-12-21', '6', 'Meet Galan, a Russian spastic geek who''d do anything to be a real, live samurai. But that''s just an impossible dream... or is it? When his friend Natsu, who is a successor of Japanese emigrants family, gives him the gift of an ancient sword, strange events unfold, and even stranger people drop out of the sky to attack. Now Galan must overcome his ineptitude and join a bunch of beautiful women in a wacky romp through a kingdom that time forgot. Hey, what could be better?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga Ojousama Densetsu Yuna: Shinen no Fairy', 'OVA', 3, 'Completed', '1996-12-21', '1997-05-21', '6', 'Just when everything seems peaceful again for Yuna and her friends, a new enemy appears in the form of three robotic sisters. Yuna must once again become the Savior of Light to fight this strong, new evil.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saikin, Imouto no Yousu ga Chotto Okashiinda ga.', 'TV', 12, 'Completed', '2014-01-04', '2014-03-23', '6', 'Saikin, Imouto no Yousu ga Chotto Okashiinda ga. follows a family just starting to rebuild. When they marry, Mr. and Mrs. Kanzaki bring a teenage son and daughter along for the ride. But high school freshman Mitsuki Kanzaki is less than thrilled. Stinging from a history of absent and abusive father figures, she is slow to accept her stepfather and stepbrother.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tales of Eternia The Animation', 'TV', 13, 'Completed', '2001-01-08', '2001-03-26', '6', 'In order to prevent the catastrophe called the Grand Fall, Rid Hershel and his companions Farah, Keel and Meredy have obtained the three Greater Spirits ("Craymels" in the game version) of Inferia. En route to Mount Farlos, Rid is kidnapped by the bounty hunter Marone Blucarno, and the party is compelled to head to Belcarnu, an archipelago far from the major cities of Inferia. A series of adventures forces them to remain on the islands, where a more immediate threat to Inferia sleeps.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Photokano', 'TV', 13, 'Completed', '2013-04-05', '2013-06-28', '6', 'High school student Kazuya Maeda finds his daily life dull and meaningless. This changes right before the end of his summer break when he receives an old camera from his father. Initially hesitant, Kazuya decides to experiment with photography and starts looking for potential models for his pictures.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Battle Spirits: Heroes', 'TV', 50, 'Completed', '2011-09-18', '2012-09-02', '6', 'Like every card game enthusiast, Hajime Hinobori has always wanted to see the Spirits from his cards come to life and witness them in real combat. This dream is successfully realized by Hajime''s scientist parents, who develop an augmented reality system that revolutionizes the competitive scene of Battle Spirits. Curious players from across the globe travel to partake in this innovative battle system.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaze no Tairiku', 'Movie', 1, 'Completed', '1992-07-18', NULL, '6', 'Three adventurers—a warrior, a priest, and a young woman—traverse a land devastated by centuries of environmental calamities searching only for a way to survive. In their journeys they stumble across first the remains of a band of desperate treasure-hunters, and then the treasure they were seeking: Azec Sistra, the legendary City of the Dead. Unfortunately, the bandits responsible for slaughtering the treasure-hunters have also found their way to the city, but more worrisome still are the guardians which protect Azec Sistra from those who would violate the spirits at rest there...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Submarine Super 99', 'TV', 13, 'Completed', '2003-05-08', '2003-07-31', '6', 'Dr. Oki , the genius scientist who designed a new type of submarine is missing. His son, Susumu, smells an evil scheme of unknown group. He knows everything of his father''s submarine called "Super 99" – equipment, weapons, functions and capacity. Susumu thinks that to find his father is to reveal the secret organization, Helmet Party, and stop their conspiracy. With the help of his friends and Marine Corps, he sets out to an underwater quest, not knowing how dangerous his endeavour is…
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pandora to Akubi', 'Movie', 2, 'Completed', '2019-04-05', NULL, '6', 'Pandora and Akubi form a team to find "The Pieces of Calamity" that have a great power to destroy the whole world. To find the pieces that have been scattered around various places, the two travel beyond dimensions.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Brain Powerd', 'TV', 26, 'Completed', '1998-04-08', '1998-11-11', '6', 'In the not so distant future much of the earth has been submerged under the sea or destroyed by earthquakes. At the center of the turmoil is the mysterious Orphan. Orphan may or may not be the original cause of the cataclysms. Orphan''s goal is to raise a ship hidden deep beneath the sea to the surface, but doing so would result in the destruction of all humans except for the small number which are loyal to Orphan.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Senkou no Night Raid: Aruku Hako', 'Special', 1, 'Completed', '2010-12-22', NULL, '6', 'Picture drama included with the 7th volume of the Blu-ray.', 14, 'https://cdn.myanimelist.net/images/anime/7/28136.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yami Shibai 10', 'TV', 13, 'Completed', '2022-01-10', '2022-04-04', '6', 'Tenth season of Yami Shibai', 403, 'https://cdn.myanimelist.net/images/anime/1760/120105.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yu☆Gi☆Oh! Go Rush!!', 'TV', 151, 'Completed', '2022-04-03', '2025-03-30', '6', 'After inheriting the company from their parents, siblings Yuuhi and Yuamu Oudou have started to work at the Alien Trouble Consultancy, an organization that hunts aliens. Although they have never encountered aliens before, Yuuhi is desperate to meet one as he believes that an alien has stolen his important item, called the "Earthdama".
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Minori Scramble!', 'OVA', 1, 'Completed', '2012-02-15', NULL, '6', 'Tamaki is an elementary school girl. Her father Dr. Yagiyama loves penguins and his excessive lectures about penguins makes Tamaki hate them. In order to get rid of her hatred of penguins, he engineers the penguin-roid "Minori". Tamaki and Minori run about the neighborhood to solve troubles caused by her father.', 1192, 'https://cdn.myanimelist.net/images/anime/6/31903.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Psychic Academy', 'TV', 24, 'Completed', '2002-03-29', '2002-09-13', '6', 'Insecure Ai Shiomi begins attending the prestigous Psychic Academy for psychically gifted students, following in the footsteps of his legendary older brother.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Manyuu Hikenchou', 'TV', 12, 'Completed', '2011-07-11', '2011-09-26', '6', 'The Edo period of Japan gave rise to a clan of warriors with a very specialized, magical skill. The clan was known as the Manyuu, and the skill was the ability to administer a sword strike that could shrink the size of a woman''s breasts. This might not seem like an ability that could exert power over a land, but in Manyuu Hikenchou, large breasts denote status, wealth, fame, and influence.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('VitaminX Addiction', 'OVA', 3, 'Completed', '2011-08-26', '2011-10-21', '6', 'The story is set at Seitei Gakuen, an elite private academy that teaches every level from kindergarten until college in Tokyo. A new female teacher named Minami Yuuri is starting her second year of teaching here, and she is now moving up from teaching middle school students to the assignment she had sought after: grammar for high school students. Unfortunately, she gets assigned to class 3-E. The class, called "Class X," is an infamous group of seniors who lack study skills; it is said that all of their previous teachers have retired due to ulcers or neurosis. Minami must try to reach out to these students, including the six leaders of the class "B6" (Baka 6), and get them into college.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchuu Majin Daikengou', 'TV', 26, 'Completed', '1978-07-27', '1979-02-15', '6', 'Giant robot Daikengo flies through space to re-establish galactic peace; on-board prince Ryger, who ran away from his planet Emperius to defeat the menace out of his reign borders, in order to save his people; Cleo, corrupted prime minister''s daughter, help him along with two nice little robots, Anike and Otoke. They fight evil Lady Baracross, leading invasion forces, with her assistant Roboleon, wearing a Napoleon style hat. Daikengo is the first robot with scuttles on his mouth. When he opens them, his vampire style teeth are shown and he can spit fire.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mai no Mahou to Katei no Hi', 'Special', 1, 'Completed', '2011-02-20', NULL, '6', 'The main character Tatsumi Mai is a girl who uses magic to understand the feelings of people.', 653, 'https://cdn.myanimelist.net/images/anime/1475/127171.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sore Ike! Anpanman: Niji no Pyramid', 'Movie', 1, 'Completed', '1997-07-26', NULL, '6', '9th Anpanman short movie.', 990, 'https://cdn.myanimelist.net/images/anime/12/26142.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kanchigai no Atelier Meister Mini Anime', 'ONA', 14, 'Completed', '2025-04-06', '2025-06-27', '6', 'Mini anime of Kanchigai no Atelier Meister: Eiyuu Party no Moto Zatsuyougakari ga, Jitsu wa Sentou Igai ga SSS Rank Datta to Iu Yoku Aru Hanashi.', 39, 'https://cdn.myanimelist.net/images/anime/1949/149094.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yami Shibai 14', 'TV', 13, 'Completed', '2025-01-06', '2025-04-07', '6', 'Fourteenth season of Yami Shibai.', 403, 'https://cdn.myanimelist.net/images/anime/1811/146726.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('9: Ruler''s Crown', 'TV', 13, 'Completed', '2025-07-05', '2025-09-27', '6', 'While helping out at an anime convention to promote his city, high school student Kakeru Niimi is caught up in a sudden earthquake. During the emergency, he ends up entering a shrine where he sees a peculiar relic shatter. The very next day, his classmate Miyako Kujou, who was cosplaying at the event, worries that she has been cursed as a result of the earthquake, but Niimi brushes her suspicions off.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jantama Kan!!', 'ONA', 13, 'Completed', '2024-04-25', '2024-07-18', '6', 'Sequel to Jantama Pong☆.', 57, 'https://cdn.myanimelist.net/images/anime/1551/142498.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsugu Tsugumomo Mini Anime Specials', 'Special', 8, 'Completed', '2020-06-10', '2020-09-09', '6', 'Special episodes of Tsugu Tsugumomo Mini Anime included with the BD/DVD release of the series.', 39, 'https://cdn.myanimelist.net/images/anime/1142/135358.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hokkyoku no Muushika Miishika', 'Movie', 1, 'Completed', '1979-07-21', NULL, '6', 'Adventures of the polar cubs is a delightful story of Mushka and Mishka, two polar bear cubs who set out on a series of adventures in the North Pole. Mushka is thoughtful; Mishka is daring. While out on their own Mishka befriends Aura, A prank-playing seal and Mushka stumbles over swan eggs, breaks them and creates havoc in the bird village. The cub''s father is Scholar Mu (voice of Joseph Campanella), who is the wise leader of the Great Northern animal kingdom and is in charge of their annual Summer Festival. When Mu is injured by man, the cubs must take on the responsibilities of their father and save the other animals from the hunters. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gundam: G no Reconguista', 'TV', 26, 'Completed', '2014-10-03', '2015-03-27', '6', 'In the year Regild Century 1014, an entire millennium has passed since the end of the fabled Universal Century, where legends like Amuro Ray and Char Aznable ruled the battlefield as ace mobile suit pilots. The Earth''s surface that was once hotly contested is now mostly abandoned, with humanity preferring to live in space colonies and the surface of the moon.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Life: Jinsei no Taisetsu na Toki ni...', 'Special', 1, 'Completed', '2013-03-28', NULL, '6', 'A paper stop-motion commercial for D-Mail, a live-event gift company with roses for anniversaries, cards, picture frames, incense for condolences, etc. With products available to celebrate weddings, births, first day of school ceremonies and graduation.', 1160, 'https://cdn.myanimelist.net/images/anime/7/88414.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chichibu de Buchichi', 'ONA', 1, 'Completed', '2018-03-30', NULL, '6', 'Kaoruko is set to meet a marriage partner... but there''s a person she can''t forget. Someone she met in Chichibu when she was a girl. A young boy whose name she doesn''t even know. Treasured memories of walking with him through Chichibu Shrine. Taking in the carpets of pink flowers at Hitsujiyama Park, the mountain stream at Nagatoro, the sea of clouds from Mitsumine Shrine. These are priceless moments she yearns to relive. Maybe... just maybe... if she heads to Chichibu she might see him again. Clinging to her faint hope and distant memories, Kaoruko resolves to find out.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('K: Seven Stories - The Idol K', 'Movie', 6, 'Completed', '2018-07-07', '2018-12-01', '6', 'Shorts featuring the characters reimagined as idols.', 339, 'https://cdn.myanimelist.net/images/anime/1642/90546.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kipling Jr.', 'Movie', 1, 'Completed', '1995-01-01', NULL, '5', 'A fantastic animation adventure about Kipling Jr., his father, mother, and a musical band led by Rog. Advanced animation techniques, yet to be seen on the screen, help to create incredible movements by animated dolls.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Arigatou Kumanofu', 'ONA', 11, 'Completed', '2011-11-30', '2013-01-21', '5', 'Shorts that focus on a female bear''s life.', 457, 'https://cdn.myanimelist.net/images/anime/8/63757.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Choubakuretsu Ijigen Menko Battle: Gigant Shooter Tsukasa', 'TV', 32, 'Completed', '2014-04-01', '2015-02-10', '5', 'The anime follows Tsukasa, whose dream is to become the best at Gigant Shooter (battles in a game similar to pog) in the world. The menko card his father left for him called King Menger is his partner. Tsukasa''s fellow gamers are the cute but tsundere Koide Miruko, the spectacled bully Numata Manabu, and the realist and sharp-tongued Doumoto Ataru.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Peeping Life: The Perfect Evolution Specials', 'Special', 3, 'Completed', '2011-01-27', NULL, '5', '3 bonus episodes centering around TV Asahi''s female announcers.', 184, 'https://cdn.myanimelist.net/images/anime/9/45823.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Twinkle Heart: Gingakei made Todokanai', 'OVA', 1, 'Completed', '1986-12-05', NULL, '5', 'Love, Heaven''s greatest treasure went missing and to get it back, the Great God decides to send his two daughters Lemon and Cherry, as well as their governess Berry to find it. However, their search doesn''t go so well, mainly because they decide they like it at planet Earth and prefer to work in a hamburger shop (Sic!).
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Soukihei MD Geist', 'OVA', 1, 'Completed', '1986-05-21', NULL, '5', 'In the distant future, mankind has colonized other planets in the universe. While many planets lived in peace, the planet Jerra has been ravaged by decades of war. Geist is an M.D.S. (Most Dangerous Soldier), an enhanced human with unsurpassed combat capabilities and an insatiable lust for battle. Because of his uncontrollable nature, Geist is cryogenically frozen and locked in a satellite. Several years later, the satellite crashes and Geist wakes up from his sleep to engage in another war. This time, to help the army stop the planet''s central computer from activating a doomsday device that will lead to total annihilation of all life on Jerra. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Okamoto Zero One CM Kyouryuu-hen', 'Special', 1, 'Completed', '2016-01-13', NULL, '5', 'A commercial for Okamoto Zero One condoms.', 1049, 'https://cdn.myanimelist.net/images/anime/1170/136269.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Onigiri', 'TV', 13, 'Completed', '2016-04-07', '2016-06-30', '5', 'Ancient Japan is under attack by powerful beings called "Kamikui," and it is up to the "Oni" and his band of eight beautiful female warriors to stop them. Each of these girls have unique skills, abilities, and personalities. They partner themselves with the Oni, Jin, to stop the miasma of darkness sweeping across Japan. Onigiri follows the escapades of Jin and his merry companions as they strengthen their bonds and fend off the demonic invasion.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gyo', 'Movie', 1, 'Completed', '2011-10-29', NULL, '5', 'Though her trip to Okinawa was supposed to be a lovely excursion to the seaside, college student Kaori Sawahara finds that it is anything but when a horrifying menace emerges from the watery depths. A strange mechanism has taken control of the sea creatures, granting them legs and sending them on land to attack anything in their way. Kaori and her friends—the lustful Erika and the reserved Aki—find themselves caught up in this onslaught, made worse by the creatures'' rotting stench of death.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oshiri Tantei: Mina to Machi no Tuk-tuk Chase', 'ONA', 1, 'Completed', '2017-08-02', NULL, '5', '', 1030, 'https://cdn.myanimelist.net/images/anime/1534/109302.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wadachi wo Koete Yuke', 'Movie', 1, 'Completed', '2025-10-10', NULL, '5', 'In the shadow of a ruinous war, three young women are serving as soldiers in a barren, snow-swept landscape. Their task is to scour the frozen wastes for stragglers of the Iron Army, eerie, formerly human flesh-weapons. Gros and especially the inexperienced Leichte admire Esus, stronger and wiser than they. Esus has her weaknesses, though, and unhealed wounds in her heart. Somewhere out there in the vast, deadly sea of snow lie answers—to Esus'' pain, and to the awful secret of this war.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wo Zai Tianting Shou Feipin', 'ONA', 40, 'Completed', '2025-09-28', '2025-11-02', '5', 'In a modern martial arts world, Zhao Xin unexpectedly inherits the Celestial Realm''s recycling station. This grants him not only the aid of numerous immortals but also the admiration of many beauties, ultimately leading him to the pinnacle of martial arts.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Samurai-den Yaiba: Kaguya-hen', 'TV', NULL, 'Upcoming', NULL, NULL, '5', 'Second season of Shin Samurai-den Yaiba.', 1105, 'https://cdn.myanimelist.net/images/anime/1913/152261.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koikeya SDGs Gekijou Suss to Tina Season 6', 'TV', 13, 'Airing', '2025-10-01', NULL, '5', 'Sixth season of Koikeya SDGs Gekijou Suss to Tina.', 327, 'https://cdn.myanimelist.net/images/anime/1543/152209.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zenryoku Usagi (2023)', 'TV', 12, 'Completed', '2023-10-07', '2023-12-30', '5', 'New anime project for Zenryoku Usagi.', 745, 'https://cdn.myanimelist.net/images/anime/1654/120887.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xue Wang Jiadao', 'ONA', 12, 'Completed', '2023-08-25', '2023-10-27', '5', 'The ice cream scepter was mysteriously stolen. In order to regain the scepter and save the ice continent, Snow King chased the scepter thief all the way to Hunting Valley, and accidentally met the bounty hunter "Boss Rabbit" whose dream is to make money to revitalize the restaurant. In this way, with their own goals, the two started a fun adventure to find the scepter together.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Honnou da Zou', 'ONA', 1, 'Completed', '2013-04-17', NULL, '5', '', 684, 'https://cdn.myanimelist.net/images/anime/1559/138264.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chufa Ba Lu Qi', 'TV', 52, 'Completed', NULL, NULL, '5', '', 280, 'https://cdn.myanimelist.net/images/anime/1487/131021.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiongmao Zou Tianya', 'TV', 104, 'Completed', '2012-01-01', NULL, '5', '', 280, 'https://cdn.myanimelist.net/images/anime/1574/131019.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sennen no Yakusoku', 'OVA', 1, 'Completed', '2005-03-01', NULL, '5', 'Part of the series of educational videos that teaches kids and young adults several basic tax lessons.', 435, 'https://cdn.myanimelist.net/images/anime/6/54971.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Akindo Sei no Little Peso', 'TV', 12, 'Completed', '2017-04-03', '2017-06-19', '5', '', 281, 'https://cdn.myanimelist.net/images/anime/1951/150145.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsuyu no Hito Shizuku', 'OVA', 1, 'Completed', '2006-08-01', NULL, '5', 'Working since before WW2, UEDA Shoji pierced through amateurism, Then, in his picture world he takes, cuts and rearranges photos through his own sensibility, which takes him to the new media that is Ga-nime, encouraged by his friend the actor SANO Shiro, born in the same prefecture. The pictures used for this exhibition are not only from his most famous “Dune Mode” series, but also of many pre/post-war pictures of his birthplace, streetcars running in Tokyo, and traditional scene of Japan, through which a whole culture appears. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gakuen Senki Muryou Recap', 'Special', 1, 'Completed', '2001-08-28', NULL, '5', 'Recap of the first 14 episodes of Gakuen Senki Muryou.', 538, 'https://cdn.myanimelist.net/images/anime/13/84191.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Buppu na Mainichi', 'TV', 27, 'Completed', '2017-03-11', '2017-09-09', '5', 'The story will focus on a cat who begins living with 10 dogs, and the animals'' busy everyday life. The story draws inspiration from real-life singer Noriyuki Makihara and his pets. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sore Ike! Anpanman: Buruburu no Takarasagashi Daibouken!', 'Movie', 1, 'Completed', '2017-07-01', NULL, '5', 'The film centers on Buruburu, a cowardly lion who is a member of a clan of treasure hunters. He is given a treasure map by his father. With the help of Anpanman, he sets out on an adventure to prove himself to the other clan members. Baikinman, however, appears and schemes to take the treasure for himself.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Working''!!', 'TV', 13, 'Completed', '2011-10-01', '2011-12-24', '8', 'The exciting antics of Wagnaria return as more ridiculous incidents occur, friendships are deepened, and new feelings are discovered. In addition to Souta Takanashi and his wacky co-workers, more eccentric personalities join the family restaurant: Haruna, Hyougo Otoo''s missing wife, who has a habit of getting hopelessly lost through the sewer system; Kirio Yamada, Aoi''s older brother, who is able to withstand Mahiru Inami''s deadly punches; and twins Youhei and Mitsuki Mashiba, Kyouko Shirafuji''s juniors who do not get along.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Haikyuu!! (OVA)', 'OVA', 10, 'Completed', '2020-03-04', NULL, '8', 'A stop-motion anime that will bundle with the 42nd compiled book volume of Haruichi Furudate''s Haikyu!! manga. Anime will have 10 short episodes featuring the Karasuno team as puppets.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kara no Kyoukai Movie 4: Garan no Dou', 'Movie', 1, 'Completed', '2008-05-24', NULL, '8', 'Following the events of Satsujin Kousatsu (Zen), Shiki Ryougi has been in a coma for two years due to a traffic accident. When she finally awakens, she has no memories of her past and is plagued by a profound loneliness. Even stranger, she notices dark lines encompassing the things around her, and if she touches them she can disassemble the object—something which completely terrifies her. Her friend, Mikiya Kokutou, enlists the help of Touko Aozaki, a mage who can help Shiki understand what her eyes—the "Mystic Eyes of Death Perception"—are truly capable of and how to use them properly.  
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Digimon Adventure: Bokura no War Game!', 'Movie', 1, 'Completed', '2000-03-04', NULL, '8', 'This movie takes place after the Adventure series ends. It begins when a new Digimon Egg is found on the internet, and manages to penetrate into almost every computer system in Japan. When the egg hatches, it''s identified as a new kind of Digimon, a Virus-type. It sustains itself by eating data from various system, and starts wreaking havok in Japan. As it consumes more and more data, it continues to evolve. And Taichi and Koushiro decide it''s time to stop it.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gekkan Shoujo Nozaki-kun', 'TV', 12, 'Completed', '2014-07-07', '2014-09-22', '8', 'Chiyo Sakura is a cheerful high school girl who has fallen head over heels for the oblivious Umetarou Nozaki. Much to Chiyo''s confusion, when she confesses to her beloved Nozaki, he hands her an unfamiliar autograph. As it turns out, the stoic teenage boy is actually a respected shoujo manga artist, publishing under the pen name Sakiko Yumeno! A series of misunderstandings leads to Chiyo becoming one of Nozaki''s manga assistants.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Id:Invaded', 'TV', 13, 'Completed', '2020-01-06', '2020-03-23', '8', 'The Mizuhanome System is a highly advanced development that allows people to enter one of the most intriguing places in existence—the human mind. Through the use of so-called "cognition particles" left behind at a crime scene by the perpetrator, detectives from the specialized police squad Kura can manifest a criminal''s unconscious mind as a bizarre stream of thoughts in a virtual world. Their task is to explore this psychological plane, called an "id well," to reveal the identity of the culprit.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shadows House', 'TV', 13, 'Completed', '2021-04-11', '2021-07-04', '8', 'The Shadows, characterized by their pitch-black appearance and tendency to emit soot when agitated, are a family of nobles who reside in a colossal manor deep within the mountains far from other humans. When a Shadow child is nearly of-age, they are assigned a Living Doll who acts not only as their attendant but also as their second half—the faces they could have had if not for their complexion.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Grisaia no Meikyuu: Caprice no Mayu 0', 'Special', 1, 'Completed', '2015-04-12', NULL, '8', 'Having attended Mihama Academy for about a year, Yuuji Kazami has seemingly found his place within the school, but he suddenly decides to pursue a promotion in CIRS. After consulting JB about his intentions, they both thoroughly examine Yuuji''s documents and dissect the events of his upbringing to determine if the job is fit for him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Somali to Mori no Kamisama', 'TV', 12, 'Completed', '2020-01-10', '2020-03-27', '8', 'In a world inhabited by demons, cyclopes, and other fantastic creatures, humans stand apart as the outcasts. Quick to anger, the human race engaged in a war that all but wiped them out. The few humans that remain are seen as a delicacy, serving no purpose but to be hunted down and eaten.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Umibe no Étranger', 'Movie', 1, 'Completed', '2020-09-11', NULL, '8', 'Shun Hashimoto is an openly gay aspiring novelist living in Okinawa who was abandoned by his parents after coming out to them. Mio Chibana is a reserved, orphaned high school student, often found spending his time by the sea. One day, the two meet on the beach, and Shun is instantly captivated by Mio. The days fly by as they slowly begin to grow closer until Mio suddenly announces that he has to leave for the mainland.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shiguang Dailiren Fanwai Pian: Biwu Zhaoqin', 'ONA', 1, 'Completed', '2021-05-28', NULL, '8', 'At the Time Photo Studio, partners Lu Guang and Cheng Xiaoshi accept jobs of a peculiar nature. With the aid of their complementary abilities, they are able to leap into photographs—thereby entering the past. One such case involves Liu Siwen, whose only wish is to marry his one true love, Ou Yang. However, her martial arts master father is apprehensive of a suitor who is an outsider and refuses to give his permission unless Liu Siwen defeats him in an honest duel.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('SK∞ OVA: Extra Part', 'OVA', 1, 'Completed', '2025-03-19', NULL, '8', 'Four slice-of-life omnibus stories.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('5-toubun no Hanayome Movie', 'Movie', 1, 'Completed', '2022-05-20', NULL, '8', 'Fuutarou Uesugi''s efforts as the Nakano quintuplets'' private tutor are finally paying off. The academic performances of the five sisters are steadily improving, and they are each closer than ever to achieving their respective dreams. However, it appears that Fuutarou has become more than a teacher for the girls, who urge him to sort out his feelings.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tasogare Otome x Amnesia', 'TV', 12, 'Completed', '2012-04-09', '2012-06-25', '8', 'Seikyou Private Academy, built on the intrigue of traditional occult myths, bears a dark past—for 60 years, it has been haunted by a ghost known as Yuuko, a young woman who mysteriously died in the basement of the old school building. With no memory of her life or death, Yuuko discreetly finds and heads the Paranormal Investigations Club in search of answers.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Crayon Shin-chan', 'TV', NULL, 'Airing', '1992-04-13', NULL, '8', 'There is no such thing as an uneventful day in the life of kindergartener Shinnosuke "Shin-chan" Nohara. The five-year-old is a cut above the most troublesome, perverted, and shameless kid one can imagine. Shin-chan is almost always engaged in questionable activities such as forgetting about a friend during hide and seek, sumo wrestling for love, performing various gags including the notorious "elephant" in public, and flirting with college girls. The exemplary troublemaker has done it all and has no plans to stop anytime soon.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gungrave', 'TV', 26, 'Completed', '2003-10-07', '2004-03-30', '8', 'Brandon Heat and Harry MacDowel, two friends so close they could be called brothers, receive an abrupt and violent reminder one fateful day of how appallingly merciless the world around them can be. Their whole lives before then were simple and easygoing, consisting largely of local brawls, seducing women, and committing petty theft to make a living and pass the time. What they failed to realize is that in this cruel world, happiness is fleeting, and change is inevitable.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece Film: Red', 'Movie', 1, 'Completed', '2022-08-06', NULL, '8', 'As a child, Uta—the Red Hair Pirates'' ex-musician and Monkey D. Luffy''s childhood friend—promised that she would build a new era of freedom by performing joyful music for the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Break Blade Movie 4: Sanka no Chi', 'Movie', 1, 'Completed', '2010-10-30', NULL, '8', 'Fourth Break Blade Movie.', 704, 'https://cdn.myanimelist.net/images/anime/11/68085.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xingchen Bian 6th Season', 'ONA', 28, 'Completed', '2025-01-30', '2025-07-17', '8', 'The story revolves around Qin Yu and his three brothers after ascending to the God Realm. As Qin Yu gradually learns the rules of the God Realm, he aspires to become the strongest craftsman god in order to marry Jiang Li, a member of one of the eight great families of the God Realm, whose status is vastly different from his own. Starting with eliminating bandits, he rises to become a high-level god, gaining the favor of the Holy Emperor and becoming a rising star… step by step, he finally reaches a position where he can openly propose to Jiang Li. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaijuu 8-gou 2nd Season', 'TV', 11, 'Completed', '2025-07-19', '2025-09-27', '8', 'Following the massive operation that led to the confinement of recent recruit Kafka Hibino, otherwise known as Kaijuu No. 8, the Defense Force has been puzzled by how to deal with him. Kafka is the first kaijuu to side with humans, and after careful consideration, he is eventually transferred to the Defense Force''s First Division in the hope of adding his power to the strongest division, capable of handling any threat. However, some people are still doubtful about Kafka, and he must prove his worth in the next mission.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('MF Ghost 2nd Season', 'TV', 12, 'Completed', '2024-10-07', '2024-12-23', '8', 'The second race in the MFG tournament at the notoriously difficult Lake Ashinoko track is underway. Though his car is severely disadvantaged in terms of horsepower, tune-ups to Kanata Katagiri''s Toyota 86 GT allow him to quickly soar into a qualifying position. However, torrential downpour on the final day of racing brings tire traction woes and causes all drivers to struggle. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nitian Xie Shen', 'ONA', 30, 'Completed', '2023-09-23', '2024-03-30', '8', 'In the Cangyun Continent, the Medicine Sage Yun Gu was brutally murdered due to possessing one of the Seven Heavenly Treasures, the Sky Poison Pearl, which made it the object of desire for the entire realm. Yun Che, his disciple, carried the treasure to seek revenge for his master and caused boundless bloodshed in the process. Eventually, he was cornered by formidable foes at the Desolate Sky Cliff. Unyielding, Yun Che swallowed the poison pearl and leaped off the cliff to his death. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga Eiyuu Densetsu: Die Neue These - Kaikou', 'TV', 12, 'Completed', '2018-04-03', '2018-06-26', '8', 'For over a century and a half, two interstellar states have wrested for control of the Milky Way. The Galactic Empire, an absolute monarchy ruled by Kaiser Friedrich IV and an entrenched nobility, seeks to suppress the rebels daring to oppose the inviolable crown. The Free Planets Alliance, a representative democracy led by a corrupt High Council, degenerates as its elected leaders⁠ use war and conflict as a way to win popular support.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('New Initial D Movie: Legend 1 - Kakusei', 'Movie', 1, 'Completed', '2014-08-24', NULL, '8', 'One foggy morning, a black and white Toyota AE86 flies past Keisuke Takahashi''s Mazda RX7 on Mount Akina, making him believe he has seen the ghost of a racer who died on the mountain. Resolving to defeat this phantom, Keisuke mobilizes the Akagi Red Suns to take on the local Akina Speed Stars racing team in an exchange race. He anticipates that the competition will lure the elusive "Ghost of Akina" out into the open and give him the opportunity to exact revenge for his previous defeat. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuru Yuri♪♪', 'TV', 12, 'Completed', '2012-07-03', '2012-09-18', '8', 'The girls of the Amusement Club return in Yuru Yuri♪♪, finding new ways to make passing time even more enjoyable. Their members consist of the always energetic Kyouko Toshinou; calm and sensible Yui Funami; polite but often overlooked Akari Akaza; and Chinatsu Yoshikawa, who stumbled upon the others while looking for the Tea Ceremony Club. Together they are the Amusement Club, which has the deceptively simple task of keeping its members entertained.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lian Qi Shi Wan Nian', 'ONA', 360, 'Airing', '2023-02-18', NULL, '7', 'One hundred thousand years ago, he was the founding disciple of the Tianlan Sect, his master ascended to the top, and he was refining Qi. Ninety thousand years ago, his martial nephew ascended, and he was refining Qi. Fifty thousand years ago, the old dog who was the gatekeeper of Tianlanzong also ascended, and he was still refining Qi. Thirty thousand years ago, the old tree at the foot of the mountain also became a demon, and he was still refining Qi before he could pass the catastrophe. Ten thousand years ago, Zhang Wuji, the 9872nd generation disciple of Tianlanzong, also ascended, and Xu Yang silently refined Qi. He retreated for 10,000 years, and finally, he broke through the 9999th floor of the Qi refining period! Ten thousand years later, he broke through and came out!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon (2023)', 'TV', NULL, 'Airing', '2023-04-14', NULL, '7', 'In a world filled with strange yet majestic creatures known as Pokémon, a new adventure begins! Hailing from the pristine region of Paldea, the timid Liko travels to the Kanto region to attend the Indigo Academy and become a Pokémon trainer—a person who forms relationships with Pokémon and trains them to participate in battles. Soon, Liko acquires Nyahoja, a fickle Grass-type cat Pokémon, as her first partner.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('2.5-jigen no Ririsa', 'TV', 24, 'Completed', '2024-07-05', '2024-12-13', '7', 'After a disastrous romantic confession, Masamune Okumura finds solace in the fictional world of anime and manga. Now a second-year high school student and the president of the Manga Research Club, Masamune spends a peaceful existence watching the adventures of the angel Liliel, his favorite character.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tensei shitara Dainana Ouji Datta node, Kimama ni Majutsu wo Kiwamemasu', 'TV', 12, 'Completed', '2024-04-02', '2024-06-18', '7', 'In his past life, Prince Lloyd de Saloum was a commoner who could not become adept at magic, no matter how knowledgeable or obsessed he was about it. Now reincarnated into his current royal lineage, he receives a body with seemingly endless mana, making his desire to master all things arcane attainable. Moreover, as the seventh prince of the kingdom, Lloyd has no claim to the throne, allowing him to nurture his abilities as freely as he wants.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('K', 'TV', 13, 'Completed', '2012-10-05', '2012-12-28', '7', '"Kings" are individuals who have been bestowed with incredible supernatural powers and granted the ability to recruit others into their clans. Protecting the lives and honor of their clansmen is an integral part of the Kings'' duties. After a video depicting the heinous murder of a Red Clansman spreads virally, the unassuming student Yashiro Isana is accused of homicide. Now, a manhunt is underway for his head, bringing him into contact with the infamous "Black Dog" Kurou Yatogami—a skilled swordsman and martial artist determined to follow the wishes of his late master, the Seventh King.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Haiyore! Nyaruko-san F', 'OVA', 1, 'Completed', '2015-06-19', NULL, '7', 'A new OVA of the light novel Haiyore! Nyaruko-san, titled Haiyore! Nyaruko-san F, has been green-lit.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon XY: Mega Evolution', 'Special', 4, 'Completed', '2014-04-03', '2015-10-29', '7', 'Previously an assistant of Lumiose City''s Professor Platane, Alain and his Lizardon set off on a journey to become even stronger, by mastering the powers of mega evolution. Investigating the mysteries of this phenomenon, at the behest of the enigmatic Fleur-de-lis, Alain and Lizardon travel across Kalos and Hoenn in search of capable trainers who can use mega evolution in order to improve, as well as help Fleur-de-lis with his research. Along the way, they meet a young girl named Manon who, with her Harimaron, decide to accompany Alain, to which he reluctantly agrees.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yaoguai Mingdan 2nd Season', 'ONA', 21, 'Completed', '2017-08-03', '2017-12-28', '7', '', 369, 'https://cdn.myanimelist.net/images/anime/1278/108493.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Huyao Xiao Hongniang 3: Yue Hong Pian Part 2', 'ONA', 8, 'Completed', '2016-11-18', '2017-01-06', '7', 'Part two of the third season of Huyao Xiao Hongniang.', 369, 'https://cdn.myanimelist.net/images/anime/1760/153690.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Naruto: Shippuuden Movie 4 - The Lost Tower', 'Movie', 1, 'Completed', '2010-07-31', NULL, '7', 'Led by Yamato, Naruto Uzumaki, Sakura Haruno, and Sai are assigned to capture Mukade, a rogue ninja who is pursuing the ancient chakra Ryuumyaku located underneath the Rouran ruins. While the Ryuumyaku has been sealed by the Fourth Hokage, the group fails to prevent Mukade from releasing its power. Consequently, a strong energy burst engulfs both Naruto and Yamato before they can escape.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('K: Seven Stories Movie 4 - Lost Small World - Ori no Mukou ni', 'Movie', 1, 'Completed', '2018-10-06', NULL, '7', 'Misaki Yata is a youth whose reckless and immature attitude has led him to be shunned by his classmates. Saruhiko Fushimi is a loner who views the world in a pessimistic way. Despite being polar opposites, the two become the best of friends.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hakuouki: Reimeiroku', 'TV', 12, 'Completed', '2012-07-10', '2012-09-25', '7', 'Beaten and left to perish, Ryuunosuke Ibuki is robbed of everything to his name. Seeing him in such a pitiful state, a man named Kamo Serizawa gives him a second chance and offers him to become his personal assistant. Ibuki seems to be spared by grief, but this new lifestyle only makes him nothing more than a dog to one of the most influential men in all of Kyoto.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Captain Tsubasa (2018)', 'TV', 52, 'Completed', '2018-04-03', '2019-04-02', '7', 'Captain Tsubasa is the passionate story of an elementary school student whose thoughts and dreams revolve almost entirely around the love of soccer. 11-year-old Tsubasa Oozora started playing football at a very young age, and while it was mostly just a recreational sport for his friends, for him, it developed into something of an obsession. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kiratto Pri☆chan Season 2', 'TV', 51, 'Completed', '2019-04-07', '2020-03-29', '7', 'Mirai Momoyama, Emo Moegi, and Rinka Aoba are 2nd year students at Kirarigaoka Middle School in Kirajuku, and together they form an idol group called "Miracle☆Kiratts"! The popularity of their streaming programs has skyrocketed! One day, a mysterious Pri☆Chan idol named "Dia" appears, and everyone is given a Jewel Pact. Along with that, she announces the opening of the "Jewel Auditions", an event where idols with a jewel-like shine are chosen to become "Jewel Idols". Only those who can pass the audition with a sparkling heart can make their "Kiratto Jewel" shine, allowing them to receive their "Jewel Coord". And out of all of them, only the best "Jewel Idol" can wear the long-admired "Diamond Coord". Who''s going to be?!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oshi ga Budoukan Ittekuretara Shinu', 'TV', 12, 'Completed', '2020-01-10', '2020-03-27', '7', 'After receiving a flyer from Maina Ichii—a member of the idol group ChamJam—and seeing her perform at a local concert, Eripiyo falls in love with Maina and decides to devote her life to supporting the shy and reserved rising star. Eripiyo''s charismatic presence and iconic red tracksuit soon give her recognition as Maina''s one and only unrivaled fan. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tegamibachi: Hikari to Ao no Gensou Yawa', 'Special', 1, 'Completed', '2008-11-24', NULL, '7', 'The story takes place in the land of Amber Ground, a place of perpetual night only partially illuminated by an artificial sun. Lag Seeing works as a "Letter Bee" (delivery boy) at the "Bee Hive" (a delivery service), with his Dingo, Niche, and her "pet," Steak, traveling with him. He is entrusted with the "hearts" of the everyone in Amber Ground to deliver their packages.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shugo Chara!! Doki', 'TV', 51, 'Completed', '2008-10-04', '2009-09-25', '7', 'Amu Hinamori and the Seiyo Elementary Guardians continue their quest to seek out and purify X Eggs while in pursuit of the elusive Embryo—an egg said to be able to grant any wish. However, the Guardians must secure the Embryo before it falls into the hands of the nefarious Easter Corporation. As part of their plan to lure out the Embryo, Easter hires Lulu de Morcerf, an aloof girl whose ruby necklace gives her the ability to convert Heart Eggs into Mystery Eggs.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toradora! Recap', 'OVA', 1, 'Completed', '2009-04-30', NULL, '7', 'Recap OVA of the Toradora series included as a bonus with limited edition of Choudokyuu Premium Box release of PSP game Toradora! Portable.', 436, 'https://cdn.myanimelist.net/images/anime/2/77024.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yao Shen Ji 4th Season', 'ONA', 52, 'Completed', '2020-04-08', '2020-09-27', '7', 'Fourth season of Yao Shen Ji.', 752, 'https://cdn.myanimelist.net/images/anime/1196/107545.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece Movie 09: Episode of Chopper Plus - Fuyu ni Saku, Kiseki no Sakura', 'Movie', 1, 'Completed', '2008-03-01', NULL, '7', 'As Nami has fallen seriously ill, the Straw Hats head to Drum Island in search of a doctor. However, they learn that there is only one doctor left on the island, the reclusive Dr. Kureha who currently resides at the top of a mountain. With a sick Nami in tow, Monkey D. Luffy and Sanji set out on an arduous journey to seek her help. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sakigake!! Otokojuku', 'TV', 34, 'Completed', '1988-02-25', '1988-11-14', '7', 'Otokojuku: a private school for juvenile delinquents that were previously expelled from normal schools. At this school, Japanese chivalry is taught through feudal and military fundamentals. Similar to an action film, the classes are overwhelmed by violence. Only those who survive it become true men.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jewelpet Twinkle☆', 'TV', 52, 'Completed', '2010-04-03', '2011-04-02', '7', 'In Jewel Land, Jewelpets, creatures who has the natural ability to use magic lived in harmony with the Witches, attending the School of Witchcraft and Wizardry to learn to use magic with their Jewel Eyes. However for Ruby, a white Japanese Hare whose magic sometimes fail, is appointed to go to the Human World to search for her partner. But when she used the card the magicians gave her, she was sent to the Human World by accident. In the Human World, A girl named Akari Sakura met her on the beach on her way to school. At first, Akari can''t understand her due to her Jewel Land Language until Ruby took a special candy so she could speak and understand human language. As the day passes, Ruby knew about her problems and later apologized. A Jewel Charm appeared on Akari''s hand and she realized it that she''s chosen by Ruby to be her partner. After that, she decided to enter the Jewel Star Grand Prix, on the prize is that any wish that they wanted will be granted. Will she be the Next Jewel Star and her wish be granted in the end? Or It''ll just end in one big disaster...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jashin-chan Dropkick X', 'TV', 12, 'Completed', '2022-07-06', '2022-09-21', '7', 'Ever since she was summoned from Hell by the witch Yurine Hanazono, Jashin-chan—a half-human, half-snake demon—has been searching for any way to go back. One of her options is to kill the one who summoned her, which is much easier said than done. Jashin-chan often finds herself getting violently beaten by Yurine after not only any failed murder attempt, but also when she is just causing mischief, destroying any hope of going back home to Hell.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dekin no Mogura', 'TV', 12, 'Completed', '2025-07-07', '2025-09-22', '7', 'When university students Kuriaki Magi and Yaeko Kirihara witness a man receive a fatal blow to the head, they can barely believe it when he flees the scene unscathed. Once they catch up to the victim, Momoyuki Mogura, they learn that he is immortal.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bocchi the Rock!: Gotou Futari no Onee-chan Kansatsu Nikki', 'Special', 1, 'Completed', '2022-12-24', NULL, '7', 'This is a special program where we look back on the recent daily life of the main character, Hitori Gotou, from the observation of her younger sister, Futari Gotou.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wangu Kuang Di', 'ONA', 20, 'Completed', '2024-01-01', '2024-04-29', '7', 'Chu Kuangsheng, son of Patriarch Chu in the remote Shiyang town in Shenlong Empire, was born weak and unable to train. Due to his cultivation impairment, he is the laughingstock of the entire town. Three years ago, his parents go missing while on official duty. His talented and beautiful sister, Chu Liu''er, is the apparent successor to head the Chu family but she suffers a strange illness. Since then, Chu Kuangsheng''s situation gets increasingly difficult. During an ambush, the injured Chu Kuangsheng inherits the ancestral technique of Chu family, rebuilding his damaged meridians. From then on, Chu Kuangsheng''s training progresses rapidly. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hua Jianghu: Tiangang', 'ONA', 1, 'Completed', '2023-12-29', NULL, '7', 'During the reign of Emperor Da Zhou, the political situation was turbulent, and treacherous officials held power. Bu Liang Ren, a secret assassination organization directly under the emperor, suddenly lost its leader overnight, and their chief, Yuan Tiangang, resigned with a letter. Lost and directionless, Yuan Tiangang, guided by a brocade pouch left by his friend Li Chunfeng, arrived at the Anle Pavilion in Chang''an, only to discover it was a brothel. What followed, with the appearance of those seeking freedom, immortality, and power, set a new stage in Yuan Tiangang''s journey…
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('T.P BON', 'ONA', 12, 'Completed', '2024-05-02', NULL, '7', 'An ordinary high school student named Bon becomes part of a team of time-traveling agents tasked with saving people''s lives during historical events that happen across different eras and locations around the globe. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bakeneko Anzu-chan', 'Movie', 1, 'Completed', '2024-07-19', NULL, '7', 'Karin, 11 years old, is abandoned by her father at her grandfather’s house, the monk of a small town in the Japanese countryside. Her grandfather asks Anzu, his jovial and helpful although rather capricious ghost cat, to look after her. The meeting of their strong characters causes sparks, at least at the beginning…
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Anhe Zhuan', 'ONA', 12, 'Completed', '2023-08-02', '2023-10-11', '7', 'Anhe, the most mysterious killer organization in the world, is composed of the three surnames Su, Xie, and Mu. Everyone was poisoned, and their lives were at stake. After learning the news, the three forces of the Anhe River took the opportunity to launch a rebellion. Su Muyu, as the leader of Spider Shadow''s guard group, brought in Bai Hehuai, the genius doctor of Medicine King Valley, to heal the elders, while repelling the killers and protecting the elder Zhouquan. At this time, his friend Su Changhe in Anhe, but on behalf of the Su family joined the operation to assassinate the patriarch.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Danganronpa 3: Monokuma Gekijou', 'Special', 3, 'Completed', '2016-10-27', '2016-12-21', '7', 'Danganronpa 3 skits included in the Blu-ray Box Sets.', 510, 'https://cdn.myanimelist.net/images/anime/8/90004.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('ReLIFE: Kanketsu-hen Specials', 'Special', 2, 'Completed', '2018-03-21', NULL, '7', 'Two specials of ReLIFE: Kanketsu-hen released on mobile and later included on Blu-ray/DVD volume.', 990, 'https://cdn.myanimelist.net/images/anime/1563/93020.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yu☆Gi☆Oh! 5D''s: Shinkasuru Kettou! Stardust vs. Red Demon''s', 'Special', 1, 'Completed', '2008-09-21', '2008-11-23', '7', 'A non-canon Yu☆Gi☆Oh! 5D''s special from the 2008 Super Jump Anime Tour. Yuusei Fudou and Jack Atlas face off in a Riding Duel for the title of Duel King, with Aki and the twins watching. The ace dragons, Stardust Dragon and Red Daemon''s Dragon, clash once again, and this time gain the power to ''evolve'' using the Buster Mode trap card, becoming "Stardust Dragon/Buster" and "Red Demon''s Dragon/Buster."', 325, 'https://cdn.myanimelist.net/images/anime/8/10786.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doraemon (2005) Specials', 'Special', NULL, 'Airing', '2005-04-15', NULL, '7', '59 Doraemon (2005) TV Specials exist as of January 24, 2018.', 802, 'https://cdn.myanimelist.net/images/anime/1969/109880.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchi Tama?! Uchi no Tama Shirimasen ka?', 'TV', 11, 'Completed', '2020-01-10', '2020-03-20', '7', 'The animals of Third Street are seen getting into many misadventures. Tama Okamoto, the curious feline, often goes missing from his home, causing his owner to have posters up looking for him. However, Tama''s absence is his opportunity to visit all of his wandering furry friends around the neighborhood. From Tama''s best friend Pochi Yamada to the stray alley cat Nora, these animals take human form to hang out, to cause various mischief, but most of all, to have fun!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Strike the Blood IV', 'OVA', 12, 'Completed', '2020-04-08', '2021-06-30', '7', 'Fourth season of Strike the Blood.', 194, 'https://cdn.myanimelist.net/images/anime/1692/116875.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Strike Witches', 'TV', 12, 'Completed', '2008-07-04', '2008-09-19', '7', 'In the year 1939, humanity was on the verge of destruction. Equipped with weapons of devastating power, a mysterious alien race, known as the Neuroi, began an invasion of the Earth, ravaging the planet, obliterating countries, and vanquishing human armies. To counter this seemingly unstoppable force, the world''s powers united. A new device was produced, called the Striker Unit, capable of facing Neuroi technology. Girls equipped with the Striker Unit became known as the Witches, forming humanity''s last line of defense. They began their fight against the Neuroi, utilizing their now-enhanced magical abilities, flaunting destructive weapons no human could manage.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Baka to Test to Shoukanjuu: Matsuri - Sentakushi Ikou nomi', 'Special', 6, 'Completed', '2011-02-23', '2011-03-30', '7', 'Specials included in the Baka to Test to Shoukanjuu: Matsuri BD/DVD volumes featuring alternative endings to the OVA episodes.', 761, 'https://cdn.myanimelist.net/images/anime/11/75276.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ryuusei no Rockman Tribe', 'TV', 21, 'Completed', '2007-11-03', '2008-03-29', '7', 'The second series is to follow the events of the second video game, focusing on the lost continent of Mu. The ancient civilization vanished ages ago, and a few of its remnants still exist as myths and legends called UMAs (unidentified lifeforms). The UMAs begin merging with humans in order to search for the treasures of Mu, the powerful ooparts, which will give them the power to revive Mu. After Subaru and War-Rock encounter several unusual enemies, they meet a professor named Doctor Orihime who sends them on a quest to find the ooparts and stop the UMAs. Using the ooparts, Rockman is able to take new forms, including Thunder Berserk, Fire Dinosaur, and Green Shinobi. (Source: Wikipedia)', 1117, 'https://cdn.myanimelist.net/images/anime/1256/94652.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Buddy Complex: Daremo Shiranai Ashita e', 'ONA', 1, 'Completed', '2014-09-20', NULL, '7', 'A summary of the Buddy Complex series told from the point of view of Nasu Mayuka.', 974, 'https://cdn.myanimelist.net/images/anime/4/75763.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sword Art Online: Alicization - War of Underworld Recap', 'Special', 1, 'Completed', '2020-07-04', NULL, '7', 'Recap of Sword Art Online: Alicization - War of Underworld.', 14, 'https://cdn.myanimelist.net/images/anime/1946/106255.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Koihime†Musou: Otome Tairan', 'TV', 12, 'Completed', '2010-03-26', '2010-06-17', '7', 'The third season of Koihime Musou.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hoshi no Kirby', 'TV', 100, 'Completed', '2001-10-06', '2003-09-27', '7', 'A diminutive pink creature orbiting in space called "Kirby" crash lands into Dream Land. Once getting acquainted with the citizens who live there in Cappy Town, he begins to defend the town from the monsters that King Dedede, the self-proclaimed ruler of Cappy Town, orders from the evil Nightmare Enterprises.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Naruto Movie 3: Dai Koufun! Mikazuki Jima no Animaru Panic Dattebayo!', 'Movie', 1, 'Completed', '2006-08-05', NULL, '7', 'Led by Kakashi Hatake, Naruto Uzumaki, Sakura Haruno, and Rock Lee are tasked to escort the extravagant Prince Michiru Tsuki and his spoiled son Hikaru to the prosperous Land of Moon when the two return from a long trip around the world. As if guarding two whimsical high-ranked individuals was not challenging enough, the prince''s reckless decision to acquire an entire circus during their journey—mainly to entertain Hikaru''s wish of owning the saber-toothed tiger featured in the show—further propels the mission into disarray.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ensemble Stars!', 'TV', 24, 'Completed', '2019-07-07', '2019-12-22', '7', 'Yumenosaki Academy has been home to the best boy idols of different generations. Holding immense influence over the school, its student council maintains the status quo by enforcing old traditions with an iron fist. Transfer student Anzu winds up attending as the very first member in the production course, making her the sole female student in the entire school. There, she meets Subaru Akehoshi, Hokuto Hidaka, Mao Isara, and Makoto Yuuki—her classmates and members of the idol unit "Trickstar." 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Overman King Gainer', 'TV', 26, 'Completed', '2002-09-07', '2003-03-22', '7', 'Sometime in the distant future, mankind is forced to live in domed cities while the rest of the world is left to recover from years of environmental hardships. In the Siberian Dome-polis, professional gamer Gainer Sanga and mercenary Gain Bijou commandeer an Overman and lead a mass exodus out of the city.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('To Heart 2 Adnext', 'OVA', 2, 'Completed', '2010-09-23', '2010-12-22', '7', 'Komaki Manaka daydreams about classmate Kono Takaaki but is too shy to talk to boys. As Takaaki-kun helps her in the library they resolve to have training sessions there, calling each other by first name. When Manaka addresses Takaaki-kun outside the library, his buddy Kosaka Yuji overhears them and tells their classmates how close these two have become, causing a surprising effect on other girls around Takaaki.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Afro Samurai Pilot', 'Special', 1, 'Completed', '2003-01-01', NULL, '7', 'Original pilot for the "Afro Samurai" TV Show, directed and animated by Takeshi Koike.', 538, 'https://cdn.myanimelist.net/images/anime/1508/149710.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sword Art Online II: Debriefing', 'Special', 1, 'Completed', '2014-10-11', NULL, '7', 'Recap episode of the Phantom Bullet arc, also known as Episode 14.5.', 14, 'https://cdn.myanimelist.net/images/anime/10/67587.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Candy Boy Episode: EX02 - Shiawase Kyouyuu Riron', 'Special', 1, 'Completed', '2009-06-24', NULL, '7', 'Final episode (designated as Episode 8) of Candy Boy which came with DVD volume 2.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sasuke', 'TV', 29, 'Completed', '1968-09-03', '1969-03-25', '7', 'Sasuke is the son of a very skilled ninja, whose name is Ozaru. After the defeat of their lord, Yukimura Sanada, Tokugawa''s and Hattori''s ninjas begin to persecute all their enemies still alive: that means Ozaru and Sasuke must leave their house and start a violent struggle for their own life. Danger, vengeance, anger, loyalty, pain are the basic elements of this story, where the worst aspects of the human soul are described together with the growth of the main character, the young Sasuke.', 986, 'https://cdn.myanimelist.net/images/anime/4/30805.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hamatora The Animation: Saishuukai Chokuzen! Mao ga Okuru', 'Special', 1, 'Completed', '2014-03-21', NULL, '7', 'Recap of the Hamatora The Animation series narrated by Mao.', 590, 'https://cdn.myanimelist.net/images/anime/2/72302.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kindaichi Shounen no Jikenbo: Shinigami Byouin Satsujin Jiken', 'Special', 1, 'Completed', '1997-04-27', NULL, '7', 'A one-hour special that aired after a month of the series'' absence on television between episodes 23 and 24.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sheng Shi Zhuang Niang', 'ONA', 20, 'Completed', '2018-07-24', '2018-12-04', '7', 'A beauty blogger has been sent to a VR reality game, where she has to stand firm in a catfight in boudoir. But how so? She is given numerous cosmetic products that she can arm herself up with. Based on the popular online novel published on the famous female-oriented online novel website "Jinjiang", this animation is strongly recommended to those who love all kinds of cosmetics.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Super Robot Taisen OG: Divine Wars - Sorezore no Michi', 'Special', 1, 'Completed', '2007-10-26', NULL, '7', 'This is considered episode 26 of the series which was only included on the final DVD. It primarily focuses on the aftermath of the final TV episode (25).', 621, 'https://cdn.myanimelist.net/images/anime/8/31081.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Night Head Genesis', 'TV', 24, 'Completed', '2006-07-29', '2006-12-30', '7', 'Following a 15-year long seclusion in a research facility, brothers Naoto and Naoya Kirihara finally escape after the psychic barrier separating them from the outside world collapses. Abandoned by their parents, who feared their supernatural powers, the siblings now strive for a normal life. However, the two are soon forced to use their talents to save lives as the "minus energy" begins to engulf the world and crimes involving psychic abilities gradually multiply.  
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fate/kaleid liner Prisma☆Illya Specials', 'Special', 5, 'Completed', '2013-09-27', '2014-01-31', '7', 'Specials bundled with each of all five Blu-ray/DVD volumes.', 761, 'https://cdn.myanimelist.net/images/anime/3/51235.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Grimm Douwa: Kin no Tori', 'Movie', 1, 'Completed', '1987-03-14', NULL, '7', '"Kin No Tori" is an adaptation of the homonymous fairy tale "The Golden Bird" by Brothers Grimm.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sekai Meisaku Douwa: Mori wa Ikiteiru', 'Movie', 1, 'Completed', '1980-03-15', NULL, '7', 'Twelve Months is the story of an orphaned girl named Anya. When a spoiled princess, who is also orphaned, sees a picture of a Galanthus, she immediately wants one. However, the Galanthus only blooms in spring, in the month of April. It is New Year''s Eve and there was no way that such a flower can be found in the middle of the winter. The princess offers a basket of gold to anyone who can bring her a bag of Galanthus.', 1030, 'https://cdn.myanimelist.net/images/anime/1263/131904.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wellber no Monogatari: Sisters of Wellber Zwei', 'TV', 13, 'Completed', '2008-01-02', '2008-03-26', '7', 'The loquacious sentient tank, Gyrano De Borgerac seems very busy being pampered by solicitous maids. The fairy Sherri, too, is enjoying the luxury of the court''s life. And for Rita, time has come to face her duties as princess of Wellber. But Tina is resolute: she wants to continue her search for the Man with a tattoo of Bee the Death, the devil who exterminated her family. An unspeakable feeling of sadness fills the hearts of the two girls, who shared so much and are now about to say farewell to each other.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nagasaki 1945: Angelus no Kane', 'Movie', 1, 'Completed', '2005-09-09', NULL, '7', 'August 1945. In a converted theological seminary on the outskirts of Nagasaki, a young doctor works to help his patients, as unsettling news comes of a new weapon used by the Americans on the city of Hiroshima. When the second nuclear weapon is dropped on Nagasaki, the hospital staff must work to save lives in the midst of the concentric circles of death that their city has become.', 587, 'https://cdn.myanimelist.net/images/anime/1579/112922.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cop Craft', 'TV', 12, 'Completed', '2019-07-09', '2019-10-01', '7', 'Fifteen years ago, a hyperspace gate appeared in the middle of the Pacific Ocean, connecting Earth to a strange world filled with fairies and monsters. The city of San-Teresa became a home for over two million of these otherworldly visitors. Unfortunately, the population boom also brought its fair share of problems—drugs, prostitution, and trafficking. To combat the rampant crime lurking in the city''s shadows, a new department was established in the San-Teresa Metropolitan Police.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Majokko Megu-chan', 'TV', 72, 'Completed', '1974-04-01', '1975-09-29', '7', 'Megu is sent to Earth in her early teens, she is adopted by Mammi Kanzaki, a former witch who gave up her royal ambitions to wed a mortal. Mammi bewitches her husband and their two children, Rabi and Apo, into believing that Megu has always been the eldest child of the family. Under Mammi''s tutelage, Megu learns to control both her abilities and impulses in order to prove her worthiness for the crown. This Rite-of-Passage subtext is continued throughout the series.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Ball Z: Saiya-jin Zetsumetsu Keikaku', 'OVA', 2, 'Completed', '1993-07-23', NULL, '7', 'Dr. Raichii is the only Tsufurujin (the race eradicated by the Saiyajin many years ago) thought to have survived. He now is going to take revenge on the only surviving Saiyajin still alive, Goku and Vegeta. He uses machines that emit destron, a gas that will destroy all life on Earth. Now the the Z warriors only have 72 hours to find and destroy Dr. Raichii.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ohayou! Spank', 'TV', 63, 'Completed', '1981-03-07', '1982-05-29', '7', 'Morimura Aiko is a junior high school student who is short for her age. Her father went on a yacht ten years ago and his whereabouts remained in obscurity. Her mother, a designer for hats, left for Paris, leaving Aiko in the care of her uncle, Mr Fujinami. Aiko had a pet dog, Papi, but it died in a car accident. Around the same time, another dog, Spank, appears before her. Having gone through so many unfortunate events in her life, Spank''s presence begins to brighten up Aiko''s life and put a smile on her face.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chiisana Viking Vickie', 'TV', 78, 'Completed', '1974-04-03', '1975-09-24', '7', 'Long ago, in a little Viking Village called Flake, young Wickie lives a happy life. His father, Halvar, is the chief of the Vikings, and would have liked a son a little more courageous. So, he and his team take Wicke along on their journeys to give him the experience he''ll need to be a real Viking. Yet, somehow Halvar and his men end up trapped or hopelessly stuck somewhere in most cases, and it`s up to Wickie alone to help them out with his flashes of wit.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Girls & Panzer Movie: Cinematic Concert - Fushou Akiyama Yukari no Sensha Kouza - Shoujun-hen', 'Special', 1, 'Completed', '2017-12-22', NULL, '7', 'An additional episode of Fushou Akiyama Yukari no Sensha Kouza released with the BD of the cinematic concert for the movie.', 48, 'https://cdn.myanimelist.net/images/anime/1253/115636.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Recorder to Randoseru', 'OVA', 2, 'Completed', '2012-07-17', NULL, '7', 'Unaired episodes bundled with the special edition of volume 4 of the original manga.', 785, 'https://cdn.myanimelist.net/images/anime/10/40081.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jungle Taitei (1989)', 'TV', 52, 'Completed', '1989-10-12', '1990-10-11', '7', 'Leo (a.k.a. Kimba in the U.S.) is a young ambitious lion cub who takes his father''s place as emperor of the jungle when is father is killed by poachers. Even though his father''s fate was met by the hands of humans, Leo is one of the few animals in the Jungle that doesn''t fear or feel hatred toward humans. He is not alone either, he is guided by friends of his father to help create the best animal kingdom there can be. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pyramid Game', 'ONA', 9, 'Completed', '2025-06-14', '2025-07-19', '6', 'Every Thursday afternoon, once a month, students at Love High cast their votes in a popularity poll. The result? A brutal ranking system that determines the entire social hierarchy of the school. After starting at the bottom, can new transfer student Suji make her way to the top of the pyramid? Or will she topple the game altogether?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fate/Grand Order: Fujimaru Ritsuka wa Wakaranai Season 2 Specials', 'Special', 2, 'Completed', '2025-03-19', NULL, '6', 'Specials included in the BD/DVD release of Fate/Grand Order: Fujimaru Ritsuka wa Wakaranai Season 2.', 214, 'https://cdn.myanimelist.net/images/anime/1544/148383.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Monpoke', 'ONA', 10, 'Completed', '2025-02-19', '2025-04-16', '6', '', 281, 'https://cdn.myanimelist.net/images/anime/1064/146989.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bye Bye, Earth 2nd Season', 'TV', 10, 'Completed', '2025-04-04', '2025-06-06', '6', 'Belle Lablac, the only human in an anthropomorphic animal world, is recovering from the wounds she suffered after a violent falling-out with her companion, Adonis Question. Despite feeling guilty and betrayed, Belle reaffirms her resolve to set out on a journey to discover her roots—even without him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kanojo, Okarishimasu 4th Season', 'TV', 12, 'Completed', '2025-07-05', '2025-09-20', '6', 'After the success of his crowdfunded movie featuring the woman of his dreams, Chizuru Ichinose, university student Kazuya Kinoshita resumes his life of lies and deception. Although he pretends that he has been in an ideal relationship with Chizuru for more than a year, Kazuya still mostly sees her through a rental girlfriend company''s services.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ijiranaide, Nagatoro-san 2nd Attack Mini Anime', 'ONA', 12, 'Completed', '2023-01-08', '2023-03-26', '6', 'The mini-anime for Ijiranaide, Nagatoro-san 2nd Attack released on Twitter and YouTube.', 39, 'https://cdn.myanimelist.net/images/anime/1383/132539.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shishang Zui Qiang Nan Zhujiao', 'ONA', 48, 'Completed', '2022-06-05', '2022-10-23', '6', 'The protagonist Zhao Xiaotian is gifted with supernatural abilities and possesses super self-healing ability. After an accidental explosion, he came to a new world advocating martial arts and became the grandson of the richest man Zhao family. But this identity made him repeatedly persecuted by gangsters, so he was sent by his family to the famous martial arts sect, Xiaoyaomen, to practice martial arts for self-defense. However, to everyone''s surprise, Zhao Xiaotian, who had never had a foundation in martial arts, turned out to be exceptionally talented and possessed an extraordinary talent for martial arts. Because Zhao Xiaotian''s master was worried that he was too proud, he decided to suppress teaching, which made Zhao Xiaotian mistakenly think that his strength was low, so he practiced harder. In this way, Zhao Xiaotian gradually grew up unknowingly, and gradually formed a deep friendship with the brothers and sisters in the door. However, as his strength grows, the hidden crisis gradually emerges, and he is about to face the challenge of accepting trials...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Princess Lover! Picture Drama', 'Special', 6, 'Completed', '2009-10-23', '2010-03-25', '6', 'Specials included on the Princess Lover! Blu-ray/DVD volumes.', 339, 'https://cdn.myanimelist.net/images/anime/4/18207.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aa Harimanada', 'TV', 23, 'Completed', '1992-04-23', '1992-10-01', '6', 'When Harimanada makes his grand entrance into the world of Sumo, he causes complete uproar throughout the entire arena. The novelty headmask is clearly not a good idea but not content with just ruffling the feathers of all the spectators, he sends the the entire Sumo Association into a frenzy when he arrogantly declares that he will surpass the legendary Futabayama''s consecutive run of 69 victories. Should he fail to achieve such a feat, he will immediately retire all together.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('King of Prism by Pretty Rhythm', 'Movie', 1, 'Completed', '2016-01-09', NULL, '6', 'The unit Over The Rainbow succeeds in its debut. Aiming to become like the boy band, more students enroll in Edel Rose. Hiro and the others begin practice for the Prism King Cup, an event that is held once every four years. However, a rival called "Schwarz Rose" appears... Who will become the Prism King, the one who can make girls'' hearts throb the most!?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maken-Ki! Specials', 'Special', 6, 'Completed', '2011-12-21', '2012-05-25', '6', 'Each of the six volumes of the Maken-Ki! Blu-rays will carry a 10 minute long short anime "Doki Doki! Maken-ki! Himitsu no Kunren". Secret trainings with the main characters will be animated.', 32, 'https://cdn.myanimelist.net/images/anime/1832/121753.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ebiten: Kouritsu Ebisugawa Koukou Tenmonbu', 'ONA', 10, 'Completed', '2012-07-14', '2012-09-15', '6', 'Noya Itsuki just transferred to Ebisugawa High School. Since he has always had a fascination with space, he decides to join the Astronomy Club; however, he mistakenly walks into the Asstronomy Club—a club whose members are all female otaku. Itsuki notices that the members are really weird, but he has yet to realize that he joined the wrong club. His life becomes very strange very quickly.', 28, 'https://cdn.myanimelist.net/images/anime/11/75842.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shinkansen Henkei Robo Shinkalion The Animation Recap', 'ONA', 1, 'Completed', '2018-08-02', NULL, '6', '', 621, 'https://cdn.myanimelist.net/images/anime/1175/93343.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Coffee Ikaga deshou', 'ONA', 30, 'Completed', '2018-08-24', NULL, '6', 'The anime follows a coffee food truck shop, where the barista makes an individual cup for each customer. The coffee brewed conscientiously, sincerely, and wholeheartedly helps customers unwind.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kemono Friends 2', 'TV', 12, 'Completed', '2019-01-15', '2019-04-02', '6', 'Serval and Caracal find a "human" child in the forest. As they travel with the child, they meet new Friends, uncover the secrets of Japari Park, and become involved in an event that will "shake the earth."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Monster Sonic! D''Artagnan no Idol Sengen', 'ONA', 5, 'Completed', '2017-06-14', '2017-07-19', '6', 'When D''Artagnan went to Tokyo for a little fun, she spotted an unforgettable sight: Lucifer singing while basking in moonlight in a park. From that moment, no matter if she was asleep or awake, D''Artagnan''s heart would not stop throbbing for some reason.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Carole & Tuesday Specials', 'ONA', 8, 'Completed', '2019-06-28', '2019-10-16', '6', 'Short flash animation series of Carole &amp; Tuesday released on the official YouTube and Twitter channels.', 138, 'https://cdn.myanimelist.net/images/anime/1197/142325.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maesetsu!', 'TV', 12, 'Completed', '2020-10-11', '2020-12-27', '6', 'Manzai is a traditional form of Japanese stand-up comedy where two comedians act out skits as a straight man and funny man, guiding the audience through a series of punchlines. Two determined girls, Mafuyu Kogarashi and Fubuki Kitakaze, are aspiring manzai entertainers who struggle to achieve any real success, despite their lengthy time on stage. They often partner up with manzai newcomers and their close friends—Rin Araya and Nayuta Asougi—to help in the opening acts of each other''s routines.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Animegatari', 'Movie', 8, 'Completed', '2015-04-17', '2016-03-05', '6', 'Short animations screened during intermission at TOHO Cinemas Shinjuku. Eight episodes were shown in theaters, but only six were included on the DVD release.', 931, 'https://cdn.myanimelist.net/images/anime/13/73567.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Guraburu!', 'TV', 12, 'Completed', '2020-10-08', '2020-12-24', '6', 'Anime adaptation of Guraburu!, which is 4-koma manga of Granblue Fantasy.', 1092, 'https://cdn.myanimelist.net/images/anime/1870/119993.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga Tetsudou 999: Shounen no Tabidachi to Wakare', 'Special', 1, 'Completed', '1982-04-05', NULL, '6', 'Recap of TV episodes 1, 79-81, and 112-113.', 1030, 'https://cdn.myanimelist.net/images/anime/1578/140052.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Licca-chan no Nichiyoubi', 'OVA', 1, 'Completed', '1992-07-21', NULL, '6', 'One relaxing Sunday, Licca tags along with a friend to babysit two rather grumpy little boys.', 53, 'https://cdn.myanimelist.net/images/anime/1089/113402.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seikima II Humane Society: Jinrui Ai ni Michita Shakai', 'OVA', 1, 'Completed', '1992-07-01', NULL, '6', 'Seikima II was a real-life Japanese death-metal band. Full of kabuki makeup, songs about rape, murder, and satanic destruction, and a public persona of devilish evil. The OVA purports to tell the backstory of the band, which, according to its publicity, was composed of actual demons (akuma) from the parallel dimension Makai. In the OVA, five vicious demons (the five band members), led by Demon Kogure (the lead singer), are plotting the destruction of humanity. The only effective opposition comes from the saintly Rosa, who is actually the reformed war goddess Freyja in disguise. The demons attempt to activate their ultimate weapon, the Tower of Babel, before Rosa can complete her counter weapon, the Tower of Cain. The demons triumph and are on the verge on destroying the world when their leader suddenly decides that they should, instead, form a rock-and-roll band in order to convert people everywhere into demon worshipers.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ladies versus Butlers! Tokuten Disc Music Clip', 'Special', 1, 'Completed', '2010-03-26', NULL, '6', 'Special music clip released on DVD.', 1117, 'https://cdn.myanimelist.net/images/anime/3/25044.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Donguri to Yamaneko', 'OVA', 1, 'Completed', '1988-09-30', NULL, '6', 'The Acorns and the Wildcat is a unique short film in picture-book format from the creator of Night on the Galactic Railroad and Gauche the Cellist. Unusually for an anime, a narrator reads Kenji''s story aloud while the action is played out on the screen by a succession of warm and evocative illustrations brought to life by subtle touches of animation. If the film feels somehow familiar yet you can''t put your finger on the reason why, it''s probably the sumptuously minimalist animation by Yasuhiro Nagura, who was the animation director of Mamoru Oshii''s artsy 1986 feature Angel''s Egg. That, and Kenji''s wildcat is said to have been the inspiration for Miyazaki''s Panda/Totoro creature. The idea of reading Kenji''s story aloud instead of playing it out as a drama is quite refreshing, and Kenji''s magical language and narrative style are entirely sufficient to sustain interest. Combined with the spacey music and breathtaking art, the result is a pleasantly unassuming little gem of a film.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Notari Matsutarou', 'OVA', 10, 'Completed', '1990-11-22', '1991-04-25', '6', 'A teenage school dropout finds new meaning in life when he discovers sumo wrestling, heading off to Tokyo for the bright lights and training with an aging master of the sport.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('ARP Backstage Pass: Celebrate Good Time - Short Stories', 'Special', 1, 'Completed', '2020-03-02', NULL, '5', 'Short Stories of ARP Backstage Pass that describe the secret of the ARP members and everyday life.', 249, 'https://cdn.myanimelist.net/images/anime/1327/106289.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hyoutan', 'Movie', 1, 'Completed', '1976-01-01', NULL, '5', 'Independent animation by Suzuki Shinichi.', 964, 'https://cdn.myanimelist.net/images/anime/13/71329.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doamaiger D', 'TV', 13, 'Completed', '2015-01-05', '2015-03-30', '5', 'Kyougoku Daijirou is the 15th generation owner of the Kyoto sweets shop Amashoudou. One day, Daijirou discovers a giant robot named Doamaiger D in his store''s basement. At the same time, enemies called "Mekaijuu" appear in Kyoto and begin wreaking havoc.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Momoya x Peeping Life: Go en desu yo!', 'Special', 4, 'Completed', '2013-04-25', '2013-05-16', '5', 'This is a sketch drama consisting of four episodes on dating in collaboration with the leading food company Momoya.', 184, 'https://cdn.myanimelist.net/images/anime/6/52087.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Circuit no Ookami II: Modena no Ken', 'OVA', 1, 'Completed', '1990-12-21', NULL, '5', 'The adventures of Ken Ferrari, a former racer and motor journalist with an appetite for women. Based on the manga by Satoshi Ikezawa.', 889, 'https://cdn.myanimelist.net/images/anime/1192/90761.jpg');
