INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koikeya SDGs Gekijou Suss to Tina Season 2', 'TV', 13, 'Completed', '2022-04-03', '2022-06-26', '5', 'Season season of Koikeya SDGs Gekijou Suss to Tina.', 327, 'https://cdn.myanimelist.net/images/anime/1562/152205.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koikeya SDGs Gekijou Suss to Tina', 'TV', 13, 'Completed', '2021-10-03', '2021-12-26', '5', 'The story is set on the fictional Hexagon Island. The twin female ninjas Suss and Tina, who have protected the island for generations, and the AI ​​robot Bull, use their wits and words to fight against the SDG monsters that appear one after another. The story depicts their struggle to save the Earth, borrowing wisdom from all over the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('BeyWarriors: Cyborg Specials', 'ONA', 2, 'Completed', '2015-02-27', NULL, '5', '', 983, 'https://cdn.myanimelist.net/images/anime/1170/152198.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Death Stranding: Mosquito', 'Movie', 1, 'Upcoming', NULL, NULL, '5', '', 19, 'https://cdn.myanimelist.net/images/anime/1379/152196.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shen Zai Jiong Tu', 'ONA', 40, 'Airing', '2025-09-29', NULL, '5', 'A divine master accidentally fell into the mortal realm, losing all his magical powers. He''d spent millennia trying to unlock the secrets of ascension, only to discover that the first step was to return to earth, starting all over again! The divine master had intended to emulate other cultivators and plunge into arduous cultivation, but who could have imagined that a chef, appearing out of nowhere, would unexpectedly unlock a new path for him to "level up through food." Having lived on spiritual energy and dew since childhood, when had the noble divine master of the Ninth Heaven ever encountered such down-to-earth human delicacies? He loved to eat, to eat more, and to fight over the food! It wasn''t until he''d collected every delicacy in the world, with those kneeling before him in submission, that the divine master realized: I''d eaten myself into invincibility!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ojamajo Carnival!!: Yuru Tabi-hen', 'ONA', 1, 'Completed', '2025-03-08', NULL, '5', 'Third music video commemorating the 25th anniversary of the franchise.', 1030, 'https://cdn.myanimelist.net/images/anime/1911/152055.jpg');
