INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kiitarou Shounen no Youkai Enikki: Jonan no Saijitsu', 'Special', 1, 'Completed', '2017-01-27', NULL, '6', 'An unaired episode 13 of Kiitarou Shounen no Youkai Enikki included on the DVD/BD release. Kiitarou runs into typical ecchi manga tropes due to Lucky Eros albeit he doesn''t feel "lucky" and tries to avoid everything happening between him and the female youkai.', 200, 'https://cdn.myanimelist.net/images/anime/1833/112407.jpg');
