INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Minna de Tonda: Jouhoku Chuugaku 2-nen 1-kumi no Kiroku', 'OVA', 1, 'Completed', '2003-01-07', NULL, '5', 'An educational film about compassion. The story follows a class trying to break a jump rope record and one student is terrible at the task. The issue causes a divide in the classroom.', 513, 'https://cdn.myanimelist.net/images/anime/7/74009.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('himitsukesshatakanotsume.jp Specials', 'Special', 2, 'Completed', '2012-12-12', '2013-02-06', '5', 'The episodes parody the Batman Begins and The Dark Knight Rises films. They were only released on the DVD/BD Box sets of himitsukesshatakanotsume.jp.', 214, 'https://cdn.myanimelist.net/images/anime/2/74059.jpg');
