INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shimajirou no Wow! Movie 11: Shimajirou to Yuuki no Uta', 'Movie', 1, 'Completed', '2023-06-01', NULL, '5', '', 792, 'https://cdn.myanimelist.net/images/anime/1358/147319.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Haruniwa Ie no 3 Nin-me', 'TV', 45, 'Completed', '1998-01-23', '1998-03-26', '5', 'The Haruba family is a wonderful family of three kids. The protagonist is the youngest son of the three siblings, who is in actuality, a spirit. The story unfolds in a nostalgic background of Japan and relates the life of this incredible family.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hanitarou desu.', 'TV', 70, 'Completed', '1997-10-06', '1998-01-22', '5', 'Shown daily during the Super J Channel news programme.', 1030, 'https://cdn.myanimelist.net/images/anime/12/84056.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Genji Fantasy: Neko ga Hikaru Genji ni Koi wo Shita', 'Special', 1, 'Completed', '2019-04-02', NULL, '5', 'The Tale of Genji Museum in Uji City, Kyoto will be airing a short film blending history and fantasy, the story follows a modern high school girl named Hana who is transformed into a cat and transported back in time. She travels 1,000 years ago to the Heian Era as portrayed in The Tale Of Genji, arguably the most famous novel in Japanese literature. Guided by the novel''s titular character Hikaru Genji, Hana experiences firsthand the emotions that the author Murasaki Shikibu depicted in her novel. The short features scenes based on The Diary of Lady Murasaki and other historical materials, such as the real-life noble Fujiwara no Michinaga swiping early drafts of The Tale Of Genji because he could not wait to read chapters as Murasaki wrote them. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maple Town Monogatari (Movie)', 'Movie', 1, 'Completed', '1986-07-12', NULL, '5', '', 1030, 'https://cdn.myanimelist.net/images/anime/1148/145183.jpg');
