INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Onimomomomo', 'ONA', NULL, 'Airing', '2025-06-21', NULL, '5', '', 39, 'https://cdn.myanimelist.net/images/anime/1577/150680.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Goumon Baito-kun no Nichijou', 'TV', NULL, 'Upcoming', '2026-01-05', NULL, '5', 'This is a world where killing and torture are legalized. Sero, a part-time worker at a torture company, enjoys torturing people every day with his senior colleague, Siu. With the addition of new part-timers Mike and Hugh, fun torture life continues!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maou no Musume wa Yasashisugiru!!', 'TV', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'Demon King Ahriman has a problem: his daughter, Dou, loves everyone! Consequently, Ahriman had to halt his invasion of the world in the worry that his daughter''s behavior is not one befitting someone of her kind. She loves making friends, helping others, and bringing happiness to all creatures including their enemies, the humans.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ying Shi', 'Movie', 1, 'Completed', '2010-01-01', NULL, '5', 'A boy takes an adventure in the old and shabby temple which was burnt down for a secret reason. The film is based on a story in Taiwanese folk culture.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiong Chumo: Chong Fan Di Qiu', 'Movie', 1, 'Completed', '2022-02-01', NULL, '5', 'Bramble has always dreamed of becoming a great hero in order to gain recognition from everyone, especially his older brother, Briar. A piece of the alien nucleus that fell from the sky broke the peace of Pine Tree Mountain, but unexpectedly, Bramble merged with the alien nucleus and became a bear with alien wisdom and energy. However, this also brought about the pursuit of "alien" Abu who wanted to reclaim the nucleus.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wasted Chef', 'Movie', 1, 'Upcoming', NULL, NULL, '5', '', 162, 'https://cdn.myanimelist.net/images/anime/1307/148217.jpg');
