INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yankee Hamster Season 3', 'ONA', 50, 'Completed', '2022-05-06', '2023-04-14', '5', 'The third season of Yankee Hamster.', 684, 'https://cdn.myanimelist.net/images/anime/1546/136281.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jian Gu', 'ONA', 60, 'Completed', '2023-06-16', '2023-12-29', '5', 'Ning Yi, a commoner from Xiling, possesses a special gluttonous physique. He relies on Pei Fan, who is burdened with a blood feud, for survival. Later, he becomes entangled with the mysterious girl Xu Qingyan through the rare treasure bone flute. Xu Zang, a sword immortal from Shu Mountain, teaches Ning Yi the ultimate swordsmanship, and the bone flute helps him achieve the honor of being a swordsman, bearing the responsibility of saving the world and bringing light.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yancharu Moncha', 'TV', 80, 'Completed', '1999-04-05', '2002-03-30', '5', 'An NHK toddler''s anime following a green tea monkey and his mischief.', 90, 'https://cdn.myanimelist.net/images/anime/13/72124.jpg');
