INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dokidoki Gakuen Kessen!! Youki Daimashiro', 'OVA', 1, 'Completed', '1988-09-20', NULL, '5', 'Four heroes set out to rescue girls taken by ayakashi.', 92, 'https://cdn.myanimelist.net/images/anime/5/52097.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tokyo Juushouden', 'OVA', 3, 'Completed', '1999-07-23', '2000-01-21', '5', 'Long ago, in feudal Japan, there was a fierce warrior named the Demon King. He controlled a band of demons, known as the Kyouma. Only the powers of ten warriors sealed the Demon King away and kept the Kyouma under control. But now, Lord Shindigan, a powerful Kyouma is planning to free the Demon King, and the reincarnations of the ten warriors must band together and save the earth. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Psychic Force', 'OVA', 2, 'Completed', '1998-05-25', NULL, '5', 'When James "Burn" Griffith collides with a young man on his motorcycle, he enters a world of turmoil. He takes the injured party, Keith Evans, to his home to recuperate—but soon armed men in suits arrive in pursuit of Keith. Unable to comprehend Keith''s relationship with these thugs, Burn protects him for as long as he can.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hachimitsu Suicide Machine', 'ONA', 1, 'Completed', '2021-03-26', NULL, '5', 'A novel writer and his family move into a new house that was used as a set in his favorite horror movie. There, strange things start to happen.', 1077, 'https://cdn.myanimelist.net/images/anime/1894/113740.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Genma Taisen', 'Movie', 1, 'Completed', '1983-03-12', NULL, '5', 'From the depths of space he is coming...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Phantom Yuusha Densetsu', 'OVA', 1, 'Completed', '1991-01-24', NULL, '5', 'Yazawa, a Japanese pilot, suffers a crash in his Phantom jetfighter. After a six month recovery, his old friend from an airplane magazine wants him to investigate the appearance of a Phantom in an armed conflict in El Salvador. Yazawa''s investigations makes him wind up in an international arms conspiracy. Based on a series of military fiction novels.', 540, 'https://cdn.myanimelist.net/images/anime/1288/146189.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dia Horizon', 'ONA', 3, 'Completed', '2017-08-10', '2017-08-21', '5', 'The web anime of Dia Horizon; characters are featured as chibis as they break the 4th wall to talk about their own real-life mobile game (which is being released this month). As well as promoting the full length TV anime coming out in a October 2017 as well as the 4-koma manga available now.', 281, 'https://cdn.myanimelist.net/images/anime/7/87292.jpg');
