INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ghost', 'Movie', 1, 'Upcoming', '2027-01-01', NULL, '5', 'Everyone has a "ghost" in their heart—feelings that are hard to express but still real. This story follows Nike, a brave and lonely girl who stands up against the unfairness of the world to protect the starry sky. Along the way, she begins to change through the people she meets and the emotions she discovers in herself.
