INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hula Kappa: Owakare-kai (2) Atarashii wo Tomodachi', 'Special', 1, 'Completed', '2006-01-01', NULL, '5', 'An alternative episode 78 created from TV viewer''s ideas. In this special, when Takeda-kun returns to introduce himself again, a new character comes along with him called Ayaka-chan. After introductions of everyone, Pochi the seal comes dancing on screen with two other seals never before seen in the show.', 633, 'https://cdn.myanimelist.net/images/anime/12/83259.jpg');
