INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gan Gan Ganko-chan', 'TV', 10, 'Completed', '2016-12-19', '2017-03-27', '5', 'The anime follows a boy named Gen, who time travels from the year 2020 to a distant future where humanity has gone extinct. He begins staying at the Ganko family home in the Rustling Forest, where he has none of the amenities he is used to: no electricity, gas, or running water, as well as no television, smartphones, convenience stores, snacks, or games. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchi no 3 Shimai Movie', 'Movie', 1, 'Completed', '2019-04-26', NULL, '5', '"An animated version of a super child-rearing essay blog. The cute three sisters Fu, Su, and Chi, along with their mom and dad, have a lot of interesting things going on in their "happy-go-lucky" daily lives."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sentai Hero Sukiyaki Force: Gunma no Heiwa wo Negau Season', 'TV', 24, 'Completed', '2017-01-09', '2017-06-19', '5', 'The anime will be a "surreal comedy" that emphasizes Gunma prefecture''s self-sufficiency in ingredients for sukiyaki. The story centers around the titular Sukiyaki Force, created by Professor Warishita, who fight against the forces of Kiraida, who have come to Gunma and threaten to destroy the world.', 849, 'https://cdn.myanimelist.net/images/anime/10/83035.jpg');
