INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ulysses 31 Pilot', 'Special', 1, 'Completed', '1980-01-01', NULL, '6', 'Unaired pilot episode for the TV series.', 990, 'https://cdn.myanimelist.net/images/anime/9/29487.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yami Shibai 15', 'TV', 13, 'Completed', '2025-07-14', '2025-10-06', '6', 'Fifteenth season of Yami Shibai.', 403, 'https://cdn.myanimelist.net/images/anime/1975/150436.jpg');
