INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Da Yuan Hun', 'ONA', 12, 'Completed', '2025-06-02', '2025-08-11', '5', 'Demons are rampant, countless lives are lost. A strange stone descends in the troubled times, transforming into a clever stone monkey, shouldering the responsibility of saving the world. Because this is the origin of Sun Wukong becoming a great demon, the ape soul is about to awaken!
