INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Daoying', 'Movie', 1, 'Completed', '2022-01-01', NULL, '5', 'Seed who can’t get under the sun and the shadow who needs light to exist is the meaning of life for each other. Seed wants to be with the shadow on a journey in this strange world.
