INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wuxia', 'Movie', 1, 'Completed', '2017-01-01', NULL, '5', 'A girl who was floating freely in the water accidentally gets her skin cut by a sailboat passing by. The story is derived from personal experience, recreating the senses of women in love and the unique inner sense of time through creation.
