INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rifle Is Beautiful: Zenkoku Taikai Is Mokuzen', 'Special', 1, 'Completed', '2019-12-01', NULL, '6', 'Recap of the first seven episodes of Rifle Is Beautiful.', 848, 'https://cdn.myanimelist.net/images/anime/1347/104573.jpg');
