INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Afghanistan Paghman-mura no Monogatari: Boku no Mura ni Circus ga Kita', 'OVA', 1, 'Completed', '2002-01-01', NULL, '5', 'Following the previous story, a circus comes to town displaced by the War in Afghanistan. This one has a stronger focus on the actual war affecting the citizens.', 1030, 'https://cdn.myanimelist.net/images/anime/3/66027.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Afghanistan Paghman-mura no Monogatari: Sekaiichi Utsukushii Boku no Mura', 'OVA', 1, 'Completed', '2002-01-01', NULL, '5', 'An educational film about Paghman, Afghanistan showing the simple life and beauty of the region and its regular citizens to juxtapose the War in Afghanistan that stared in real life the year prior.', 1030, 'https://cdn.myanimelist.net/images/anime/4/66025.jpg');
