INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ao no Miburo: Serizawa Ansatsu-hen', 'TV', NULL, 'Upcoming', '2025-12-20', NULL, '5', 'Second season of Ao no Miburo.', 542, 'https://cdn.myanimelist.net/images/anime/1753/152079.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dokodemo Makibao', 'ONA', 24, 'Completed', '2024-12-16', '2025-03-13', '5', 'A spin-off of Midori no Makibao to celebrate the 30th anniversary of the series. It depicts "everyday races" such as "who can pick up the most trash at the beach" and "who can get to the basement of the department store first to get the food that is limited to just one person."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sorotani no Keibatchi', 'TV', 4, 'Completed', '2024-11-28', '2024-12-19', '5', 'Behind the scenes of the serious competition in G1 races, you''ll see the quirky and hilarious tactics played out by jockeys, horses, spectators, and trainers. Don''t miss the emotions of the people and horses who, with their complicated circumstances and personal feelings in mind, are determined to win the G1 and make the right predictions!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Douse, Koishite Shimaunda. Season 2', 'TV', NULL, 'Upcoming', '2026-01-09', NULL, '5', 'Second season of Douse, Koishite Shimaunda..', 1069, 'https://cdn.myanimelist.net/images/anime/1054/153719.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sittakaman!', 'ONA', 8, 'Completed', '2011-01-07', NULL, '5', 'Kenji and Mamoru''s simple questions are challenged by Shittakaman, who pretends to know what he''s doing!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kodomo datta Tsurai yo', 'ONA', NULL, 'Airing', '2019-07-02', NULL, '5', 'Watabe and Nokishita are primary school students living in Japan in early 1990s. They like to play a popular RPG game or buy the popular chocolate snacks with stickers inside.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sore Shikanai Wakenai deshou', 'Special', 1, 'Completed', '2023-03-22', NULL, '5', 'The story centers on a girl who worries too much about the future, and her grandmother who tells her that the future has many possibilities. Through her family, the girl learns a fun way to view the future.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nushen You Dian Ling', 'ONA', 18, 'Completed', '2023-04-24', '2023-08-14', '5', 'Yao Ling and Hu Xiaozhen, who parted ways due to a misunderstanding in childhood, reunited in the academy after they grew up. The infatuated female protagonist hopes to continue writing a sweet journey with the male protagonist, but due to the appearance of the mysterious administrator, Ma Shen, "accidents" occur frequently. Under the lure of Ma Shen''s plan, the two became acting administrators and they help spirits to realize their long-cherished dreams, in order to continue their progress in love. Through the experience of missions again and again, the relationship between Hu and Yao becomes deeper and deeper, and they are moving towards the road of righteousness. But the true purpose of Ma Shen gradually implicates the operating laws behind the world, and more mysteries, and dangers lie between the hero and heroine. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chan Chiho Challenge Channel', 'ONA', NULL, 'Airing', '2023-02-10', NULL, '5', 'Video distributor Chan Chiho delivers various challenges related to Pokemon "Chan Chiho Challenge Channel."
