INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kore Kaite Shine', 'TV', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'Ai Yasumi, a first-year high school student living on Izu-Oshima, loves manga more than anything. When she learns that her long-admired, yet long-inactive, favorite manga artist Hoshi no Rei will be exhibiting at COMITIA, she sets off on a journey to Tokyo.
