INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mukashibanashi Dokkiri Anime', 'ONA', 4, 'Completed', '2019-02-09', '2019-05-16', '5', 'CoroCoro Comic''s Yarisugi!!! Itazura-kun, in honor of it''s 3rd manga volume going on sale, received web shorts on CoroCoro Comic''s official YouTube channel. Itazura-kun loves pranks and thinks about them 24/7. These web shorts are Itazura-kun''s re-imagining of classic folktales such as Cinderella and Momotarou.', 468, 'https://cdn.myanimelist.net/images/anime/1948/99820.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ero◆Lover', 'ONA', 30, 'Completed', '2019-03-22', '2019-01-01', '5', 'There is a dorm where male and female students live together in order to have children. Miyu enrolls at the school with this dorm, and the domineering yet attractive dorm leader Heiji becomes her roommate. Miya resists Heiji at first, but the two gradually grow closer by living together. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ninja Bear the Animation★ PV', 'Special', 1, 'Completed', '2016-11-11', NULL, '5', 'The Ninja International Kindergarten in the Land of White Goats is where kids trying to become the world''s best ninjas go to school. Ninja Bear is aiming to become the master of the food chain or, in short, a master ninja! He''s training night and day. Other colorful and unique characters like Hige-chan, Bunnie Antoinette, Ham Rock Star, and Usawan are classmates at the school. No challenge is too great for these cool guys! Enjoy their carefree and mischievous life at the Ninja Kindergarten!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kai: Geoul Hosu-ui Jeonseol', 'Movie', 1, 'Completed', '2016-08-17', NULL, '5', 'Kai: Geoul Hosu-ui Jeonseol is an adaptation of Hans Christian Andersen''s The Snow Queen in a central Asian setting.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aqua Kids', 'TV', 26, 'Completed', '2004-04-01', '2004-09-23', '5', 'The polar ice caps have melted due to global warming. The human race has been stuck on one island as the marine life begins to evolve. Kids use a submarine and the help of their robot companions to explore the depths and come upon an ancient secret underwater civilization with treasure. It''s a new hope for the human race to live under water but a money hungry real-estate tycoon stands in their way of peace.', 177, 'https://cdn.myanimelist.net/images/anime/4/82405.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pittanko! Nekozakana', 'TV', 50, 'Completed', '2016-10-02', '2017-09-17', '5', 'On a distant southern island, a fish (sakana) opened its mouth for a cat (neko), thus "nekozakana" (cat-fish) is born.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ohayou! Kokekkou-san', 'TV', 50, 'Completed', '2016-10-02', '2016-09-17', '5', 'Kokekkou-san is a mother hen in a big chicken family. Keeping everyone and everything right is not an easy job for her.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dochamon Junior 2', 'TV', 16, 'Completed', '2016-10-10', '2017-02-27', '5', 'The second season of Dochamon Junior.', 153, 'https://cdn.myanimelist.net/images/anime/9/82316.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('GJ8man', 'ONA', 73, 'Completed', '2016-10-08', '2021-08-08', '5', 'Gorou Joe is a boy who lives a carefree life in the small historical town of Gujo Hachiman in Gifu prefecture. One day an old self-professed "water fairy" appears in front of Joe, and tells him to help people, and grants Joe the power to turn into "GJ8 Man" (a pun on Gujo Hachiman, as the number 8 is pronounced "hachi" in Japanese, and the "hachi" in "Hachiman" uses the kanji for the number 8).
