INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chinpu na Otoko', 'Movie', 1, 'Completed', '2018-01-01', NULL, '5', 'Unable to bear children, I produced labor robots. However, people did not accept the robots and began to eliminate them. I decided to take revenge on the person responsible for destroying them. Anyone who kills my children must be a monster.
