INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Senlin Li De Jin Yueliang', 'Movie', 1, 'Completed', '1989-01-01', NULL, '5', 'The moon hangs high, and a band is playing under the command of a lion on the top of the mountain... The lunar eclipse is quietly going on, the music stops abruptly, all the animals are commotion, and the little red bird tells everyone that this is a lunar eclipse. The lion and all the animals believed the wolf and the fox''s deception, thinking that the tengu ate the golden moon. In the night, the deception hangs over the forest.', 792, 'https://cdn.myanimelist.net/images/anime/1759/118620.jpg');
