INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gudu De Lily', 'Movie', 1, 'Completed', '1990-01-01', NULL, '5', 'The protagonist of Gudu De Lily is a young girl named Lily who dreams of one day becoming a famous singer. She sets off on a mission to reach her dreams with the help of her friends. She encounters several challenges along the journey and gains insightful knowledge about courage, friendship, and determination. Lily learns how to use music to express her feelings and realizes her true potential with the aid of her companions.', 792, 'https://cdn.myanimelist.net/images/anime/1175/118628.jpg');
