INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Neko to Ryuu', 'TV', NULL, 'Upcoming', '2026-07-01', NULL, '5', 'Deep in the forest where ferocious beasts and magical creatures dwell, a cat takes in an orphaned baby dragon as one of her own.
