INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Made in Abyss: Mezameru Shinpi', 'Movie', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'Sequel to Made in Abyss: Retsujitsu no Ougonkyou.', 480, 'https://cdn.myanimelist.net/images/anime/1411/151354.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Souzou Teki Shinka', 'Movie', 1, 'Completed', '2019-01-01', NULL, '5', 'Where do I come From? What am I? Where am I going? Where do we come from? What are we? Where are we going? Life keeps traveling across the universe.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Iyab! Space Jungle 2nd Season', 'TV', 52, 'Completed', '2016-01-01', '2016-08-26', '5', 'The second season of Iyab! Space Jungle.', 652, 'https://cdn.myanimelist.net/images/anime/1207/132702.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wo Shi Xuexiao Weiyi de Renlei', 'ONA', 52, 'Completed', '2023-01-17', '2023-07-04', '5', 'An ordinary human named Ah-Ren, suffering from severe social anxiety, transfers to an animal school where "there are no humans." Here, his classmates are all sorts of animals, and even the teachers are rare species like Yangtze alligators and pandas. As an ordinary human, Ah-Ren is completely lost in lessons on spinning silk, nest building, bioluminescence, and molting, gets repeatedly outmatched by the animals in physical education, and even suffers a crushing defeat in academic subjects! Besides, to graduate from this animal school, Ah-Ren needs to complete a special task—to become friends with all the animals on an animal dating app. With this impossible task in mind, a heartwarming and hilarious story unfolds, from initial anxiety to bittersweet farewell.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gunma-chan Season 2', 'TV', 13, 'Completed', '2023-04-08', '2023-07-01', '5', 'The second season of Gunma-chan, an anime series based on the Gunma Prefecture mascot character, Gunma-chan.', 91, 'https://cdn.myanimelist.net/images/anime/1471/132675.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiao Hua Xian 5th Season: Si Shi Huayu - Chun Xia', 'ONA', 26, 'Completed', '2019-07-24', '2019-10-16', '5', 'Fifth season of Xiao Hua Xian.', 1008, 'https://cdn.myanimelist.net/images/anime/1631/108511.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Benkai to Ushiwakamaru', 'Movie', 1, 'Completed', '1999-12-04', NULL, '5', 'This is the story of the extraordinary Benkei, who after having met his enemy Yoshitsune in his childhood (then named ''Ushiwaka'') came to guard him as a lifetime partner in later years.', 1021, 'https://cdn.myanimelist.net/images/anime/1514/113958.jpg');
