INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Future Kid Takara', 'TV', 11, 'Completed', '2025-11-08', '2025-11-09', '5', 'Future Kid Takara will be an action-packed, family-oriented film set in a dystopian future. The adventure story will feature a girl named Sara who is time warped into the year 2100, where she and the protagonist Takara try to navigate a world ravaged by the effects of global warming. Title and story subject to change
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sore Ike! Anpanman Movie: Roboly to Pokapoka Present', 'Movie', 1, 'Completed', '2023-06-30', NULL, '5', 'Comet Robo is a place where robots who can make anything live. The robot girl who lives on this planet, Roboly, is always the best at what she does. However, she learns that there is only one "important thing" that even she can''t make, and leaves Comet Robo to find it. During the journey, Roboly and her partner, the little robot bird Koto, pick up a gift box containing a nice music box and come to Anpanman''s world to find the owner.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mouse Doubutsuen', 'Movie', NULL, 'Airing', '2016-08-29', NULL, '5', 'An original anime for the talent management agency Mausu Promotion.', 693, 'https://cdn.myanimelist.net/images/anime/1727/132532.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fighting 32nd Olympic', 'ONA', 1, 'Completed', '2022-02-15', NULL, '5', 'An Olympic Opening AD made by SteamWorks Studio using paper-cut animation. This animation used 45 kinds of different paper and more than 600 pieces of props.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Motto! Majime ni Fumajime Kaiketsu Zorori 2nd Season', 'TV', 25, 'Completed', '2021-04-02', '2021-10-22', '5', 'Sequel to Motto! Majime ni Fumajime Kaiketsu Zorori', 53, 'https://cdn.myanimelist.net/images/anime/1337/118275.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Onimaru: Senjou ni Kakeru Itsutsu no Seishun', 'OVA', 1, 'Completed', '1990-04-25', NULL, '5', 'During the Onin wars in Japan''s medieval Muromachi era, five powerful warriors hire out their services to the highest bidder. Onimaru is the leader; Bo handles demolitions; Saru is as agile as a monkey; Osamu is a cool tactician; and Kiri is the sexy swordswoman. The group gains an extra member when Onimaru rescues Princess Aya who naturally falls in love with him and refuses to go away.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gokuu no Daibouken Pilot', 'Special', 1, 'Completed', '1966-06-12', NULL, '5', 'In this film, because of complaints from children that Goku is depicted as too much of an eager student, he is instead portrayed as a very naughty modern boy. It then received so many complaints from the PTA about its bad language that it was forced out of the show after all.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doctor Mambo & Kaitou Jibako: Uchuu yori Ai wo Komete!!', 'Special', 1, 'Completed', '1983-09-12', NULL, '5', 'In this one-shot adaptation of one of Morio Kita''s Dr. Mambo SF novels, the dashing Dr. Mambo and his unlikely sidekick, Jibako the thief, help Princess Laura, former ruler of Eden, regain her birthright from the usurping President Capo. 
