INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('667-tsuu no Love Letter', 'Special', 1, 'Completed', '2023-03-20', NULL, '6', '667 Love Letters was produced to commemorate the resumption of sales of Lipton paper pack series milk tea, which was discontinued in March 2022. 
