INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Watashi no Hashtag ga Baenakute.', 'Special', 1, 'Completed', '2023-01-18', NULL, '6', 'The story is set in a ''smart city'' envisioned by Kyocera, where people express themselves through hashtags on overhead displays.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gowapper 5 Gordam', 'TV', 36, 'Completed', '1976-04-04', '1976-12-29', '6', 'Five youths from Edo City explore a strange rocky island and discover the mecha that Doctor Hoarai had been creating in order to resist the impending attack by a race of subterranean rock people. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('CMFU Xueyuan: Shenshi Ji Jijian', 'ONA', 24, 'Completed', '2017-11-21', '2018-05-02', '6', 'The recruitment of new students in various clubs of CMFU Academy is in full swing. Freshman Minnie has joined the CMFU Fencing Club because of her fascination with "Three Musketeers". The swordsman contest is coming soon, and the president Chu Zhuoran intends to conduct an internal trial in the fencing club to select contestants for the swordsman contest. Minnie was excluded because of her zero foundation, but she didn''t get discouraged and approached the president Chu Zhuoran to ask for fair participation in the selection. In desperation, Chu Zhuoran decided to give Minnie a week to personally train her. The Fencing Club of the Yunzong Academy in the same city also came here, not only to find out the strength of the newly recruited female swordsmen of CMFU, but Lian Kai, the president of the Fencing Club of the Yunzong Academy, had a holiday with A Qiao, a member of the CMFU Fencing Club. This series shows how the CMFU Academy Fencing Club prepares for the swordsman competition and Minnie''s growth as a zero-base fencer, conveys the charm of campus sports, encourages more audiences to learn about fencing and love the sport of fencing.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tales of HR', 'ONA', 13, 'Completed', '2018-06-17', '2019-12-14', '6', '', 813, 'https://cdn.myanimelist.net/images/anime/1637/93339.jpg');
