INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sonyeonjangsu', 'TV', 50, 'Completed', '1982-01-01', '1997-01-01', '5', 'The brave young warrior Seo-Me defeats the SeoGuk invaders. After defeating Hobi, Seo-Me and his comrades return home. Meanwhile Hobi survived after falling and some people rescued him out.', 758, 'https://cdn.myanimelist.net/images/anime/1354/100287.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pro Yakyuu wo 10-bai Tanoshiku Miru Houhou Part 2', 'Movie', 1, 'Completed', '1984-04-21', NULL, '5', 'Sequel of The Racing Baseball.', 540, 'https://cdn.myanimelist.net/images/anime/13/49121.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Norasco Specials', 'Special', 6, 'Completed', '2014-12-10', '2015-08-12', '5', 'Norasco episodes released only on 3 of the 4 Norasco DVDs.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chuizhi Shijie', 'ONA', 12, 'Completed', '2019-06-18', '2019-08-27', '5', '', 369, 'https://cdn.myanimelist.net/images/anime/1850/100436.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ju Bing Chang Cheng Zhuan', 'TV', 40, 'Completed', '2019-01-26', '2019-03-24', '5', 'The main character of ‘The Great Wall Warrior’ is a wolf raised up by herbivores. The adventure starts with his pure mind of being the hero who can save the world from the Giant Warrior, but he has unconsciously involved in some big scheme…
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Darwin''s Game: Log Line', 'Special', 1, 'Completed', '2020-02-01', NULL, '7', 'Recap of the first 4 episodes of Darwin''s Game.', 602, 'https://cdn.myanimelist.net/images/anime/1975/111967.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aldnoah.Zero Extra Archives', 'Special', 1, 'Completed', '2015-01-04', NULL, '7', 'Recap of the first season of Aldnoah.Zero series.', 14, 'https://cdn.myanimelist.net/images/anime/2/70417.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chuuzumou', 'Movie', 1, 'Completed', '2010-01-03', NULL, '7', 'Once upon a time, there lived an old man and his wife in a mountain. One night, he found a bunch of mice heading to somewhere. He followed them and saw the mice playing Sumo. The man and his wife happened to know the mice living in their house always lose the matches, and they gave them some foods to support the team.', 893, 'https://cdn.myanimelist.net/images/anime/6/23788.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zhan Shuang Panini', 'ONA', 12, 'Completed', '2020-10-27', '2021-01-12', '7', 'Based on the video game "Punishing: Gray Raven."', 130, 'https://cdn.myanimelist.net/images/anime/1045/109449.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Youjo Shachou', 'ONA', 13, 'Completed', '2021-01-01', NULL, '7', 'Najimu Mujina is just your average five-year-old girl—who also happens to be the CEO of Mujina company. While she leaves most of the important work to her secretary Yuki Karuizawa, she often tries to act like a CEO with her inadequate business jargon. But, although her innocent efforts can be unexpectedly kind and uplifting, it just usually adds to the troubles of those around her, such as diligent employee Mayu Warito and her fellow colleagues at Mujina Company.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Futatsu no Kurumi', 'Special', 1, 'Completed', '2007-08-15', NULL, '7', 'Futatsu no Kurumi is a short story following 12-year-old Ayaka as she is teleported back in time to the fire bombing of Tokyo in 1945 and covers her experiences in this very different and unfamiliar environment.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga Tetsudou 999: Diamond Ring no Kanata e', 'Movie', 1, 'Completed', '2009-09-09', NULL, '7', 'July 22, 2009. Galaxy Express 999 made a brief stop at Kagoshima on the day of total solar eclipse. Tetsuro gives a pass for the 999 to a boy named Kakeru dreaming of becoming an astronaut, saying "It''s up to you whether you can use this pass or not".
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ie Naki Ko Remy Specials (2001)', 'Special', 2, 'Completed', '2001-07-14', '2001-07-15', '7', 'A summary of the Ie Naki Ko Remy full series aired as a TV specials.', 607, 'https://cdn.myanimelist.net/images/anime/11/64147.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Element Hunters', 'TV', 39, 'Completed', '2009-07-04', '2010-03-27', '7', 'In 2029, a large scale ground sinkage occurred in the Mediterranean Sea. Chemical elements such as oxygen, carbon, gold, molybdenum, and cobalt disappeared from the earth''s crust suddenly. The human population was decreased by 90% in sixty years. Researchers found out that the disappeared elements were drained into a planet "Nega Earth", located in another dimension. To save the Earth, a special team called the "Element Hunters" is organized. All of the members are under 13 years old, because young and flexible brains are needed to access "Nega Earth".', 375, 'https://cdn.myanimelist.net/images/anime/1059/133878.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kodai Ouja Kyouryuu King: Yokuryuu Densetsu', 'TV', 30, 'Completed', '2008-02-03', '2008-08-31', '7', 'Sequel series to Kodai Oja Kyoryu King. The Alpha Gang and the Ancients return. While the parents are talking, they are kidnapped by Gunenco, a member of the Zanjark Space Aliens. This causes the Alpha Gang and D-Team to join forces against the Zanjark Space Aliens in their plot to obtain the Cosmos Stones. Seth later returns as an ally to the Zanjark space aliens. Jark, the leader of the Zanjark, provides the dinosaur cards', 974, 'https://cdn.myanimelist.net/images/anime/13/23619.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koihime†Musou: Gunyuu, Seitoukaichou no Za wo Neratte Aiarasou no Koto - Ato, Porori mo Aru yo!', 'OVA', 1, 'Completed', '2009-04-01', NULL, '7', 'OVA of Koihime Musou in a school environment, where factions of 4 individuals fight off in school athletic events to obtain the positions of Student Council seats.', 241, 'https://cdn.myanimelist.net/images/anime/8/22586.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sky Girls OVA', 'OVA', 1, 'Completed', '2006-08-25', NULL, '7', 'After the first war between humanity and the alien species known as Worms, the Earth is a shadow of its former self, with many landmasses submerged and countless human lives lost. When the Worms return, nearly every able body is drafted to join the desperate fight. Otoha Sakurano, Eika Ichijou, and Karen Sonomiya are three young girls tasked with forming an elite unit of "Sonic Divers": soldiers using innovative new exoskeleton technology to enhance their combat. When their covert carrier is viciously ambushed, the girls must suit up and prove that their unit has what it takes to protect humanity.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Akuma no Riddle', 'TV', 12, 'Completed', '2014-04-04', '2014-06-20', '7', 'Tokaku Azuma has just transferred to the elite Myoujou Academy, a private girls'' boarding school. But there is a catch: she, along with 11 of her fellow students in Class Black, is an assassin taking part in the challenge to kill their sweet-natured classmate, Haru Ichinose. Whoever succeeds will be granted their deepest desire, no matter the difficulty or cost. However, each assassin only gets one chance; if they fail to kill her, they will be expelled.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Konchuu Monogatari Minashigo Hutch', 'TV', 91, 'Completed', '1970-04-07', '1971-12-28', '7', 'Hutch is a small honeybee who got separated from his mom when his home was destroyed by invading wasps, and he now desperately wants to find her back. It''s the beginning of an adventure that will make him meet all kinds of friendly insects who try to help him out, but unfortunately for most of them, they will not survive the end of the episode... 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maze☆Bakunetsu Jikuu (TV)', 'TV', 25, 'Completed', '1997-04-03', '1997-09-25', '7', 'Maze wakes up in her house, everything is a wreck and she has amnesia. Before she can gather what has happened the girl Mill storms into her house thanking her for having saved her life. She tells Maze that her house suddenly fell down from the sky and crushed Mills pursuers under it. However before long they are both on the run from further pursuers who want their hands on princess Mill. They are only saved when Maze discovers that she has phantom light magical powers and can summon Mills family heirloom mecha. However her performance with the mecha is weak; that is until the sun goes down and she is turned in to a lecherous man. Soon other travellers join them as Maze tries to protect Mill and figure out what she is doing in this fantasy world. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Recorder to Randoseru Mi☆', 'TV', 12, 'Completed', '2013-07-08', '2013-09-23', '7', 'Third season of Recorder to Randoseru.', 785, 'https://cdn.myanimelist.net/images/anime/6/50651.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Princess Tutu Recaps', 'Special', 3, 'Completed', '2002-12-27', '2003-05-16', '7', '', 357, 'https://cdn.myanimelist.net/images/anime/4/26516.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dallyeola Hani', 'TV', 13, 'Completed', '1988-08-14', '1988-11-20', '7', 'Hany is a small tomboy and slightly troublesome teenager who lives life a bit carelessly on her own since her Father lives abroad due to work in the Middle East and her Mother died when she was very small. The only thing Hany is very good at is running~ fast! Hong Du-kke is a new track and field coach of her school and takes notice in her talent and gets her to train with him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ray The Animation', 'TV', 13, 'Completed', '2006-04-06', '2006-06-29', '7', 'If you have enough money, you can buy anything. So why wait for an organ you need to become available? Raised to be harvested for parts, Ray had already lost her eyes when renegade surgeon Black Jack rescued her. Now, ten years later, she has grown up to be a surgeon herself. And thanks to the unique artificial eyes she received as replacements, she has a reputation for performing incredible medical operations that no one else could even attempt. But unknown to any but a select few, her surgical endeavors are only part of a greater mission: to discover what happened to the other children she was raised with, and to find the men who stole the eyes she was born with and to bring them to justice. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bastard!! Ankoku no Hakaishin (ONA)', 'ONA', 13, 'Completed', '2022-06-30', NULL, '7', 'Fifteen years ago, Dark Schneider, a ruthless magician of immeasurable power, sought to conquer the world with an army led by his generals, the Four Divine Kings. However, he was defeated and sealed in the body of a newborn boy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Holmes: Aoi Ruby no Maki / Kaitei no Zaihou no Maki', 'Movie', 1, 'Completed', '1984-03-11', NULL, '7', 'The famous blue ruby is stolen in such an elaborate way, that only one villain can be suspected - Professor Moriarty. It is up to Sherlock Holmes to return it and, in the process, to turn a young pick-pocket on the right path. In the second part, Moriarty sets his sights even higher, stealing a top-secret submarine from the Navy. What does he need it for? Holmes is once again on the trail.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon Movie 23: Koko', 'Movie', 1, 'Completed', '2020-12-25', NULL, '7', 'Deep within the Forest of Okoya, the Mythical Pokémon Zarude live in a troop and maintain a strict rule that forbids outsiders from entering their territory. Elsewhere in the jungle lives Koko, a human boy raised by a lone Zarude who left the troop. Koko has grown up never doubting that he is a Zarude. But one day, a chance meeting with Satoshi and Pikachu leaves Koko with his first human friend. Is he truly a Pokémon? Or is he, in fact, a human? When danger threatens the jungle, the bonds between Pokémon and human—and the love between parent and child—will be put to the test.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Owari no Seraph: The Beginning of the End', 'Special', 1, 'Completed', '2015-10-03', NULL, '7', 'Recap of 1st Season Aired Before Nagoya Kessen-hen.', 1105, 'https://cdn.myanimelist.net/images/anime/13/76490.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nijiiro Days', 'TV', 24, 'Completed', '2016-01-10', '2016-06-26', '7', 'Nijiiro Days follows the colorful lives and romantic relationships of four high school boys—Natsuki Hashiba, a dreamer with delusions of love; Tomoya Matsunaga, a narcissistic playboy who has multiple girlfriends; Keiichi Katakura, a kinky sadist who always carries a whip; and Tsuyoshi Naoe, an otaku who has a cosplaying girlfriend.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hiyokoi', 'Special', 1, 'Completed', '2010-07-30', NULL, '7', 'After recovering from an accident, shy and small 15-year-old Hiyori Nishiyama is finally able to attend school again after a year. While trying to introduce herself in front of her class, she is interrupted by the tall and outgoing Yuushin Hirose. To make matters worse, their stark difference in height and personality starts to attract unwanted attention to Hiyori.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Popee the Performer', 'TV', 39, 'Completed', '2000-01-03', '2001-12-28', '7', 'Somewhere in the desert lies the Wolf Zirkus: a strange circus where Popee, a clown in a pink rabbit jumpsuit, shares the stage with Kedamono, a purple creature who wears a mask. Together, they juggle the whims of performing, practicing their acts, and poking fun at each other. In a world where anything seems possible, there is no telling what will happen next during this eccentric spectacle.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gokushufudou', 'ONA', 5, 'Completed', '2021-04-08', NULL, '7', 'Who would have ever thought that the most feared gangster of his time now spends his days as a modest househusband? Seemingly giving up the way of the yakuza, the legendary "Immortal Dragon" Tatsu, best known for his prolific skirmishes against rival gangs, has abruptly vanished. Unbeknownst to most, however, Tatsu is currently staying at an apartment with his wife, doing his best to live a peaceful life.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Selection Project', 'TV', 13, 'Completed', '2021-10-01', '2021-12-24', '7', 'Due to a weak heart, Suzune Miyama has remained bedridden for most of her childhood. However, despite her illness, she has always dreamed of becoming an idol. Eventually, her opportunity comes in the form of the seventh Selection Project—a brutal series of competitions best known as the starting point of the legendary idol Akari Amasawa.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tales of the Abyss', 'TV', 26, 'Completed', '2008-10-03', '2009-03-27', '7', 'The world of Auldrant is bound by the Score, a series of prophecies from centuries past that dictate the world''s future. It is considered an absolute fate that everyone lives by—even people whose actions lead to bloodshed and tears. Using magical abilities known as the Fonic Arts, a war between the nation of Kimlasca-Lanvaldear and the Malkuth Empire is waged in hopes of bringing the Score''s foreseen utopia to life.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nerima Daikon Brothers', 'TV', 12, 'Completed', '2006-01-10', '2006-03-28', '7', 'In the town of Nerima, the boisterous Hideki and his stoic brother Ichiro run a daikon radish farm along with Mako, their bubbly but vain cousin. The three dream of raising the money needed to build their own concert hall, where their band—Nerima Daikon Brothers—would perform and hopefully rise to stardom. But their farm and Ichiro''s host club job aren''t raising money fast enough for their liking, leading them to resort to get-rich-quick schemes.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sweat Punch', 'OVA', 5, 'Completed', '2002-03-02', '2006-07-01', '7', 'Sweat Punch is a series of five Studio 4°C shorts collected as a direct-to-DVD package film entitled Deep Imagination.', 849, 'https://cdn.myanimelist.net/images/anime/5/10292.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mary to Majo no Hana', 'Movie', 1, 'Completed', '2017-07-08', NULL, '7', 'Mary Smith is a clumsy girl with wild red hair who can''t seem to do anything right. After moving in with her Great Aunt Charlotte, Mary finds herself lonely and bored, until one day she spies a cat which seems to keep changing color every time she sees it. Curiosity gets the better of her and she follows it into nearby woods. Deep in the forest, the cat takes her to a clearing with dead trees and brown grass, where the only sign of life is a cluster of mysterious blue flowers that Mary has never seen before. The gardener of the estate later tells her that the rare species is called "Fly-by-Night," and is said to be sought by witches for its incredible magical power.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hige wo Soru. Soshite Joshikousei wo Hirou.', 'TV', 13, 'Completed', '2021-04-05', '2021-06-28', '7', 'When regular salaryman Yoshida wakes up one Sunday morning after a long night at the bar, the last thing he expects to see is that his tiny apartment has a new resident—an unfamiliar high school girl.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Moonlight Mile 2nd Season: Touch Down', 'TV', 14, 'Completed', '2007-09-13', '2007-12-13', '7', 'The second season of Moonlight Mile.', 903, 'https://cdn.myanimelist.net/images/anime/9/4265.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ashita no Joe 2 (Movie)', 'Movie', 1, 'Completed', '1981-07-04', NULL, '7', 'It has been six months since the tragic accident in Joe and Rikiishi''s fight. Joe believes he has overcomed Rikiishi''s death and decides to make a comeback. Joe does make a successful comeback by scoring 5 KO''s by body blows. Joe is then given a shot at the national title as a means by the boxing commission to put him down. The champion, Tiger Ozaki makes use of Joe''s habits and ends up making Joe''s corner throw in the towel. Joe is afraid to throw punches at the face because of what happened to Rikiishi. Youko, Joe''s love interest and the owner of the gym where Rikiishi trained at recruits a world ranked boxer from Venezuela, Carlos Rivera, to get Joe back on his feet and pursue his boxing career to the regional and world ranks. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pale Cocoon', 'OVA', 1, 'Completed', '2005-12-10', NULL, '7', 'A future where the continuity of history has broken off, a world of enormous ruins that continues endlessly. Oceans and continents have vanished, existing only within the archives brought up from the remains. Ura works in the Archive Excavation Department, which restores and analyzes the data left behind. One day, he finds a disturbing visual record... 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Strawberry Panic', 'TV', 26, 'Completed', '2006-04-04', '2006-09-26', '7', 'Nagisa Aoi begins her new school life as a transfer student at St. Miator’s Girls Academy, one of three prestigious all-girls institutions atop Astraea Hill. Getting lost on her first day, Nagisa encounters a mysterious student whose elegance and charm is so bewitching, she ends up in the infirmary.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chuunibyou demo Koi ga Shitai! Lite', 'ONA', 6, 'Completed', '2012-09-27', '2012-10-31', '7', 'Short episodes aired on KyoAni''s official YouTube channel.', 494, 'https://cdn.myanimelist.net/images/anime/5/42655.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rec', 'TV', 9, 'Completed', '2006-02-03', '2006-03-31', '7', 'After being stood up for a movie date, marketing employee Fumihiko Matsumaru is about to throw away his tickets when he is stopped by a girl who implores him to let her accompany him instead. Thanks to his upbeat and eccentric companion Aka Onda, an aspiring voice actress, Fumihiko enjoys his evening. While walking home together, they find out that they live in the same neighborhood. Mere hours later, Fumihiko wakes up from a nightmare and hears sirens outside his window. Going outside to check the situation, he sees that Aka''s apartment has burned down, along with all her possessions. Fumihiko invites the distressed Aka to stay at his place, leading to them sleeping together.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Isekai Yakkyoku', 'TV', 12, 'Completed', '2022-07-10', '2022-09-25', '7', 'World-class medical researcher Kanji Yakutani lost his little sister to a tumor years ago due to ineffective treatment. To honor her legacy, he has dedicated his research to developing new medications for such conditions. But as fate would have it, he overworks himself and passes away at the age of 31, only to be given a second chance at life in another world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aura: Maryuuin Kouga Saigo no Tatakai', 'Movie', 1, 'Completed', '2013-04-13', NULL, '7', 'Ichirou Satou is an ordinary high school student who pretended that he was a hero by the name of "Maryuuin Kouga" back in middle school, which led to others frequently bullying him. Now that he has left this embarrassing phase behind, he does his best to avoid standing out and live a peaceful life, although he feels the world has become quite dull. But when he makes his way back to school one night to grab a textbook he left in class, he runs into a strange girl wearing a costume.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Legend of Basara', 'TV', 13, 'Completed', '1998-04-03', '1998-06-26', '7', 'In a small village, twins are born: a boy, Tatara, and a girl, Sarasa. The prophet Nagi declares that Tatara is the chosen one who will free Japan from the tyrannical rule of the King and his four sons. But when the ruthless Red King slays Tatara, Sarasa must take on her brother''s name and responsibilities and embark on a quest to free Japan and deliver vengeance to the Red King. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Btooom!', 'TV', 12, 'Completed', '2012-10-04', '2012-12-20', '7', 'Ryouta Sakamoto is unemployed and lives with his mother, his only real achievement being that he is Japan''s top player of the popular online video game Btooom! However, his peaceful life is about to change when he finds himself stranded on an island in the middle of nowhere, with a small green crystal embedded in his left hand and no memory of how he got there. To his shock, someone has decided to recreate the game he is so fond of in real life, with the stakes being life or death.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Persona 4 the Animation: The Factor of Hope', 'Movie', 1, 'Completed', '2012-06-09', NULL, '7', 'Recap of the entire 25-episode television anime series with new cuts and also the unaired "True End Episode" that was included in the 10th Blu-ray Disc/DVD volume.', 26, 'https://cdn.myanimelist.net/images/anime/3/50415.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Inugami-san to Nekoyama-san: Nekoyama-san to Onsen Ryokou', 'Special', 1, 'Completed', '2014-07-18', NULL, '6', 'Unaired episode bundled with the Blu-ray/DVD Box-Set.', 785, 'https://cdn.myanimelist.net/images/anime/1016/115623.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('NG Knight Ramune & 40 DX: Wakuwaku Jikuu - Honoo no Daisousasen', 'OVA', 3, 'Completed', '1993-06-23', '1993-09-22', '6', 'Lamune and Da Cider head off to Puff-Puff Palace to rescue two beautiful barely clothed maidens, Gold Mountain and Silver Mountain- the Mountain Duo. This of course infuriates Milk and Leska, who with a rather confused and unwilling Cocoa "transform" into "Seinaru Milky", "Seinaru Cacao", and "Seinaru Lemon". The three then head after their would-be boyfriends to extract their revenge.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toradora!: SOS! Kuishinbou Banbanzai', 'Special', 4, 'Completed', '2009-02-03', '2009-08-26', '6', 'Toradora DVD shorts featuring the miniature forms of the Toradora characters talking about, and eating, food.', 436, 'https://cdn.myanimelist.net/images/anime/1242/123508.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Brothers Conflict: Setsubou', 'Special', 1, 'Completed', '2014-02-26', NULL, '6', 'Ema finds a special lamp that her father left for her. Ema and the brothers rub the lamp to find that something peculiar happens in front of them.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ta ga Tame no Alchemist', 'Movie', 1, 'Completed', '2019-06-14', NULL, '6', 'The game is set in the continent of Babel, where the Tower of Babel looms large over seven nations. After the invention of alchemy led to its use as a tool of war that brought humanity to the brink of extinction, the seven nations struck an uneasy peace that led to a prohibition on alchemy for hundreds of years since. In the Continental Year 911, the nation of Lustrice broke the pact by assembling an army bolstered by alchemy, with ambitions of conquest over the continent. Led by Envylia, the six nations allied and struck down the rogue nation, casting alchemy once again to darkness. But 20 years after the war, alchemy once again begins to cause chaos in the land. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Salad Juu Yuushi Tomatoman', 'TV', 50, 'Completed', '1992-04-03', '1993-03-27', '6', 'Tomato is one of the 10 knights of the salad kindom. Young and clumsy, yet always ends up saving the day and is admired by everyone even the pretty princess peach, who he desperately falls in love with.Every episode they embark on a new journey to solve a new mission. This would be easier if only the insect band didn''t get in their way every time. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Norman the Snowman: Kita no Kuni no Aurora', 'Movie', 1, 'Completed', '2013-11-23', NULL, '6', 'As the first snow falls on a town in the northern country, a boy sneaks out of his house to board a northbound train with his friend “Norman the Snowman.” They are off to witness the beautiful wonders of nature that Norman had always talked about.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Muteki Robo Trider G7', 'TV', 50, 'Completed', '1980-02-02', '1981-01-24', '6', 'Takeo Watta inherits a company upon his father''s death. The company focuses on space travel, and the transformable robot Trider-G7 is their greatest creation. When an evil space organization lead by Lord Zakuron starts attacking Earth, Watta has to use Trider in a more combat-oriented way.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaiketsu Zorori: Mamoru ze! Kyouryuu no Tamago', 'Movie', 1, 'Completed', '2013-12-14', NULL, '6', 'Three main characters — Zorori, Ishishi, and Noshishi — get a letter from their friend (a dinosaur mother) to come see some dinosaur eggs because they are going to hatch soon. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Megami Tensei Devil Children: Light & Dark', 'TV', 52, 'Completed', '2002-10-05', '2003-09-27', '6', 'A series based off of the Shin Megami Tensei Devil Children: Light &amp; Dark games (known as DemiKids in the U.S.).
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Absolute Duo', 'TV', 12, 'Completed', '2015-01-04', '2015-03-22', '6', 'Individuals who can materialize weapons from their soul are called "Blazers," and they attend Kouryou Academy High School in order to harness their abilities. Each student is required to partner with another, in the hopes that one day, the pair can attain the power of Absolute Duo.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Transformers: The☆Headmasters', 'TV', 35, 'Completed', '1987-07-03', '1988-03-28', '6', 'Headmasters starts with Galvatron leading a new batch of Destrons to wage war on Cybertron, the Destron Headmasters. The Cybertrons are rescued by the arrival of the Cybertron Headmasters, led by Fortress (Cerebros, the head of Fortress Maximus). It is revealed that Fortress Maximus left Cybertron millions of years ago in search of energy, and have finally managed to come home. He explains that the Headmasters are from a planet called Master; the human-sized robots who live there built themselves Transformers-sized bodies. They can then transform themselves into the heads of the robots, and have now joined the Cybertron-Destron war.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('SKET Dance: SD Character Flash Anime', 'ONA', 16, 'Completed', '2011-03-07', '2011-10-14', '6', 'The SD Character Flash Anime is a special addition to the anime series'' official website. Each "episode" features a different character, drawn in a super-deformed style, set to a song sung by the character''s seiyuu.', 1009, 'https://cdn.myanimelist.net/images/anime/5/44956.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jinrui wa Suitai Shimashita: Ningen-san no, Yousei-san Memo', 'ONA', 1, 'Completed', '2012-10-28', NULL, '6', 'Recap featuring fairies with new narration by Watashi.', 26, 'https://cdn.myanimelist.net/images/anime/3/45706.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bakuretsu Hunters OVA', 'OVA', 3, 'Completed', '1996-12-21', '1997-04-23', '6', 'The Sorcerer Hunters—brothers Carrot and Marron Glace, sisters Tira and Chocolate Misu, and warrior Gateau Mocha—decide to take a break from their travels, planning to stop by a hot springs resort and visit a local village festival. However, their hopes of a simple vacation are dashed by the appearance of a troublesome sorcerer.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shakotan★Boogie', 'OVA', 4, 'Completed', '1991-02-06', '1992-07-17', '6', 'It''s girls, gangs, and cars in this adaptation of the 1985 manga in Young Magazine, by Lullaby for Wednesday''s Cinderella-creator Michiharu Kusunoki. Local punks steal cars, switch the plates, and sell them, but not without racing them for a while against rival gangs. The anime continues the story where the 1987 live-action movie starring Kazuya Kimura left off.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Miami Guns', 'TV', 13, 'Completed', '2000-02-05', '2000-05-20', '6', 'Spoiled rich girl Yao Sakurakouji decides to join the Miami police force to enjoy car chases, gunfights and wanton destruction. The psychotic and not-too-bright Yao is partnered with Lu Amano, the soft-spoken and sharp-tongued daughter of the police chief. Together the dirty duo clean up the streets of Miami and take on a mysterious crime syndicate known only as ''The Organization''. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yadamon', 'TV', 170, 'Completed', '1992-08-24', '1993-07-16', '6', 'After causing havoc in the Witch Forest, the queen, Yadamon''s mother, banishes her to human world.  She does this not only to teach Yadamon a lesson, but also because she has a secret passion for human magazines and books.  While at the human world, the queen keeps a close watch at Yadamon which becomes a problem cause she falls asleep almost anywhere.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Osomatsu-san: Hipipo-Zoku to Kagayaku Kajitsu', 'Movie', 1, 'Completed', '2022-07-08', NULL, '6', 'First of two new anime installments commemorating the anime''s sixth anniversary.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kageyama Tamio no Double Fantasy', 'Special', 1, 'Completed', '1994-01-02', NULL, '6', 'A 2-part TV special. The first part is a comedic bickering couple taking a sketchy plane for vacation. The second part is a horror a camera crew encounter while staying at the Hotel Southpacific after landing.', 802, 'https://cdn.myanimelist.net/images/anime/1523/106150.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kosuke-sama Rikimaru-sama: Konpeitou no Ryuu', 'OVA', 1, 'Completed', '1988-09-23', NULL, '6', 'Kosukesama Rikimarusama: Konpeito no Ryu was a 45 minute long anime TV special produced by J.C. Staff and broadcast on Japanese television in 1988. Similar to Dragon Ball, it was a martial arts adventure story featuring villains that could have stepped out of the Red Ribbon Army, typical Toriyama mecha, and a clone of Son Gohan''s Haiya Dragon.
(Source: animenation.net)', 436, 'https://cdn.myanimelist.net/images/anime/8/5076.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuuki Yuuna wa Yuusha de Aru Churutto!', 'TV', 12, 'Completed', '2021-04-10', '2021-06-26', '6', 'Set in year 300 of the Era of the Gods, heroes and shrine maidens were summoned after a crisis befell on the sacred tree. The Sanshu Middle School Hero Club was transformed into a bountiful household with 27 of them gathered together. Headed by someone who has a strong sense of companionship, Fu Inubozaki, she is determined to make it an Udon Hero Club!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Qin Shi Mingyue: Luosheng Tangxia', 'ONA', 1, 'Completed', '2014-08-13', NULL, '6', 'A single episode special that was released on a web-tour game to coincide with the movie release. This special tells of a young Taoist who joins the Yin-Yang School to find his sister.', 827, 'https://cdn.myanimelist.net/images/anime/10/71825.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuusha ni Narenakatta Ore wa Shibushibu Shuushoku wo Ketsui Shimashita. Specials', 'Special', 5, 'Completed', '2013-12-27', '2014-04-25', '6', 'Specials included in the Blu-ray/DVD volumes. Please refer to More Info section for details.', 1153, 'https://cdn.myanimelist.net/images/anime/4/69041.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gegege no Kitarou: Youkai Daisensou', 'Movie', 1, 'Completed', '1986-03-15', NULL, '6', 'Movie based on the 1985 TV anime with an original plot.', 1030, 'https://cdn.myanimelist.net/images/anime/5/27354.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Assemble Insert', 'OVA', 2, 'Completed', '1989-12-21', '1990-02-25', '6', 'A criminal group known as Demon Seed terrorizes Tokyo with its vast armies of mecha. The local police is afraid to confront them, but one person stands in their way: Maron Namikaze, a 13-year-old idol singer with a catchy voice and unbelievable superhuman strength.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Umi no Triton (1979)', 'Movie', 2, 'Completed', '1979-04-04', '1984-05-21', '6', 'A recap of the TV series. While two parts were made, only the first one was shown in theaters during the Uchuu Senkan Yamato Festival. The second part was released half a decade later direct to home-video by Nippon Columbia. Later releases on DVD in 1999 and 2002 put both halves of the recap together for sale.', 73, 'https://cdn.myanimelist.net/images/anime/1736/153090.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kirameki☆Project', 'OVA', 5, 'Completed', '2005-06-24', '2006-02-24', '6', 'In a world where giant rude robots are common and used to fight wars appears a giant Handcrafted robot that defeats the major armies of the world. Meanwhile in a kingdom where three sisters reign in peace and harmony there is a secret that they keep from the rest of the world until they must use a Doll-looking robot to protect their nation, even when her creator refuses to put her friend in danger.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kokoroya', 'OVA', 1, 'Completed', '2014-01-01', NULL, '6', 'An educational film about empathy in Japan. In the movie''s example, uses a sci-fi twist to show how the hearts of others to the main character in certain situations.', 1030, 'https://cdn.myanimelist.net/images/anime/2/65991.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Grick no Bouken', 'Movie', 1, 'Completed', '1981-07-21', NULL, '6', 'Grick is a young chipmunk living in the city with his sister. But after hearing from a carrier pigeon of the Chipmunk homeland, the Great Forest, he leaves home alone. Grick meets both friends and enemies along his adventure to find the place where he truly belongs.', 917, 'https://cdn.myanimelist.net/images/anime/9/84017.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shikabane Hime: Puchitto', 'Special', 1, 'Completed', '2009-08-05', NULL, '6', 'Chibi comedy released as a DVD extra.', 321, 'https://cdn.myanimelist.net/images/anime/10/16690.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ougon Senshi Gold Lightan', 'TV', 52, 'Completed', '1981-03-01', '1982-02-18', '6', 'When a young boy called Hiro finds what appears to be a broken lighter in an empty field, it changes his life forever. This lighter is actually the Gold Lightan, a robot that fell to Earth from the Robot Dimension. When called upon to defend the Earth from Ivalda the Great''s evil robots, Gold Lightan transforms into a giant super robot, known as the Golden Warrior. Gold Lightan joins forces with Hiro''s and his gang, the One Pack Rangers to protect the Earth from the evil schemes of Ivalda the Great and his armored forces.', 1009, 'https://cdn.myanimelist.net/images/anime/10/60089.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tattoon Master', 'OVA', 2, 'Completed', '1996-04-26', '1996-08-23', '6', 'When Hibio''s adventurer mother sets off to research a mysterious tribe, she hits a wall. Fortunately for her, the beautiful young Nima sees a family portrait and decides that she wants her son for her husband and she gets a chance to further her research. She agrees to the arrangement. Of course, she doesn''t consult him about his future bride. When Nima shows up in Tokyo to be with her new husband, hilarity and chaos ensues as Hibio and his modern Tokyo background meets Nima''s magical heritage. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ai Shoujo Pollyanna Story Specials', 'Special', 2, 'Completed', '2001-04-01', NULL, '6', 'A summary of Ai Shoujo Pollyanna Monogatari full series aired as TV Specials in 2001.', 607, 'https://cdn.myanimelist.net/images/anime/1963/140232.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koguma no Misha', 'TV', 26, 'Completed', '1979-10-06', '1980-04-05', '6', 'This hilarious and lovable story takes place in the strange animal town of Himadabeya.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Utsunomiko: Heaven Chapter', 'OVA', 13, 'Completed', '1990-10-24', '1992-02-19', '6', 'Delving into the humans'' spiritual journey to the Celestial Realm of Buddha, UTSU NO MIKO follows five friends on their quest to bring peace to a corrupt and chaotic Earth.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Last Orders', 'Special', 1, 'Completed', '1997-10-01', NULL, '6', 'The 60-second film features six fierce samurai who rush through a post-futuristic megalopolis using the most unpredictable means of transport (including a kite!) as to make it on time for the last order at their favorite pub.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Dokonjou Gaeru', 'TV', 30, 'Completed', '1981-09-07', '1982-03-29', '6', 'Continuation of Dokonjougaeru series.', 1036, 'https://cdn.myanimelist.net/images/anime/8/56689.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nanami-chan 3rd Series', 'TV', 16, 'Completed', '2006-08-04', '2006-11-17', '6', 'Michi and her family have just moved into the Happiness House, a huge tree with all sorts of little buildings and houses built on and inside of it. Upon exploring what is to be her new bedroom, Michi finds an odd nut-like object. Before long, a strange creature, Nanami-chan, hatches out of it. The two become fast friends. Together, Michi and Nanami-chan learn all kind of new things, and everyday they meet more eccentric residents of the Happiness House.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Personal Computer Travel Tanteidan', 'TV', 26, 'Completed', '1983-04-04', '1983-09-26', '6', 'The book fell onto a computer keyboard, giving anybody the ability to see into the past from Sho''s home via the monitor. Ruffles, Chris'' dog, managed to get lost in time, prompting Zenmaijikake and Sho''s cousin Hisashi to search for her. Sho and Azusa kept watch and control of the computer from the present. The older children also had a hard time trying to keep what happened a secret from Sho''s parents.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Himitsukessha Taka no Tsume Countdown', 'TV', 11, 'Completed', '2009-10-07', '2009-12-23', '6', 'The second season of Eagle Talon.', 214, 'https://cdn.myanimelist.net/images/anime/9/82798.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyoufu Densetsu Kaiki! Frankenstein', 'Special', 1, 'Completed', '1981-07-27', NULL, '6', 'Airing on TV Asahi in 1981, with a running time of 111 minutes, Frankenstein is a reasonably standard retelling of the classic book by Mary Shelley. In a foreboding castle scientist Dr. Victor Frankenstein performs a hideous experiment which he hopes will bring the dead back to life. With the help of his assistant he is successful in reanimating a man recreated from parts gathered from corpses but the creature is unpredictable and horrifying. The doctor flees back to his home in Switzerland leaving his assistant in charge of destroying the monster. But Dr. Frankenstein soon finds that he cannot hide from his shameful secret forever as mysterious murders are committed around him forcing him to question if his creation really is dead and gone...', 1030, 'https://cdn.myanimelist.net/images/anime/10/16281.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tonari no 801-chan R', 'OVA', 1, 'Completed', '2009-09-10', NULL, '6', 'A 90 second anime adaptation of the original Tonari no 801-chan manga about a 28 year-old salaryman otaku who has a 22 year-old co-worker girlfriend who is a fujoshi, or female otaku obsessed with yaoi.', 14, 'https://cdn.myanimelist.net/images/anime/13/17047.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kougyou Aika Volley Boys', 'OVA', 2, 'Completed', '1997-03-14', '1997-04-25', '6', 'In a mix of Field of Dreams and Ping Pong Club, sex-starved teenage boys at Kudo High School sign up for the girls'' volleyball team hoping that if they build it, the girls will come, to a year that has no girls in it at all.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('La Rose de Versailles', 'Special', 1, 'Completed', '2007-01-01', NULL, '6', 'Toei Animation announced the new movie based on the classic anime and manga. This project is most likely canceled and a trailer is all that remains, which is what this entry encompasses.', 1030, 'https://cdn.myanimelist.net/images/anime/6/64921.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahjong Hishouden: Naki no Ryuu', 'OVA', 3, 'Completed', '1988-05-25', '1990-07-27', '6', 'The protagonist, Ryuu or Crying Dragon, is a mysterious man who often plays games with the gang members. He only wins by "ron," a move in which one needs to wait for the opponent''s tile to complete the win.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Money Wars: Nerawareta Waterfront Keikaku', 'OVA', 1, 'Completed', '1991-09-27', NULL, '6', 'A new waterfront area is being built in Tokyo, and Chinese mafia man Lin Haifeng wants to gain control of it by owning the majority stock of the company in charge of construction. Lin''s plan is to use the waterfront as a gateway for the Chinese mafia in an attempt to turn Tokyo into a "New Hong Kong". After his friend Kurihara commits suicide after unknowingly helping Lin get a hold of some stocks, his friend Tsuyoshi Aiba aims to avenge his friend by keeping Lin from taking over the waterfront.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Marginal Prince: Gekkeiju no Ouji-tachi - Tokyo Merry-Go-Round', 'Special', 1, 'Completed', '2007-07-19', NULL, '6', 'Keita and the other Marginal Prince are away from St. Alphonso Academy and meet each other in the city, where they meet Keita''s sister.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyoto Animation: Hassou-hen', 'Special', 1, 'Completed', '2012-04-01', NULL, '6', 'While waiting in a park for someone to arrive, a certain person''s mind begins to wander: in daydreams and visions, they watch parts of their surroundings transform into the one they await as they descend into these fantasies.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Magma Taishi', 'OVA', 13, 'Completed', '1993-02-21', '1993-06-21', '6', 'The alien invader Goa plots to conquer the Earth. He first warns the Murakami family (father Atsushi, mother Tomoko, and son Mamoru) of their invasion, and demonstrates his powers by transporting them to a prehistoric jungle and destroying a Giant Dinosaur before their very eyes. But they will not agree to surrender to Goa, so hope comes in the form of Magma, an armored, golden giant with long hair and antennae. He and his human-sized wife Mol, both created by the wizard Earth are sent to defend our world against Goa. They befriend Atsushi and Mamoru, the latter has Magma emotionally touched, as he wanted to have a child with his wife Mol, so Earth creates a duplicate of Mamoru, named Gam Earth gives Mamoru a whistle, with which he can call Gam Mol and Magma in times of crisis. So when Goa unleashes his various daikaiju, chances are, Magma, Mol, and Gam will fly to the rescue.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nessa no Haou Gandalla', 'TV', 26, 'Completed', '1998-04-11', '1998-10-17', '6', 'A dispute between young band members and an unfortunate choice of melody inadverdently draws them all into the demonic horror known as  the desert-god Gandalla.', 92, 'https://cdn.myanimelist.net/images/anime/5/58541.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Asako Get You!!', 'OVA', 2, 'Completed', '2013-01-26', NULL, '6', 'Unaired anime bundled with the limited edition of the 9th volume of the manga.', 761, 'https://cdn.myanimelist.net/images/anime/5/53435.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tantei wa Mou, Shindeiru. Mini Anime', 'ONA', 5, 'Completed', '2021-05-21', '2021-05-25', '6', 'Mini anime series released on YouTube serving as an advertisement for Tantei wa Mou, Shindeiru. light novel.', 255, 'https://cdn.myanimelist.net/images/anime/1467/116797.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kekkou Kamen', 'OVA', 4, 'Completed', '1991-08-01', '1992-03-01', '6', 'At the academy Miami Takashi attends, higher education has sunk to the lowest levels of depravity, with armed hall monitors, teachers who wear masks to hide their identities and special detention sessions in a torture chamber beneath the gym! It''s a curriculum designed to chew up sweet young things, and poor Miami''s been voted "Least Likely to Survive" in her class! Is there no hope? Can no one save her? Enter Kekko Kamen, the most outrageous superheroine ever! Clad in a red mask, red boots and nothing else, she is the supreme protector of innocents like Miami. Armed with her trusty nunchaku and a body that just won''t quit, she''ll make chopped pork out of the swine who run this school from hell! But who is she really? The only one who knows for sure is creator Go Nagai and he''s not giving anything away... except lots of free peeks at Kekko Kamen''s magnificent physique!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Haru wa Kuru', 'Special', 1, 'Completed', '2012-01-27', NULL, '6', 'A short promotional film for the Johnnie Walker whiskey brand, animated by STUDIO 4°C.', 849, 'https://cdn.myanimelist.net/images/anime/5/37107.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koi-ken!: Watashitachi Anime ni Nacchatta!', 'ONA', 12, 'Completed', '2012-03-01', '2012-05-24', '6', 'Koi-Ken Love Research club member Kaede Wakamiya comments that being an idol must be extremely easy—a comment that irritates idol Nagisa Toyama. At the suggestion of her manager, all female members of the KoiKen club are invited to become an idol unit with Nagisa. Kaede then realizes that maybe being an idol isn''t so easy after all...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('JU Chuuko Jidousha Hanbaishi x Peeping Life', 'Special', 2, 'Completed', '2013-09-30', '2014-11-10', '5', 'Collaboration of Peeping Life and JU.', 184, 'https://cdn.myanimelist.net/images/anime/3/71525.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hairpin Double', 'Special', 1, 'Completed', '2022-02-04', NULL, '5', '', 282, 'https://cdn.myanimelist.net/images/anime/1330/114903.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Barom One', 'TV', 13, 'Completed', '2002-12-07', '2003-03-22', '5', 'Takeshi Kido and Kentaro Shiratori are a pair of friends who have been together for almost their entire life. One night, a strange being comes out from the lake and starts attacking them. When Takeshi and Kentaro are almost eliminated, a strange being named Kopu calls them and tells them that they are the chosen ones to inherit the power to protect the world from an evil being named Goumon. Now, they join their hands to transform into Barom One, a being with superior skills, who will fight to protect the city.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hawk no Onayami Soudanshitsu Special', 'Special', 1, 'Completed', '2020-09-25', NULL, '5', 'A special episode of Hawk no Onayami Soudanshitsu included in the second Blu-Ray of Nanatsu no Taizai: Kamigami no Gekirin.', 879, 'https://cdn.myanimelist.net/images/anime/1259/134572.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hentatsu (TV)', 'TV', 12, 'Completed', '2020-01-04', '2020-03-21', '5', 'Hentatsu follows two girls exploring a seemingly abandoned version of Nakano Broadway, a Tokyo shopping mall known for Mandarake and other shops catering to fans of anime and other forms of pop culture.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kujakuou: Sengoku Tensei', 'ONA', 1, 'Completed', '2014-10-21', NULL, '5', 'A promotional anime for the 2nd volume release of Makoto Ogino''s Kujakuou: Sengoku Tensei manga.', 329, 'https://cdn.myanimelist.net/images/anime/9/68111.jpg');
