INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hawaiian Conu', 'TV', 13, 'Completed', '2018-07-07', '2018-09-29', '5', '', 540, 'https://cdn.myanimelist.net/images/anime/1127/93313.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chokkan x Algorhythm♪ 2nd Season', 'ONA', 17, 'Completed', '2018-10-08', '2019-02-11', '5', 'Second season of Chokkan x Algorhythm♪.', 1092, 'https://cdn.myanimelist.net/images/anime/1441/93210.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chiro-wa Chingu-deul', 'TV', 52, 'Completed', '2007-08-27', NULL, '5', 'An anime aimed at preschoolers starring Chiro, the youngest of 3 chicks. The short stories focus on fun learning and adventure with riddles and games.', 409, 'https://cdn.myanimelist.net/images/anime/1163/93285.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shaman King: Flowers', 'TV', 13, 'Completed', '2024-01-10', '2024-04-03', '7', 'The story will center on You and Anna''s son, Hana.', 146, 'https://cdn.myanimelist.net/images/anime/1117/139294.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ling Yu 3rd Season', 'ONA', 12, 'Completed', '2016-07-21', '2016-10-06', '7', 'Qin Lie has pulled up twelve spiritual columns, but the war between the Evil Clan and many tribues is imminent. However, at the most critical moment, the appearance of Li Mu in Tianjian Mountain prevented things from going in the worst direction.', 369, 'https://cdn.myanimelist.net/images/anime/2/88950.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nagareboshi Lens', 'OVA', 1, 'Completed', '2012-03-18', NULL, '7', 'Risa Hanakago has always thought that falling in love makes the whole world sparkle. Although she longs to experience this herself, it seems futile without romantic prospects of her own. However, a chance encounter lands her in the sights of Touga Yuugure, a popular boy in her school. Charmed by each other, Risa and Touga quickly become a couple, but it remains unclear whether a relationship between a plain girl and a well-liked boy can last.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hai to Gensou no Grimgar: Furoagari no Kabe ni Kaketa Seishun - One More Centimeter', 'Special', 1, 'Completed', '2016-03-16', NULL, '7', 'Special episode that will expand on the ending of episode 2 where the boys try to spy on the girls bathing.', 14, 'https://cdn.myanimelist.net/images/anime/11/78160.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hakuouki: Otogisoushi', 'TV', 12, 'Completed', '2016-04-05', '2016-06-28', '7', 'Features the characters from the games in chibi form with a completely new story with the theme: "A normal everyday that might have existed."', 214, 'https://cdn.myanimelist.net/images/anime/9/78600.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maken-Ki! OVA', 'OVA', 2, 'Completed', '2012-03-01', '2013-09-25', '7', 'OVA episodes bundled with the 8th and 11th volumes of the manga.', 1117, 'https://cdn.myanimelist.net/images/anime/7/36929.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('12-sai.: Chicchana Mune no Tokimeki 2nd Season', 'TV', 12, 'Completed', '2016-10-03', '2016-12-19', '7', 'The story begins with Hanabi, a sixth-grade girl who is neither an adult nor a child. She deals with issues such as accidentally witnessing her homeroom teacher kissing, and worrying about experiencing physiological changes before her friends. The series depicts a 12-year-old girl''s innocent worries and first love.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gokukoku no Brynhildr: Kara Sawagi', 'Special', 1, 'Completed', '2014-09-24', NULL, '7', 'Unaired episode 11.5 included with the second Blu-ray/DVD volume.', 85, 'https://cdn.myanimelist.net/images/anime/9/68045.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ano Hi no Kanojo-tachi', 'ONA', 8, 'Completed', '2018-03-24', '2018-11-12', '7', 'Web shorts focusing on each of the 22/7 idols in normal everyday life.', 183, 'https://cdn.myanimelist.net/images/anime/1263/93685.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sword Art Online Alternative: Gun Gale Online - Refrain', 'Special', 1, 'Completed', '2018-05-13', NULL, '7', 'Following the conclusion of the first ever Squad Jam, Pitohui is eager to see what she missed, dying to know how everything went down. To satiate her desires, M reviews footage of the competition with her, commentating on the trials that he and LLENN faced together.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Umayon', 'TV', 12, 'Completed', '2020-07-07', '2020-09-22', '7', 'It''s a "pop" and cute everyday anime based on the 4-koma manga featuring the characters from Uma Musume: Pretty Derby.', 1092, 'https://cdn.myanimelist.net/images/anime/1032/111641.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('B-Project: Kodou*Ambitious', 'TV', 12, 'Completed', '2016-07-03', '2016-09-25', '7', 'The anime''s story follows Tsubasa, a new hire in the A&amp;R department of the major recording company Gandala Music. Tsubasa is immediately assigned to oversee the idol unit "B-PROJECT," which is made up of three idol groups: Kitakore, THRIVE, and MooNs. This is Tsubasa''s first job, and she gets involved in various incidents and accidents as she deals with this group of young men who each have their own differing personalities.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Future Card Buddyfight Triple D', 'TV', 51, 'Completed', '2016-04-02', '2017-03-25', '7', 'Third season of Future Card Buddyfight.', 1117, 'https://cdn.myanimelist.net/images/anime/4/78622.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou Sensei Negima!: Introduction Film', 'OVA', 3, 'Completed', '2004-08-25', '2005-03-24', '7', 'Before the beginning of the series, three OVAs were produced for the sole purpose of introducing the characters. The first two were released on DVD bundled with two drama CDs, with the third being sold separately. It is unknown if these will ever be released outside of Japan.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ikkitousen: Dragon Destiny Specials', 'Special', 6, 'Completed', '2007-06-24', '2007-11-24', '7', 'Ikkitousen Dragon Destiny Specials.', 85, 'https://cdn.myanimelist.net/images/anime/1636/138210.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sacred Seven', 'TV', 12, 'Completed', '2011-07-03', '2011-09-16', '7', 'Alma Tandoji lives a lonely life. One day, Ruri Alba, a girl accompanied by her butler and maids, visits him. Knowing the power of Sacred Seven is latent within Alma, she asks him to lend her his powers. However, he refuses and drives her away since he injured many with his unusual strength in the past.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saki Biyori Animation', 'OVA', 1, 'Completed', '2015-07-25', NULL, '7', 'A single episode OVA released with the 14th volume of the Saki manga, consisting of 4-koma gags featuring characters from the first season. The two pros meet up at a family restaurant. The captains of the four teams prepare for a joint training camp. Ikeda keeps her little sisters occupied. The Tsuruga team goes on an unplanned camping trip. Ryuumonbuchi celebrate Koromo''s birthday.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gegege no Kitarou (1985)', 'TV', 108, 'Completed', '1985-10-12', '1988-02-06', '7', 'As civilization advances, people are beginning to lose the consideration and kindliness for Nature. This has incurred the wrath of the ghosts who are becoming increasingly unhappy with the selfishness of the human kind. However, there is a conflict of interests within the ghosts in which one extreme opposes the humans completely while another extreme desires the co-existence of humans and ghosts. Kitaro and his family belongs to the latter category and yearns to seek mutual understanding between the humans and ghosts. Kitaro''s fight for love and hope continues.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kurokami: Intermission', 'Special', 1, 'Completed', '2009-04-03', NULL, '7', 'A recap of the first part of the series.', 974, 'https://cdn.myanimelist.net/images/anime/11/15086.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Spirit of Wonder: China-san Tanpenshuu', 'Special', 3, 'Completed', '2001-01-25', '2004-01-23', '7', 'Three short stories featuring China-san.', 53, 'https://cdn.myanimelist.net/images/anime/1448/116730.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ultraman Final', 'ONA', 12, 'Completed', '2023-05-11', NULL, '7', 'Final Season of Ultraman.', 704, 'https://cdn.myanimelist.net/images/anime/1671/134694.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cang Lan Jue', 'ONA', 12, 'Completed', '2022-07-15', '2022-09-23', '7', 'A donghua based on the novel of the same name written by Jiu Lu Fei Xiang. The story revolves around the relationship between Xiao Lanhua, a low-ranking flower fairy, and the powerful "Moon Supreme" Dongfang Qingcang. After being locked away for thousands of years, Xiao Lanhua mistakenly revives Dongfang Qingcang. The two of them become connected as a result, with the powerful and stoic Moon Supreme forced to experience everything she does, both physical and emotional.', 314, 'https://cdn.myanimelist.net/images/anime/1927/125119.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Phi Brain: Kami no Puzzle - Orpheus Order-hen', 'TV', 25, 'Completed', '2012-04-08', '2012-09-23', '7', 'The puzzles get tougher and even more deadly as Kaito Daimon continues his battle against the power hungry Givers of the POG. And with one team member already switching sides, will Kaito have what it takes to keep solving the deadly puzzle traps put before him and reach the fabled Puzzle of God? More importantly, will he be able to solve the puzzles AND maintain his sanity? 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kakumeiki Valvrave 2nd Season', 'TV', 12, 'Completed', '2013-10-10', '2013-12-27', '7', 'Haruto and his comrades continue to fight against the forces of Dorssia. However, many things remain unanswered in the midst of battle, including the past of L-Elf and his fellow soldier''s past, the destiny of the mysterious girl Liselotte, and the feelings of Haruto, Shouko, and Saki. The relationships and loyalty of each and every member of each army will be tested as the clash of ideals and power reaches its climax.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Senjou no Valkyria 3: Tagatame no Juusou', 'OVA', 2, 'Completed', '2011-04-13', '2011-06-29', '7', 'The Second Europa War is being fought between Gallia and the East Europan Imperial Alliance, and a penal military unit known as the Nameless is on the run from both superpowers. Deemed rebels by Gallia and also a priority target of the Empire, the Nameless struggle to find their place in the raging war. To make matters worse, the company''s tank driver, Gusurg, abandons them to fight for the Empire.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sidonia no Kishi Movie', 'Movie', 1, 'Completed', '2015-03-06', NULL, '7', 'A recap of the first season of Sidonia no Kishi with additional scenes and re-edited sound effects.', 695, 'https://cdn.myanimelist.net/images/anime/6/69369.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sabage-bu! Specials', 'Special', 6, 'Completed', '2014-09-24', '2015-02-20', '7', 'Short specials bundled with the volumes 1 to 6 of the Blu-ray releases of Sabagebu!', 683, 'https://cdn.myanimelist.net/images/anime/3/65183.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Imawa no Kuni no Alice', 'OVA', 3, 'Completed', '2014-10-15', '2015-02-16', '7', 'Ryouhei Arisu is a high school student with no ambitions and just wants to escape from what he feels is a meaningless reality. One night when he is with his two friends Daikichi Karube and Chouta Segawa, they see an abnormally large firework shoot into the sky, an event which signals a permanent change in their lives.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsuki ga Kirei Special', 'Special', 1, 'Completed', '2017-09-27', NULL, '7', 'A series of unaired comedic shorts released with Blu-ray and DVD boxes of Tsuki ga Kirei.', 1162, 'https://cdn.myanimelist.net/images/anime/6/88307.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Servamp Movie: Alice in the Garden', 'Movie', 1, 'Completed', '2018-04-07', NULL, '7', 'The Servamps and their pact-bound "Eves" are finally getting back to their normal lives as they recover from their injuries from the previous battles. However, when it starts snowing in the middle of summer, one of the Eves, Mahiru Shirota, suspects vampiric interference. Concerned by the strange phenomenon, he sets out to gather the group once more to try and solve the mystery; however, they suddenly lose contact with Misono Arisuin, the Eve of the Servamp of Lust.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kobayashi-san Chi no OO Dragon', 'Special', 7, 'Completed', '2017-03-15', '2017-09-20', '7', 'Specials included with the BD/DVD release of Kobayashi-san Chi no Maid Dragon.', 494, 'https://cdn.myanimelist.net/images/anime/1013/121928.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Watashi ni Tenshi ga Maiorita!', 'TV', 12, 'Completed', '2019-01-08', '2019-03-26', '7', 'College student Miyako Hoshino is quite shy around other people. She mostly spends her time in her room making cosplay outfits. When her fifth-grade sister Hinata brings her classmate Hana Shirosaki home, Miyako instantly becomes captivated with Hana''s cuteness. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Soukyuu no Fafner: Dead Aggressor', 'TV', 25, 'Completed', '2004-07-05', '2004-12-27', '7', 'Tatsumiyajima is the central island in the middle of a small cluster of islands, in a sleepy backwater of the Japanese isles. Not much happens there, and the island''s young people go to school knowing that their lives are likely to remain peaceful and undisturbed. Or so they have been taught... but the truth is different. The fate of mankind is on the line, and Tatsumiyajima is the last line of defense against a hostile and incomprehensible enemy. At the center of it all, fighting for Humanity''s continued existence, is the giant robot Fafner, the dragon that guards this final treasure of mankind.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Natsu no Arashi! Akinaichuu', 'TV', 13, 'Completed', '2009-10-05', '2009-12-28', '7', 'The summer of a man''s boyhood memories continue. Still on the cusp between childhood and being a man, he has linked with the ghost of a young woman from the World War 2 era. She, and the ghosts of other young ladies from that time, continue adventures alongside their linked partners, learning more about each other and travelling through time via their supernatural connection. While he struggles to see his crush on her come to fruition, meanwhile his friend—a girl his age, pretending to be a boy—seeks his attention as well.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boku no Hero Academia: Hero Note', 'Special', 1, 'Completed', '2017-03-25', NULL, '7', 'Recap of Boku no Hero Academia that aired a week before the second season.', 138, 'https://cdn.myanimelist.net/images/anime/1089/121748.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rokka no Yuusha', 'TV', 12, 'Completed', '2015-07-05', '2015-09-20', '7', 'An ancient legend states that with the revival of the Demon God, six heroes—the Braves of the Six Flowers—will be chosen by the Goddess of Fate, granting them power to rise up against the fiends attempting to turn the world into a living hell. Adlet Mayer, self-proclaimed "Strongest Man in the World," has arrived at the continent of Piena in hopes of becoming a Brave. Although it doesn''t go as smoothly as he had planned, Adlet is ultimately chosen as one of the six heroes shortly after being greeted by Nashetania Loei Piena Augustra, crown princess and fellow Brave.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('RideBack', 'TV', 12, 'Completed', '2009-01-12', '2009-03-30', '7', 'In the future, an organization called the GGP has taken control of the world. Rin Ogata was a promising up-and-coming ballet dancer, but suffered a serious injury while dancing and decided to quit. Years later in college, she comes across a club building and soon finds herself intrigued by a transforming motorcycle-like robotic vehicle called a "Rideback". She soon finds that her unique ballet skills with balance and finesse make her a born natural on a Rideback. However, those same skills also get her into serious trouble with the government.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jashin-chan Dropkick'': Chitose-hen', 'Special', 1, 'Completed', '2020-04-30', NULL, '7', 'After the devils see a television advertisement for Chitose, Hokkaido, Yurine Hanazono suggests that they all take a trip there. Everyone readily agrees to the excursion except for Jashin-chan; however, she is forced to tag along under the threat of Yurine''s chainsaw.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The iDOLM@STER Cinderella Girls: Anytime, Anywhere with Cinderella.', 'Special', 1, 'Completed', '2016-02-25', NULL, '7', 'The unaired 26th episode bundled with the ninth Blu-ray and DVD volume of The iDOLM@STER Cinderella Girls.', 14, 'https://cdn.myanimelist.net/images/anime/1335/150202.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Utawarerumono: Itsuwari no Kamen', 'TV', 25, 'Completed', '2015-10-04', '2016-03-27', '7', 'Waking up cold and alone in the woods, a nameless man is surrounded by unfamiliar scenes. Without any memories, he is utterly lost until he stumbles upon Kuon—a young girl with animal ears and a tail. She saves him, leading him back to her town while protecting them both from "boro-gigiri"—giant centipede-like creatures—and a mysterious red slime. After they arrive, she names him Haku after a prominent historical figure from the area. He quickly realizes he is one of a kind—the only one without animal ears and a tail. The two journey to the capital of Yamato, the country in which Kuon lives, meeting more people and making new friends, all the while unknowingly delving deeper into the politics and inner conflicts of Yamato...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ling Jian Zun 4th Season', 'ONA', 560, 'Completed', '2020-09-08', '2025-11-18', '7', 'Fourth season of Ling Jian Zun.', 978, 'https://cdn.myanimelist.net/images/anime/1972/108157.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Edens Zero', 'TV', 25, 'Completed', '2021-04-11', '2021-10-03', '7', 'All his life, Shiki has been surrounded by machines. At Granbell Kingdom, a long-abandoned amusement park, he is the only one of his kind around. That is, until Rebecca Bluegarden and her feline companion Happy arrive, unaware that they are Granbell''s first visitors in one hundred years. Their goal is to make fun videos for their B-Cube channel, but what they find instead is a friend in the socially awkward Shiki.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('KimiKiss Pure Rouge', 'TV', 24, 'Completed', '2007-10-07', '2008-03-23', '7', 'Kouichi Sanada and Kazuki Aihara''s childhood friend Mao Mizusawa has returned after living in France for a couple of years. Kouichi is surprised to learn that, since her parents are remaining overseas for the time being, his mother has agreed to let Mao stay with them. The three friends help each other deal with the ups and downs of high school romance.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lupin the IIIrd: Mine Fujiko no Uso', 'Movie', 1, 'Completed', '2019-05-31', NULL, '7', 'Fujiko Mine is on the run with Gene, a boy who knows the location of a stash of $500 million dollars that his deceased father embezzled from the company Godfrey Mining. The boy is targeted by Bincam, an assassin hired by Godfrey Mining with a mysterious ability that allows him to bend a person’s will.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jinyi Shen Jiang', 'ONA', 13, 'Completed', '2023-09-11', '2023-11-27', '6', '', 1130, 'https://cdn.myanimelist.net/images/anime/1204/138328.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam: Fukushuu no Requiem', 'ONA', 6, 'Completed', '2024-10-17', NULL, '6', 'In the year Universal Century 0079, a state of war began when the Principality of Zeon declared its independence from the Earth Federation government. In the war''s opening stages, the Zeon forces maintained an advantage thanks to the effectiveness of their new weapon, the mobile suit. However, they lacked the fighting strength to fully conquer Earth, and the war became a stalemate.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gamera: Rebirth', 'ONA', 6, 'Completed', '2023-09-07', NULL, '6', 'The series will focus on Gamera facing off against five different Kaiju.', 255, 'https://cdn.myanimelist.net/images/anime/1024/134654.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam: Suisei no Majo Recap', 'Special', 1, 'Completed', '2022-11-13', NULL, '6', 'Recap of the first six episodes of Kidou Senshi Gundam: Suisei no Majo.', 974, 'https://cdn.myanimelist.net/images/anime/1221/131087.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Isekai wa Smartphone to Tomo ni. 2', 'TV', 12, 'Completed', '2023-04-03', '2023-06-19', '6', 'Touya Mochizuki grows accustomed to his new life in another world. Armed with his trusty smartphone, the teenager accepts small quests at his leisure while spending time with his new fiancées: Yumina Urnea Belfast, Yae Kokonoe, and twin sisters Linse and Elze Shileska. But even in a relaxing environment, Touya is only beginning to understand the responsibilities that come with these engagements.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Line Offline: Salaryman', 'TV', 114, 'Completed', '2013-01-08', '2013-10-01', '6', 'The anime shorts are set in the fictional Line Corporation with a motley crew of idiosyncratic workers. There is the narcissistic section head and president''s son James, the subsection head Moon (who is always gone somewhere but somehow gets his work done), the quiet but kindhearted subsection head Brown, and the subordinate Connie who is in an endless loop of yo-yo diets and weight gains.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Off', 'OVA', 4, 'Completed', '2012-08-05', '2012-10-07', '6', 'High school student Haruno Shiozaki and her friends live in a remote mountain town where the only thing worth looking forward to is turning 16 years old—the legal age required to obtain a motorcycle license. However, when Haruno''s family hires Cynthia B. Rogers to work at their inn during the peak season, excitement buzzes around the new visitor. As Haruno''s friends are charmed by the foreigner''s loud and brassy attitude, Haruno wonders whether people from a town as small as theirs are able to have dreams too.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Morita-san wa Mukuchi. Specials', 'Special', 2, 'Completed', '2012-01-27', NULL, '6', 'Unaired episodes of the "Morita-san wa Mukuchi" TV series bundled with the 5th manga volume.', 785, 'https://cdn.myanimelist.net/images/anime/3/36275.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('12-sai.: Chicchana Mune no Tokimeki', 'TV', 12, 'Completed', '2016-04-04', '2016-06-20', '6', 'Reaching a period of life where they are neither a child nor an adult, 12-year-old Hanabi Ayase and Aoi Yui meet with life-changing events. Due to the mischievous demeanor of her male classmates, Ayase does not think highly of the opposite sex. However, her perspective begins to change after she is paired with the kind-hearted Takao Yuuto for a class assignment and unexpectedly shared their first kisses with each other on the school rooftop.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gifuu Doudou!!: Kanetsugu to Keiji', 'TV', 25, 'Completed', '2013-07-03', '2013-12-18', '6', 'The Sengoku era gave birth to many historical legends. One of them is Naoe Kanetsugu, the brilliant military general of the Uesugi family. Together with Maeda Keiji, a legendary warrior on the battlefield, who become lifelong friends with each other, they carve out a piece of history in the most dangerous and volatile time in Japan''s history. The two men recall their beginnings and the journey they took to get to the accomplished position they now sit at.', 879, 'https://cdn.myanimelist.net/images/anime/5/51427.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hataraku Oniisan!', 'TV', 12, 'Completed', '2018-01-05', '2018-03-23', '6', 'The energetic Tapio Chatarozawa and the cool-headed Kuehiko Roshihara are two young cats trying out various part-time jobs. From delivering packages to washing windows on skyscrapers, the pair explore the opportunities that await them out on the recruiting field. As they struggle to learn the ropes, the duo endures the antics of their colorful customers and supervisors while bonding as working buddies. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Itou Junji: Collection - Tomie', 'Special', 2, 'Completed', '2018-04-27', '2018-05-25', '6', 'Memories, both good and bad, suffuse the high school experience. Whether it''s hanging out with friends or cramming for tests, everyone has something they will remember from that time in their lives. At a certain high school, one class is faced with an event that can cause people to look back on their high school days in sadness: the death of a student.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Captain Earth', 'TV', 25, 'Completed', '2014-04-06', '2014-09-21', '6', 'One night, right before summer vacation, Manatsu Daichi, a second-year in high school, sees a weird round rainbow floating in the sky above Tanegashima and ventures there alone. He has seen this rainbow before. With the memories of his father''s mysterious death and an encounter of a strange boy and girl, Daiji arrives on the island while the alarm of a building labeled Earth Engine is going off. Someone asks him if he is a captain, just as robotic intruders from Uranus called Kill-T-Gang arrive. The battle around the shining stars is about to begin.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Qing Chi Hong Xiaodou Ba! 2nd Season', 'ONA', 16, 'Completed', '2019-01-13', '2019-04-25', '6', 'A daily of a cute red bean struggles to get eaten everyday.', 546, 'https://cdn.myanimelist.net/images/anime/1996/98957.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Vatican Kiseki Chousakan', 'TV', 12, 'Completed', '2017-07-07', '2017-09-22', '6', 'Fathers Josef Kou Hiraga and Roberto Nicholas are Vatican Miracle Examiners who investigate the authenticity of miraculous phenomena reported from all over the world. In every seemingly sacred event lies horrors of hidden conspiracies, mysterious murders, and devil worship. In this battle of good and evil, Hiraga, a scientific and mathematical genius, and Roberto, a polymath in linguistics and classics, must work together to bring the truth to light. Will their friendship and faith endure the evils in their journey to find a true miracle?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eden (ONA)', 'ONA', 4, 'Completed', '2021-05-27', NULL, '6', 'The sci-fi fantasy series Eden is set thousands of years in the future, where a city known as "Eden 3" is inhabited solely by robots whose former masters vanished a long time ago. On a routine assignment, two farming robots accidentally awaken a human baby girl from stasis questioning all they were taught to believe—that humans were nothing more than a forbidden ancient myth. Together, the two robots secretly raise the child in a safe haven outside Eden. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zombie-ga Doeeo Beorin Naui Ttal', 'TV', 26, 'Completed', '2022-04-03', '2022-06-26', '6', 'One year after an unprecedented zombie attack that killed hundreds of thousands, South Korea has finally been declared zombie-free. But Jeonghwan holds a secret: his daughter is the last zombie left on earth. When her cravings are satisfied and her violent tendencies die down, it almost seems like there''s hope for her to have a normal life. But how long can he keep Su-ah a secret from everyone else?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aharen-san wa Hakarenai Mini', 'ONA', 18, 'Completed', '2022-03-12', '2022-06-19', '6', 'Mini anime for Aharen-san wa Hakarenai released on the official Twitter.', 39, 'https://cdn.myanimelist.net/images/anime/1478/129780.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xue Se Cang Qiong', 'ONA', 26, 'Completed', '2017-08-18', '2018-01-26', '6', 'Li Mingyang was originally an ordinary office worker. Because of a strange QR code, he was trapped in a killing city. Here everyone is forced to participate in a survival game that is going to kill or be killed. In the process of finding a way out of the city, the mastermind behind the whole incident surfaced step by step.', 159, 'https://cdn.myanimelist.net/images/anime/8/88891.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Queen''s Blade: Rebellion Specials', 'Special', 6, 'Completed', '2012-06-27', '2012-11-28', '6', 'Specials included in the Blu-ray/DVD volumes. Each special will be about a different character.', 85, 'https://cdn.myanimelist.net/images/anime/7/38419.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('DRAMAtical Murder: Data_xx_Transitory', 'Special', 1, 'Completed', '2014-12-24', NULL, '6', 'Data xx Transitory is the thirteenth and bonus episode of the DRAMAtical Murder animation. It features all of the bad endings from the original game.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shounen Hollywood: Holly Stage for 49', 'TV', 13, 'Completed', '2014-07-06', '2014-09-27', '6', 'At a theater called Hollywood Tokyo in Harajuku, members of the idol group "Shounen Hollywood" develop their talents with diligent work and studying.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Elsword: Ain-ui Gieog Animation', 'ONA', 1, 'Completed', '2016-12-12', NULL, '6', 'This was the Secret Video that was shown in Anime premiere event. It tells the story of, Ain, a secretive timekeeper during the events of Elsword: El-ui Yeoin''s first episode.
