INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dixia Cheng Yu Yongshi: Nizhuan Zhi Lun', 'ONA', 12, 'Completed', '2020-04-23', '2020-07-23', '6', 'Sequel to Arad: Suming Zhi Men.', 499, 'https://cdn.myanimelist.net/images/anime/1117/108106.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ikebukuro PR Anime', 'ONA', 1, 'Completed', '2019-01-17', NULL, '6', 'The anime''s story takes place in the year 2020, near the Hareza Tower building plaza. This is an area under development currently but is expected to be completed by 2020. A girl gives chase to an owl she sees in Ikebukuro. Over the course of the anime, the audience witnesses the girl grow and learns about the charm of Ikebukuro, a place where "everyone can be the lead player."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Neko no Nyagh: Nya Misérables', 'TV', 25, 'Completed', '2019-04-03', '2019-09-18', '6', 'TV adaptation of Cocone Corporation''s mobile puzzle game app.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ying Xiong Bie Nao', 'ONA', 13, 'Completed', '2015-07-01', '2015-11-04', '6', 'The series takes place on a parallel world filled with superhumans. Allegiances are formed between heroes and villains.', 1082, 'https://cdn.myanimelist.net/images/anime/1013/132391.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam G40', 'ONA', 1, 'Completed', '2020-01-01', NULL, '6', 'U.C. 0079 - A squadron of Zakus from the Principality of Zeon invades a neutral space colony. Amuro Ray reluctantly pilots the Gundam G40 prototype mobile suit to combat the threat, as well as Zeon ace pilot Char Aznable and his custom red Zaku II.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dahua Zhi Shaonian You', 'ONA', 16, 'Completed', '2020-08-15', '2020-11-20', '6', 'Rookie Jianghu and swordsman Xiao Yao Sheng have defeated the baby-eater that caused Chang''an, but they now find themselves falling into a bigger mystery. They traveled to the distant Spirit Beast Village and met the beautiful Demon Fox Girl, the Bone Elves, and people of all kinds inhabiting rivers and lakes along the way. They gained growth and friendship, but are now entangled in a greater crisis: a dispute between immortals and demons. The animation will combine elements such as martial arts, fantasy, blood, adventure, and more, to present to the audience a tale of ups and downs in legendary stories!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tama Pawns', 'ONA', 6, 'Completed', '2017-01-27', '2017-02-01', '6', 'The story follows Mihiro and begins on a day like any other. Mihiro bumps heads with a pet dog and loses consciousness. When she wakes up, she finds herself in a mysterious animal world. Mihiro discovers the shocking truth of her new situation and starts work at an animal pawn shop. She sets her sights on the day she can leave the shop and return to her former world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsukiyo to Megane', 'Movie', 1, 'Completed', '1966-01-01', NULL, '6', 'An adaptation of Mimei Ogawa''s short story. It was a night with a beautiful moon. An optician visited an old lady who was living in a house alone just outside of town. Since she has gotten older and her eyesight has weakened, she bought a pair of large-rimmed glasses made of tortoise shell... 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Choukadou Girl ⅙: Nona Video Nikki', 'ONA', 40, 'Completed', '2019-02-13', '2019-07-01', '6', '', 851, 'https://cdn.myanimelist.net/images/anime/1641/102913.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shiroi Zou', 'Movie', 1, 'Completed', '1963-01-01', NULL, '6', 'A Matsue Jinbo production of the classic "White Elephant" story where a kind white elephant is tricked into helping a human who leads others back so the elephant would be captured.', 324, 'https://cdn.myanimelist.net/images/anime/4/80519.jpg');
