INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hei Mao Jing Zhan Zhi Fei Cui Zhi Xing', 'Movie', 1, 'Completed', '2015-08-07', NULL, '5', 'In this exciting Chinese action flick, Mr. Black is back! After notorious criminal rat, One-Ear escapes, Mr. Black organises a all-points bulletin to capture him. But more trouble is brewing: a mad ape scientist, Dr. Big Ape seeks revenge on those who have wronged him. Now joining forces with One-Ear, they have a diabolical plan up their sleeve: to kidnap the citizens and banish them to space using the "Emerald Star" on opening day. With the help of his fellow officers and a young pig partner, Mr. Black faces his foes in an epic showdown of the "Emerald Star"
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zhandou Wang Zhi Jufeng Zhan Hun 5', 'TV', 26, 'Completed', '2018-09-14', '2018-10-09', '5', '', 58, 'https://cdn.myanimelist.net/images/anime/1018/108496.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Miao Xiansheng', 'Movie', 1, 'Completed', '2020-07-31', NULL, '5', 'Adapted from a short tale from self-made animator Bu Sifan, writer and director of Dahufa, the feature introduces a fictional golden-colored flower, which possesses the magical ability to debauch humans who get too close to it.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saikyou Kamizmode!', 'ONA', 26, 'Completed', '2020-09-28', '2021-04-01', '5', 'Dai Mugen once held an unmatched passion for playing the drums. However, after being defeated by rival drummer Rin Tanba in a competition, he is left questioning where his heart lies and quits as a result.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pittarazu', 'OVA', 10, 'Completed', '2014-03-04', '2014-06-03', '5', 'A series of surreal dialogue-heavy sketches by comedy trio Tokyo03 featuring everyday objects.', 214, 'https://cdn.myanimelist.net/images/anime/1243/108652.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pittarazu Gekijou Manner CM', 'Special', 9, 'Completed', '2013-09-07', '2014-08-23', '5', 'Pittarazu-themed manner movies shown at T-JOY owned theaters around Japan. The first four were shown from August 7, 2013 to November 1, 2013 and were included as specials on the Pittarazu DVDs. Beginning August 23, 2014, five more manner movies were shown at theaters. All nine manner movies were later posted on DLE''s official YouTube channel.', 214, 'https://cdn.myanimelist.net/images/anime/1368/108657.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sonic: Night of the WereHog', 'ONA', 1, 'Completed', '2008-11-01', NULL, '7', 'Published on SEGA''s website in November of 2008, Sonic: Night of the Werehog is an ONA made to promote the release of Sonic World Adventure, also known as Sonic Unleashed in North America and Europe. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bakugan Battle Brawlers: New Vestroia', 'TV', 52, 'Completed', '2010-03-02', '2011-03-05', '7', 'After the final downfall of the rogue Bakugan Naga, peace was brought back to Vestroia. With the help of Danma Kuusou, his companion Pyrus Dragonoid, and other Battle Brawlers, the Infinity and Silent Cores were combined and the realm was recreated.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seishun Anime Zenshuu', 'TV', 32, 'Completed', '1986-04-25', '1986-12-26', '7', 'A brilliant collection of beautifully animated episodes based on selected masterpieces of Japanese modern literature.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Holmes: Mrs. Hudson Hitojichi Jiken no Maki / Dover Kaikyou no Daikuuchuusen no Maki', 'Movie', 1, 'Completed', '1986-08-02', NULL, '7', 'The second Meitantei Holmes movie featuring two episodes from the anime series.', 990, 'https://cdn.myanimelist.net/images/anime/3/54265.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rolling☆Girls', 'TV', 12, 'Completed', '2015-01-11', '2015-03-29', '7', 'In a dystopian future where Japan''s political organization has crumbled after the Great Tokyo War, Japan is broken up into 10 independent nations, with each nation controlled by a gang led by a "Best," a human-proclaimed prophet with destructive superpowers. Nozomi Moritomo is a "Rest"—a normal girl that has just started out as a rookie in the local gang. She wants to help the Best Masami Utoku, her childhood friend and role model, in the ongoing territorial dispute. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Betterman', 'TV', 26, 'Completed', '1999-04-02', '1999-10-01', '7', 'Keita Aono is an ordinary high school student who loves to chat with his friends about military technology and the girls in their class. One day, Keita is surprised and delighted by a new transfer student in his class, his childhood friend Hinoki Sai. But when Keita tries to catch up with Hinoki after school, he accidentally wanders into Bottom World—an underground amusement park whose opening was canceled due to an unexplained tragedy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Star Ocean EX', 'TV', 26, 'Completed', '2001-04-03', '2001-09-25', '7', 'Claude C. Kenni, a crewmember on the spaceship Calnus and son of the commander of the ship, is transported to Expel, a backwards planet with swords and magic. He teams up with Rena Lanford, who thinks he is the legendary Warrior of Light, and other characters to investigate the Sorcery Globe, a meteorite that has been causing problems all over the world. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Asobot Senki Gokuu', 'TV', 52, 'Completed', '2002-10-01', '2003-09-30', '7', 'Four years into the future, the world has lost its balance...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaibutsu-kun', 'TV', 49, 'Completed', '1968-04-21', '1969-03-23', '7', 'The prince of Kaibutsu Land, Kaibutsu-kun, decides to go to the human world as part of his training to become the King.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mars Red', 'TV', 13, 'Completed', '2021-04-06', '2021-06-29', '7', 'In the year 1923, a vampire crisis takes Tokyo by storm. Provoked by the illegal trade of "Ascra," an artificial blood source, the population of vampires begins to rapidly increase within the city. Under orders from Lieutenant General Sounosuke Nakajima, the Special Forces Unit 16 gathers vampires within the military to create a new undercover vampire-hunting unit known as Code Zero.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Stars*Collection!', 'ONA', 61, 'Completed', '2022-01-28', '2023-03-24', '7', 'A series of shorts following the eccentric and hilarious daily lives of the Holostars VTubers!', 383, 'https://cdn.myanimelist.net/images/anime/1261/120889.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Candy Candy: Haru no Yobigoe', 'Movie', 1, 'Completed', '1978-03-18', NULL, '7', 'Candy returns to Pony''s Home and she meets a girl who has lost her parents and doesn''t associate with the other kids. In order to cheer her up she decides to tell her about herself from the moment she was found by Miss Pony and sister Lane to her decision to leave the boarding school in England and walk her own path.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaiketsu Jouki Tanteidan', 'TV', 26, 'Completed', '1998-10-07', '1999-03-31', '7', 'The scene is Steam City, a London-ish city which represents an entire civilization run by coal and steam power. Because of steam, the city is sometimes covered in a mist. Villains take advantage of the steamy mist to hide and execute their evil plans. Only a few dare venture into what''s beyond the steamy mist. They are known as the Steam Detectives: Narutaki (and his convertible all-purpose pistol), his nurse-assistant Lingling, and his Megamaton robot Gohliki.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Junk Head 1', 'Movie', 1, 'Completed', '2013-11-16', NULL, '7', '', 1126, 'https://cdn.myanimelist.net/images/anime/1686/116666.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mitsubachi Maya no Bouken', 'TV', 52, 'Completed', '1975-04-01', '1976-04-20', '7', 'Maya, a newborn honeybee, brims with curiosity about the world around her. From the time she is born, she is brought up to be a worker bee, but it is difficult for her to understand and follow the strict rules of the hive because of her individuality and strong desire for independence.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tottoko Hamtarou OVA 1: Hamtaro no Otanjoubi - Mama wo Tasunete Sanzen Techi Techi', 'OVA', 1, 'Completed', '2002-11-21', NULL, '7', 'Laura tells Hamtaro where he came from yet Laura thinks it is not true, just in time for his birthday, Hamtaro sets out with Boss and Oxnard to visit his mother to see if what Laura said is true, while the other Ham-Hams set up a surprise birthday party for him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Five Star Stories', 'Movie', 1, 'Completed', '1989-03-11', NULL, '7', 'Amaterasu is the god of light, the future emperor of the Joker Star System. Under the guise of young mecha conceptor Ladios Sopp, he is compelled by an old friend, Dr Ballanche, to save his two latest Fatimas Lachesis and Clotho. And so began the stories of the Joker System, as well as Amaterasu''s love for Lachesis. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bomberman B-Daman Bakugaiden', 'TV', 48, 'Completed', '1998-02-07', '1999-01-31', '7', 'A long time ago, B-Da City was attacked by an evil force called the Dark B-Da (or dark beings) in their quest to control the entire Blue Solar System. The heroic B-Daman, drawing on their legendary powers and ingenious technology, were able to overthrow the Nol Arc Empire and restore peace to the universe. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chibi Maruko-chan: Watashi no Suki na Uta', 'Movie', 1, 'Completed', '1992-12-19', NULL, '7', 'Sakura Momoko''s teacher assigns the third grade to draw an image based on their favorite song to enter a contest. Momoko loves a song she recently learned during her music class and is anxious to make a good drawing based on it. On her way to meet her relatives in Shizuoka, she meets Shouko Kimura, a university student who occasionally draws portraits at the local train station and plans to also participate in an art contest. Fascinated by her illustrations, Sakura meets Kimura once again. Shouko is enchanted by Momoko''s sympathy and honesty. They quickly become friends and end up inspiring each other in their own way.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Baka to Test to Shoukanjuu Specials', 'Special', 6, 'Completed', '2010-04-23', '2010-09-22', '7', 'The candid shots of Muttsurini''s female and male classmates that fund his surveillance habits.', 761, 'https://cdn.myanimelist.net/images/anime/8/67315.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('ef: A Tale of Memories. - Recollections', 'Special', 1, 'Completed', '2008-09-26', NULL, '7', 'Asou Renji comes back at the station with Chihiro, after the events of ef - a tale of memories. They recollect various moments in this ''summary'' of the first season of ef, with special new intermissions.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gakuen Utopia Manabi Straight!', 'TV', 12, 'Completed', '2007-01-08', '2007-03-26', '7', 'Manabi Straight! follows the lives of a group of young high school girls living in the year 2035 while they attend the all-girl Seioh Private High School. Since the birth rate has dropped dramatically, schools are being closed down due to the sheer lack of students available to teach. Morale in schools has dropped dramatically, and Seioh is no exception.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hitorijime My Hero', 'TV', 12, 'Completed', '2017-07-08', '2017-09-23', '7', 'Masahiro Setagawa is a hopeless teenager who is often used by the neighborhood bullies as an errand boy. Defenseless, Masahiro knows that nobody will ever save him. However, his life drastically changes when he meets Kousuke Ooshiba, a man known as the "Bear Killer," who takes down neighborhood gangs.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yamada-kun to 7-nin no Majo PV', 'Special', 1, 'Completed', '2013-08-25', NULL, '7', 'Shiraishi Urara is the top student in her school. One day, due to an accidental kiss, Urara finds herself in the body of the school delinquent, Yamada Ryuu! In trying to switch back to their own bodies, Urara and Ryuu discover that kissing causes them to switch bodies, which leads to their discovery that there are 7 witches in their school. They soon try to uncover the identities of the 7 witches... 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam I', 'Movie', 1, 'Completed', '1981-03-14', NULL, '7', 'In the future, with Earth''s population rapidly increasing, humanity has developed giant orbiting space colonies gathered in clusters known as "Sides." As the elites on Earth force most of the populace into space, rebellion begins to brew. In the year Universal Century 0079, one of the colony clusters known as Side 3 declares itself the Principality of Zeon and launches a war of independence against the Earth Federation.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kanojo to Kanojo no Neko', 'OVA', 1, 'Completed', '1999-01-01', NULL, '7', 'It was on a rainy spring day that Chobi became a young woman''s pet cat. Though he immediately fell in love with the beautiful and kind person who took him in, he can never hope to fully understand the complex world of humans. Over the course of their first year living in the same apartment, Chobi and his new owner live in their own separate worlds⁠—standing alone yet close together.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The Sky Crawlers', 'Movie', 1, 'Completed', '2008-08-02', NULL, '7', 'In an alternate timeline, the world has seemingly achieved peace. Bereft of international conflicts, wars are now waged between private corporations in place of peaceful nations. Yuuichi Kannami, a recent transfer in Area 262, simply does his job as a contracted fighter pilot. However, the more time he spends at his new base, the more mysteries come to light.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yes! Precure 5 Movie: Kagami no Kuni no Miracle Daibouken!', 'Movie', 1, 'Completed', '2007-11-10', NULL, '7', 'The five girls plus Coco, Nuts, and Milk all go to visit a castle-themed theme park, where they dress up as princes and princesses and go off to have a fun-filled day. However, Coco and Nuts end up kidnapped! The girls have to save them with the help of two inhabitants of the Mirror Country, Hidarin and Migirin,  by battling Shadow, an evil clown, and five girls who are also from the Mirror Country that look very familiar...', 1030, 'https://cdn.myanimelist.net/images/anime/1878/142472.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Konjiki no Gash Bell!!: 101-banme no Mamono', 'Movie', 1, 'Completed', '2004-08-07', NULL, '7', 'During the Summer holidays, Gash and gang decide to head for Fuji Mountain for a picnic gathering. There, they encounter a girl with a white magical book. Her name is Kotoha and her book has a message saying that Gash''s mother is located a cave in the forest. However, when they eventually found the cave, there was already a blond-haired youth by the name of Wiseman. In order to rescue Wiseman, Gash and the others attempt to proceed into the depths of the cave and stumble upon the entrance to another world. Soon later, the strongest warrior, the Black Knight, appeared before them. Thinking that Gash was the one who stole the 101th magical book, the Black Knight started to attack them. Gash and Kiyomaro have to find the real criminal in exactly 24 hours, or else they will be stuck in the alternative world forever.', 1030, 'https://cdn.myanimelist.net/images/anime/5/15308.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('JoJo no Kimyou na Bouken: Adventure', 'OVA', 7, 'Completed', '2000-05-25', '2002-01-25', '7', 'Kujo Jotaro is a normal, popular Japanese high-schooler, until he thinks that he is possessed by a spirit, and locks himself in prison. After seeing his grandfather, Joseph Joestar, and fighting Joseph''s friend Muhammad Abdul, Jotaro learns that the "Spirit" is actually Star Platinum, his Stand, or fighting energy given a semi-solid form. Later, his mother gains a Stand, and becomes sick. Jotaro learns that it is because the vampire Dio Brando has been revived 100 years after his defeat to Jonathan Joestar, Jotaro''s great-great-grandfather. Jotaro decides to join Joseph and Abdul in a trip to Egypt to defeat Dio once and for all.', 38, 'https://cdn.myanimelist.net/images/anime/8/53147.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan OVA 07: Agasa kara no Chousenjou! Agasa vs Conan & Shounen Tanteidan', 'OVA', 1, 'Completed', '2007-03-13', NULL, '7', 'Professor Agasa is kidnapped and the Detective Boys must use clues found at his house and in various parts of the city in order to find him.', 990, 'https://cdn.myanimelist.net/images/anime/12/31145.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xue Ying Ling Zhu 3rd Season', 'ONA', 26, 'Completed', '2021-12-27', '2022-06-13', '7', 'The third season of Xue Ying Ling Zhu.', 564, 'https://cdn.myanimelist.net/images/anime/1490/120175.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Natsuyuki Rendezvous', 'TV', 11, 'Completed', '2012-07-06', '2012-09-14', '7', 'Ryousuke Hazuki is a young man whose heart has been stolen away, stopping by the local floral shop daily in order to catch a glimpse of the beautiful Rokka Shimao, the shop''s owner. In hopes of getting close to her, he decides to get a part-time job at the shop, but before he is able to make his move, he runs into a major roadblock: in her apartment dwells a ghost who claims to be Rokka''s deceased husband.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yu☆Gi☆Oh!', 'TV', 27, 'Completed', '1998-04-04', '1998-10-10', '7', 'Bullies often target someone frail and weak—someone exactly like Yuugi Mutou. His beautiful childhood friend, Anzu Mazaki, is always there to stand up for him, but he can''t depend on her forever. Katsuya Jonouchi, who is almost always accompanied by his verbal sparring partner Hiroto Honda, doesn''t seem like a bad person either, despite always bringing Yuugi trouble. But most of all, Yuugi wishes for a true friend who understands him and would never betray him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam SEED Special Edition', 'Special', 3, 'Completed', '2004-08-27', '2004-10-22', '7', 'Three TV Specials complied from Kidou Senshi Gundam SEED series.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Another: The Other - Inga', 'OVA', 1, 'Completed', '2012-05-26', NULL, '7', 'Shortly before the start of a new semester, Misaki Fujioka visits her twin sister Mei Misaki in Yomiyama City. The girls make full use of the last days of summer, roaming around a heat-weary town and visiting various places including a shopping center and shooting stall. When they prowl around her basement, Mei expresses uneasiness about her new class, which is said to be cursed.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kowarekake no Orgel (Movie)', 'Movie', 1, 'Completed', '2010-09-11', NULL, '7', 'In 2039, helper androids are widespread as general purpose electronics. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mononogatari', 'TV', 12, 'Completed', '2023-01-10', '2023-03-28', '7', 'Saenome are tasked with sealing spirits that possess objects and pose a threat to society. Known as tsukumogami, these spirits are generally non-violent, and saenome normally seal them after a simple verbal exchange.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sekirei: Pure Engagement', 'TV', 13, 'Completed', '2010-07-04', '2010-09-26', '7', 'The second stage of the battle royale known as the Sekirei Plan is underway. Shintou Teito has been closed off; no Sekirei or Ashikabi may leave. Minato Sahashi and his harem of Sekirei must now prepare to fight new battles as changes to the rules are put into place. However, not all groups will return to the battle: some Sekirei are loved very much by their Ashikabi partners, who would rather forfeit the prize than see them perish.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Slow Loop', 'TV', 12, 'Completed', '2022-01-07', '2022-03-25', '7', 'Since childhood, Hiyori Yamakawa has witnessed her father''s various eccentricities, but one activity she has always loved doing with him is fly fishing—a complicated yet rewarding method of catching fish. Even after his sudden death, Hiyori still visits the seaside in her spare time, savoring the joy that her father''s memento brings her.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Otome Game no Hametsu Flag shika Nai Akuyaku Reijou ni Tensei shiteshimatta... X', 'TV', 12, 'Completed', '2021-07-03', '2021-09-18', '7', 'With no more death flags in sight, personable but dense Catarina Claes is finally able to lead a peaceful life surrounded by all of her friends and family. For that reason, she is determined to enjoy the school festival to the fullest without any concern on her mind.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hanamaru Youchien', 'TV', 12, 'Completed', '2010-01-11', '2010-03-29', '7', 'Anzu goes to a kindergarten with her friends, the shy Koume and the eccentric Hiiragi. Together they try to make their caretaker, Tsuchida Naozumi, fall in love with Anzu. However, he is clearly more interested in the pretty Yamamoto Nanako, a fellow kindergarten teacher who supervises the class next door. Even though Anzu tries to convince Tsuchida to marry her when she grows up by using various methods. Tsuchida, on the other hand, hopes to get a chance to date Yamamoto, and, if not, to marry her.', 321, 'https://cdn.myanimelist.net/images/anime/3/50395.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Genjitsu Shugi Yuusha no Oukoku Saikenki', 'TV', 13, 'Completed', '2021-07-04', '2021-09-26', '7', 'After the death of his grandfather, 19-year-old Kazuya Souma—an aspiring civil servant—is left all alone with no one to call family. Out of the blue, he is transported to the Elfrieden Kingdom, a small ailing country in another world, to be a "hero." An ongoing war with the demon army has put the entire world in peril, and Kazuya was summoned to aid in the conflict as an offering from Elfrieden to its allies.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Null Peta', 'ONA', 12, 'Completed', '2019-10-04', '2019-12-20', '6', 'Genius inventor Null tragically loses her older sister Peta in an accident. To get over the grief, Null develops "Peta Robo," a robot with the same characteristics as her late sister. However, the robot is a little different as to what Null expected.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Evangelion Shito, Hakata Shuurai', 'Movie', 1, 'Completed', '2019-06-07', NULL, '6', 'When the Fourth Angel attacks Shin Fukuoka City, it''s up to Shinji Ikari and his friends Asuka Langley Soryu, Rei Ayanami, and Mari Illustrious Makinami to stop it through any means necessary.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Planetarium Chibi Maruko-chan, Hoshi ni Negai wo', 'Movie', 1, 'Completed', '2015-07-18', NULL, '6', 'The Konica Minolta "Tenkuu" Planetarium in Tokyo Skytree Town will run a Chibi Maruko-chan planetarium show from July 18 to August 31. The show, titled "Planetarium Chibi Maruko-chan, Hoshi ni Negai wo" (Planetarium Chibi Maruko-chan, Wish Upon a Star), celebrates the 25th anniversary of the Chibi Maruko-chan anime since it first aired in January 1990.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga Hyouryuu Vifam 13', 'TV', 26, 'Completed', '1998-03-21', '1998-10-03', '6', 'On July 27 1996, Mr. Takeyuki Kanda died suddenly at the age of 52. Born August 11 1943, he was known as the director of several animations including VIFAM. Thus in 1998 a new TV series of VIFAM was broadcasted in memory of him. Televised 1998/3/21-1998/10/3 (in Kansai area), it contains 26 episodes, and like Twelve people disappeared it is a sidestory, but some new features are added: new persons, new RV, etc.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga Hyouryuu Vifam: Keito no Kioku - Namida no Dakkai Sakusen', 'OVA', 1, 'Completed', '1985-09-25', NULL, '6', 'The story takes place in Kukto in D.C. 2060 - a year after VIFAM. Ypserlon has been restored to peace, though there still remains occasional skirmishes. The Thirteen are invited there for a ceremony by the new Kukto government (its members are formerly the rebels). As two unexpected people appear, they develop a new story. It is a quest for memory.', 974, 'https://cdn.myanimelist.net/images/anime/8/59739.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Takamiya Nasuno desu! Teekyuu Spin-off', 'TV', 12, 'Completed', '2015-04-07', '2015-06-23', '6', 'A spin-off from Teekyuu which centers on the daily life of Nasuno Takamiya, the "exceedingly airheaded" school tennis club member in Teekyuu, and her friends.', 566, 'https://cdn.myanimelist.net/images/anime/12/73473.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ketsuekigata-kun! 2', 'TV', 12, 'Completed', '2015-01-08', '2015-03-26', '6', 'A-gata-kun, B-gata-kun, O-gata-kun, and AB-gata-kun are back again to explore more cultural stereotypes associated with blood type! With assistance from their feminine counterparts, the blood types delve into a range of topics related to relationships, such as one''s own charms, how to react to a mediocre gift, and... How to properly hide adult content on a computer? Whether they are stranded on an uninhabited island or sharing a dorm room together, no two blood types will react the same way to any of these humorous yet relatable situations.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Miru Tights: Cosplay Satsuei Tights', 'Special', 1, 'Completed', '2019-08-23', NULL, '6', 'In the lead-up to a photoshoot in which Yua Nakabeni and Ren Aikawa have been invited to model for an illustrator, the two girls are feeling anxious. To help them out, their friend and fellow classmate Homi Moegi decides to run a practice shoot in hopes of easing their nerves.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Moetan', 'TV', 12, 'Completed', '2007-07-09', '2007-09-24', '6', 'Ink Nijihara is a girl in high school. Unfortunately her crush Nao Tezuka barely recognizes her. To make matters worse, she is very short. Now Ink meets a duck and becomes a "mahou shoujo" and teaches Nao english in disguise. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blue Dragon', 'TV', 51, 'Completed', '2007-04-07', '2008-03-29', '6', 'As Shu''s village was being attacked by an unknown enemy, he and his friends, Jiro and Kluke decide to defend their home. They soon meet warrior Zola and receive the powers of Shadow, an ability that let''s them transform their shadow into a powerful monster. Shu receives one of the most powerful monsters, Blue Dragon, and they all set out to defeat their enemy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lovely Movie: Itoshi no Muco', 'TV', 20, 'Completed', '2013-07-29', '2013-12-23', '6', 'The happy daily life of Muco, a not-too-bright Akita dog, and its owner Komatsu-san the glass-blower.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tori no Uta (OVA)', 'OVA', 1, 'Completed', '2007-01-30', NULL, '6', 'A boy is walking home through the city where he finds a new path that he follows. It starts to rain and he seeks shelter with the aid of a girl. He falls in love with the girl. He gets a feather, and if he always carries it, they will meet again. He returns to his home following the path, but the next day he cant find it again. Time progresses and he forgets the girl. 50 years later he returns to the same city and he dreams of the girl. He is still dutifully carrying the feather. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Beast Wars Second Chou Seimeitai Transformers', 'TV', 43, 'Completed', '1998-04-01', '1999-01-27', '6', 'Beast Wars Second features a new cast of characters set many years in the future, who travel to a post apocalyptic Earth now known as the planet Gaia. The Cybertrons, led by Lio Convoy, are sent to the planet to investigate an unusual change in the planet’s behavior and thus thwart the Destrons, led by Galvatron, who seek to consume the planet’s rich source of energy called Angolmois.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hello Harinezumi: Satsui no Ryoubun', 'OVA', 1, 'Completed', '1992-09-01', NULL, '6', 'One stormy night, a young woman is shot to death on a cliff; her body is found floating in the waters below the next morning. She was last seen with a man who is now being sought not only for her death. Meanwhile, an estranged wife hires Goro, a private investigator, to find her husband. Alongside another member of law enforcement with his own motives for finding the man, Goro sets forth on a trail of tragedy and intrigue to find the reason and connection behind the murders and missing husband.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blue Seed 2', 'OVA', 3, 'Completed', '1996-07-24', '1998-02-04', '6', 'A renegade scientist in San Francisco has found a way to create a new creature called a Neo-Aragami without the power of Susanoo. When these monsters start to terrorize California, the U.S. turns to the old members of the Terrestrial Administration Center (TAC) for help. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaiketsu Zorori Da-Da-Da-Daibouken!', 'Movie', 1, 'Completed', '2012-12-22', NULL, '6', 'The first full-length feature film adaptation of Yutaka Hara''s Kaiketsu Zorori.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yi Shijie Zhongyao Pu', 'ONA', 40, 'Completed', '2020-05-08', '2020-09-11', '6', 'After graduating from the University of Traditional Chinese Medicine, Sun Jiayou returned home to inherit a traditional Chinese medicine shop. He found that although the people here would not use medicine as a treatment, they had own spiritual system. To realize his grandfather’s dream, he plans to promote Chinese medicine in a different world. However, the spirit messenger considers it a big threat. In some confrontations with the spirit messenger, he discovers a greater mystery.', 978, 'https://cdn.myanimelist.net/images/anime/1789/108202.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nine: Original-ban', 'Movie', 1, 'Completed', '1983-09-16', NULL, '6', 'Cinema adaption of the manga by Mitsuru Adachi.', 351, 'https://cdn.myanimelist.net/images/anime/5/49881.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tekkamen wo Oe: "d''Artagnan Monogatari" yori', 'Special', 1, 'Completed', '1987-05-05', NULL, '6', 'Based on The Three Musketeers by Alexandre Dumas.', 325, 'https://cdn.myanimelist.net/images/anime/12/21062.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lime-iro Senkitan: Nankoku Yume Roman', 'OVA', 2, 'Completed', '2004-04-23', '2004-06-25', '6', 'With the battleship Amanohara seriously damaged and in need of repair, it lands on an island where a Gogyou festival has just begun. Shintaro Umakai and his five female students, known as Raimu Unit, enjoy a period of peace on the island. However, the enemy still pursues them. Umakai and his unit deal with the enemy while the five girls try to draw his attention.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boku, Otaryman.', 'OVA', 1, 'Completed', '2010-01-29', NULL, '6', 'Boku, Otary-man (otaku + salaryman) is a autobiographical manga of the author Yoshitani, who is also working as a system engineer. It''s about a slice of life of an office worker, who is a little bit otaku.', 666, 'https://cdn.myanimelist.net/images/anime/13/19796.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Majokko Shimai no Yoyo to Nene Movie Extra: Hatsukoi - Mikako Komatsu', 'Special', 1, 'Completed', '2014-06-25', NULL, '6', 'An animated music video included as a bonus on the Blu-ray/DVD release of Majokko Shimai no Yoyo to Nene.', 1192, 'https://cdn.myanimelist.net/images/anime/11/64181.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaiketsu Zorori: Mahoutsukai no Deshi/Dai Kaizoku no Takara Sagashi', 'Movie', 1, 'Completed', '1993-07-17', NULL, '6', '"Unbelievable" Zorori is a prankster fox determined to become the Prince of Mischief, with his very own castle and beautiful bride. While is notorious for his prank-making schemes, his ill-meaning plots often backfire against him, and can usually end up even benefiting or cheering up his targets, much to his dismay. Nevertheless, Zorori has the wits and intelligence to wriggle out of the tightest of all spots, and journeys with a pair of twin boars, Ishishi and Noshishi, in order to fulfill his long wished-for goal and at last prove to his deceased mother, Mama Zorori that he truly holds the potential to achieve his dreams.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sugar Bunnies Chocolate!', 'TV', 26, 'Completed', '2008-04-01', '2008-09-30', '6', 'Sequel to Sugar Bunnies.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Luck & Logic', 'TV', 12, 'Completed', '2016-01-09', '2016-03-26', '6', '"Logic" is the concept that governs emotions, abilities, ideals, memories, and all other abstract properties that make up life in various worlds. With its power, however, alien "Foreigners" are able to pass through portals imbued with their respective world''s Logic and pose a threat to other worlds. To counter this problem, the Another Logic Counter Agency (ALCA) from the human world of Septpia employs "Logicalists," people with the power to form bonds with the Foreigners who seek peace and share their Logic, tasked with dealing with all possible dangers.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('King''s Raid: Ishi wo Tsugumono-tachi', 'TV', 26, 'Completed', '2020-10-03', '2021-03-27', '6', 'Long ago, the king of Orvelia, Kyle, defeated the demon king Angmund and brought peace to the world. However, one hundred years later, demons have been sighted in the forests, threatening humanity once more. A scouting expedition is sent to verify the claim but only one member returns. Meanwhile, Riheet, the leader of a dark elf mercenary group, plots to take over Orvelia to exact revenge against the humans who forsook their race a century ago.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam: Uchuu Seiki Yowa', 'Special', 10, 'Completed', '1996-10-25', '1999-07-25', '6', 'Brief background information about the One Year War as told by a narrator, to fill in some gaps for new viewers of the franchise.', 974, 'https://cdn.myanimelist.net/images/anime/8/28180.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hakujaden', 'Movie', 1, 'Completed', '1958-10-22', NULL, '6', 'As a young boy, Xu-Xian is forced to free his pet, a small snake. Unbeknownst to him, the snake is actually a young snake goddess named Bai-Niang and she is in love with him. Many years later, when they are both adults, the princess is magically transformed into a human and sets out to find her love. But the local wizard believes her to be a vampire, and banishes Xu-Xian from the village in order to save him. Xu-Xian''s pet pandas Panda and Mimi set out to save him and bring him, in the process becoming leaders of an animal gang.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Angel Cop', 'OVA', 6, 'Completed', '1989-09-01', '1994-05-20', '6', 'Sometime in the future, terrorism in Japan has become commonplace, and the police have become almost as brutal as criminals. A member of the Special Security Force known as Angel, is the best of the best, stopping at nothing in her fight for justice.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sugar Bunnies', 'TV', 26, 'Completed', '2007-04-03', '2007-09-25', '6', 'Random cutesy edutainment tales aimed at small children, featuring animated speaking plushy toys.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Forza! Hidemaru', 'TV', 26, 'Completed', '2002-04-06', '2002-09-28', '6', 'A soccer anime with a cast of wacky animals in sports getup seems far out of its time in the early 21st century, but it was the year of the World Cup in Japan and South Korea, and the very young audience sees these tropes with fresh eyes. Hidemaru is a feisty fox; his friends include bunnies, dogs, horses, and a couple of hefty hippo girls. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Anime Tenchou', 'OVA', 1, 'Completed', '2002-08-19', NULL, '6', 'This is the Animation Store Manager!!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Celia-sensei no Wakuwaku Magical Kyoushitsu', 'ONA', 18, 'Completed', '2021-05-25', '2021-09-21', '6', 'Informational mini anime posted on the anime''s official Twitter and HJ Bunko/HJ Novel''s official YouTube channel.', 39, 'https://cdn.myanimelist.net/images/anime/1928/116547.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchuu Kaizoku Mito no Daibouken: Futari no Joou-sama', 'TV', 13, 'Completed', '1999-07-13', '1999-10-05', '6', 'Aoi was raised as a normal boy on Earth. Little did he know he was the heir apparent to Mito, the Queen-turned-Space-Pirate of an alien race that chooses their sex at puberty! Aoi fell in love with Mutsuki, the police officer who was chasing Mito, and the three of them saved the Universe. The only side effect was that Aoi blossomed into a beautiful young woman.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kujibiki Unbalance', 'OVA', 3, 'Completed', '2004-12-22', '2005-04-22', '6', 'Chihiro Enomoto is a freshman that just got to a new school called Rikkyoin High School. He lost his parents in a traffic accident when he was 10. Since then, he has been living only with his elder sister Shinobu. He is good at cooking and cleaning, and does all the housekeeping jobs. He fell in love with Tokino at first sight when he met her in the school library on the first day of school. Another girl named Ritsuko, a childhood friend of Chihiro and the chair of student council, falls in the love with the boy instantly after this long-awaited reunion. But she is not the only one who is in love with him. This is the story about a one-year campaign among the candidates for the next students government leaders, who are also chosen by the lot (kujibiki), in order to gain the position.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zhongguo Jingqi Xiansheng', 'ONA', 63, 'Completed', '2014-02-28', '2016-05-17', '6', 'A lost form of magic is revived from the Eastern Han dynasty, meanwhile, dangerous man eating monsters lurk the streets. What will stop these beasts from their mindless terror? 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Queen''s Blade Rebellion vs. Hagure Yuusha no Aesthetica', 'Special', 1, 'Completed', '2012-06-27', NULL, '6', 'A promotional video for Hagure Yuusha no Estetica, with a little battle against Queen''s Blade: Rebellion characters, as the first part. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aoi Sekai no Chuushin de', 'Special', 3, 'Completed', '2012-10-20', '2013-04-04', '6', 'Segua Kingdom has been losing the war against Ninterdo Empire but the tables are turned by the appearance of a boy called Gear. All the characters are parodies of Nintendo or Sega games such as Sonic the Hedgehog, Super Mario Bros., The Legend of Zelda etc.', 286, 'https://cdn.myanimelist.net/images/anime/4/43233.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('himitsukesshatakanotsume.jp', 'ONA', 78, 'Completed', '2012-04-06', '2014-04-23', '6', 'Eagle Talon, a secret society based in Kojimachi, Tokyo, with plans for world domination, is going nation-wide by broadcasting a new series through NHK! But that''s not all, they''re going world-wide with a new series on their homepage as well!', 214, 'https://cdn.myanimelist.net/images/anime/13/37615.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yumemakura Baku Twilight Gekijou', 'OVA', 4, 'Completed', '1991-05-21', '1991-11-21', '6', 'Originally released as a feature part of Studio Pierrot''s video magazine show Anime V Comic Rentaman (アニメ・V・コミック レンタマン) along with Abashiri Ikka, Eguchi Hisashi no Kotobuki Gorou Show and Akai Hayate. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Busou Chuugakusei: Basket Army', 'ONA', 5, 'Completed', '2011-12-22', '2012-12-20', '6', 'The story is set in August of 2026 at the Fuji Training Facility. Natori Touko, a third-year middle school student in the Eastern Private Defense Academy, is entrenched in field training with instructor Kamiya. It has been a harsh training regiment, but it is finally the last day. Kamiya proposes a extracurricular class under the name Newest Weapons Research. But then, an incident occurs that rocks all of Japan.', 1153, 'https://cdn.myanimelist.net/images/anime/10/48839.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('What''s Michael?', 'OVA', 1, 'Completed', '1985-11-25', NULL, '6', 'A series of adventures featuring the one cat apparently everyone in the world owns... Michael.', 483, 'https://cdn.myanimelist.net/images/anime/8/57369.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Himote House', 'TV', 12, 'Completed', '2018-10-08', '2018-12-24', '6', 'The comedy anime centers on five girls and one cat all living as housemates in Nakano, Tokyo: the three Himote sisters (Tokiyo, Kinami, and Kokoro) whose family manages the "Himote House," Kokoro''s classmates Tae and Minamo, and the cat Enishi. The girls live their daily lives trying to figure out ways to be popular, and they (and the cat) all possess a mysterious secret power...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pink Mizu Dorobou Ame Dorobou', 'Movie', 1, 'Completed', '1990-07-07', NULL, '6', 'The plot is about a young girl named Pink who is a bandit in the desert who steals water from the Silver Company.', 1030, 'https://cdn.myanimelist.net/images/anime/1605/107687.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Anime Tenchou Movie', 'Special', 1, 'Completed', '2010-11-05', NULL, '6', 'A project made to celebrate the 10th anniversary of the Animate mascot character Anime Tenchou, screened at the Animate Ichioshi Bishoujo Matsuri event in Tokyo.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shinsei Galverse', 'ONA', 1, 'Completed', '2025-06-25', NULL, '6', 'Long ago, harmony across the galaxy was maintained by a sacred star known as the Mother Planet. But that peace was shattered when the Mother mysteriously exploded and vanished without a trace.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Annecy Festival 60th Anniversary PVs', 'Special', 2, 'Completed', '2021-06-16', NULL, '6', 'Contributions by Toei Animation to celebrate the 60th anniversary of the Annecy International Animation Film Festival.', 1030, 'https://cdn.myanimelist.net/images/anime/1717/145485.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Murder Mystery of the Dead', 'TV', 6, 'Completed', '2024-11-14', '2024-12-26', '6', 'In a world devastated by a zombie pandemic, the protagonist, Mikoto Amano, wakes up in an unfamiliar place with no memory. She is taken in by six girls: Ranna, Lili, Yuu, Fumika, Murumuru, and Rumina. However, their peaceful days are suddenly shattered when a shocking event occurs—the man who was rescued alongside Mikoto is brutally murdered. The killer is among them, and the next target could be anyone...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Two Car', 'TV', 12, 'Completed', '2017-10-08', '2017-12-24', '6', 'Two Car follows high schoolers Yuri Miyata and Megumi Meguro as they battle six other rival pairs in the sport of motorcycle sidecar racing.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Honda-san x Taka no Tsume', 'ONA', 1, 'Completed', '2018-11-03', NULL, '5', 'A collaboration between the Eagle Talon franchise and Gaikotsu Shotenin Honda-san. The former is promoting the latter''s TV series. In a tongue-in-cheek style Yoshida-kun "explains" what Gaikotsu Shotenin Honda-san is about but gets it hilariously wrong much to the shock and frustration of Honda-san himself, such that never getting his name right.', 214, 'https://cdn.myanimelist.net/images/anime/1348/96025.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('the FLY BanD!', 'Special', 1, 'Completed', '1998-01-01', NULL, '5', 'The FLY BanD is a group of funky, fashionable musicians from NY who have an outstanding sense of rhythm and groove. They start another music session using daily products somewhere in the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The Ghost of Cartoon', 'Special', 1, 'Completed', '2015-09-24', NULL, '5', 'Space Shower TV Station ID directed by Ryuu Ookubo, with music by Mndsgn.', 406, 'https://cdn.myanimelist.net/images/anime/1081/102219.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Takemoto Denki x Peeping Life', 'Special', 1, 'Completed', '2014-11-16', NULL, '5', 'Peeping Life collaboration with Takemoto Denki, an electronics company. The short focuses on a career fair booth between the attendant and job hunting student.', 184, 'https://cdn.myanimelist.net/images/anime/6/77230.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Peeping Life: Shinkon-chan Kansai ni Irasshai', 'ONA', 1, 'Completed', '2014-03-27', NULL, '5', 'The newlyweds have moved to the Kansai region! For now they''ve settled down, but their room is still a huge mess. They also realize that they''ve been wasting a lot of electricity, and they begin to ponder ways to cut back on their bills...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One: Kagayaku Kisetsu e', 'OVA', 4, 'Completed', '2001-08-10', '2002-05-24', '5', 'Orihara Kouhei returns to his town after a long disappearance to fullfil the promises he made to several girls in his childhood. He suffered from memory loss, and carries a tragic past. An strange ambience surrounds the OVA...It''s almost like a dream, like memories from the past trying to come together in one piece but without being able to...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Marimo no Hana: Saikyou Butouha Shougakusei Densetsu', 'OVA', 1, 'Completed', '2012-03-18', NULL, '5', 'The story of the manga centers around Marimo Nogami, a usually quiet fourth-grade girl in elementary school. However, a certain incident leads to Marimo''s personal strength blossoming. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Amedama', 'Movie', 1, 'Completed', '2024-03-02', NULL, '5', 'The other kids at the park never ask Dong-Dong to play. That''s ok. He''s fine just playing marbles on his own. One day, he buys a bag of colorful candies instead of new marbles. The first time he pops one of them into his mouth, his old sofa starts talking to him! The two share an unexpected conversation before the sweet melts away. As it happens, the people, animals, and objects in Dong-Dong''s life have a lot to say.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hua Jianghu: Bu Liang Ren Qi - Jiu Youxuan Tian', 'ONA', 12, 'Completed', '2025-03-27', '2025-06-05', '5', 'The situation in Mobei appears calm on the surface, but in reality, undercurrents are surging. Queen Shuliduo is planning a grand assembly, while Bu Liang Shuai has led a group of Bu Liang Ren to Mobei to investigate its movements. During this time, the Four Great Corpse Ancestors, led by the surrendered minister, have also arrived in Mobei and opened an antique soup shop. Meanwhile, a mysterious murderer has thrown the people into panic. Various forces harbor their own intentions...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('IDOLiSH7: First Beat', 'Movie', 2, 'Completed', '2025-10-03', '2025-12-05', '5', 'Theatrical compilation of the first season of the anime IDOLiSH7.', 995, 'https://cdn.myanimelist.net/images/anime/1673/151081.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Majutsushi Kunon wa Mieteiru', 'TV', NULL, 'Upcoming', '2026-01-04', NULL, '5', 'Born blind, Kunon aims to be the first person to use water magic to create new eyes for himself. After five months of study, he has already surpassed his teacher, and continues to grow his talents. Not only can his magic help him sense color, but he can also use it to make handy items and even conjure a whole cat! Word of his skills and ingenuity soon reach the court and earn him a spot as disciple to the most powerful magician in the land. But is his ultimate goal even attainable?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tensei shitara Ken deshita 2', 'TV', NULL, 'Upcoming', '2026-10-01', NULL, '5', 'Second season of Tensei shitara Ken deshita.', 152, 'https://cdn.myanimelist.net/images/anime/1955/150906.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Minami no Shima no Chiisana Hikouki Birdy', 'TV', 105, 'Completed', '2005-12-26', '2007-04-02', '5', 'This is Bird Paradise Island, a small island in the southern sea.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimagure Orange☆Road: Summarized Edition', 'OVA', 1, 'Completed', '1988-03-14', NULL, '5', 'Special recap with the best scenes of Kimagure Orange☆Road.', 939, 'https://cdn.myanimelist.net/images/anime/1775/105357.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tokusou Kihei Dorvack OVA', 'OVA', 3, 'Completed', '1984-08-21', NULL, '5', 'Short stories recorded after the broadcast of the series.', 92, 'https://cdn.myanimelist.net/images/anime/1697/131945.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Megami-chan to Iku! Flag Osaka Office Goannai Tour', 'ONA', 1, 'Completed', '2022-05-20', NULL, '5', 'A promotional video for the Osaka office of flag Co.', 1163, 'https://cdn.myanimelist.net/images/anime/1124/131944.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('From North Field', 'ONA', 2, 'Completed', '2019-12-19', '2020-12-17', '5', 'The Hokuren Federation of Agricultural Cooperatives, Hokkaido''s top Japan Agricultural Cooperatives group, produced a PR anime titled from North Field which released on YouTube. The anime commemorates the organization''s 100th anniversary and tells the story of a young man who joins the group.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Skyers 5', 'TV', 25, 'Completed', '1971-10-14', '1972-03-03', '5', 'A science fiction action series about the future battles between a planetary police force and an international crime syndicate. The series is sometimes denoted with 26 episodes, in such a case episode 1 is a colored version of the original monochrome episode 1 of Skyers 5. No changes to dialogue and story were made. As such this episode will be accounted for in its original entry.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Obake no Q-Tarou: Tobidase! Bake Bake Daisakusen', 'Movie', 1, 'Completed', '1986-03-15', NULL, '5', 'Note: Screened as a double feature with Doraemon: Nobita to Tetsujin Heidan and with Pro Golfer Saru: Super Golf World e no Chousen!!.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Obake no Q-Tarou: Susume! 1/100 Daisakusen', 'Movie', 1, 'Completed', '1987-03-14', NULL, '5', 'Note: Screened as a double feature with Doraemon: Nobita to Ryuu no Kishi and with Pro Golfer Saru: Kouga Hikyou! Kage no Ninpou Golfer Sanjou!.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mon Cheri CoCo', 'TV', 13, 'Completed', '1972-08-27', '1972-11-26', '5', 'A young woman aims to become a famous fashion designer.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hyokkori Hyoutan Shima', 'Movie', 1, 'Completed', '1967-07-21', NULL, '5', 'A group of kids are stranded on a volcanic deserted island.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aoi Hane Mitsuketa! Sagashite Miyou Mijika na Tori-tachi', 'ONA', 6, 'Completed', '2021-04-26', '2021-06-14', '5', 'Hayato and Hina are close brothers and sisters who live in Tokyo. One day, he became interested in the beautiful blue feathers that he found on the road, and came up with the idea of ​​finding an owner. A mysterious crow appears there and travels together as a guide to guide the brother and sister to the owner of the feathers. Is it possible to find a brother or sister who searches for the owner of feathers through encounters with various birds?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sora Iro Hana Iro', 'Movie', 1, 'Completed', '2005-01-01', NULL, '5', 'A woman and a dog go on a spiritual journey and undergo a spiritual transformation while wandering in a forest side-by-side.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Norman the Snowman: Nagareboshi no Furu Yoru ni', 'Movie', 1, 'Completed', '2016-01-01', NULL, '5', 'Tomorrow is the night of the shooting stars! A new chapter of “Norman the Snowman” begins as Norman and the Boy embark on another venture to see the star-filled sky.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jian Wang 3: Xia Gan Yi Dan Shen Jianxin Zhi Chang Piao', 'ONA', 20, 'Completed', '2020-10-24', '2021-02-27', '5', 'The story shifts its setting from the grand martial arts world and imperial court to the bustling, ordinary streets of the city. Shen Jianxin, invited by the sect leader Li Wangsheng, travels to Chang''an to establish a branch of the Chunyang Palace, making a living by setting up a fortune-telling stall. During his time as a "Chang''an drifter," Shen Jianxin is no longer the renowned martial arts master with the protagonist''s halo. Due to some misconceptions about the world and insufficient judgment of his current situation, he encounters a series of strange and amusing events. Like many young people struggling in big cities, he experiences the bittersweet life of a "Chang''an drifter," yet remains optimistic, ambitious, and full of chivalrous spirit.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Happy☆Lesson', 'OVA', 5, 'Completed', '2001-07-19', '2003-05-23', '7', 'One guy. Five girls. One roof. It''s a recycled idea, but it never gets old. Happy Lesson is a kinetic take on an old genre.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiao Mo Tou Baolu La!', 'ONA', 13, 'Completed', '2022-01-15', '2022-04-02', '7', 'In an attempt for survival, Yu Renjie, the son of the demon lord, was ordered to enter Hero''s Academy which only recruits distinguished and upright disciples. The goal is to obtain a Hero''s Certificate which can bring legitimacy to the demon clan.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jungle Taitei', 'TV', 52, 'Completed', '1965-10-06', '1966-09-28', '7', 'Leo the white lion was born on an ocean liner that crashed on the shores of a bustling city, where he spent his childhood learning the language and customs of humans. But something was missing. In search of his family, home, and a place to truly belong, Leo traveled back to Africa and began his journey to become the King of the Jungle.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Touch: Miss Lonely Yesterday - Are kara, Kimi wa...', 'Special', 1, 'Completed', '1998-12-22', NULL, '7', 'Unsure of Tatsuya''s feelings, Minami ponders.', 351, 'https://cdn.myanimelist.net/images/anime/1300/96421.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tokyo Underground', 'TV', 26, 'Completed', '2002-04-02', '2002-09-24', '7', 'Under the capital city of Tokyo, Japan, there exists a large, vast, and unknown world known as Underground. There, people known as Elemental Users exist; people who have the ability to control the elements: Fire, Water, Lightning, Magnetism, Freeze, etc. Meet Rumina Asagi and his best friend Ginnosuke Isuzu, two average high school freshmen who reside in Tokyo. When they meet Gravity User, Chelsea Rorec, and the Miko of Life, Ruri Sarasa, their whole lives change into one big adventure.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Ball: Super Saiya-jin Zetsumetsu Keikaku', 'OVA', 1, 'Completed', '2010-11-11', NULL, '7', 'Remake of Dragon Ball Z: Plan to Destroy the Saiyajin. Extra on Dragonball Raging Blast 2 game on X360/PS3.', 1030, 'https://cdn.myanimelist.net/images/anime/1131/122382.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lupin III: Napoleon no Jisho wo Ubae', 'Special', 1, 'Completed', '1991-08-09', NULL, '7', 'Lupin has a lively time of it this time in a classic car race from Madrid to Paris. The race prize is Napoleon''s dictionary, which contains the key to the Treasure of the Empire, something that just about everybody seems to be after. Lupin and his buddies take off after the prize, pursued not only by the perennial Inspector, but also by an army of secret agents from around the world. Classic cars and state-of-the-art weapons heighten the speed and thrills of this adventure.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Entotsu Machi no Poupelle', 'Movie', 1, 'Completed', '2020-12-25', NULL, '7', 'On Halloween night, a young chimney sweep named Lubicchi befriends a man magically conjured out of garbage. Giving him the name Poupelle, Lubicchi is able to recreate a bond he lost when his father died to the tyranny of the Inquisitors—an oppressive force that aims to suppress outside knowledge and the town''s true history. But their newfound relationship soon captures a lot of attention, and the threat of the Inquisitors and even the criticism of a few townspeople will test the duo''s friendship. In spite of this, Poupelle has struck a particular chord with Lubicchi, and the two conspire to bring the truth to the surface and clear the chimney smoke that clouds the town''s skies.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Emblem Take 2', 'OVA', 2, 'Completed', '1993-10-25', '1995-11-21', '7', 'Shinjuku, 1983. A member of the Kaeda Yakuza gang, Akutsu Jouji, has lost in a brawl with a university cheering squad, and begs for forgiveness through bitter tears. Since then, nothing has gone well in Jouji''s life, until 10 years later in 1993, his friend was ordered to kill him, and as he ran away he killed himself, ending his miserable life.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Skull Man', 'TV', 13, 'Completed', '2007-04-29', '2007-07-22', '7', 'Otomo City: where freedom and justice have atrophied to the bone; where conspiracy rules the day and death stalks the night... Death in the form of the Skull Man, a literal Grim Reaper whose skeletal grin presages grisly mayhem and murder, even to the monstrous mutants that haunt the city''s underworlds! 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ys: Tenkuu no Shinden - Adol Christine no Bouken', 'OVA', 4, 'Completed', '1992-12-16', '1993-07-21', '7', 'Now that Adol Christen has saved the land of Esteria from the evil priest Dark Fact, Adol and the two priestesses travel to the floating land of Ys, where evil has an even greater influence on the people and no one has hope. The future of Ys falls to Adol, heir to the powers of the priests and the only one who can show the people of Ys the truth about their world. But, as Adol''s power grows, he may be the one who will save Ys—or destroy it.', 1033, 'https://cdn.myanimelist.net/images/anime/1984/110828.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Masamune-kun no Revenge: Uchi no Mama ni Kagitte/Tsunade Shima, Futatabi./12-Ji wo Sugita Cinderella', 'OVA', 1, 'Completed', '2018-07-27', NULL, '7', 'Uchi no Mama ni Kagitte (Of Course, My Mom...) 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimetsu no Yaiba Movie: Mugenjou-hen Manner Eizou', 'Movie', 1, 'Completed', '2025-07-20', NULL, '7', 'A short animation about manners screened before the movie, featuring Uzui Tengen and his wives Hinatsuru, Makio, and Suma.', 1192, 'https://cdn.myanimelist.net/images/anime/1858/151344.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuromi''s Pretty Journey: Hacha Mecha! Multiverse Daidasshutsu!', 'ONA', 19, 'Completed', '2024-10-31', '2024-12-12', '7', 'Kuromi''s new journey into multiverse and met Niko.', 933, 'https://cdn.myanimelist.net/images/anime/1586/146238.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bai Fa Shen La', 'ONA', 8, 'Completed', '2024-07-11', '2024-08-22', '7', 'Shen La, a special investigator of the "Poll Bureau" of the mysterious incident management agency, was seriously injured in the execution of his mission. When he was about to die, he accepted the inheritance of Wu Rendi, the director of the Sixth Office - a "seed" containing mysterious power. After regaining consciousness, Wu Rendi''s senior brother Guangren accepted him as his disciple. In order to find the fragments of the Tianli Diagram, Shen La, after going through the Tianshan Wolf Tomb, energy backlash, foundation conspiracy and other incidents, was finally recognized by Wu Rendi and received the ancient artifact-the Twin Swords of Crime and Punishment given by him. At the same time, the problem of the insider in the polling bureau became more complicated and confusing, and Shen La and her partner Sun Desheng went into battle again.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tianting Ban Zhuan Xia', 'ONA', 18, 'Completed', '2024-06-12', '2024-09-25', '7', 'Li Ji, a cold and arrogant genius student in the Department of Architecture, was kidnapped by a creature from another world, Dark Qilin, and taken to a secret realm called Po Nian Space. The secret realm contained the ruins of an ancient heaven. Dark Qilin told him that he had to pass through if he wanted to go back. The test of heaven, and this test is to rebuild heaven...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Babanbabanban Vampire', 'TV', 12, 'Completed', '2025-01-11', '2025-03-29', '7', 'A decade ago, 450-year-old vampire Ranmaru Mori was saved from the brink of death by Rihito Tatsuno, a young and innocent boy. Ever since then, Ranmaru has been working at the Tatsuno family''s bathhouse with a secret: he wants a taste of Rihito''s virgin blood as soon as he turns 18. However, his plan is threatened when Rihito falls in love with a girl on his first day of high school.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ninja Kamui', 'TV', 13, 'Completed', '2024-02-11', '2024-05-05', '7', 'Seemingly an average man, Joe Logan leads a peaceful life in the countryside with his wife and child. However, the Logan family have actually assumed false identities to escape from Joe''s past as a fearsome ninja assassin. Despite a string of high-profile murders of his former peers, Joe is sure that his new life is secure—but his tranquil bliss is soon shattered when his family is slaughtered by members of his former clan.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shenlong Xing Zhu', 'ONA', 48, 'Completed', '2024-01-20', '2024-06-22', '7', 'Gu Zhengfeng was originally the divine dragon that guarded the Dragon Star. He was seriously injured in an ancient battle with alien enemies and fell into a long sleep. He wakes up and finds that the Dragon Star has changed, and is now called evil. In order to investigate and retrieve the treasure hidden in the Dragon King Academy, he changed into a human form and entered as a tutor in the Dragon Slaying Department.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saikyou Donbei x Hanma Baki: Saikyou no Dongitsune Genrutsutsu', 'Special', 1, 'Completed', '2022-11-21', NULL, '7', 'Nissin has teamed up with Baki Hanma for a new anime commercial that promotes the brand''s Saikyou Donbei (The Strongest Donbei) cup noodles, which have thicker noodles than the regular Donbei products among other features.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsuyokute New Saga', 'TV', 12, 'Completed', '2025-07-03', '2025-09-18', '7', 'Humanity and demonkind have been on bad terms for millennia, resulting in the continent of Leunders being split in two. Although the situation has stabilized between the races, the fragile peace breaks when the new demon king launches a fierce all-out attack. With all of the non-demon nations falling to the violence in under a year, humanity''s hope rests in a special squad, led by swordsman Kyle Leonard, that must assassinate the demon king in order to bring an end to the war.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Omoi, Omoware, Furi, Furare', 'Movie', 1, 'Completed', '2020-09-18', NULL, '7', 'Yuna Ichihara''s spring break is far from pleasant, especially after she sends off her best friend Sacchan, who is moving away. But while heading home, the timid girl brightens up when she encounters a boy who looks exactly like her first love—a prince from a shoujo manga. Subsequently, she finds herself in a peculiar situation with the mature Akari Yamamoto, a new neighbor who immediately befriends her.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hatsukoi Limited.', 'TV', 12, 'Completed', '2009-04-12', '2009-06-28', '7', 'Ayumi Arihara believes that being loved is the ultimate key to happiness—which is why her greatest wish is to have a boy confess to her. A series of unfortunate events leads to her ideal dream coming true, albeit in a nightmarish way: the towering and terrifying Misao Zaitsu confesses his love to Ayumi through a letter.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Motto To LOVE-Ru', 'TV', 12, 'Completed', '2010-10-06', '2010-12-22', '7', 'Rito Yuuki never gets a break—he''s always finding himself in lewd accidents with girls around him. Although his heart still yearns for Haruna, his childhood love, Rito can''t help but question his feelings for Lala, the alien princess who appeared in front of him and declared she would marry him. But now, it''s not just Lala he has to deal with: her younger twin sisters, Momo and Nana, have also traveled to Earth, wanting to meet their older sister''s fiancé, and just as luck would have it, they end up staying at Rito''s home.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece Egghead Arc Recap', 'Special', 1, 'Completed', '2025-04-05', NULL, '7', 'A special edited version which looks back on the episodes 1089-1122 that were broadcast from January to October 2024. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dead Dead Demons Dededede Destruction (ONA) Episode 0', 'ONA', 1, 'Completed', '2024-05-24', NULL, '7', 'Episode 0 of Dead Dead Demons Dededede Destruction (ONA).', 701, 'https://cdn.myanimelist.net/images/anime/1514/143260.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('BanG Dream! It''s MyGO!!!!! Movie', 'Movie', 2, 'Completed', '2024-09-27', '2024-11-08', '7', 'Theatrical compilation of BanG Dream! It''s MyGO!!!!!.', 756, 'https://cdn.myanimelist.net/images/anime/1055/145734.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cong Hong Yue Kaishi', 'ONA', 16, 'Completed', '2023-12-25', '2024-02-05', '7', 'The story tells the story of a blood-red moon suddenly appearing in the sky, which is known as the red moon event in history. The remaining survivors had to hide in the city protected by high walls. Among the survivors, some people also suffered from mental mutations. Among them, those who could not control their own mental mutations would emit mental plague and radiation. It contaminates the normal people around it and poses a great threat to the surviving humans. In order to solve the source of the pollution, High Wall City established a special pollution cleanup department, recruiting people who can control spiritual energy, and our protagonist Lu Xin is applying for the most dangerous cleanup department!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyuujitsu no Warumono-san', 'TV', 12, 'Completed', '2024-01-08', '2024-03-25', '7', 'As a member of a malevolent organization, the General is tasked with invading Earth and wiping out humanity. Even an extraterrestrial being like him, however, needs a chance to rest.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Made in Abyss: Retsujitsu no Ougonkyou - Papa to Issho', 'Special', 1, 'Completed', '2022-10-26', NULL, '7', 'Bonus mini anime included in the first Made in Abyss: Retsujitsu no Ougonkyou Blu-ray/DVD BOX volume.', 480, 'https://cdn.myanimelist.net/images/anime/1874/125099.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doupo Cangqiong', 'ONA', 12, 'Completed', '2017-01-07', '2017-04-01', '7', 'In a land where no magic is present. A land where the strong make the rules and weak have to obey. A land filled with alluring treasures and beauty, yet also filled with unforeseen danger. Three years ago, Xiao Yan, who had shown talents none had seen in decades, suddenly lost everything. His powers, his reputation, and his promise to his mother. What sorcery has caused him to lose all of his powers? And why has his fiancee suddenly shown up?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Soukyuu no Fafner: Dead Aggressor - The Beyond', 'Movie', 3, 'Completed', '2019-05-17', NULL, '7', '', 704, 'https://cdn.myanimelist.net/images/anime/1512/94632.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaitou Joker 3rd Season', 'TV', 13, 'Completed', '2016-04-04', '2016-06-27', '7', 'Third season in the Kaitou Joker anime series.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hana to Alice: Satsujin Jiken', 'Movie', 1, 'Completed', '2015-02-20', NULL, '7', 'After transferring to Ishinomori Middle School, Tetsuko "Alice" Arisugawa overhears her classmates discussing a strange rumor. The previous occupant of her seat, a nondescript "Judas," is missing and presumed murdered—poisoned by one of his four wives. Amidst dealing with her mother''s undesired meddling in her affairs and warding off her classmates'' bullying, the troubled Alice starts to investigate the mystery surrounding Judas'' disappearance.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gegege no Kitarou (2018)', 'TV', 97, 'Completed', '2018-04-01', '2020-03-29', '7', 'Nearly twenty years into the 21st century, people have forgotten the existence of youkai. When a number of unexplainable phenomena plague adults of the human world with confusion and chaos, thirteen-year-old Mana writes a letter to the Youkai Post in search of answers, only to be greeted by Gegege no Kitarou...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wan Jie Xian Zong 2nd Season', 'ONA', 40, 'Completed', '2019-04-25', '2019-09-09', '7', '', 752, 'https://cdn.myanimelist.net/images/anime/1981/105370.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hetalia Axis Powers', 'ONA', 52, 'Completed', '2009-01-24', '2010-03-05', '7', 'In a tumultuous era of World Wars and general uncertainty for the future, Germany did not expect that his only constant allies would be North Italy and Japan. Despite being a descendant of the once-powerful Ancient Rome, North Italy is weak, useless, and overly in love with pasta. In contrast, Japan is reliable and pragmatic, but has strange obsessions that would bewilder anyone. Believing he drew the short end of the straw, Germany must think of a way to make this unlikely alliance work.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shikabane Hime: Kuro', 'TV', 12, 'Completed', '2009-01-01', '2009-03-26', '7', 'A direct continuation of Shikabane Hime: Aka, taking place six months after Tagami Keisei''s death at the hands of the Shichisei (Seven Stars), a group of elite Shikabane who act on more than just regrets. As per Keisei''s dying wish, Kagami Ouri formed a temporary contract with Makina to save her from degenerating into a Shikabane. Since then, Ouri''s been training to become a proper monk so that he can remain contracted to Makina and help her fight against the Shichisei -- the ones who originally killed Makina, the entire Hoshimura family, and now Keisei. However, the traitorous monk Shishidou Akasha has sided with the Shichisei in an attempt to destroy all Shikabane Hime and the entire monk organization that uses them -- Kougon Sect.', 321, 'https://cdn.myanimelist.net/images/anime/1125/105989.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam Thunderbolt: Bandit Flower', 'Movie', 1, 'Completed', '2017-11-18', NULL, '7', 'Compilation film for Mobile Suit Gundam Thunderbolt 2nd Season.', 974, 'https://cdn.myanimelist.net/images/anime/13/87511.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Love Live! School Idol Festival All Stars', 'ONA', 1, 'Completed', '2018-09-19', NULL, '7', 'Special short to promote the release of the Love Live! School Idol Festival All Stars game.', 974, 'https://cdn.myanimelist.net/images/anime/1943/102566.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Noblesse: Pamyeol-ui Sijak', 'OVA', 1, 'Completed', '2015-12-04', NULL, '7', 'Humans live their lives driven by ambition and greed, prepared to kill their own kind with no hesitation. Since the beginning of humanity, wars have raged on throughout the human world, with the other races watching on.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Planetarian: Snow Globe', 'OVA', 1, 'Completed', '2021-01-20', NULL, '7', 'The new OVA will feature the prequel short story "Snow Globe," which debuted as part of a light novel volume that bundled with a limited-edition version of the original PC game.', 639, 'https://cdn.myanimelist.net/images/anime/1169/113365.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('PriPara Movie: Mi~nna no Akogare♪ Let''s Go☆Prix Paris', 'Movie', 1, 'Completed', '2016-03-12', NULL, '7', 'Falulu is far away in the heart of the PriPara world in Puransu. The sparkle is disappearing from the idol sacred ground PriPara, and Falulu sends an SOS message to Laala and her friends. If the sparkle doesn''t return, the PriPara world itself will disappear. Laala and her friends try to help Falulu, and they work together to save the PriPara world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Terra e...', 'Movie', 1, 'Completed', '1980-04-26', NULL, '6', 'In the five hundred years since Earth''s environment was destroyed and the planet came to be known as Terra, humans have created a society in space that is entirely logical. Supercomputers control the government, babies are grown in artificial wombs and assigned parents randomly, and at age 14, children take an "Adulthood Exam." Humanity''s greatest enemy is the "Mu"—humans who have developed into espers.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Spirit of Wonder: China-san no Yuuutsu', 'OVA', 1, 'Completed', '1992-06-03', NULL, '6', 'Tenkai is a successful bar and restaurant located on a small European island run by an immigrant known affectionately as "Miss China." In addition to running this well-loved establishment, she rents the upstairs unit to Jim, a young inventor who works alongside Mr. Breckenridge in the makeshift lab they have constructed there. The struggling pair are convinced that their scientific innovations will revolutionize the world in spite of the scorn they receive from the scientific community. However, as Miss China''s patience wears thin due to their consistently overdue rent payments, Mr. Breckenridge and Jim must prove their work has value in order to avoid eviction.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ganbare Douki-chan: Kakusa Shakai ni Nayamu Kaisha no Douki', 'Special', 1, 'Completed', '2021-12-24', NULL, '6', 'Unaired episode 13 included with the Blu-ray release of Ganbare Douki-chan.', 95, 'https://cdn.myanimelist.net/images/anime/1244/117818.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sengoku Collection', 'TV', 26, 'Completed', '2012-04-06', '2012-09-28', '6', 'Sengoku Collection revolves around many samurai who are accidentally removed from a parallel universe inhabited by well-known historic characters. Unlike the historical war period known to us, all inhabitants in this unique world look like high school girls. Coming from the medieval era and finding themselves totally amazed by everything they encounter in modern day Tokyo, the girls become best friends through their adventures. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Slow Step', 'OVA', 5, 'Completed', '1991-06-01', '1991-11-01', '6', 'Based on the Adachi manga of the same name. The story revolves around a romantic triangle formed by the girl Minatsu Nakazato, a young student and softball player; Shu Akiba, a schoolmate; and Naoto Kadomatsu, an up-and-coming boxer. In reality the three-way relationship is more like three-and-a-half, considering that Naoto is in love with Maria... actually Minatsu herself, who''d once disguised herself to escape some evildoers.', 674, 'https://cdn.myanimelist.net/images/anime/1/2341.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sojunghan Nal-ui Kkum', 'Movie', 1, 'Completed', '2011-06-16', NULL, '6', 'Not wanting to lose, Yi-rang orchestrates a collapse in the middle of a relay race even though she''s on the verge of giving up her dream of becoming an athlete. At the same time, Soo-min transfers in from Seoul and Cheol-soo, who dreams of becoming a scientist, come into her life. They are all immature but they are in the midst of youthful aspiration.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('R-15', 'TV', 12, 'Completed', '2011-07-10', '2011-09-25', '6', 'R-15 is about a boy, Taketo Akutagawa, who attends a school for geniuses: Inspiration Academy Private High School. Taketo is a genius novelist and writes erotica. Despite negative perceptions many people have of him, he aims to be at the top of his class and be recognized as the world''s greatest writer.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cutie Honey', 'TV', 25, 'Completed', '1973-10-13', '1974-03-30', '6', 'One day, Honey Kisaragi''s a trendy, class-cutting Catholic schoolgirl. The next, her father''s been murdered by demonic divas from a dastardly organization called Panther Claw. When his dying message reveals that she''s an android, Honey uses the transformative power of the Atmospheric Element Solidifier - the very thing Panther Claw wanted to steal - to seek revenge against the shadowy clan. Can Honey fight her way up Panther Claw''s ranks to defeat its leader, the sinister Sister Jill while managing to escape the watchful eyes of Miss Histler, her school''s headmistress?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ultra B: Black Hole kara no Dokusaisha BB!!', 'Movie', 1, 'Completed', '1988-03-12', NULL, '6', 'No synopsis has been added for this series yet.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kiniro no Corda: Blue♪Sky', 'TV', 12, 'Completed', '2014-04-06', '2014-06-22', '6', 'Soon after transferring to Seisou Gakuin, Kanade finds the orchestra club in the middle of preparing for the National concur. Teaming up with the other members, she will improve her skills, meet new rivals and create memories for what will become an unforgettable summer...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('L/R: Licensed by Royal', 'TV', 12, 'Completed', '2003-01-08', '2003-03-26', '6', 'Jack Hofner and Rowe Rikenbacker are Cloud 7''s L/R. Their job is to protect the Royal family of Ishtar, their treasures, and their reputation. Jack &amp; Rowe face one of the toughest missions of their career when they are assigned to protect Noelle, a candidate for the 15 Year Princesse contest. It starts out simple, but soon all of Cloud 7 are involved in a web of intrigue that includes bombings, corruption and murder. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ys', 'OVA', 7, 'Completed', '1989-11-21', '1991-09-05', '6', 'Mythical beasts lay siege on the people of Esteria, who have raised an army to fight back. The beasts are relentless and seemingly have no end to their numbers, while the population of defenders dwindle in every skirmish. Even in the town of Minea, where the people are safely nestled behind castle walls, the constant attacks have left them hopeless. It is then that a prophecy is made, proclaiming the arrival of a brave young soul that could be the one who will bring their salvation.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Crying Freeman', 'OVA', 6, 'Completed', '1988-11-25', '1994-02-25', '6', 'Yo Hinomura was an ordinary Japanese potter when a run-in with a Chinese mafia changed his life forever. Now an assassin for the 108 Dragons, Yo is the perfect killing machine. As a sign for remorse over his victims, he sheds tears after eliminating his targets. Because of this, he is infamously known by the Dragons and every crime syndicate in the world as "Crying Freeman."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aldnoah.Zero: Ame no Danshou - The Penultimate Truth', 'Special', 1, 'Completed', '2025-03-26', NULL, '6', 'Episode 24.5 released with the Blu-ray Box.', 14, 'https://cdn.myanimelist.net/images/anime/1566/145506.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Asatir 2: Mirai no Mukashi Banashi', 'TV', 13, 'Completed', '2024-11-03', '2025-02-02', '6', 'Sequel to Asatir: Mirai no Mukashi Banashi.', 1030, 'https://cdn.myanimelist.net/images/anime/1717/144671.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ima wa Shourai ni Hairimasu ka.', 'Special', 1, 'Completed', '2024-02-20', NULL, '6', 'In his second year at university, a young boy, Hayato, thinks about his future.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Da Yuzhou Shidai', 'ONA', 12, 'Completed', '2024-01-22', '2024-04-01', '6', '', 295, 'https://cdn.myanimelist.net/images/anime/1661/150248.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Don Chuck Monogatari', 'TV', 26, 'Completed', '1975-04-05', '1975-09-27', '6', 'Young beaver Chuck''s adventure with his little friends. When thy are in trouble, Chuck often asks his father to help them out.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchuujin Tanaka Tarou', 'TV', 24, 'Completed', '2000-04-17', '2001-03-26', '6', 'Takashi Horimachi is an ordinary curious fifth grader attending "Anytown" Elementary School. One day, a very unusual transfer student named Tarou Tanaka joins Takashi''s class. Takashi and his classmates have never encountered anyone quite like Taro before. He is blue, has huge glowing eyes, pointy ears, a smooth bald head and one horn. Takashi, obsessed with trying to figure out this strange new visitor, attempts to track Tarou''s every move; and in the process he continuously falls victim to Tarou''s hilarious assortment of cosmic jokes and traps.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Masou Kishin Cybuster', 'TV', 26, 'Completed', '1999-05-03', '1999-10-25', '6', 'In an enviromentally wrecked future Tokyo, a young man named Ken Ando joins an organization called DC. Little does he realize that his fate and that of Earth will be linked to a mysterious mecha from another world. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Moldiver', 'OVA', 6, 'Completed', '1993-02-25', '1993-11-25', '6', 'Hiroshi Ozora invents the Mol Unit, a device that makes its user invincible. His plans of becoming a super hero are short lived however when his sister, Mirai, accidently modifies the suit configuration. Now she is forced to save Tokyo by herself from the evil Machinegal and his gang of all-female androids. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eiyuu Kyoushitsu', 'TV', 12, 'Completed', '2023-07-09', '2023-09-24', '6', 'After defeating the Demon Lord, the great hero Blade finds himself on the brink of death. Though he miraculously survives, he loses a significant portion of his strength. Being stripped of his immense power frees Blade from the obligation of being humanity''s savior. He chooses to spend his newfound freetime embarking on a new quest, making friends.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Himitsu no Akko-chan (Movie)', 'Movie', 1, 'Completed', '1989-03-13', NULL, '6', 'Taisho''s father plans to construct an apartment building on a vacant land he owns behind his own house. The spot is a playing field for the kids in the neighborhood who will fight to keep it as it is.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Inga Nikki', 'ONA', 10, 'Completed', '2011-10-05', '2011-12-22', '6', 'Parody web specials.', 138, 'https://cdn.myanimelist.net/images/anime/1713/141222.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Final Fantasy', 'OVA', 4, 'Completed', '1994-03-21', '1994-07-21', '6', 'Two hundred years have passed since the hero Bartz and his companions saved the inhabitants of Planet R—a world where crystals control the natural elements—from the threat of Exdeath. However, agents of the wizard Ra Devil steal the crystals of Earth, Fire, and Water. With three of the four crystals in his possession, Ra Devil seeks to claim the Wind Crystal, the final piece he needs to summon the destructive god Deathgyunos. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Kaitei Gunkan', 'OVA', 2, 'Completed', '1995-12-21', '1996-08-01', '6', 'Moments after an atomic bomb falls over Hiroshima, a secret Japanese submarine sails into battle against its American counterpart, and both are lost to history. Some fifty years later, a special UN task force sent to investigate unusual phenomena in Antarctica is threatened by a mysterious black cylinder.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kerokko Demetan', 'TV', 39, 'Completed', '1973-01-02', '1973-09-25', '6', 'Demetan comes from such a poor family that he cannot even go to school in his woodland pond community. However, he has a friend named Ranatan, the lovely, gentle frog girl who is the daughter of the pond''s rich ruler. Naturally her father is quite displeased by this relationship and he seeks to break it up. Nevertheless the young frogs continue with courage and confidence, not only to live their own lives but to guide the heartless leopard frog to a sense of justice and generosity. Gradually the pond community responds to their sincerity and joins them in a march toward a bright future. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Precure kara Minna e no Ouen Movie', 'ONA', 1, 'Completed', '2011-05-20', NULL, '6', 'Support video for the victims and sufferers of the 2011 Japanese earthquake and tsunami featuring all the Precure girls.', 1030, 'https://cdn.myanimelist.net/images/anime/10/29572.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yumeria', 'TV', 12, 'Completed', '2004-01-09', '2004-03-26', '6', 'On his 16th birthday, Tomokazu Mikuri had a realistic dream where he sees a girl battling a giant floating monstrosity. When he wakes up, he is surprised that the girl is actually sleeping next to him... Whenever he sleeps from now on, he ends up back at the dream world, and more and more people that he knows keep showing up there too. He finds out from a mysterious masked woman in the dream world named Silk that they are fighting against one named Faydoom, and he is the one who provides the powers to those girls so that they can fight these monsters. And so it goes...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hiatari Ryoukou! Yume no Naka ni Kimi ga Ita', 'Movie', 1, 'Completed', '1988-10-01', NULL, '6', 'The movie starts out with Katsuhiko going to the US, with Kasumi and Yusaku seeing him off at Narita.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Youma', 'OVA', 2, 'Completed', '1989-05-01', '1989-06-01', '6', 'A terrible war has ravaged the land, and now, fueled by the blood of numerous fallen warriors the Yoma, demons from hell, emerge once more. A skilled ninja seeks to end the bloodshed these demons inflict upon humanity, but to do this he must fight against his undead former best friend and fellow ninja who was killed in battle and has been resurrected to serve the Yoma. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sore Ike! Anpanman: Soratobu Ehon to Glass no Kutsu', 'Movie', 1, 'Completed', '1996-07-13', NULL, '6', 'Eight Anpanman short movie.', 990, 'https://cdn.myanimelist.net/images/anime/11/28053.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Houma Hunter Lime', 'OVA', 3, 'Completed', '1996-10-25', '1997-03-07', '6', 'For centuries, the magic and human worlds have been at peace with each other, though physically seperated by a magical gate. But when the powerful magic spheres are stolen and fall to the Earth below, the king of magic sends Boss, a fighter; Lime, a master transformer; and Poogie, a master morpher to retrieve them. With not much time, the trio must retrieve the spheres which, when in contact with the human world, suck up the negative emotions of household objects and become BEMs, Bug Eyed Monsters!', 92, 'https://cdn.myanimelist.net/images/anime/1936/93963.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaze wo Nuke!', 'OVA', 1, 'Completed', '1988-12-16', NULL, '6', 'In the world of motocross, 16-year-old Satoshi Ichimonji fights his way from the novice grade up to Junior Cross championship.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('SI-VIS: The Sound of Heroes', 'TV', 24, 'Airing', '2025-10-05', NULL, '6', 'SI-VIS is a co-ed music group, led by Yosuke, shaking up the global music scene with their unmatched vocals and performances. However, they are actually heroes in disguise, battling against mysterious forces threatening the world. They convert audience energy at live performances into combat power. Luckily, the battles appear to be ordinary concerts to the public, keeping their identity a secret.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon Masters EX', 'Special', NULL, 'Airing', '2019-12-05', NULL, '6', 'Animated videos for Pokemon Masters EX.', 622, 'https://cdn.myanimelist.net/images/anime/1885/151870.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Weaving', 'ONA', 1, 'Completed', '2017-08-15', NULL, '6', 'A bejeweled spider weaves a bejeweled web.', 1160, 'https://cdn.myanimelist.net/images/anime/2/88393.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Naki no Ryuu: Hiryuu no Shou (1991)', 'OVA', 1, 'Completed', '1991-08-23', NULL, '6', 'An OVA released in 1991. Unlike the previous OVA series, this episode was produced separately by Toshiba.', 321, 'https://cdn.myanimelist.net/images/anime/11/88606.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('It''s My Life', 'OVA', 1, 'Completed', '2019-01-30', NULL, '6', 'Based on a fantasy manga by Narita Imomushi.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Terrace House x Craft Boss', 'Special', 1, 'Completed', '2019-08-30', NULL, '6', 'A Suntory advertisement featuring popular beverages (from the Craft Boss brand) as anime characters in their twenties. The ad is a collaboration with the latest season of the Terrace House reality TV show series, which follows the lives of three men and three women who live in the same house and get to know each each other. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The Peak', 'ONA', 1, 'Completed', '2019-09-26', NULL, '6', 'THE PEAK is Marza Animation Planet''s second short film created entirely using the Unity game engine.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lord of Vermilion III Special Anime Movie', 'Special', 1, 'Completed', '2015-08-22', NULL, '6', 'A short special that features characters from the arcade game Lord of Vermilion III engaged in battle.', 787, 'https://cdn.myanimelist.net/images/anime/8/75895.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Himitsukessha Taka no Tsume The Movie 4: Kaspersky wo Motsu Otoko', 'OVA', 1, 'Completed', '2010-06-10', NULL, '6', 'Fourth film in the Secret Society Eagle Talon film series. Initially released directly to DVD, but was later screened at TOHO Cinemas Roppongi Hills.', 214, 'https://cdn.myanimelist.net/images/anime/2/74060.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Katarina to Manabou', 'ONA', 9, 'Completed', '2020-05-10', '2020-07-07', '6', 'Short specials posted on the official Twitter account focused on main cast of Otome Game no Hametsu Flag shika Nai Akuyaku Reijou ni Tensei shiteshimatta...', 39, 'https://cdn.myanimelist.net/images/anime/1229/107958.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bean Bandit', 'OVA', 1, 'Completed', '2021-01-19', NULL, '5', 'A legendary courier-for-hire also known as "Roadbuster," Bean Bandit can deliver anything and everything anywhere, but only at a high price. He won''t tolerate anyone standing in his way or betraying him, and when faced with such a challenge he removes them with his strength and muscles.', 200, 'https://cdn.myanimelist.net/images/anime/1651/93298.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ojisan to Sakana', 'Special', 1, 'Completed', '2019-05-21', NULL, '5', 'Commercial animated by Takashi Taniguchi for Dear-Natura Gold EPA &amp; DHA (Eicosapentaenoic Acid &amp; Docosahexaenoic Acid) fish oil supplements.', 513, 'https://cdn.myanimelist.net/images/anime/1782/107640.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hawk no Onayami Soudanshitsu', 'ONA', 39, 'Completed', '2019-08-01', '2019-10-09', '5', 'The series of shorts featuring Hawk posted on official Twitter account.', 879, 'https://cdn.myanimelist.net/images/anime/1622/111168.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('PiKA PiKA', 'Movie', 1, 'Completed', '2006-01-01', NULL, '5', 'Abstract short film, the first "lightning doodle" film by Tochka.', 1029, 'https://cdn.myanimelist.net/images/anime/7/69169.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eien no Hou', 'Movie', 1, 'Completed', '2006-09-30', NULL, '5', 'Ryuta and his friends from the science club visit a museum exhibit on Thomas Edison and it''s there they learn about one of his proposed inventions called the "spirit phone" which would enable communication with the deceased. Later that day, they bump into a shaman who claims she has a message from Edison. In an instant Ryuta is given the necessary knowledge he needs to construct the device and decides to go for it, so beginning a spiritual adventure.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zoku Natsume Yuujinchou: 3D Nyanko-sensei Gekijou', 'Special', 5, 'Completed', '2009-04-22', '2009-08-26', '5', 'Short 3D Nyanko-sensei animations bundled on BD/DVD''s of the Zoku Natsume Yuujinchou series.', 143, 'https://cdn.myanimelist.net/images/anime/9/53183.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Houkago no Shokuinshitsu', 'OVA', 2, 'Completed', '1994-04-01', '1995-01-27', '5', 'Fresh out of college, Kawase Mitsuro is eager to start his new job as a middle school art teacher. Upon his arrival, he quickly blends in with the masses of girls ogling the toned body of senior teacher Kazama Toshiaki. Kazama ignores the schoolgirls. However, Kazama realizes something is different about Kawase and decides to ask the latter out to dinner. Unconvinced his advances are serious, Kawase goes along with Kazama halfheartedly. When Kazama''s true feelings are revealed, will Kawase embrace his potential lover or give in to the expectations of society?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Choujin Gakuen Gowcaizer: The Voltage Fighters', 'OVA', 3, 'Completed', '1996-09-27', '1997-01-31', '5', 'It is the dawn of the 21st century. The cataclysmic earthquake which reduced half of Tokyo to a broken landscape of twisted steel and shattered stone was only the first sign of the impending apocalypse. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Soukihei MD Geist 2: Death Force', 'OVA', 1, 'Completed', '1996-03-01', NULL, '5', 'After unleashing the Death Force machines all over the planet Jerra, Geist has kept himself busy by dismantling them one by one. But now he faces a formidable opponent in the form of Krauser, another M.D.S. (Most Dangerous Soldier) who has aligned himself as the only savior of mankind.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fujinkoron-senpai', 'Special', 1, 'Completed', '2016-05-23', NULL, '5', 'Short promotional video for the Fujinkoron magazine, starring employees of the editorial department.', 362, 'https://cdn.myanimelist.net/images/anime/9/81541.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tenka Hyakken: Meiji-kan e Youkoso!', 'TV', 12, 'Completed', '2019-10-13', '2019-12-29', '5', 'The Tenka Hyakken franchise centers around the "Mitsurugi," maidens who are physical incarnations of ancient swords. They have pledged to live peaceful lives after the era of warfare, but are now returning to battle to fight a new foe that has arisen during an alternate version of the Meiji Era, three hundred years after the Battle of Sekigahara. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Douzhan Tianxia', 'ONA', 48, 'Completed', '2025-01-21', '2025-06-24', '5', 'The mysterious young man Dafeng rescued Li Huamei, who was seriously ill after being plotted against. Dafeng wanted to go to Kyoto to find his senior sister and happened to be on the same road with Li Huamei. On the way, Li Huamei was shocked to find that her senior sister was the Queen Qin Zhao, and the Queen repeatedly sent assassins to kill her. In order to find out the reason, Dafeng and Li Huamei entrusted their lives to each other and fought against the enemy together. Disputes arose in the rivers and lakes, and the court struggles became more intense. The two were unknowingly involved in a treacherous conspiracy, and Dafeng was the key to solving all the mysteries...', 752, 'https://cdn.myanimelist.net/images/anime/1190/150133.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Francois CMs', 'Special', 10, 'Completed', '2005-01-22', '2008-01-01', '5', 'Animated commercials for the Japanese bread and confectionary business Francois.', 1050, 'https://cdn.myanimelist.net/images/anime/1258/147545.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cassis to Arles no Monogatari', 'Special', 20, 'Completed', '2007-01-01', '2017-04-28', '5', 'Cassis is the only daughter of a bakery in the small town of Fran. Her daily routine is to deliver freshly baked bread to the people of the town every morning. One day, a blonde young man named Arles comes to Cassis''s shop. She is gradually drawn to him for his refreshing and gentle gaze. However, there is a reason why the young man has come to this town.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiang Huo Er Sheng', 'ONA', 6, 'Completed', '2025-01-17', '2025-02-14', '5', 'It mainly tells the moving story of Han Yan, the head of Feiliu Fire Station, and a group of young people including Jiang Mingsheng, Ning Wei, and Fan Haoyuan, who burn their youth and blood and fight on the front line of firefighting. Not only are there high-energy moments of fire rescue, but also the fire brigade that is extremely brave in wartime and extremely cute in leisure time, as well as fascinating suspense cases and hard-core firefighting knowledge! Show a different kind of passionate youth.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fushigi no Kuni de Alice to: Dive in Wonderland', 'Movie', 1, 'Completed', '2025-08-29', NULL, '5', 'Rise Azumino is a university student who has lost in her life. One day, guided by an invitation letter left behind by her late grandmother, she enters "Wonderland." She meets a girl named Alice there and they travel together.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaijuu Sakaba Kanpai! x Yamasa Soy Sauce: Genki Kaijuu Chikarakonbu-kun Genru', 'ONA', 1, 'Completed', '2016-04-30', NULL, '5', '', 214, 'https://cdn.myanimelist.net/images/anime/1708/147528.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Baolie Feiche 5: Jing Ma Mi Zong', 'ONA', 30, 'Completed', '2024-09-15', '2024-10-14', '5', 'Fifth season of Baolie Feiche.', 59, 'https://cdn.myanimelist.net/images/anime/1521/147500.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tianming Da Zhuzai', 'ONA', 40, 'Completed', '2025-01-15', '2025-05-14', '5', 'Since ancient times, Dahe Shenzhou has been a land where virtue and evil have been at odds. Numerous justice-related sects have banded together to combat the evil''s twelve irresponsible sects. The justice Jinyi Sect''s low-level supernatural power is Li Wannian, who possesses ordinary cultivation. He wants to live a life of peace and quiet, lying flat in the Jinyi Sect and receiving a salary.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Space Idol', 'ONA', 6, 'Completed', '2023-01-27', NULL, '5', 'An original short anime depicting four girls who belong to the idol group "Uchu Seifuku" who are active in space. The short anime will be distributed on DMM TV.', 472, 'https://cdn.myanimelist.net/images/anime/1305/132881.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchuu Senkan Yamato II: Yamato yo Eien Nare', 'Special', 1, 'Completed', '1979-10-06', NULL, '5', 'Recap TV special of Uchuu Senkan Yamato 2.', 46, 'https://cdn.myanimelist.net/images/anime/1109/131935.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyojin no Hoshi: Tokubetsu-hen - Hanagata Mitsuru', 'TV', 13, 'Completed', '2002-10-23', '2003-01-15', '5', 'Mitsuru Hanagata spent his early childhood in the UK, where he developed a noble spirit by fighting back against the bullying faced by Asian people. After returning to Japan, he becomes the leader of a baseball team of juvenile delinquents and meets his eternal rival, Hyuuma Hoshi. After going to Koshien, the two rivals join Tigers and Giants respectively as professional players. They face-off against each other as they continue to improve their skills, Hyuuma as a pitcher who throws "Big League" balls and Hanagata as an aggressive player.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chao Wa Zhanshi: Xingji Jiayuan', 'TV', 25, 'Completed', '2011-07-01', NULL, '5', '', 793, 'https://cdn.myanimelist.net/images/anime/1424/124054.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yume wo Kanaeru Zou', 'TV', 12, 'Completed', '2009-01-13', '2009-12-27', '5', 'It''s about an ordinary office worker Fumiyama Fumio, who gains self-confidence by the advices of an Indian god, Ganesha.', 879, 'https://cdn.myanimelist.net/images/anime/10/12867.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kerokero Keroppi: Hasunoue Town Kiki Ippatsu!', 'TV', 6, 'Completed', '2006-10-10', '2006-12-19', '5', '', 90, 'https://cdn.myanimelist.net/images/anime/10/59081.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kupu~!! Mamegoma!', 'TV', 51, 'Completed', '2009-01-10', '2009-12-26', '5', 'The story revolves around a palm-sized seal named Mameta, the other seals (Cherry-chan, Soda-kun, Lemon-chan, Candy-chan), and the Mamekawa family that raises the seals.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Peeping Life: Tezuka Pro - Tatsunoko Pro Wonderland Specials', 'Special', 2, 'Completed', '2013-06-25', NULL, '5', '2 bonus episodes done as a part of the 100th Anniversary campaign video collaboration with Universal Studios. Episode 1 features E.T. and episode 2 features Jaws.', 184, 'https://cdn.myanimelist.net/images/anime/1353/90984.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lalala Demacia', 'ONA', 10, 'Completed', '2011-12-09', '2012-03-09', '5', '', 1048, 'https://cdn.myanimelist.net/images/anime/1017/114410.jpg');
