INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimezou no Kimarimonku Ja Kimaranee. Featuring Sabu-Otoko', 'ONA', 12, 'Completed', '2011-10-05', '2012-04-19', '5', 'Follows the story of young employee of a company that produces star-shaped confections. The unusual man views society cynically and does not fit typical Japanese competitive male stereotypes. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lie Yang Tiandao I', 'ONA', 1, 'Completed', '2020-08-06', NULL, '5', '', 1048, 'https://cdn.myanimelist.net/images/anime/1296/114407.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimezou no Kimarimonku Ja Kimaranee.', 'ONA', 12, 'Completed', '2010-10-03', '2010-12-20', '5', 'Follows the story a flamboyant Kimezou who works for a company that makes star shaped confections.', 802, 'https://cdn.myanimelist.net/images/anime/10/58923.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nukko.', 'TV', 24, 'Completed', '2012-04-02', '2012-09-19', '5', 'The new Nukko. anime is an adolescent school story revolving around Nukko and Nukko''s slightly(?) oddball friends.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nemurenai Yoru no Tsuki', 'Movie', 1, 'Completed', '2015-09-05', NULL, '5', 'A squirrel and a boy set out on a journey together to restore daylight. They must find and release the moon stuck high up on a tree somewhere far, far away.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tai Yi Xian Mo Lu: Ling Fei Ji', 'ONA', 26, 'Completed', '2016-03-08', '2016-10-04', '5', 'Qingcheng Mountain was destroyed and Xuanmen (Profound Gate) suffered a great calamity. Qing Yu''s Altar Master Xing Xiang Zi ordered Zhu Dian''s reincarnation, Leng Shuangning, to go to Kunlun and fight the Demon Army. The magic power was in the air, and the hidden feeling was bewildering. As the two of them boarded Kunlun, Black Hand was planning something behind the scenes...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tai Yi Xian Mo Lu: Ling Fei Ji II', 'ONA', 26, 'Completed', '2017-04-25', '2017-10-17', '5', '', 222, 'https://cdn.myanimelist.net/images/anime/1487/110779.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kintamani Dog', 'TV', 50, 'Completed', '2021-01-14', '2021-12-26', '5', '', 457, 'https://cdn.myanimelist.net/images/anime/1815/120757.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('81 Hao Nongchang: Fengkuang de Mai Ji', 'Movie', 1, 'Completed', '2014-10-01', NULL, '5', '', 792, 'https://cdn.myanimelist.net/images/anime/1037/115616.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Robot Trains', 'TV', 32, 'Completed', '2015-02-26', '2015-11-18', '5', 'Set in the "Train World" where all citizens are trains. However, among the residents there are special trains that can transform into robots, the Robot Trains. Featuring our 5 train heroes, with special powers: Kay, Alf, Duck, Selly and Victor - and their exciting adventures. Can the Robot Trains save the village from the evil dark forces that be?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bakukyuu Renpatsu! Super B-Daman Specials', 'Special', 2, 'Completed', '1999-03-29', '1999-05-31', '5', 'Two specials during Bakukyuu Renpatsu! Super Bedaman''s airing. The first is a story recap that aired between episode 6 and 7. And the second is a "Best Battle" highlight reel that aired between episode 10 and 11.', 1117, 'https://cdn.myanimelist.net/images/anime/4/81875.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sugar Bunnies Fleur Specials', 'Special', 2, 'Completed', '2010-01-19', NULL, '5', 'The 7th DVD of Sugar Bunnies Fleur! contained the unaired episode 27 finale and an unaired recap episode.', 90, 'https://cdn.myanimelist.net/images/anime/7/81866.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sugar Bunnies Chocolate! Specials', 'Special', 2, 'Completed', '2009-02-04', NULL, '5', 'The 7th DVD of Sugar Bunnies Chocolate! contained the unaired episode 27 finale and an unaired recap episode.', 90, 'https://cdn.myanimelist.net/images/anime/3/81865.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wanwanwan Coin', 'ONA', 15, 'Completed', '2015-11-30', '2016-06-20', '5', 'A "vertical" anime starring a coin with doglike properties.', 214, 'https://cdn.myanimelist.net/images/anime/12/81612.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Peeban', 'OVA', 6, 'Completed', '2010-04-22', NULL, '5', 'The episodes follow a pig named Peeban and his friends.', 315, 'https://cdn.myanimelist.net/images/anime/5/81609.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Skyers 5 EX', 'Special', 3, 'Completed', '2015-04-24', NULL, '5', 'Unreleased episodes of Skyers 5 released to the public nearly five decades later on the HD Remaster DVD-BD Box Set 1.', 986, 'https://cdn.myanimelist.net/images/anime/1362/100888.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blend S', 'TV', 12, 'Completed', '2017-10-08', '2017-12-24', '7', 'Wishing to be independent, 16-year-old Maika Sakuranomiya is desperate to nail down a part-time job so that she can afford to study abroad. Unfortunately, her applications are constantly rejected due to the menacing look she unintentionally makes whenever she smiles, despite her otherwise cheerful disposition.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka II', 'TV', 12, 'Completed', '2019-07-13', '2019-09-28', '7', 'It is business as usual in the massive city of Orario, where legions of adventurers gather to explore the monster-infested "Dungeon." Among them is the easily flustered yet brave Bell Cranel, the sole member of the Hestia Familia. With the help of his demi-human supporter Liliruca Arde and competent blacksmith Welf Crozzo, Bell has earned the title of Little Rookie by becoming Orario''s fastest-growing adventurer thanks to his endeavors within the deeper levels of the Dungeon.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Heavy Object', 'TV', 24, 'Completed', '2015-10-03', '2016-03-26', '7', 'In the distant future, the nature of war has changed. "Objects"—massive, spherical tanks impermeable to standard weaponry and armed with destructive firepower—rule the battlefield; their very deployment ensures victory, rendering traditional armies useless. However, this new method of warfare is about to be turned on its head.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uzaki-chan wa Asobitai! Double', 'TV', 13, 'Completed', '2022-10-01', '2022-12-24', '7', 'During the summer holidays, energetic Hana Uzaki spent most of her time accompanying her lonesome upperclassman, Shinichi Sakurai. Now that school has resumed, Uzaki''s teasing continues to ramp up, much to Sakurai''s constant annoyance. Nevertheless, no amount of ridicule can damage the pair''s relationship—which only seems to be getting better as their college days fly by!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sei Juushi Bismarck', 'TV', 51, 'Completed', '1984-10-07', '1985-09-29', '7', 'In the distant future, humanity has explored beyond Earth and colonized both the inner and outer planets of the Solar System. In order to protect the colonies and maintain law and order in the solar system, the Earth Federation Government (EFG) was created. Soon, many settlers started to resent the EFG''s and its sphere of influence, straining the relationship between the central government and the colonies.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dr. Stone: Stone Wars - Kaisen Zenya Special Eizou', 'Special', 1, 'Completed', '2020-10-11', NULL, '7', 'A recap episode with additional scenes which was screened on Jump''s official YouTube channel for Jump Special Anime Festa 2020.', 990, 'https://cdn.myanimelist.net/images/anime/1097/109900.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyouran Kazoku Nikki', 'TV', 26, 'Completed', '2008-04-12', '2008-10-04', '7', 'Midarezaki Ouka is used to having strange things happen to him -after all, he is the head of the Great Japanese Empire Paranormal Phenomena Bureau of Measures. But when he catches a small cat girl in the shopping district stealing apples, his whole life rearranges to fit a new operation... 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dinghai Fusheng Lu', 'ONA', 12, 'Completed', '2021-07-15', '2021-12-16', '7', 'Immortal arts, magic weapons, magical powers, and the boundless spiritual qi between heaven and earth vanished into obscurity overnight, and all exorcists turned to mere mortals.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Papa no Iukoto wo Kikinasai!', 'TV', 12, 'Completed', '2012-01-11', '2012-03-28', '7', 'Yuuta Segawa has just started his freshman year of university. One day, his sister Yuri, who raised him after their parents died, asks him to take care of her daughters Hina, Sora and Miu while she and her husband go overseas on a business trip. Yuuta grudgingly accepts, but tragedy strikes when their plane goes missing and all passengers are presumed dead. In an effort to prevent the three girls from being split up, Yuuta goes against their family and takes them in, just as his sister took him in when he had no one else.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hamatora The Animation', 'TV', 12, 'Completed', '2014-01-08', '2014-03-26', '7', 'The ability to create miracles is not just a supernatural phenomenon; it is a gift which manifests in a limited number of human beings. "Minimum," or small miracles, are special powers that only selected people called "Minimum Holders" possess. The detective agency Yokohama Troubleshooting, or Hamatora for short, is composed of the "Minimum Holder PI Duo," Nice and Murasaki. Their office is a lone table at Cafe Nowhere, where the pair and their coworkers await new clients.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tekken Chinmi', 'TV', 20, 'Completed', '1988-07-02', '1988-12-24', '7', 'Chinmi is a young Chinese boy devoted to martial arts training. Word of his skill reaches the kung-fu masters at the famous Dailin temple who invite him to study with them. Through his own dedication and the guidance of his teachers, Chinmi becomes one of the top students at the temple. Eventually, the time comes for him to leave Dailin and make a pilgrimage. On his journey he faces a number of dangers that test his skills, but he also meets many people who inspire him in different ways. A chastened but determined Chinmi returns to Dailin for advanced training. But soon his skills are needed again—the Mongol hordes are nearing the temple.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yume no Crayon Oukoku', 'TV', 70, 'Completed', '1997-09-07', '1999-01-31', '7', 'The civilians of the Crayon Kingdom have always view their Princess Silver as a twelve-year old girl with a beautiful smile. However, unknown to them, the princess has 12 bad habits. This has created much distress to the Chameleon Prime Minister and the Crayon ministers for it would be embarassing if this gets out. One day, a party was held to celebrate Princess Silver''s twelvth birthday. The princess was trying to seek her Prince Charming that she forgot to take notice of her bad habits. One of the boys at the party was so angry that he changed Silver''s parents, the King and Queen, into stone. In order to break the curse and save her parents, Silver decided to set on a journey to locate the boy. Together with her companions, Silver begins her adventure.', 1030, 'https://cdn.myanimelist.net/images/anime/11/28591.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lupin III: Honoo no Kioku - Tokyo Crisis', 'Special', 1, 'Completed', '1998-07-24', NULL, '7', 'Lupin &amp; co. attempt to steal two face plates from millionare Michael Sizuki, thinking that they will lead to an ancient treasure when brought together. However, it soon becomes apparent that there is more behind the plates then meets the eye. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nu Wushen de Canzhuo Spring Festival Special', 'ONA', 1, 'Completed', '2021-02-11', NULL, '7', 'The St. Freya squad returns with a bubbling hot pot! Let Valkyries introduce you to a very special Spring Festival~ 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sayonara Ginga Tetsudou 999: Andromeda Shuuchakueki', 'Movie', 1, 'Completed', '1981-01-08', NULL, '7', 'Despite the destruction of the mechanization home world Andromeda, the machine empire is still swept across the galaxy and Earth has become a battleground. Having returned from his journey aboard the train Galaxy Express 999, Tetsurou Hoshino joins the resistance and fights alongside others who have retained their humanity.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Slayers Revolution', 'TV', 13, 'Completed', '2008-07-03', '2008-09-25', '7', 'Having lost the Sword of Light in the previous battle, Lina and Gourry continue their journey in search of a replacement weapon. On the way, the two of them meet up with Amelia and Zelgadis in the kingdom of Luvinagard while taunting some pirates. Lina is happy to reunite with her old friends, but appearing before her is Luvinagard''s Inspector of the Special Investigative Unit; a man called Wizer. However, Lina is amazed at his unusual behavior... 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Air Gear Special', 'Special', 1, 'Completed', '2007-03-21', NULL, '7', 'Takes part a while after Ikki accepts Simca''s offer to become the new leader of Genesis. Shows the Battle between Kogarasumaru and Potemkine. The episode takes place between episodes 21 and 22 of the main series.', 1030, 'https://cdn.myanimelist.net/images/anime/1902/97393.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nabari no Ou', 'TV', 26, 'Completed', '2008-04-07', '2008-09-29', '7', 'Silent, apathetic, yet mischievous, 14-year-old Rokujou Miharu is the bearer of the hijutsu "Shinrabanshou," a powerful technique many ninja clans desire so they can become the ruler of Nabari. His classmate Kouichi Aizawa and English teacher Thobari Durandal Kumohira are both secretly Banten clan ninjas who have pledged themselves to protect Miharu from his many attackers. Keeping apathetic, Miharu attempts to reject their invitation to join their ninja "club." However, after numerous attacks, he finds no choice but to join their group as a means for his survival. Slowly, Miharu gets ever closer to becoming the ruler of Nabari.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maria-sama ga Miteru: Haru Specials', 'Special', 6, 'Completed', '2004-10-22', '2005-05-23', '7', 'Specials of Maria-sama ga Miteru: Haru released on the DVDs only.', 879, 'https://cdn.myanimelist.net/images/anime/8/5782.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wan Jie Du Zun', 'ONA', 50, 'Completed', '2021-04-06', '2021-09-18', '7', 'On this day, Lin Feng was condensing his martial soul in the Lin Mansion. He didn''t want to, he had just cultivated his sword martial soul into a prototype, and his fiancee Ji Manyao took the opportunity to take away his martial soul, causing him to vomit blood and die. At the same time, Lin Feng''s spirit entered the place where the gods were buried. The mysterious woman in the place told Lin Feng that he could gain huge martial arts power and knowledge by destroying the ancient gods buried here. In the real world, Lin Feng, who was originally the eldest young master of the Lin family, was no longer respected by his servants because he lost his sword spirit. It was not until Lin Feng used the power obtained from the place of burial to defeat Lin Yuhong, the powerhouse of Huangjie Wuhun, that the Lin family''s attitude towards Lin Feng changed. On the other hand, Lin Feng killed Qin Xiao who was fighting with him because he couldn''t control the newly acquired power well. Qin Xiao is the grandson of the first elder of the Qin family, and has always been favored by the elders. Now that Qin Xiao was killed, the elders of the Qin family were unwilling.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('"Bungaku Shoujo" Memoire', 'OVA', 3, 'Completed', '2010-06-25', '2010-12-24', '7', 'Episodes which depict the background stories of "Bungaku Shoujo" Movie''s main heroines.', 704, 'https://cdn.myanimelist.net/images/anime/6/26770.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Crayon Shin-chan Movie 21: Bakauma! B-Kyuu Gourmet Survival Battle!!', 'Movie', 1, 'Completed', '2013-04-20', NULL, '7', 'Comical adventure story starring Kasukabe Defense Forces and dealing with "food" as theme. Kasukabe Defense Forces (Shinnosuke and his mates: Kazama-kun, Nene-chan, Masao-kun and Bo-chan) decide to attend "B-class Gourmet Carnival", a big event in Kasukabe, without their parents, to eat very tasty yakisoba sauce cooked by "Sauce''s Ken". On the way, a mystery woman asks them to bring a legendary sauce to Sauce''s Ken. They head to the event site with the sauce, but they wander off into a mountain, and "A-class Gourmet Organization", an organization plotting to eliminate B-class gourmet, seeks to take the sauce away from them.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kindaichi Shounen no Jikenbo Specials', 'Special', 2, 'Completed', '2007-11-12', '2007-11-19', '7', 'Kindaichi and the gang are on their way to a hot spring, but get lost and end up at a run down and sinister hotel. They are told that a vampire used to live in the hotel way back. Someone even died (was found with bite marks on the neck).
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maria-sama ga Miteru 3rd Specials', 'Special', 5, 'Completed', '2006-12-29', '2007-07-25', '7', 'A series of chibi-style "outtakes" from the "shooting" of the Mariamite series.', 879, 'https://cdn.myanimelist.net/images/anime/13/44396.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lupin III vs. Cat''s Eye', 'ONA', 1, 'Completed', '2023-01-27', NULL, '7', 'Lupin III, the great phantom thief—the man who loves freedom and lives in romance—never fails to steal his prey. The Cat''s Eye are the ladies who run the night splendidly and create commotion in the world. They are sometimes phantom thieves, other times three beautiful sisters who run a café.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ling Yu 5th Season', 'ONA', 12, 'Completed', '2017-07-20', '2017-10-05', '7', '', 369, 'https://cdn.myanimelist.net/images/anime/1070/92961.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koukyoushihen Eureka Seven Hi-Evolution 2: Anemone', 'Movie', 1, 'Completed', '2018-11-10', NULL, '7', 'The film centers on Anemone, a girl who lost her father in a battle in Toyko seven years prior to the film''s story, leaving her with only her stuffed toy Gulliver, and the AI concierge Dominikids for emotional support. Now she is a key part of a strategy by the experimental unit "Acid" to combat the seventh Eureka, "Eureka Seven," an enemy of humanity that has killed 2.6 billion people. Driven to the brink, all of humanity entrusts its hope to Anemone as she dives deep into the interior of Eureka Seven.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Minami Kamakura Koukou Joshi Jitensha-bu: Kita yo, Taiwan!', 'Special', 1, 'Completed', '2017-05-15', NULL, '7', 'Unaired episode included with the special edition BD release.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sangokushi: Dai Ichi Bu - Eiyuu-tachi no Yoake', 'Movie', 1, 'Completed', '1992-01-25', NULL, '7', 'The Yellow Turban rebellion that initiated the downfall of the ruling Han dynasty. At the start of the story, both Liu Bei, its eventual protagonist, and Cao Cao, its eventual antagonist, are minor players. Liu Bei is striving to find a way to bring order to a chaotic world. As he puzzles he way toward the correct course of action, he befriends two powerful warriors, Zhang Fei and Guan Yu. Together, they take the Oath of the Peach Garden, to live and die together as warriors for justice. Meanwhile, Cao Cao is pondering how to fulfill his destiny as "a hero in a chaotic world or a villain in a peaceful one."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cross Fight B-Daman', 'TV', 52, 'Completed', '2011-10-02', '2012-09-30', '7', 'A rumor has spread amongst the children worldwide regarding the popular B-Daman matches: A select group will be allowed to participate in an upcoming secret competition, known as "Cross Fight"! 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hyakka Ryouran: Samurai Bride Specials', 'Special', 6, 'Completed', '2013-06-26', '2013-11-27', '7', 'Specials included on DVDs and Blu-rays.', 85, 'https://cdn.myanimelist.net/images/anime/13/52085.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ranpo Kitan: Game of Laplace', 'TV', 11, 'Completed', '2015-07-03', '2015-09-18', '7', 'After what appears to be just another ordinary day, middle school student Yoshio Kobayashi wakes up in his classroom to make a terrifying discovery: his teacher has been mutilated, and Yoshio happens to be holding the weapon used to commit the crime.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Grancrest Senki: Tsuisou', 'Special', 1, 'Completed', '2018-03-24', NULL, '7', 'A recap of major events and notable characters from the first 11 episode of Grancrest Senki.', 14, 'https://cdn.myanimelist.net/images/anime/1795/91146.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Itou Junji: Collection', 'TV', 12, 'Completed', '2018-01-05', '2018-03-23', '7', 'In the light of day and in the dead of night, mysterious horrors await in the darkest shadows of every corner. They are unexplainable, inescapable, and undefeatable. Be prepared, or you may become their next victim.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Soushin Shoujo Matoi: Kabushiki Gaisha Knight Busters', 'Special', 1, 'Completed', '2017-04-21', NULL, '7', 'An unaired thirteenth episode of Soushin Shoujo Matoi included with the second BD box set.', 1102, 'https://cdn.myanimelist.net/images/anime/3/85472.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Qin Shi Mingyue: Tian Xing Jiu Ge 2nd Season', 'ONA', 30, 'Completed', '2019-04-24', '2019-11-08', '7', '', 827, 'https://cdn.myanimelist.net/images/anime/1107/102465.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tennis no Oujisama: Best Games!!', 'OVA', 4, 'Completed', '2018-08-24', '2019-11-15', '7', 'Tezuka vs. Atobe
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oda Cinnamon Nobunaga', 'TV', 12, 'Completed', '2020-01-11', '2020-03-28', '7', 'In the "one-of-a-kind samurai-general-reincarnated-as-a-canine comedy," Nobunaga perishes at Honnouji as in history, and reincarnates in modern-day Japan as a dog named Shinamon. Other Warring States era warlords such as Takeda Shingen eventually join him, also as dogs.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Berserk 2nd Season', 'TV', 12, 'Completed', '2017-04-07', '2017-06-23', '7', 'Demons have now become commonplace around the kingdom of Midland, which has fallen into chaos. The swordsman Guts still cannot stay in one place for long due to his demonic brand. He could always manage to protect himself when he was alone, but now he has the added challenge of protecting former Commander Casca, a shell of her former self who neither remembers nor trusts him. They never have a moment''s rest with the constant threat of demons, and they need a place where Casca will be safe till they find a way to heal her. Their elf ally, Puck, tells of the mystical land of Elfhelm, which is supposed to be a safe haven from the demons that ravage the lands. Tired and with only a vague hope, they struggle on to find a place to live—and they still need to find those responsible for the madness they are forced to endure. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Arslan Senki (TV): Tsuioku no Shou - Dakkan no Yaiba', 'Special', 1, 'Completed', '2015-07-05', NULL, '7', 'Arslan Senki (TV): Dakkan no Yaiba retells the events of the series'' first 13 episodes, summarizing the events that transpired from Arslan''s escape with Daryun, to their time in the Peshawar Citadel.', 756, 'https://cdn.myanimelist.net/images/anime/11/74848.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('K-On!!: Ura-On!!', 'Special', 9, 'Completed', '2010-07-30', '2011-03-16', '7', 'Extra short anime "Ura-On!!" included in the limited edition of the K-ON!! Blu-ray.', 494, 'https://cdn.myanimelist.net/images/anime/10/25513.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Spider Riders: Oracle no Yuusha-tachi', 'TV', 26, 'Completed', '2006-04-05', '2006-09-27', '7', 'Underneath the surface of the Earth lies the Inner World, a realm where a war rages on between intelligent spiders and the invading humanoid insects known as Insectors. However, the spiders are not alone, as "Spider Riders"—humans from the Outer World, known as Earthens in the Inner World, that are chosen by the Oracle—fight alongside them. Filled with wondrous tales of a mysterious pyramid and entrusted with his grandfather''s journal, a young boy called Hunter Steele sets out on an exploration. There, his destined meeting with the Oracle occurs, and he is transported into the Inner World as a Spider Rider.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mushi-Uta', 'TV', 12, 'Completed', '2007-07-06', '2007-10-05', '7', 'Mushi-uta''s story takes place in the near future. Ten years before the story''s opening, strange insect-like creatures known as "Mushi" began appearing. The Mushi are able to consume peoples'' dreams and thoughts in return for supernatural powers. At the end of episode one, protagonist Daisuke "Kakkou" Kusuriya encounters a young girl named Shiika Anmoto. The two, in time, become quite close. However, unbeknownst to Kakkou, Shiika is an escapee from a secret prison known as GARDEN where those posessed by the Mushi, known as the Mushitsuki are held. GARDEN''s military force, the Special Environmental Conservation Executive Office, dispatches its finest killer to track down Shiika. However, they are faced with resistance from the Mushibane resistance organisation, led by the secretive "Ladybird."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bear Bear Bear Kuma!', 'ONA', 12, 'Completed', '2020-10-09', '2020-12-25', '7', 'Mini anime for Kuma Kuma Kuma Bear released weekly on the Kadokawa Anime YouTube channel.', 254, 'https://cdn.myanimelist.net/images/anime/1584/109714.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tottoko Hamtarou Movie 2: Ham-Ham Hamuuja! Maboroshi no Princess', 'Movie', 1, 'Completed', '2002-12-14', NULL, '7', 'Lately, Hamtaro has been having a strange dream. In the dream, a beautiful princess hamster tearfully asks for help. Hamtaro can’t forget about her, even when he’s awake. One winter day, Laura talks to Hamtaro. She tells him that everyone in the family is going home to her father’s hometown. When Hamtaro tells his friends about it, Maxwell pulls out a Ham-Ham source book. It’s a book on old hamster history. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koro no Dai Sanpo', 'Special', 1, 'Completed', '2001-10-01', NULL, '7', 'This is a short film about 15 minutes long, which was shown for a limited time only at the Ghibli Museum. Koro is a puppy owned by a little girl in a small town. One day she leaves the front gate ajar when she goes to school. Koro slips out and wanders the streets of the town. He is picked up by a girl riding a bicycle, but slips away at the level train crossing. He meets a friendly old dog and his kindly owners, while his mistress and her father ride around town putting up "Lost" signs on the power poles. Koro eventually falls asleep under a delivery van, whose driver gives him a ride. When he gets near home, Koro smells the familiar neighborhood and leaps out of the truck and into the arms of his delighted mistress.', 893, 'https://cdn.myanimelist.net/images/anime/8/16252.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mouryou no Hako: Chuuzenji Atsuko no Jikenbo - Hako no Yurei no Koto', 'Special', 1, 'Completed', '2009-05-22', NULL, '7', 'A side story that reveals the investigative notes that Atsuko, the younger sister of the main character Akihiko Chuzenji, wrote about the brutal dismembering incidents in the main story.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Isekai Suicide Squad', 'TV', 10, 'Completed', '2024-07-06', '2024-09-07', '6', 'The Joker and his best girl, Harley Quinn, are tearing through the streets of Gotham with sacks full of cash and the law in hot pursuit. Unfortunately for them, though the jester manages to escape, the night ends with Harley being captured by a mysterious, katana-wielding woman.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wan Jie Zhizun', 'ONA', 50, 'Completed', '2022-11-24', '2023-05-03', '6', 'Seven years ago, Chu Yunfei was struck by a dramatic change in his family and was stranded in the Pill King Valley in Zhongzhou. He returned to his homeland to take revenge and vowed to find out the truth.', 752, 'https://cdn.myanimelist.net/images/anime/1027/131166.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gurazeni', 'TV', 12, 'Completed', '2018-04-06', '2018-06-22', '6', 'This is the story of Natsunosuke Honda, a pro baseball player—a relief pitcher who has been playing pro in a team called Spiders for 8 years. The team operates as a highly-stratified society, where the player''s performance determines his annual salary. Natsunosuke is one of the highest paid players in the game. He measures how good players are by how much money they make, and he intends to be on top and stay there, and as such is always looking for players to challenge and does everything to insure that he is better than they are.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Genei wo Kakeru Taiyou', 'TV', 13, 'Completed', '2013-07-06', '2013-09-28', '6', 'Akari Taiyou is an apprentice fortune teller living with her aunt, uncle, and their daughter Fuyuna. Having lost her mother at a young age, the only thing Akari has left of her is a deck of tarot cards and a dream to follow in her footsteps as a fortune teller.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lan Mo de Hua', 'ONA', 9, 'Completed', '2017-07-13', '2017-08-14', '6', 'Gluttonous and tomboyish, Lan Mo is hardly anyone''s ideal girl, but with a magical hair clip from a mysterious trinket shop that disappears the next day, she may be able to become just that. With its power, she can transform into a beautiful and feminine young lady, someone who may finally be able to catch the eye of her childhood friend and crush, Liu Yifeng. However, keeping the clip''s secret proves difficult for Lan Mo when faced with Liu Yifeng''s admirers and the mysterious stranger Xia An. And to further complicate matters, Lan Mo''s possession of the hair clip may turn out to be more than just mere coincidence.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Miru Tights', 'ONA', 12, 'Completed', '2019-05-11', '2019-07-27', '6', 'Light showers accompany falling cherry blossoms as they flood the view of another April morning, marking the start of a new school year for students Homi Moegi, Ren Aikawa, and Yua Nakabeni. Discovering that they all share the same class, the three playfully reunite as the new semester begins.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Warau Salesman Dai SP-banashi', 'Special', 8, 'Completed', '1990-01-23', '1992-07-07', '6', 'Specials of Warau Salesman broadcasted intermittently during the main show not included in the episode count of the main show. They are 3 times the length of a normal episode and fill a half hour time-slot.', 802, 'https://cdn.myanimelist.net/images/anime/12/84709.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kitsune no Koe', 'TV', 12, 'Completed', '2018-10-05', '2018-12-21', '6', 'The series follows 16-year-old Hu Li, who dreams of becoming a popular singer. However, he has neither good looks nor the financial means to pursue his dream, so Hu Li uploads his singing online using a fox avatar.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Escha Chron', 'ONA', 2, 'Completed', '2017-11-03', NULL, '6', 'The story follows the two titular girls Escha and Chron, whose contrasting personalities are like the sun and moon. The two girls are from Terminal, a future post-apocalyptic world that''s empty and monochrome. The two girls cross worlds and arrive in the present day, which they call Transit. As Escha and Chron experience the light (scenery) and sound (music) of the real world, the future world of Terminal gradually changes into a more vivid world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kochira Katsushikaku Kameari Kouenmae Hashutsujo: Washi to Ore!? - Bokura wa Asakusa Shounen Tanteidan!', 'Special', 2, 'Completed', '2008-04-06', '2008-04-13', '6', 'An amazing time machine invention allows Ryoutsu to return to the years of his childhood.', 325, 'https://cdn.myanimelist.net/images/anime/6/81552.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Battle Spirits: Shounen Toppa Bashin', 'TV', 50, 'Completed', '2008-09-07', '2009-09-06', '6', 'Energetic and thrill-seeking sixth grader Toppa Bashin has his mind set on only one thing—the card game Battle Spirits. Bearing a ruby pendant inherited from his missing father, Bashin heads to school every day with excitement: not for academics, but for card battling, much to the chagrin of his peers.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Love Live! The School Idol Movie: Gekijou Manner CMs', 'Movie', 4, 'Completed', '2015-06-13', '2015-06-27', '6', 'Short videos shown in theaters before Love Live! The School Idol Movie which teach basic theater manners.', 974, 'https://cdn.myanimelist.net/images/anime/10/88032.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Anklet to Aoi Umi', 'Movie', 1, 'Completed', '2018-09-27', NULL, '6', 'One day, a girl living on an island drops her precious anklet into the sea. A strange boy emerged from the sea and returned it to her. It is a nostalgic and warm story that depicts the harshness and beauty of the ocean and the small friendship born there through the girl''s anklet.', 904, 'https://cdn.myanimelist.net/images/anime/1989/106267.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Getsuyoubi no Tawawa', 'ONA', 12, 'Completed', '2016-10-10', '2016-12-26', '6', 'Oniisan, a typical salaryman, has the weekly duty of protecting high school student Ai-chan from gropers by escorting her during their Monday morning train commutes. Despite the short time Oniisan and Ai-chan spend together, they manage to bond and learn more about each other''s lives. To help Oniisan get through his Monday blues, Ai-chan gives him small presents as motivation.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyouryuu Shoujo Gauko 2nd Season', 'ONA', 19, 'Completed', '2020-03-20', NULL, '6', 'The comedy series is set in Japan and follows Naoko Watanabe, a typical tween girl aside from the fact that she possesses strange and sometimes troubling powers. When her anger exceeds a maximum level, she turns into Gauko, the fire-breathing dinosaur girl.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ars no Kyojuu', 'TV', 12, 'Completed', '2023-01-07', '2023-03-25', '6', 'In the world of Ars, humans lead a decades-long war against giant beasts that ravage the lands and feed on their resources. Those tasked with fighting them are Paladins, who utilize the destructive power of Clerics: beings gifted with uncontrollable magical powers.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kai Feng Qitan: Zhege Baogong Bu Taixing', 'ONA', 10, 'Completed', '2017-05-19', '2017-07-21', '6', 'North Song Dynasty in ancient China, a legendary figure emerged in North Song''s capital Kai Feng. He is governor Zheng Bao. Peasants call him Bao Gong (Lord Bao). In a corrupted government, he differentiates himself by demonstrating extreme honestly, uprightness, impartiality, and the courage to uphold justice, which, won him the title "Justice Bao". In Chinese folklore, Zheng Bao is the reincarnation of Megrez (Chinese God of Wisdom) and possesses supernatural powers. Kai Feng Story tells the legend of Bao Gong in a brand new type of personality.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Choboraunyopomi Gekijou Dai San Maku Ai Mai Mii: Surgical Friends', 'TV', 12, 'Completed', '2017-01-03', '2017-03-21', '6', 'Ai, Mai, Mii, and Ponoka continue to make the most of their high school years working on manga, engaging in friendly competition with each other, and going toe-to-toe with fierce rivals. As they continue to encounter a series of bizarre and amusing situations, the girls find little time to be bored.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gunslinger Stratos The Animation', 'TV', 12, 'Completed', '2015-04-04', '2015-06-20', '6', 'A.D. 2115—the island nation once called Japan is now known as the "17th Far East Imperial City Management District."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('DRAMAtical Murder', 'TV', 12, 'Completed', '2014-07-07', '2014-09-22', '6', 'Some time ago, the influential and powerful Toue Inc. bought the island of Midorijima, Japan, with the plans of building Platinum Jail—a luxurious utopian facility. Those who are lucky enough to call it home are the wealthiest citizens in the world. The original residents of the island, however, were forced to relocate to the Old Residential District; and after the completion of Platinum Jail, they were completely abandoned.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fight League: Gear Gadget Generators', 'ONA', 26, 'Completed', '2019-02-14', '2019-08-08', '6', 'Hot-blooded in nature, Adjust Wrench competes with her team Boltechs in a popular tournament known as the "Fight League," where two teams fight using personalized weapons called "Gadgets" until only one team is left standing. However, despite their best efforts, Wrench and her friends have only achieved moderate success in the Fight League—winning just as often as they lose.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Iron Man', 'TV', 12, 'Completed', '2010-10-01', '2010-12-17', '6', 'Tony Stark, CEO of a large weapons manufacturer, physicist, engineer, and brilliant inventor, is wounded by shrapnel from one of his own weapons. While held captive by terrorists, he develops the Iron Man Suit  and escapes. From that day on, he vows not to waste his second chance at life and to change the world for the better. For that purpose, he comes to Japan.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('"Eikou Naki Tensai-tachi" Kara no Monogatari', 'Special', 2, 'Completed', '2017-03-25', '2017-05-28', '6', 'An anime/documentary series about athletes present by NHK.
