INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuang Kuang Riji', 'ONA', 20, 'Completed', '2009-01-01', NULL, '5', '', 396, 'https://cdn.myanimelist.net/images/anime/1677/124010.jpg');
