INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mayi', 'ONA', 1, 'Completed', '2007-11-27', NULL, '5', '', 354, 'https://cdn.myanimelist.net/images/anime/1445/123670.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gushu Xin Shuo', 'Movie', 1, 'Completed', '1992-01-01', NULL, '5', '', 792, 'https://cdn.myanimelist.net/images/anime/1133/123119.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yattokame Tanteidan', 'TV', 14, 'Completed', '2007-10-07', '2008-01-06', '5', 'Neighborhood children help a group of retirees solve local mysteries in contemporary Japan.', 611, 'https://cdn.myanimelist.net/images/anime/3/11274.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuuto-kun ga Iku Movie', 'Movie', 1, 'Completed', '2014-05-31', NULL, '5', 'Movie of Yuuto-kun ga Iku.', 804, 'https://cdn.myanimelist.net/images/anime/4/59177.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Miracle! Mimika', 'TV', 225, 'Completed', '2006-04-03', '2009-03-13', '5', 'Himeno Mimika is a daughter of historical cook family. She goes to a cooking school, Miracle Academy which train cooks all over the world. Vying with rivals, she brings out her gift, and she grows up as a cook.  
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kattobase! Dreamers: Carp Tanjou Monogatari', 'Movie', 1, 'Completed', '1994-01-22', NULL, '5', '', 538, 'https://cdn.myanimelist.net/images/anime/1567/145981.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Holiday Love: Fuufukan Renai', 'ONA', 20, 'Completed', '2018-08-03', NULL, '5', 'Can a relationship survive after an affair? Azu is 30-year-old stay at home mom and she runs a nail salon in her apartment. While carrying the frustration of thinking that her husband Junpei (32) doesn''t love her as a woman anymore, she raises the child they were blessed with and continues through the motions of everyday life. One day, while Azu is running her salon, a customer asks to borrow her cellphone, and shows her something dangerously entrancing. A few days afterward, she receives a notification from an unknown man, sending Junpei and Azu''s relationship into the deep-end... From Yukari Koyama of the TV drama "Rose-Colored Crusade" comes a challenging original work! You are invited to the story of 4 married people that could take place anywhere, filled with temptation, betrayal, and broken hearts - a true love story!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hoshi no Shima no Nyanko', 'TV', 26, 'Completed', '2018-10-06', '2019-03-30', '5', 'The story centers on the cats Hopi, Toto, and Mao, who set out on the ocean in search of a place to establish a new town. The three friends plan to find the mysterious "Island of Stars." When they happen to chance upon it, they immediately get to work developing the island, but encounter many difficulties in their task. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xian Wu Chuan', 'ONA', 26, 'Completed', '2023-03-19', '2023-09-03', '7', 'As a loyal disciple, Ye Chen dedicated himself to guard the spiritual medicine field for his sect. But, during a fight with enemies, the spiritual field was destroyed. His loyalty and dedicating to the sect could not save him. The loyalty he thought he had obtained from his peers and lover, could not save him from betrayal. Thus, he was shamelessly banished from the sect. With the help of a flame falling from heaven, Ye Chen began to develop himself into a stronger cultivator. Battled against his opponents, unfolded his legendary life and rewrote his own story...', 1118, 'https://cdn.myanimelist.net/images/anime/1401/126049.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pui Pui Molcar: Driving School', 'TV', 12, 'Completed', '2022-10-08', '2022-12-24', '7', 'New series for Pui Pui Molcar.', 1072, 'https://cdn.myanimelist.net/images/anime/1382/125361.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Masamune-kun no Revenge R', 'TV', 12, 'Completed', '2023-07-03', '2023-09-18', '7', 'With the tumultuous cultural festival behind him, Masamune Makabe continues his efforts to carry out his revenge: to make the "Cruel Princess" Aki Adagaki deeply fall for him and then immediately dump her. As his class is going on a trip to Paris, widely known as the City of Love, Masamune has the perfect opportunity to get even for his childhood heartbreak.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gatchaman Crowds Insight', 'TV', 12, 'Completed', '2015-07-05', '2015-09-27', '7', 'One day, a huge UFO spins over Japan and crashes into a rural farmland outside Nagaoka, disrupting Tsubasa Misudachi''s ordinary life. As the Gatchaman, the legendary defenders of Tachikawa City, supervise the ordeal, a peaceful alien creature emerges from the spacecraft. In the ensuing chaos, Tsubasa is given a special high-tech notebook, or NOTE, from Gatchaman founder J.J. Robinson, signaling Tsubasa''s sudden recruitment into their group. Under the tutelage of fellow hero Hajime Ichinose, Tsubasa slowly begins to adjust to life as a defender of justice.  
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Trinity Seven Movie 1: Eternity Library to Alchemic Girl', 'Movie', 1, 'Completed', '2017-02-25', NULL, '7', 'The film''s story begins when Arata inadvertently touches "Hermes Apocrypha," Lilith''s Grimoire. Suddenly, he is enveloped by a bright white light, and a girl appears before him. She calls herself Lilim, and treats both Arata and Lilith as her parents. At the same time she appears, something changes in the world. The forbidden Eternal Library awakens. In the Library is sealed the ultimate culmination of Alchemy, the White Demon Lord. The White Demon Lord plots to eliminate Arata and the Trinity Seven to usurp the position of Demon Lord. Bristling with untold power, the White Demon Lord attacks Arata, and triggers a desperate crisis where Arata and the Trinity Seven must save the world in this last battle.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Phi Brain: Kami no Puzzle - Shukuteki! Rätsel-hen', 'TV', 25, 'Completed', '2013-10-06', '2014-03-23', '7', '"Are puzzles really necessary in this world?"
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Girls & Panzer Specials', 'Special', 6, 'Completed', '2012-12-21', '2013-06-21', '7', 'Mini episodes bundled with Blu-rays and DVDs.', 48, 'https://cdn.myanimelist.net/images/anime/7/42857.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wu Geng Ji: San Jie', 'ONA', 42, 'Completed', '2019-12-20', '2020-10-09', '7', 'Third season of Wu Geng Ji.', 827, 'https://cdn.myanimelist.net/images/anime/1000/116470.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Amanchu!', 'TV', 12, 'Completed', '2016-07-08', '2016-09-23', '7', 'Originally from a big city, Futaba Ooki spends most days cataloguing her life through pictures on her phone. Upon moving to a seaside town, she gazes out over the vast expanse of sea and quickly becomes captivated by its endless possibilities. Unbeknownst to Futaba, her quiet contemplation catches the attention of local diving enthusiast Hikari Kohinata. Finding herself in the same class as Futaba the next day, Hikari is drawn to her quiet and shy demeanor and affectionately nicknames her Teko, sparking a tender friendship. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blood Lad', 'TV', 10, 'Completed', '2013-07-08', '2013-09-09', '7', 'Staz Charlie Blood is a powerful vampire who rules the Eastern district of Demon World. According to rumors, he is a bloodthirsty and merciless monster, but in reality, Staz is just an otaku obsessed with Japanese culture and completely uninterested in human blood. Leaving the management of his territory to his underlings, Staz spends his days lazing around, indulging in anime, manga, and games.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ou Dorobou Jing in Seventh Heaven', 'OVA', 3, 'Completed', '2004-01-21', '2004-04-28', '7', 'Jing, the infamous King of Bandits, finds himself and his feathered partner Kir behind bars in Seventh Heaven, the most notorious prison complex in the world. There, they seek to steal the Dream Orb from the convict Campari. But before doing so, they must escape from the prison of dreams that Campari has conjured for them.', 879, 'https://cdn.myanimelist.net/images/anime/1304/140180.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doraemon Movie 30: Nobita no Ningyo Daikaisen', 'Movie', 1, 'Completed', '2010-03-06', NULL, '7', 'Nobita asks Doraemon to take him somewhere they can dive and as a result the robot-cat uses several gadgets to make it possible for both to able to swim on an imaginary ocean above sea level. Inadvertently a mermaid ends up on Nobita''s backyard when they turn off the illusion. Her name is Sophia and she is a princess of an ancient underwater civilization. Doraemon, Nobita, Shizuka, Jyaian, and Suneo quickly become her friends and are invited to visit her homeland. While heading towards the underwater kingdom they find themselves amid a conflict between the mermaids and an opposing tribe that has driven them away from their home planet thousands of years ago. Doraemon, Nobita, and their friends must then aid Sophia find a legendary sword that might bring peace once again to the seas. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aggressive Retsuko: We Wish You a Metal Christmas', 'ONA', 1, 'Completed', '2018-12-20', NULL, '7', 'Red panda Retsuko, worked to the bone, unleashes her frustration in the form of death metal. Lately, though, she''s found another joy—getting the most likes possible on her Instagram posts. In fact, it is said that social media attention can release endorphins. As Christmas falls upon the city, Retsuko''s hunger for validation only grows, pushing her to find new ways to embellish and sugarcoat her otherwise drab life for the internet to see.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaidan Restaurant', 'TV', 23, 'Completed', '2009-10-13', '2010-06-08', '7', 'TV Asahi announced a new kids anime "Kaidan Restaurant (Thriller Restaurant)" based on a picture book. Each episode will consist of three stories or "dishes": the appetizer, the main dish, and dessert. The first two "dishes" will deal with an ordinary sixth-grade schoolgirl named Ako Ozara and the bizarre occurrences that befall her classmates. The third "dish" will be a standalone short ghost story told by Ako and her friends.', 1030, 'https://cdn.myanimelist.net/images/anime/11/17905.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Inu to Neko Docchi mo Katteru to Mainichi Tanoshii', 'TV', 24, 'Completed', '2020-10-03', '2021-03-27', '7', 'Matsumoto-san owns an innocent dog and an adorably devious cat. Laughing and crying ensue as they all live daily life together.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ajin Part 3: Shougeki', 'Movie', 1, 'Completed', '2016-09-23', NULL, '7', 'For high schooler Kei—and for at least forty-six others—immortality comes as the nastiest surprise ever.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mnemosyne: Mnemosyne no Musume-tachi', 'TV', 6, 'Completed', '2008-02-04', '2008-07-07', '7', 'Immortality is something many people would wish for. But would it be such a coveted ability if people knew they would be subject to countless attacks because of it? Such is the case for Rin Asougi, an immortal private investigator, because there is no shortage of people who want her dead. Over the centuries, she has met many grisly ends, but each time, she returns to life as if nothing had happened.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Subete ga F ni Naru', 'TV', 11, 'Completed', '2015-10-09', '2015-12-18', '7', 'In a research facility hidden away on a remote island, genius programmer Shiki Magata has lived as a recluse for years. She rarely sees guests, but associate professor Souhei Saikawa and university student Moe Nishinosono still seek her out. However, their meeting is cut short when they are caught up in a locked-room murder mystery. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Long Zhi Gu: Poxiao Qibing', 'Movie', 1, 'Completed', '2014-07-31', NULL, '7', 'The land of Altera has observed an uneasy peace for years among Humans, Elves and Evil beasts who are loyal to the legendary Black Dragon. But the Black Dragon begins to stir from its hibernation, sending the Beasts marching across Altera. With a beast conquest perilously close, a small group of Humans and Elves unite to try to find a secret hidden road to the Black Dragon''s cave and destroy it. But the fate of all of them may be in the hands of the young warrior Lambert, who must summon the confidence and skill to face the Black Dragon himself just when all may be lost.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Asura Cryin'' 2', 'TV', 13, 'Completed', '2009-10-01', '2009-12-24', '7', 'Following the first season, Tomoharu is now faced with a dilemma: if he doesn''t form a contract with an "akuma," he risks losing his dear friend Takatsuki. However, doing so would compromise his own existence as it would result in him and his ghost friend Misao becoming an Asura Cryin''—mankind''s biggest threat, according to their school''s presidents. To make the decision even harder, Tomoharu and Misao have recovered some of their past memories—memories of a world that they didn''t even know existed.', 786, 'https://cdn.myanimelist.net/images/anime/9/50897.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuma Kuma Kuma Bear', 'TV', 12, 'Completed', '2020-10-07', '2020-12-23', '7', 'After fanatically playing the VRMMO World Fantasy Online for almost a year, the shut-in yet relatively affluent 15-year-old Yuna receives a bear costume from the game''s administrators. The outfit, while somewhat embarrassing to wear, turns out to have overpowered stats and effects that make her character significantly more powerful. After accepting the bear equipment, she finds herself transported to another in-game world that prevents her from returning to reality.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tetsuwan Birdy Decode: The Cipher', 'OVA', 1, 'Completed', '2009-07-22', NULL, '7', 'Birdy uses her pin-up alter ego to help Tsutomu make a love connection with Sayaka, but everything goes horribly wrong when a Federation marionette is added to the equation!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cuticle Tantei Inaba', 'TV', 12, 'Completed', '2013-01-04', '2013-03-22', '7', 'In a world where half-human, half-animal chimeras live and work alongside normal people, there are sure to be a few bad apples in the bunch. Unfortunately, half-human criminals means non-human clues that often leave the police stumped. That''s where lone wolf detectives like Hiroshi Inaba come in. He''s literally part wolf and has the amazing ability to extract critical information just by examining or tasting a sample of someone''s hair! Of course, that ability has also resulted in Inaba having a little bit of a hair fetish, but that doesn''t seem to be a problem for his two assistants. (Well, at least the cross-dressing one isn''t complaining much.) And it''s nothing compared to the strange tastes of Inaba''s nemesis, the omnivorous (and half goat) crime boss Don Valentino, who has an appetite for green legal tender instead of tender young greens! Inaba''s sworn to cut Valentino out of the criminal flock before the Don can wolf down more ill-gotten dough, but he''s going to have to chew his way through a lot of evidence to get his goat. Can sheer dogged detective work put the baaaaad guys behind bars?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nanatsu no Taizai: Funnu no Shinpan', 'TV', 24, 'Completed', '2021-01-13', '2021-06-23', '7', 'After the Kingdom of Liones faces a new threat, the Seven Deadly Sins split up in order to defeat an enemy force spanning Britannia. With their members divided, they face 3 powerful foes, attempt to rescue the lost part of a dear friend, and begin their rescue of Elizabeth.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aka no Kioku', 'ONA', 1, 'Completed', '2025-03-27', NULL, '7', 'Short directed by Kiyotaka Oshiyama in collaboration with Fukushima Prefecture''s general information magazine Fukushima Map''s Supporter Association to promote the appeal of the prefecture to more people.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hyakushou Kizoku 2nd Season Specials', 'Special', 2, 'Completed', '2025-04-23', NULL, '7', 'Specials included with the DVD release of the second season of Hyakushou Kizoku bundled with volume 8.1 of the manga.', 681, 'https://cdn.myanimelist.net/images/anime/1806/150091.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('A-Rank Party wo Ridatsu shita Ore wa, Moto Oshiego-tachi to Meikyuu Shinbu wo Mezasu.', 'TV', 24, 'Completed', '2025-01-12', '2025-06-29', '7', '"I can''t do this anymore!" Yuke Feldio, a red mage, just left his adventurer A-Rank party. After being mistreated as a handyman and ridiculed for five years, he finally snapped! And so began his desolate, unemployed life... or so he thought! Through a stroke of luck, Yuke is welcomed into an all-female adventurer party comprised of his former students!! As they defeat dungeons one after another, Yuke''s true strength is gradually revealed! As it turns out, this red mage wields extraordinary magic and skills?!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tensei shitara Slime Datta Ken: Kanwa - Luminous Memories', 'Special', 1, 'Completed', '2024-08-10', NULL, '7', 'Recap of Tensei shitara Slime Datta Ken 3rd Season.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuroiwa Medaka ni Watashi no Kawaii ga Tsuujinai', 'TV', 12, 'Completed', '2025-01-07', '2025-03-25', '7', 'There is not a single room that Mona Kawai enters where she does not become the center of attention—dealing with this everlasting spotlight is but a fact of her daily life. Mona''s absolute confidence in her own charms, however, is shaken when she meets Medaka Kuroiwa, a recent transfer student to her highschool. Unlike all other classmates who constantly fawn over her, Medaka frowns every time they interact. Seeing his disinterest as something to be rectified, Mona pulls out all the stops in the hopes of winning Medaka over, only to be met with one stern face after another.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tougen Anki', 'TV', 24, 'Airing', '2025-07-11', '2025-12-26', '7', 'Long ago, demon-like creatures known as Oni butchered humans and brought on destruction solely for their own delight. A lone man named Momotarou opposed these gruesome, near-invincible monsters, but the war against them was just beginning.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tensei Akujo no Kuro Rekishi', 'TV', 12, 'Airing', '2025-10-09', '2025-12-25', '7', 'Konoha Satou has a dark history. After all, she spent her teen years writing self-indulgent fantasy romance fics-like her Dark History. But since she''s become its most despicable villainess, remembering every last detail is now a matter of life-and-death. Having avoided the first couple of death flags, Satou''s suddenly left in the dark when a mysterious stranger returns from the Lily Kingdom-a character she doesn''t recall writing in the original script. Although Yomi claims to be her ally, can Satou really trust a character she knows nothing about in such a dangerous world?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hitoribocchi no Isekai Kouryaku', 'TV', 12, 'Completed', '2024-10-04', '2024-12-20', '7', 'High school student Haruka has always been a content loner. One day, he and his class are abruptly transported to another world and given skill points to use when choosing from an assortment of abilities and magical powers. Unfortunately, Haruka arrives last, and he can only use his points on the seemingly impractical abilities the others had no interest in. Although he is on his own again and must adjust to his new life by himself, he much prefers it that way.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shangri-La Frontier: Kusoge Hunter, Kamige ni Idoman to su - Saishin Wa made Maruwakari! Chousoku Digest', 'Special', 1, 'Completed', '2024-01-14', NULL, '7', 'Recap of the first 14 episodes of Shangri-La Frontier: Kusoge Hunter, Kamige ni Idoman to su with new narration by Sunraku, Pencilgon, and OiKatzo.', 152, 'https://cdn.myanimelist.net/images/anime/1508/140903.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nanatsu no Taizai: Ensa no Edinburgh Part 2', 'ONA', 1, 'Completed', '2023-08-08', NULL, '7', 'The second part of Nanatsu no Taizai: Ensa no Edinburgh.', 559, 'https://cdn.myanimelist.net/images/anime/1597/137276.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Danjo no Yuujou wa Seiritsu suru? (Iya, Shinai!!)', 'TV', 12, 'Completed', '2025-04-04', '2025-06-20', '7', 'Yuu Natsume met Himari Inuzuka in middle school while trying to sell his accessories made with preserved flowers. When Yuu told her about his dream to open a shop to sell his creations, Himari decided to help him. Now, in their second year of high school, Yuu sells his accessories online thanks to Himari modeling and promoting them. As Yuu''s best friend, Himari declares that if his ambition does not come to fruition by the time they turn thirty, she will have to marry him herself.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saikin Yatotta Maid ga Ayashii', 'TV', 11, 'Completed', '2022-07-24', '2022-10-09', '7', 'The maid Lilith, hired to look after young Yuuri and his family''s mansion, seems highly suspicious: she is too good to be true. Every dish she serves turns out to be delicious, the whole residence sparkles after she cleans it, and all the clothing has given off a pleasant scent since she started doing the laundry. Furthermore, her devilishly beautiful eyes only serve to heighten Yuuri''s suspicions. Is Lilith perhaps a witch or a sorcerer? Yuuri cannot figure it out.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ramen Daisuki Koizumi-san', 'TV', 12, 'Completed', '2018-01-04', '2018-03-22', '7', 'From standing in the sun for hours to traveling miles away from home, gorgeous high school student Koizumi stops at nothing to fulfill her desire for ramen. But these previously solo trips soon change when Koizumi''s classmate Yuu Oosawa develops an infatuation with her, and begins to join Koizumi uninvitedly on her adventures. As Yuu continues to be shocked by Koizumi''s enormous appetite, she learns about the endless variety of ramen from, arguably, its greatest connoisseur ever!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Soukou Kihei Votoms: Pailsen Files Movie', 'Movie', 1, 'Completed', '2009-01-17', NULL, '7', 'Alternative release of Armored Trooper Votoms: Pailsen Files OVA. Was aired 2 years later. Created by the original staff of the series, with an all new story about the end of the 100 year war.', 1022, 'https://cdn.myanimelist.net/images/anime/5/18067.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Okusama ga Seitokaichou!+!', 'TV', 12, 'Completed', '2016-10-02', '2016-12-18', '7', 'Some time has passed since student council president Ui Wakana and vice president Hayato Izumi got married due to the agreement their parents made. While they still try to avoid unnecessary attention by keeping their unusual relationship a secret from the public, the two frequently misunderstand each other''s desires. However, as Ui and Hayato continue working in the school''s student council and spending time together at home, the peculiar couple gradually grows closer.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ojisan to Marshmallow', 'TV', 12, 'Completed', '2016-01-08', '2016-03-25', '7', 'Habahiro Hige is a simple-minded older man who works an office job and is an enthusiast of Tabekko Marshmallows. His days often consist of being teased by his 24-year-old colleague Iori Wakabayashi, who uses his obsession to her advantage: from eating them in front of his face, to buying out his favorite brand from the convenience store, and even embarrassing him in front of their boss. Although her friends cannot fathom what she sees in him, she just cannot get over his marshmallow-like, fluffy frame. No matter the lengths it takes, Iori will find a way to get his attention.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cardfight!! Vanguard G Z', 'TV', 24, 'Completed', '2017-10-08', '2018-04-01', '7', 'Fourth season of Cardfight!! Vanguard G series.', 621, 'https://cdn.myanimelist.net/images/anime/1335/125017.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('7 Seeds', 'ONA', 12, 'Completed', '2019-06-28', NULL, '7', 'Imagine this: you are living a normal day in your life. Maybe you are out with friends, eating your family''s home-cooked meal or spending time with your girlfriend. When you next wake up, you are suddenly thrust into a strange, new world, surrounded by five strangers on a rapidly sinking boat in the middle of a storm.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('NG Knight Ramune & 40 EX: Biku Biku Triangle Ai no Arashi Daisakusen', 'OVA', 3, 'Completed', '1991-07-21', '1991-11-21', '6', 'Lamune has returned to Earth with no memory of his adventures on Hara-Hara world and Doki-Doki space. The remains of Gobuhriki find their way to Earth, and awaken the spirit of Don Harumage. While Cocoa builds a fighting vehicle with stuff she finds around Tokyo, Milk and Leska set off to find Lamune and Da Cider to save the day before the new Gobuhriki is revived and destroys the Earth. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oretachi ni Tsubasa wa Nai: Hadairo Ritsu Kyuuwari Zou!?', 'OVA', 1, 'Completed', '2011-06-24', NULL, '6', 'An OVA bundled with the non-adult version of the OreTsuba PC game. The OVA has more fan service than the TV series (what they call, "nakedness plus 90%").', 612, 'https://cdn.myanimelist.net/images/anime/3/64495.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Odd Taxi Movie: In the Woods', 'Movie', 1, 'Completed', '2022-04-01', NULL, '6', 'October 4 marks the fateful day when a high school girl vanished, triggering an unpredictable series of events. In order to unravel the mystery behind the girl''s disappearance, all of the key witnesses connected to the case recount the events leading up to and following the crime. As the pieces to the story come together, they all seem to be connected to one individual—taxi driver Hiroshi Odokawa.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boku no Chikyuu wo Mamotte: Kiniro no Toki Nagarete', 'Special', 1, 'Completed', '2001-10-24', NULL, '6', 'Please Save My Earth Music Image Video: The Passing of the Golden Age contains six music videos with footage not seen in the OVA and scenes taken from the manga, as well as a slightly different version of the OVA ending sequence, and the ending credits for the image videos.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Baraou no Souretsu', 'TV', 24, 'Completed', '2022-01-09', '2022-06-26', '6', 'Richard Plantagenet has dedicated his whole life to becoming strong enough to fight alongside his father, the Duke of York. Together they have waged war to reclaim the right to the throne of England from King Henry VI and the House of Lancaster. However, the young Richard hides a secret—one that his mother scorns him for, which the cruel voices in his head never fail to remind him of. Even amid his personal turmoil, he is fortunate to find solace in the light of his father''s love. But when the War of the Roses takes a turn for the bloodier, the fervent ambitions of Richard grow while his old loyalties splinter, threatening to taint his family''s path to glory.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('High School Mystery: Gakuen Nanafushigi', 'TV', 41, 'Completed', '1991-04-12', '1992-03-13', '6', 'Mizuki Ichijo is a junior student at Kosen high school. Her grandmother was a medium and she experiences various psychic and mysterious phenomena which occur at the school: accidents, suicides, bullying, resentment, romance and more. She is befriended by the third year student Meiko Tsukikage, and together they attempt to solve the mysteries.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bakusou Kyoudai Let''s & Go Special', 'Special', 1, 'Completed', '1996-12-30', NULL, '6', '', 1117, 'https://cdn.myanimelist.net/images/anime/13/27281.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Black Magic M-66', 'OVA', 1, 'Completed', '1987-06-28', NULL, '6', 'When Sybel, a freelance reporter, discovers a military plane crash, she is thrilled by the prospect of getting her hands on the latest inside scoop. However, she is unaware that the plane was carrying two top-secret prototype android assassins who will stop at nothing to destroy their target. As the military frantically tries to clean up its mess, Sybel races against time to find and protect the robots'' targeted victim—all while documenting the military''s misconduct—before it is too late.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Grisaia: Phantom Trigger', 'TV', 13, 'Completed', '2025-01-02', '2025-03-27', '6', 'Several years after The Fruit of Grisaia...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dianqi Shaonu', 'ONA', 12, 'Completed', '2023-04-11', '2023-06-20', '6', 'Liang Xigua is a poor young man struggling to make a living in the cracks of the city. One day, his old refrigerator, which had been with him for many lonely summers, took on a human form and intervened in his life. They confront each other over food, struggle to make ends meet, drag each other down, and support each other, resulting in lots of ludicrous daily stories. Xigua gradually realizes that he is not the only one who has awakened the life of the appliance.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toaru Ossan no VRMMO Katsudouki', 'TV', 12, 'Completed', '2023-10-03', '2023-12-19', '6', 'A new type of VRMMO called "One More Free Life Online" is out. He logs in as a young boy avatar called "Earth." Taichi Tanaka (38, single) has a regular office job and enjoys playing video games in his free time. In a world where the player is free to do as they wish, he decides to master a skill that''s been deemed to be useless! He makes potions that are too much of a hassle to make, cooks food that is excessively too good, and uses bizarre original weapons to hunt monsters...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dongitsune CMs', 'Special', NULL, 'Airing', '2017-11-11', NULL, '6', 'Commercials for Nissin''s Donbei Kitsune Udon.', 849, 'https://cdn.myanimelist.net/images/anime/1424/129944.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xian Wu Cangqiong', 'ONA', 48, 'Completed', '2022-07-03', '2022-11-20', '6', 'There are many dynasties in Yongxian Continent. In order to strengthen the body and prolong life, the people here have always maintained the tradition of Xianwu fellow practitioners. Once the practitioners reach the peak of martial arts, they will ask about Xiandao. The young Su Yu, who suffered a severe accident at a young age, changed his name and changed his surname, but he was still in a hurry, but he was unexpectedly reborn back to his youth. Foreseeing that the family is about to fall, in order to protect his family and relatives, Su Yu decided to work hard and practice the secret methods of Xianmen he learned in his previous life.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shuumatsu no Walküre Mini Anime', 'ONA', 14, 'Completed', '2021-07-27', '2021-10-01', '6', 'Short episodes with super-deformed characters posted on the official Twitter account and on Warner Bros. Japan.', 39, 'https://cdn.myanimelist.net/images/anime/1899/116794.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Age: Blood Mage no Seisen', 'Movie', 1, 'Completed', '2012-02-11', NULL, '6', 'In a time of darkness and barbarism, the Chantry has arisen - a religious order seeking to bring stability to a world corrupted by sinister magic. Led by the Divine, the Chantry''s Templar warriors ruthlessly restrain the Mages and their magical cabals. But when the Templars fail, the most elite order of the Chantry takes charge - the Seekers!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hello Kitty: Ringo no Mori no Fantasy', 'TV', 13, 'Completed', '2006-04-04', '2006-09-19', '6', 'Kitty and Mimmy come upon the Apple Forest thanks to the help of a forest fairy. The fairy kingdom welcomes them as the "Twin Heroines" and ask that they save the princess. The key to the rescue is a golden apple and so the sisters'' adventure begins.', 90, 'https://cdn.myanimelist.net/images/anime/10/32139.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kagaku Bouken-tai Tansar 5', 'TV', 34, 'Completed', '1979-07-27', '1980-03-28', '6', 'In 1999, a special mystery/paranormal investigative unit consisting of five youths is formed. The series uses a mix of real tokusatsu footage (vehicle scenes) and animation (character drama).', 974, 'https://cdn.myanimelist.net/images/anime/1548/96339.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jinki:Extend', 'TV', 12, 'Completed', '2005-01-06', '2005-03-24', '6', 'Aoba is a young girl who loves to build models of robots. She lived alone with her grandmother until her grandmother passes away. Shortly after she is kidnapped and brought to a secret base where she discovers a huge robot. The piloted robots fight against Ancient-Jinki in The Grand Savanna, but the true meaning behind the fights is hidden. Aoba works hard at the base so one day she can pilot one of the robots and discover these secrets.', 1162, 'https://cdn.myanimelist.net/images/anime/3/44792.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiang Qi Wang', 'TV', 26, 'Completed', '2006-01-01', NULL, '6', 'Features preteens involved in the competition and challenges in the world of Chinese chess.', 384, 'https://cdn.myanimelist.net/images/anime/3/27196.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Licca-chan Fushigi na Fushigi na Yunia Monogatari', 'OVA', 2, 'Completed', '1990-11-23', NULL, '6', 'When Licca Kayama''s father returns from a trip to Paris, she is thrilled to see that he has brought back her favorite piano. However, she is disappointed about the stuffed dodo bird he gave her as a gift. One day, when Licca accidentally falls into the piano, she is transported to the magical world of Yunia. Within Yunia, the dodo gains the ability to speak and helps Licca find a way home.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Golden Douga Gekijou Specials', 'Special', 7, 'Completed', '2018-07-27', '2023-09-27', '6', 'Extra episodes included on volumes 1 and 7-12 of the BD/DVD.', 1092, 'https://cdn.myanimelist.net/images/anime/1194/121164.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ganglion', 'TV', NULL, 'Airing', '2025-10-03', NULL, '6', 'Early 2000s Tokyo. Isobe, a combatant for the evil corporation Ganglion, spends his days on the battlefield. Whether it''s the "Tokyo Cedar Pollen Operation" or the "Mount Fuji Demolition Plan," he faces off in nothing but a bodysuit, only to be crushed by the hero Hopeman time and again. As he struggles under unreasonable bosses during the dawn of compliance, his story unfolds—a workplace drama dedicated to all who work, following the bittersweet life of a salaryman soldier.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kamitsubaki-shi Kensetsuchuu.: Witchling - Zenpen', 'Special', 1, 'Completed', '2025-07-03', NULL, '6', 'Episode 0 of Kamitsubaki-shi Kensetsuchuu.', 806, 'https://cdn.myanimelist.net/images/anime/1509/150872.jpg');
