INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sea Cat', 'Movie', 1, 'Completed', '1988-01-01', NULL, '6', 'An orphaned cat adrift at sea is raised by an otter to live in the ocean. They live together in peace until one day they encounter a submarine...', 638, 'https://cdn.myanimelist.net/images/anime/1796/137348.jpg');
