INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bloody Escape: Jigoku no Tousou Geki', 'Movie', 1, 'Completed', '2024-01-05', NULL, '6', 'After human experimentation turns Kisaragi into a cyborg, he finds himself pressured by multiple organizations: An undying convent of vampires bent on the conquest of Tokyo, and an immortal order of knights, and a group of Yakuza, sword to avenge the killing of their leader. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bosanimal', 'TV', 96, 'Completed', '2023-04-03', '2023-09-14', '6', 'A short anime series based on Sanrio''s Bosanimal character line.', 1178, 'https://cdn.myanimelist.net/images/anime/1360/133846.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tousouchuu: Great Mission', 'TV', 97, 'Completed', '2023-04-02', '2025-03-30', '6', 'Due to Earth''s increasing climate crisis, humanity has developed futuristic technology to migrate to the Moon. Tomura Sawyer works as a courier in the higher areas, saving money for his little brother, Haru, who suffers from Smoky Moon Disease - a sickness produced by the smoke and polution from the lower areas. The two siblings dream of moving to the higher, cleaner areas to treat this disease.
