INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nikoniko, Pun', 'TV', 40, 'Completed', '1988-01-01', NULL, '5', 'Anime spin-off from a children''s show that featured out-of-work actors dressed up as a giant mouse, penguin, and lion, itself part of the Japanese "Watch with Mother" TV strip for the preschool audience.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaba Enchou no Doubutsuen Nikki', 'Special', 1, 'Completed', '1981-08-23', NULL, '5', 'Aging zoo keeper Toshio Nishiyama acquires two young trainees: short-tempered former chef Takeshi Ishizawa and gentle vet Ichiro Hasegawa. Both are surprised by the difficulties they face in a deceptively easy job but persevere through troubles such as an escaped pelican, a dying camel, and the birth of a hippo. A semi-autobiographical TV special of anecdotes from real-life Tobu Animal Park zookeeper Toshio Nishiyama, who appears at the beginning and end of the film to talk about his love for animals-and to reveal that Ishizawa is in fact a projection of his younger self.
