INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zhege Nianji Huan Neng Dang Daxia Ma', 'ONA', 10, 'Completed', '2023-01-05', '2023-03-02', '5', 'After the Lao Bai left the big city, he returned to his hometown Chang''an with Yanzi (Yanshan Xue) to live. While working hard to run a Chang''an supermarket for their former heroic dreams, they met community neighbors: A Meng, A Hun, Long Zi, Xiao Man, Long Shu, You You, and Xiao Wu.
