INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Rascal', 'TV', 12, 'Completed', '2014-01-09', '2014-03-27', '5', 'Assistant Detective Rascal travels around the world with Uncle Po to check various mysteries.', 607, 'https://cdn.myanimelist.net/images/anime/5/56615.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sirotsumekusa', 'Movie', 1, 'Completed', '2020-09-19', NULL, '5', 'Ao Sirotubaki, who works at "Hanagumi", was living a normal and quiet life as a flower shop owner. However, her twin sister, Beni Sirotubaki, contacts Ao for the first time in six years. What happened to the sisters six years ago, and what do the two reunited talk about? The lives of the sisters begin to move greatly as their feelings intermingle. A shocking one-situation suspense movie developed in the world''s first all-cast VTuber!!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wansa-kun OVA', 'OVA', 1, 'Completed', '1989-01-01', NULL, '5', 'Compilation OVA of the Wansa-kun series.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sabaku no Kaizoku! Captain Kuppa', 'TV', 26, 'Completed', '2001-08-13', '2002-02-11', '5', 'Sometime in the future, the world was completely dried up and became all desert. They had little rivers and lakes left, which villians and dangerous animals lived. Water has become the most valueable thing on the world. Whoever can control water will rule over the world.  
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Katta-kun Monogatari', 'Movie', 1, 'Completed', '1995-07-12', NULL, '5', 'An anime starring Katta-kun, a real-life pelican who inhabited the Tokiwa Park in Ube.
