INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kennedy Knights Pilot Film', 'Movie', 1, 'Completed', '2003-03-21', NULL, '5', 'Unaired pilot movie based on the Kennedy Knights manga by Mikiya Mochizuki.', 986, 'https://cdn.myanimelist.net/images/anime/1037/146527.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('DenDekaDen PV', 'Special', 1, 'Completed', '2024-08-06', NULL, '5', 'Passing through the Torii gates of a shrine in Kyoto, seven souls with unwavering conviction, were reborn in the DenDenGarden. Now they must fight epic duels to become gods.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Naruheso-kun Pilot', 'Special', 1, 'Completed', '1999-11-21', NULL, '5', 'A pilot film for the manga Naruheso-kun by Aooni Yamane. It was included with the Eiken TV Anime Shudaika Taizenshuu LD and DVD.', 986, 'https://cdn.myanimelist.net/images/anime/1901/146537.jpg');
