INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pole Princess!! Self Introduction', 'ONA', 7, 'Completed', '2022-12-09', '2023-03-10', '5', 'Self-introductions for each character posted to the official YouTube Channel.', 1009, 'https://cdn.myanimelist.net/images/anime/1100/146522.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hiro & Hana: Rakko no Okiniiri', 'Movie', 1, 'Completed', '2018-10-01', NULL, '5', 'Hiro and Hana own a little café. One day a sad sea otter visits them for some tea and refreshments.', 852, 'https://cdn.myanimelist.net/images/anime/1814/142724.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eisen Flügel', 'Movie', 1, 'Upcoming', NULL, NULL, '5', 'In a world where dragons rule the skies, mankind still dreams about taking to the skies and dominating the heavens in their place. Even during wartime, the passionate young pilot Karl Schuniz pursues his dreams, taking up his steel wings—the revolutionary new aircraft, the Blitz Vogel—to challenge the Kaiser Drache, the fastest dragon capable of supersonic flight.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eiga no Yousei: Fill and Moo', 'Movie', 1, 'Completed', '2017-01-01', NULL, '5', 'Fill is a film fairy who lives alone in ruins. She looks lonely. One day, a projector shows up in front of her, and suddenly old films appear among the sound of rolling film. Fill is roped into the screen by a film seed named Moo, and the journey of Fill and Moo begins.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pacalien', 'Movie', 1, 'Completed', '2017-06-03', NULL, '5', 'Romeros is an alien investigator who looks like an alpaca. When he lands on Earth, he finds his spaceship damaged and becomes disconnected with his planet. He arrives on a mountain where a person wearing a weird mask is waiting for him.
