INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Furiten-kun (1990)', 'OVA', 2, 'Completed', '1990-06-21', '1990-07-21', '5', 'Continuation of the everyday life adventures of the avid mahjong player Furiten-kun.', 484, 'https://cdn.myanimelist.net/images/anime/9/53547.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Only You: Viva! Cabaret Club', 'TV', 15, 'Completed', '1998-11-04', '1998-11-27', '5', 'Based on a manga by Fujinami Toshihiko, serialized in Weekly Spa! between 1998 and 1999. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ijiwaru Baasan (1996)', 'TV', 46, 'Completed', '1996-03-19', '1997-06-13', '5', 'Grandma is a nasty and manipulative thing most of the time, causing endless trouble for her son-in-law and daughter, her grandchildren, and her neighbours.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ijiwaru Baasan', 'TV', 39, 'Completed', '1970-09-03', '1971-08-18', '5', 'Based on a 1966 manga by Sazae-san creator Hasegawa Machiko.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dotanba no Manners', 'TV', 283, 'Completed', '1984-10-03', '1987-04-09', '5', 'An introduction to etiquette through the hapless antics of Mr. Dotanba, who manages to put his foot in it in innumerable social situations.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nihon Meisaku Douwa Series: Akai Tori no Kokoro', 'TV', 26, 'Completed', '1979-02-05', '1979-07-30', '5', 'A collection of children''s stories originally printed in the popular magazine Akai Tori, which was published from 1918 to 1936.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doubutsu Mura Monogatari', 'TV', 100, 'Completed', '1970-03-30', '1970-07-21', '5', 'A short kids series featuring cute animal stories.
