INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Neko no Dayan: Fushigi Gekijou', 'TV', 30, 'Completed', '2016-10-01', '2017-04-20', '5', 'Third season of Dayan the Cat. The shorts will be "theatrical-style," with a curtain opening on the everyday adventures of Dayan and his friends.', 457, 'https://cdn.myanimelist.net/images/anime/10/81109.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga Tetsudou no Yoru: Fantasy Railroad in the Stars Special', 'Special', 1, 'Completed', '2007-02-23', NULL, '5', 'A BD/DVD special of Ginga Tetsudou no Yoru: Fantasy Railroad in the Stars. It contains new animation and further explains star constellations.', 450, 'https://cdn.myanimelist.net/images/anime/7/81092.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Taka no Tsume 8: Yoshida-kun no Batten File', 'Movie', 1, 'Completed', '2016-08-20', NULL, '5', 'The eighth film in the Taka no Tsume film series.', 214, 'https://cdn.myanimelist.net/images/anime/12/80927.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xing You Ji', 'TV', 26, 'Completed', '2011-10-30', NULL, '5', 'In an era where everyone is free to travel in space, there still exists an area in the universe where all lives and hopes are forbidden - the black hole. This ruthless star devours anything that comes in close contact, whether it is life, substance, or even light. The most avid adventurers don''t dare to even mention going there, because of the risk. Until one day, a man in fiery red clothing declared to the whole universe: "In the deepest part of black hole, lies a mysterious place called Rainbow Sea. A place full of precious stones, rivers of gold and rainbow covered skies. Anyone who gets there gets all their wishes granted." This declaration ignited the enthusiasm of the whole universe, attracting people from everywhere. They followed the man in red into the black hole, and ultimately no one came back. The adventurers that vanished with the man in red were called the descendants of the loathful "Red Devil" and Rainbow Sea was then considered as history''s biggest lie ever.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kahei no Umi', 'Movie', 1, 'Completed', '2005-07-16', NULL, '5', 'Biopic of Takadaya Kahei.', 241, 'https://cdn.myanimelist.net/images/anime/7/80827.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mo Jing Lieren 3rd Season', 'ONA', 29, 'Completed', '2016-07-14', '2017-01-26', '5', 'The series takes place on a fantastical world where crystals can provide great strength. Their value has led to to the rise of a unique profession: crystal hunting.', 1001, 'https://cdn.myanimelist.net/images/anime/7/81462.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mo Jing Lieren 2nd Season', 'ONA', 26, 'Completed', '2015-04-26', '2015-12-31', '5', 'The series takes place on a fantastical world where crystals can provide great strength. Their value has led to to the rise of a unique profession: crystal hunting.', 1001, 'https://cdn.myanimelist.net/images/anime/6/81461.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nana Moon', 'TV', 52, 'Completed', '2013-01-15', NULL, '5', 'There is a mysterious Nana Moon in the universe with lovely little moonies as residents. One day, a girl named Coco from the Earth suddenly appeared, which reminded the moonies of an old saying that whenever a catastrophe would happen, a human with magic power will surely come from the Earth to help them discover 7 treasures to rescue Nana Moon.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tokyo Onlypic', 'Movie', 1, 'Completed', '2008-08-08', NULL, '5', 'An omnibus film depicting 15 fictional sports events created by different directors. Onlypic stands for only + pictures (video).', 260, 'https://cdn.myanimelist.net/images/anime/9/80665.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kubbe Kort Animasjon', 'ONA', 24, 'Completed', '2013-04-24', '2014-03-30', '5', 'Johnsen Kubbe''s picture book adaptation. Each story is split into two videos titled "prequel" and "sequel" for a total of 24 episodes.', 260, 'https://cdn.myanimelist.net/images/anime/3/80650.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tayo-ui Jangnangam Adventure', 'Special', 1, 'Completed', '2019-04-01', NULL, '5', 'When Bella finds out that all the toys were not forgotten and was touched by Ace and Duri''s friendship, she decides to help other toys to find their friends(owners) back. But, it seems that Louie isn''t the lucky one to find his old friend, Kevin. Tayo and Lani decide to help Louie to find Kevin but there are adventures that they never thought of!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Go Go Smile Anime', 'Special', 6, 'Completed', '2013-04-01', '2014-02-01', '5', 'A music anime made for CBC''s Go Go! Smile! TV program.', 214, 'https://cdn.myanimelist.net/images/anime/2/80598.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Black Jack Specials: Inochi wo Meguru Yottsu no Kiseki', 'Special', 4, 'Completed', '2003-12-22', '2004-10-13', '7', 'Black Jack is the "Surgeon with the Hands of God," a mysterious young Japanese doctor who travels the world performing feats of miraculous surgical genius. Though all recognize his skill, Black Jack is widely hated, especially by the medical establishment, because he refuses to conform to rules of any kind, and because he charges outrageous fees for his services. Black Jack''s only companion is Pinoko, a child he created out of a special kind of tumor called a teratoma, who insists she is his wife.', 1021, 'https://cdn.myanimelist.net/images/anime/1879/120375.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zero no Tsukaima', 'TV', 13, 'Completed', '2006-07-03', '2006-09-25', '7', 'Louise Françoise Le Blanc de La Vallière is a self-absorbed mage in a world of wands, cloaks, and royalty. Although she studies at Tristain Academy, a prestigious school for magicians, she has a major problem: Louise is unable to cast magic properly, earning her the nickname of "Louise the Zero" from her classmates.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shaman King Specials', 'Special', 5, 'Completed', '2002-01-02', '2003-07-24', '7', 'Throughout the broadcast of Shaman King, many shorts (usually referred to as Shaman King omake and TV specials) were made on special days of the year related to spirits and the like. The omake were short stories that were made for humorous effect. Apparently, all of the omake fit into the story before the Shaman Fight 2nd round. Documents of the Shaman Fight was shown with a New Year''s omake as well. The TV Specials were aired after specific points of the story as well as on holidays. The specials were never dubbed in English, and, most likely, never will be. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dead Leaves', 'Movie', 1, 'Completed', '2004-01-16', NULL, '7', 'Shortly after waking up in an unknown street with no clothes or memories, Retro and Pandy team up and begin a life of thrill chasing and violence. Retro''s wild antics and Pandy''s carefree personality make them the perfect partners in crime to cause mayhem wherever they strike.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Soukou Kihei Votoms: Pailsen Files', 'OVA', 12, 'Completed', '2007-10-26', '2008-08-25', '7', 'OVA release from anime series "Armored Trooper Votoms" utilizing the latest in 3D CG animation. Created by the original staff of the series, with an all new story about the end of the 100 year war.', 1022, 'https://cdn.myanimelist.net/images/anime/4/5264.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Love Hina: Motoko no Sentaku, Koi ka Ken... "Naku na"', 'Special', 1, 'Completed', '2001-05-02', NULL, '7', 'Out of nowhere, Motokos'' sister (Tsuroko) appears and is ready to pass on the dojo. However, Motoko is still not quite as strong as her sister and when her big sister finds out about this, she gives Motoko an ultimatum- Motoko must beat her sister or marry Keitaro!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Witchblade', 'TV', 24, 'Completed', '2006-04-06', '2006-09-21', '7', 'Masane Amaha and her daughter Rihoko are on the run from a government child welfare agency that wants to take Rihoko away from her mother. They are caught and Rihoko is taken away. Meanwhile, Masane is attacked by an advanced weapon that can disguise itself as a human being. When faced with the danger, a strange light emits from her wrist and she transforms into a powerful being. She destroys the weapon and consequently becomes involved in a power struggle between powerful organizations, with her at the center of their attention. Because she holds the greatest power of them all, the legendary Witchblade.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Arte', 'TV', 12, 'Completed', '2020-04-04', '2020-06-20', '7', 'In the 16th century, the city of Florence booms with cultural and creative revival in celebration of the Renaissance. Arte, a delightful young lady from an aristocratic family, dreams of being an artist and contributing to the renewal of civilization. However, with her father''s death, she ends up losing the only person who believed in her passion for art. Now she is expected to marry a nobleman and live as a refined housewife without disgracing her family name. Reluctant to accept her fate, the headstrong Arte steps into the streets in search of a master artisan to take her on as an apprentice.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lupin III: Part 6', 'TV', 24, 'Completed', '2021-10-17', '2022-03-27', '7', 'The infamous Arsene Lupin III takes his gang of thieves to Great Britain to investigate the existence of the Raven''s hidden treasure. The Raven, an underground society rumored to be pulling the strings behind the British government, has evaded Lupin''s grasp for nearly 10 years. But finding clues proves difficult when he is pursued by not only Interpol''s Inspector Kouichi Zenigata but also the MI6, Scotland Yard, and Britain''s finest: the consulting detective Sherlock Holmes, who appears to have his own score to settle with the gentleman thief.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Air Movie', 'Movie', 1, 'Completed', '2005-02-05', NULL, '7', 'Centuries ago, Kanna, a princess and the last of a winged race, was held prisoner in a castle as she was feared by the rest of the world. However, when she met a soldier named Ryuuya, she fell in love with him and told him of her wishes to see the outside world and to find her mother. Ryuuya attempted to fulfill these wishes. However, his efforts were in vain as Kanna was sealed in the sky through magic and cursed to be in pain for all eternity.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Re:cycle of the Penguindrum', 'Movie', 2, 'Completed', '2022-04-29', '2022-07-22', '7', 'Compilation of Mawaru Penguindrum, including new scenes.', 143, 'https://cdn.myanimelist.net/images/anime/1199/120216.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Housekishou Richard-shi no Nazo Kantei', 'TV', 12, 'Completed', '2020-01-09', '2020-03-26', '7', 'Possessing a deep knowledge of mineralogy, Richard Ranasinghe de Vulpian is a young and handsome British jewelry appraiser who owns a small shop in Japan. One fateful night, Seigi Nakata, a righteous college student, saves him from drunks who were harassing him due to his good looks. Upon learning of Richard''s identity, Seigi hires him to appraise a pink sapphire ring that was left behind by his deceased grandmother.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Goblin Slayer II', 'TV', 12, 'Completed', '2023-10-06', '2023-12-22', '7', 'Second season of Goblin Slayer.', 499, 'https://cdn.myanimelist.net/images/anime/1100/138338.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doraemon Movie 05: Nobita no Makai Daibouken', 'Movie', 1, 'Completed', '1984-03-17', NULL, '7', 'Having dreamed of being in a world of magic, Nobita and Doraemon used the what-if-telephone-booth gadget to turn the world into one that is based on magic instead of science. Little did they know that demons exist and threaten this magical world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Soukou Kihei Votoms: Red Shoulder Document - Yabou no Roots', 'OVA', 1, 'Completed', '1988-03-19', NULL, '7', 'After armored trooper pilot Chirico Cuvie  is given orders to transfer to Planet Odon, he and all of the other new recruits are sent into a simulated battle to test their abilities. However, this ''simulated battle'' turns out to be a serious fight to eliminate those without the necessary skills. Chirico survives along with just three others, despite the fact that he fought while injured. It soon becomes apparent that this is not the first time he has survived against incredible odds, a fact that Colonel Peruzen wishes to exploit. But is Chirico truly immortal? 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dr. Slump: Arale-chan', 'TV', 243, 'Completed', '1981-04-08', '1986-02-19', '7', 'Dr. Slump creates a little android girl, Arale, who is very strong, happy, and totally common senseless. They live in Penguin Village where the strangest things happen (e.g., the dawn is announced by a little pig wearing a basquee)
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Akuyaku Reijou nanode Last Boss wo Kattemimashita', 'TV', 12, 'Completed', '2022-10-01', '2022-12-17', '7', 'Aileen Lauren Dautriche''s life changes forever on the day her engagement with the crown prince Cedric Jeanne Elmir is nullified so he can be together with Lilia Rainworth. The event triggers Aileen''s memories from her past life—she has been reincarnated in an otome game as the villainess, who is destined to die in the final act. To prevent her predetermined demise, Aileen has only one option: to court the game''s last boss, Claude Jeanne Elmir—the proclaimed "Demon King" and Cedric''s half-brother—and marry him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('El Cazador de la Bruja', 'TV', 26, 'Completed', '2007-04-03', '2007-09-25', '7', 'Nadie is a bounty hunter with an attitude, and she''s got a lock on her next target: Ellis, a young amnesiac girl who is a suspect in the murder of a famous scientist. Nadie manages to apprehend Ellis, but on a whim, decides to accompany her to Wiñay Marka, a place which supposedly holds the key to unlocking Ellis''s memories and her mysterious past. However, Nadie cautions Ellis that this does not mean she will go free—once Ellis has found what she is looking for, Nadie will turn her over to the authorities. With Ellis''s connection to a gemstone called the Inca Rose as their only guide, the two set off on their journey south through Mexico to search for the mysterious "Eternal City" of Wiñay Marka.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Canaan', 'TV', 13, 'Completed', '2009-07-04', '2009-09-26', '7', 'Oosawa Maria is a Japanese photographer currently working in Shanghai, China. Along with her partner Mino, she searches for potential newsworthy stories throughout the city. When strange events occur at a local festival, Maria and Mino immediately investigate. Quickly, the two are immersed in a battle between unknown masked men and a strange, white-haired woman. Just when Maria is about to be caught in the crossfire, an old friend by the name of Canaan appears and helps Maria escape. But a sinister plot over a deadly virus soon develops, and Canaan learns she must confront her past if she wants any chance at stopping the perpetrator and saving her friends.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Spiral: Suiri no Kizuna', 'TV', 25, 'Completed', '2002-10-01', '2003-03-25', '7', 'Ayumu Narumi has lived all his life in the shadow of his famous detective brother, Kiyotaka. However, Kiyotaka disappeared two years ago, leaving behind his wife Madoka and Ayumu himself, along with a cryptic message about the "Blade Children."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kanashimi no Belladonna', 'Movie', 1, 'Completed', '1973-06-30', NULL, '7', 'The beautiful Jeanne marries a man named Jean, and the happy newlyweds make their way to the Lord''s castle with a cow''s worth of money for his blessings. However, the demonic Lord is unmoved by their offering, ignoring their desperate, impoverished pleas. The Lord''s wife offers an alternative: Jeanne must become the Lord''s conquest for the night in a ritual deflowering.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Groove Adventure Rave', 'TV', 51, 'Completed', '2001-10-13', '2002-09-28', '7', 'Fifty years ago, malevolent stones known as Dark Brings brought about the "Overdrive," a calamitous event that destroyed one-tenth of the world. In the present day, the nefarious organization Demon Card seeks the Dark Brings'' power for their all but innocent intentions. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gyakuten Saiban 6 Prologue', 'ONA', 1, 'Completed', '2016-03-17', NULL, '7', 'The country of Khura''in doesn''t have attorneys. Instead, the outcome of trials are decided by the oracles.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahoutsukai Sally', 'TV', 109, 'Completed', '1966-12-05', '1968-12-30', '7', 'Sally, the kind but mischievous princess of the Land of Magic, has developed an interest in the human world. Wanting to experience it for herself, she runs away and meets two girls her age—Yoshiko "Yocchan" Hanamura and Sumire Kasugano—at a department store. They quickly become friends and spend time at Sally''s mansion, which she conjured with magic.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kakutou Bijin Wulong', 'TV', 25, 'Completed', '2005-10-10', '2006-03-26', '7', 'At first glance, Mao Ran is a normal cute girl, but she is a master of a martial arts handed down by Mao family. One day, she is tricked by her grandfather, and forced to take part in the fighting match, "Prime Mat". First, she is reluctant to fight, but fighting against the rivals, she is gradually fascinated by the "fighting".
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Ball Z Movie 04: Super Saiyajin da Son Gokuu', 'Movie', 1, 'Completed', '1991-03-09', NULL, '7', 'Gohan Son and Piccolo are peacefully playing when they sense a powerful entity approaching Earth. It soon reaches everyone''s ears that this entity is in fact a small planet on a deadly collision course with Earth. Gokuu Son and Kuririn attempt to change the small planet''s path with a Kamehameha, but the attack fails and the two warriors are blown away. However, after coming very close to Earth''s surface, the object changes direction on its own and explodes soon after.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yume Senshi Wingman', 'TV', 47, 'Completed', '1984-02-07', '1985-02-26', '7', 'Hirono Kenta is your average geeky junior high school student. His childhood obsession has always been Tokusatsu and anime. In fact, he fancies himself as a "Hero of Justice" and often is seen running around in a makeshift costume of his own design called "Wing Man." Most of his fellow classmates thinks he''s just a crazy otaku, but his childhood friend Ogawa Miku thinks he''s a noble spirit.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tokyo ESP', 'TV', 12, 'Completed', '2014-07-12', '2014-09-27', '7', 'Rinka Urushiba works part time as a waitress to help out her unemployed father. By all accounts, her life in Tokyo is a relatively normal one—but her sense of normalcy begins to fade when she inexplicably sees a flying penguin one day. Chasing it all the way to the top of a building, she encounters more surprises, including flying goldfish and another person—a classmate named Kyoutarou Azuma—who can also see these strange things. After Rinka passes out when a goldfish phases through her, she wakes up an esper with the ability to phase her body through solid matter.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Love All Play', 'TV', 24, 'Completed', '2022-04-02', '2022-09-24', '7', 'In junior high, Ryou Mizushima and his friends join the badminton club on a whim. As he grows fond of the sport, Ryou works tirelessly to improve his badminton skills until he qualifies in the prefectural tournament. Lacking a coach who can bring out his full potential, he does not consider entering a high school with a strong badminton team. Instead, he plans on attending a local high school where he can play badminton for fun.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ryuugajou Nanana no Maizoukin PV', 'Special', 1, 'Completed', '2011-12-26', NULL, '7', 'Promotion video for Kazuma Ootorino''s light novel Ryuugajou Nanana no Maizoukin, commissioned by Enterbrain after Ootorino won the 13th Entertainment Awards Grand Prize (Entame Taishou) from the publisher''s light novel department.', 14, 'https://cdn.myanimelist.net/images/anime/11/47725.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Transformers: Car Robots', 'TV', 39, 'Completed', '2000-04-05', '2000-12-27', '7', 'The evil Gigatron has led his forces of Destrongers to Earth, where they seek to pillage the planet for its vast energy resources in order to fuel their war against the Autobots. If successful, the Destrongers will finally be able to tip the scale of power in the war to their favor, eliminating the Autobots and moving on to conquer the universe. To this end, the Destrongers kidnap the scientist Dr. Ohnishi, Earth''s leading scientist on energy and natural resources.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yaku nara Mug Cup mo', 'TV', 12, 'Completed', '2021-04-03', '2021-06-21', '7', 'The city of Tajimi is well-renowned for its Mino ware ceramics and being the hometown of Himeno Toyokawa''s mother. Considered a legend in the world of pottery, Himeno''s mother suddenly passed away when Himeno was four. However, her legacy lives on in the dozens of unique mugs that adorn the Toyokawas'' new restaurant in Tajimi.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Master Mosquiton ''99', 'TV', 26, 'Completed', '1997-09-30', '1998-03-31', '7', 'Catholic schoolgirl Inaho discovers that a vampire, Mosquiton, is feeding off of her classmates. So she stakes him, but he is revived after her blood comes in contact with the his remains. Mosquiton becomes her slave and also a history teacher. Together, along with Yuuki and Honou, the unlikely duo have many escapades and adventures. One of Inaho''s main goals is to find the mythical O-Part to make some money!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hamelin no Violin Hiki', 'TV', 25, 'Completed', '1996-10-02', '1997-03-26', '7', 'Trouble arises in Staccato one day. Demons show up and start to wreak havoc on the townspeople. The entire country seems to be suffering. The source of the problem is that the "barrier" which until now has kept the demons from crossing over to the human world, is weakening. The person who sustains it is losing her strength after holding it up for so many years. That person is Queen Horn of Sforzando. Hell King Bass is trying to break through the barrier and release their "supreme leader," Kestra (Orchestra). One whose power is unparalleled yet is trapped somewhere in the world of the humans.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Densetsu no Yuusha no Densetsu: Iris Report', 'Special', 1, 'Completed', '2010-10-14', NULL, '7', 'Recap episode. Includes re-edited footage from episode 1 up to episode 15. Iris is narrating along with Sion.', 1145, 'https://cdn.myanimelist.net/images/anime/11/26850.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chain Chronicle: Haecceitas no Hikari', 'TV', 12, 'Completed', '2017-01-08', '2017-03-26', '7', 'Set in the land of Yuguto, the people thought that the land they live is the size of the world, but it''s actually divided into several areas, each with a respective king. Even though there were small wars among areas, the kings had roundtable meetings to maintain peace and balance. It was until a dark group of dark monsters appeared...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('MARO17: Mada, Akirametenai Daro?', 'Special', 1, 'Completed', '2024-11-25', NULL, '7', '', 527, 'https://cdn.myanimelist.net/images/anime/1301/146648.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cat''s♥Eye', 'ONA', 12, 'Airing', '2025-09-26', '2026-01-30', '7', 'The protagonists of the series are the three Kisugi sisters—Hitomi, Rui and Ai—who run a café called Cat''s Eye. The sisters lead a double life as a trio of highly skilled art thieves, leaving cards with the name "Cat''s Eye" at the scene of their crimes. They steal works of art that belonged to their long-missing father, Heinz who was a famous art collector during the Nazi regime, in the hopes of him contacting them. Toshio, the police officer investigating this case is the fiancé of Hitomi. He also swears to capture and bring down the Cat''s Eye Gang.', 499, 'https://cdn.myanimelist.net/images/anime/1347/151708.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shounen Sunday CM: Denpa Kyoushi', 'Special', 2, 'Completed', '2012-10-02', '2013-02-17', '6', 'Two short anime clips, produced by A-1 Pictures and serving as promotion for the manga.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saikyou Robot Daiouja', 'TV', 50, 'Completed', '1981-01-31', '1982-01-30', '6', 'This is the story of Mito Mitsukuni in mecha style. Prince of the Edon Star, Edward Mito begins a trip to the galaxy with his servant Baron Kalkus, Duke Skead and the ninja girl Shinobu. Under the false identity of Bocchan, Suke and Kaku they help the oppressed people and fight with the super robot Daioja.', 974, 'https://cdn.myanimelist.net/images/anime/1170/93954.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga Reppuu Baxingar', 'TV', 39, 'Completed', '1982-07-06', '1983-03-29', '6', '600 years after Ginga Senpuu Braiger, Jupiter has been destroyed, and many planets have come from it, bringing about more colonization. To combat the increasing lawless activity, Don Diego Condor gathers Billy the Shot, Samanosuke Dodi, Layla Minesato, and Shuteken Radcliffe, a.k.a. J9-II. They pilot Cosmo Bikes, which combine into the robot Baxingar. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blue Seed 1.5', 'OVA', 2, 'Completed', '1996-06-21', NULL, '6', 'This is a re-telling of the first series. one episode is seen through the view of Momiji, the other is seen through the view of Kusunagi.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ichiban Chikakute Tooi Hoshi', 'Special', 1, 'Completed', '2021-08-23', NULL, '6', 'A four-minute concept animation that exists within the same world as Summer Ghost.', 290, 'https://cdn.myanimelist.net/images/anime/1867/122710.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nurse Witch Komugi-chan Magikarte Special', 'Special', 1, 'Completed', '2003-06-06', NULL, '6', 'A TV special, known as episode 2.5, that takes place between episodes 2 and 3.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('To Heart: Remember My Memories', 'TV', 13, 'Completed', '2004-10-02', '2004-12-25', '6', 'Time flies by; Hiroyuki and Akari are 12th-graders now. Both of them and their friends have grown up gradually in someway, physically or mentally, but one of their best friends is missing: the lifelike android Multi. To their surprise, Multi is brought to their campus again without notice, yet she is no longer the same Multi they have known. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shakugan no Shana: Friagne & Marianne no Naze Nani Shana! Nandemo Shitsumonbako! 2', 'Special', 8, 'Completed', '2008-01-25', '2008-08-29', '6', 'A series of short specials where Friagne and Marianne explain different terms from the second season of Shakugan no Shana.', 436, 'https://cdn.myanimelist.net/images/anime/10/40599.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yurumates 3D Plus', 'TV', 13, 'Completed', '2012-07-03', '2012-09-25', '6', 'The continuation of Yurumates 3D right after the first season.', 152, 'https://cdn.myanimelist.net/images/anime/5/40001.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hachigatsu no Cinderella Nine: Tsuzuku, Monogatari', 'Special', 1, 'Completed', '2021-09-25', NULL, '6', 'Special episode of Hachigatsu no Cinderella Nine (TV) sent to buyers of collector''s edition of the Blu-ray.', 990, 'https://cdn.myanimelist.net/images/anime/1869/117974.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wo Qi Ku Le Baiwan Xiulian Zhe', 'ONA', 160, 'Completed', '2021-08-19', '2023-02-16', '6', 'The story is about a student, Jiangbei, who fought valiantly at the subway station and was blessed by the system. Fortunately, he hosts the system and travels to another world. In this different world filled with cultivators, Jiangbei had gone from being a trash in a small town to a genius child in everyone''s eyes. Relying on the system, Jiangbei had started the path of improvement and became stronger just by playing treasures, and upsetting people. After a series of chaos and poetry battles, Jiangbei gradually developed feelings for his relatives here.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Soukou Kihei Votoms Vol.I: Stories of the "A.T.Votoms"', 'OVA', 1, 'Completed', '1985-06-21', NULL, '6', 'Recap special.', 974, 'https://cdn.myanimelist.net/images/anime/1326/94489.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou Shoujo Pretty Sammy', 'OVA', 3, 'Completed', '1995-08-25', '1997-08-24', '6', 'Sasami''s always been kind of neat... but now she''s been imbibed with a healthy dose of magic (which she plans to use to right the things wrong with the Earth, and, of course, help keep her brother Tenchi out of trouble). Naturally, there''s going to be trouble: this time, it''s the mysterious Pixy Misa... and Ryoko going at it against Ayeka (as usual) isn''t making things any easier for her!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Battle Fighters Garou Densetsu', 'Special', 1, 'Completed', '1992-12-23', NULL, '6', 'Jeff Bogard was a master of the Hakkyokuseiken martial arts school and the guardian of its secret techniques. Coveting this knowledge, Geese Howard, the most powerful man in South Town, challenged and murdered him in front of his adoptive sons Terry and Andy Bogard. Under the guidance of their mentor Tung Fe Rue, the brothers dedicate their lives to training in the ultimate art to avenge their father. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Baldr Force Exe Resolution', 'OVA', 4, 'Completed', '2006-11-10', '2007-04-04', '6', 'Any network runs all over the world, and the development of the information network reaches its acme. In this age, there are two developed worlds; "the real world" and "wired", or the virtual network world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Choujin Koukousei-tachi wa Isekai demo Yoyuu de Ikinuku you desu!', 'TV', 12, 'Completed', '2019-10-03', '2019-12-19', '6', 'Seven Japanese high school students enjoy international renown for their remarkable talents. One day, these friends survive a plane crash only to find themselves in the medieval fantasy world of Freyjagard, where two human races live side by side in a feudal society: the byuma, who have animal features and formidable strength, and the hyuma, who have a small chance of magical aptitude. After being rescued by the byuma Winona and her adopted elven daughter Lyrule, the group pledges to use their advanced skills and knowledge to pay back the people of Elm Village for their hospitality and find a way to return back home.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ring ni Kakero 1: Sekai Taikai-hen', 'TV', 6, 'Completed', '2011-04-10', '2011-06-12', '6', 'After defeating Black Shaft''s makeshift Team USA and proving their worth to the Shadow Clan, Team Golden Japan Jr. will finally enter the World Jr. Boxing Tournament. In order to fulfill their goal of a perfect victory they''ll have to take on teams from countries like Mexico, Italy, France, Germany, and the mysterious and godlike Team Greece.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Future GPX Cyber Formula: Early Days Renewal', 'OVA', 2, 'Completed', '1996-04-01', '1996-06-01', '6', 'Future GPX Cyber Formula: Early Days Renewal is following Future GPX Cyber Formula ZERO.', 974, 'https://cdn.myanimelist.net/images/anime/1957/106760.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Project A-Ko 4: Final', 'OVA', 1, 'Completed', '1989-10-07', NULL, '6', 'In Iraq, a group of archaeologists discover ancient relics that prophecize the coming of a superior race and the end of all civilization. Meanwhile, back in Graviton City, as A-Ko and B-Ko''s rivalry over Kei intensifies, Mr. Daitokuji sets up an arranged marriage between Miss Ayumi and Kei. Furious over the engagement, both A-Ko and B-Ko do whatever it takes to prevent the wedding from going through. Little do they know that another alien fleet is on its way towards Earth. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wan Jie Chun Qiu', 'ONA', 56, 'Completed', '2020-04-13', '2020-10-15', '6', 'Ye Chen, who is an ancient god, has fallen from the world of the gods to the world of the blue world. Here, hundreds of thousands of countries are standing, and the heroes are fighting for hegemony. Ye Chen has been in this pale blue world for hundreds of years and has established a huge force. In Baizhou Qianguo, the existence of Ye Chen has always been a legend. But the power from the world of the gods slowly extended to the blue world, and a cruel dragon battle is about to begin. In the capital city of Nanzhou, the first battle of Tianbei State, Hong Xu and the Wulong two men of Nanzhou Shuangyuemen Gate competed outside the Huashen Palace, but they were defeated in the hands of Su Xiaoxiao, the group leader of the Huashen Palace. The Northern Army emerged in the eastern part of southern South China and wanted to break South. The defender will disregard the safety of the people of Nanzhou and the hurricane, and intends to open the city gate to surrender
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece: Dr. Chopper no Bouken Karte - Chichi to Musume no Ballad', 'Special', 1, 'Completed', '2025-05-11', NULL, '6', 'The sixth recap special of the Egghead arc.', 1030, 'https://cdn.myanimelist.net/images/anime/1584/149734.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Scramble Wars: Tsuppashire! Genom Trophy Rally', 'OVA', 1, 'Completed', '1992-10-28', NULL, '6', 'Take the characters from a number of sci-fi based animes, a stage not unlike "Wacky Races," super deformed madness, and general insanity and what you get is Scramble Wars. While Scramble Wars does include characters from the original Bubblegum Crisis, Gall Force and Genesis Survivor Gaiarth, it also has a few other characters from other animes such as AD Police and Riding Bean. It doesn''t matter if you loved or hated any of these series, as long as you''ve seen at least one of them you''ll have a great time watching this, though the insanity is so generic that it really doesn''t matter if you haven''t seen any of the animes featured in Scramble Wars. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tokimeki Memorial 4: Original Animation - Hajimari no Finder', 'OVA', 1, 'Completed', '2009-12-03', NULL, '6', 'OVA added to new PSP game Tokimeki Memorial 4.', 90, 'https://cdn.myanimelist.net/images/anime/12/21756.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Puchitto Gargantia: Marumaru no Gargantia', 'Special', 1, 'Completed', '2013-09-25', NULL, '6', 'Special Project Gargantia.', 704, 'https://cdn.myanimelist.net/images/anime/2/59811.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tengai Makyou: Ziria Oboro-hen', 'OVA', 2, 'Completed', '1990-07-27', '1990-08-24', '6', 'Based on the first Tengai Makyou game, that initially came out in 1989 as one of the first titles for NEC''s PC Engine CD-ROM.', 990, 'https://cdn.myanimelist.net/images/anime/6/13003.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shounen Tokugawa Ieyasu', 'TV', 20, 'Completed', '1975-04-09', '1975-09-17', '6', 'A historical tale of the early life of Tokugawa Ieyasu, who would eventually become shogun and establish the Edo Period in Japan.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shinshaku Sengoku Eiyuu Densetsu: Sanada Juu Yuushi The Animation', 'TV', 12, 'Completed', '2005-05-07', '2005-07-23', '6', 'In the Fifth Year of the Keicho era, the Tokugawa clan sought to solidify their control of Japan. Hidetada Tokugawa has come to the doorsteps of Ueda Castle with the intentions of having the Sanada clan open its doors to him. But the Sanada and their retainers have other plans...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Densetsu Kyojin Ideon: Sesshoku-hen', 'Movie', 1, 'Completed', '1982-07-10', NULL, '6', 'Scouring the universe in pursuit of knowledge, mankind has discovered three large trucks and a giant spaceship belonging to an extinct alien civilization on the planet Solo. During their excavation, a humanoid alien race known as the Buff Clan arrives at Solo, and Karala Ajiba—daughter of the Buff Clan''s military leader—flies down to the planet against orders. In hunting for Karala, the Buff Clan attacks and destroys the Earth settlement to bring her back.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('To Heart: Remember My Memories Specials', 'Special', 7, 'Completed', '2006-01-26', '2006-08-24', '6', 'This is a special to To Heart: Remember My Memories, which includes fighting scenes between all the female characters.', 26, 'https://cdn.myanimelist.net/images/anime/1/686.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Move to the Future', 'Special', 9, 'Completed', '2020-01-31', '2024-09-20', '6', 'A short video about moving in the future by transportation company Art Corporation.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kakutou Ryouri Densetsu Bistro Recipe', 'TV', 26, 'Completed', '2001-12-11', '2002-06-25', '6', 'An 11-year old boy named Zen bands together with his younger sister, Karen, and a young boy who has a large appetite, Pitan, to battle an evil empire by using their "Foodons"; strange monsters that are created from various foods.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tobira wo Akete (1995)', 'OVA', 1, 'Completed', '1995-06-05', NULL, '6', 'It''s bedtime, and Nonoko is about to go to sleep. But the play of light and shadow on those objects on the wall look almost like... a person. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kiss Dum: Omokage', 'Special', 1, 'Completed', '2011-09-29', NULL, '6', 'Special included with the Blu-ray Box Set.', 780, 'https://cdn.myanimelist.net/images/anime/3/69105.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saru Getchu: On Air', 'TV', 26, 'Completed', '2006-04-08', '2006-09-30', '6', 'An evil monkey, Specter, has escaped a circus, using a mind-controlling device which allows him to become smarter and have access to controlling the monkeys. Kakeru is called over by a professor in order to capture all the monkeys, including the one''s who''s controlling them: Specter.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yousei Hime Ren', 'OVA', 2, 'Completed', '1995-10-27', '1996-01-26', '6', 'Gou has woved to find the legendary treasure of Salamander. Searching for it he meets Ren, a fairy, who is looking for the four treasures of Heart. Gou''s childhood friend Mari is frustrated with Gou running after treasures, but befriends with another fairy Rin. Gou and Ren''s treasure hunt messes with a secret project led by Mari''s father. It turns out Salamander isn''t what Gou thought it was in the first place... 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rio: Rainbow Gate! Special', 'Special', 1, 'Completed', '2011-10-19', NULL, '6', 'An extra episode of Rio: Rainbow Gate! which will be bundled with the seventh volume of the Blu-ray and the DVD.', 1117, 'https://cdn.myanimelist.net/images/anime/8/28328.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fushigi na Koala Blinky', 'TV', 26, 'Completed', '1984-07-07', '1984-12-28', '6', 'One day, Sandy''s father, Prof. Brown, sends her a stuffed koala doll from one of his trips. Sandy discovers that, after rubbing the koala''s nose, he comes alive. His name is Blinky and he is from the magical "down under" Koalawalla Land. They are soon joined by his little sister, Pinky. Adventures ensue in both Sandy''s world and Koalawalla land. Among the characters met are 2 men after the "magical talking bear", a lizard that bounces back and forth from the magical realm and the real realm, and kangaroo police officers.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Earthian', 'OVA', 4, 'Completed', '1989-07-26', '1996-12-21', '6', 'Since the beginning of Earth''s history, angels from the planet Eden have been carefully monitoring the behavior of its inhabitants, whom they call "Earthians." Chihaya and Kagetsuya are two agents sent from Eden to assess the positive and negative aspects of the Earthians'' nature. Despite the orders Chihaya was given by his home planet, he frequently ends up entangled in Earthian affairs, much to Kagetsuya''s annoyance. Meanwhile, as Chihaya tries to understand the origin of his strange black wings, he uncovers one mystery after another.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Idobata Kaigi de New Saga', 'ONA', 12, 'Completed', '2025-07-08', '2025-09-30', '6', '', 39, 'https://cdn.myanimelist.net/images/anime/1142/151011.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Holostars★Survival: Oretachi no Kaitaku Seikatsu', 'ONA', 1, 'Completed', '2024-03-18', NULL, '6', 'A short following the eccentric and hilarious daily lives of the Holostars VTubers in a survival setting!', 383, 'https://cdn.myanimelist.net/images/anime/1895/143737.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Toe! Space Attendant Aoi', 'Movie', 1, 'Completed', '2019-03-09', NULL, '6', '', 471, 'https://cdn.myanimelist.net/images/anime/1001/97418.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Historical', 'ONA', 1, 'Completed', '2016-02-01', NULL, '6', 'A highschool girl encounters a rabbit like creature who sends her back in time.', 733, 'https://cdn.myanimelist.net/images/anime/9/78389.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou no Tenshi Creamy Mami: Perfect Memory', 'OVA', 1, 'Completed', '1987-03-28', NULL, '6', 'An OVA supercut of Eien no Once More, Long Goodbye, and Curtain Call. One new animated feature is a fake Creamy Mami commercial for Creamy Soap. The feature then goes on to promote the Majokko Club Yoningumi: A Kuukan kara no Alien X release for later that year. This entry will only reflect the new footage.', 939, 'https://cdn.myanimelist.net/images/anime/8/77437.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mirai e no Kakehashi: Bridge for Future', 'Special', 6, 'Completed', '2015-10-01', '2016-08-01', '6', 'Fukushima Gainax''s commissioned commercials for TOHO Bank. The series involves Sayaka Hinata, an overly-energetic new bank employee (voiced by Sarah Emi Bridcutt), and her beleaguered boss, Mitsuya (voiced by Tomokazu Sugita).
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sword Gai', 'ONA', 1, 'Completed', '2013-10-04', NULL, '6', 'A promotional video for the manga.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ogaki Matsuri ni Ikou yo!', 'ONA', 1, 'Completed', '2020-03-30', NULL, '6', 'A tourism promotion anime for Ogaki City in the Gifu Prefecture. The story''s script was written by Kou Nakamura, a famous novelist from Ogaki City.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chaos Dragon: Sekiryuu Seneki', 'TV', 12, 'Completed', '2015-07-02', '2015-09-17', '6', 'In 3015, the year of Huanli, two countries, Donatia and Kouran, are embroiled in a war of supremacy that is tearing the world around them apart. The small island Nil Kamui has suffered exceptionally from the war, with lands conquered in the name of each kingdom and stolen away from the people. To make matters worse, their deity, the Red Dragon, has gone mad, rampaging about Nil Kamui burning villages and killing people indiscriminately.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Elf 17', 'OVA', 1, 'Completed', '1987-01-14', NULL, '6', 'Muscat Tyler is the 108th prince of the Galaxy Empire and is known as an eccentric person. He travels around the universe accompanying a Walking Arsenal, K.K, and Lu of the Light Wing Race, the strongest creature in the universe. Wherever they go, there is trouble.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saint Elmo: Hikari no Raihousha', 'Special', 1, 'Completed', '1987-12-31', NULL, '6', 'Inside Mercury, Japan builds a large-sized solar space power plant. The plant supports Earth with its large solar energy supply but suddenly there is an abnormality at the Saint Elmo plant. To pinpoint the problem, Earth sends several technicians to fix it.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Megumi to Taiyou III: Kajuu Gummi Tweet Fantasy - Timeline World', 'Special', 1, 'Completed', '2012-06-03', '2012-06-09', '5', 'The third "Megumi to Taiyou" CM for Meiji''s Kajuu Gummi candies.', 538, 'https://cdn.myanimelist.net/images/anime/4/64917.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hermes: Ai wa Kaze no Gotoku', 'Movie', 1, 'Completed', '1997-04-12', NULL, '5', 'Thousands of years in the past, a young boy named Hermes is named as a future great hero in a prophecy. Hermes grows up to save a beautiful princess and face the evil king Minos of Crete.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Master of Torque', 'ONA', 4, 'Completed', '2014-03-20', '2014-07-18', '5', 'It is Tokyo, Japan in the year 2017, just three years before the city''s hosting of the 2020 Olympic Games.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('PES: Peace Eco Smile - Drive your Heart', 'Special', 1, 'Completed', '2012-05-23', NULL, '5', 'Special spin-off episode that aired between episodes three and four of the original PES series. Is also an ad to Toyota''s new Vios vehicle.', 849, 'https://cdn.myanimelist.net/images/anime/8/50253.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dougram vs. Round-Facer', 'Special', 1, 'Completed', '1987-01-21', NULL, '5', 'Flying Dougram battles in space.', 974, 'https://cdn.myanimelist.net/images/anime/9/50183.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('First Kiss Monogatari', 'OVA', 1, 'Completed', '2000-02-14', NULL, '5', 'Moments before her upperclassman, Yoshihiko, left for college, Kana Orikura finally built up the courage to confess her love to him. Sharing their first kiss, the two decided to enter a relationship—a dream come true for Kana. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Imagination of Marathon Runners', 'Movie', 1, 'Completed', '1984-01-01', NULL, '5', 'A comedic short film by Yoji Kuri about runners.', 493, 'https://cdn.myanimelist.net/images/anime/1654/120989.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchuu Seibutsu Jirou', 'Special', 1, 'Completed', '2019-09-20', NULL, '5', 'A mysterious cat from space called Uchuu Sebutsu Jirou has come to Earth. Jirou is often seen in places with music.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Frame Arms: A Violent Struggle', 'OVA', 1, 'Completed', '2015-05-31', NULL, '5', 'Bundled with Kotobukiya''s pack of Frame Arms model kits.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Potecco Babies', 'ONA', 2, 'Completed', '2010-05-17', '2010-09-04', '5', 'Anime about potato characters.', 802, 'https://cdn.myanimelist.net/images/anime/13/24824.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ultra Dino Makera', 'Special', 1, 'Completed', '2008-01-01', NULL, '5', 'The Makera demo reel for RG Studios. It features a dinosaur in a yellow jumpsuit rescuing a girl tied to train tracks.', 731, 'https://cdn.myanimelist.net/images/anime/9/65745.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ni-hiki no Sanma', 'Movie', 1, 'Completed', '1960-11-26', NULL, '5', 'Original monochrome version of a short experimental film by animation pioneer Youji Kuri.', 493, 'https://cdn.myanimelist.net/images/anime/1427/144176.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Momotarou no Umiwashi', 'Movie', 1, 'Completed', '1943-03-25', NULL, '5', 'Momotaro sends a sneak aircraft attack to sink the ships of Demon Island, using his animal companions as crew members and pilots.', 805, 'https://cdn.myanimelist.net/images/anime/1889/145532.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ougon no Hou: El Cantare no Rekishikan', 'Movie', 1, 'Completed', '2003-10-11', NULL, '5', 'In the year 2403 AD a young student named Satoru is visited by a time traveler from the future, a cute girl named Alisa. The two go back in time together to explore the 21st century when a malfunction sends them hurdling through seemingly random episodes of religious and perhaps historic importance. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chou Kidou Densetsu DinaGiga', 'OVA', 2, 'Completed', '1998-07-15', '1998-08-26', '5', 'Touno Hikari is learning to pilot robots at a training facility. While she cannot do anything right, her instructors are interested in her for some reason. As the students learn to pilot the robots, they become suspicious of the goal of the training facility. Marie Vlaanderen transfers into the facility, and her instructor says that Marie has been training for all of her life and has the best chance of awakening "it".
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wanjie Zhuzai', 'ONA', 32, 'Completed', '2024-10-28', '2025-02-03', '5', '', 752, 'https://cdn.myanimelist.net/images/anime/1457/146357.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Isekai no Sata wa Shachiku Shidai', 'TV', NULL, 'Upcoming', '2026-01-06', NULL, '5', 'Already at his wit''s end, 29-year-old corporate slave Seiichirou Kondou suddenly witnesses the ground opening up and swallowing a woman. Amid his efforts to save her, the two are transported to another world. He soon learns that the people in this world summoned a saint to save their kingdom from a plague. As compensation for dragging Kondou into the mess, the kingdom assures him that they will provide him with a comfortable life and fulfill any of his desires. To everyone''s surprise, Kondou asks for a job.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaya-chan wa Kowakunai', 'TV', NULL, 'Upcoming', '2026-01-11', NULL, '5', 'Kaya-chan is infamous at kindergarten for being a troublemaker. But Ms. Chie, who''s been assigned to look after her, soon discovers Kaya''s hidden abilities. Get ready for the ultimate horror-action adventure set in kindergarten!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Elemon', 'ONA', 30, 'Completed', '2023-09-28', '2023-10-19', '5', 'Leo is a boy genius inventor. Aquro is a water type Elemon (H2O) created by Leo. Elemon are creatures born from the Elemon Blender. They are mysterious beings with the power of the elements! "ELEMON" opens up an exciting world of science and adventure, anchored by the friendship of Leo and Aquro as they explore an entire universe of unique Elemon!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cheng He Titong 2nd Season', 'ONA', NULL, 'Upcoming', '2025-01-01', NULL, '5', 'Second season of Cheng He Titong.', 798, 'https://cdn.myanimelist.net/images/anime/1470/149664.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wo Shi Da Shenxian 3rd Season', 'ONA', 16, 'Completed', '2024-10-28', '2024-12-02', '5', 'The third season of Wo Shi Da Shenxian.', 159, 'https://cdn.myanimelist.net/images/anime/1397/146193.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eris no Seihai', 'TV', NULL, 'Upcoming', '2026-01-08', NULL, '5', 'It is common knowledge that nobles will do anything for power; lying, manipulation, and extortion are the usual tactics. However, one family is exempt from this generalization: House Grail, whose main tenets are truth and integrity. The youngest daughter, Constance Grail, is just as moral as the rest of her family, believing in always doing the right thing and helping those in need.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Love Live! Nijigasaki Gakuen School Idol Doukoukai: Kanketsu-hen Part 3', 'Movie', 1, 'Upcoming', NULL, NULL, '5', 'Third part of Love Live! Nijigasaki Gakuen School Idol Doukoukai Kanketsu-hen.', 974, 'https://cdn.myanimelist.net/images/anime/1093/146168.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sylvanian Families: Mini Story - Peony', 'TV', 12, 'Completed', '2020-10-01', '2020-12-17', '5', 'The story takes place in a village called Sylvania, and centers on Chocolate Usagi-chan, Kurumi Risu-kun, and their friends and families.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sylvanian Families: Freya no Happy Diary', 'TV', 12, 'Completed', '2022-10-06', '2022-12-22', '5', 'A TV series based on the Sylvanian Families toy line.', 504, 'https://cdn.myanimelist.net/images/anime/1452/151860.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Prepare', 'ONA', 3, 'Completed', '2020-12-14', NULL, '5', 'In this short animation, Luna, a girl who is uncomfortable with hospitals, medicine and injections, comes to understand the value of medicine via the thrilling explanations of a mysterious doctor.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Qin Shi Mingyue: Chunjie Tebie Pian', 'ONA', 1, 'Completed', '2016-02-04', NULL, '5', 'An episode that was released to celebrate Chinese New Year.', 827, 'https://cdn.myanimelist.net/images/anime/1876/122980.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shi Wan Ge Leng Xiaohua Fanwai Pian', 'ONA', 1, 'Completed', '2013-05-10', NULL, '5', 'The special of Shi Wan Ge Leng Xiaohua.', 524, 'https://cdn.myanimelist.net/images/anime/1779/128237.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('King Kong: 001/7 Tom Thumb', 'TV', 26, 'Completed', '1967-04-05', '1967-10-04', '5', 'Professor Bond is doing research on an island in the Java Sea when his son discovers the giant ape and befriends him, and together they fight to protect Kong from Dr. Who, who has sinister designs on the ape. Each episode consisted of a King Kong story, a Tom of T.H.U.M.B., then another King Kong story. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaminari Boy Pikkari★bee', 'TV', 53, 'Completed', '1967-04-01', '1968-03-30', '5', 'A comedy about a mischievous boy. Each episode contains 2 stories.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hennako-chan', 'ONA', 6, 'Completed', '2008-04-25', '2008-07-03', '5', 'Hennako-chan is a black comedy series targeted at adult readers. The main character is an eccentric elementary school girl who has telekinetic powers that enable her to manipulate other people, animals, and even plants or objects by just staring at them. The series follows the helter-skelter daily lives of Hennako-chan and the people around her, including her family consisting of her very cracker-barrel parents, hot-to-trot elder sister, and a former stray dog, who are always thrown into frenzy by Hennako-chan''s super-natural powers that expose their secrets. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tobidase! Bacchiri', 'TV', 132, 'Completed', '1966-11-14', '1967-04-15', '5', 'The adventures of jug-eared schoolboy detective Bacchiri, who can solve cases that baffle the police, thanks to his brilliantly ingenious mind. The 10 minutes episodes aired daily, Monday through Saturday.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaitou Pride', 'TV', 105, 'Completed', '1965-05-31', '1965-11-04', '5', 'Each episode features a part of the story in which a detective tries to hunt down and capture a notorious and narcissistic thief. This series aired daily, Monday to Friday, in 8 minutes segments to complete a single story by the end of the week.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchuujin Pipi', 'TV', 52, 'Completed', '1965-04-08', '1966-03-31', '5', 'An alien from another world lands on Earth and befriends a human boy. Pipi tends to help his human friends by giving them sound advice and sometimes using his advanced technology when needed. This is a drama which is mostly live actors and scenery. The main character, Pipi, and many of the special effects are animated.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shounen Ninja Kaze no Fujimaru: Nazo no Arabiya Ningyou', 'Movie', 1, 'Completed', '1964-07-21', NULL, '5', 'Kidnapped and rescued by a Ninja, Fujimaru has mastered martial arts over the years. Now he sets off on a journey to find his mother and also locate an old tome containing secret martial arts techniques.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ikinari Dagon', 'TV', 12, 'Completed', '1988-04-09', '1988-06-25', '5', 'Dagon''s little rocket crashes into a beautiful, blue planet and lands on a bed of green weeds. He quickly becomes friends with all kinds of creatures: Zipzap Mantis, General Ant Garibaldi, Andy Ant, Doctor Marilyn Wasp, and many more. Needless to say they are all insects. Insects? Yes, Dagon is only one centimetre tall!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eikou e no Spur: Igaya Chiharu Monogatari', 'Movie', 1, 'Completed', '1997-09-13', NULL, '5', 'A biography of Chiharu Igaya, who won a silver medal in men''s slalom in Cortina d''Ampezzo Olympics in 1956, and became the first Japanese Winter Olympics medalist.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimu no Juujika', 'Movie', 1, 'Completed', '1990-07-21', NULL, '5', 'Based on the novel by Noboru Wada.', 1009, 'https://cdn.myanimelist.net/images/anime/11/53177.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pipi Tobenai Hotaru', 'Movie', 1, 'Completed', '1996-03-23', NULL, '5', 'Based on the fairy tale novel series by Akira Ozawa (小沢昭巳).', 587, 'https://cdn.myanimelist.net/images/anime/12/53081.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Little Charo: Touhoku-hen', 'TV', 12, 'Completed', '2012-04-07', '2012-06-30', '5', 'Charo venture around Tono, Iwate, a city in Japan''s Tohoku (Northeast) region, attempting to find the Eight-Starred Note in order to prevent the reappearance of the Tenaga-Ashinaga monster of local legend.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Panda no Taputapu', 'TV', 431, 'Completed', '2012-04-02', '2013-11-29', '5', 'A short anime featuring the zodiac animals with a panda named Taputapu as the main character. Each episode is focuses on having a proverb, moral, or uplifting value.', 457, 'https://cdn.myanimelist.net/images/anime/1747/90564.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tabi Hani: Kyoto-hen', 'OVA', 1, 'Completed', '2023-04-08', NULL, '5', 'The anime''s story centers on Akari (a quiet high schooler who has inherited a love of travel from her older sister, who took care of her in place of often absent parents) and Nagi (Akari''s cheerful classmate who willingly jumps into any activity, and becomes interested in Akari due to her mysterious air), who travel throughout Japan.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tomodachi 8-nin', 'TV', 398, 'Completed', '2011-03-28', '2019-01-05', '5', 'A series oriented to three-year-old children, showing the everydays of 9 characters, each of them having a distinct feature. Children will recognize characters and situations from their own life. Sometimes through conflicts, sometimes through encouragement, they will find everyone''s place in the world. The story conveys messages such as "Nobody''s alone", "It''s good to be different" and the importance of being connected with others, in a fun way.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zumomo to Nupepe', 'TV', 32, 'Completed', '2012-04-03', '2013-02-26', '5', 'No synopsis has been added for this series yet.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('He Nü''er De Richang', 'ONA', 18, 'Completed', '2016-10-14', '2016-01-01', '5', 'A father with lots of love is often tormented endlessly by his daughter in everyday life. But this father would often look on all the troubles created by this child with a warm and loving heart. This is the super healing and cute series about the daily life of this father and daughter, it’s warm loving and interesting too.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zoobles!', 'TV', 26, 'Completed', '2011-05-18', '2011-11-16', '5', 'The Candy Factory is a place where all Zoobles are born. Beyond that factory is a world called Candy Land, where all Zoobles live. The story revolves around the three main Zoobles: Chevy, a Cat Zooble with an Orange Flavour; Coron, a Rabbit Zooble with a Strawberry Milk Flavour; and Panky, a Panda Zooble with a Blueberry Yogurt Flavour. The three of them live in Candy Town, and they get into serious misadventures as they try to get in (and out of) trouble.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zannen na Ikimono Jiten the Movie', 'Movie', 1, 'Completed', '2022-07-08', NULL, '5', 'Based on a series of illustrated children''s books.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Paboo & Mojies', 'TV', 52, 'Completed', '2012-04-02', '2013-03-02', '5', 'Paboo is a fun loving and curious boy panda, and he and his group of larger-than-life friends explore and problem-solve in their quirky, imaginative and sometimes zany world! Each episode sees the Mojies (Japanese for letters of the alphabet) and Pappy (the Mojies book fairy of course!) help Paboo to discover the Magic Word and solve the problem of the day!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tongari Atama no Gonta: Futatsu no Namae wo Ikita Fukushima Hisai Inu no Monogatari', 'Movie', 1, 'Completed', '2022-06-03', NULL, '5', 'On March 11, 2011, a massive earthquake of magnitude 9.0 hit the Tohoku region. The Tomita Diner family evacuates from place to place, leaving their 8-year-old dog, Gonta, behind. Meanwhile Yoshino, a female university student in Tokyo, joins a pet rescue volunteer group and goes to the disaster area. There, she rescues a dog and names him Peace, but he is found to be suffering from a serious illness and is diagnosed as having only one month to live. Yoshino desperately tries to bring Peace back to his original owner. Miraculously, Yoshino meets the Tomita family and learns that Peace is Gonta. Gonta continues to live to the point that even doctors are surprised, and becomes a hope for many victims. Yoshino also becomes increasingly involved in pet rescue, which she had a reason for.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Joshikousei to Mahou no Note', 'ONA', 1, 'Completed', '2022-12-01', NULL, '5', 'The story follows Yuzuki Shidou, a second-year high school student who can''t find what she wants to do. One day, a fairy named Buruburu suddenly appears before her and teaches her how to find and fulfill her dreams.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kono Shihai kara no Sotsugyou: Ozaki Yutaka', 'OVA', 1, 'Completed', '2004-04-21', NULL, '5', 'A compilation OVA of 5 stories portraying the life of Ozaki Yutaka, a famous Japanese musician in the 80s and early 90s who died young.', 1030, 'https://cdn.myanimelist.net/images/anime/9/52725.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('He Nü''er De Richang 2nd Season', 'ONA', 18, 'Completed', '2017-03-21', '2017-01-01', '5', '', 1056, 'https://cdn.myanimelist.net/images/anime/1657/117932.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('He Nü''er De Richang 3rd Season', 'ONA', 18, 'Completed', '2018-10-09', '2018-01-01', '5', '', 1056, 'https://cdn.myanimelist.net/images/anime/1083/117933.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Love Hina Again', 'OVA', 3, 'Completed', '2002-01-26', '2002-03-27', '7', 'Keitaro has finally passed the entrance exams, and is officially a Toudai student. But after breaking his leg in an accident in the entrance ceremony, he thought and re-evaluated himself. Having new goals, Keitaro follows Seta on an overseas archeology trip. During his absence, however, all was not well in Hinata Lodge. Urashima Kanako, Keitaro''s sister, arrives on the scene. She claims to be the new manager of Hinata Lodge starts to go against all the tenants. Things become even more complicated when they recieve a letter from Keitaro. The tenants and Kanako made a big mess trying to get the letter, but Seta''s car crashes in before anyone could read the letter...', 1117, 'https://cdn.myanimelist.net/images/anime/3/10289.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon Movie 21: Minna no Monogatari', 'Movie', 1, 'Completed', '2018-07-13', NULL, '7', 'As Satoshi continues his journey to become a Pokémon Master, he travels to Fura City to attend the annual Wind Festival. Pumped up, Satoshi and Pikachu are determined to win the festival''s Get Race. Meanwhile, Kagachi, a show-off and a habitual liar, joins the competition at the request of his niece Lily. Having almost no knowledge about Pokémon, he manages to strike a deal with a socially awkward scientist named Torito in exchange for help with his upcoming speech. Following Kagachi''s victory, Satoshi meets Risa, an ex-regional track and field champion looking to catch a Pokémon. However, during Torito''s speech, Team Rocket strikes and manages to steal a capsule from his lab.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Brigadoon: Marin to Melan', 'TV', 26, 'Completed', '2000-07-21', '2001-02-09', '7', 'Marin is a typical junior high school girl with a sunny disposition and a loving adoptive family. Her life takes a drastic change when a mysterious mirage is seen in the sky above the entire earth. Killer androids called Monomakia descend to earth from the formation in the sky called Brigadoon and begin to hunt down little Marin. She discovers a blue bottle in a shrine as she seeks escape and from the bottle comes a protector, a sword carrying gun slinging alien called Melan Blue, together they must save the earth and deal with family crisis, school prejudice and the police and come to an understanding of Marins past and Melans unexplained mission, as well as learn to trust each other. Set in 1969 Japan with a colorful cast of friends and enemies.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga e Kickoff!!', 'TV', 39, 'Completed', '2012-03-26', '2013-02-26', '7', 'The story follows a boy who was in a soccer team, but it was disbanded due to not enough players. However, after the boy meets a female professional soccer player, he aims to bring his soccer team back.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cyber City Oedo 808', 'OVA', 3, 'Completed', '1990-06-21', '1991-10-04', '7', 'It is the year 2808. Three convicts are recruited as members of the Cyber Police to keep major criminal activity in Oedo (formerly Tokyo) in check. In return, their life sentences will be reduced by a few years for every mission accomplished. However, to ensure that these convicts are doing their job, the police have secured special collars around their necks. If they attempt to remove their collars or fail to meet the time limit of their mission, the collars will self-destruct. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fate/Apocrypha', 'TV', 25, 'Completed', '2017-07-02', '2017-12-31', '7', 'The Holy Grail is a powerful, ancient relic capable of granting any wish the beholder desires. In order to obtain this power, various magi known as "masters" summon legendary Heroic Spirits called "servants" to fight for them in a destructive battle royale—the Holy Grail War. Only the last master-servant pair standing may claim the Grail for themselves. Yet, the third war ended inconclusively, as the Grail mysteriously disappeared following the conflict.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ling Qi', 'ONA', 20, 'Completed', '2016-06-21', '2016-11-01', '7', 'Low on luck after a series of unfortunate events, You Keika works part-time to try bringing himself out of a life of poverty. After a strange encounter with a white-haired man in a junkyard, You wakes up to discover that he was killed in a sudden accident and has become a spirit. The man he had encountered, Tanmoku Ki, is revealed as the 13th Youmeshi of the Tanmoki, the highest-ranking exorcist family of China. Noticing the wandering spirit, he offers You the opportunity to form a pact: he will offer You protection from humans and in return, You will have to become his spirit shadow, keeping him safe and guarded at all times.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tenchi Muyou! in Love 2: Harukanaru Omoi', 'Movie', 1, 'Completed', '1999-04-24', NULL, '7', 'Tenchi runs off into the woods to spend some time alone after his friends have another argument. While lost in thought, he hears a voice coming from a camellia tree. Tenchi approaches it and vanishes through a portal.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nagasarete Airantou', 'TV', 26, 'Completed', '2007-04-05', '2007-09-27', '7', 'Ikuto Touhohin just had a fight with his old man, one that led him to make a rash decision to run away from home. He boards a ship, deciding to take a vacation, but the ship is suddenly hit by a huge storm—one that sends Ikuto overboard! When he regains consciousness, he realizes he is still alive on some island. An isolated island. An isolated island with nothing but girls. Beautiful girls. Stranded on an island with only girls, no electricity, gas, radio, television, like he was back in the stone age.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mayo Chiki!', 'TV', 13, 'Completed', '2011-07-08', '2011-09-30', '7', 'Due to his mother and sister, who both love professional wrestling, Kinjirou Sakamachi developed a resilient body that could take hard punches, aggressive kicks, and even deadly vehicle bumps, in order to survive their various grappling positions and locks. However, he also developed gynophobia, an abnormal fear of women. With just one touch from a girl, his nose bleeds uncontrollably, he sweats excessively, and in rare cases, faints abruptly.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zutto Mae kara Suki deshita. Kokuhaku Jikkou Iinkai', 'Movie', 1, 'Completed', '2016-04-23', NULL, '7', 'Love is blooming at Sakuragaoka High School. Natsuki Enomoto has finally mustered the courage to confess to her childhood friend, Yuu Setoguchi. However, in the final moments of her confession, an embarrassed Natsuki passes it off as a "practice confession." Oblivious to her true feelings and struggling with his own, Yuu promises to support Natsuki in her quest for love. While Natsuki deals with her failed confession, fellow classmate Koyuki Ayase struggles with his own feelings for Natsuki. Despite his timidness, he is determined to win over her heart.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chao Neng Lifang: Chaofan Pian', 'ONA', 12, 'Completed', '2025-03-21', '2025-05-23', '7', 'In an accident, an ordinary boy, Wang Xiaoxiu, obtains a space system called "Superpower Cube" from a high-latitude cosmic civilization and gains extraordinary powers. When the school belle, Shen Yao, Wang Xiaoxiu’s longtime crush, confesses her love to him, the delinquent Sun Jun, who also has a crush on her, is provoked. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Inazuma Eleven: Aratanaru Eiyuu-tachi no Joshou', 'Movie', 1, 'Completed', '2024-12-27', NULL, '7', 'The protagonist, Sasanami Unmei, transfers to Nagumohara Junior High School in Nagasaki in search of a soccer-free environment, wishing that soccer would disappear. Meanwhile, Endou Haru, who has demonstrated his natural talent and reigns at the top of his generation, also has complicated feelings about soccer. The unexpected encounter between these two opens the door to new heroes.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ensemble Stars!! Tsuioku Selection Checkmate', 'ONA', 6, 'Completed', '2024-03-10', '2024-03-15', '7', 'New Ensemble Stars!! web animated series based on the game story "Checkmate".', 223, 'https://cdn.myanimelist.net/images/anime/1499/141979.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lazarus', 'TV', 13, 'Completed', '2025-04-06', '2025-06-29', '7', 'In the year 2048, Dr. Deniz Skinner, a scientific genius dubbed second only to Einstein, developed the revolutionary painkiller Hapna. Being cheap with no reported side effects, the drug gained widespread acceptance, even though Skinner himself silently vanished one year after launching the drug. Everyone revelled in the heaven of relief and ecstasy provided by Hapna, but they would suddenly come crashing down to Earth. It is now 2052, and Skinner reappears, giving the shocking announcement that Hapna was designed to mutate into a lethal toxin, killing anyone who had consumed it. While he claims to have a cure, he will only hand it over if he is physically found within 30 days. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yoru wa Neko to Issho', 'TV', 30, 'Completed', '2022-08-04', '2023-01-11', '7', 'Fuuta-kun has never owned a cat before, but his younger sister, Pii-chan, moves into his house with the round gray cat Kyuruga. Inexperienced with cats, Fuuta-kun has no idea what to expect, and each night after he returns home is marked by odd and endearing surprises from his new pet.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zuoshou Shanglan', 'ONA', 8, 'Completed', '2023-02-02', '2023-03-16', '7', 'The story follows teenager Xu Xingze, a passionate basketball player who aspires to join the Basketball Team of the regions top school after seeing their Star Player win the Final Four Tournament. When his sister accidentally enrolls him into a lesser school with a similar name, its up to Xu and his ragtag group of new friends to prove their worth and their skill on the Court against some of the top High School players in the Region.', 374, 'https://cdn.myanimelist.net/images/anime/1700/122189.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wu Shan Wu Xing', 'ONA', 1, 'Completed', '2016-12-31', NULL, '7', 'A legend tells that a long time ago, monsters could give the ability to certain elected officials to master the five elements. But for wha, you have to go through the dangerous foggy mountains. Follows the adventures of one of these elected officials.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Date A Live III', 'TV', 12, 'Completed', '2019-01-11', '2019-03-29', '7', 'Shidou Itsuka carries on with his quest for Ratatoskr in finding Spirits and trying to seal their powers, all while maintaining his relationships with the ones he had already sealed. Moreover, as new Spirits appear, he must undergo more complicated trials—all to put a stop to further disasters as he discovers more about the Spirits'' origin.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece Film: Gold Episode 0 - 711 ver.', 'ONA', 1, 'Completed', '2016-07-02', NULL, '7', 'A short web prequel to One Piece Film: Gold featuring the nine Straw hat crew members on the ship, planning what to do when they arrive the Casino.', 1030, 'https://cdn.myanimelist.net/images/anime/4/83792.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Selector Destructed WIXOSS Movie', 'Movie', 1, 'Completed', '2016-02-13', NULL, '7', 'This movie is a retelling/summary of Selector Infected and Spread, with extra scenes interspersed such as the characters in childhood. Despite mostly being previously used scenes, they were cut and altered to make a high intensity and fast paced story, highlighting the moments of slow silence and reflection. Some changes were made such as the true origin of Tama''s name, the significance of Sachi and Rumi, and the relationship between your name and being alone.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Amagami SS+ Plus: Extra Episode+ Plus', 'Special', 6, 'Completed', '2012-04-04', '2012-09-05', '7', 'Short extras of the anime included in each of the six Blu-ray volumes of Amagami SS+.', 25, 'https://cdn.myanimelist.net/images/anime/12/56023.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hetalia: The World Twinkle', 'ONA', 15, 'Completed', '2015-07-03', '2015-10-09', '7', 'United Kingdom and America have to put aside their centuries of differences and cooperate if they want to stand a chance against Italy and Germany on the African Front. After being defeated by a questionable border defense system, France swears vengeance on Germany. In another part of the world, the Nordic countries discuss how similar they are to each other, much to Finland''s dismay. Meanwhile, Sealand embarks on a very ambitious quest to search for the other micronations after befriending Wy and Seborga.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fuyu no Okurimono', 'ONA', 1, 'Completed', '2023-03-18', NULL, '7', 'The original short animation depicts the growth of a girl and her encounter with a mysterious creature.', 1105, 'https://cdn.myanimelist.net/images/anime/1109/134904.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kono Sekai wa Fukanzen Sugiru', 'TV', 13, 'Completed', '2024-07-06', '2024-09-28', '7', 'Nikola is just a village girl working at the inn...until the day dragons invade, and she meets Haga, a scholar of everything around him. He''s a part of an elite society called "Seeker," created to address a series of maladies plaguing their usually peaceful world. But both Nikola and Haga have secrets they hide...ones that will change each other''s very existence...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Li Shi Zhentan Shiwusuo: A Day in Lungmen', 'ONA', 6, 'Completed', '2022-12-23', '2023-02-03', '7', 'A mysterious man by the name of Lee dwells with Aak, Hung, and Waai Fu in the dark alleyways of Lungmen City. Styling themselves as Lee''s Detective Agency, they strove to run errands, investigate mysteries, and mediate disputes for their neighbors. Herein lists a few of their actual yet strange cases to go with your tea.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Onna no Sono no Hoshi', 'OVA', 1, 'Completed', '2022-12-08', NULL, '7', 'Hoshi-sensei, a Japanese language teacher at an all-girls school, is at the mercy of his students and colleagues. Students challenge him to their shiritori word games illustrated in their daily notes, convince him to bring a dog into the classroom, and seek his advice on becoming a manga artist, while colleagues drag him along on their rounds to the pub. Matter-of-fact interactions between a cast of unique characters make for an offbeat comedy. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Eternal Boys', 'TV', 24, 'Completed', '2022-10-11', '2023-03-28', '7', 'Washed-up salaryman Kentarou Sanada is at his wits end trying to find a job, applying anywhere and everywhere since his former company went bankrupt. After unknowingly showing up to an idol audition that he thinks is a regular job interview, Sanada is shocked when he gets a callback saying that he has been accepted. Along with five other men in their forties, he has been chosen as a member of Eternal Boys—a new idol group that strives to prove that people can debut at any age. However, as the Eternal Boys attempt to establish themselves in an industry saturated with much younger talent, they wonder whether their age will hold them back or their experience will be their key to success.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon Movie 17: Hakai no Mayu to Diancie', 'Movie', 1, 'Completed', '2014-07-19', NULL, '7', 'In the underground Diamond Domain, where many Carbink live, the Mythical Pokémon Diancie serves as ruler. The Holy Diamond that sustains the land is beginning to fall apart, and Diancie is not yet strong enough to create a new one. While seeking help from the Legendary Pokémon Xerneas, Diancie encounters a group of thieves who want to take control of its diamond-producing power–and who awaken the Legendary Pokémon Yveltal from its cocoon in the process! Can Satoshi and his friends help Diancie discover its true power, stop Yveltal’s rampage, and save the Diamond Domain?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Magatsu Wahrheit: Zuerst', 'TV', 12, 'Completed', '2020-10-13', '2020-12-29', '7', 'In the technologically and magically advanced Wahrheit Empire, rumors of a returning catastrophe known only as the "light" causes a disturbance amongst the people. Meanwhile, in the capital of the Empire, transporter Innumael Grauer prepares his daily deliveries, struggling to make ends meet for himself and his sister. Leocadio Wöhler, a newly recruited soldier, assists Innumael whilst commuting to work—unknowingly loading a mysterious package containing contraband artillery belonging to a criminal organization.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hakubo', 'Movie', 1, 'Completed', '2019-06-21', NULL, '7', 'Hakubo revolves around the daily life of Sachi Koyama, a high school violinist with promising talent. Although Sachi is content with her school life and retains friends within the music club, her favorite pastime is appreciating the scenery around her neighborhood in Iwaki, Fukushima while walking to her bus stop alone. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ladies versus Butlers!', 'TV', 12, 'Completed', '2010-01-05', '2010-03-23', '7', 'Hino Akiharu lost his parents when he was small and was adopted into his uncle''s family. He didn''t want to be a burden on his uncle''s family and decides to enter a free boarding school as a butler, Hakureiryou high school. However, his delinquent boy-like appearance frightens the girls, who make up the majority of the students. Unable to get along with the classmates, Akiharu meets his childhood crush Saikyou Tomomi.', 1117, 'https://cdn.myanimelist.net/images/anime/7/75252.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Amagami SS+ Plus Picture Drama', 'Special', 2, 'Completed', '2012-10-03', NULL, '7', 'Picture Dramas from the DVD/BD Vol.7.', 25, 'https://cdn.myanimelist.net/images/anime/8/55899.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Masou Gakuen HxH Specials', 'Special', 6, 'Completed', '2016-09-30', '2017-02-24', '7', 'Masou Gakuen HxH specials included with the volumes of the DVD/BD.', 705, 'https://cdn.myanimelist.net/images/anime/11/83016.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lostorage Conflated WIXOSS: Missing Link', 'OVA', 1, 'Completed', '2017-12-14', NULL, '7', 'Suzuko Homura and Chinatsu Morikawa''s victory against the nefarious Bookmaker Kou Satomi has allowed the two girls to finally return to a life of normalcy and seize the chance to move on. However, the peace does not last long, as Kiyoi Mizushima requests Suzuko''s help to prevent the next cycle of Selector battles; even after Satomi''s defeat, efforts to continue his plans seem to persist. Troubled by lingering doubts and the unresolved situation, Suzuko decides to assist Mizushima with her investigation—unknowingly becoming involved in the escalating fight that will determine the fate of Selectors once and for all.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan: Hoshikage no Majutsushi', 'Movie', 1, 'Completed', '2012-01-01', NULL, '7', 'The Japan Aerospace Exploration Agency (JAXA) has planned a huge exhibition to present current progress in space exploration, as well as showcase a set of large, beautiful celestial jewels. But then, a message arrives from infamous Kaitou Kid, who plans to steal the treasure. Conan and the Detective Boys are brought in as added security. Everything is going well... until the power cuts out. With limited time, Conan and company must protect the jewels from Kaitou Kid.', 207, 'https://cdn.myanimelist.net/images/anime/3/88889.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blood-C', 'TV', 12, 'Completed', '2011-07-08', '2011-09-30', '7', 'Peaceful schoolgirl by day, fearsome monster slayer by night, Saya Kisaragi is leading a split life. Equipped with a ceremonial sword given to her by her father for sacred tasks, she vanquishes every monster who dares threaten her quiet little village. But all too soon, Saya''s reality and everything she believes to be true is tested, when she overhears the monsters speak of a broken covenant—something she knows nothing about. And then, unexpectedly, a strange dog appears; it asks her to whom she promised to protect the village, curious as to what would happen if she were to break that promise. Tormented by unexplainable visions and her world unraveling around her, we travel with Saya through her struggle to find a way to the truth in a village where nothing is as it seems.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cinderella Girls Gekijou 3rd Season', 'TV', 13, 'Completed', '2018-07-03', '2018-09-25', '7', 'The third season of Cinderella Girls Gekijou.', 329, 'https://cdn.myanimelist.net/images/anime/1618/90871.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pastel Life', 'TV', 6, 'Completed', '2018-05-17', '2018-06-21', '7', 'A Nico Live broadcast of BanG Dream! franchise on Monday has announced a spin-off anime featuring one of the units in the franchise, Pastel*Palettes. Titled Pastel Life, the slice-of-life series is yet to announce its type and broadcast details.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wo Shi Jiang Xiaobai 2nd Season', 'ONA', 12, 'Completed', '2018-11-09', '2019-01-25', '7', 'After coming to terms with their past, Jiang Xiaobai and Tong Li are still together as editor and author—and now, as lovers too. But not everything is smooth-sailing for the new couple. Tong Li''s most recent work is being panned by readers and critics, and Wen Zheng Magazine''s recent decline in sales means that her serialization is in jeopardy. Meanwhile, Jiang Xiaobai, fondly remembering making music with his friends in high school, steps in as the backup bassist for a local band struggling to make their break. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou Shoujo Site', 'TV', 12, 'Completed', '2018-04-07', '2018-06-23', '7', 'Every day, Aya Asagiri thinks about killing herself. She is bullied relentlessly at school, and at home, her older brother Kaname physically abuses her to relieve the academic stress put on him by their father.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Crayon Shin-chan Gaiden: O-o-o no Shinnosuke', 'ONA', 13, 'Completed', '2017-05-31', '2017-08-23', '7', 'A small country town. Recently, the town has witnessed many strange incidents. A youkai kindergartner O-o-o no Shinnosuke (an apparent homage to the classic supernatural franchise Gegege no Kitarou) and his youkai father Tamatama Dad arrive in town. They are said to be looking for the yokai Big Butt Mom who has run away from home. When an elementary school girl Fumie Sakura is suddenly attacked by the mysterious Fuzzy Wuzzy, a superfluous-hair youkai, Shinnosuke goes to her aid. Their encounter is the start of the greatest youkai case in the small town''s history. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Birthday Wonderland', 'Movie', 1, 'Completed', '2019-04-26', NULL, '7', 'The day before her birthday, Akane is asked to retrieve her birthday present from her aunt Chi''s shop. While looking around, she chances upon a mysterious slab with a hand-shaped cavity in it. Curious, she places her hand in it, and—to her surprise—it fits perfectly. The next thing she knows, a strange alchemist named Hippocrates and his apprentice Pipo appear, calling Akane the legendary "Goddess of the Green Wind."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tate no Yuusha no Nariagari Season 2', 'TV', 13, 'Completed', '2022-04-06', '2022-06-29', '7', 'With another Wave happening in a week, Naofumi Iwatani and his party have no time to waste. However, when bat familiars raid Lurolona Village and the Wave countdown comes to a halt, the Four Cardinal Heroes reconvene with the queen, Mirelia Q Melromarc, for a quick briefing. The queen presumes that the odd occurrences are linked to the Spirit Tortoise—a threatening creature that has awakened from its slumber, back to cause havoc once again. A plan to put the Spirit Tortoise to rest is devised—but out of the four men, only the cursed Shield Hero agrees to help.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zenonzard The Animation Episode 0', 'ONA', 1, 'Completed', '2019-09-10', NULL, '7', 'The year 20XX. Humans called "Concodes" and ultra-high-performance AI called "Codeman" team up as buddies to compete in the card battle game ZENOZARD. People are going wild with excitement at the world championships, THE ZENON.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yu-Gi-Oh! Card Game: The Chronicles', 'ONA', NULL, 'Airing', '2025-04-21', NULL, '6', 'The stories that lie within the cards come to life...', 489, 'https://cdn.myanimelist.net/images/anime/1653/147242.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Around 40 Otoko no Isekai Tsuuhan', 'TV', 13, 'Completed', '2025-01-09', '2025-04-03', '6', 'From nowhere, middle-aged illustrator Kenichi Hamada finds himself summoned to another world. Despite arriving in an unfamiliar land, he realizes he can still connect to an online shop named Shangri-La, which he frequented back in Japan, to order almost anything. Not long after, Kenichi comes across a town and, using Shangri-La, decides to become a merchant in the settlement.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuroko no Basket: Basket Kyoushitsu', 'Special', 1, 'Completed', '2023-03-24', NULL, '6', 'An original picture drama included with the Kuroko no Basket Thanks Disc: 10th Anniversary BD/DVD.', 704, 'https://cdn.myanimelist.net/images/anime/1231/143270.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Midnight Grand Mos Burger', 'ONA', 1, 'Completed', '2022-09-14', NULL, '6', 'A collaboration between Midnight Grand Orchestraand MOS Burger to promote the release of the their Tsukimi Focaccia sandwich.', 1123, 'https://cdn.myanimelist.net/images/anime/1212/140400.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shangri-La Frontier: Kusoge Hunter, Kamige ni Idoman to su Mini Anime', 'ONA', 9, 'Completed', '2023-09-28', '2023-11-08', '6', '', 39, 'https://cdn.myanimelist.net/images/anime/1687/138921.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsuru ga Mau Yoru ni', 'ONA', 1, 'Completed', '2023-03-31', NULL, '6', '', 1175, 'https://cdn.myanimelist.net/images/anime/1034/135878.jpg');
