INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('RWBY: Hyousetsu Teikoku', 'TV', 12, 'Completed', '2022-07-03', '2022-09-18', '6', 'Since ancient times, the world of Remnant has been under constant threat by the Grimm: creatures of nightmare obsessed with destroying both humans and the half-human Faunus. To protect themselves, the four kingdoms of the world established academies that train young people to become huntsmen: warriors tasked with destroying Grimm.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Minami Kamakura Koukou Joshi Jitensha-bu', 'TV', 12, 'Completed', '2017-01-07', '2017-03-25', '6', 'Maiharu Hiromi has moved from Nagasaki to Kamakura. She begins her new life in Kamakura and her first day in Minami Kamakura High School by cycling to her school, but she has not ridden a bicycle in many years. On the way to the first day ceremony she almost crashes into Akizuki Tomoe. Obviously Hiromi needs a lot more practice, so Tomoe decides to help Hiromi train to become better at riding a bicycle, and they become good friends.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zhandou Wang Zhi Jufeng Zhan Hun', 'TV', 52, 'Completed', '2012-08-23', '2013-08-18', '6', 'Dawn and Athas find a mysterious sleeping boy, Pandora, who suffers from amnesia after he comes around. When Pandora just arrives at Freewheel Town, he becomes the chasing target of an organization called Ancient Hunter Group, which demands of him to carry out the "Great Mission". Under the attack of Jin and his friends, Ancient Hunter Group is temporarily repelled. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yi Ren Zhi Xia Recap', 'Special', 1, 'Completed', '2018-01-10', NULL, '6', 'Recap of the first season of Yi Ren Zhi Xia that aired a week prior to Japanese broadcast of the second season.', 369, 'https://cdn.myanimelist.net/images/anime/1155/92922.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cinderella Girls Gekijou: Kayou Cinderella Theater 3rd Season', 'ONA', 7, 'Completed', '2018-07-03', '2018-09-25', '6', 'Bonus segments of Cinderella Girls Gekijou 3rd Season streamed on The iDOLM@STER Cinderella Girls Mobage following the television broadcast.', 329, 'https://cdn.myanimelist.net/images/anime/1652/90873.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zoo: Hidamari no Shi', 'Movie', 1, 'Completed', '2005-03-19', NULL, '6', 'A man makes a robot girl and tries to teach her the aspects of daily life. But what is his real goal?', 461, 'https://cdn.myanimelist.net/images/anime/1190/93698.jpg');
