INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nui Story 2', 'ONA', NULL, 'Airing', '2024-10-19', NULL, '5', 'Second season of Nui Story.', 684, 'https://cdn.myanimelist.net/images/anime/1060/149983.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Odayaka Kizoku no Kyuuka no Susume.', 'TV', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'When Lizel mysteriously finds himself in a city that bears odd similarities to his own but clearly isn''t, he quickly comes to terms with the unlikely truth: this is an entirely different world. Even so, laid-back Lizel isn''t the type to panic. He immediately sets out to learn more about this strange place, and to help him do so, hires a seasoned adventurer named Gil as his tour guide and protector.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaijuu Sekai Seifuku (TV)', 'TV', NULL, 'Airing', '2025-04-05', NULL, '5', 'Following the chaotic and heartwarming daily lives of Kaijuu who have come to Earth to conquer the world and live with their human masters.', 214, 'https://cdn.myanimelist.net/images/anime/1582/150123.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xian Ji Xun Zong', 'ONA', 48, 'Completed', '2024-09-13', '2025-02-07', '5', 'The protagonist, Lin Chu, was born into a wealthy and prestigious family. However, his parents suddenly disappeared without a trace, the family company was seized by his father''s former assistant, and even the villa he had lived in since childhood was taken over by so-called creditors. Forced to temporarily reside in the Lin family''s old mansion in the suburbs, Lin Chu was surprised to find mysterious voices emanating from a bonsai tree in the courtyard. He unexpectedly entered the bonsai and discovered a sacred mountain and an immortal—Xuanqing Patriarch—sealed within. Xuanqing Patriarch realized Lin Chu possessed the ability to break the seal and decided to take him as a disciple, teaching him cultivation methods so he can break the seal. At the same time, to repay Lin Chu, Xuanqing Patriarch also agreed to teach him some skills to help him investigate the truth behind his parents'' disappearance. Lin Chu agreed to Xuanqing Patriarch''s request and thus embarked on the path of cultivation!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyoushi no K', 'ONA', 24, 'Completed', '2024-10-06', '2025-04-06', '5', 'Mini anime for Touhai: Ura Rate Mahjong Touhai Roku.', 39, 'https://cdn.myanimelist.net/images/anime/1291/145973.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cap Kakumei Bottleman DX: Side Story', 'ONA', 8, 'Completed', '2022-08-21', '2022-11-27', '5', 'Side stories to Cap Kakumei Bottleman DX released biweekly on the Takara Tomy YouTube channel.', 320, 'https://cdn.myanimelist.net/images/anime/1671/128992.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Phantom in the Twilight Recap', 'ONA', 1, 'Completed', '2018-09-10', NULL, '5', 'A short recap of the first ten episodes of Phantom in the Twilight.', 499, 'https://cdn.myanimelist.net/images/anime/1903/127231.jpg');
