INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shouri Toushu', 'Movie', 1, 'Completed', '1987-10-24', NULL, '5', 'Baseball coach Hoshiyama offers a chance to turn professional to Katsumi Kunimasa, a star member of the student squad that won the summer tournament. The young girl becomes a star pitcher for the Chunchi Dragons (conveniently, the team her father owns), and, after a year of triumphs, she leads them to victory in the national championships at the legendary Koshien Stadium. Based on the manga by Noriko Umeda, this anime may be compared to the other girl-playing baseball story "Song of the Baseball Enthusiasts". 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Marude Dameo', 'TV', 47, 'Completed', '1991-11-02', '1992-09-26', '5', 'The series stars an elementary school boy named Dameo Marude, who has little success with anything he tries, and a robot named Borot, which is good with housekeeping.
