INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Himekishi wa Barbaroi no Yome', 'TV', NULL, 'Upcoming', '2026-04-01', NULL, '5', '"Just kill me!" These are the words of Serafina de Lavillant, the strongest female knight in the West. After being defeated in a war with the East, she has become a prisoner of the barbarians! What awaits the captive Serafina is a life of revenge, torture, and humiliation... or so she thought! What she is offered instead is a marriage to the barbarian king?! An intriguing tale of otherworldly marriage is about to begin!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Slime Boukenki', 'Special', 1, 'Completed', '1995-08-01', NULL, '5', 'A short anime directed by Itsuro Kawasaki and produced by Production I.G, which was shown at the V Jump Festival ''95. The special is based on the manga of the same name by Osamu Kaneko.', 704, 'https://cdn.myanimelist.net/images/anime/1292/145887.jpg');
