INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nakado Riku Animation: Hijouyou Mochidashi Bukuro wo Youi Shiyou', 'ONA', 1, 'Completed', '2019-03-11', NULL, '5', 'For the 8th anniversary of the Great East Japan Earthquake, Fukushima Prefecture support character Nakado Riku and her friends teach us how to prepare an earthquake survival kit.', 264, 'https://cdn.myanimelist.net/images/anime/1068/109076.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kotencotenco', 'TV', 52, 'Completed', '2005-10-06', '2006-09-28', '5', 'Kotencotenco is a gag strip anime for young children featuring the flourishes of the Prince of the country of the Paradice, Kotenco.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rusuban', 'Movie', 1, 'Completed', '1996-01-01', NULL, '5', 'A Handmade Animated Cat! Stop and Look at Me for just 4 minutes! It''s the first time for the Cat to be all by itself at home. This Cat does not have a name yet and nobody knows whether it is female or male. And it has two faces, one is very sensitive and the other is rather naughty. We try to make sensitive animations, and do not want to bombard children with too much noise and too many images. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Miao Qiansui de Chengnian Li', 'ONA', 7, 'Completed', '2020-08-06', '2020-08-12', '5', 'Sanwei Mountain is home to an ancient civilization, where Miao Qiansui and her sister Nuluo live. Miao Qiansui is an innocent little girl, full of curiosity about the outside world. In her memory, there has always been a mysterious place called Moon Lake. But is the Moon Lake real? Can she go to Moon Lake smoothly?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Renwu Dashi', 'ONA', 6, 'Completed', '2020-08-03', '2020-09-12', '5', 'This is an adventure story about Ah Shu and Ah Lang. Ah Shu is the executor of the mission, and Ah Lang is the intermediary of the "Task Association," specifically looking for tasks for Ah Rat. While the two were constantly completing various difficult tasks, Ah Shu revealed his yearning for something indescribable – "The Sea of ​​Stars"; while Ah Lang was also looking for clues to the disappearance of the family during various tasks. The two learned from the mission that in addition to the present world, there is an "upper world," and various signs indicate that Ah Shu''s yearning and the clues Ah Lang is looking for point directly to the "upper world," even "more upper world."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Midoriyama Koukou Koushien-hen (Movie)', 'Movie', 1, 'Completed', '1990-06-30', NULL, '5', 'Compilation of episodes 1-4 of the OVA.', 67, 'https://cdn.myanimelist.net/images/anime/4/23071.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Biriken Nandemo Shoukai', 'TV', 22, 'Completed', '1989-04-10', '1989-09-18', '5', 'The sequel to Biriken series.', 802, 'https://cdn.myanimelist.net/images/anime/1089/120951.jpg');
