INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dab-eul Chaj-eun du Sonyeon', 'Special', 1, 'Completed', '2015-11-11', NULL, '5', 'Two young boys play a computer game that involves shooting asteroids, and lose the second match. In order to beat it, they must learn about the Earth. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lyeonglihan Neoguli', 'TV', 63, 'Completed', '1987-01-01', '2009-01-01', '5', 'Clever Raccoon Dog is a North Korean animated television series produced by SEK Studio which aired on North Korean state television. The series was produced for a number of years and features both old and new animation style, depending on the production year of each episode. The series focuses on three main characters: A raccoon dog, A male bear and A female cat, often involved in minor adventures or incidents. Each episode has a scholastic element or a particular message, focusing on matters as scientific information, road safety, commitment to sport and contests, among others. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sore Ike! Anpanman: Tanoshiku Teasobi Mama ni Natta Kokin-chan!?', 'Movie', 1, 'Completed', '2014-07-05', NULL, '5', 'Kokin-chan, Dokin-chan''s little sister, is a master of fake tears. One day, she finds an egg that hatches into Tefutefu, a caterpillar who recognizes Kokin-chan as her mother! Sing and dance with Kokin-chan, Anpanman and the rest as their newborn friend grows up!', 990, 'https://cdn.myanimelist.net/images/anime/1406/125699.jpg');
