INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zokuzoku Mura no Obake-tachi', 'OVA', 12, 'Completed', '1996-02-21', '1999-04-21', '5', 'A succession of tales taken from the 1.3-million-selling children''s books by Akiko Sueyoshi and Mako Taruishi, including Ram the Mummy, Obatan the Witch, The Childish Goblin, and Kitten Ghosts Goo, Soo and Pea.
