INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaijuu Girls: Ultra Kaijuu Gijinka Keikaku', 'ONA', 12, 'Completed', '2016-09-27', '2016-12-13', '6', 'Very rarely is a girl born with two distinct souls: one of a human and the other of a kaiju. These extraordinary individuals, dubbed "Kaiju Girls," possess the form of a normal person and the supernatural abilities of a giant monster. The International Kaiju Rescue and Mentoring Organization, also known as GIRLS, was created to help these Kaiju Girls adjust to their powers and find a place in society. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Azur Lane Recap', 'Special', 1, 'Completed', '2019-11-14', NULL, '6', 'Recap of the first six episodes of Azur Lane narrated by Enterprise.', 128, 'https://cdn.myanimelist.net/images/anime/1713/104378.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mini Hama: Minimum Hamatora Movies', 'Movie', 2, 'Completed', '2015-11-14', NULL, '6', 'Two special episodes of Mini Hama promoting the Fw:Hamatora movie.', 510, 'https://cdn.myanimelist.net/images/anime/7/76836.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doushitemo Eto ni Hairitai', 'TV', 13, 'Completed', '2015-10-11', '2016-01-10', '6', 'Rat, a member of the Zodiac, meets a normal cat at a park one day. Rat comes to love Cat so much that it becomes very eager to get Cat to become a member of the Zodiac. Cat goes with Rat to meet the rest of the 12 members of the Zodiac to ask them to become a member.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Go for 2020', 'Special', 1, 'Completed', '2016-09-20', NULL, '6', 'Studio Colorido was commissioned by Japanese real estate developer Mitsui Fudosan to create a promotional video for their BE THE CHANGE campaign, in anticipation of the Tokyo 2020 Summer Olympic and Paralympic games. Initiatives from the campaign include communal sport academies, promotional city dressing, and the FUTSUJANAI TEN interactive sports exhibition. In particular, the campaign supports sport climbing, wheelchair rugby, and women''s basketball, the later of which is featured in the video.', 870, 'https://cdn.myanimelist.net/images/anime/1765/106088.jpg');
