INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oam Monogatari: Sono Natsu, Watashi ga Shitta koto', 'ONA', 1, 'Completed', '2018-04-08', NULL, '6', 'A tourism promotion anime for Ogaki City in the Gifu Prefecture. It is based on Oam Monogatari, a book about a woman who spent her coming-of-age during the Sengoku Era. Oam is the main character and is the daughter of Yamada Kyoreki who is a vassal to the warlord Ishida Mitsunari. It offered one of the few historical viewpoints of an noble teen/woman''s life during the wars. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Oi-san to 40 no Monogatari', 'ONA', 41, 'Completed', '2018-03-26', '2018-09-19', '6', 'Fourty shorts featuring a delightfully chubby cat named Oi-san. This entry also includes the unnumbered "はじまり" (Hajimari) episode that was released the same day as the numbered episode 1.', 557, 'https://cdn.myanimelist.net/images/anime/1760/93247.jpg');
