INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sakura Internet', 'Special', 1, 'Completed', '2017-01-26', NULL, '6', 'Freelancer Touno Kouhei, office lady Hamada Saori, and graphic designer Ginji realize that they''re not content in their current jobs, and break free to pursue their dreams - as a musician, a photographer, and an artist, respectively.
