INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Muumin Pilot Film', 'Special', 1, 'Completed', '1989-12-16', NULL, '5', 'The pilot film for the 1969 Moomin TV series. It was released to the public on the first LD volume of the 1969 series.', 1035, 'https://cdn.myanimelist.net/images/anime/1908/107754.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Crayon Shin-chan Specials', 'Special', NULL, 'Airing', '1992-12-28', NULL, '5', '87 Crayon Shin-chan TV Specials exist as of August 6, 2022.', 802, 'https://cdn.myanimelist.net/images/anime/1474/107403.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('AWOL Compression Re-MIX', 'OVA', 4, 'Completed', '1998-08-25', '1998-12-18', '5', 'Cyress was a peaceful planet until Solomon, a mysterious terrorist group lead by Duran Gash, seizes seven PDP missiles that are capable of destroying entire planets. Jim Hyatt is chosen to be the man to lead a team to do what seems to be impossible: Find a way to both rescue the hostages and reclaim or destroy the deadly PDP missiles. The problem though is that the team members don''t really like each other...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shimajirou Hesoka', 'TV', 99, 'Completed', '2010-04-05', '2012-03-26', '5', 'Third season of the Shimajirou children''s television series.', 683, 'https://cdn.myanimelist.net/images/anime/8/50735.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The Midnight★Animal', 'ONA', 12, 'Completed', '2013-08-03', '2014-01-22', '5', 'The story is set in Savannah''s 2nd district, where diva-like animals gather in the dead of night to wax poetic about topics that transcend gender.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pakkororin', 'TV', NULL, 'Airing', '2011-03-28', NULL, '5', 'A minute long children''s anime that follows 3 siblings. Two brothers who are rectangular and circular shaped, and a sister who is triangluar shaped. They have unique personalities and foster growth and discovery through their play time.', 1025, 'https://cdn.myanimelist.net/images/anime/1134/93318.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Neko Konogoro', 'TV', 50, 'Completed', '2016-06-08', '2016-10-05', '5', 'Based on the characters created by Study.', 457, 'https://cdn.myanimelist.net/images/anime/1877/91297.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maji de Wakaru! Waccha PriMagi Gakuen', 'Special', 1, 'Completed', '2022-01-09', NULL, '5', 'Special episode of Waccha PriMagi! that aired between episodes 13 and 14.', 1009, 'https://cdn.myanimelist.net/images/anime/1838/120452.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Huan Bian Jingling: Dangao Tianxin', 'TV', 40, 'Completed', '2012-11-10', '2013-02-18', '5', 'The Sweetsheart Kingdom  is a magical world filled with various sweets and pastries, inhabited by animal people who are good patisseries and cooks experting on each dessert. The kingdom''s only Princess, Mousse Bibi is soon going to ascend to the throne as the new Queen, however all she cared on her life is to taste various kinds of cakes and sweets. One day, Lyan, her royal adviser, set up a plan by making her suffer Aguesia. As she is shocked that she can no longer taste anything, he told her that the only way to cure her condition is to search for the legendary magic called Delicious Miracle. She immediately left the castle and venture outside, not knowing to her that Lyne is doing this to eradicate her.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sprin'' Pan: Mae e Susumou!', 'Movie', 1, 'Completed', '2017-06-13', NULL, '5', 'An original animation project shown by CGCG Studio HD at Mifa with Annecy International Animation Film Festival.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Honoo no Alpenrose: Sweet Memory Ongaku-hen', 'OVA', 1, 'Completed', NULL, NULL, '5', 'A music-video style recap OVA. This release covers episode 1-11. Some music used is full song versions with accompanied singing, other sections of the recap are entirely classical Austrian music.', 1009, 'https://cdn.myanimelist.net/images/anime/9/85887.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Line Rangers', 'ONA', 10, 'Completed', '2014-07-24', '2016-09-19', '5', 'Line Rangers follows the Line characters as super heroes who battle enemies. The various "story movies" of the web anime are meant to promote the Line Rangers RPG game app.', 233, 'https://cdn.myanimelist.net/images/anime/13/85872.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Anime-ban Little★Nicky: Henachoko Akuma Nicky no NY Taikenki', 'ONA', 6, 'Completed', '2001-04-09', '2001-05-08', '5', 'An anime tie-in to the Adam Sandler film Little Nicky that expands slightly on the story, showing the demonic Nicky exploring New York.', 199, 'https://cdn.myanimelist.net/images/anime/1375/93755.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sekirei: Pure Engagement Episode 0', 'Special', 1, 'Completed', '2010-08-25', NULL, '7', 'Episode 0, consisting of two subepisodes: "Sekirei Shindan" (鶺鴒診断) and "Sekirei Yoka" (鶺鴒余暇), of Sekirei: Pure Engagement included on the first DVD/BD volume.', 786, 'https://cdn.myanimelist.net/images/anime/9/25948.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cheburashka', 'Movie', 1, 'Completed', '2010-12-18', NULL, '7', 'The stop-motion animated film based on Russia''s Cheburashka character.', 190, 'https://cdn.myanimelist.net/images/anime/5/25871.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ano Natsu de Matteru: Bokutachi wa Koukou Saigo no Natsu wo Sugoshinagara, Ano Natsu de Matteiru.', 'Special', 1, 'Completed', '2014-08-29', NULL, '7', 'Special episode included in the Blu-ray Box of Ano Natsu de Matteru.', 436, 'https://cdn.myanimelist.net/images/anime/13/63493.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chuukan Kanriroku Tonegawa', 'TV', 24, 'Completed', '2018-07-04', '2018-12-26', '7', 'Chuukan Kanriroku Tonegawa is a spin-off of the Kaiji series, which follows Tonegawa, the right hand man of Kazutaka Hyoudou, the president of the Teiai Corporation and owner of numerous gambling tournaments. After Hyoudou is getting bored with his life, he orders Tonegawa to organize a so called "game of death" as it is his and his subordinate''s job to keep the president in a good mood. Tonegawa must cooperate with his subordinates in order to make the president happy and what follows is a humorous story of his interactions with his subordinates and other characters of the Kaiji series.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Munou na Nana', 'TV', 13, 'Completed', '2020-10-04', '2020-12-27', '7', 'Fifty years ago, horrific creatures dubbed as the "enemies of humanity" suddenly appeared around the world. To combat these threats, teenagers gifted with supernatural abilities called "Talents"—such as pyrokinesis and time travel—hone their powers at an academy on a secluded island. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Druaga no Tou: The Sword of Uruk', 'TV', 12, 'Completed', '2009-01-09', '2009-03-27', '7', 'With broken spirits and enigmatic questions that hold no answers lingering, Jil is still trying to figure everything out. Then, a mysterious girl named Kai appears before him and says: "Take me to the top of the tower."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece: Oounabara ni Hirake! Dekkai Dekkai Chichi no Yume!', 'Special', 1, 'Completed', '2003-04-06', NULL, '7', 'The story opens on Pirate Zap''s ship, where two of his crew, Bonnie and Max, are tired and want to escape, but unfortunately they have no money. Three children were being held captive on the ship overhear them. The eldest, Amanda, who''s father was a pro treasure hunter, knows the whereabouts of a great treasure, and offers them a deal. If they help them make a clean escape, they could take all the treasure they wanted. They agree, and the five of them barely escape and make it onto a small island where they meet Luffy and his crew. Unfortunately they were pursued and Luffy and Amanda are captured and brought back to their boss, the head of the Bayan Pirates, who is also after the treasure. Now Luffy and the others must battle the Bayan pirates and find the treasure that Amanda''s father had left for his children. Amanda, who has always resented adventure and treasure because her father was constantly gone in search for it, finally understands his feelings. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shakugan no Shana-tan II (Second)', 'Special', 3, 'Completed', '2008-01-25', '2009-10-19', '7', 'Shana-tan specials bundled with the limited edition first and fifth volumes of the Shakugan no Shana II (Second) DVD and the limited edition Shakugan no Shana II (Second) guide book.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon Movie 05: Mizu no Miyako no Mamorigami Latias to Latios', 'Movie', 1, 'Completed', '2002-07-13', NULL, '7', 'As they continue their journey through the Johto region, Satoshi and his friends visit Altomare, an island city that hosts an annual racing event called the Pokémon Water Race. While Takeshi and Kasumi are enjoying themselves, strange things seem to be happening to Satoshi—he somehow loses the water race, sees some women attack a girl with their Pokémon, and despite them saving her, the girl later denies ever seeing Satoshi and Pikachu before!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Utawarerumono OVA', 'OVA', 3, 'Completed', '2009-06-05', '2010-06-23', '7', 'A three part OVA of Utawarerumono. The animation work will be done by the same staff that did the opening of the game the show was based on. The story will cover parts that weren''t shown in the anime series. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wagaya no Oinari-sama.', 'TV', 24, 'Completed', '2008-04-07', '2008-09-15', '7', 'The Mizuchi bloodline has long been hunted by Yokai, or monsters. Toru and Noboru Takagami are descendents of this bloodline, and under their grandmother''s discretion, are given a secret weapon to combat these monsters. It is Tenko Kugen, a fox deity who can take the shape of a man or woman at will. The mischievous deity is accompanied by a shrine maiden, Ko, who will both live with the Takagami brothers at their house. Life just got complicated. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Juu Ou Sei', 'TV', 11, 'Completed', '2006-04-14', '2006-06-23', '7', 'After the murder of their parents, 11-year-old twin brothers Thor and Rai Klein are sent away from their home planet. They find themselves awakening on the terraformed planet of Chimaera, where carnivorous plants dominate and the few humans who live there are divided into four groups known as "Rings." Soon after, they meet a young man by the name of Zagi, and the twins learn that only the "Jyu Oh Sei"—the one who conquers these four Rings—is allowed to leave the planet. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tokimeki Tonight', 'TV', 34, 'Completed', '1982-10-07', '1983-09-22', '7', 'Fifteen-year-old Ranze Etou lives a normal life for any girl her age—except for the fact that she resides in a castle with a vampire father and a werewolf mother who constantly worry about her lack of powers.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rewrite 2nd Season', 'TV', 11, 'Completed', '2017-01-14', '2017-03-25', '7', 'The second season of the Rewrite series which adapts Moon and Terra routes.', 12, 'https://cdn.myanimelist.net/images/anime/13/83930.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tetsuwan Atom (1980)', 'TV', 52, 'Completed', '1980-10-01', '1981-12-23', '7', 'Set in a future where machines have advanced to the point of autonomy and become a point of major contention in the political and social realms, Astro Boy (1980) chronicles the struggles of a crime-fighting young robot named Atom. Created in the image of his enigmatic inventor''s deceased son, Atom survives rough beginnings, getting saved and adopted by the benevolent Dr. Ochanomizu. In his pursuit of justice, Atom finds himself in the midst of numerous clashes with various factions, and is often faced with the harsh realities of the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyou no 5 no 2', 'OVA', 4, 'Completed', '2006-03-24', '2007-03-21', '7', 'Kyou no Go no Ni revolves around Sato Ryota, a 5th grader in an elementary school. He is a bright and active boy but always manages to get in to a bit of ecchi trouble with his female classmates.', 803, 'https://cdn.myanimelist.net/images/anime/6/42631.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tabisuru Nuigurumi: Traveling Daru', 'Movie', 1, 'Completed', '2012-04-04', NULL, '7', 'Daru, a cherished handmade stuffed toy, gets lost and separated from its owner one day when at the airport. Determined to find her again, Daru sets out on a journey around the world in search of her. As time passes, the girl begins to forget about Daru. Will Daru be able to find and see his beloved owner again?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Doraemon Movie 10: Nobita no Nippon Tanjou', 'Movie', 1, 'Completed', '1989-03-11', NULL, '7', 'Nobita wants to run away from home, again. He finds out that there is nowhere for him to go. All the land is owned by someone. His friends end up wanting to run away also, even Doraemon. They figure out that the only way to find land that isn''t owned by anyone is to go back in time to when no humans existed. They end up helping a prehistoric boy rescue his tribe from Gigazombie.', 802, 'https://cdn.myanimelist.net/images/anime/8/72415.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meitantei Conan OVA 03: Conan to Heiji to Kieta Shounen', 'OVA', 1, 'Completed', '2003-01-01', NULL, '7', 'Conan and Ran are visiting Heiji and Kazuha in Osaka when the four come across a trio of kids while touring the city. These children, who look eerily similar to the Detective Boys but with different personalities, are looking for their friend who has gone missing—and the two young detectives agree to help find the vanished boy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Otome Game no Hametsu Flag shika Nai Akuyaku Reijou ni Tensei shiteshimatta... Movie', 'Movie', 1, 'Completed', '2023-12-08', NULL, '7', 'After Catarina avoids her own death flag, she and her friends run into a mysterious young man traveling with a caravan. Who is this young man and what does he want?', 761, 'https://cdn.myanimelist.net/images/anime/1360/138828.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Little Nemo', 'Movie', 1, 'Completed', '1989-07-15', NULL, '7', 'Based on the classic Nemo comic strips by Winsor McCay. A pioneer of animation, McCay created the first Little Nemo animated movie in 1911.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuu☆Yuu☆Hakusho: Eizou Hakusho - Ankoku Bujutsukai no Shou', 'OVA', 2, 'Completed', '1994-09-21', '1994-10-05', '7', 'These are two recap specials that focus on Team Urameshi''s matches in the Dark Tournament, with a few character songs playing in the background. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Thermae Romae Novae', 'ONA', 11, 'Completed', '2022-03-28', NULL, '7', 'Lucius Modestus, an ancient Roman architect, finds himself job-hunting due to having trouble coming up with new ideas. As his demeanor and personality become dismal, his friends try taking him to a bathhouse for him to relax. Unable to unwind in the bustling and crowded bath, Lucius dips his head in the water. Down there, he finds a secret tunnel that transports him to a modern-day Japanese bathhouse, providing him the inspiration he needed to make a new creation.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dimension W', 'TV', 12, 'Completed', '2016-01-10', '2016-03-27', '7', 'In the near future, humans have discovered a fourth dimension, Dimension W, and a supposedly infinite source of energy within. In order to harness this profound new energy, mankind develops advanced "coils," devices that link to and use the power of Dimension W. However, by year 2071, the New Tesla Energy corporation has monopolized the energy industry with coils, soon leading to the illegal distribution of unofficial coils that begin flooding the markets.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Miss Monochrome The Animation 3', 'TV', 13, 'Completed', '2015-10-02', '2015-12-25', '7', 'Third season of Miss Monochrome: The Animation.', 756, 'https://cdn.myanimelist.net/images/anime/6/76089.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Monster Musume no Iru Nichijou: Hobo Mainichi ◯◯! Namappoi Douga', 'ONA', 60, 'Completed', '2015-07-08', '2015-09-29', '7', 'Anime shorts that offer a secret candid look at the daily lives of Monster Musume. The shorts will update almost every weekday, but each short will be available for 24 hours only. The weekends will have a digest version summarizing the week''s videos.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Persona 4 the Golden Animation: Thank you Mr. Accomplice', 'Special', 1, 'Completed', '2014-12-10', NULL, '7', 'After Yuu finds out the past and circumstances of Adachi, he makes a single decision in order to save him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiang Ling Ji', 'ONA', 15, 'Completed', '2017-03-22', '2017-08-16', '7', 'The 19-year-old tomboy exorcist Hua Jiu got to know ''evil spirit'' Seven Lord and forced him to be her spirit servant when cleansing spirits. Later the human being and the spirit set forth on a journey of ranting each other and cleansing spirits. However, Hua Jiu''s enemy started insidious revenge at the same time... 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Princess Principal: Ange Report', 'ONA', 1, 'Completed', '2017-09-16', NULL, '7', 'Chronological summary of episode 1 to 8 of Princess Principal.', 48, 'https://cdn.myanimelist.net/images/anime/10/87902.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mu Wang Zhi Wang: Qi Lin Jue', 'ONA', 20, 'Completed', '2016-07-21', '2016-11-24', '7', 'Luo Wu Zi helped Li Si Xiu to build the mound of Qin Shi Huang; the first emperor who united China. His disciples continued to build and safeguard the royal tombstone. In between lies the appearance of the Nine Great Tombstones, also known as Great King of the Graves. For thousands of years, the tombs were never robbed. The outsiders regard these guardians of the tombs like the Tomb Sect. After the death of Luo Wu Zi, the position of Grave King is transferred to his eldest disciple, Mu Rong Xiu.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fuuka', 'TV', 12, 'Completed', '2017-01-06', '2017-03-24', '7', 'The story follows the life of Yuu Haruna, who recently moved into Tokyo with his sisters after their father is forced to transfer overseas on work.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Inu to Hasami wa Tsukaiyou', 'TV', 12, 'Completed', '2013-07-02', '2013-09-17', '7', 'A nonsense comical mystery. Harumi Kazuhito is a high school boy who loves books and is a fan of novelist Natsuno Kirihime. One day, he finds Kirihime writing at a cafe, about to be shot by a robber. He protects her from the attack but is killed instead. Through the supernatural power of a book-worm, he is reincarnated as a dachshund dog. Kazuhito (as a dog) writhes in a painful bookless life, when a sadistic woman carrying a pair of scissors offers him help. She is Kirihime herself.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Action Heroine Cheer Fruits', 'TV', 12, 'Completed', '2017-07-07', '2017-09-29', '7', 'Several years ago, local heroines—superhero characters who represent towns and perform stage shows in order to raise their town''s acclaim—had a boom in popularity. The most famous of these local heroines, Kamidaio, is scheduled to perform in the small town of Hinano, much to the excitement of Mikan Kise''s little sister Yuzu. Unfortunately, when Mikan takes Yuzu to the show, she finds out that it has been canceled. She promises her distraught sister that she''ll make sure she can see the show. Desperate not to let her down, Mikan asks her classmate, the local heroine fanatic An Akagi, for help.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kochouki: Wakaki Nobunaga', 'TV', 12, 'Completed', '2019-07-08', '2019-09-23', '7', 'The fearsome warlord, the demonic king—Oda Nobunaga! Before he was trying to rule over Japan, he was a teenager who began his path to greatness with his younger brother and faithful followers. Through succession, betrayal, battles, and bonds between one another, the struggles these boys face promise a future where they can blossom into powerful men.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Blood Lad: Kanketsu Kinen', 'Special', 1, 'Completed', '2017-01-11', NULL, '7', 'A short conclusion memorial PV promoting the final tankoubon volume of the Blood Lad manga going on sale. The PV shows various moments throughout the whole manga.', 143, 'https://cdn.myanimelist.net/images/anime/11/83781.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kochira Katsushikaku Kameari Kouenmae Hashutsujo: Hashire! Ryoutsu-shiki Chinchin Densha', 'Special', 1, 'Completed', '2006-04-02', NULL, '7', 'The first Kochikame television special of 2006.', 325, 'https://cdn.myanimelist.net/images/anime/8/81547.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Motto! Majime ni Fumajime Kaiketsu Zorori', 'TV', 25, 'Completed', '2020-04-05', '2020-11-08', '7', '', 53, 'https://cdn.myanimelist.net/images/anime/1401/106017.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Naisho no Tsubomi', 'OVA', 3, 'Completed', '2008-04-25', '2008-06-27', '7', 'Tsubomi Tachibana is a fifth grader dealing with rather sensitive issues such as her mother''s pregnancy, her first period and the strange feelings she has started to get when she has been around boys.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bakuon!!', 'TV', 12, 'Completed', '2016-04-05', '2016-06-21', '7', 'Every day Hane Sakura makes the arduous trip to school, cycling up a large hill on her bicycle. After encountering the motorcycle enthusiast Onsa Amano one morning, she is introduced to the motorcycle club, led by the ever-silent Raimu Kawasaki. New to motorcycles, Sakura experiences firsthand the difficulty of learning to ride again. However, through this, she hopes to once again recreate her first biking experience, which was filled with both horror and exhilaration.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shi Xiong', 'ONA', 41, 'Completed', '2014-11-24', '2015-03-05', '7', 'Protagonist XiaoFei used to be an ordinary guy from H city. After the spring water was contaminated with a virus, however, he unexpectedly encountered an unprecedented crisis. The people living in H City became zombies one by one, devouring each other, and gradually evolving. Can XiaoFei escape from H city and meet up with his girlfriend Wei? The story now begins...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wooser no Sono Higurashi: Mugen-hen', 'TV', 13, 'Completed', '2015-07-03', '2015-09-25', '7', 'The zany and cute-but-crude Wooser returns for another season in Wooser’s Hand-to-Mouth Life: Phantasmagoric Arc! Wooser is a creature that only cares about three things in life: meat, money, and girls.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ikkitousen: Xtreme Xecutor Specials', 'Special', 6, 'Completed', '2010-06-25', '2010-11-25', '7', 'Ikkitousen: Xtreme Xecutor Blu-ray and DVD specials.', 85, 'https://cdn.myanimelist.net/images/anime/10/22814.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Anime de Wakaru Shinryounaika', 'ONA', 20, 'Completed', '2015-02-13', '2015-06-26', '7', 'The psychologist Ryou and his cheerful nurse Asuna explain many aspects of mental illness to the reader. They cover topics such as the validity, prevalence, and origins of mental disorders, in addition to addressing specific disorders. The information is imparted in a cheerful and comic manner, with various jokes, puns, and pop culture references.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ai Monogatari: 9 Love Stories', 'OVA', 1, 'Completed', '1993-04-02', NULL, '7', 'An OVA based on the work of Kawaguchi Kaiji consisting of nine independent stories, each animated by a different director. With Beatles music involved, somewhere.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fight Ippatsu! Juuden-chan!! Specials', 'Special', 6, 'Completed', '2009-12-18', '2010-05-21', '7', 'Special side stories included with the DVD version of Fight Ippatsu! Juuden-chan!!', 903, 'https://cdn.myanimelist.net/images/anime/2/18791.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nils no Fushigi na Tabi (Movie)', 'OVA', 1, 'Completed', '1985-10-01', NULL, '7', 'Nils Holgersson is a young boy on a farm who is cruel to the animals. But when he catches the farm''s little goblin it becomes one prank too many. He is magically shrunk and suddenly the farm animals are out for revenge. He flees on the back of the goose Morten and they join up with a flock of wild geese. Together they travel all over Sweden, with Nils hoping to find a way to become big again. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dragon Quest: Dai no Daibouken Tachiagare!! Aban no Shito', 'Movie', 1, 'Completed', '1992-03-07', NULL, '7', 'The second Dragon Quest Dai no Daibouken movie. The story takes place between episode 18 and 19 of the TV series.', 1030, 'https://cdn.myanimelist.net/images/anime/12/31457.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaibutsu Oujo Specials', 'Special', 3, 'Completed', '2010-12-09', '2011-10-07', '7', 'Specials of 4 minutes which recounts the adventures of Kerberotte-chan including characters of Princess Resurrection.', 1009, 'https://cdn.myanimelist.net/images/anime/11/66099.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fuyu no Sonata: Joshou - Hatsuyuki no Negai', 'Special', 1, 'Completed', '2009-10-10', NULL, '7', 'Based on the Korean drama television series about the love between two childhood friends and the tragic events that happen.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sayounara Ryuusei, Konnichiwa Jinsei', 'TV', 12, 'Completed', '2024-10-11', '2024-12-27', '6', 'Long ago, a human managed to defeat the oldest, most powerful dragon of them all. This dragon was so strong that even the gods feared it, but it accepted its end all alone. Then, suddenly, the dragon woke up in a new life as a guy named Dolan, living in a faraway village.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiao Lu He Xiao Lan 5th Season', 'ONA', 12, 'Completed', '2024-03-13', '2024-05-29', '6', '', 130, 'https://cdn.myanimelist.net/images/anime/1878/146569.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ore dake Level Up na Ken: How to Get Stronger', 'Special', 1, 'Completed', '2024-02-25', NULL, '6', 'Recap of the first seven episodes of Ore dake Level Up na Ken.', 14, 'https://cdn.myanimelist.net/images/anime/1043/141605.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lili Kurong', 'ONA', 1, 'Completed', '2024-01-28', NULL, '6', 'A short film directed by Yakumo Crack for the Arknights 2024 Spring Festival Gala.', 330, 'https://cdn.myanimelist.net/images/anime/1802/141229.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ochibi-san', 'TV', 24, 'Completed', '2023-10-08', '2024-03-31', '6', '"I can help you laugh, but I can''t take away the tears you''ve shed." In Mametsubu-cho, a town somewhere in the ancient Japanese city of Kamakura, Ochibi-san lives a relaxed, easy life. With his friend Nazeni the dog, Jack the naughty kitten, and Pankui the hungry dog, Ochibi-san''s year in Mametsubu-cho is filled with encounters and new discoveries! Flower-viewing in spring, swimming in summer, collecting leaves in fall, and eating yummy food in winter.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('RoboMasters the Animated Series', 'TV', 6, 'Completed', '2017-10-13', '2017-11-17', '6', 'The series will depict college students as they prepare and participate in a RoboMasters tournament.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Heroman Specials', 'Special', 3, 'Completed', '2010-09-22', '2011-03-16', '6', 'Heroman specials released in DVD/BD volumes 2, 5 and 8.', 138, 'https://cdn.myanimelist.net/images/anime/10/44081.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('FLCL Progressive', 'Movie', 1, 'Completed', '2018-09-28', NULL, '6', 'Hidomi Hibajiri is a disillusioned young girl who never takes off her headphones. Her whole life consists of going to school, helping out at her mother''s cafe, and listening to music. And with nothing else to break the crippling monotony, she keeps her headphones on at all times. That is, until she is run over by a mysterious guitar-wielding woman.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koha Ginjiro', 'OVA', 3, 'Completed', '1991-05-22', '1991-11-20', '6', 'After the death of his elder brother, Ginjiro Yamazaki appoints himself his parents'' protector. After transferring to a new school, he gets into a lot of fights.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Scratch x One Piece Film: Gold', 'Special', 1, 'Completed', '2016-05-01', NULL, '6', 'A TV collaboration between One Piece Film: Gold and Takarakuji the nationwide lottery system in Japan. The commercial is promoting lottery scratch cards with One Piece designs on them.', 1030, 'https://cdn.myanimelist.net/images/anime/8/87541.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wangpai Yushi Di 0 Ji', 'ONA', 1, 'Completed', '2014-01-01', NULL, '6', 'Episode 0 of Wangpai Yushi.', 369, 'https://cdn.myanimelist.net/images/anime/7/72199.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bai Gui Youeryuan 3rd Season', 'ONA', 12, 'Completed', '2020-05-21', '2020-08-06', '6', 'Third season of Bai Gui Youeryuan.', 663, 'https://cdn.myanimelist.net/images/anime/1984/108463.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kumi to Tulip', 'Movie', 1, 'Completed', '2015-03-22', NULL, '6', 'Kumi is a little girl who lives in a world with sparkling metal skyscrapers, and where robots support everything. Kumi''s playground is a garden by one of those skyscrapers with a man-made water fountain, artificial vegetation, and digital water and butterflies. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cybot Robocchi', 'TV', 39, 'Completed', '1982-10-07', '1983-06-29', '6', 'Apparently inspired largely by Akira Toriyama''s popular Dr. Slump, Cybot Robocchi is the story of Robocchi, a fun-loving, mischievous robot with a TV set in his stomach.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cyborg 009', 'Movie', 1, 'Completed', '1966-07-21', NULL, '6', 'When Joe Shimamura gets in a serious car crash, strange men quickly load his body into a fake ambulance. He is transported to the headquarters of Black Ghost, an organization that promotes human conflicts in order to profit off of wars. It is here where Joe is reborn as the powerful Cyborg 009.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Manga Aesop Monogatari', 'Movie', 1, 'Completed', '1983-03-13', NULL, '6', 'Aesop is a trouble-making young boy who finds himself in another world filled with creatures he never believed to exist, such as fairies and talking donkeys. He sets off to find a way back to the normal world. On his journey he befriends many classical creatures from well-known fables and encounters many trials, each teaching him a valuable lesson.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Magical★Taruruuto-kun Movie', 'Movie', 1, 'Completed', '1991-03-09', NULL, '6', 'First movie of Magical Taruruuto-kun', 1030, 'https://cdn.myanimelist.net/images/anime/1991/148928.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dies Irae: To the Ring Reincarnation', 'ONA', 6, 'Completed', '2018-07-01', NULL, '6', 'Episodes 12–17 of Dies Irae released exclusively on the web.', 17, 'https://cdn.myanimelist.net/images/anime/1244/93395.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin SOS Dai Tokyo Tankentai', 'Movie', 1, 'Completed', '2007-05-19', NULL, '6', '"While packing for a move, elementary school student Ryuhei finds his father''s old school notebook detailing a search for a treasure in Tokyo''s vast network of underground passages. With his little brother tagging along, he and three friends from an online chat room gather and set out on a quest to find the treasure. What they discover instead is an entire underground community composed of assorted eccentrics, including a senile old soldier still performing a World War II-era mission." 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Twin Bee Paradise', 'OVA', 4, 'Completed', '1998-12-18', '1999-04-25', '6', 'Pastel ate the cookies Madoka made, and it shrunk her, but because of her condition she couldn''t take part in the "Miss Donburi Contest". To return her to normal, she needed the power-up bell from the clouds. However, a mysterious island floating in the air was absorbing clouds above Donburi Island. When they tried to get power bells back, enemies attacked them suddenly. Would they get back for the contest in time? 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Choujin Locke: Lord Leon', 'OVA', 3, 'Completed', '1989-10-25', '1989-12-16', '6', 'It is the year 336 of the Space Century on the planet of Sieren, and in the state of Innex, Flora Rain-who is blind-is employed at an elementary school. Flora is adored by her students, the principal of the school, and all the town’s people, and enjoys a peaceful life in the town.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Riki-Oh: Toukatsu Jigoku', 'OVA', 1, 'Completed', '1989-06-25', NULL, '6', 'A Retelling of the prison arc of the manga RIKI-OH!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dallos', 'OVA', 4, 'Completed', '1983-12-21', '1984-07-05', '6', 'There was a time when life on Earth ran out of resources due to overpopulation. As a result, colonists were sent to the Moon, where they had to do dangerous and challenging mining jobs. Their efforts paid well, as the people of Earth now prosper from the Moon''s bounty—but the colonists'' lives are still riddled with terror.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ebiten: Kouritsu Ebisugawa Koukou Tenmonbu Specials', 'Special', 5, 'Completed', '2012-11-30', '2013-03-29', '6', 'BD/DVD specials.', 28, 'https://cdn.myanimelist.net/images/anime/6/44588.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kishin Houkou Demonbane', 'OVA', 1, 'Completed', '2004-07-01', NULL, '6', 'Lily Bridge, a young journalist, arrives at Arkham City, hoping to find a big scoop. However, with all the strange things occuring around the city, only the exceptional findings are news-worthy, such as the mysterious mecha known as Demonbane. However, upon finding a small piece of machinery that seemed to be connected with the Hadou Combine, Lily is determined to find the truth. Little does she know, she enters into a dark world, involving herself with Demonbane and the powerful forces that control the city.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shining Hearts: Shiawase no Pan Specials', 'Special', 6, 'Completed', '2012-07-27', '2012-12-21', '6', 'The 6 short "Chibi Style" Specials on each of the Blu-rays/DVDs.', 704, 'https://cdn.myanimelist.net/images/anime/13/42153.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mini Van Large', 'ONA', 26, 'Completed', '2021-06-06', '2022-05-03', '6', 'The stage is set on a moon of Planet Cray, "Aniversario." To develop the moon, Selca summons Aichi, Chrono and friends. A large undertaking by familiar vanguard characters!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mi Bao Zhi Guo', 'ONA', 10, 'Completed', '2021-04-16', '2021-06-11', '6', 'In the multiverse called the data world, everything corresponding to the real world is stored. Within it, the data from relics of human culture gained self-awareness, and a secret group of spirits established an alliance: The Country of Rare Treasure.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ruri-iro Princess', 'OVA', 2, 'Completed', '1992-03-21', '1992-05-21', '6', 'High school girl Ruri is dragged into a battle over the fate of the Pulsean Moon when the princess Leila sends assassins to dispense with her. Ruri''s lover, Toru, is wounded protecting her, and Ruri must leave the real world behind and journey to the Pulsean Moon to save him. Based on the manga in Omajinai Comic by Mito Orihara, who also wrote the theme song. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nar Doma', 'TV', 26, 'Completed', '2015-05-17', '2015-11-12', '6', 'The "unorthodox hard surreal gag" comedy centers around the narcissistic (narushi na) Hagito and the masochistic (domazo na) Kei. Together they are "Nar Doma."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kiki to Lala no Habatake! Pegasus', 'OVA', 1, 'Completed', '1994-03-21', NULL, '6', 'Kiki and Lala try to help a lost Pegasus get home. Pegasus keeps getting on Kiki''s nerves with his foolishness and the journey becomes increasingly difficult.', 352, 'https://cdn.myanimelist.net/images/anime/5/70349.jpg');
