INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Juan Siliang 3rd Season', 'ONA', NULL, 'Upcoming', '2026-01-01', NULL, '5', 'This is a story of conspiracy and redemption set on the magnificent and fantastical Island of Siliang. It begins with the protagonist, Jingxuan, investigating the truth behind his parents'' deaths, gradually uncovering the secrets of the island''s past while showcasing the journey of a group of young people striving to grow and break free from their shackles in pursuit of their life goals.
