INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nori P-chan', 'OVA', 1, 'Completed', '1989-12-25', NULL, '5', 'An anime adaptation of a shoujo manga of the same name. The story follow Nori P-chan''s everyday live and the antics she gets in with her friends.', 99, 'https://cdn.myanimelist.net/images/anime/13/79691.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dokachin', 'TV', 26, 'Completed', '1968-10-02', '1969-03-26', '5', 'A tremendous explosion occurs in the middle of a time warp experiment and causes a caveman family to appear in the modern world. Since so many of the sights and sounds are strange to them, they wind up destroying things with their stone axes, thus setting off wild adventures.
