INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sou Xuan Lu Zhi Chen Ling Ji', 'ONA', 6, 'Completed', '2021-07-06', '2021-08-03', '6', 'For almost a millennium, the mainland of Lingzhou was ruled by an emperor and protected by eight princes. However, after the enthronement of the ninth emperor, a revolt ensued.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Urvan', 'ONA', 1, 'Completed', '2021-02-12', NULL, '6', 'An unnamed girl appears in a school. She traverses through a cyberpunk version of the town of Sasebo, collecting lanterns while being pursued by an ominous figure.', 1030, 'https://cdn.myanimelist.net/images/anime/1650/112507.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Minna Atsumare! Falcom Gakuen', 'TV', 13, 'Completed', '2014-01-05', '2014-03-30', '6', 'Characters from various games released by Falcom (e.g. Dragon Slayer, The Legend of Heroes, and Ys series) come together in a school.', 211, 'https://cdn.myanimelist.net/images/anime/10/56549.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tezuka Osamu no Don Dracula', 'TV', 8, 'Completed', '1982-04-05', '1982-04-26', '6', 'After living in Transylvania for several years, "Earl Dracula" (as Osamu Tezuka''s official website calls him in English) has moved to Japan. In the Nerima Ward of Tokyo, he and his daughter, Chocola, and faithful servant Igor have taken up residence in an old-Western style house.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Vampiyan Kids: Pilot', 'Special', 1, 'Completed', '1999-01-01', NULL, '6', 'A young boy ends up at a castle belonging to a vampire and his daughter.', 704, 'https://cdn.myanimelist.net/images/anime/6/8386.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hitotsubu ni Kawaranu Ai wo Komete', 'ONA', 1, 'Completed', '2013-06-01', NULL, '6', 'A special animated movie to commemorate the 100th anniversary of "Morinaga Milk Caramel".', 849, 'https://cdn.myanimelist.net/images/anime/1179/150332.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Play Ball', 'TV', 13, 'Completed', '2005-07-05', '2005-09-27', '6', 'After fracturing a finger in a junior high school game, Takao Taniguchi is unable to play baseball. After entering Sumitani High School, he is constantly watching the baseball club even though he is unable to play. He catches the eye of the captain of the soccer club, and while he still has lingering hopes of joining the baseball club, he decides to join the soccer club. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The Borgman: Last Battle', 'OVA', 1, 'Completed', '1989-09-16', NULL, '6', 'It has been three years since the end of the series. Ryo works for NASA as an engineer on a large rocket project. Anise, fellow Borgman and lover, has been reduced to flipping burgers in a restaurant. So naturally, when she gets a letter offering her a professional job in a big, Japanese, high-tech project, she jumps at the chance. Ryo, however, is as indecisive as ever and so she leaves for Japan without him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ouritsu Uchuugun: Honneamise no Tsubasa Pilot', 'Special', 1, 'Completed', '1985-01-01', NULL, '6', 'Short film/pilot from year 1985 for the Royal Space Force movie that came out two years later.', 321, 'https://cdn.myanimelist.net/images/anime/4/47345.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahoutsukai Reimeiki Mini Anime', 'ONA', 21, 'Completed', '2022-03-19', '2022-04-07', '6', 'Mini anime for Mahoutsukai Reimeiki released on the official Twitter.
