INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Metropolis (2009)', 'Movie', 1, 'Completed', '2009-01-01', NULL, '6', 'A city as a pulsating organism. Repetitive movements are made by drawing on graph papers. Mirai Mizue''s first time experimenting with geometric animation.
