INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ku Pao Ying Xiong', 'ONA', 26, 'Completed', '2017-09-02', '2018-02-17', '6', 'The animation tells the story of Xiao Shuai who has gone into a cool running world by accident and is embroiled in a dispute between parkour colleges.', 108, 'https://cdn.myanimelist.net/images/anime/3/87942.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Crayon Shin-chan x Panpaka Pants: Aeon Cinema Manner Movie Collab', 'ONA', 1, 'Completed', '2017-03-17', NULL, '6', 'A three-way collaboration between Crayon Shin-chan, Panpaka Pants, and the Aeon Cinema movie theater company. This short is promoting good theater etiquette as well as the 25th Crayon Shin-chan film "Shin-chan Shuurai! Uchuujin Shiriri" being released April 15th. The manner movie will be shown in Aeon cinemas nationwide starting March 18th and collaborative goods will be sold at participating Miraiya bookstores (also owned by the Aeon conglomerate).', 802, 'https://cdn.myanimelist.net/images/anime/8/84745.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kagaku Manga Survival', 'Special', 1, 'Completed', '2019-03-28', NULL, '6', 'Short promotional anime for the learning manga of the same title.', 1030, 'https://cdn.myanimelist.net/images/anime/1228/102592.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zunda Horizon', 'Movie', 1, 'Completed', '2017-03-11', NULL, '6', 'Zunko Tohoku can make any mochi into delicious zunda mochi by shooting it with her Zunda Arrow. Along with Kiritan Tohoku, Itako Tohoku, Usagi Chuugoku, Metan Shikoku, and Sora Kyushu, she enjoys eating zunda mochi while being full of happiness.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('PS3 no Tsukai Kata: feat. Peeping Life', 'OVA', 6, 'Completed', '2010-09-26', NULL, '6', 'Collaboration of Peeping Life and PS3. A DVD containing 6 PS3 related Peeping Life episodes was given out at the 2010 Tokyo Game show.', 184, 'https://cdn.myanimelist.net/images/anime/1002/147453.jpg');
