INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lost Utopia', 'Movie', 1, 'Completed', '2007-01-01', NULL, '5', 'The story of Adam and Eve with jazzy music. Short experimental animation without words.', 573, 'https://cdn.myanimelist.net/images/anime/7/51513.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sin in the Rain', 'OVA', 1, 'Completed', '2006-03-24', NULL, '5', 'It is raining in  Tokyo at night. A woman, named Kimura Yu, is caught in the rain. She has had lots of trauma in her life, because her parents were killed, and to make things worse she experiences another tragedy, her reliable councilor, Kanzaki, is killed. But Yu is "saved" by a mysterious detective named Takamizawa Kyosuke.', 582, 'https://cdn.myanimelist.net/images/anime/13/53735.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tesla Note', 'TV', 13, 'Completed', '2021-10-03', '2021-12-26', '5', 'Mission T is a secret operation to save the world from destruction. Trained as a ninja from a young age, Botan Negoro, raised to become the ultimate spy, teams up with another excellent spy, Kuruma. Their aim is to recover the legacy of the genius inventor Nikola Tesla, the "Shards of Tesla." Can the two outwit the agents of other countries who are also pursuing these fragments? A super-original spy thriller begins. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('FLCL: Grunge', 'TV', 3, 'Completed', '2023-09-10', '2023-09-24', '5', 'While the adults have no hope for tomorrow, the youth accept the decline and poverty of the city as an ordinary part of their reality until Haruko throws the city into chaos.
