INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hatachi no Ryouma with Kurofune-kun!', 'ONA', NULL, 'Airing', '2018-08-01', NULL, '5', 'A Shinagawa ward tourism anime. The anime was made in honor of the 150th anniversary of the Meiji Restoration.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sakkai Eightraid', 'ONA', 1, 'Completed', '2019-02-02', NULL, '5', 'The story takes place in a universe where countless parallel universes known exist. There is always a link — called "Prism" — connecting the modern world and these parallel worlds, and sometimes energy and substance comes through. One day, monsters known as "Eight" come from a parallel world and begin attacking. Humanity begins its counterattack using a power called "Skuld," which harnesses the power of tomorrow. The government gathers Skuld users into an army known as "Norn," but the Eight still wreak destruction over the years. Then, a boy named Asuma who can use an ancient weapon is discovered. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nar Doma Manner Movie', 'Movie', 1, 'Completed', '2015-11-01', NULL, '5', 'A short manner movie that aired at 109 Cinemas from November 1 to November 30, 2015 before films.', 457, 'https://cdn.myanimelist.net/images/anime/13/77480.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aware! Meisaku-kun: DVD Hatsubai Kettei!', 'ONA', 11, 'Completed', '2017-05-05', '2020-03-15', '5', 'Unique episodes of Aware! Meisaku-kun where the characters break the 4th wall to promote the DVD releases of their own show. They have new animation and new dialogue to accompany the highlights of the DVD''s release such as bloopers and sticker sheets.', 681, 'https://cdn.myanimelist.net/images/anime/2/85783.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mim Mam Mint', 'TV', 4, 'Completed', '2015-12-24', '2016-03-25', '5', 'Two girls, based on the real-life models Mim and Mam, received a strange creature that is 70% rabbit and 30% bear.', 457, 'https://cdn.myanimelist.net/images/anime/12/77757.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Vicky and Johnny', 'TV', 104, 'Completed', '2007-01-01', NULL, '5', 'The series follows Vicky and Johnny, two exuberant children who become involved in several boy vs. girl matches.', 996, 'https://cdn.myanimelist.net/images/anime/1974/135549.jpg');
