INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kataude', 'Movie', 1, 'Completed', '2019-06-11', NULL, '5', 'A woman lends an admirer her arm for the course of one night for him to find pleasure with it... An eerie erotic short story by Nobel Prize laureat Kawabata Yasunari is turned into minimalist animation of dazzling beauty indebted to Alfons Maria Mucha. A true gem created by two anime giants.
