INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Papan Ga Panda!', 'TV', NULL, 'Airing', '2012-01-01', NULL, '5', 'A series of shorts broadcasted on Kids Station. The star a Panda (with other animals present) as they do quick skits usually revolving around singing, dancing, and exercise.', 1165, 'https://cdn.myanimelist.net/images/anime/6/86918.jpg');
