INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Totemo Mijikai', 'Movie', 1, 'Completed', '2024-04-25', NULL, '5', 'Somewhere between calligraphy, embryology and words from beyond the grave, a convulsive poem wraps itself around the Japanese syllable ‘da’ — a breath that could just as well be the first as the last.
