INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Konpora Kid', 'TV', 26, 'Completed', '1985-06-03', '1985-12-23', '5', 'The time is set in the Mechatronics Era in the future. In this era, schools actually float in the Tokyo sky at around 2000 - 3000 metres. At home, there is freedom in movement as everyone has a flight mechanism within them which allows them to fly. Transportation is made easy as a result.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tantei Shounen Kageman', 'TV', 39, 'Completed', '2001-04-10', '2002-01-16', '5', 'Kageman is a boy who wants to become the best detective in the world. Each of the self-contained episode features a fun guessing game and unriddling of a case. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hula Kappa', 'TV', 78, 'Completed', '2006-04-01', '2006-12-21', '5', 'Some sort of educationnal anime for children. A bit of humoristic.', 633, 'https://cdn.myanimelist.net/images/anime/8/80771.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yanase Takashi Märchen Gekijou', 'OVA', 30, 'Completed', '2008-04-23', '2008-07-25', '5', 'A collection of children''s stories by Yanase Takashi.', 1022, 'https://cdn.myanimelist.net/images/anime/13/46679.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kouchuu Ouja Mushiking: Greatest Champion e no Michi', 'Movie', 1, 'Completed', '2005-12-17', NULL, '5', 'The ultimate Beetle Battle unreels!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pittanko!! Nekozakana (2020)', 'TV', 13, 'Completed', '2020-07-06', '2020-09-28', '5', '', 871, 'https://cdn.myanimelist.net/images/anime/1927/113821.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pink Lady Monogatari: Eikou no Tenshi-tachi', 'TV', 33, 'Completed', '1978-10-24', '1979-06-12', '5', 'Based on the real life-story of Pink Lady, a female pop duo that rose to superstardom in the mid-1970''s.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('RGB Adventure', 'TV', 6, 'Completed', '2006-11-19', '2006-12-24', '5', 'The light – it is the resource of life. There are mysterious monsters and robots that aim at the powers of the light, i.e. R(Red), G(Green), and B(Blue). However, no one notices that… except three children.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yuusei Koukou Tenmon-bu', 'ONA', 20, 'Completed', '2021-03-11', '2021-08-02', '5', 'Web anime for the Yuusei Koukou Tenmonbu mixed media project.', 39, 'https://cdn.myanimelist.net/images/anime/1333/113884.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pro Golfer Saru: Kouga Hikyou! Kage no Ninpou Golfer Sanjou!', 'Movie', 1, 'Completed', '1987-03-14', NULL, '5', '', 802, 'https://cdn.myanimelist.net/images/anime/8/46227.jpg');
