INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nono-chan Theater', 'ONA', 85, 'Completed', '2001-09-03', '2001-12-28', '5', 'Animated shorts focusing on the Yamada family.', 642, 'https://cdn.myanimelist.net/images/anime/4/85747.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ganbare!! Tabuchi-kun!! (ONA)', 'ONA', 10, 'Completed', '2004-05-21', NULL, '5', 'Animated shorts revolving around the titular character Tabuchi-kun.', 642, 'https://cdn.myanimelist.net/images/anime/5/85746.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ore to Issho ni Training', 'OVA', 1, 'Completed', '2014-04-18', NULL, '5', 'An animated training DVD, where your attractive boyfriend teaches you about exercising and eating healthy.', 642, 'https://cdn.myanimelist.net/images/anime/13/85716.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chikasugi Idol Akae-chan', 'TV', 12, 'Completed', '2014-01-07', '2014-04-01', '5', 'Based on the upcoming "Underground Princess" idol role playing game for mobile devices.', 214, 'https://cdn.myanimelist.net/images/anime/2/59173.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Geisters Movie: Inochi no Shou', 'Movie', 1, 'Completed', '2002-08-24', NULL, '5', 'Recap of the second half of the TV series.', 689, 'https://cdn.myanimelist.net/images/anime/9/85625.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Geisters Movie: Hikari no Shou', 'Movie', 1, 'Completed', '2002-08-17', NULL, '5', 'Recap of the first half of the TV series.', 689, 'https://cdn.myanimelist.net/images/anime/4/85624.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou no Yousei Persia: Kaiten Mokuba', 'OVA', 1, 'Completed', '1987-09-25', NULL, '5', 'A recap of the TV series with six and a half minutes of new footage.', 939, 'https://cdn.myanimelist.net/images/anime/8/85623.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yu☆Gi☆Oh! Movie: Chou Yuugou! Toki wo Koeta Kizuna', 'Movie', 1, 'Completed', '2010-01-23', NULL, '7', 'While riding with Jack Atlas and Crow Hogan, Yuusei Fudou''s Stardust Dragon is captured by Paradox, a mysterious Turbo Duelist from the future, during a Turbo Duel and turned into a Sin Monster. With the help of the Crimson Dragon, Yuusei chases after Paradox as he enters a time slip, ending up in the past. During this time, Paradox duels against Jaden Yuki, who is still able to use the powers of Yubel and The Supreme King. However, by this time Paradox had also captured Cyber End Dragon and Rainbow Dragon and overwhelms Jaden. He is saved thanks to Yuusei and the Crimson Dragon. Jaden informs Yuusei of Paradox''s true intentions. By stealing various monsters from across time and turning them dark, he plans to kill Maximillion Pegasus, the creator of Duel Monsters, preventing the game from being created and causing the events of all three series to never happen.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Genius Party Beyond', 'Movie', 5, 'Completed', '2008-10-11', NULL, '7', 'Containing shorts that could not be included in the original, Genius Party Beyond weaves stories that are both deep and insightful: the idea all life is relative in size, the consequences of an oppressive government, and how to deal with your darker desires, among others.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaze no Stigma', 'TV', 24, 'Completed', '2007-04-13', '2007-09-21', '7', 'Kazuma Yagami is a user of "Fuujutsu," the ability to control the wind. He returns to his old home, the noble Kannagi household, after being banished four years ago for his inability to control fire and his subsequent defeat in a duel at the hands of his younger cousin, Ayano Kannagi.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pumpkin Scissors', 'TV', 24, 'Completed', '2006-10-03', '2007-03-18', '7', 'Three years ago, the long war between the Royal Empire and the Republic of Frost came to an end. With both nations a long way from recovery, a passionate young woman named Alice L. Malvin leads the Pumpkin Scissors, a unit of the imperial army specializing in war relief.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wake Up, Girls! Shichinin no Idol', 'Movie', 1, 'Completed', '2014-01-10', NULL, '7', 'In Wake Up, Girls! Green Leaves Entertainment is in the worst situation any Talent Management Agency can be in... they have NO talent! Desperate for an act, President Junko Tange targets the idol singer market and gives her flunky Matsuda his marching orders: get a girl group to manage, even if it means building one from scratch!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yes! Precure 5 GoGo! Movie: Okashi no Kuni no Happy Birthday', 'Movie', 1, 'Completed', '2008-11-08', NULL, '7', 'It''s Nozomi''s birthday, but it is disturbed by Bunbee chasing after a girl from another world, Chocola. When Pretty Cure rescue her, she thanks them by taking them to her country, Dessert Kingdom. In this cockaigne with rivers of juice and candy growing on trees, they feel very comfortable. But then they meet the evil Mushiban and his two subordinates Dry and Bitter. They want to take over the kingdom and change Pretty Cure into sweets. In order to save not only Nozomi''s Birthday but also the whole Dessert Kingdom, Pretty Cure have to fight their way against Dry and Bitter and also against their own friend: Coco, who is being brainwashed by Mushiban.', 1030, 'https://cdn.myanimelist.net/images/anime/1889/142444.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ookami-san to Shichinin no Nakama-tachi', 'TV', 12, 'Completed', '2010-07-01', '2010-09-16', '7', 'Tomboy Ryouko Ookami is a fierce boxer and the assigned bruiser of her club. Of course, no normal high school club needs a bruiser, but the Otogi Bank operates more akin to an actual bank. Here, the students can ask for favors from the club as long as they promise to return the favor in the future. Sixteen-year-old Ryoushi Morino is a shy boy, a far cry from the Otogi Bank members. To his biggest surprise, after unsuccessfully confessing to Ryouko, he inadvertently finds himself joining the club! 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece: Umi no Heso no Daibouken-hen', 'Special', 1, 'Completed', '2000-12-20', NULL, '7', 'The Straw Hats encounter a city in the middle of a whirlpool, called the Ocean''s Navel, that is being destroyed by giant monsters. These monsters supposedly protect a treasure capable of granting wishes, but in the process of defeating these guardians, the crew ends up releasing another evil.  (aired after Episode 53)
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ushio to Tora', 'OVA', 10, 'Completed', '1992-09-11', '1993-08-01', '7', 'Ushio thinks his father''s tale of an ancient ancestor impaling a demon on a temple altar stone with the legendary Beast Spear is nuts, but when he finds the monster in his own basement, Ushio has to take another look at the family legend! Fortunately, Ushio knows it''s best to let sleeping dogs lie and leave captured demons where they are. Unfortunately, the release of the monster''s evil energies begins to beckon other demons to Ushio''s hometown! To save his friends and family from the invading spirits, Ushio is forced to release Tora from his captivity. But will the cure prove to be worse than the curse? Will Ushio end his life a Tora-snack? Or will the Beast Spear keep Tora in line long enough to save the city?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cyborg Kuro-chan', 'TV', 66, 'Completed', '1999-10-02', '2001-01-06', '7', 'Kuro is just an ordinary cat who only wants to protect his owners who are an old couple that can''t fend for themselves. One day while on a date with his girlfriend Pooly who is a dog, he is kidnapped by an evil scientist and turned into a robot. Kuro somehow removes the chip that controlled him and notices that people get scared with his new robotic appearance and that he can now talk like a human. He decides to disguise himself with the skin of a stuffed toy and to continue living as a pet.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Miracle☆Girls', 'TV', 51, 'Completed', '1993-01-08', '1993-12-24', '7', 'Mikage and Tomomi Matsunaga are Miracle Girls: they have a telepathic link with each other and can teleport when they link their little fingers. Tomomi is a sports star and has a boyfriend called Noda. Mikage is the smartest student in the school and is in love with her sempai. He moved to London to study but they still kept in touch, that is until a selfish princess called Marie decides that he should come with her back to Diammas. Back in Japan the twins are having various problems of their own. But they soon realise that there is a link between Marie, an ancient legend, and a girl they know called Emma.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aku no Hana', 'TV', 13, 'Completed', '2013-04-05', '2013-06-30', '7', 'Takao Kasuga, a high school student fascinated by poetry, reveres Charles Baudelaire and even decorates his room with the poet''s portrait. On a normal day, Takao forgets his copy of The Flowers of Evil in the classroom. When returning to retrieve it, he steals the sports garments of Nanako Saeki—a model student who Takao calls his muse and a femme fatale.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dash! Kappei', 'TV', 65, 'Completed', '1981-10-04', '1982-12-26', '7', 'Kappei is a dramatically short guy but he is a master in every sport. He lives as a guest in sweet Akane''s house, and he''s in love with her, but there''s a strange rival, her dog Salomone (Italian name) who plans evil traps to encumber Kappei. But the dog has also another function: he explains all sport rules when a new sport is depicted. Kappei is fond of white female underwear, always trying to lift girl''s skirts up.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Galaxy Angel Z', 'TV', 9, 'Completed', '2002-02-03', '2002-03-31', '7', 'In the far future, the human race advanced to space, and prospered. However, Jikushin ( earthquake of time and space ) which occurred suddenly intercepted all networks, and all the civilizations were reset. However, the human race begins to revive, and enters the prosperity age of The Second by the Transvaal imperial country which rises at the center of the galactic system. The science and technology before the civilization was reset, that is, "Lost Technology" was considered to be god`s task. And, it came to be worshiped by the priest who was called "Tsuki no miko".
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Black Jack: Futari no Kuroi Isha', 'Movie', 1, 'Completed', '2005-12-17', NULL, '7', 'The mega-corporate Daedalus Group is under attack by a small group of activists known as the Ghost of Icarus. While taking care of some of the victims of the bombing, Black Jack encounters Dr. Kiriko, also known as Death Incarnate, who just like him, asks his patients huge sums of money but instead of saving them, he offers them a painless death. When the activist group requests both doctors’ collaboration, Black Jack finds himself caught in a spiral of life, death and treason while trying to save his patients'' lives and avoid the breaking of a biological war that could destroy humanity.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Boogiepop wa Warawanai', 'TV', 12, 'Completed', '2000-01-05', '2000-03-22', '7', 'Boogiepop, a rumored shinigami, is said to lurk where they cannot be seen. Five years ago, a string of gruesome murders shocked the populace, and students attributed some of those killings to the aforementioned death god. When mysterious happenings once again affect the lives of those attending Hijiridani High School and Shinyo Academy, whispers of the enigmatic Boogiepop are resurrected. The stories being told may contain partial truths, or perhaps the world as humans know it is more dangerous than previously believed.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kotoura-san', 'TV', 12, 'Completed', '2013-01-11', '2013-03-29', '7', 'Since childhood, Haruka Kotoura''s classmates have seen her as a creepy and monstrous person. This is due to her ability to read other people''s minds—the same ability that drove her parents away, leaving her alone with her grandfather. As a result, she has grown accustomed to the bitter treatment by the people around her, becoming completely cold and unsociable to others.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Shirayuki-hime Densetsu Prétear', 'TV', 13, 'Completed', '2001-04-04', '2001-06-27', '7', 'Due to her father''s remarriage, robust 16-year-old Himeno Awayuki moves into a large mansion with a beautiful garden—the quintessential dream house for any girl her age. However, much to Himeno''s disappointment, her new stepfamily doesn''t really seem to like her, as her stepmother often occupies herself with her father, her younger stepsister Mawata ignores her, and her other stepsister—the equally aged Mayune—tries to prank her at every opportunity.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Vandread', 'TV', 13, 'Completed', '2000-10-03', '2000-12-19', '7', 'In Vandread, men are from Mars and women are from Venus! Well, not quite. Technology has allowed mankind to colonize the entire Milky Way galaxy, and in one star system, the men and women live on two different planets, Taraak and Mejere. A bitter and very literal gender war rages, to the point where they don''t even see each other as the sames species anymore!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ultra Maniac', 'TV', 26, 'Completed', '2003-05-20', '2003-11-11', '7', 'Fantasies and miracles never interested Ayu Tateishi, a popular second-year student at her middle school. She was content with preserving her image of being cool, calm, and collected—all to catch the eye of her crush, Tetsushi Kaji. Ayu''s carefree youthful days are interrupted by the appearance of Nina Sakura, a new transfer student who turns out to be a witch. As the only person who knows about Nina''s ability to cast spells using a mini-computer, Ayu is forced to help Nina with her mission to find the five Holy Stones, qualifying her to marry the prince of the Magic Kingdom.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kai Byoui Ramune', 'TV', 12, 'Completed', '2021-01-10', '2021-03-28', '7', 'At first glance, Ramune may not seem like a professional doctor—he is crass, rude, and often acts halfheartedly. But his true brilliance shines through once his patients pay him a visit: he is able to diagnose and treat all sorts of strange, mysterious diseases that come his way. From a young student whose fingers have turned into chili peppers to a child whose tears are made of condiments, Ramune is able to tap into a kind of innate, otherworldly sensibility that enables him to decipher the roots of their source. But finding the proper cure for these illnesses comes at a valuable price, and money certainly cannot be used to pay it. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimi ni Todoke: Kataomoi', 'Special', 1, 'Completed', '2011-01-05', NULL, '7', 'The Kimi ni Todoke story so far, from Kurumi''s point of view.', 704, 'https://cdn.myanimelist.net/images/anime/1598/121757.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tantei Opera Milky Holmes Movie: Gyakushuu no Milky Holmes', 'Movie', 1, 'Completed', '2016-02-27', NULL, '7', 'The four members of Milky Holmes are going on a study tour. While soaking in the hot springs among snow monkeys, alarms interrupt the relaxing environment! It was the work of the Thief Empire. A fierce battle between Milky Holmes and the Thief Empire begins, with both sides using their Toys (special powers). Furthermore, with the arrival of the Genius 4, a three-way fight occurs! In the midst of battle, a violent lightning strikes from the sky. Struck by the lightning, the four Milky Holmes girls lose their abilities.', 436, 'https://cdn.myanimelist.net/images/anime/7/77175.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Phi Brain: Kami no Puzzle', 'TV', 25, 'Completed', '2011-10-02', '2012-04-01', '7', 'Kaito Daimon would be a completely average high school student except for one thing: he''s a "demon" at solving puzzles. Kaito is so brilliant, in fact, that when he''s asked to take some ''special'' tests of his unique ability, he immediately suspects that the test itself is a test. Kaito suddenly finds himself caught up in a lethal Philosopher''s Puzzle made by the sinister group POG, a murderous maze of trap upon trap, where failing to solve the secret correctly will result in death! Fortunately, Kaito''s skills prove up to the first test, both for himself and his childhood friend Nanoha, who is also caught up in the deadly scheme. But now that he has been designated as a Solver, he is pulled into a new life where he must travel the world with other Solvers, attempting to solve the latest deadly riddles left by POG. There''s a new conundrum around every corner and each deception could lead to death, but once a riddle has been posed, you can count on Kaito to unfold, unravel and unlock it!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hetalia Axis Powers Fan Disc', 'OVA', 1, 'Completed', '2010-05-25', NULL, '7', 'The Fan Disc includes the unaired episode "Ore-sama Nikki Sono 2"', 879, 'https://cdn.myanimelist.net/images/anime/7/27300.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Karakuri no Kimi', 'OVA', 1, 'Completed', '2000-03-24', NULL, '6', 'In an obscure corner of feudal Japan, a clumsy young girl carrying a massive box searches for a legendary ninja. That girl is Rangiku Ayawatari—the sole survivor of the Ayuwatari clan—and she seeks revenge against Lord Sadayoshi Karimata, the man who slaughtered her family and stole the secrets of her father''s prized puppet collection. However, in place of the legendary ninja, Rangiku finds Yasaburou Manajiri, a vagabond who is being pursued by "deathless ninjas"—strange, fearless warriors who can survive seemingly fatal blows. Upon discovering that they share a common enemy, the pair team up to defeat the cruel lord and rid the world of strange puppets that conceal a horrible secret.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yami Shibai 2', 'TV', 13, 'Completed', '2014-07-07', '2014-09-29', '6', 'For the second time, the masked storyteller returns to tell children tales and legends of horror and woe, such as the tale of a ventriloquist''s dummy, a locker that grants wishes, a capsule toy machine that returns lost possessions, and a strange food called Ominie-san.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Feng Qi Luoyang: Shen Ji Shaonian', 'ONA', 16, 'Completed', '2021-12-17', '2022-03-18', '6', 'During the Wu Zhou period, Wu Zetian''s imperial examination system severely hindered the interests of the traditional aristocrats. They were prepared to prevent Wu Zetian from ascending the throne. The protagonist Pei Kun came to the divine city Luoyang and was involved in the conspiracy of Chun Qiudao. Through a series of accidents, he tears apart this huge conspiracy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('IGPX: Immortal Grand Prix', 'TV', 5, 'Completed', '2003-09-15', '2003-09-19', '6', 'In the year 2035, Team Suzaku and Team Sledge Mamma are preparing to meet in the final round of the 12th Immortal Grand-1 Prix (IG1 or IGPX). Takeshi leads Team Suzaku, which is made up of a group of young amateur pilots who must make the most of their limited funds and weaponry in order to prepare for the competition designed for professionals.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Merc Storia: Mukiryoku no Shounen to Bin no Naka no Shoujo', 'TV', 12, 'Completed', '2018-10-11', '2018-12-27', '6', 'Merc Storia takes places in a world where humans and monsters coexist. The protagonist, Yuu, is a healer apprentice and possesses the ability to tame monsters. In a quest to regain the memories of Merc, a girl confined in a bottle, the pair embarks on a journey.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('.hack//Intermezzo', 'Special', 1, 'Completed', '2003-03-28', NULL, '6', 'A virtual multiplayer online role-playing game exists known as "The World." In "The World," there is an event held in the Dungeon of Nankoflank that Mimiru, a character in the game, undertakes with Bear, another character in the game. Mimiru confesses to Bear that she is not doing the event for the treasures or experiences, but for the memories and experiences of when she first started playing. The two later meet a certain character named Mimika, and together, the three proceed through quests and events as Mimiru learns the meaning of the game.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Onmyou Kaiten Re:Birth', 'TV', 12, 'Completed', '2025-07-03', '2025-09-18', '6', 'Teenage delinquent Takeru Narihira has been having a recurring dream where he is chased by monsters, only for a mysterious girl to always rescue him. Having fallen in love with her, he promises her on their 1,999th meeting that he will be the one to save her the next time. But a motorcycle accident sends Takeru to Denji Heian-kyo—an alternate version of Japan''s ancient capital with futuristic technology and the home of the girl from his dreams, Tsukiyima, who does not recognize him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Itsuka no Watashi Yori', 'Special', 1, 'Completed', '2025-01-17', NULL, '6', 'A short directed by loundraw. Made as a collaboration between Z-Kai Group, loundraw, and FLAT STUDIO.', 290, 'https://cdn.myanimelist.net/images/anime/1357/147584.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wonderful Precure! Movie: Dokidoki Game no Sekai de Daibouken!', 'Movie', 1, 'Completed', '2024-09-13', NULL, '6', 'Komugi, Iroha, Yuki, Mayu, Daifuku, and Satoru have gathered to play the super popular game "Doki Doki♡TanuKingdom"! Everyone starts the game happily! Or so they thought...but it seems they''ve been sucked into a world of the game with a suspicious tanuki...and now they''re in even more trouble! Komugi has been separated from Iroha and the others...!?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Snack Basue', 'TV', 13, 'Completed', '2024-01-13', '2024-04-05', '6', 'Located five stations away from Hokkaido''s largest downtown area Susukino. A fun shop called "Snack Busue" can be found run by mama Basue and mama Akemi. Filled with the laughter of the girls and their unusual regulars, you''ll be smiling along with them before you know it. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bucchigiri?!', 'TV', 12, 'Completed', '2024-01-13', '2024-04-06', '6', 'Minato Kai and Siguma Squad, two rival gangs at Ichizu High School, are embroiled in a bitter power struggle. As a transfer student, Arajin Tomoshibi has no interest in getting involved; instead, his priority is finding a girlfriend. Fortunately for him, he is placed next to Mahoro Jin, the prettiest girl in the class who also seems to like him. However, she has an overprotective older brother, Marito—none other than the combative leader of Siguma Squad. Moreover, Arajin''s reunion with his childhood friend, Matakara Asamine, spells trouble since Matakara is a member of Minato Kai.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Great Teacher Onizuka Recaps', 'Special', 2, 'Completed', '2000-09-03', '2000-09-24', '6', 'Recaps of the Great Teacher Onizuka aired on Fuji TV.', 939, 'https://cdn.myanimelist.net/images/anime/1785/131859.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jidao Long Shen', 'ONA', 40, 'Completed', '2022-07-02', '2022-11-12', '6', 'Legend has it that the Dragon God is sitting in the realm of the gods, and if he is the inheritor of the gods, he will become the new ruler of China. The various sects and gangs are gradually fighting over the inheritance of the Dragon God. The protagonist, Chu Qianye, was regarded as the son of a sinner because of his father''s loss of the treasure of the sect. A subtle connection was made.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tonari no Kaibutsu-kun PV', 'Special', 1, 'Completed', '2012-09-03', NULL, '6', 'PV for Tonari no Kaibutsu-kun with original animation. Was later included on the DVD release.', 143, 'https://cdn.myanimelist.net/images/anime/1203/121682.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon Movie 15: Kyurem vs. Seikenshi', 'Movie', 1, 'Completed', '2012-07-14', NULL, '6', 'Mythical Pokémon Keldeo wishes to join the Swords of Justice, a group of Pokémon traveling around the world, helping out those in need. To do so he must first harness the power of his horn and learn the move Sacred Sword, and he decides to challenge Kyurem, a Legendary Dragon residing in an abandoned mine located within an icy crater. Confident as he is at first, it soon occurs to Keldeo that he is not yet ready for the fight.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Puzzle & Dragons Cross', 'TV', 89, 'Completed', '2016-07-04', '2018-03-26', '6', 'Dorogoza Island is rich in "Drop Energy" that players can use on friendly monsters. Once strong enough, they can face enemies in puzzle wars. Winners reap rewards, but what happens to the losers? Only the brave can take on these monstrous challenges!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Morita-san wa Mukuchi.', 'TV', 13, 'Completed', '2011-07-06', '2011-09-28', '6', 'Morita Mayu, a high school girl. She is extremely reticent and her silence and habit of looking at people''s eyes straightly sometimes cause misunderstanding. The reason behind it is not because she doesn’t like to talk nor because she has nothing to say. The reason she rarely speaks is due to the fact she thinks too much before speaking, thus losing the timing to speak altogether. But she lives a happy school life with her classmates.', 785, 'https://cdn.myanimelist.net/images/anime/13/30166.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hi☆sCoool! SeHa Girls', 'TV', 13, 'Completed', '2014-10-08', '2014-12-24', '6', 'The story of the anime will revolve around Dreamcast, Sega Saturn, and Mega Drive, who have just enrolled in SeHaGaga Academy at Tokyo''s Haneda Ōtorii station. They are given an assignment needed to graduate by a suspicious teacher, and to clear this assignment, the girls need to enter the world of Sega games. The girls must try their best to graduate without incident.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shoujo Shuumatsu Jugyou', 'ONA', 12, 'Completed', '2017-10-06', '2017-12-22', '6', 'Super deformed parody shorts of Shoujo Shuumatsu Ryokou streamed on Kadokawa''s official YouTube channel. They follow Chito and Yuuri in a classroom setting exploring what "school" might have been for people when civilization was still around.', 945, 'https://cdn.myanimelist.net/images/anime/10/88044.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cyborg 009: Chou Ginga Densetsu', 'Movie', 1, 'Completed', '1980-12-20', NULL, '6', 'The cyborgs are no longer on duty, they live normal lives until a mysterious space ship lands on earth. The only survivor on the ship warns about an evil conqueror called Zoa that wants to conquer the universe, which means the cyborgs are back in action...
(Source: ANN)', 1030, 'https://cdn.myanimelist.net/images/anime/3/17466.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Robot Girls Z Specials', 'Special', 3, 'Completed', '2014-06-13', '2014-08-08', '6', 'Bonus episodes 3.5, 6.5, and 9.5 included with the Blu-ray/DVD releases.', 1030, 'https://cdn.myanimelist.net/images/anime/8/63697.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam UC: One of Seventy Two', 'Special', 1, 'Completed', '2013-08-03', NULL, '6', 'U.C. 0095.12.03 The Neo Zeon remnants known as the Sleeves conduct a performance test on a certain new type of mobile suit in a debris sector. Having gotten wind of this intel, two warships head for the debris sector. One ship is a Earth Federation Forces warship. The other ship is an Anaheim Electronics testing ship. On board the Federation Forces battleship, a newly constructed Unicorn Gundam Unit 3 awaited its time to sortie…
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hikari no Ou', 'TV', 10, 'Completed', '2023-01-14', '2023-03-18', '6', 'Human civilization no longer revolves around fire, but is instead now driven by fear of it. Repeated wars have changed human biology, and people now spontaneously combust when they get close to natural flame. However, a new source of energy prevents society from complete collapse: a stone-shaped material used to produce light and steam lies within the bodies of monsters that infest numerous forests. Those tasked with collecting this precious resource are called fire hunters.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shiroi Kiba White Fang Monogatari', 'Special', 1, 'Completed', '1982-05-05', NULL, '6', 'White Fang is born on the planes of Alaska to a wolf father and a half-wolf, half-dog mother. One day he and his mother run into an Alaskan inuit boy Mit-sah, who has long dreamed of a dog of his own, and by a marvellous twist of fate, the wolves are taken in by him and his father. But life in Alaska is harsh for humans and wolves alike, and as winter comes, hardships lie in waiting for White Fang and Mit-sah. Facing the extreme coldness of their habitat and that of humans'' greedy hearts, the two journey towards what they hope to be a happier environment.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Argento Soma: Hitori to Hitori', 'Special', 1, 'Completed', '2002-03-01', NULL, '6', 'The pilot Sue Harris goes to a mission on a frozen country, there she suffers an accident on the mountains and her life is in severe danger. Trying to survive on the harsh enviroment, she encounters an alien and engages in combat with it. The two beings will use all means possible to escape of that dead trap alive.', 974, 'https://cdn.myanimelist.net/images/anime/6/3194.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon XY: New Year Special', 'Special', 1, 'Completed', '2013-12-31', NULL, '6', 'Recap episode.', 621, 'https://cdn.myanimelist.net/images/anime/13/57141.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Heart Cocktail Again', 'OVA', 1, 'Completed', '2003-10-22', NULL, '6', 'An OVA produced to celebrate the 20th anniversary of Watase Seizou''s Heart Cocktail manga.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kenji no Trunk', 'Movie', 1, 'Completed', '1996-08-24', NULL, '6', 'An omnibus movie consisting of three stories by Miyazawa Kenji.', 1053, 'https://cdn.myanimelist.net/images/anime/2/55711.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Muu no Hakugei', 'TV', 26, 'Completed', '1980-04-04', '1980-09-26', '6', 'In ancient times, the continents of Atlantis and Mu fought a war, and Atlantis lost. After losing the war, Atlantis transformed itself into a small planet and timeslipped to the present-day to try to take over the world again. But five warriors from Mu assemble on Easter Island, and together with giant cyborg white whale that houses the brain of the ancient queen of Mu, fight Atlantis off at various famous ruins around the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sengoku Basara Movie: 4-koma Gekijou - Another Last Party', 'Special', 5, 'Completed', '2011-12-07', NULL, '6', 'Random side stories of Sengoku Basara characters in chibi form.', 704, 'https://cdn.myanimelist.net/images/anime/4/49863.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mori no Youki na Kobito-tachi: Belfy to Lillibit', 'TV', 26, 'Completed', '1980-01-07', '1980-06-30', '6', 'This family-friendly series features a community of tiny forest pixies living in a quaint, old fashioned village. Kind-hearted Belfy, adventurous Lillibit, mischievous Napoleon and tiny Chuchuna have adventures with their friends and help out those around them. With the guidance of wise village elder Ronji, competent (but not always sober) Doctor Dokkorin, authoritative Mayor Maymond and Lillibit''s hardworking parents Rock and Marla, the children learn lessons about kindness, friendship, courage, hard work, perseverance, following your dreams, standing up for what''s right and rising up to face life''s unexpected challenges.', 1009, 'https://cdn.myanimelist.net/images/anime/10/73405.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Interlude', 'OVA', 3, 'Completed', '2004-03-25', '2004-08-27', '6', 'The unnamed main character has been having strange dreams, seeing strange things, and meeting strange people. He investigates these events and finds a strange girl named Aya. With her help, he discovers that his world may not in fact be real and many of the people he thinks he knows may not exist anymore.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fate/Grand Order: Moonlight/Lostroom', 'Special', 1, 'Completed', '2017-12-31', NULL, '6', 'Short centering on a "Lost Room" where you can find what was lost—or those who lost. This room, which belongs to no one, lies forgotten in a corner of Chaldea.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The SoulTaker: Tamashii-gari', 'TV', 13, 'Completed', '2001-04-04', '2001-07-04', '6', 'Kyousuke Date comes home one night and finds his mother dying in a pool of her own blood. In her final moments, she stabs him in the chest. After a swift recovery, Kyousuke searches for answers regarding his mother''s motives, but finds more than he bargained for when he is attacked by two rival organizations: the Hospital and the Kirihara Group.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rokushin Gattai GodMars', 'TV', 64, 'Completed', '1981-10-02', '1982-12-24', '6', 'In the year 1999, humanity begins to advance beyond the solar system. The planet Gishin, led by the Emperor Zule, which aims to conquer the galaxy, runs into conflict with Earth. He targets Earth for elimination and to do this, he sends a baby called Mars to live among humanity. Accompanying the baby is a giant robot named Gaia, which utilizes a new power source strong enough to destroy an entire planet. As planned, Mars is expected to grow up, where he will activate the bomb within Gaia to fulfill the mission of destroying the Earth. However, when Mars arrives on Earth his is adopted into a Japanese family and given the name Takeru. Seventeen years later, Takeru would grow up with a love for humanity and refuses to detonate the bomb as ordered by Zule. However, if Takeru was to die, the bomb within Gaia would explode destroying the earth.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chiisana Kyojin Microman', 'TV', 52, 'Completed', '1999-01-04', '1999-12-27', '6', '3 kids meet 5 micro-sized superheroes from another world who enlist in their aid in fighting off alien invaders.', 939, 'https://cdn.myanimelist.net/images/anime/1058/110297.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kamen Rider SD Kaiki?! Kumo Otoko', 'OVA', 1, 'Completed', '1993-01-23', NULL, '6', 'This OVA is a parody of the popular japanese Tokusatsu (Power Ranger/Ultraman genre) franchise Kamen Rider. It features all of the Kamen Riders from The Original to Shin (Shin only makes a cameo). See More Info for a more detailed synopsis.', 1030, 'https://cdn.myanimelist.net/images/anime/9/51043.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('B-Legend! Battle B-Daman', 'TV', 52, 'Completed', '2004-01-05', '2004-12-27', '6', 'Upon the creation of marble launching machines known as B-Daman, people started to participate in the competitive sport B-DaBattles. However, B-Daman contain hidden powers which enhance marble shooting that can be misused for combative purposes.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chou Kuse ni Narisou', 'TV', 39, 'Completed', '1994-04-05', '1995-01-03', '6', 'Shiratori Nagisa is a pink haired singing idol, continually badgered by her father to find new disciples for the family dojo. In an attempt to gain free-time as a normal kid, she cuts her hair and cross-dresses as a high-school boy. "Ootori Nagisa" enrolls in a run-down school, falling in love with a rival school''s gang leader, Nosaka Akira. She soon finds out Nosaka-kun is a fan of Nagisa - The Idol. Keeping up the charade, they manage to sneak time together. Rivals for Nagisa''s affection, BOTH their dojo-running fathers, as well as martial artist animals and an up-in-coming Idol conspire to make thier lives a complicated as possible.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yume de Aetara (TV)', 'TV', 16, 'Completed', '1998-11-30', '1998-12-24', '6', 'Fuguno Matsuo has never had a girlfriend all his 24 years in life and what makes things worse is that a fortune teller predicted that he never will. However, when he laid his eye on Nagisa-sensei he fell in-love right away and began earnestly wooing her. Along comes Hamaoka, a co-worker who is smitten with Fuguno, and a love-triangle ensues.', 436, 'https://cdn.myanimelist.net/images/anime/1949/127321.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yume de Aetara', 'OVA', 3, 'Completed', '1998-04-21', '1998-12-19', '6', 'Yume de Aetara is a story about one guy Fuguno Masuo (a complete loser when it comes to relationship with women) and two girls: Shiozaki Nagisa and Hamaoka Miho. Since the story is pretty simple (and hilariously funny), further explanation will spoil everything (take the hint: watch it yourself!)
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jantama Pong☆ Episode 0', 'Special', 1, 'Completed', '2022-04-01', NULL, '6', 'Episode 0 of Jantama Pong☆ that aired as an April Fool''s joke.', 782, 'https://cdn.myanimelist.net/images/anime/1385/122259.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bernard-jou Iwaku.', 'TV', 12, 'Completed', '2016-10-07', '2016-12-23', '6', '​Sawako Machida—or "Miss Bernard," as she prefers to be called—can frequently be found in the school library with a book in hand. Whether or not she has read it, however, is another matter entirely. In her own words, Sawako finds it too much work to actually read, and would rather just make others believe she spends a lot of time reading. But in the same library where she constantly hangs out, there are other students who love books and are quite upset with her disdainful approach to reading their favorite titles.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kemeko Deluxe!: Izumi-chan, Fukenkou yo! (Kari)', 'Special', 1, 'Completed', '2008-12-26', NULL, '6', 'Short special bundled with Blu-ray/DVD volume 1.', 357, 'https://cdn.myanimelist.net/images/anime/9/78037.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nurse Witch Komugi-chan R', 'TV', 12, 'Completed', '2016-01-10', '2016-03-27', '6', 'The new "slapstick" story will depict Komugi-chan and her rivals as they juggle their daily lives as students, idols, and magical girls "with laughter and tears."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mo Ri Shu Guang', 'ONA', 20, 'Completed', '2018-05-20', '2018-09-23', '6', 'In the year of 2013, the tide of zombies outbreak exploded in everyone''s homeland, humanity launches a large-scale battle in the endless nights awaiting for the arrival of the dawn.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shounen Ashibe: Go! Go! Goma-chan 2', 'TV', 32, 'Completed', '2017-04-04', '2018-02-13', '6', 'Second season of Shounen Ashibe: Go! Go! Goma-chan.', 146, 'https://cdn.myanimelist.net/images/anime/6/89580.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kabushikigaisha G-anime Saiyou Concept Movie', 'ONA', 1, 'Completed', '2017-04-19', NULL, '6', 'Promotional anime for the studio G-angle.', 311, 'https://cdn.myanimelist.net/images/anime/1388/102398.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Obsolete', 'ONA', 12, 'Completed', '2019-12-03', '2020-12-01', '6', 'In 2014, aliens revealed themselves to request trade with humanity. In exchange for limestone, they would provide a consciousness-controlled general-use robot known as an "Exoframe." Cheaper than an aircraft, tank, or firearm, and easy enough for anyone to operate, the "Exoframe" spreads change throughout the world in the blink of an eye... 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Obake no... Holly', 'TV', 200, 'Completed', '1991-01-28', '1993-04-12', '6', 'Holly the Ghost is about Holly (Chocola) who wants to be a "holly ghost". "Holly ghost" is a group of "monsters" who spread fear. Their leader is a witch called Majoline. Together with his 4 new friends (Candy, Toreppaa, etc) he learns to be a real "holly ghost".', 908, 'https://cdn.myanimelist.net/images/anime/6/24954.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maze☆Bakunetsu Jikuu: Tenpen Kyoui no Giant', 'Movie', 1, 'Completed', '1998-04-25', NULL, '6', 'Long time ago, there was peace until the giants decide to wake up after years and years of slumber.The three priestesses sisters who were guarding their shrine had to retreat to seek help and who better to ask Maze for help. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gegege no Kitarou (1985 Movie)', 'Movie', 1, 'Completed', '1985-12-21', NULL, '6', 'Movie based on the 1985 TV anime with an original plot.', 1030, 'https://cdn.myanimelist.net/images/anime/5/21017.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sore Ike! Anpanman: Hashire! Wakuwaku Anpanman Grand Prix', 'Movie', 1, 'Completed', '2010-07-10', NULL, '6', 'The Anpanman Grand Prix is a land, air and sea race around Anpanman World using specially built cars. A grumpy young girl from Flower Land called Maggie causes an accident that wrecks Creampanda’s race car. After helping him fix it, she enters the race as his partner.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Usaru-san', 'Special', 4, 'Completed', '2009-10-03', '2009-10-10', '6', 'The Media Factory mascot character franchise revolves around a male rabbit that transforms into Usaru-san by wearing a monkey costume and eating bananas. The title “Usaru-san” is a portmanteau of “usagi” (rabbit) and “saru” (monkey).
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hello Kitty: Ringo no Mori no Mystery', 'TV', 13, 'Completed', '2007-01-02', '2007-03-27', '6', 'Mysterious incidents are occurring in the Apple Forrest. Precious items disappearing, others getting lost, and the prince is missing. It''s up to Kitty and Mimmy to solve the cases by becoming detectives!', 90, 'https://cdn.myanimelist.net/images/anime/2/58655.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chotto dake Ai ga Omoi Dark Elf ga Isekai kara Oikaketekita Mini Anime Gekijou', 'TV', 12, 'Completed', '2025-04-07', '2025-06-23', '6', 'A weekly mini anime shown with each episode of Chotto dake Ai ga Omoi Dark Elf ga Isekai kara Oikaketekita exclusively on the AT-X broadcast of the TV anime.', 301, 'https://cdn.myanimelist.net/images/anime/1707/149093.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Inu to Shounen', 'ONA', 1, 'Completed', '2023-01-31', NULL, '6', 'An abandoned robot dog is found and befriended by a young boy. The robot dog is always by the boy''s side as he grows up. But when the boy comes of age, war threatens to tear the two of them apart.', 1105, 'https://cdn.myanimelist.net/images/anime/1766/152142.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mini Toji: Kanami-Mihono no "Toji Miko Taidou-hen" 205-byou de Shoukai Tokuban!', 'Special', 1, 'Completed', '2019-01-06', NULL, '6', 'Episode 0 of Mini Toji. Kanami and Mihono are self-aware that they are in an anime and introduce/recap the Toji no Miko story so that viewers can enjoy Mini Toji the following week even if they haven''t watched the original.', 708, 'https://cdn.myanimelist.net/images/anime/1635/101220.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mirai Koushi Harima SACLA NEX RAY', 'Special', 1, 'Completed', '2017-10-12', NULL, '6', '', 461, 'https://cdn.myanimelist.net/images/anime/1617/98375.jpg');
