INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('A-Girl', 'OVA', 1, 'Completed', '1993-09-24', NULL, '6', 'High-school student Mariko and her elder sister Mayu are forced out of their apartment by a fire and move in with their landlord. Mariko meets the landlord''s handsome son, Natsume, who is also a model. They fall in love but break up when Mariko discovers that Natsume is seeing other girls. Eventually, they are reunited, and the end credits roll.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Code Geass: Hangyaku no Lelouch - Kiseki no Birthday Omake Flash', 'Special', 1, 'Completed', '2010-04-23', NULL, '6', 'From the Code Geass: Lelouch of the Rebellion - Kiseki no Birthday DVD/Blu-ray. It is different from the 9 Omake Flash specials included in the Code Geass R2 DVD/Blu-ray.', 974, 'https://cdn.myanimelist.net/images/anime/4/71045.jpg');
