INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Alexandros no Ketsudan', 'OVA', 1, 'Completed', '2003-06-01', NULL, '6', 'King Alexander of Macedonia and his troops are at war with the armies of Persia. When he suddenly falls ill, Alexander is faced with a decision: to trust his life-long Persian friend Philip and accept his help or treat him as an enemy because he is Persian.', 1030, 'https://cdn.myanimelist.net/images/anime/1946/112681.jpg');
