INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Azur Lane Valentine Special Mission', 'ONA', 1, 'Completed', '2023-02-13', NULL, '6', 'Commander, Essex and Enterprise have prepared some chocolate for you~ Have a bite of chocolate, it melts softly like a tender kiss~ Happy Valentine''s Day!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('He Wei Dao x Guan Yu Wo Zhuan Sheng Bian Cheng Shi Lai Mu Zhe Dang Shi', 'Special', 1, 'Completed', '2022-11-01', NULL, '6', 'A commercial for a Chinese noodle brand', 12, 'https://cdn.myanimelist.net/images/anime/1627/132215.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Circlet Princess', 'TV', 12, 'Completed', '2019-01-08', '2019-03-26', '6', 'Virtual Reality and the arrival of Circlet Technology has changed people''s lives. A new competitive electronic sport called Circlet Bout emerges, and schools duel to determine the strongest Circlet Bout Club and player. One day, Yuuka Sasaki gets mistaken for a challenger and battles against Chikage Fujimura, the best player in Japan, tying the intense fight despite her inexperience. These events lead to her passion for the sport, deciding to become a Circlet Bout player. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sin: Nanatsu no Taizai Zange-roku', 'ONA', 12, 'Completed', '2017-04-14', '2017-07-31', '6', 'Short anime series of Sin: Nanatsu no Taizai.', 86, 'https://cdn.myanimelist.net/images/anime/8/87985.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Corpse Party: Missing Footage', 'OVA', 1, 'Completed', '2012-08-02', NULL, '6', 'Someday a group of classmates will perform a charm at night after school—the Happy Sachiko charm. This paper doll ritual is meant to make them stay friends forever, but performing it incorrectly will lead them to be dragged down into a dilapidated phantom of Tenjin Elementary School, which had been torn down years ago. Trapped until they can reunite and perform the charm correctly, the students will have to solve the mystery of the haunted school in order to make it out alive.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Choboraunyopomi Gekijou Dai Ni Maku Ai Mai Mii: Mousou Catastrophe', 'TV', 12, 'Completed', '2014-07-08', '2014-09-23', '6', 'Manga club members Ai, Mai, and Mii continue their everyday absurd antics as they progress through high school alongside their upperclassman Ponoka. Whether the girls are drawing manga, joking around, or discovering odd creatures, they never run out of new ways to have fun together and grow closer as friends.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('The Five Killers', 'ONA', 1, 'Completed', '2007-01-01', NULL, '6', 'The Five Killers was supposed to be an original creation from writer/producer Eric Calderon as an animated TV series (12 episodes with a 1 hour finale) done by Gonzo. The designs were created by manga artist Maeshima Shigeki and the trailer was done under the direction of Trinity Blood director Hirata Tomohiro. The trailer is unfortunately all that came out of this project due to GDH''s alarming financial situation.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Monogatari no Aru Satou', 'Special', 1, 'Completed', '2017-10-10', NULL, '6', 'A short animation promoting the Komaya company. A lonely sugar elephant searches for companionship.', 1160, 'https://cdn.myanimelist.net/images/anime/3/88406.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Guan Hai Ce', 'ONA', 16, 'Completed', '2018-06-17', '2018-09-23', '6', '', 1042, 'https://cdn.myanimelist.net/images/anime/1711/108541.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Saint Seiya: Gold Saints Data File', 'Special', 3, 'Completed', '2006-12-15', '2007-02-16', '6', 'Short special about Gold Saints, included on DVDs of Saint Seiya: Meiou Hades Meikai-hen series.', 1030, 'https://cdn.myanimelist.net/images/anime/8/85080.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Twin Angel Break', 'TV', 12, 'Completed', '2017-04-07', '2017-06-23', '6', 'Amatsuki Meguru is a girl who innocently aspires to be a hero of justice and the cool Kisaragi Sumire who grew up in the strict Kisaragi household... The two girls who are in their 3rd year of middle school end up getting orders from a mysterious hedgehog named Miruku-chan and turn into Twin Angels in order to fight evil! Meguru is always cheerful but sometimes a bit too forceful. Meanwhile, Sumire isn''t accustomed with being around others. Despite their differences, as they work together, they start opening up to each other.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ankoku Shindenshou Takegami', 'OVA', 3, 'Completed', '1990-03-23', '1992-01-24', '6', 'A trio of diabolical dragons stirs from eons of slumber deep within the earth. Charging to the surface, they launch a bloody rampage against humanity, feasting on the weak and gaining strength from their hapless victims'' souls. It will take the power of ancient god Takegami, the Guardian of Darkness, to vanquish the evil serpent forces. But alas, the mortal body Takegami inhabits belongs to a host reluctant to fight.', 436, 'https://cdn.myanimelist.net/images/anime/1837/97239.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nodoka Mori no Doubutsu Daisakusen', 'Special', 1, 'Completed', '1980-02-03', NULL, '6', 'With Peter the fairy as chairman, the animals of Placid Forest gather in a meeting to discuss the villagers'' plan to cut down all the trees in the forest. They decide to stage a protest in the hope of preserving the woods, but the greedy men will not listen to their warning. The animals are forced to carry out one final operation. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Variable Geo', 'OVA', 3, 'Completed', '1996-11-29', '1997-06-27', '6', 'The special of the day is Variable Geo-a brutal battle between waitresses who serve up generous portions of energy blasts and vicious side orders of murderous martial artistry.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tasuuketsu', 'TV', 24, 'Completed', '2024-07-03', '2024-12-25', '6', 'During his school computer class, Saneatsu Narita is presented with a strange screen posing a yes-or-no question that quickly disappears. The next day, Saneatsu wakes up to a world where everyone, save for himself and a few others, is dead.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hand Shakers: Go ago Go', 'Special', 1, 'Completed', '2017-07-26', NULL, '6', 'Unaired 13th Episode of Hand Shakers.', 339, 'https://cdn.myanimelist.net/images/anime/9/87980.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('And2! And2!', 'ONA', 1, 'Completed', '2018-08-15', NULL, '6', 'The animation And2 Girls is based on the five members of the virtual idol group And2girls. The story takes place after the era of Big Power Outages in which Shang Jing City has become an international metropolis due to energy reserves and development. Idols have also become recognized by everyone and sought after. Studying at Music&amp;Art Private High School, the five girls encounter acquaintances and companions for their common purpose. They make unremitting efforts for the goal, boarding the summit of Star List through the match, to prove their strength!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ken to Mahou no Logres: Inishie no Megami x Fate/Extella', 'Special', 1, 'Completed', '2016-12-07', NULL, '6', 'A collaboration between the mobile game Ken to Mahou no Logless Inishie no Megami and the video game Fate/Extella (which takes place in the Fate/Extra and Fate/Extra CCC world). Advertising that Nero Claudius (and others) from the latter are now playable characters in the former. Along with limited edition equipment and prizes the even ran from December 07-21, 2016. The commercial features some live-action imagery of the phone app but is predominately unique animated footage.', 791, 'https://cdn.myanimelist.net/images/anime/1926/97011.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Satsuriku Tenshi Jibril PV', 'Special', 1, 'Completed', '2014-04-01', NULL, '6', 'Released as an April Fools prank in 2014, later included in the Blu-ray/DVD release of No Game No Life.', 538, 'https://cdn.myanimelist.net/images/anime/1527/121206.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bikini Warriors OVA', 'OVA', 6, 'Completed', '2016-12-07', '2021-05-17', '6', 'New OVAs slated for release in Fall 2016. The OVAs will include two new characters, Cleric and Kunoichi.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsuujou Kougeki ga Zentai Kougeki de Ni-kai Kougeki no Okaasan wa Suki desu ka?', 'TV', 12, 'Completed', '2019-07-13', '2019-09-28', '6', 'Forming a party with one''s mother in an online game seems not only unlikely but also uncomfortable to most teenage gamers. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Onizushi', 'ONA', 3, 'Completed', '2016-04-19', '2016-05-25', '6', 'A comedy series that pits the inhabitants of a Japanese sushi restaurant against a gaggle of greedy oni.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pâtisserie no Monster', 'ONA', 4, 'Completed', '2016-04-26', '2016-07-28', '6', 'Pâtisserie no Monster focuses on the titular monster Powan, the owner of a small pastry shop in France.', 1160, 'https://cdn.myanimelist.net/images/anime/1464/91691.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ball yo Doko e Yuku', 'ONA', 1, 'Completed', '2014-09-11', NULL, '5', 'Collaboration between Studio Binzo and J-toys Channel. Features zombies from Zombie Clay Anime.', 860, 'https://cdn.myanimelist.net/images/anime/8/72094.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Samurai', 'Movie', 1, 'Completed', '1965-01-01', NULL, '5', 'A short film by Kuri Youji.', 493, 'https://cdn.myanimelist.net/images/anime/3/71269.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Choujikuu Romanesque Samy: Missing 99', 'OVA', 1, 'Completed', '1986-07-05', NULL, '5', 'Getting caught up in a gang fight would be a bad day in anybody''s life. But for high school student Sami Yoshino, things go from bad to worse as she finds herself thrown across time and space to unknown worlds. Now she''s caught up in a gang fight of biblical proportions, between the divine masters of the universe and the demons who seek to destroy it. As it turns out, Samy hides phenomenal cosmic powers within her, and the demons will stop at nothing to suppress it. Can Samy ever escape the conflict and return to being a normal girl, or is the whole universe going to die?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zettai Shougeki: Platonic Heart', 'OVA', 5, 'Completed', '2008-10-29', '2009-02-25', '5', 'The story centers on the Platonic Heart, a jewel that—according to an old urban legend—can grant any wish when collected. Only a chosen few are allowed to compete in the Platonic Heart hunt, and high school junior Aya Iseshima is one of 11 girls and women who are taking part.', 85, 'https://cdn.myanimelist.net/images/anime/12/24959.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Trip Trek', 'ONA', 4, 'Completed', '2003-01-01', NULL, '5', 'A young girl from a fairy-tale world, Zocco searches the real world for her missing mother. She is accompanied by Minime, a magical companion / pet that her mother created for her.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Head Spoon', 'Movie', 1, 'Completed', '1972-01-01', NULL, '5', 'Furukawa Taku film.', 1004, 'https://cdn.myanimelist.net/images/anime/13/72630.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('In Search of Axis', 'Special', 3, 'Completed', '1989-01-01', '1991-01-01', '5', 'Polygon Pictures Inc.''s first animated work.', 695, 'https://cdn.myanimelist.net/images/anime/1409/95844.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kyochuu Rettou Movie', 'Movie', 1, 'Completed', '2020-01-10', NULL, '5', 'After an airplane crash during a school trip, Oribe Mutsumi and her classmates were stranded on a seemingly deserted island. Mutsumi found the other survivors, and used her wilderness knowledge to help them. She expects that they will be rescued in about three days, which doesn''t seem so long to endure. However, she didn''t account for the fact that the island is populated with gigantic killer insects. Her knowledge of butterflies, wasps, and more may be the only thing that will help any of her classmates survive to be rescued!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sayokyoku', 'Movie', 1, 'Completed', '1985-01-01', NULL, '5', 'Short film by Yamamura Kouji.', 1124, 'https://cdn.myanimelist.net/images/anime/1041/107680.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mayo Elle Otokonoko', 'OVA', 1, 'Completed', '2010-11-26', NULL, '5', 'Located far from town, standing on a headland, is Ginga Private Academy. The school buildings are refined and graceful, and waterways wend through the grounds. It is a large facility with 600 students in primary, middle, and high school sections, all studying the performing arts.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Prison Bear', 'ONA', 1, 'Completed', '2011-11-21', NULL, '5', 'Focuses on the odd inmates at a bear prison.', 457, 'https://cdn.myanimelist.net/images/anime/6/63759.jpg');
