INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Go! Go! Tokyo MER: Kinkyuujitai to Tatakau Nakama-tachi', 'ONA', NULL, 'Airing', '2022-01-05', NULL, '5', 'The live-action Tokyo MER: Hashiru Kinkyuukyuumeishitsu medical drama series got a short anime to commemorate the series'' movie announcement. It portrays the characters as animals.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shengsi Huifang', 'ONA', 20, 'Completed', '2016-10-19', '2017-03-08', '5', 'Young man Wei Sisi worked hard to support himself after losing all his memories. One day in an accident, he somehow obtained an ability with which he could see the memories of the dead. A series of events coming right after it made him aware that he had been involved into a well-designed conspiracy. His past was also gradually uncovered...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zhonghua Meide', 'TV', 99, 'Completed', '2004-01-01', NULL, '5', '', 792, 'https://cdn.myanimelist.net/images/anime/1686/122540.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lalala Lala-chan', 'ONA', 24, 'Completed', '2015-03-21', '2016-02-26', '5', 'Lala-chan is a slightly selfish squirrel girl. On her birthday the gifts given to her by her friends go awry. The group gets teleported into a new world (Earth) where they try to retrieve the elemental magic crystal balls that bring balance in their world.', 1077, 'https://cdn.myanimelist.net/images/anime/1785/91151.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lalala Lala-chan Mini', 'ONA', 24, 'Completed', '2015-03-26', '2016-02-11', '5', 'Lalala Lala-chan video letter style episodes. Characters break the 4th wall to talk to the viewer as if it was a reality show studio being filmed on camera. The episodes are meant to complement each episode of Lalala Lala-chan.', 1077, 'https://cdn.myanimelist.net/images/anime/11/88332.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Lalala Lala-chan: Patapata Daisensou', 'TV', 12, 'Completed', '2016-10-21', '2017-01-13', '5', 'The 2nd season of Lalala Lala-chan. A prince from another country washes ashore and asks for help from the group. His kingdom is overrun by an evil monster that has laid the land to waste.', 1077, 'https://cdn.myanimelist.net/images/anime/1828/91150.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pikachin-Kit', 'TV', 115, 'Completed', '2018-01-06', '2020-03-28', '5', 'A fifth-year elementary student named Eiji Toomatsu, and his "inspiration" buddy, a dog named Pochirou. One day Eiji finds a mysterious book called the "Pikachin Research Book," and learns about the seven tools that make up the Pikachin Kit. Eiji presses a button inside the research book, and immediately a "Future Amazon" delivery arrives at his door with the kit. Eiji uses the blueprints included in the box to assemble the kit, but it seems as though 1% part of the kit is still missing. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zukkoke Sannin-gumi: Kusunoki Yashiki no Guruguru-sama', 'Special', 1, 'Completed', '1995-11-11', NULL, '5', '', 436, 'https://cdn.myanimelist.net/images/anime/13/88358.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Neko Neko Gong Show', 'ONA', 6, 'Completed', '2015-08-13', '2015-11-16', '5', 'A collaboration between Kihara Yousuke and studio dwarf. Kihara is most famous for being the head artist for the PS2/GameCube game Ribbit King and the anime Nikoniko♪Connie-chan. Neko Neko Gong Show is a talent show for cats, where if their skits are bad, get a gong (made from a cat food tin can lid) hit to boot them off.', 1160, 'https://cdn.myanimelist.net/images/anime/8/88391.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Peace Shitenchou', 'Special', 5, 'Completed', '2014-12-14', '2015-02-13', '5', 'Shorts created to promote Ehime Bank''s mascot character Peace.', 698, 'https://cdn.myanimelist.net/images/anime/12/88412.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bary-san no Shokoku Manyuuki', 'TV', 47, 'Completed', '2016-02-03', '2016-03-30', '5', 'Ehime Prefecture''s mascot Bary-san travels to different Japanese prefectures. The short skits are meant to feature something local.', 457, 'https://cdn.myanimelist.net/images/anime/5/88460.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shi Wan Ge Leng Xiaohua Movie 2', 'Movie', 1, 'Completed', '2017-08-18', NULL, '5', '', 524, 'https://cdn.myanimelist.net/images/anime/12/90074.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nintama Rantarou: Saraba Ninjutsu Gakuen no Dan', 'Special', 2, 'Completed', '2017-10-30', '2017-10-31', '5', 'Rantarou misunderstands an overheard comment from the Headmaster and leaves Ninjutsu Academy in shock. At the same time, the Dokutake Castle ninja team is once again up to no good...', 53, 'https://cdn.myanimelist.net/images/anime/10/88492.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yakiniku-ten Sengoku', 'ONA', 12, 'Completed', '2017-12-17', '2018-02-25', '5', 'The story centers on Souji, who is kind but extremely timid. Souji, whose nickname is Mop, starts his first job at the neighborhood yakiniku shop "Sengoku." He struggles and grows together will his unique coworkers at the shop. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Stone Age: Jeonseol-ui Pes-eul Chaj-aseo', 'TV', 26, 'Completed', '2017-07-12', '2018-05-02', '5', 'An animated adaptation of the mobile game of the same name. Each episode is composed of two stories. The story is set in the future, after the destruction of machine civilization which leaves humans in a more primitive state. Dinosaurs, woolly mammoths, saber-tooth tigers, etc. roam free, as their species were brought back to life and modified to be friendlier thanks to cloning fossil samples during the machine civilization era. Children can become Stone Leaders by having one of these creatures as a "pet" which they can do friendly battles with against others.', 409, 'https://cdn.myanimelist.net/images/anime/1185/129475.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shimajirou no Wow! Movie 6: Mahou no Shima no Daibouken', 'Movie', 1, 'Completed', '2018-03-09', NULL, '5', '', 1022, 'https://cdn.myanimelist.net/images/anime/1265/90942.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Aurora wo Mita Kyouryuu-tachi', 'Movie', 1, 'Completed', '2011-01-01', NULL, '5', 'A planetarium program that features dinosaurs living in the cold Alaskan climate.', 1175, 'https://cdn.myanimelist.net/images/anime/4/88870.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Baito-saki wa "Aku no Soshiki"!?', 'ONA', 10, 'Completed', '2017-11-13', '2018-01-29', '5', 'Arihisa Aokura needs money. He needs money in order to support his family of orphans and earn a living at the same time. Looking online for potential employees, he finds a posting for a part time job in an "evil organization." Seeing that the pay and benefits were fairly substantial, he took the chance and took the interview. He was somehow hired and now has to work as a henchman inside the evil organization "Antares." Will he be able to survive the onslaught of missions against heroes while providing for his orphan brothers and sisters?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chikyuu wa Guruguru Merry-Go-Round', 'Movie', 1, 'Completed', '2017-01-01', NULL, '5', '', 207, 'https://cdn.myanimelist.net/images/anime/12/89028.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Youtai Nuhai Zai Shanghai 2: Xianglian Mima', 'Movie', 1, 'Completed', '2015-08-28', NULL, '5', 'The second Youtai Nuhai Zai Shanghai film which expands the back story of Rina and Michalli. It focuses on what happened to their parents fleeing and how the two children ended up in Shanghai as the Nazis try to hunt them down.', 792, 'https://cdn.myanimelist.net/images/anime/6/89106.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pooky''s', 'Movie', 1, 'Completed', '2007-09-11', NULL, '5', 'Charming but Surreal. Scary but Adorable. Pooky''s is a "Cool and Stylish" animation comedy full of cute &amp; unique ghost characters. Designers''unit "Spooky graphic" presents a great 3DCG animation piece to all the kids in the world. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shouji Li de Huanxiong Xiao Zhen', 'ONA', 26, 'Completed', '2021-01-21', '2021-07-08', '5', 'This is a story about a group of cute little animals that live in human cell phones and work hard to keep cell phones functioning properly so that people can maintain communication with others, keep in contact with the world, and gain a sense of happiness. The raccoon town in the cell phone is like a miniature human society, where there are various institutions and systems such as police stations, hospitals, entertainment venues, restaurants, air transport, public transport, etc., and of course, there is culture and festivals as well.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Digital Tokoro-san', 'TV', 245, 'Completed', '2000-10-02', '2001-09-28', '5', 'CGI shorts about famous Japanese comedian George Tokoro.', 695, 'https://cdn.myanimelist.net/images/anime/1777/114798.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Minami e Itta Misuke', 'Movie', 1, 'Completed', '1971-08-01', NULL, '5', 'Jumping out of the cupboard, Chi-cha and Ikeho ask for Misuke''s help, saying that they have to answer a quiz that the god Don-dan has given them to save their mother. Misuke then heads for a country in the south passing right through the cupboard.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shaonian Jinyiwei Xuzhang', 'ONA', 1, 'Completed', '2016-12-29', NULL, '5', 'Prologue of Shaonian Jinyiwei.', 142, 'https://cdn.myanimelist.net/images/anime/1374/114823.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Robby to Kerobby', 'TV', 52, 'Completed', '2007-04-01', '2008-03-30', '5', 'A story of the adventures of Robby and Kerobby along with their other friends.', 14, 'https://cdn.myanimelist.net/images/anime/4/67973.jpg');
