INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Twin Bee Paradise Specials', 'Special', 4, 'Completed', '1998-02-27', '1999-04-25', '5', 'Extras of Twin Bee Paradise that were included on the DVD Volumes.', 25, 'https://cdn.myanimelist.net/images/anime/1738/150538.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gokiburi-chan', 'TV', 20, 'Completed', '2005-03-21', '2005-04-15', '5', 'A story about love, friendship, and effort that cockroaches and their friends put into living behind a refrigerator in an ordinary salaryman''s family home. Cockroaches who are hated by all humans strive every day to be liked by everyone in the family; will the day when they are accepted by the family come?', 263, 'https://cdn.myanimelist.net/images/anime/1817/102767.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Panpaka Pants W-O-New!', 'TV', 26, 'Completed', '2016-04-02', '2016-10-15', '5', 'Sequel to Panpaka Pants O-New!. It follows a young underwear-wearing pig and his adventures.', 214, 'https://cdn.myanimelist.net/images/anime/6/79173.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('CoCO & NiCO', 'TV', 39, 'Completed', '2016-04-08', '2017-02-03', '5', 'CoCO and her sister NiCO are under training to become graceful and elegant cat princesses. They are watched over and trained by the strict but caring Lady Oppenheimer. CoCO and NiCO keeps Lady Oppenheimer quite busy as they try their best to learn the ways of a princess, and have fun with a little mischief along the way.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yongshi', 'Movie', 1, 'Completed', '2007-06-29', NULL, '5', 'Based on a Mongolian folklore, the story begins with a young warrior Barter coming to Balin Grassland. He rescues a young girl from a herd of running horses and finds out she is the daughter of the wrestling coach working for the grassland lord. Barter starts learning wrestling while working for the grassland lord as a coolie. Barter falls in love with the girl he saved. However, there is a reason for his coming to the grassland – he is looking for the man who killed his father.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('YanYan Machiko Specials', 'Special', 5, 'Completed', '2011-12-07', '2013-12-04', '5', 'YanYan Machiko shorts included with the DVD releases of the original series.', 463, 'https://cdn.myanimelist.net/images/anime/4/78980.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seishun Anime Zenshuu Specials', 'Special', 2, 'Completed', '1987-10-08', '1997-10-15', '5', 'Two episode, adaptations of Masao Kume''s Student Days and Saneatsu Mushanokoji''s The Friend Who Didn''t Believe in Friendship, were not broadcast in the original run, appearing instead as two "specials" on TV Asahi the following year.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Magnerobo Ga-Keen Recap', 'OVA', 1, 'Completed', NULL, NULL, '5', '', 1030, 'https://cdn.myanimelist.net/images/anime/8/78853.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nameko: Sekai no Tomodachi', 'TV', 26, 'Completed', '2016-04-10', '2017-02-12', '5', 'Nameko Forest gathers nameko from all over the world. They form the Nameko Universal Ranger (NUR) to convey the charm of the forest. It''s an everyday life of inviting new nameko with unique personalities to the forests. What incident will happen today?', 879, 'https://cdn.myanimelist.net/images/anime/13/78819.jpg');
