INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiong Chumo: Nianhuo', 'Special', 1, 'Completed', '2014-01-30', NULL, '5', 'The second New Year special, this time released a day before the Chinese New Year. Logger Vick finds himself unexpectedly unemployed for the upcoming New Year. In order to afford presents, he takes on a temporary forest ranger job.  Briar and Bramble are quire mistrusting of him now that his new job requires that he protect the forest.', 280, 'https://cdn.myanimelist.net/images/anime/1453/90187.jpg');
