INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiong Chumo: Tanxian Riji', 'TV', 52, 'Completed', '2017-11-28', '2017-12-01', '5', 'Ninth season of Boonie Bears. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Taka no Tsume 7: Joou Heika no Jobuubu', 'Movie', 1, 'Completed', '2014-04-04', NULL, '5', 'A second collaboration with Town Work. Jobuubu is looking for a job and so is the Chancellor as he was fired from his previous one. The two run into each other on the street after having an unsuccessful job hunt. Chancellor takes Jobuubu back to the Eagle Talon headquarters where they discover that he has the ability to repair hand dryers. The repair not only makes it dries properly but gives the user a sense of pure bliss. Together they team up; Chancellor finds clients while Jobuubu does the repairs. Queen Electronic, one of the manufactures of the hand dryers, gets wind of them and invites them to work on new ideas for their company in order to improve their old products. But a rival company wants to make sure they don''t succeed.', 214, 'https://cdn.myanimelist.net/images/anime/3/90066.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bakutsuri Bar Hunter', 'TV', 25, 'Completed', '2018-10-02', '2019-03-26', '5', 'After finding a strange fishing rod at his father''s gravesite, elementary school student Totta decides to give it a whirl, only to discover that it fishes "bar souls" right from the barcodes of everyday items around him! From ramen, to drinks, to candy, the Bakutsuri Bar Rod reveals a whole new world of discovery and sport for fishing-lover Totta. With the rod in hand, and a new companion named Potepen that he fished from his bag of potato chips, Totta embarks on a mission to catch the strongest bar souls possible.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tenkousei wa Kounin Kaikeishi!', 'OVA', 1, 'Completed', '2013-03-01', NULL, '5', 'A video produced for middle and high school students showcasing the role of CPAs and the importance of audits. The anime aims to make accounting an attractive occupation.', 999, 'https://cdn.myanimelist.net/images/anime/1198/90120.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nikuiyo! Galbi-kun: Kemuri ga Me ni Shimiru', 'ONA', 5, 'Completed', '2018-01-19', '2018-05-17', '5', 'A short gag anime about yakiniku meat on a grill. It primarily focuses on Galbi-kun (beef short rib) who admires a higher cut of meat and tries to change his demeanor to be more refined.', 1160, 'https://cdn.myanimelist.net/images/anime/1489/90148.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuiba Yao Xia Zhuan', 'ONA', 20, 'Completed', '2014-07-19', '2014-12-27', '5', 'The backstories of the characters in the Kuiba movies.', 1082, 'https://cdn.myanimelist.net/images/anime/1568/90241.jpg');
