INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Umi Da! Funade Da! Nikoniko, Pun', 'Movie', 1, 'Completed', '1990-01-04', NULL, '5', 'Animation movie by Hirata Toshio.', 638, 'https://cdn.myanimelist.net/images/anime/3/43743.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tensai? Dr. Hamax', 'TV', 12, 'Completed', '2007-10-06', '2007-12-22', '5', 'No synopsis has been added for this series yet.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Taiyo Kikaku''s 49th Anniversary Movie', 'ONA', 1, 'Completed', '2017-02-03', NULL, '5', 'TAIYO KIKAKU Co., Ltd., a commercial production company based in Tokyo, Japan, was founded on February 5th, 1968, and proudly celebrates its 49th anniversary with the release of a paper craft stop-motion animation short to celebrate this milestone. The sun-shaped corporate logo symbolizing the company’s name is beautifully animated in a white setting, depicting the whole process of filmmaking from pre-production to post-production. The film is crafted entirely out of paper by director Ayako Hiroki, a member of “TECARAT,” a division of TAIYO KIKAKU.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Miracle Psychicer Seizan', 'OVA', 5, 'Completed', '1991-11-20', '1993-06-17', '5', '', 939, 'https://cdn.myanimelist.net/images/anime/2/43185.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('81 Hao Nongchang: Baowei Mai Ji', 'Movie', 1, 'Completed', '2013-09-28', NULL, '5', 'Even the smallest creatures can make a big difference in this eggs-ceptionally funny adventure! Young chicks Cluck Norris, Chickpea, and Tiny SchwarzHENegger are determined to show everyone that chickens really can fly, but when their tiny alien pal, Magic, is in danger, this young feathered trio will join the efforts of their animal neighbors, including Charlie Horse, Angelina Poultrie, Meryl Cheep, and more, in order to save their home and their friend from the "fowlest" of villains. Featuring the voice talents of Sean Astin and Jeff Foxworthy, it''s a wild rescue mission that will have everyone cracking up.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sore Ike! Zukkoke Sannin-gumi', 'TV', 26, 'Completed', '2004-04-04', '2004-10-03', '5', 'Based on Nasu Masamoto''s Zukkoke Sannin-gumi juvenile novels series.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Norimono Man: Mobile Land no Car-kun', 'TV', 104, 'Completed', '2020-04-02', '2022-03-24', '5', 'The anime will depict various vehicles as characters in the "Mobile Land" island. The protagonist Car-kun arrives at the island as a delivery worker. Through his deliveries, he gets to know the residents of Mobile Land, all while following traffic rules and having his deliveries stopped by the meddling Sabibi. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Origami Ninja Koyankinte', 'TV', NULL, 'Airing', '2020-04-07', NULL, '5', 'Koyan, the Origami Ninja, came to Earth from his planet Origamio to find the magical stone "Hapiton" that has the ability to make people happy. On the way, he was joined by childhood friend Namin anda new friend Lublin. One day, a villain called Evilrun appeared. Evilrun has a black hole in her stomach and tries to inhale anything. Every time an event happens, Evilrun gets in the way of Koyan and friends. But what Evilrun''s aim is remains a mystery...', 239, 'https://cdn.myanimelist.net/images/anime/1860/106477.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chickip Dancers', 'TV', 26, 'Completed', '2021-10-05', '2022-03-29', '5', 'TV anime based on San-X''s new series of mascot characters "Chickip Dancers." The main characters in the anime will be the apprehensive but curious bone-in chicken Hone Chicken, and the dancing instructor frog Skip Gaeru, who travels by dancing.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Otoppe', 'TV', 265, 'Completed', '2017-04-03', '2023-03-31', '5', 'The series follows a young girl named Shina who hopes to become the world''s best DJ, and is interested in new sounds. Shina explores a mysterious world filled with Otoppe, strange creatures capable of unique sounds.', 1175, 'https://cdn.myanimelist.net/images/anime/4/85180.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shimajirou no Wow!', 'TV', NULL, 'Airing', '2012-04-02', NULL, '5', 'Fourth season of the Shimajirou children''s television series.', 1022, 'https://cdn.myanimelist.net/images/anime/9/50737.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kuma no Puutarou', 'TV', 30, 'Completed', '1995-04-19', '1996-03-29', '5', 'The series depicts Puutarou''s peculiar encounters with his bizarre neighbors.', 879, 'https://cdn.myanimelist.net/images/anime/6/31019.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zouressha ga Yatte Kita', 'Movie', 1, 'Completed', '1992-07-04', NULL, '5', 'An educational film about the Elephant Trains in Japan. During WW2 many zoos were slaughtering their dangerous animals (such as elephants) as a safeguard against Allied bombings which might release the animals. After WW2, the only elephants that remained in Japan were two at Higashiyama Zoo in Nagoya. Special trains called Elephant Trains were arranged to bring children from all over the country to Higashiyama Zoo.', 587, 'https://cdn.myanimelist.net/images/anime/9/30719.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fujilog 2nd Season', 'TV', 13, 'Completed', '2011-10-02', '2011-12-26', '5', 'More about the hapless life of Osamu Fujiyama, 33 years old and NEET (Not in Education, Employment or Training).', 1193, 'https://cdn.myanimelist.net/images/anime/4/30525.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Silk Road Shounen Yuuto', 'TV', 26, 'Completed', '2006-09-16', '2007-03-24', '5', 'When a boy Yuto visits Qinghai in China, he is involved in the battle between time-travelers, and he is sent to the Silk Road in the past. They are looking for a mysterious treasure, the statue of Yuki Daruma Taishi, which is said to make miracles. Seeing historical events and encountering historical persons, such as Yang Guifei and Xuanzang, he will learn many thinks. Whether will he be able to go back to today?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ganbare!! Nattou-san', 'TV', 4, 'Completed', '2011-07-02', '2011-07-01', '5', 'No synopsis has been added for this series yet.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yoshida Katsuko no Yabai wa! SDGs: Araburu! Trouble! Sustainable!', 'TV', 13, 'Completed', '2021-10-04', '2021-12-27', '5', 'The anime centers on Katsuko Yoshida, the cousin of Eagle Talon''s Yoshida-kun, and an employee in Kemonomichi Electronics'' "special general affairs" section. She educates her poorly informed colleagues about their misunderstandings of Sustainable Development Goals, the United Nations-backed goals for member nations to attain a sustainable future.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('4-nin wa Sorezore Uso wo Tsuku', 'TV', 11, 'Completed', '2022-10-16', '2022-12-25', '7', 'What do an alien, former ninja, weak telepath, and boy pretending to be a girl have in common? They are all classmates at Kashihara Girls'' Academy, and they hide their true identities from the world. Rikka, Chiyo, Sekine, and Tsubasa seem like the best of friends, but they each harbor a monumental secret that they cannot reveal, no matter what. In order to continue masquerading as normal middle school girls, each of them must invent creative ways to conceal their true selves. But that is easier said than done, as the four students end up entangled in numerous shenanigans along the way.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mikakunin de Shinkoukei: Kamoniku tte Midori-ppoi Aji ga Suru no ne.', 'OVA', 1, 'Completed', '2014-03-28', NULL, '7', 'OVA included with special edition of volume 5 of the Mikakunin de Shinkoukei manga.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rurouni Kenshin: Meiji Kenkaku Romantan - Shin Kyoto-hen', 'OVA', 2, 'Completed', '2011-12-17', '2012-06-23', '7', 'A large scale remake of the time after Kenshin leaves Tokyo up until before the inferno of Kyoto.', 879, 'https://cdn.myanimelist.net/images/anime/2/39663.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Planet With', 'TV', 12, 'Completed', '2018-07-08', '2018-09-23', '7', 'According to the theories of oneiromancy, dreams of dragons represent the struggle of losing yourself to your own anger. Fittingly, Souya Kuroi wakes up from a nightmare of a massive dragon destroying everything around him in a blaze of rainbow colored light. After being told that he lost his parents and memory in a strange accident, the waking world becomes another nightmare in itself. With this dream being his only memory, he has no choice but to be taken care of by his two strange guardians: the spunky and energetic maid Ginko, and a huge cat known only as "Sensei."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('SSSS.Gridman', 'TV', 12, 'Completed', '2018-10-07', '2018-12-23', '7', 'Yuuta Hibiki wakes up in the room of Rikka Takarada and notices two things: he has no memories, and he can hear a mysterious voice calling his name from a nearby room. On further inspection, he finds a robot—which introduces itself as Hyper Agent Gridman—behind the screen of an old computer. Much to Yuuta''s surprise, Rikka cannot hear Gridman, nor can she see the ominous monsters looming over a thick fog as it envelopes the town outside.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('K: Seven Stories Movie 3 - Side:Green - Uwagaki Sekai', 'Movie', 1, 'Completed', '2018-09-01', NULL, '7', 'Sukuna Gojo is a boy who ran away from his wealthy home after becoming disgusted by his controlling parents. Since then, he''s been surviving alone on the streets using an SNS app called JUNGLE, which grants its user unnatural power and abilities.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Super Danganronpa 2.5: Komaeda Nagito to Sekai no Hakaisha', 'OVA', 1, 'Completed', '2017-01-12', NULL, '7', 'At Hope''s Peak Academy, a school full of extraordinarily talented individuals, Nagito Komaeda is an ordinary boy with no special traits or interesting skills to speak of—except for his incredible unluckiness. Just walking to school in the morning leads to a number of unfortunate accidents, which only escalate as the day goes on. Despite this, Komaeda leads a relatively normal life and is satisfied with his modest slice of happiness.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('To LOVE-Ru: Multiplication - Mae kara Ushiro kara', 'OVA', 1, 'Completed', '2017-11-02', NULL, '7', 'On what would typically be another ordinary day, Lala Satalin Deviluke takes one of her recent inventions—a robotic cat with cloning powers—to school for a chance to show it to Rito Yuuki. Upon accidentally touching the gadget, Rito begins repeatedly duplicating himself, and the school is soon entirely overrun by a horde of his clones.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shingeki no Bahamut: Genesis - Short Story', 'ONA', 2, 'Completed', '2016-12-28', '2017-02-20', '7', 'The first short story focuses on Favaro and Kaiser between the events of the first and second series as they visit Favaro''s home village. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mouretsu Pirates', 'TV', 26, 'Completed', '2012-01-08', '2012-07-01', '7', 'Far in the future, where interstellar travel is considered commonplace, high school student Marika Katou balances her duties in the space yacht club and her job as a restaurant waitress. Following a chance encounter with a peculiar pair of customers, Marika meets them again and learns that her absent father has passed away.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('PriPara Movie: Mi~nna de Kagayake! Kirarin☆Star Live!', 'Movie', 1, 'Completed', '2017-03-04', NULL, '7', 'The anime will take place not in space (uchuu), but in "Puchuu," and will feature the first "Puchuu tour" in PriPara history. The PriPara idols will tour the solar system and will discover new wonders. Various trials await the idols, and things aren''t straight forward. Will the idols be able to make it back to Earth safely?
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ore no Nounai Sentakushi ga, Gakuen Love Comedy wo Zenryoku de Jama Shiteiru OVA', 'OVA', 1, 'Completed', '2014-05-20', NULL, '7', 'Unaired TV episode bundled with the light novel''s volume eight.', 238, 'https://cdn.myanimelist.net/images/anime/1464/112501.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tonkatsu DJ Agetarou', 'TV', 12, 'Completed', '2016-04-10', '2016-06-26', '7', 'Tonkatsu chef by day, professional DJ by night—this is the aspiration of Agetarou Katsumata, whose family owns a small tonkatsu shop in Shibuya.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ore no Nounai Sentakushi ga, Gakuen Love Comedy wo Zenryoku de Jama Shiteiru', 'TV', 10, 'Completed', '2013-10-10', '2013-12-12', '7', 'For Kanade Amakusa, life as a high schooler should have been normal, and it would have been—if he wasn''t living with the most ridiculous curse imaginable. "Absolute Choice," a system forced upon him by a self-proclaimed god, randomly presents a mental selection of actions that he must act out based on his choice. To add to his dilemma, it tends to occur in the most public of places, and his options never seem to deviate from the rude and crude in nature.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Fate/Grand Order: Zettai Majuu Sensen Babylonia - Initium Iter', 'Special', 1, 'Completed', '2019-08-04', NULL, '7', 'The year 2010 AD. Romani Archaman has been posted to Chaldea. There, he becomes the primary doctor for a young girl. Mash Kyrielight, Chaldea''s second successful summoning experiment, is interested in the word "Senpai." The interaction between the two gives Mash a reason to hope. That hope becomes a wave and starts to spread. That is your story, the story of a normal "somebody." The story at the beginning of a journey that weaves the future.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wake Up, Girls! Seishun no Kage', 'Movie', 1, 'Completed', '2015-09-25', NULL, '7', 'Movie sequel of Wake Up, Girls!, announced at Wake Up, Girls! Festa.2014 Winter.', 644, 'https://cdn.myanimelist.net/images/anime/6/75337.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Piece Recap', 'OVA', 1, 'Completed', '2010-03-17', NULL, '7', 'A recap OVA summarizing the ten-year TV series up to the Impel Down arc.', 1030, 'https://cdn.myanimelist.net/images/anime/9/20706.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sengoku Basara: Setonai no Gekitotsu! Hi wo Fuku Umi no Daiyousai - Fugaku!!', 'Special', 1, 'Completed', '2010-01-06', NULL, '7', 'Maeda Toshiie and Matsu visit Chousokabe Motochika, who governs Shikoku. They tell Motochika unreasonable demands from Nobunaga. Motochika rejects them and urges Maeda to betray Nobunaga. Meanwhile Keiji tries to convince Mouri Motonari to join the fight against Nobunaga, and is imprisoned as a result. Motochika and Motonari move against each other.', 704, 'https://cdn.myanimelist.net/images/anime/6/25451.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tales of Symphonia The Animation: Sylvarant-hen', 'OVA', 4, 'Completed', '2007-06-08', '2007-12-21', '7', 'Two worlds exist, both unaware of the existance of the other. In order for one world to flourish, the other will have to perish. On the perishing world, a Chosen one is sent on a journey to restore that world''s mana by awakening the Spirits and becoming an angel. Colette Brunel, the Chosen of Sylvarant, sets out on her journey accompanied by her best friends Lloyd Irving and Genis Sage. As they travel further they meet more friends and even more enemies, while they learn more and more about the truth behind the World Regeneration. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Deadman Wonderland', 'TV', 12, 'Completed', '2011-04-17', '2011-07-03', '7', 'It looked like it would be a normal day for Ganta Igarashi and his classmates—they were preparing to go on a class field trip to a certain prison amusement park called Deadman Wonderland, where the convicts perform dangerous acts for the onlookers'' amusement. However, Ganta''s life is quickly turned upside down when his whole class gets massacred by a mysterious man in red. Framed for the incident and sentenced to death, Ganta is sent to the very jail he was supposed to visit. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Love Stage!!', 'TV', 10, 'Completed', '2014-07-10', '2014-09-11', '7', 'With an actress mother, producer father, and rockstar brother, anyone would expect Izumi Sena to eventually enter showbiz himself. However, aside from a commercial for a wedding magazine when he was a child, Izumi has never been in the spotlight; instead, he aims to become a manga artist. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shakugan no Shana: Koi to Onsen no Kougai Gakushuu!', 'OVA', 1, 'Completed', '2006-12-08', NULL, '7', 'Yuji and Shana''s class go on a trip to see various temples and shrines, followed by a trip to a hot springs resort. During the trip, Matake Ogata tries to tell Eita Tanaka her feelings for him, but various complications and hijinks occur that prevent her from doing so.', 436, 'https://cdn.myanimelist.net/images/anime/1710/120194.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga Tetsudou 999: Kimi wa Haha no You ni Aiseru ka!!', 'Special', 1, 'Completed', '1980-10-02', NULL, '6', 'A remake of episodes 51-52 of the TV version.', 1030, 'https://cdn.myanimelist.net/images/anime/1529/133416.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hitorigurashi no Shougakusei', 'ONA', 10, 'Completed', '2017-10-10', '2017-12-12', '6', 'Rin Suzune is a nine-year-old girl who, due to her parents'' deaths, lives alone and runs her family''s restaurant by herself. Since she is a child, she lacks the proper knowledge to cook good food and manage a business, so her attempts to make money are unsuccessful. To make matters worse, she is bullied in school for being poor! But through it all, Rin remains resilient. Although her restaurant''s food is not the greatest, local residents are drawn to the establishment, hoping to lend Rin a hand because of her sincere nature.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Vatican Kiseki Chousakan: Majo no Soup', 'OVA', 1, 'Completed', '2018-04-11', NULL, '6', 'While going through old documents, Roberto Nicholas comes upon a peculiar record. It details the agreement of a witch who concocted a soup that supposedly granted generations of popes with longevity in return for her exoneration from the brutal witch trials. Curious as to why the Vatican treated the record with such secrecy and whether the elixir of longevity truly exists, Roberto and his partner, Josef Kou Hiraga, seek to recreate the witch’s soup.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nyoro-n Churuya-san', 'ONA', 13, 'Completed', '2009-02-13', '2009-05-08', '6', 'An anime adaptation of the 4-panel strip manga release: Nyoron Churuya-san. Based on Suzumiya Haruhi''s energetic and ''always up to go'' character, Tsuruya.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Meiken Lassie: Yume ni Mukatte Hashire!', 'Special', 1, 'Completed', '1997-02-25', NULL, '6', 'The unaired episode 26 of Meiken Lassie.', 607, 'https://cdn.myanimelist.net/images/anime/3/85785.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tensai Ouji no Akaji Kokka Saisei Jutsu: Short Drama Specials', 'Special', 4, 'Completed', '2022-03-30', '2022-06-29', '6', 'Extra chibi short dramas written by Tooru Toba featuring the characters of Tensai Ouji no Akaji Kokka Saisei Jutsu, included across the Blu-ray release of the series.', 39, 'https://cdn.myanimelist.net/images/anime/1140/120676.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hero Mask 2nd Season', 'ONA', 9, 'Completed', '2019-08-23', NULL, '6', 'The investigation on masks is still ongoing as Connor is still on the loose. New clues and movements starts appearing after a simple bus crashes in which only one girl survives completely untact. Who is she and how is she related to the case? SSC continue to investigate but, after Steven''s death the police director - Richard put resignation, new director is suspicious of SSC. He place a new agent in SSC team...', 939, 'https://cdn.myanimelist.net/images/anime/1960/102191.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Digimon Survive: Prologue Movie', 'ONA', 1, 'Completed', '2019-07-22', NULL, '6', 'A prologue movie released on Bandai Namco''s official YouTube channels for the eventual 2020 release of the Digimon Survive game. The movie was first shown at the Anime Expo''s panel "The Future of Digimon" and then later posted online.', 1030, 'https://cdn.myanimelist.net/images/anime/1099/102198.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kigyou Senshi Arslan', 'Special', 6, 'Completed', '2016-10-05', NULL, '6', 'Short anime of Arslan Senki (TV) characters working in an office environment. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gundam: G no Reconguista Movie II - Bellri Gekishin', 'Movie', 1, 'Completed', '2020-02-21', NULL, '6', 'In an attempt to rescue Bellri and the others, Dellensen launches an attack on the pirate corps'' Megafauna. Bellri, forced into space combat in Earth orbit, fails to realize he is facing his former instructor and shoots him down with the G-Self.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Da Wang Bu Gaoxing', 'ONA', 12, 'Completed', '2020-01-01', '2020-03-11', '6', 'We follow the daily life of Xiao Luo, a young yama (god and judge of the dead) who is afraid of ghosts. In order to properly reign in the underworld, she will have to face her fears.', 369, 'https://cdn.myanimelist.net/images/anime/1003/106043.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Qiang Shen Ji: Xuezu Mishi Pian', 'ONA', 12, 'Completed', '2019-12-15', '2020-02-23', '6', 'Third season of Qiang Shen Ji.', 578, 'https://cdn.myanimelist.net/images/anime/1898/108205.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chie-chan Funsenki: Jarinko Chie', 'TV', 39, 'Completed', '1991-10-19', '1992-09-22', '6', 'An adaptation of the first series, with different characters and an alternate setting.', 1036, 'https://cdn.myanimelist.net/images/anime/12/26026.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tottoko Hamtarou OVA 2: Hamuchanzu no Takara Sagashi Daisaku - Hamuha! Suteki na Umi no Natsuyasumi', 'OVA', 1, 'Completed', '2003-03-01', NULL, '6', 'As Laura heads out to summer camp, Hamtaro and Oxnard come across a young girl by the name of Haibi, who''s trying to find the ocean. Haibi found a treasure map while searching through the storage burrow and is now willing to find the treasure to help her heat exhausted granny. The Ham-Hams, who are more than willing to help her, pack their things and set out to find the treasure. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shin Koihime†Musou: Live Revolution', 'OVA', 1, 'Completed', '2010-03-17', NULL, '6', 'Shin Koihime†Musou characters sing theme songs on stage at a live event.', 241, 'https://cdn.myanimelist.net/images/anime/1061/129468.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tistou Midori no Oyayubi', 'Movie', 1, 'Completed', '1990-03-24', NULL, '6', 'When eight-year-old Tistou is sent home from school after being unable to stop falling asleep at lessons, his father decides that he will continue his education by learning from observation of real life, and where better to start than in the garden!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchuu Kuubo Blue Noah', 'TV', 24, 'Completed', '1979-10-13', '1980-03-30', '6', 'Set in the year 2052, Earth has managed to find peace until the arrival of the Death Force - ruthless aliens from a dying solar system - who are desperately searching for a new home. Attacking the Earth with a massive satellite ship called Terror Star, the aliens proceed to terraform the planet to make it their own. For mankind there is one hope: it''s up to Colin Collins and a small band of his fellow surviving students to crew a top-secret submersible vessel that can fight the invaders at sea or in space.', 46, 'https://cdn.myanimelist.net/images/anime/2/27147.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dokonjou Gaeru', 'TV', 103, 'Completed', '1972-10-07', '1974-09-28', '6', 'When Hiroshi was fighting against his rival Gorillaimo, he stumbled over a stone and fell on to a frog. To be surprised, the frog was still alive and it named itself Pyonkichi.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Teekyuu 2 Specials', 'Special', 2, 'Completed', '2013-10-25', NULL, '6', 'Short specials included in the Blu-ray release.', 527, 'https://cdn.myanimelist.net/images/anime/12/56005.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yoza-Quar!', 'Special', 6, 'Completed', '2013-12-18', '2014-05-21', '6', 'Each of the six BD/DVDs will include one short. They will feature the characters in a "slighly risqué" light not seen in the main story.', 1009, 'https://cdn.myanimelist.net/images/anime/6/55779.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Megami Kouhosei', 'TV', 12, 'Completed', '2000-01-10', '2000-03-27', '6', 'In the future humankind has expanded and colonized other planets. Then an alien species, Victim, attacks the human colonies leaving only one planet, Zion. In an effort to stop Victim from destroying the last planet a training school, GOA, is set up to gather boys from the Zion colonies and train them to become pilots of the Ingrids AKA The Goddesses, five fighting robots that protect Zion. The boys must possess a rare blood type, EO, as well as a special ability, or EX. Zero (Candidate 88) has just arrived in GOA when he falls into the cockpit of the Ingrid Eeva-Leena. Since the synch between pilot and Ingrid are very sensitive everyone believes the Goddess will kill Zero in an attempt to synch. Just before Zero passes out he makes a full synch with the Goddess. Before he can find out more about the incident, his pilot training begins.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Makasete Iruka!', 'OVA', 1, 'Completed', '2004-06-10', NULL, '6', 'While most children their age are busy with elementary school, Umi, Sora, and Ao only have one thing on their minds: making money! The girls run their own business for odd jobs, willing to take on nearly any request for the right price. When a concerned parent hires Umi, Sora, and Ao to convince her son to return to school, they struggle to convey the importance of a system they do not participate in.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ai no Wakakusa Monogatari Specials', 'Special', 2, 'Completed', '2001-01-01', NULL, '6', 'A summary of the Ai no Wakakusa Monogatari full series aired as a TV special in 2001.', 607, 'https://cdn.myanimelist.net/images/anime/6/42395.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Uchuu Kaizoku Mito no Daibouken', 'TV', 13, 'Completed', '1999-01-05', '1999-03-30', '6', 'Mito isn''t just another space pirate, she''s a three foot tall childlike alien with enough guts to outshine a supernova. She''s known as the galaxy''s most dangerous pirate, a wanted criminal who destroys a dozen police space cruisers every day before breakfast. But all she really wants is to be called "Mom."
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Okusama wa Mahou Shoujo', 'TV', 13, 'Completed', '2005-07-04', '2005-09-26', '6', 'Ureshiko Asaba, 26 years old, married. Few people know the fact that she is a magical girl named "Agnes", and she is actually the guardian of the town where she lives. One day she meets Sayaka Kurenai, aka "Cruje", another magical girl appointed by the magic realm as the legitimate sucessor to her position, but Agnes is reluctant in letting her assume because she knows that Cruje has orders to erase the whole place, including its human inhabitants with the purpose of creating a new one. To complicate matters, Ureshiko must deal with the growing distance between her and her husband, Tamotsu, her crescent feelings for Tatsumi Kagura, a young man who is now living as a tenant in her home, and the fact that in the moment she ever kisses a common human, she would lose her powers forever. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nangoku Shounen Papuwa-kun', 'TV', 42, 'Completed', '1992-10-10', '1993-10-02', '6', 'Papuwa-kun is a young boy living a quiet life with his dog, Chappy, on a small island located somewhere in South Pacific, when Shintaro, who is being pursued by gangsters, invades their happy existence. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hi no Youjin', 'Movie', 1, 'Completed', '2012-06-04', NULL, '6', 'The city of Edo, the 18th century.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mori no Densetsu', 'Movie', 1, 'Completed', '1987-12-18', NULL, '6', 'A tranquil forest and all of its residents must face the destruction of man. A squirrel, born and raised in the forrest, fights to defend his home and faces trials and adversities along the way.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ginga Tetsudou 999: Hoshizora wa Time Machine', 'Movie', 1, 'Completed', '2007-07-14', NULL, '6', 'Sometime in the 21st century on the Earth, Galaxy Express 999 destined for Great Andromeda is about to depart. A mysterious girl, Jula, suddenly appears in front of Maetel and Tetsuro who are visiting a museum. After predicting the fall of the human race, Jula has disappeared into outer space. Matel and Tetsuro follow her riding in the 999. Tetsuro finds Jula on asteroid Itokawa, which was once explored by the Hayabusa probe. Jula disappears into space again but her spacecraft crashes into an asteroid, falling down to Jupiter. Will Tetsuro be able to rescue Jula? What does Jula mean by the "fall of the human race"? Transcending space and time, this is the saga of the 999 traveling among the stars in our solar system.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hana yori Dango (Movie)', 'Movie', 1, 'Completed', '1997-03-08', NULL, '6', 'Set in an alternative timeline to the TV series and manga, the movie features a classic Cinderella story told through the medium of 80''s dance. Tsukushi Makino is a trainee dancer in a New York Performance group, struggling to become the star of the show with the help of Rui Hanazawa and Tsukasa Doumyouji.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Futari Ecchi', 'OVA', 4, 'Completed', '2002-07-26', '2004-01-22', '6', 'Makoto and Yura Onoda are a newly-wed couple with zero sexual experience. Yura is a shy and naive 25-year-old woman whose good looks grab men''s attention, something that she dislikes because she gets embarrassed very easily. Her husband Makoto is of the same age, but as opposed to his wife, he loves having dirty thoughts about other women. Physically though, Makoto is truly faithful to Yura.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kaze no Na wa Amnesia', 'Movie', 1, 'Completed', '1990-12-22', NULL, '6', 'Two years ago, a mysterious wind swept over the Earth without warning, taking everyone''s memories with it. Not knowing their names or even how to speak, cars crashed, planes dropped from the sky, and society crumbled in an instant. One young man happens to wander into a military testing facility, where he meets Johnny, a young boy who underwent experimental memory enhancement treatment and could, therefore, still remember who he was. Johnny names the young man Wataru and teaches him everything that he can before his frail body fails him.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Venus Versus Virus', 'TV', 12, 'Completed', '2007-01-12', '2007-03-30', '6', 'Venus Versus Virus follows regular schoolgirl Sumire who''s had the ability to see ghosts since a young age. She tells friends and family about this fact and they just dismiss it, thinking she''s a liar. A chance encounter with a broach flying out of nowhere, a monster and gothloli clad monster killer named Lucia leaves her with a life changing decision to use her ability and fight against these "viruses" feeding upon the human race.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('1 Pound no Fukuin', 'OVA', 1, 'Completed', '1988-12-02', NULL, '6', 'Young boxer Kosaku Hatanaka was once Coach Mukoda''s prized prospect and the only member of their gym to become a professional. In the short time he has been on the scene, however, he has racked up an unimpressive record, failing to even make his weight class for several matches. After a particularly embarrassing incident in the ring causes the cancellation of multiple upcoming fights, his coach tells him that his next bout may be his last if he fails to shape up.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Seikimatsu★Darling', 'OVA', 1, 'Completed', '1996-02-16', NULL, '6', 'Kousaku Ogata has been nursing feelings for his coworker, Youichirou Takasugi, for so long that he can no longer sleep without dreaming of him. When he finally manages to confess, he is thrilled that Takasugi feels the same way. But despite their mutual attraction, Takasugi thinks that their relationship is doomed to fail due to an unfortunate incompatibility in the bedroom. Unwilling to give up, they end up challenging each other to a contest of romance in order to determine what form their relationship will take.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Island', 'TV', 12, 'Completed', '2018-07-01', '2018-09-16', '6', 'On a remote island far from the mainland named Urashima, a man washes ashore, with no recollection of his name or homeland. What he does recall, however, is that he is a time traveler with a mission: to save a certain girl from harm. As nightfall arrives, he meets Rinne Ohara, a girl who sings a tune that reminds him of a specific name—Setsuna—and decides to use it as his own.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('One Punch Man 2nd Season: Ichigeki de Wakaru! Maji Furikaeri!', 'Special', 1, 'Completed', '2025-10-05', NULL, '6', 'Commemorative recap of One Punch Man 2nd Season.', 436, 'https://cdn.myanimelist.net/images/anime/1604/153958.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koala Enikki', 'ONA', NULL, 'Airing', '2025-10-02', NULL, '6', 'Koala writes about daily life, whether it''s good or bad, happy or sad. Koala treats every day as a precious day.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tong Ling Fei 2nd Season', 'ONA', 24, 'Airing', '2025-07-17', NULL, '6', 'Qian Yunxi, the eldest daughter of the prime minister of Guyu Kingdom, has supernatural powers. She has been considered an unlucky person since she was a child and is forced to marry into the Ye Palace. Seeing her sincerity and kindness, the prince Ye Youming uses thousands of tricks to show his kindness. Qian Yunxi thinks that the prince has bad intentions, so she fights with him. A chaotic cohabitation life begins.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Panda no Daibouken', 'Movie', 1, 'Completed', '1973-03-17', NULL, '6', 'Panda no Daibouken, a 1973 Toei Animation production aimed at children, follows the adventures of a young panda. Being born into royalty but having failed a rite of passage, the young Panda is exiled from his land. He goes on a journey of self discovery, meeting many friends along the way who help him discover his true potential.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Himitsukessha Taka no Tsume MAX', 'TV', 38, 'Completed', '2013-04-05', '2014-02-21', '6', 'Sequel to the previous season.', 214, 'https://cdn.myanimelist.net/images/anime/3/49315.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gensou Jotan Ellcia', 'OVA', 4, 'Completed', '1992-10-23', '1993-09-23', '6', 'The Sacred Book of the land of Eija has been rediscovered and with it the legends of a mysterious and all powerful ship. Now Princess Crystal of Megaronia has set forth on a quest to recover the ship and its ultimate weaponry. All that stands between her and total domination of the world is a small group of piratical misfits. Swords, sorcery and technology blend to form a mesmerizing tale of Good vs. Evil in Ellcia. (Source: ANN)', 436, 'https://cdn.myanimelist.net/images/anime/3/5763.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kinnikuman: Haresugata! Seigi Choujin', 'Movie', 1, 'Completed', '1985-12-21', NULL, '6', 'While performing in a movie at Toei Eigamura, Kinnikuman suddenly disappears. Somehow, he has been sent to Edo Period Japan. In Edo Japan, a villain called Shuten Douji (朱天童子) is threatening to destroy the Earth if he is not given Princess Mari. Always willing to impress a pretty girl, Kinnikuman immediately vows to destroy Shuten Doji. He disguises himself as Princess Mari and goes to meet Shuten Doji, but Shuten Doji and his Big Four (四天王, Shitennou) see through Kinnikuman''s disguise and beat him up. Aware of Kinnikuman''s situation, Terryman, Robin Mask, and the other Seigi Choujins travel to Edo Japan (via Kinkotsu-obaba''s powers).
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hatara Kids Mai Ham Gumi', 'TV', 50, 'Completed', '2007-10-07', '2008-10-05', '6', 'Hatara Kids Maihamu Gumi, literally "Working Kids, My Hamster Team", is a Japanese anime action series for young children about hamsters who hold down jobs from firefighting to cooking.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bobby ni Kubittake', 'Movie', 1, 'Completed', '1985-03-09', NULL, '6', 'The "Bobby" referred to in the title is actually 17-year-old Akihiko Nomura, an underachieving high school kid with a deep love for motorcycles. His grades are failing, and his father – traditional and strict (but who must have also at some point gave in and allowed him to have a motorcycle) – is trying everything he can think of to get the kid to apply for college. His mother is so silent, she might as well not even exist. Really, his support system lies entirely in his twinkle-toed little sister, who''s nosy but cheers him on in her own way.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gunma-chan', 'TV', 13, 'Completed', '2021-10-03', '2021-12-26', '6', 'An anime series based on the Gunma Prefecture mascot character, Gunma-chan.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Akai Shouzou: Char, Soshite Frontal e', 'Special', 1, 'Completed', '2010-08-13', NULL, '6', 'A recap of Gundam, Gundam Z, Gundam ZZ, and Char''s Counterattack as experienced by Char Aznable, as well as a precursor to Gundam Unicorn. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Black★★Rock Shooter: Dawn Fall', 'TV', 12, 'Completed', '2022-04-03', '2022-06-19', '6', 'In the year 2062, Earth finds itself fiercely battling Artemis—an AI which rebelled against humankind following a grand-scale workforce automation project failure years prior. In the hope of winning the war, a group of three highly skilled human warriors is assembled, known as the guardians of humanity.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Juusou Kikou Dancougar Nova', 'TV', 12, 'Completed', '2007-02-15', '2007-05-03', '6', 'In the 22nd century, there are no longer any world wide wars. Instead, small scale wars break out all over the Earth. Meanwhile, a large robot appears who protects the weak. It is called "Dancougar Nova". Some even call it God. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kimagure Robot', 'TV', 10, 'Completed', '2004-12-22', NULL, '6', 'A brilliant, slightly crazy, and extremely eccentric scientist toils away his days in his lab, creating robots to carry out different tasks. A robot to grant three wishes, a robot to help you write your diary, a robot that intentionally misbehaves in order to keep its master from becoming bored… the robots are each built for a very specific purpose, and can’t really do much of anything else. Luckily for mankind, however, these robots are much more useful than they appear to be at first glance… most of the time, anyway. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Maou Dante', 'TV', 13, 'Completed', '2002-08-31', '2002-11-23', '6', 'While sleeping one night, Ryo Utsugi had a nightmare of monsters attacking him. One day he learns a mysterious power to let him hear voices and have visions of girls getting killed, but one night he hears the same voice.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Suzy''s Zoo: Daisuki! Witzy', 'TV', 25, 'Completed', '2011-04-03', '2011-10-04', '6', 'The Japanese television network TBS announced that it will start airing the Suzy''s Zoo Daisuki! Witzy series of television anime shorts this April. The anime adapts the American greeting card line Suzy''s Zoo from the San Diego-based artist Suzy Spafford. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Strange+', 'TV', 12, 'Completed', '2014-01-10', '2014-03-28', '6', 'Kou comes to a slum neighborhood in search of his elder brother Takumi and finds him to have become the head of a private detective firm. Kou is drafted by Takumi to do errands and chores in the detective firm, and they come to meet various interesting people...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Bio Hunter', 'OVA', 1, 'Completed', '1995-12-08', NULL, '6', 'In the molecular biology department of a major university, Komada and Koshigaya do more than just teach. They are also investigating demon viruses, which cause people to morph into grotesque creatures with a craving for human flesh. While conducting their research, the pair encounter Sayaka Murakami, the granddaughter of a famous fortune teller. Feeling compelled to help her find her missing grandfather, Komada and Koshigaya learn that a group of thugs is pursuing Sayaka. To make matters more sinister, these perpetrators seem to have a connection to the demon viruses.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tian Yu', 'ONA', 13, 'Completed', '2017-04-26', '2017-10-11', '6', 'A millennium ago, the Five Monarchs guarded the land of the Xia Dynasty with magical artifacts. Later, the leader of the Dragon Clan, Zu Long, assisted humanity by establishing the Yun Chui Empire. The Empire faces the Tranquil Ocean where the Xi and Black Water Clans have defended it throughout a peaceful millennium. Now, the waves are surging from below and chaos will rise once again.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Mahou Sensou', 'TV', 12, 'Completed', '2014-01-10', '2014-03-28', '6', 'The world as we know it is actually just half the story, as Takeshi Nanase finds out abruptly one summer morning. On his way to kendo practice, Takeshi comes across an unconscious girl in a uniform he doesn''t recognize. Takeshi does the decent thing and saves her, and in return the girl wakes up and accidentally turns him into a magic-user.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tsurezure PoPiPa', 'ONA', 10, 'Completed', '2025-04-28', '2025-08-27', '6', 'Short anime about Poppin''Party''s daily life released for the band''s 10th anniversary.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tatakae!! Ramenman (Movie)', 'Movie', 1, 'Completed', '1988-07-09', NULL, '6', 'Theatrical film of the anime series Tatakae!! Ramenman, based on the manga chapter "Strike the Darkness".
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Peeping Life: The Perfect Extension', 'OVA', 10, 'Completed', '2011-09-23', NULL, '6', 'Another iteration in the Peeping Life franchise, The Perfect Extension features 10 new animated versions of improvised comedy sketches.', 184, 'https://cdn.myanimelist.net/images/anime/6/44191.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('PES: Peace Eco Smile', 'ONA', 7, 'Completed', '2012-05-25', '2012-08-17', '6', 'A collaborative effort between the Japanese automaker and Japanese anime company Studio 4°C, PES: Peace Eco Smile is a new web promotional anime series that centers around PES, a traveller from space, and NaSuBi, a mysterious life-form who is enamored by the charm of Earth. The car of choice for these strangers in a new world? The Prius, particularly the Prius Liftback and Prius C hatchback. These two hybrids seem to be as much a part of this series as the two main characters are. A Lexus LFA (likely the ride of the antagonist) and the Toyota Camry hybrid also have a role to play.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Coluboccoro', 'OVA', 1, 'Completed', '2007-01-01', NULL, '6', 'Long ago, a mysterious shrine maiden sealed nature spirits within forest trees to stop them from terrorizing the world. Now, her descendant, a cheerful young princess named Suzu, is prohibited from going outside. However, one day, after sneaking out into an area known as the "forbidden zone," Suzu discovers a strange seed which grows into a fun-loving nature spirit. With her new friend, Suzu is eager to explore the outside world that she has been kept from, despite not knowing the dangers of the forbidden zone—or why the seed was being kept there.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Game Tengoku: The Game Paradise!', 'OVA', 1, 'Completed', '1997-06-06', NULL, '6', 'Game Tengoku OVA which came with the limited edition version of the Sega Saturn video game.', 226, 'https://cdn.myanimelist.net/images/anime/12/29973.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kai Doh Maru', 'OVA', 1, 'Completed', '2001-12-19', NULL, '6', 'This story takes place during the Heian Period of Japan`s history, when evil spirits still resided in the forests, mountains and rivers. A girl, accompanied by her loved one, battles against these evil spirits, while she is disguised as man. This brave woman, aka "Kaidomaru", with a Chinese character "Flame" tatooed on her upper arm, was one of the "Four Devas". Kaidomaru fights for the honor of her lost love, Raikou Minamotono, who had sacrified his life in order to protect the capital Kyoto, from the evils deeds of a "princess" cursed by a malicious ogre. The princess, whom Kaidomaru used to play with as a child, has now become her ultimate enemy.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gokicha!!', 'ONA', 2, 'Completed', '2012-09-14', NULL, '6', 'Gokicha is a small cockroach girl who has moved from Kanto to Hokkaido. She hopes the people in Hokkaido, who are less used to her kind, will become her friends. Despite her best intentions, however, she always seems to find herself on the bottom of someone''s shoe or covered in insecticide. As Gokicha and her friend Chaba try to make it on the streets, it becomes apparent that the lives of cockroaches are full of peril.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Schick x One Piece', 'Special', 2, 'Completed', '2010-06-01', '2011-08-01', '6', 'Collaboration commercials between Schick and One Piece to promote their razors.', 1030, 'https://cdn.myanimelist.net/images/anime/1864/145777.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kidou Senshi Gundam-san: Gekijou Manner CM', 'Movie', 2, 'Completed', '2015-02-07', '2015-10-10', '6', 'Two manner movies created to promote theatrical screenings of the first two episodes of Mobile Suit Gundam: The Origin.', 974, 'https://cdn.myanimelist.net/images/anime/1961/126000.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('DEathMAtCH: Real ni Koishiteru', 'Special', 1, 'Completed', '2022-06-11', NULL, '6', 'Original anime short that aired during the Fuji TV''s Geinin Anime Kantoku (Entertainer Anime Director) variety show.', 643, 'https://cdn.myanimelist.net/images/anime/1761/124826.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('W''z', 'TV', 13, 'Completed', '2019-01-06', '2019-03-31', '6', 'Inspired by house music from a young age, Yukiya spends his free time as a DJ for a crowd of one and uploads his videos online. Like any young teenager, he yearns for something greater than his current life. He wants recognition and importance, but breaking out of his comfort zone means he runs the risk of getting hurt, so the cycle continues. That is, until the day he finally crosses the line of no return and live streams a performance that will change his world forever.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Cipher', 'OVA', 1, 'Completed', '1989-03-03', NULL, '5', 'Two brothers are in the spotlight: one a movie star making a football movie, the other a musician who occasionally goes to school (to cover for his sibling). What will destiny bring them?', 540, 'https://cdn.myanimelist.net/images/anime/11/33203.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Iron Virgin Jun', 'OVA', 1, 'Completed', '1992-07-21', NULL, '5', 'Jun Asuka is supposed to meet with a variety of suitors and become engaged to one of them on her 18th birthday. Instead, she breaks tradition and escapes into the night to avoid the schemes of her mother. With her mother resorting to increasingly extreme tactics to bend her daughter to her will, Jun must use all of her strength in order to protect her virginity.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Canary', 'OVA', 1, 'Completed', '2002-03-22', NULL, '5', 'Mika Katagiri wants her band to perform at the upcoming local festival. However, complications arise. Their keyboardist, Jun, refuses to play, and their stage has been cancelled. Refusing to give up, Mika and her band strive to find a way to play at the festival, using any means necessary.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Onyankopon', 'ONA', 12, 'Completed', '2017-10-06', '2017-12-22', '5', 'Onyankopon watched over people long ago, but one day an old woman accidentally hit Onyankopon in the head with a mallet while mashing yams. Since then, Onyankopon has been nervous about greeting people directly, and so sends subordinates to speak to them and solve their problems. He will use Afrobeat and dance to help Japanese high school girls with problems such as dieting, love, and cramming for exams.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zonmi-chan: Halloween☆Special Movie!', 'ONA', 1, 'Completed', '2015-10-26', NULL, '5', 'A Halloween special starring Zonmi-chan. A soldier is being chased by several Zonmi-chan zombies. He shoots at them but is ultimately caught.', 597, 'https://cdn.myanimelist.net/images/anime/12/79267.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chou Futsuu Toshi Kashiwa Densetsu R', 'TV', 10, 'Completed', '2020-07-06', '2020-09-28', '5', 'A gag anime set in Kashiwa, featuring high school girls and mysterious creatures.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Portrait', 'Movie', 1, 'Completed', '1983-01-01', NULL, '5', 'Furukawa Taku film.', 1004, 'https://cdn.myanimelist.net/images/anime/6/72725.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Majin Sentai Death Ranger: Ubawareta Pudding!', 'ONA', 1, 'Completed', '2014-09-18', NULL, '5', 'Stop-motion animation about pudding.', 860, 'https://cdn.myanimelist.net/images/anime/8/72096.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Timbre A to Z', 'ONA', 26, 'Completed', '2011-01-22', '2011-02-16', '5', 'A series of short films where Mirai Mizuki uploaded one abstract representation of a letter of the alphabet every day for 26 days.', 573, 'https://cdn.myanimelist.net/images/anime/3/70209.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Michitas to Fumidasu Ippo', 'Special', 1, 'Completed', '2024-01-05', NULL, '5', 'A commercial for Meiji''s Michitas beverages.', 327, 'https://cdn.myanimelist.net/images/anime/1843/142785.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gendai Goyaku', 'TV', 12, 'Completed', '2024-07-07', '2024-09-22', '5', 'The series focuses on teaching students famous quotations from historical figures from all over the world by presenting the quotations incorrectly at first as "mistranslations" in the "modern day," encouraging the students to learn the correct quotes in the process.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Enen no Shouboutai: San no Shou Part 2', 'TV', NULL, 'Upcoming', '2026-01-10', NULL, '5', 'Second part of Enen no Shouboutai: San no Shou.', 227, 'https://cdn.myanimelist.net/images/anime/1508/152472.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiao Hua Xian', 'TV', 52, 'Completed', '2014-02-14', '2014-05-10', '5', 'There is a mysterious power of the Holy Spirit hidden in the legendary continent of Labelle, and the way to get power is recorded in the book of flower, guard by numerous flower Fairy Kings,only the legendary magic ambassador is recognized to wake up the power, and use them to defeat evil. For this.The evil force,led by Jakarta,the Queen of Dark had start a war to the continent of Labelle.With the help of the Flower Goddess,Pupula and the tribe of gouring flower fairys, the fate of the continent of Labelle is linked with an Earth girl... Who is the legendary envoy XiaAnAn.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tian Shu Qi Tan', 'Movie', 1, 'Completed', '1983-01-01', NULL, '5', 'Yuangong, the deacon, opens the shrine and exposes the holy book to the human world. He also carves the contents of the book on the stone wall of white cloud cave in the mountains. He is then punished by the Jade Emperor to guard the book for life for breaking heaven''s law and betraying the holy secret to humankind. In order to pass this holy book to human beings, he must get by the antagonist fox.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Gan Gan Ganko-chan 2nd Season', 'TV', 8, 'Completed', '2018-02-04', '2018-03-25', '5', 'Second season of the Gan Gan Ganko-chan anime series.', 2, 'https://cdn.myanimelist.net/images/anime/1066/90380.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Genki Genki Non-tan: Obake Mura Meiro', 'OVA', 1, 'Completed', '2015-06-03', NULL, '5', 'Another edition of Genki Genki Non-tan, this one''s focus is "trying hard." Between trying to get along with your sibling, to trying to fall asleep for nap time, to trying to be brave when you think something is scary.', 695, 'https://cdn.myanimelist.net/images/anime/1456/90421.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Go-chan.: Moko to Koori no Ue no Yakusoku', 'Movie', 1, 'Completed', '2018-03-18', NULL, '5', '', 983, 'https://cdn.myanimelist.net/images/anime/1037/90455.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tenka Touitsu Koi no Ran: Shutsujin! Saika 4-nin Shuu', 'ONA', 4, 'Completed', '2018-05-28', '2018-06-26', '5', '15th Century Japan is ravaged by constant wars, as the lords of the realm seek to rule the land. Having lost your father in battle, you are working in the restaurant he left your mother and little brother...when an evil magistrate sends your little brother away...to become a poison taster! To save his life, you disguise yourself as a boy and go to the castle in his place...but what awaits you there is so much more!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tanuki to Kitsune Specials', 'Special', 2, 'Completed', '2018-05-15', NULL, '5', 'Two specials of Tanuki to Kitsune released only on the DVD of the main show. The disc will bundle with the manga''s 4th tankoubon. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kekkero Ke', 'TV', 13, 'Completed', '2018-04-05', '2018-06-28', '5', 'The anime follows the frogs Kekkero and Ke who try to find their 998 other siblings. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Chara to Otamajakushi Shima', 'TV', 40, 'Completed', '2018-04-02', '2019-01-28', '5', 'The anime is set on the titular Musical Note Island, where the god of music is said to reside. The island is home to "instrument animals," who are born from music energy, and have parts of their body composed of a musical instrument. One day, a witch arrives at the island. The warrior girl Cara must go on a journey to defeat the witch and win back the peace on the island.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Usagi no Matthew', 'TV', 52, 'Completed', '2018-04-05', '2019-04-04', '5', 'The story centers on Matthew, a daydreaming worrywart of a rabbit. Matthew also has two friends: Keron, a pessimistic frog who is fond of good-luck charms; and Ham, a hamster of few words and who moves through life at his own pace. The story follows the three animals'' everyday lives within a mysterious forest. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kono Hoshi no Ue ni', 'Movie', 1, 'Completed', '1998-01-28', NULL, '5', '', 35, 'https://cdn.myanimelist.net/images/anime/1892/91046.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Picchipichi Shizuku-chan', 'TV', 52, 'Completed', '2012-10-05', '2013-09-27', '5', 'Third season of Pururun! Shizuku-chan.', 90, 'https://cdn.myanimelist.net/images/anime/10/47085.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pyun Pyun Maru', 'TV', 26, 'Completed', '1967-07-03', '1969-03-30', '5', 'The Ninja Pyun Pyun-Maru and his brother Chibi-Maru are working at an office that accepts anything. They solve unexpected happenings caused by other Ninjas. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Banshou Shaonian', 'ONA', NULL, 'Upcoming', NULL, NULL, '5', 'A thousand years ago, the pieces of a meteorite with massive energy fell on multiple places in the world. They were called "fragments of God". Humans started wars for them. In a certain city, the lord sacrificed himself in resistance against the evil force to protect the residents. When the war came to an end, mechanics rebuilt the city and founded St. Beroro Academy, a dream school for mechanics to pursue their dreams...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kick & Slide', 'TV', 12, 'Completed', '2021-07-07', '2021-09-22', '5', 'The third generation of J SOUL BROTHERS from EXILE TRIBE is reimagined as 7 unique and diverse characters in "KICK &amp; SLIDE". This is a slapstick story where the characters solve difficult cases!? and rare cases!? that occur in the colorful and pop vibrant city "Nakame Town" with dance and music.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Heisei Inu Monogatari Bow Movie', 'Movie', 1, 'Completed', '1994-08-20', NULL, '5', 'The story is set in primitive times,in a village which is home to Bow, Sayaka, and other funny characters. The village is suffering from a shortage of food. To resolve this critical situation, Inugami’s grandmother makes a prophesy: “The chosen one will save the village with a great animal.”
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Sakura no Ondo', 'Movie', 1, 'Completed', '2011-10-29', NULL, '5', 'Hiirigo, who grew up in a country town, spent his life feeling frustrated with his hometown where nothing is happening.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Omoikkiri Kagaku Adventure Sou Nanda!', 'TV', 26, 'Completed', '2003-10-05', '2004-03-28', '5', 'After a soccer game one day, six kids are playing a cute RPG-looking video game at their homes. One of them scored the winning goal, one was the goal keeper who barely missed the ball, and the others were two groups of two who were rooting for their respective sides. Suddenly, when they defeat a boss, a strange thing pops up in front of them, and they''re sucked into the game world! Tomoru (scorer), Mio, and Dai end up together with Professor Galileo, who tells them that he''s the one that created this game that they`ve appeared in, called Eureka, but he inadvertently got sucked into it as well. In order to get back to their world, they need to clear missions that pop up in certain areas of the world. So when a mission appears, Tomoru and the gang make the professor take them along.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Otoppe Movie: Papa, Don''t Cry', 'Movie', 1, 'Completed', '2021-10-15', NULL, '5', '', 746, 'https://cdn.myanimelist.net/images/anime/1242/118540.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('MAFF x Chobitto Zukan', 'ONA', 3, 'Completed', '2017-02-28', NULL, '5', 'A series of collaboration episodes between Chobitto Zukan and JAS.', 457, 'https://cdn.myanimelist.net/images/anime/8/85605.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Jimoto ga Japan', 'TV', 50, 'Completed', '2019-04-08', '2020-03-23', '5', 'There''s a new tough guy transfer student in Tokyo. His name is Tokio and he''s raring to see how scrappy the locals are. But when he comes face-to-face with a Japan-obsessed red-haired kid that won''t leave him alone until he tells him exactly what prefecture he''s from, his life takes a turn for the crazy! This kid isn''t just Japan obsessed, he''s developed a martial art based on all the different prefectures in the country! 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Little Charo 4: Eigo de Aruku New York', 'TV', 36, 'Completed', '2013-04-03', '2013-12-18', '5', '', 831, 'https://cdn.myanimelist.net/images/anime/1899/93780.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Licca-chan to Mahou no Kuni', 'ONA', 7, 'Completed', '2009-10-09', '2009-11-20', '5', 'Takara Tomy''s popular doll "Licca-chan" got it''s own animation "Licca-chan and the Magical World" produced by DLE Inc.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ring Ring Boy', 'Movie', 1, 'Completed', '1963-01-01', NULL, '5', '', 493, 'https://cdn.myanimelist.net/images/anime/1124/138765.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yukai na Animal Bus 2nd Season', 'TV', 12, 'Completed', '2017-07-02', '2017-09-17', '5', 'Second season of Yukai na Animal Bus.', 990, 'https://cdn.myanimelist.net/images/anime/5/85231.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Iriya no Sora, UFO no Natsu', 'OVA', 6, 'Completed', '2005-02-25', '2005-06-29', '7', 'Asaba Naoyuki is an ordinary high school student. As a member of his school''s press club, he''s just spent the summer camping outside the local military base, in hopes of seeing the UFOs that are secretly kept there, according to local legend. Returning to school, he meets a strange girl, Iriya Kana, and gradually comes to realize that she is more than merely strange - and that a dark secret lies beneath the world that he knows.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Zettai Muteki Raijin-Oh', 'TV', 51, 'Completed', '1991-04-03', '1992-03-25', '7', 'Suddenly, an evil empire, Jaaku, raids the Earth. But the light appears from the Earth, and fights against Jaaku. It is Raijin Oh operated by Eldran. Eldran has protected the earth since the ancient ages. But he was injured during the fight, and Raijin-Oh falls to the ground. On the other hand, Jaaku scatters their weapons, Aku-Darmer, all over the world.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Agatha Christie no Meitantei Poirot to Marple', 'TV', 39, 'Completed', '2004-07-04', '2005-05-15', '7', 'Young Mabel West is the daughter of mystery writer Raymond West, who wants her to lead a normal life. Rebelling against this, Mabel wants to be a great detective, and sets out for London to become assistant to none other than Hercule Poirot, the great Belgian detective who resides there. She finally wins the reluctant approval of her father, and embarks on an exciting life of mystery and suspense—his only demand being that she occasionally spend some time with her great-aunt, Jane Marple, in the small village of St. Mary Mead.', 621, 'https://cdn.myanimelist.net/images/anime/6/3149.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Tokusou Senshatai Dominion', 'OVA', 6, 'Completed', '1993-10-20', '1994-10-21', '7', 'In the follow up to Shirow''s classic anime, Al, Leona and their trusty steed, Bonaparte, continue to fight crime in New Port City, alongside the rest of the Tank Police. But a new threat appears in the form of a series of terrorist attacks, using the latest weapons technology. The Tank Police are out-numbered and out-gunned, but Al and Leona set out to discover who or what is behind these attacks. With massive explosions and high-speed chases, Leona often causes more damage than the criminals she pursues.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yingxiong Zai Lin', 'ONA', 12, 'Completed', '2020-10-18', '2020-12-27', '7', 'Zero was mankind’s first real superhero. Under his watch, countless other superheros appeared and followed in his footsteps. However, after 5 years of war, Zero disappeared without a trace.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wo Neng Wuxian Dunwu', 'ONA', 52, 'Completed', '2024-10-26', '2025-04-12', '7', 'With determination and courage, Xiao Yun, a mortal boy, joins the battle for the qualification of the emperor with the help of the epiphany system. But why did the emperor know him a million years ago? Why did he leave notes in the future? What is the true origin of the epiphany system? All parallel worlds will face a huge crisis, and the only savior is the boy from Earth summoned by the gods!
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pop Pop City', 'ONA', 1, 'Completed', '2024-03-22', NULL, '7', 'The night of a family birthday party. The mother is tired from work and wants to drink a beer as soon as possible. The father is fidgety and keeps an eye on the clock. A little girl is excited about the sumptuous meal and runs around the house. The intercom rings. There, a "new family member" is standing there...
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yishi Zhi Zun', 'ONA', 16, 'Completed', '2024-02-18', '2024-05-25', '7', 'Meng Qi, a time-traveler who wants to be a dashing swordsman in white, fails in endless extreme missions in the ''reincarnation space''. The wind suddenly changed and he became the world-famous "Thunder Sword Mad Monk". However, all of this turned out to be the treacherous plan of the ancient power. Let’s look at the invincible and funny little monk who is happy in the world and proud of the three worlds.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Hypnosis Mic: Division Rap Battle - Rhyme Anima +', 'TV', 13, 'Completed', '2023-10-07', '2023-12-30', '7', 'A recent uptick in civilian riots and crimes has been observed across the country following the conclusion of the second Division Rap Battle. To make matters more chaotic, the individuals perpetrating the crimes have no recollection of the incidents nor any reason to be committing them in the first place. Suspecting these events to be linked to the effect of the Hypnosis Microphones, the governing Party of Words begins investigating the whereabouts of the mastermind behind them.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Xiao Lu He Xiao Lan 2nd Season', 'ONA', 12, 'Completed', '2023-07-12', '2023-09-20', '7', 'The second season of Xiao Lu He Xiao Lan.', 130, 'https://cdn.myanimelist.net/images/anime/1356/129999.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Paradox Live the Animation', 'TV', 12, 'Completed', '2023-10-03', '2023-12-26', '7', 'In a future where hip-hop reigns supreme, skilled rappers put on shows known as Phantom Lives. There they turn their powerful emotions into captivating illusions for their audiences through the usage of "Phantometal"—a material that reacts to the rapper''s DNA to create the fantastic imagery. However, usage of Phantometal causes rappers to relive past traumas and painful memories in so-called Trap Reactions. Depending on the strength of the rapper''s emotions, these reactions can be debilitating and even affect their psyche.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Rinne no Lagrange', 'TV', 12, 'Completed', '2012-01-08', '2012-03-25', '7', 'Madoka Kyouno is an energetic girl who is full of passion. As the proud, and only, member of the Kamogawa Girls'' High School Jersey Club, she goes around helping people in need.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Futsuu no Joshikousei ga "Locodol" Yattemita.', 'TV', 12, 'Completed', '2014-07-04', '2014-09-19', '7', 'Nanako Usami, a high school girl living in the small rural city of Nagarekawa, is asked by her uncle, who works at city hall, to take part in a stage show at the local zoo to help promote the town. There, she meets her senpai from high school, Yukari Kohinata, who is also scheduled to perform. With Yukari''s advice, Nanako successfully completes the show. This experience leads them to form the "Nagarekawa Girls," a local idol duo created to promote Nagarekawa.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('A-Channel: Nabe wo Tabeyou', 'Special', 1, 'Completed', '2017-09-27', NULL, '7', 'A new episode included with the complete Blu-ray box collection of A-Channel.', 896, 'https://cdn.myanimelist.net/images/anime/9/84989.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Harmony', 'Movie', 1, 'Completed', '2015-11-13', NULL, '7', 'In 2019, following an uprising in the USA and a subsequent global nuclear war, humanity was decimated by a catastrophe called "The Maelström." A half-century after this cataclysmic event—to preserve humankind—the World Health Organization (WHO) has progressively assimilated worldwide political power and completely redefined society: people are now considered public resources and are guaranteed a happier life. The heightened development of medicine, nanomachine technology, and augmented reality promote this greater devotion to human health.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Yinhun x KFC', 'Special', 1, 'Completed', '2018-05-09', NULL, '7', 'Chinese streaming platform Weibo is hosting exclusive Gintama footage. The ad is in Japanese with Chinese subtitles showing the characters enjoying KFC''s Chinese brand.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Guilty Crown: Lost Christmas - An Episode of Port Town', 'OVA', 1, 'Completed', '2012-07-26', NULL, '7', 'In 2029, Scrooge escapes from a research facility where he had been confined as an experimental subject. His body was remodeled by genetic manipulations and he uses his psychic power to kill the chasers. One day, he meets another experimental subject called Carol. When three psychic chasers hunt down the two, Carol asks Scrooge to use his right arm to extract a weapon from her body.', 704, 'https://cdn.myanimelist.net/images/anime/7/80010.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Anima Yell!', 'TV', 12, 'Completed', '2018-10-07', '2018-12-23', '7', 'Kohane Hatoya''s most lovable trait is also her greatest flaw. She loves to help others no matter how far she has to go in order to get the job done. Her biggest inspiration to do so comes to light when she sees what cheerleading looks like for the first time in middle school. Now a highschooler but as enthusiastic as ever, Kohane wants nothing more than to start her very own cheerleading squad. She is encouraged by her best friend, Uki Sawatari, who often has to help her get out of trouble.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Love Live! School Idol Project OVA', 'OVA', 1, 'Completed', '2013-11-27', NULL, '7', 'Bundled with the sixth single of the anime''s μ''s idol group.', 974, 'https://cdn.myanimelist.net/images/anime/1565/104629.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Nekomonogatari: Kuro Recap', 'Special', 1, 'Completed', '2013-03-06', NULL, '7', 'A short recap included in the Blu-ray volume of Nekomonogatari: Kuro.', 791, 'https://cdn.myanimelist.net/images/anime/1145/98159.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Koisuru Asteroid', 'TV', 12, 'Completed', '2020-01-03', '2020-03-27', '7', 'In a fateful childhood encounter, Mira Kinohata met a stargazing dreamer named Ao Manaka. Though their time together was short, Ao showed Mira the wonders of astronomy, from orbiting planets to distant stars. Before they parted, Mira learned that a star with her name exists, but there are none with Ao''s. And so, she forged a promise: one day, she would discover a new asteroid and name it after Ao.
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Ikebukuro West Gate Park', 'TV', 12, 'Completed', '2020-10-06', '2020-12-22', '7', 'Ikebukuro is home to many different businesses and gangs. This includes Makoto Majima: the infamous "troubleshooter" who mediates between warring factions. Makoto knows all of the ins and outs of the bustling Tokyo district and strives to maintain peace alongside the G-Boys, who assist Makoto in his troubleshooting endeavors. Led by the charismatic and ruthless Takashi Andou, the G-Boys is the most influential gang in all of Ikebukuro. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Wander Burabura Bakkamu', 'ONA', 1, 'Completed', '2023-03-31', NULL, '6', '', 260, 'https://cdn.myanimelist.net/images/anime/1732/135876.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shuumatsu no Walküre II Mini Anime', 'ONA', 18, 'Completed', '2023-04-13', '2023-11-23', '6', 'Short episodes with super-deformed characters posted on the official Twitter account and on Warner Bros. Japan.', 39, 'https://cdn.myanimelist.net/images/anime/1215/135276.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Protector', 'ONA', 1, 'Completed', '2022-11-18', NULL, '6', 'A short animation depicting Kiriko''s past, exclusively released in Japan.', 270, 'https://cdn.myanimelist.net/images/anime/1781/131678.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Shinmai Renkinjutsushi no Tenpo Keiei Mini Anime', 'ONA', 13, 'Completed', '2022-09-30', '2022-12-23', '6', 'Mini anime episodes posted on the official YouTube channel.', 255, 'https://cdn.myanimelist.net/images/anime/1843/128798.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Megaton-kyuu Musashi Pilot', 'ONA', 1, 'Completed', '2016-07-27', NULL, '6', 'Pilot episode of Megaton-kyuu Musashi released on YouTube in 2016.', 621, 'https://cdn.myanimelist.net/images/anime/1085/122368.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Poputepipikku Specials', 'Special', 3, 'Completed', '2018-02-28', '2018-03-28', '6', 'Specials included in the Blu-ray and DVD releases of Poputepipikku.', 461, 'https://cdn.myanimelist.net/images/anime/1444/92651.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Pokemon: Aki no Special', 'Special', 1, 'Completed', '1997-10-07', NULL, '6', 'A recap special that aired after episode 28 of the Pokemon anime.', 621, 'https://cdn.myanimelist.net/images/anime/1287/123875.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Youkai Ningen Bem: Part II', 'Special', 2, 'Completed', '1992-10-21', NULL, '6', 'For 1982 a 26-episode TV series sequel to Youkai Ningen Bem was planned. Because the original producers disbanded, the animation was done by Topcraft. 2 episodes were created and the project shut down without airing on television. The episodes were released to the public on a LD-Box Set a decade later. 2,000 units were printed and all were sold out.', 1045, 'https://cdn.myanimelist.net/images/anime/1173/94675.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Power Battle Watch Car', 'TV', 13, 'Completed', '2016-04-07', '2016-07-07', '6', 'The series is set in the near future, when an automobile company named JHC Motors is depicted to have created the Watch Cars, which are miniature sentient robotic cars that are supposed to have become good companions to children and adults alike. Watch Cars are depicted to have become a global trend. There is a Battle League where Watch Cars and their trainers battle. Jino, one of the young Watch Car Masters, goes to the Watch Car Battle League with his Watch Car Blue-will, but The Rangers of Darkness an evil force to takeover al the watch cars in The city, Jino and his friends must stop them. 
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Kumichou Musume to Sewagakari Picture Drama', 'ONA', 7, 'Completed', '2022-01-28', '2022-07-22', '6', 'Introductory Picture Drama episodes released online prior to the TV anime debut.', 39, 'https://cdn.myanimelist.net/images/anime/1169/120746.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Queen''s Blade: Rurou no Senshi Specials', 'Special', 6, 'Completed', '2009-06-25', '2009-11-25', '6', 'Special episodes added to DVDs and Blu-rays.', 85, 'https://cdn.myanimelist.net/images/anime/13/22751.jpg');
INSERT INTO anime (title, type, episodes, status, airing_start, airing_end, rating, synopsis, StudioID, image_url) VALUES ('Dash! Yonkurou: Horizon Gundan vs. Dash Gundan', 'Special', 1, 'Completed', '1990-07-27', NULL, '6', 'A TV Special of Dash! Yonkurou that aired 4 months after the TV anime ended.
